import { useState, FormEvent } from 'react';
import { LogIn, UserPlus, CheckCircle2, AlertCircle } from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import { OrganizationRole, STAFF_ROLES, ROLE_DESCRIPTIONS } from '@/lib/auth/roles';;

import { Modal, inputCls, btnPrimary } from './ui';
import { InstallAppButton } from '@/components/pwa/InstallAppButton';

export default function AuthModal({ open, onClose }: { open: boolean; onClose: () => void }) {
  const { signIn, signUp, signInAsDemo } = useAuth();
  const [mode, setMode] = useState<'signin' | 'signup'>('signin');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [role, setRole] = useState<OrganizationRole>('Stylist');
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const handleDemoSignIn = async () => {
    setError(null);
    setBusy(true);
    const { error } = await signInAsDemo();
    setBusy(false);
    if (error) {
      setError(error);
    } else {
      setSuccess('Welcome to Demo Mode!');
      setTimeout(() => {
        handleClose();
        window.location.reload();
      }, 900);
    }
  };

  const reset = () => {
    setError(null);
    setSuccess(null);
    setBusy(false);
  };

  const handleClose = () => {
    reset();
    onClose();
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError(null);
    setBusy(true);

    try {
      if (mode === 'signin') {
        let { error } = await signIn(email.trim().toLowerCase(), password);
        
        // Auto-provision user account if credentials do not exist on this environment yet
        if (error && (error.toLowerCase().includes('invalid login credentials') || error.toLowerCase().includes('user not found'))) {
          const defaultName = email.split('@')[0].replace(/[^a-zA-Z0-9]/g, ' ');
          const formattedName = defaultName.charAt(0).toUpperCase() + defaultName.slice(1);
          const signUpRes = await signUp(email.trim().toLowerCase(), password, formattedName, 'Stylist');
          error = signUpRes.error;
        }

        if (error) {
          setBusy(false);
          setError(error);
        } else {
          setSuccess('Opening VowOS WorkspaceΓÇª');
          setTimeout(() => {
            handleClose();
            window.location.reload();
          }, 900);
        }
      } else {
        if (!name.trim()) {
          setBusy(false);
          setError('Please enter your name.');
          return;
        }
        const { error } = await signUp(email, password, name.trim(), role);
        setBusy(false);
        if (error) {
          setError(error);
        } else {
          setSuccess('Account created ΓÇö you are signed in!');
          setTimeout(() => {
            handleClose();
            window.location.reload();
          }, 1100);
        }
      }
    } catch (err: any) {
      console.error('Sign in error:', err);
      setBusy(false);
      setError(err?.message || 'An error occurred during authentication.');
    }
  };

  return (
    <Modal open={open} onClose={handleClose} title={mode === 'signin' ? 'Staff Sign In' : 'Create Staff Account'}>
      {success ? (
        <div className="flex flex-col items-center py-8">
          <CheckCircle2 className="h-12 w-12 text-status-success" />
          <p className="mt-3 font-medium text-stone-800">{success}</p>
        </div>
      ) : (
        <>
          {/* Mode toggle */}
          <div className="mb-5 grid grid-cols-2 gap-1 rounded-xl bg-stone-100 p-1">
            <button
              type="button"
              onClick={() => {
                setMode('signin');
                reset();
              }}
              className={`flex items-center justify-center gap-1.5 rounded-lg py-2 text-sm font-medium transition-colors ${
                mode === 'signin' ? 'bg-white text-stone-900 shadow-sm' : 'text-stone-500 hover:text-stone-700'
              }`}
            >
              <LogIn className="h-4 w-4" /> Sign In
            </button>
            <button
              type="button"
              onClick={() => {
                setMode('signup');
                reset();
              }}
              className={`flex items-center justify-center gap-1.5 rounded-lg py-2 text-sm font-medium transition-colors ${
                mode === 'signup' ? 'bg-white text-stone-900 shadow-sm' : 'text-stone-500 hover:text-stone-700'
              }`}
            >
              <UserPlus className="h-4 w-4" /> Sign Up
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            {mode === 'signup' && (
              <>
                <div>
                  <label className="mb-1 block text-xs font-medium text-stone-600">Full name *</label>
                  <input
                    required
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className={inputCls}
                    placeholder="Dana Roberts"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-xs font-medium text-stone-600">Role *</label>
                  <div className="grid grid-cols-2 gap-2">
                    {STAFF_ROLES.map((r) => (
                      <button
                        key={r}
                        type="button"
                        onClick={() => setRole(r)}
                        className={`rounded-lg border px-3 py-2 text-sm font-medium transition-colors ${
                          role === r
                            ? 'border-brand-primary bg-brand-soft text-brand-primary ring-1 ring-rose-300'
                            : 'border-stone-300 bg-white text-stone-600 hover:bg-stone-50'
                        }`}
                      >
                        {r}
                      </button>
                    ))}
                  </div>
                  <p className="mt-1.5 text-[11px] leading-relaxed text-stone-400">{ROLE_DESCRIPTIONS[role]}</p>
                </div>
              </>
            )}

            <div>
              <label className="mb-1 block text-xs font-medium text-stone-600">Email *</label>
              <input
                required
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className={inputCls}
                placeholder="you@robertsenterprises.com"
              />
            </div>
            <div>
              <label className="mb-1 block text-xs font-medium text-stone-600">Password *</label>
              <input
                required
                type="password"
                minLength={6}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className={inputCls}
                placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
              />
              {mode === 'signup' && <p className="mt-1 text-[11px] text-stone-400">At least 6 characters.</p>}
            </div>

            {error && (
              <div className="flex items-start gap-2 rounded-lg bg-brand-soft px-3 py-2.5 text-sm text-brand-primary-hover ring-1 ring-inset ring-focus-ring">
                <AlertCircle className="mt-0.5 h-4 w-4 flex-shrink-0" />
                {error}
              </div>
            )}

            <button type="submit" disabled={busy} className={`${btnPrimary} w-full justify-center disabled:opacity-60`}>
              {busy ? 'Please wait...' : mode === 'signin' ? 'Sign In' : 'Create Account'}
            </button>

            {mode === 'signin' && (
              <div className="mt-8 border-t border-stone-200 pt-6">
                <div className="mt-4">
                  <InstallAppButton fullWidth variant="outline" className="border-stone-300 text-stone-700 hover:bg-stone-50" />
                </div>
              </div>
            )}

            <p className="text-center text-[11px] text-stone-400">
              Staff access is managed by your organization. Your role controls what you can edit.
            </p>
          </form>
        </>
      )}
    </Modal>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { AlertTriangle, CalendarPlus, CreditCard, Loader2, MailCheck, Pencil } from 'lucide-react';
import {
  Appointment,
  LocationId,
  locationById,
  teamMembers,
  APPOINTMENT_TYPES,
  TIME_SLOTS,
  LOOKING_FOR_OPTIONS,
  BUDGET_RANGES,
  BOOKING_FEE_CENTS,
  formatCents,
} from '@/data/vowosData';
import { useVowosData, NewAppointmentInput } from '@/contexts/VowosDataContext';
import { toast } from '@vowos/design-system';
import { Modal, inputCls, btnPrimary, btnSecondary } from './ui';
import { LocationSelect } from './LocationSelect';
import {
  sendAndLogMessage,
  appointmentConfirmationTemplates,
  appointmentRescheduleTemplates,
  isEmail,
  isPhone,
} from '@/lib/messaging';
import { fetchBookingFeeCents } from '@/lib/settings';


const OTHER = '__other__';

const labelCls = 'mb-1 block text-xs font-medium uppercase tracking-wider text-stone-500';
const FEE_LABEL = formatCents(BOOKING_FEE_CENTS);


export default function BookAppointmentModal({
  open,
  onClose,
  appointment,
  defaults,
}: {
  open: boolean;
  onClose: () => void;
  /** When provided, the modal becomes an edit/reschedule form for this appointment. */
  appointment?: Appointment | null;
  /** Prefills for new bookings (e.g. clicking a calendar cell books that day/stylist). */
  defaults?: { date?: string; time?: string; stylist?: string; request?: any } | null;
}) {

  const {
    brides,
    leads,
    allBrides,
    allAppointments,
    activeLocation,
    addAppointment,
    updateAppointment,
  } = useVowosData();
  const isEdit = Boolean(appointment);

  const [brideChoice, setBrideChoice] = useState('');
  const [customName, setCustomName] = useState('');
  const [type, setType] = useState<Appointment['type']>('Bridal Consultation');
  const [location, setLocation] = useState<LocationId>('ido-br');
  const [date, setDate] = useState('');
  const [time, setTime] = useState('');
  const [stylist, setStylist] = useState(teamMembers[0]);
  const [lookingFor, setLookingFor] = useState('');
  const [budgetCents, setBudgetCents] = useState(0);
  const [feeCollected, setFeeCollected] = useState(true);
  const [notify, setNotify] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [dynamicBookingFee, setDynamicBookingFee] = useState(BOOKING_FEE_CENTS);
  const [consentChecked, setConsentChecked] = useState(false);

  useEffect(() => {
    fetchBookingFeeCents(location).then(fee => {
      setDynamicBookingFee(fee);
    }).catch(console.error);
  }, [location]);


  // Pre-fill the form when opening in edit mode; reset for booking mode
  useEffect(() => {
    if (!open) return;
    if (appointment) {
      setBrideChoice('');
      setCustomName('');
      setType(appointment.type);
      setLocation(appointment.location);
      setDate(appointment.date);
      // Existing times should always be one of our slots, but keep whatever it is
      setTime(appointment.time);
      setStylist(appointment.stylist);
      setLookingFor(appointment.lookingFor);
      setBudgetCents(appointment.budgetCents);
      setFeeCollected(appointment.feePaid);
    } else {
      const hasRequestCustomer = !!defaults?.request?.customer?.name;
      setBrideChoice(hasRequestCustomer ? OTHER : '');
      setCustomName(defaults?.request?.customer?.name || '');
      setType((defaults?.request?.type as Appointment['type']) || 'Bridal Consultation');
      // Book into the store the staffer is currently viewing
      setLocation(activeLocation === 'all' ? 'ido-br' : activeLocation);
      // Calendar cells pass prefills (book this day / this stylist / this slot)
      setDate(defaults?.date ?? '');
      setTime(defaults?.time ?? '');
      setStylist(defaults?.stylist ?? teamMembers[0]);
      setLookingFor(defaults?.request?.looking_for || '');
      setBudgetCents(0);
      setFeeCollected(true);
    }
    setNotify(true);
    setError('');

  }, [open, appointment, activeLocation, defaults]);



  const [isSuggesting, setIsSuggesting] = useState(false);

  const handleAISuggest = () => {
    setIsSuggesting(true);
    setTimeout(() => {
      // AI Logic: Find an available slot over the next 7 days, avoiding existing appointments
      let foundDate = '';
      let foundTime = '';
      let foundStylist = '';
      
      const today = new Date();
      for (let i = 0; i < 7; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        const dStr = d.toISOString().slice(0, 10);
        
        // Skip Sundays (0) if you want, but this is generic
        for (const t of ['10:00 AM', '11:30 AM', '1:00 PM', '2:30 PM', '4:00 PM']) {
          for (const s of teamMembers) {
            const conflict = allAppointments.some(a => 
              a.date === dStr && a.time === t && a.stylist === s && a.status !== 'Cancelled'
            );
            if (!conflict) {
              foundDate = dStr;
              foundTime = t;
              foundStylist = s;
              break;
            }
          }
          if (foundDate) break;
        }
        if (foundDate) break;
      }
      
      if (foundDate) {
        setDate(foundDate);
        setTime(foundTime);
        setStylist(foundStylist);
        toast({ 
          title: 'Γ£¿ AI Smart Suggestion Applied', 
          description: `Found an open slot with ${foundStylist} on ${foundDate} at ${foundTime}.` 
        });
      } else {
        toast({ 
          title: 'No availability', 
          description: 'No openings found in the next 7 days.',
          variant: 'destructive'
        });
      }
      setIsSuggesting(false);
    }, 800);
  };

  const customerName = isEdit
    ? appointment!.customer
    : brideChoice === OTHER
      ? customName.trim()
      : brideChoice;

  // A stylist can only be in one place at a time, so check across every store.
  const conflict = useMemo(() => {
    if (!date || !time || !stylist) return null;
    return (
      allAppointments.find(
        (a) =>
          a.stylist === stylist &&
          a.date === date &&
          a.time === time &&
          a.status !== 'Completed' &&
          a.status !== 'Cancelled' &&
          a.id !== appointment?.id, // an appointment never conflicts with itself

      ) || null
    );
  }, [allAppointments, date, time, stylist, appointment]);

  const handleClose = () => {
    setError('');
    onClose();
  };

  // Bride record (for email/phone) matching whoever the appointment is for
  const contact = useMemo(
    () => allBrides.find((b) => b.name === customerName) ?? null,
    [allBrides, customerName],
  );
  const canNotify = !!contact && (isEmail(contact.email) || isPhone(contact.phone));

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!customerName) {
      setError(brideChoice === OTHER ? "Please type the lead's name." : 'Please choose a bride.');
      return;
    }
    if (!isEdit && !lookingFor) {
      setError("Please pick what she's looking for.");
      return;
    }
    if (!isEdit && !budgetCents) {
      setError('Please pick her budget range.');
      return;
    }
    if (!date) {
      setError('Please pick a date.');
      return;
    }
    if (!time) {
      setError('Please pick a time.');
      return;
    }
    setError('');
    setSaving(true);
    let ok: boolean;
    if (isEdit) {
      ok = await updateAppointment(appointment!.id, { type, date, time, stylist, location });
    } else {
      const input: NewAppointmentInput = {
        customer: customerName,
        type,
        date,
        time,
        stylist,
        location,
        lookingFor,
        budgetCents,
        feePaid: feeCollected,
      };
      ok = await addAppointment(input);
    }

    // Email/text confirmation (new bookings) or reschedule notice (edits)
    const sendResults: string[] = [];
    if (ok && notify && canNotify && contact) {
      const apptForMsg: Appointment = {
        id: appointment?.id ?? 'new',
        customer: customerName,
        type,
        date,
        time,
        stylist,
        status: 'Confirmed',
        location,
        lookingFor,
        budgetCents,
        feePaid: feeCollected,
      };

      const tpl = isEdit
        ? appointmentRescheduleTemplates(apptForMsg)
        : appointmentConfirmationTemplates(apptForMsg);
      if (isEmail(contact.email)) {
        const r = await sendAndLogMessage({
          channel: 'email',
          to: contact.email,
          subject: tpl.emailSubject,
          body: tpl.emailText,
          html: tpl.emailHtml,
          customer: customerName,
          kind: isEdit ? 'reschedule' : 'confirmation',
        });
        sendResults.push(r.ok ? 'email sent' : 'email failed');
      }
      if (isPhone(contact.phone)) {
        const r = await sendAndLogMessage({
          channel: 'sms',
          to: contact.phone,
          body: tpl.sms,
          customer: customerName,
          kind: isEdit ? 'reschedule' : 'confirmation',
        });
        sendResults.push(r.ok ? 'text sent' : 'text failed');
      }
    }

    setSaving(false);
    if (ok) {
      toast({
        title: isEdit ? 'Appointment rescheduled ΓÇö calendar updated' : 'Appointment booked',
        description: `${customerName} ┬╖ ${type} with ${stylist} at ${time} ΓÇö ${locationById(location).short}${
          sendResults.length > 0 ? ` ┬╖ ${sendResults.join(' ┬╖ ')}` : ''
        }.`,
      });
      handleClose();
    }
  };


  return (
    <Modal
      open={open}
      onClose={handleClose}
      title={isEdit ? 'Edit Appointment' : 'Book Appointment'}
    >
      <form onSubmit={handleSubmit} className="space-y-4">
        {isEdit ? (
          <div>
            <span className={labelCls}>Bride</span>
            <p className="rounded-lg border border-stone-200 bg-stone-50 px-3 py-2 text-sm text-stone-700">
              {appointment!.customer}
            </p>
          </div>
        ) : (
          <div>
            <label htmlFor="ba-bride" className={labelCls}>
              Bride
            </label>
            <select
              id="ba-bride"
              value={brideChoice}
              onChange={(e) => setBrideChoice(e.target.value)}
              className={inputCls}
            >
              <option value="">Choose a brideΓÇª</option>
              {brides.map((b) => (
                <option key={b.id} value={b.name}>
                  {b.name} ┬╖ {b.stylist}
                </option>
              ))}
              <option value={OTHER}>Someone else (lead / walk-in)ΓÇª</option>
            </select>
            {brideChoice === OTHER && (
              <>
                <input
                  type="text"
                  value={customName}
                  onChange={(e) => setCustomName(e.target.value)}
                  placeholder="Type the lead's name"
                  list="ba-lead-names"
                  className={`${inputCls} mt-2`}
                  autoFocus
                />
                <datalist id="ba-lead-names">
                  {leads.map((l) => (
                    <option key={l.id} value={l.name} />
                  ))}
                </datalist>
              </>
            )}
          </div>
        )}

        <div>
          <label htmlFor="ba-location" className={labelCls}>
            Store location
          </label>
          <LocationSelect id="ba-location" value={location} onChange={setLocation} />
          <p className="mt-1 text-[11px] text-stone-400">
            {locationById(location).address} ┬╖ {locationById(location).hours}
          </p>
        </div>

        <div>
          <label htmlFor="ba-type" className={labelCls}>
            Appointment type
          </label>
          <select
            id="ba-type"
            value={type}
            onChange={(e) => setType(e.target.value as Appointment['type'])}
            className={inputCls}
          >
            {APPOINTMENT_TYPES.map((t) => (
              <option key={t} value={t}>
                {t}
              </option>
            ))}
          </select>
        </div>

        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
          <div>
            <label htmlFor="ba-looking" className={labelCls}>
              Looking for
            </label>
            <select
              id="ba-looking"
              value={lookingFor}
              onChange={(e) => setLookingFor(e.target.value)}
              className={inputCls}
            >
              <option value="">ChooseΓÇª</option>
              {/* Keep a non-standard existing value selectable when editing */}
              {lookingFor && !LOOKING_FOR_OPTIONS.includes(lookingFor as any) && (
                <option value={lookingFor}>{lookingFor}</option>
              )}
              {LOOKING_FOR_OPTIONS.map((o) => (
                <option key={o} value={o}>
                  {o}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="ba-budget" className={labelCls}>
              Budget
            </label>
            <select
              id="ba-budget"
              value={budgetCents}
              onChange={(e) => setBudgetCents(parseInt(e.target.value, 10) || 0)}
              className={inputCls}
            >
              <option value={0}>Choose a rangeΓÇª</option>
              {BUDGET_RANGES.map((b) => (
                <option key={b.cents} value={b.cents}>
                  {b.label}
                </option>
              ))}
            </select>
          </div>
        </div>

        {!isEdit && (
          <label className="flex cursor-pointer items-start gap-2.5 rounded-xl border border-border-subtle bg-brand-soft/60 p-3">
            <input
              type="checkbox"
              checked={feeCollected}
              onChange={(e) => setFeeCollected(e.target.checked)}
              className="mt-0.5 h-4 w-4 rounded border-stone-300 text-brand-primary focus:ring-focus-ring"
            />
            <span className="text-xs leading-relaxed text-brand-secondary">
              <span className="flex items-center gap-1 font-semibold">
                <CreditCard className="h-3.5 w-3.5" /> {formatCents(dynamicBookingFee)} booking fee collected
              </span>
              Every booking carries a flat {formatCents(dynamicBookingFee)} fee, credited toward her purchase. Uncheck if
              collecting at check-in instead.
            </span>
          </label>
        )}


        <div className="flex items-center justify-between">
          <label className="text-sm font-medium text-stone-900">Schedule</label>
          <button
            type="button"
            onClick={handleAISuggest}
            disabled={isSuggesting}
            className="flex items-center gap-1.5 rounded-full border border-violet-200 bg-violet-50 px-3 py-1.5 text-[11px] font-medium text-violet-700 hover:bg-violet-100 disabled:opacity-50 transition-colors"
          >
            {isSuggesting ? <Loader2 className="w-3 h-3 animate-spin" /> : <span>Γ£¿</span>}
            AI Smart Suggest
          </button>
        </div>
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
          <div>
            <label htmlFor="ba-date" className={labelCls}>
              Date
            </label>
            <input
              id="ba-date"
              type="date"
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className={inputCls}
            />
          </div>
          <div>
            <label htmlFor="ba-time" className={labelCls}>
              Time
            </label>
            <select
              id="ba-time"
              value={time}
              onChange={(e) => setTime(e.target.value)}
              className={inputCls}
            >
              <option value="">Pick a timeΓÇª</option>
              {/* Keep a non-standard existing time selectable when editing */}
              {time && !TIME_SLOTS.includes(time) && <option value={time}>{time}</option>}
              {TIME_SLOTS.map((t) => (
                <option key={t} value={t}>
                  {t}
                </option>
              ))}
            </select>
          </div>
        </div>

        <div>
          <label htmlFor="ba-stylist" className={labelCls}>
            Stylist
          </label>
          <select
            id="ba-stylist"
            value={stylist}
            onChange={(e) => setStylist(e.target.value)}
            className={inputCls}
          >
            {/* Keep a stylist no longer on the roster selectable when editing */}
            {stylist && !teamMembers.includes(stylist) && (
              <option value={stylist}>{stylist}</option>
            )}
            {teamMembers.map((m) => (
              <option key={m} value={m}>
                {m}
              </option>
            ))}
          </select>
        </div>

        {conflict && (
          <div className="flex items-start gap-2.5 rounded-xl border border-status-warning/20 bg-status-warning/10 p-3">
            <AlertTriangle className="mt-0.5 h-4 w-4 flex-shrink-0 text-status-warning" />
            <p className="text-xs leading-relaxed text-amber-800">
              <span className="font-semibold">Scheduling conflict:</span> {conflict.stylist} already
              has {conflict.customer} ({conflict.type}) at {conflict.time} on this date at{' '}
              {locationById(conflict.location).short}. You can still {isEdit ? 'save' : 'book'}, but
              consider another time or stylist.
            </p>
          </div>
        )}

        {/* Confirmation / reschedule notice */}
        {canNotify && contact ? (
          <label className="flex cursor-pointer items-start gap-2.5 rounded-xl border border-emerald-200 bg-status-success/10/60 p-3">
            <input
              type="checkbox"
              checked={notify}
              onChange={(e) => setNotify(e.target.checked)}
              className="mt-0.5 h-4 w-4 rounded border-stone-300 text-status-success focus:ring-emerald-400"
            />
            <span className="text-xs leading-relaxed text-emerald-800">
              <span className="flex items-center gap-1 font-semibold">
                <MailCheck className="h-3.5 w-3.5" />
                {isEdit ? 'Send reschedule notice' : 'Send booking confirmation'}
              </span>
              {isEmail(contact.email) && `Email to ${contact.email}`}
              {isEmail(contact.email) && isPhone(contact.phone) && ' ┬╖ '}
              {isPhone(contact.phone) && `Text to ${contact.phone}`}
            </span>
          </label>
        ) : (
          customerName && (
            <p className="rounded-xl border border-stone-200 bg-stone-50 p-3 text-[11px] text-stone-500">
              No email or phone on file for {customerName} ΓÇö no confirmation will be sent. Add contact
              details in Brides to enable automatic confirmations.
            </p>
          )
        )}

        {error && <p className="text-sm text-brand-primary">{error}</p>}

        <label className="flex items-start gap-2.5 rounded-xl border border-stone-200 bg-stone-50 p-3 mt-4">
          <input
            type="checkbox"
            required
            checked={consentChecked}
            onChange={(e) => setConsentChecked(e.target.checked)}
            className="mt-0.5 h-4 w-4 rounded border-stone-300 text-brand-primary focus:ring-brand-primary"
          />
          <span className="text-xs leading-relaxed text-stone-700">
            I agree to the <a href="#" className="underline">Terms of Service</a> and <a href="#" className="underline">Cancellation Policy</a>. I understand that booking fees may apply and that data is processed in accordance with the Privacy Policy.
          </span>
        </label>

        <div className="flex justify-end gap-2 pt-4">
          <button type="button" onClick={handleClose} className={btnSecondary}>
            Cancel
          </button>
          <button type="submit" disabled={saving || !consentChecked} className={`${btnPrimary} disabled:opacity-60`}>
            {saving ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : isEdit ? (
              <Pencil className="h-4 w-4" />
            ) : (
              <CalendarPlus className="h-4 w-4" />
            )}
            {saving
              ? isEdit
                ? 'SavingΓÇª'
                : 'BookingΓÇª'
              : conflict
                ? isEdit
                  ? 'Save Anyway'
                  : 'Book Anyway'
                : isEdit
                  ? 'Save Changes'
                  : 'Book Appointment'}
          </button>
        </div>
      </form>
    </Modal>
  );
}

import { useState, useMemo, useEffect } from 'react';
import {
  Customer,
  formatCents,
  formatDate,
  teamMembers
} from '@/data/vowosData';
import { useVowosData } from '@/contexts/VowosDataContext';
import { fetchContracts, fetchAlterations, ContractRecord, AlterationJob } from '@/lib/contractsAlterations';
import { fetchMessages, MessageRecord } from '@/lib/messaging';
import { Users, Calendar, Shirt, FileSignature, CreditCard, Scissors, MessageSquare, FileText, Activity, ArrowLeft, Phone, Mail, MapPin, CheckCircle2, Clock, Sparkles, Plus } from 'lucide-react';
import { btnPrimary } from './ui';

export type Bride360Tab =
  | 'overview'
  | 'appointments'
  | 'gown'
  | 'contract'
  | 'payments'
  | 'alterations'
  | 'messages'
  | 'documents'
  | 'activity';

interface Bride360ViewProps {
  bride: Customer;
  onBack: () => void;
  initialTab?: Bride360Tab;
  onNavigateView?: (view: string, params?: Record<string, string>) => void;
}

const LIFECYCLE_STAGES = [
  'Lead',
  'Consultation Scheduled',
  'Appointment Completed',
  'Gown Selected',
  'Contract Pending',
  'Payment in Progress',
  'Alterations',
  'Ready for Pickup',
  'Completed',
];

import BridalIdentity from './BridalIdentity';
import BridePhotoModal from './BridePhotoModal';

export default function Bride360View({ bride, onBack, initialTab = 'overview', onNavigateView }: Bride360ViewProps) {
  const [tab, setTab] = useState<Bride360Tab>(initialTab);
  const [photoModalOpen, setPhotoModalOpen] = useState(false);
  const { appointments = [], invoices = [], purchaseOrders = [] } = useVowosData();

  const [contracts, setContracts] = useState<ContractRecord[]>([]);
  const [alterations, setAlterations] = useState<AlterationJob[]>([]);
  const [messages, setMessages] = useState<MessageRecord[]>([]);

  useEffect(() => {
    fetchContracts().then(setContracts).catch(() => {});
    fetchAlterations().then(setAlterations).catch(() => {});
    fetchMessages(bride.name).then(setMessages).catch(() => {});
  }, [bride.name]);

  // Filter bride-specific data safely
  const brideAppointments = useMemo(
    () => (appointments || []).filter((a: any) => a.customer?.toLowerCase() === bride.name.toLowerCase() || a.brideId === bride.id),
    [appointments, bride]
  );

  const brideContract = useMemo(
    () => (contracts || []).find((c) => c.customer?.toLowerCase() === bride.name.toLowerCase()),
    [contracts, bride]
  );

  const brideInvoices = useMemo(
    () => (invoices || []).filter((i: any) => i.brideName?.toLowerCase() === bride.name.toLowerCase() || i.brideId === bride.id),
    [invoices, bride]
  );

  const brideAlterations = useMemo(
    () => (alterations || []).filter((alt) => alt.customer?.toLowerCase() === bride.name.toLowerCase()),
    [alterations, bride]
  );

  const brideMessages = useMemo(
    () => (messages || []).filter((m) => m.customer?.toLowerCase() === bride.name.toLowerCase()),
    [messages, bride]
  );

  const bridePOs = useMemo(
    () => (purchaseOrders || []).filter((po: any) => po.items?.toLowerCase().includes(bride.name.toLowerCase())),
    [purchaseOrders, bride]
  );

  // Map status to stage index
  const currentStageIndex = useMemo(() => {
    if (bride.status === 'Completed') return 8;
    if (bride.status === 'Archived') return 8;
    if (brideAlterations.some((a) => a.status === 'Ready for Pickup')) return 7;
    if (brideAlterations.length > 0) return 6;
    if (brideInvoices.some((i) => i.paidCents > 0)) return 5;
    if (brideContract) return 4;
    if (bride.purchasedGown) return 3;
    if (brideAppointments.some((a) => a.status === 'Completed')) return 2;
    if (brideAppointments.length > 0) return 1;
    return 0;
  }, [bride, brideAlterations, brideInvoices, brideContract, brideAppointments]);

  const tabs: { key: Bride360Tab; label: string; icon: any; count?: number }[] = [
    { key: 'overview', label: 'Overview', icon: Users },
    { key: 'appointments', label: 'Appointments', icon: Calendar, count: brideAppointments.length },
    { key: 'gown', label: 'Gown & Measurements', icon: Shirt },
    { key: 'contract', label: 'Contract', icon: FileSignature, count: brideContract ? 1 : 0 },
    { key: 'payments', label: 'Payments', icon: CreditCard, count: brideInvoices.length },
    { key: 'alterations', label: 'Alterations', icon: Scissors, count: brideAlterations.length },
    { key: 'messages', label: 'Messages', icon: MessageSquare, count: brideMessages.length },
    { key: 'documents', label: 'Documents', icon: FileText },
    { key: 'activity', label: 'Activity Log', icon: Activity },
  ];

  return (
    <div className="space-y-6">
      {/* Header Bar */}
      <div className="flex items-center justify-between border-b border-stone-200 pb-4">
        <button
          onClick={onBack}
          className="inline-flex items-center gap-2 text-xs font-semibold text-stone-600 hover:text-stone-900 transition-colors bg-white border border-stone-200 rounded-lg px-3 py-1.5 shadow-2xs"
        >
          <ArrowLeft className="h-4 w-4" /> Back to Brides
        </button>
        <span className="text-xs text-stone-500 font-medium">Bride 360 Unified Record ┬╖ ID: {bride.id}</span>
      </div>

      {/* Hero Banner */}
      <div className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-stone-900 via-stone-800 to-rose-950 p-6 text-white shadow-xl">
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-6">
          <div className="flex items-center gap-5">
            <BridalIdentity
              customer={bride}
              size="xl"
              showEditOverlay
              onPhotoClick={() => setPhotoModalOpen(true)}
            />
            <div className="space-y-1">
              <div className="flex items-center gap-3">
                <span className="rounded-full bg-brand-primary/20 px-3 py-0.5 text-xs font-semibold text-rose-300 ring-1 ring-inset ring-focus-ring/40">
                  {bride.status} Bride
                </span>
                {bride.stylist && (
                  <span className="text-xs text-stone-300">
                    Stylist: <strong className="text-white">{bride.stylist}</strong>
                  </span>
                )}
              </div>
              <h1 className="font-serif text-3xl font-bold tracking-tight text-white">{bride.name}</h1>
              <div className="flex flex-wrap gap-4 text-xs text-stone-300 pt-1">
                {bride.weddingDate && (
                  <div className="flex items-center gap-1.5">
                    <Calendar className="h-3.5 w-3.5 text-brand-primary" />
                    <span>Wedding: {formatDate(bride.weddingDate)}</span>
                  </div>
                )}
                {bride.email && (
                  <div className="flex items-center gap-1.5">
                    <Mail className="h-3.5 w-3.5 text-brand-primary" />
                    <span>{bride.email}</span>
                  </div>
                )}
                {bride.phone && (
                  <div className="flex items-center gap-1.5">
                    <Phone className="h-3.5 w-3.5 text-brand-primary" />
                    <span>{bride.phone}</span>
                  </div>
                )}
                {bride.location && (
                  <div className="flex items-center gap-1.5">
                    <MapPin className="h-3.5 w-3.5 text-brand-primary" />
                    <span>{bride.location}</span>
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <button
              onClick={() => setTab('messages')}
              className="rounded-xl bg-white/10 px-4 py-2 text-xs font-semibold text-white hover:bg-white/20 transition-colors border border-white/20 flex items-center gap-1.5"
            >
              <MessageSquare className="h-3.5 w-3.5" /> Message
            </button>
            <button
              onClick={() => onNavigateView && onNavigateView('appointments', { brideName: bride.name })}
              className="rounded-xl bg-brand-primary px-4 py-2 text-xs font-semibold text-white shadow-md hover:bg-brand-primary-hover transition-colors flex items-center gap-1.5"
            >
              <Calendar className="h-3.5 w-3.5" /> Book Fitting
            </button>
            <button
              onClick={() => onNavigateView && onNavigateView('invoices', { brideName: bride.name })}
              className="rounded-xl bg-white/10 px-4 py-2 text-xs font-semibold text-white hover:bg-white/20 transition-colors border border-white/20 flex items-center gap-1.5"
            >
              <CreditCard className="h-3.5 w-3.5" /> Collect Payment
            </button>
          </div>
        </div>

        {/* Lifecycle Stage Tracker */}
        <div className="mt-8 border-t border-white/10 pt-6">
          <p className="text-[11px] font-bold uppercase tracking-wider text-rose-300/80 mb-3">
            Bride Lifecycle Journey
          </p>
          <div className="grid grid-cols-3 sm:grid-cols-5 md:grid-cols-9 gap-2">
            {LIFECYCLE_STAGES.map((stage, idx) => {
              const isPassed = idx <= currentStageIndex;
              const isCurrent = idx === currentStageIndex;
              return (
                <div
                  key={stage}
                  className={`flex flex-col items-center rounded-xl p-2 text-center transition-all ${
                    isCurrent
                      ? 'bg-brand-primary text-white font-bold shadow-lg ring-2 ring-rose-300'
                      : isPassed
                      ? 'bg-white/15 text-stone-200'
                      : 'bg-white/5 text-stone-500'
                  }`}
                >
                  <div className="flex h-5 w-5 items-center justify-center rounded-full text-[10px] mb-1">
                    {isPassed ? <CheckCircle2 className="h-4 w-4" /> : <Clock className="h-3.5 w-3.5" />}
                  </div>
                  <span className="text-[10px] leading-tight line-clamp-2">{stage}</span>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* Tabs Subnav */}
      <div className="flex overflow-x-auto border-b border-stone-200 gap-1">
        {tabs.map((t) => {
          const Icon = t.icon;
          const active = tab === t.key;
          return (
            <button
              key={t.key}
              onClick={() => setTab(t.key)}
              className={`flex items-center gap-2 border-b-2 px-3 py-2.5 text-xs font-medium whitespace-nowrap transition-colors ${
                active
                  ? 'border-brand-primary text-brand-primary font-semibold bg-brand-soft/50'
                  : 'border-transparent text-stone-500 hover:border-stone-300 hover:text-stone-800'
              }`}
            >
              <Icon className={`h-4 w-4 ${active ? 'text-brand-primary' : 'text-stone-400'}`} />
              {t.label}
              {t.count !== undefined && (
                <span
                  className={`rounded-full px-1.5 py-0.5 text-[10px] ${
                    active ? 'bg-brand-primary text-white font-bold' : 'bg-stone-100 text-stone-600'
                  }`}
                >
                  {t.count}
                </span>
              )}
            </button>
          );
        })}
      </div>

      {/* Tab Contents */}
      <div className="rounded-2xl border border-stone-200 bg-white p-6 shadow-xs">
        {tab === 'overview' && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="space-y-4">
              <h3 className="text-sm font-semibold text-stone-900 border-b pb-2">Boutique Summary</h3>
              <div className="space-y-2 text-xs text-stone-600">
                <p><strong>Selected Gown:</strong> {bride.purchasedGown || 'None recorded yet'}</p>
                <p><strong>Budget:</strong> ${bride.budget || 'N/A'}</p>
                <p><strong>Boutique Store:</strong> {bride.location || 'Baton Rouge'}</p>
                <p><strong>Assigned Stylist:</strong> {bride.stylist || 'Unassigned'}</p>
              </div>
            </div>

            <div className="space-y-4">
              <h3 className="text-sm font-semibold text-stone-900 border-b pb-2">Contract & Balances</h3>
              <div className="space-y-2 text-xs text-stone-600">
                <p><strong>Contract Status:</strong> {brideContract ? brideContract.status : 'No contract'}</p>
                <p><strong>Total Invoiced:</strong> ${formatCents(brideInvoices.reduce((a, c) => a + c.totalCents, 0))}</p>
                <p><strong>Balance Due:</strong> ${formatCents(brideInvoices.reduce((a, c) => a + c.balanceCents, 0))}</p>
