  );
}

import { useState, useRef, useEffect } from 'react';
import { Customer } from '@/data/vowosData';
import { useVowosData } from '@/contexts/VowosDataContext';
import { Modal } from './ui';
import { Upload, Camera, RotateCcw, RotateCw, ZoomIn, ZoomOut, Trash2, Check, X, RefreshCw, AlertCircle, Image as ImageIcon } from 'lucide-react';
import { toast } from '@vowos/design-system';

interface BridePhotoModalProps {
  open: boolean;
  onClose: () => void;
  bride: Customer;
}

export default function BridePhotoModal({ open, onClose, bride }: BridePhotoModalProps) {
  const { updateBridePhoto } = useVowosData();
  const [tab, setTab] = useState<'upload' | 'camera'>('upload');

  // File upload state
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [sourceImage, setSourceImage] = useState<string | null>(null);

  // Camera state
  const videoRef = useRef<HTMLVideoElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');
  const [capturedPhoto, setCapturedPhoto] = useState<string | null>(null);

  // Crop / Transform state
  const [zoom, setZoom] = useState(1.0);
  const [rotation, setRotation] = useState(0); // 0, 90, 180, 270
  const [saving, setSaving] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Stop camera stream on unmount or tab switch
  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach((track) => track.stop());
      setStream(null);
    }
  };

  useEffect(() => {
    if (!open) {
      stopCamera();
      setSourceImage(null);
      setCapturedPhoto(null);
      setZoom(1.0);
      setRotation(0);
    }
  }, [open]);

  useEffect(() => {
    if (open && tab === 'camera' && !capturedPhoto) {
      startCamera();
    } else {
      stopCamera();
    }
    return () => stopCamera();
  }, [open, tab, facingMode, capturedPhoto]);

  const startCamera = async () => {
    stopCamera();
    setCameraError(null);
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: facingMode, width: { ideal: 1280 }, height: { ideal: 720 } },
        audio: false,
      });
      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
      }
    } catch (err: any) {
      console.error('Camera access error:', err);
      setCameraError('Unable to access camera. Please check browser permissions or use file upload.');
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      toast({ title: 'Invalid file type', description: 'Please select a valid image file (JPEG, PNG, WebP).', variant: 'destructive' });
      return;
    }

    if (file.size > 10 * 1024 * 1024) {
      toast({ title: 'File too large', description: 'Please select an image smaller than 10MB.', variant: 'destructive' });
      return;
    }

    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) {
        setSourceImage(event.target.result as string);
        setZoom(1.0);
        setRotation(0);
      }
    };
    reader.readAsDataURL(file);
  };

  const snapPhoto = () => {
    if (!videoRef.current) return;
    const video = videoRef.current;
    const canvas = document.createElement('canvas');
    canvas.width = video.videoWidth || 640;
    canvas.height = video.videoHeight || 480;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Flip horizontally if front camera for natural mirror preview
    if (facingMode === 'user') {
      ctx.translate(canvas.width, 0);
      ctx.scale(-1, 1);
    }
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    const dataUrl = canvas.toDataURL('image/jpeg', 0.9);
    setCapturedPhoto(dataUrl);
    setSourceImage(dataUrl);
    stopCamera();
  };

  const retakePhoto = () => {
    setCapturedPhoto(null);
    setSourceImage(null);
    startCamera();
  };

  const handleSavePhoto = async () => {
    const imgUrl = sourceImage || capturedPhoto;
    if (!imgUrl) return;

    setSaving(true);
    try {
      // Process image onto normalized 400x400 output canvas
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.src = imgUrl;
      await new Promise((resolve) => (img.onload = resolve));

      const canvas = document.createElement('canvas');
      const size = 400;
      canvas.width = size;
      canvas.height = size;
      const ctx = canvas.getContext('2d');

      if (ctx) {
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, size, size);

        ctx.save();
        ctx.translate(size / 2, size / 2);
        ctx.rotate((rotation * Math.PI) / 180);
        ctx.scale(zoom, zoom);

        const minDim = Math.min(img.width, img.height);
        const sx = (img.width - minDim) / 2;
        const sy = (img.height - minDim) / 2;

        ctx.drawImage(img, sx, sy, minDim, minDim, -size / 2, -size / 2, size, size);
        ctx.restore();

        const croppedDataUrl = canvas.toDataURL('image/jpeg', 0.88);
        await updateBridePhoto(bride.id, croppedDataUrl);
        toast({ title: 'Profile photo updated', description: `Saved new photograph for ${bride.name}` });
        onClose();
      }
    } catch (err: any) {
      console.error('Failed to save bride photo:', err);
      toast({ title: 'Save failed', description: 'Could not process photograph. Please try another image.', variant: 'destructive' });
    } finally {
      setSaving(false);
    }
  };

  const handleRemovePhoto = async () => {
    if (confirm(`Remove profile photo for ${bride.name}?`)) {
      setSaving(true);
      await updateBridePhoto(bride.id, null);
      toast({ title: 'Profile photo removed', description: `Returned ${bride.name} to initials avatar` });
      setSaving(false);
      onClose();
    }
  };

  return (
    <Modal open={open} onClose={onClose} title={`Manage Profile Photo ΓÇö ${bride.name}`}>
      <div className="space-y-5 select-none">
        {/* Navigation Tabs */}
        <div className="flex border-b border-stone-200 gap-2">
          <button
            onClick={() => {
              setTab('upload');
              stopCamera();
            }}
            className={`flex items-center gap-2 border-b-2 px-4 py-2.5 text-xs font-semibold transition-colors ${
              tab === 'upload' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-stone-500 hover:text-stone-800'
            }`}
          >
            <Upload className="h-4 w-4" /> Upload File
          </button>
          <button
            onClick={() => {
              setTab('camera');
              setCapturedPhoto(null);
            }}
            className={`flex items-center gap-2 border-b-2 px-4 py-2.5 text-xs font-semibold transition-colors ${
              tab === 'camera' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-stone-500 hover:text-stone-800'
            }`}
          >
            <Camera className="h-4 w-4" /> Take Photo
          </button>
        </div>

        {/* Tab 1: Upload */}
        {tab === 'upload' && !sourceImage && (
          <div
            onClick={() => fileInputRef.current?.click()}
            className="flex flex-col items-center justify-center rounded-2xl border-2 border-dashed border-stone-300 bg-stone-50/50 p-8 text-center cursor-pointer hover:border-brand-primary hover:bg-brand-soft/30 transition-all"
          >
            <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-brand-soft text-brand-primary mb-3 shadow-xs">
              <ImageIcon className="h-6 w-6" />
            </div>
            <p className="text-sm font-semibold text-stone-800">Click to choose or drag & drop photograph</p>
            <p className="text-xs text-stone-400 mt-1">Supports JPEG, PNG, WebP up to 10MB</p>
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              onChange={handleFileSelect}
              className="hidden"
            />
          </div>
        )}

        {/* Tab 2: Camera Stream */}
        {tab === 'camera' && !capturedPhoto && (
          <div className="space-y-3">
            {cameraError ? (
              <div className="rounded-xl border border-border-subtle bg-brand-soft p-4 text-center text-xs text-brand-primary space-y-2">
                <AlertCircle className="h-6 w-6 mx-auto text-brand-primary" />
                <p className="font-semibold">{cameraError}</p>
                <button
                  onClick={() => setTab('upload')}
                  className="rounded-lg bg-brand-primary text-white px-3 py-1.5 text-xs font-medium hover:bg-brand-primary-hover transition-colors"
                >
                  Switch to Upload File
                </button>
              </div>
            ) : (
              <div className="relative overflow-hidden rounded-2xl bg-stone-950 aspect-video flex items-center justify-center shadow-inner">
                <video ref={videoRef} autoPlay playsInline muted className="h-full w-full object-cover" />
                <div className="absolute bottom-3 inset-x-0 flex items-center justify-center gap-3">
                  <button
                    onClick={() => setFacingMode((m) => (m === 'user' ? 'environment' : 'user'))}
                    className="rounded-full bg-stone-900/80 p-2.5 text-white hover:bg-stone-900 shadow-md backdrop-blur transition-colors"
                    title="Switch Camera"
                  >
                    <RefreshCw className="h-4 w-4" />
                  </button>
                  <button
                    onClick={snapPhoto}
                    className="flex items-center gap-2 rounded-full bg-brand-primary px-5 py-2.5 text-xs font-bold text-white shadow-lg hover:bg-brand-primary-hover transition-transform active:scale-95"
                  >
                    <Camera className="h-4 w-4" /> Snap Photo
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

        {/* Image Editor & Crop Controls (when source image is ready) */}
        {sourceImage && (
          <div className="space-y-4">
            <div className="relative flex justify-center bg-stone-900 p-4 rounded-2xl overflow-hidden shadow-inner">
              <div className="relative h-64 w-64 rounded-full overflow-hidden border-4 border-white shadow-2xl">
                <img
                  src={sourceImage}
                  alt="Crop preview"
                  className="h-full w-full object-cover transition-transform duration-75"
                  style={{
                    transform: `scale(${zoom}) rotate(${rotation}deg)`,
                  }}
                />
              </div>
            </div>

            {/* Transform Sliders & Controls */}
            <div className="flex flex-wrap items-center justify-between gap-4 bg-stone-50 p-3.5 rounded-xl border border-stone-200 text-xs">
              <div className="flex items-center gap-2 flex-1 min-w-[180px]">
                <ZoomOut className="h-4 w-4 text-stone-400" />
                <input
                  type="range"
                  min="1.0"
                  max="3.0"
                  step="0.1"
                  value={zoom}
                  onChange={(e) => setZoom(parseFloat(e.target.value))}
                  className="flex-1 accent-rose-500"
                />
                <ZoomIn className="h-4 w-4 text-stone-400" />
                <span className="font-semibold text-stone-700 w-8">{zoom.toFixed(1)}x</span>
              </div>

              <div className="flex items-center gap-1.5">
                <button
                  onClick={() => setRotation((r) => (r - 90 + 360) % 360)}
                  className="rounded-lg border border-stone-200 bg-white p-2 text-stone-600 hover:bg-stone-100 transition-colors"
                  title="Rotate Left"
                >
                  <RotateCcw className="h-4 w-4" />
                </button>
                <button
                  onClick={() => setRotation((r) => (r + 90) % 360)}
                  className="rounded-lg border border-stone-200 bg-white p-2 text-stone-600 hover:bg-stone-100 transition-colors"
                  title="Rotate Right"
                >
                  <RotateCw className="h-4 w-4" />
                </button>
                {capturedPhoto && (
                  <button
                    onClick={retakePhoto}
                    className="rounded-lg border border-stone-200 bg-white px-2.5 py-2 font-semibold text-stone-600 hover:bg-stone-100 transition-colors"
                  >
                    Retake
                  </button>
                )}
              </div>
            </div>
          </div>
        )}

        {/* Action Buttons */}
        <div className="flex items-center justify-between border-t border-stone-200 pt-4">
          {bride.profilePhotoUrl ? (
            <button
              onClick={handleRemovePhoto}
              disabled={saving}
              className="inline-flex items-center gap-1.5 text-xs font-semibold text-brand-primary hover:text-brand-primary-hover transition-colors"
            >
              <Trash2 className="h-4 w-4" /> Remove Photo
            </button>
          ) : (
            <div />
          )}

          <div className="flex items-center gap-2">
            <button
              onClick={onClose}
              className="rounded-xl border border-stone-200 bg-white px-4 py-2 text-xs font-semibold text-stone-600 hover:bg-stone-50 transition-colors"
            >
              Cancel
            </button>
            {sourceImage && (
              <button
                onClick={handleSavePhoto}
                disabled={saving}
                className="inline-flex items-center gap-1.5 rounded-xl bg-brand-primary px-5 py-2 text-xs font-semibold text-white shadow-md hover:bg-brand-primary-hover transition-colors disabled:opacity-50"
              >
                <Check className="h-4 w-4" /> {saving ? 'Saving...' : 'Save Profile Photo'}
              </button>
            )}
          </div>
        </div>
      </div>
    </Modal>
  );
}

import { useEffect, useMemo, useState, FormEvent } from 'react';
import { Ruler, Shirt, Loader2, Plus, Trash2, X, PencilRuler, Sparkles, PackageSearch } from 'lucide-react';
import { Customer, formatCents, formatDate, teamMembers } from '@/data/vowosData';
import { useVowosData } from '@/contexts/VowosDataContext';
import {
  MeasurementSet,
  MEASUREMENT_FIELDS,
  fetchMeasurements,
  addMeasurement,
  deleteMeasurement,
  TryOnNote,
  TRY_ON_RATINGS,
  TryOnRating,
  RATING_STYLES,
  fetchTryOnNotes,
  addTryOnNote,
  deleteTryOnNote,
} from '@/lib/fitProfile';
import { inputCls, btnPrimary } from './ui';
import { toast } from '@vowos/design-system';

const todayIso = () => new Date().toISOString().slice(0, 10);

const emptyMeasureForm = {
  takenOn: todayIso(),
  bust: '',
  waist: '',
  hips: '',
  hollowToHem: '',
  height: '',
  heelHeight: '',
  streetSize: '',
  gownSize: '',
  notes: '',
};

export default function BrideProfileModal({
  bride,
  open,
  onClose,
}: {
  bride: Customer | null;
  open: boolean;
  onClose: () => void;
}) {
  const { allGowns, purchaseOrders } = useVowosData();
  const [tab, setTab] = useState<'measurements' | 'tryons' | 'orders'>('measurements');

  const bridePos = useMemo(() => {
    if (!bride) return [];
    return purchaseOrders.filter((p) => p.items.toLowerCase().includes(bride.name.toLowerCase()));
  }, [purchaseOrders, bride?.name]);
  const [loading, setLoading] = useState(false);
  const [sets, setSets] = useState<MeasurementSet[]>([]);
  const [tryOns, setTryOns] = useState<TryOnNote[]>([]);

  // Measurement form
  const [showMeasureForm, setShowMeasureForm] = useState(false);
  const [mForm, setMForm] = useState({ ...emptyMeasureForm, takenBy: teamMembers[0] });
  const [savingM, setSavingM] = useState(false);

  // Try-on form
  const [showTryForm, setShowTryForm] = useState(false);
  const [tForm, setTForm] = useState({
    gownPick: '',
    gownName: '',
    designer: '',
    price: '',
    rating: 'Loved' as TryOnRating,
    notes: '',
    stylist: teamMembers[0],
    triedOn: todayIso(),
  });
  const [savingT, setSavingT] = useState(false);

  useEffect(() => {
    if (!open || !bride) return;
    setTab('measurements');
    setShowMeasureForm(false);
    setShowTryForm(false);
    setMForm({ ...emptyMeasureForm, takenBy: bride.stylist || teamMembers[0] });
    setTForm((f) => ({ ...f, gownPick: '', gownName: '', designer: '', price: '', notes: '', stylist: bride.stylist || teamMembers[0], triedOn: todayIso() }));
    setLoading(true);
    Promise.all([fetchMeasurements(bride.id), fetchTryOnNotes(bride.id)]).then(([m, t]) => {
      setSets(m);
      setTryOns(t);
      setLoading(false);
    });
  }, [open, bride?.id]); // eslint-disable-line react-hooks/exhaustive-deps

  const gownOptions = useMemo(() => {
    const seen = new Set<string>();
    return allGowns.filter((g) => {
      const key = `${g.name}|${g.designer}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }, [allGowns]);

  if (!open || !bride) return null;

  const handleAddMeasurement = async (e: FormEvent) => {
    e.preventDefault();
    setSavingM(true);
    const { record, error } = await addMeasurement({
      brideId: bride.id,
      customer: bride.name,
      takenOn: mForm.takenOn || todayIso(),
      bust: mForm.bust,
      waist: mForm.waist,
      hips: mForm.hips,
      hollowToHem: mForm.hollowToHem,
      height: mForm.height,
      heelHeight: mForm.heelHeight,
      streetSize: mForm.streetSize,
      gownSize: mForm.gownSize,
      notes: mForm.notes,
      takenBy: mForm.takenBy,
    });
    setSavingM(false);
    if (error || !record) {
      toast({ title: 'Could not save measurements', description: error ?? 'Unknown error', variant: 'destructive' });
      return;
    }
    setSets((prev) => [record, ...prev]);
    setShowMeasureForm(false);
    setMForm({ ...emptyMeasureForm, takenBy: mForm.takenBy });
    toast({ title: 'Measurements saved', description: `${bride.name} ┬╖ taken ${formatDate(record.takenOn)}` });
  };

  const handleDeleteMeasurement = async (id: string) => {
    const prev = sets;
    setSets((s) => s.filter((m) => m.id !== id));
    const err = await deleteMeasurement(id);
    if (err) {
      setSets(prev);
      toast({ title: 'Could not delete', description: err, variant: 'destructive' });
    }
  };

  const handlePickGown = (val: string) => {
    if (!val) {
      setTForm((f) => ({ ...f, gownPick: '', gownName: '', designer: '', price: '' }));
      return;
    }
    const g = gownOptions.find((x) => `${x.name}|${x.designer}` === val);
    if (g) {
      setTForm((f) => ({
        ...f,
        gownPick: val,
        gownName: g.name,
        designer: g.designer,
        price: (g.priceCents / 100).toFixed(0),
      }));
    } else {
      setTForm((f) => ({ ...f, gownPick: val, gownName: '', designer: '', price: '' }));
    }
  };

  const handleAddTryOn = async (e: FormEvent) => {
    e.preventDefault();
    if (!tForm.gownName.trim()) {
      toast({ title: 'Pick or name a gown first', variant: 'destructive' });
      return;
    }
    setSavingT(true);
    const { record, error } = await addTryOnNote({
      brideId: bride.id,
      customer: bride.name,
      gownName: tForm.gownName.trim(),
      designer: tForm.designer.trim(),
      priceCents: Math.round((parseFloat(tForm.price) || 0) * 100),
      rating: tForm.rating,
      notes: tForm.notes.trim(),
      stylist: tForm.stylist,
      triedOn: tForm.triedOn || todayIso(),
    });
    setSavingT(false);
    if (error || !record) {
      toast({ title: 'Could not save try-on note', description: error ?? 'Unknown error', variant: 'destructive' });
      return;
    }
    setTryOns((prev) => [record, ...prev]);
    setShowTryForm(false);
    setTForm((f) => ({ ...f, gownPick: '', gownName: '', designer: '', price: '', notes: '', rating: 'Loved' }));
    toast({ title: 'Try-on logged', description: `${record.gownName} ┬╖ ${record.rating}` });
  };

  const handleDeleteTryOn = async (id: string) => {
    const prev = tryOns;
    setTryOns((t) => t.filter((n) => n.id !== id));
    const err = await deleteTryOnNote(id);
    if (err) {
      setTryOns(prev);
      toast({ title: 'Could not delete', description: err, variant: 'destructive' });
    }
  };

  const latest = sets[0] ?? null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-stone-900/50 backdrop-blur-sm" onClick={onClose} />
      <div className="relative flex max-h-[90vh] w-full max-w-2xl flex-col overflow-hidden rounded-2xl bg-white shadow-2xl">
        {/* Header */}
        <div className="flex items-start justify-between border-b border-stone-100 px-6 py-4">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-full bg-gradient-to-br from-rose-100 to-rose-200 text-sm font-semibold text-brand-primary">
              {bride.name.split(' ').map((n) => n[0]).join('').slice(0, 2)}
            </div>
            <div>
              <h3 className="font-serif text-xl text-stone-900">{bride.name} ΓÇö Fit Profile</h3>
              <p className="text-xs text-stone-500">
                Wedding {formatDate(bride.weddingDate)} ┬╖ Stylist {bride.stylist}
                {latest && ` ┬╖ Last measured ${formatDate(latest.takenOn)}`}
              </p>
            </div>
          </div>
          <button onClick={onClose} className="rounded-lg p-1.5 text-stone-400 transition-colors hover:bg-stone-100 hover:text-stone-600" aria-label="Close">
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Tabs */}
        <div className="flex gap-1 border-b border-stone-100 px-6 pt-3">
          {(
            [
              { key: 'measurements', label: `Measurements (${sets.length})`, icon: Ruler },
              { key: 'tryons', label: `Try-On Notes (${tryOns.length})`, icon: Shirt },
              { key: 'orders', label: `Purchase Orders (${bridePos.length})`, icon: PackageSearch },
            ] as const
          ).map(({ key, label, icon: Icon }) => (
            <button
              key={key}
              onClick={() => setTab(key)}
              className={`inline-flex items-center gap-1.5 rounded-t-lg border-b-2 px-4 py-2.5 text-sm font-medium transition-colors ${
                tab === key ? 'border-brand-primary text-brand-primary' : 'border-transparent text-stone-500 hover:text-stone-800'
              }`}
            >
              <Icon className="h-4 w-4" /> {label}
            </button>
          ))}
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-5">
          {loading && (
            <div className="py-12 text-center">
              <Loader2 className="mx-auto h-5 w-5 animate-spin text-brand-primary" />
              <p className="mt-2 text-xs text-stone-500">Loading fit profile...</p>
            </div>
          )}

          {/* ΓöÇΓöÇ Measurements tab ΓöÇΓöÇ */}
          {!loading && tab === 'measurements' && (
            <div className="space-y-4">
              {!showMeasureForm && (
                <button onClick={() => setShowMeasureForm(true)} className={btnPrimary}>
                  <Plus className="h-4 w-4" /> Record new measurements
                </button>
              )}

              {showMeasureForm && (
                <form onSubmit={handleAddMeasurement} className="rounded-2xl border border-border-subtle bg-brand-soft/40 p-4">
                  <p className="mb-3 flex items-center gap-2 text-xs font-semibold uppercase tracking-wider text-brand-primary">
                    <PencilRuler className="h-4 w-4" /> New measurement set
                  </p>
                  <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
                    {MEASUREMENT_FIELDS.map((f) => (
                      <div key={f.key}>
                        <label className="mb-1 block text-[11px] font-medium text-stone-600">{f.label}</label>
                        <input
                          value={(mForm as any)[f.key] ?? ''}
                          onChange={(e) => setMForm({ ...mForm, [f.key]: e.target.value })}
                          placeholder={f.placeholder}
                          className={inputCls}
                        />
                      </div>
                    ))}
                    <div>
                      <label className="mb-1 block text-[11px] font-medium text-stone-600">Taken on</label>
                      <input type="date" value={mForm.takenOn} onChange={(e) => setMForm({ ...mForm, takenOn: e.target.value })} className={inputCls} />
                    </div>
                    <div>
                      <label className="mb-1 block text-[11px] font-medium text-stone-600">Taken by</label>
                      <select value={mForm.takenBy} onChange={(e) => setMForm({ ...mForm, takenBy: e.target.value })} className={inputCls}>
                        {teamMembers.map((t) => (
                          <option key={t}>{t}</option>
                        ))}
                      </select>
                    </div>
                  </div>
                  <div className="mt-3">
                    <label className="mb-1 block text-[11px] font-medium text-stone-600">Fitting notes</label>
                    <textarea
                      value={mForm.notes}
                      onChange={(e) => setMForm({ ...mForm, notes: e.target.value })}
                      rows={2}
                      placeholder="e.g. Order to designer chart size 12 ΓÇö hips are the controlling measurement..."
                      className={`${inputCls} resize-none`}
                    />
                  </div>
                  <div className="mt-3 flex gap-2">
                    <button type="submit" disabled={savingM} className={`${btnPrimary} disabled:opacity-60`}>
                      {savingM ? <Loader2 className="h-4 w-4 animate-spin" /> : <Ruler className="h-4 w-4" />} Save measurements
                    </button>
                    <button type="button" onClick={() => setShowMeasureForm(false)} className="rounded-lg px-3 py-2 text-sm text-stone-500 hover:bg-stone-100">
                      Cancel
                    </button>
                  </div>
                </form>
              )}

              {sets.length === 0 && !showMeasureForm && (
                <p className="rounded-2xl border border-dashed border-stone-200 px-4 py-8 text-center text-sm text-stone-400">
                  No measurements on file yet ΓÇö record her first set at the consultation or contract signing.
                </p>
              )}

              {sets.map((m, idx) => (
                <div key={m.id} className={`rounded-2xl border p-4 ${idx === 0 ? 'border-border-subtle bg-white shadow-sm' : 'border-stone-200 bg-stone-50/50'}`}>
                  <div className="mb-3 flex items-center justify-between">
                    <p className="text-sm font-semibold text-stone-800">
                      {formatDate(m.takenOn)}
                      {idx === 0 && (
                        <span className="ml-2 rounded-full bg-brand-soft px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wider text-brand-primary ring-1 ring-inset ring-focus-ring">
                          Current
                        </span>
                      )}
                    </p>
                    <div className="flex items-center gap-2 text-[11px] text-stone-400">
                      {m.takenBy && <span>by {m.takenBy}</span>}
                      <button onClick={() => handleDeleteMeasurement(m.id)} title="Delete" className="rounded p-1 text-stone-300 transition-colors hover:bg-brand-soft hover:text-brand-primary">
                        <Trash2 className="h-3.5 w-3.5" />
                      </button>
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-x-4 gap-y-2 sm:grid-cols-4">
                    {MEASUREMENT_FIELDS.map((f) => (
                      <div key={f.key}>
                        <p className="text-[10px] font-medium uppercase tracking-wider text-stone-400">{f.label}</p>
                        <p className="text-sm font-semibold text-stone-800">{(m as any)[f.key] || 'ΓÇö'}</p>
                      </div>
                    ))}
                  </div>
                  {m.notes && <p className="mt-3 rounded-lg bg-stone-50 px-3 py-2 text-xs leading-relaxed text-stone-600">{m.notes}</p>}
                </div>
              ))}
            </div>
          )}

          {/* ΓöÇΓöÇ Try-on notes tab ΓöÇΓöÇ */}
          {!loading && tab === 'tryons' && (
            <div className="space-y-4">
              {!showTryForm && (
                <button onClick={() => setShowTryForm(true)} className={btnPrimary}>
                  <Plus className="h-4 w-4" /> Log a try-on
                </button>
              )}

              {showTryForm && (
                <form onSubmit={handleAddTryOn} className="rounded-2xl border border-border-subtle bg-brand-soft/40 p-4">
                  <p className="mb-3 flex items-center gap-2 text-xs font-semibold uppercase tracking-wider text-brand-primary">
                    <Sparkles className="h-4 w-4" /> New try-on note
                  </p>
                  <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                    <div className="sm:col-span-2">
                      <label className="mb-1 block text-[11px] font-medium text-stone-600">Gown from inventory</label>
                      <select value={tForm.gownPick} onChange={(e) => handlePickGown(e.target.value)} className={inputCls}>
                        <option value="">Custom / not in inventory...</option>
                        {gownOptions.map((g) => (
                          <option key={g.id} value={`${g.name}|${g.designer}`}>
                            {g.name} ΓÇö {g.designer} ({formatCents(g.priceCents)})
                          </option>
                        ))}
                      </select>
                    </div>
                    <div>
                      <label className="mb-1 block text-[11px] font-medium text-stone-600">Gown name *</label>
                      <input value={tForm.gownName} onChange={(e) => setTForm({ ...tForm, gownName: e.target.value })} placeholder="Seraphina" className={inputCls} />
                    </div>
                    <div>
                      <label className="mb-1 block text-[11px] font-medium text-stone-600">Designer</label>
                      <input value={tForm.designer} onChange={(e) => setTForm({ ...tForm, designer: e.target.value })} placeholder="Maggie Sottero" className={inputCls} />
                    </div>
                    <div>
                      <label className="mb-1 block text-[11px] font-medium text-stone-600">Price ($)</label>
                      <input type="number" min="0" value={tForm.price} onChange={(e) => setTForm({ ...tForm, price: e.target.value })} placeholder="2899" className={inputCls} />
                    </div>
                    <div>
                      <label className="mb-1 block text-[11px] font-medium text-stone-600">Tried on</label>
                      <input type="date" value={tForm.triedOn} onChange={(e) => setTForm({ ...tForm, triedOn: e.target.value })} className={inputCls} />
                    </div>
                  </div>
                  <div className="mt-3">
                    <label className="mb-1 block text-[11px] font-medium text-stone-600">Her reaction</label>
                    <div className="flex flex-wrap gap-2">
                      {TRY_ON_RATINGS.map((r) => (
                        <button
                          key={r}
                          type="button"
                          onClick={() => setTForm({ ...tForm, rating: r })}
                          className={`rounded-full px-3.5 py-1.5 text-xs font-semibold ring-1 ring-inset transition-colors ${
                            tForm.rating === r ? RATING_STYLES[r] : 'bg-white text-stone-500 ring-stone-200 hover:bg-stone-50'
                          }`}
                        >
                          {r}
                        </button>
                      ))}
                    </div>
                  </div>
                  <div className="mt-3 grid grid-cols-1 gap-3 sm:grid-cols-3">
                    <div className="sm:col-span-2">
                      <label className="mb-1 block text-[11px] font-medium text-stone-600">Stylist notes</label>
                      <textarea
                        value={tForm.notes}
                        onChange={(e) => setTForm({ ...tForm, notes: e.target.value })}
                        rows={2}
                        placeholder="What she loved, what didn't work, who was with her, follow-ups..."
                        className={`${inputCls} resize-none`}
                      />
                    </div>
                    <div>
                      <label className="mb-1 block text-[11px] font-medium text-stone-600">Stylist</label>
                      <select value={tForm.stylist} onChange={(e) => setTForm({ ...tForm, stylist: e.target.value })} className={inputCls}>
                        {teamMembers.map((t) => (
                          <option key={t}>{t}</option>
                        ))}
                      </select>
                    </div>
                  </div>
                  <div className="mt-3 flex gap-2">
                    <button type="submit" disabled={savingT} className={`${btnPrimary} disabled:opacity-60`}>
                      {savingT ? <Loader2 className="h-4 w-4 animate-spin" /> : <Shirt className="h-4 w-4" />} Save try-on
                    </button>
                    <button type="button" onClick={() => setShowTryForm(false)} className="rounded-lg px-3 py-2 text-sm text-stone-500 hover:bg-stone-100">
                      Cancel
                    </button>
                  </div>
                </form>
              )}

              {tryOns.length === 0 && !showTryForm && (
                <p className="rounded-2xl border border-dashed border-stone-200 px-4 py-8 text-center text-sm text-stone-400">
                  No try-ons logged yet ΓÇö capture every gown she tries so any stylist can pick up where the last visit left off.
                </p>
              )}

              {tryOns.map((n) => (
                <div key={n.id} className="rounded-2xl border border-stone-200 bg-white p-4 shadow-sm">
                  <div className="flex items-start justify-between gap-3">
                    <div>
                      <p className="text-sm font-semibold text-stone-800">
                        {n.gownName}
                        {n.designer && <span className="font-normal text-stone-500"> ΓÇö {n.designer}</span>}
                      </p>
                      <p className="text-[11px] text-stone-400">
                        {formatDate(n.triedOn)}
                        {n.stylist && ` ┬╖ with ${n.stylist}`}
                        {n.priceCents > 0 && ` ┬╖ ${formatCents(n.priceCents)}`}
                      </p>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-semibold ring-1 ring-inset ${RATING_STYLES[n.rating]}`}>
                        {n.rating}
                      </span>
                      <button onClick={() => handleDeleteTryOn(n.id)} title="Delete" className="rounded p-1 text-stone-300 transition-colors hover:bg-brand-soft hover:text-brand-primary">
                        <Trash2 className="h-3.5 w-3.5" />
                      </button>
                    </div>
                  </div>
                  {n.notes && <p className="mt-2 text-xs leading-relaxed text-stone-600">{n.notes}</p>}
                </div>
              ))}
            </div>
          )}

          {/* ΓöÇΓöÇ Purchase Orders tab ΓöÇΓöÇ */}
          {!loading && tab === 'orders' && (
            <div className="space-y-3">
              {bridePos.length === 0 ? (
                <p className="rounded-2xl border border-dashed border-stone-200 px-4 py-8 text-center text-sm text-stone-400">
                  No special purchase orders currently linked to {bride.name}. Create a PO from the Purchasing screen to track factory production and arrival ETAs.
                </p>
              ) : (
                bridePos.map((po) => (
                  <div key={po.id} className="rounded-2xl border border-stone-200 bg-white p-4 shadow-sm space-y-2">
                    <div className="flex items-center justify-between">
                      <span className="font-bold text-stone-900 text-sm">{po.id}</span>
                      <span className="rounded-full bg-amber-100 px-2.5 py-0.5 text-xs font-semibold text-amber-800">
                        {po.status}
                      </span>
                    </div>
                    <p className="text-xs font-medium text-stone-800">{po.items}</p>
                    <p className="text-xs text-stone-500">
                      Vendor: <span className="font-semibold text-stone-700">{po.vendor}</span> ┬╖ Expected ETA: <span className="font-semibold text-stone-700">{formatDate(po.expectedDelivery)}</span>
                    </p>
                  </div>
                ))
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useAuth } from '@/contexts/AuthContext';
import CalendarLeftPanel from './CalendarLeftPanel';
import CalendarCenterGrid from './CalendarCenterGrid';
import Appointment360Panel from './Appointment360Panel';
import BookAppointmentModal from './BookAppointmentModal';
import { 
  AppointmentRequest, 
  Appointment, 
  EmployeeSchedule,
  fetchAppointmentRequests,
  fetchAppointmentsByDateRange,
  fetchEmployeeSchedules,
  updateAppointment
} from '@/lib/appointment360';
import { format, startOfWeek, endOfWeek, addDays, subDays } from 'date-fns';

export default function Calendar360View() {
  const { profile } = useAuth();
  const [requests, setRequests] = useState<AppointmentRequest[]>([]);
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [schedules, setSchedules] = useState<EmployeeSchedule[]>([]);
  
  const [selectedAppointment, setSelectedAppointment] = useState<Appointment | null>(null);
  
  // Date range state
  const [dateRange, setDateRange] = useState({
    start: startOfWeek(new Date()),
    end: endOfWeek(new Date())
  });

  const loadData = async () => {
    try {
      const startStr = format(dateRange.start, 'yyyy-MM-dd');
      const endStr = format(dateRange.end, 'yyyy-MM-dd');

      const [reqs, appts, scheds] = await Promise.all([
        fetchAppointmentRequests(),
        fetchAppointmentsByDateRange(startStr, endStr),
        fetchEmployeeSchedules(startStr, endStr)
      ]);

      setRequests(reqs);
      setAppointments(appts);
      setSchedules(scheds);
    } catch (err) {
      console.error("Failed to load Calendar 360 data:", err);
    }
  };

  useEffect(() => {
    loadData();
  }, [dateRange]);

  const [isBookingModalOpen, setIsBookingModalOpen] = useState(false);
  const [bookingDefaults, setBookingDefaults] = useState<{ date?: string; time?: string; stylist?: string; request?: AppointmentRequest } | null>(null);

  const handleSelectRequest = (req: AppointmentRequest) => {
    // Open booking modal pre-filled with the request details
    setBookingDefaults({
      date: format(new Date(req.preferred_date || new Date()), 'yyyy-MM-dd'),
      time: req.preferred_time || '',
      request: req
    });
    setIsBookingModalOpen(true);
  };

  const handleAppointmentClick = (appt: Appointment) => {
    setSelectedAppointment(appt);
  };

  const handleDateSelect = (selectInfo: any) => {
    // Open a "new appointment" modal or select time
    setBookingDefaults({
      date: format(new Date(selectInfo.startStr), 'yyyy-MM-dd'),
      time: format(new Date(selectInfo.startStr), 'hh:mm a')
    });
    setIsBookingModalOpen(true);
  };

  const handleEventDrop = async (dropInfo: any) => {
    const { event } = dropInfo;
    const newStart = event.startStr; // This is a full ISO string
    const newDate = format(new Date(newStart), 'yyyy-MM-dd');
    const newTime = format(new Date(newStart), 'HH:mm'); // Needs conversion to whatever format you use
    const appointmentId = event.id;
    
    // Update locally for instant feedback
    setAppointments(prev => prev.map(a => 
      a.id === appointmentId ? { ...a, start_at: newStart, date: newDate, time: newTime } : a
    ));
    
    // Persist to backend
    try {
      await updateAppointment(appointmentId, { start_at: newStart });
    } catch (err) {
      console.error('Failed to update appointment drop:', err);
      // Revert state in a real app
    }
  };

  return (
    <div className="flex h-[calc(100vh-140px)] overflow-hidden bg-white border rounded-xl shadow-sm relative">
      {/* Left Panel: Smart Queue */}
      <CalendarLeftPanel 
        requests={requests} 
        onSelectRequest={handleSelectRequest} 
      />

      {/* Center Grid: FullCalendar workspace */}
      <CalendarCenterGrid 
        appointments={appointments}
        schedules={schedules}
        onAppointmentClick={handleAppointmentClick}
        onDateSelect={handleDateSelect}
        onEventDrop={handleEventDrop}
      />

      {/* Right Panel: Appointment 360 Drawer */}
      {selectedAppointment && (
        <Appointment360Panel 
          appointment={selectedAppointment} 
          onClose={() => setSelectedAppointment(null)}
          onUpdate={async (id, updates) => {
            // Update locally for instant feedback
            setAppointments(prev => prev.map(a => a.id === id ? { ...a, ...updates } : a));
            setSelectedAppointment(prev => prev?.id === id ? { ...prev, ...updates } as Appointment : prev);
            try {
              await updateAppointment(id, updates);
            } catch (err) {
              console.error('Failed to update appointment:', err);
              // In a real app, we'd revert the local state on failure
            }
          }}
        />
      )}

      {/* Booking Modal */}
      <BookAppointmentModal 
        open={isBookingModalOpen} 
        onClose={() => {
          setIsBookingModalOpen(false);
          setBookingDefaults(null);
        }} 
        defaults={bookingDefaults}
      />
    </div>
  );
}

import React, { useRef, useState } from 'react';
import FullCalendar from '@fullcalendar/react';
import dayGridPlugin from '@fullcalendar/daygrid';
import timeGridPlugin from '@fullcalendar/timegrid';
import interactionPlugin from '@fullcalendar/interaction';
import type { Appointment, AppointmentRequest, EmployeeSchedule } from '@/lib/appointment360';
import { Button } from '@vowos/design-system';
import { Calendar as CalendarIcon, Clock, Users, Maximize2 } from 'lucide-react';
import { Badge } from '@vowos/design-system';

interface CalendarCenterGridProps {
  appointments: Appointment[];
  schedules: EmployeeSchedule[];
  onAppointmentClick: (appointment: Appointment) => void;
  onDateSelect: (selectInfo: any) => void;
  onEventDrop: (dropInfo: any) => void;
}

export default function CalendarCenterGrid({
  appointments,
  schedules,
  onAppointmentClick,
  onDateSelect,
  onEventDrop,
}: CalendarCenterGridProps) {
  const calendarRef = useRef<FullCalendar>(null);
  const [viewName, setViewName] = useState('timeGridWeek');

  const handleViewChange = (view: string) => {
    setViewName(view);
    const calendarApi = calendarRef.current?.getApi();
    if (calendarApi) {
      calendarApi.changeView(view);
    }
  };

  const events = appointments.map((appt) => ({
    id: appt.id,
    title: `${appt.customer?.name || 'Appointment'}\nStylist: ${appt.employee?.name || 'Unassigned'}`,
    start: appt.start_at,
    end: appt.end_at,
    extendedProps: appt,
    backgroundColor: appt.status === 'Confirmed' ? '#059669' : '#f59e0b',
    borderColor: 'transparent',
  }));

  // Add employee schedules as background events
  const backgroundEvents = schedules.map((schedule) => ({
    id: `sched-${schedule.id}`,
    title: `Shift: ${schedule.employee_id}`,
    start: `${schedule.shift_date}T${schedule.start_at}`,
    end: `${schedule.shift_date}T${schedule.end_at}`,
    display: 'background',
    backgroundColor: '#ecfdf5', // light green for working
  }));

  return (
    <div className="flex-1 flex flex-col bg-white h-full relative">
      <div className="flex items-center justify-between p-4 border-b">
        <div className="flex items-center space-x-2">
          <Button variant="outline" size="icon" onClick={() => calendarRef.current?.getApi().prev()}>
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
          </Button>
          <Button variant="outline" size="sm" onClick={() => calendarRef.current?.getApi().today()}>
            Today
          </Button>
          <Button variant="outline" size="icon" onClick={() => calendarRef.current?.getApi().next()}>
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6"/></svg>
          </Button>
          <div className="h-6 w-px bg-stone-200 mx-2" />
          <div data-tour-id="calendar-view-toggle" className="flex items-center space-x-2">
            <Button 
              variant={viewName === 'timeGridDay' ? 'default' : 'outline'} 
              size="sm" 
              onClick={() => handleViewChange('timeGridDay')}
            >
              Day
            </Button>
            <Button 
              variant={viewName === 'timeGridWeek' ? 'default' : 'outline'} 
              size="sm" 
              onClick={() => handleViewChange('timeGridWeek')}
            >
              Week
            </Button>
            <Button 
              variant={viewName === 'dayGridMonth' ? 'default' : 'outline'} 
              size="sm" 
              onClick={() => handleViewChange('dayGridMonth')}
            >
              Month
            </Button>
          </div>
          <div className="h-6 w-px bg-stone-200 mx-2" />
          <Button variant="outline" size="sm">
            <Users className="w-4 h-4 mr-2" /> Staffing Grid
          </Button>
        </div>
        
        <div className="flex items-center space-x-4 text-sm text-stone-500">
          <div className="flex items-center">
            <div className="w-3 h-3 rounded-full bg-status-success mr-2" /> Confirmed
          </div>
          <div className="flex items-center">
            <div className="w-3 h-3 rounded-full bg-status-warning mr-2" /> Pending
          </div>
          <Button variant="ghost" size="icon">
            <Maximize2 className="w-4 h-4" />
          </Button>
        </div>
      </div>

      <div className="flex-1 p-4 overflow-hidden">
        <div className="h-full fc-custom-theme">
          <FullCalendar
            ref={calendarRef}
            plugins={[dayGridPlugin, timeGridPlugin, interactionPlugin]}
            initialView="timeGridWeek"
            headerToolbar={false}
            events={[...events, ...backgroundEvents]}
            editable={true}
            droppable={true}
            selectable={true}
            selectMirror={true}
            dayMaxEvents={true}
            slotMinTime="07:00:00"
            slotMaxTime="21:00:00"
            allDaySlot={false}
            eventClick={(arg) => {
              if (arg.event.display !== 'background') {
                onAppointmentClick(arg.event.extendedProps as Appointment);
              }
            }}
            select={onDateSelect}
            eventDrop={onEventDrop}
            height="100%"
          />
        </div>
      </div>
    </div>
  );
}

// ΓöÇΓöÇΓöÇ Reusable real-card payment form (Stripe Elements) ΓöÇΓöÇΓöÇ
// Used by the public booking page ($75 fee) and the invoice pay page.
// Detects the card brand as the bride types, shows the boutique's configurable
// surcharge (3% credit / 4% Amex by default), then charges the card for real:
// create-payment edge function ΓåÆ PaymentIntent ΓåÆ stripe.confirmCardPayment.

import { useEffect, useState } from 'react';
import { CreditCard, Loader2, Lock } from 'lucide-react';
import { Elements, CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import { supabase, getActiveDataPlane } from '@/lib/supabase';
import { formatCents } from '@/data/vowosData';
import {
  stripePromise,
  SurchargeSettings,
  DEFAULT_SURCHARGE,
  fetchSurchargeSettings,
  surchargePctFor,
  surchargeCentsFor,
  cardBrandLabel,
  isAmexBrand,
} from '@/lib/payments';

export interface CardPaymentResult {
  paymentIntentId: string;
  baseCents: number;
  surchargeCents: number;
  surchargePct: number;
  totalCents: number;
  brand: string;
  brandLabel: string;
}

interface Props {
  /** Amount before any card surcharge, in cents. */
  baseCents: number;
  /** Statement / gateway description for the charge. */
  description: string;
  metadata?: Record<string, string>;
  /** Label under the total row, e.g. "booking fee" or "payment". */
  baseLabel?: string;
  buttonLabel?: string;
  disabled?: boolean;
  onSuccess: (result: CardPaymentResult) => void | Promise<void>;
}

const CARD_ELEMENT_OPTIONS = {
  style: {
    base: {
      fontSize: '15px',
      color: '#1c1917',
      fontFamily: 'ui-sans-serif, system-ui, sans-serif',
      '::placeholder': { color: '#a8a29e' },
    },
    invalid: { color: '#e11d48' },
  },
  hidePostalCode: false,
};

function InnerForm({ baseCents, description, metadata, baseLabel = 'amount', buttonLabel, disabled, onSuccess }: Props) {
  const stripe = useStripe();
  const elements = useElements();
  const [settings, setSettings] = useState<SurchargeSettings>(DEFAULT_SURCHARGE);
  const [brand, setBrand] = useState<string>('unknown');
  const [cardComplete, setCardComplete] = useState(false);
  const [error, setError] = useState('');
  const [paying, setPaying] = useState(false);

  useEffect(() => {
    fetchSurchargeSettings().then(setSettings);
  }, []);

  const pct = surchargePctFor(brand, settings);
  const surcharge = surchargeCentsFor(baseCents, brand, settings);
  const total = baseCents + surcharge;
  const brandKnown = brand !== 'unknown' && brand !== '';

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!stripe || !elements) return;
    const cardEl = elements.getElement(CardElement);
    if (!cardEl) return;
    if (!cardComplete) {
      setError('Please complete the card details.');
      return;
    }
    setError('');
    setPaying(true);

    try {
      // 1) Server computes the surcharge from saved settings + brand and creates the PaymentIntent
      
      if (getActiveDataPlane() === 'demo') {
        console.log('[DEMO MODE] Processing isolated Stripe payment.');
        await new Promise((res) => setTimeout(res, 800));
        const pct = surchargePctFor(brand, settings);
        const sc = surchargeCentsFor(baseCents, brand, settings);
        await onSuccess({
          paymentIntentId: 'pi_demo_123456789',
          baseCents,
          surchargeCents: sc,
          surchargePct: pct,
          totalCents: baseCents + sc,
          brand: brand,
          brandLabel: cardBrandLabel(brand),
        });
        return;
      }

      const { data, error: fnErr } = await supabase.functions.invoke('create-payment', {
        body: { amount_cents: baseCents, card_brand: brand, description, metadata },
      });
      if (fnErr || !data?.clientSecret) {
        throw new Error(data?.error || fnErr?.message || 'Could not start the payment.');
      }

      // 2) Charge the card for real
      const { error: confirmErr, paymentIntent } = await stripe.confirmCardPayment(data.clientSecret, {
        payment_method: { card: cardEl },
      });
      if (confirmErr) {
        throw new Error(confirmErr.message || 'The card was declined.');
      }
      if (paymentIntent?.status !== 'succeeded') {
        throw new Error('The payment did not complete. Please try again.');
      }

      await onSuccess({
        paymentIntentId: paymentIntent.id,
        baseCents: data.baseCents,
        surchargeCents: data.surchargeCents,
        surchargePct: data.surchargePct,
        totalCents: data.totalCents,
        brand: data.brand,
        brandLabel: cardBrandLabel(data.brand),
      });
    } catch (err: any) {
      setError(err.message || 'The payment could not be processed.');
    } finally {
      setPaying(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div>
        <label className="mb-1 block text-xs font-medium uppercase tracking-wider text-stone-500">
          Card details
        </label>
        <div className="rounded-lg border border-stone-300 bg-white px-3 py-3 focus-within:border-brand-primary focus-within:ring-2 focus-within:ring-focus-ring">
          <CardElement
            options={CARD_ELEMENT_OPTIONS}
            onChange={(e) => {
              setBrand(e.brand ?? 'unknown');
              setCardComplete(e.complete);
              setError(e.error?.message ?? '');
            }}
          />
        </div>
        {brandKnown && (
          <p className="mt-1.5 flex items-center gap-1.5 text-[11px] text-stone-500">
            <CreditCard className="h-3.5 w-3.5 text-stone-400" />
            {cardBrandLabel(brand)} detected
            {settings.enabled && pct > 0 && (
              <span className={isAmexBrand(brand) ? 'font-medium text-status-warning' : 'font-medium text-stone-600'}>
                ┬╖ {pct}% card processing fee applies
              </span>
            )}
          </p>
        )}
      </div>

      {/* Totals breakdown */}
      <div className="rounded-xl bg-stone-50 p-3.5 text-sm ring-1 ring-stone-200">
        <div className="flex justify-between text-stone-600">
          <span className="capitalize">{baseLabel}</span>
          <span>{formatCents(baseCents)}</span>
        </div>
        {settings.enabled && (
          <div className="mt-1 flex justify-between text-stone-500">
            <span>
              Card processing fee{' '}
              {brandKnown ? `(${cardBrandLabel(brand)} ┬╖ ${pct}%)` : `(${settings.creditPct}% ┬╖ ${settings.amexPct}% Amex)`}
            </span>
            <span>{brandKnown ? formatCents(surcharge) : 'ΓÇö'}</span>
          </div>
        )}
        <div className="mt-2 flex justify-between border-t border-stone-200 pt-2 font-semibold text-stone-900">
          <span>Total charged today</span>
          <span>{formatCents(brandKnown ? total : baseCents)}</span>
        </div>
      </div>

      {error && <p className="text-sm text-brand-primary">{error}</p>}

      <button
        type="submit"
        disabled={!stripe || paying || disabled}
        className="inline-flex w-full items-center justify-center gap-2 rounded-xl bg-brand-primary py-3 text-sm font-semibold text-white shadow-sm transition-colors hover:bg-brand-primary-hover disabled:opacity-60"
      >
        {paying ? <Loader2 className="h-4 w-4 animate-spin" /> : <Lock className="h-4 w-4" />}
        {paying ? 'ProcessingΓÇª' : buttonLabel ?? `Pay ${formatCents(brandKnown ? total : baseCents)} securely`}
      </button>
      <p className="flex items-center justify-center gap-1.5 text-center text-[11px] text-stone-400">
        <Lock className="h-3 w-3" /> Card processed securely by Stripe.
        {settings.enabled && ` A ${settings.creditPct}% card fee (${settings.amexPct}% Amex) is added at checkout.`}
      </p>
    </form>
  );
}

export default function CardPaymentForm(props: Props) {
  return (
    <Elements stripe={stripePromise}>
      <InnerForm {...props} />
    </Elements>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import { Search, X, Users, Sparkles, Shirt, FileSignature, Receipt, CalendarDays, ArrowRight, ShieldAlert } from 'lucide-react';
import { NAVIGATION_ITEMS, NavigationItem, ViewKey } from '@/lib/navigation/navigationRegistry';
import { useAuth } from '@/contexts/AuthContext';
import { useVowosData } from '@/contexts/VowosDataContext';
import { canAccessView } from '@/components/vowos/Sidebar';
import { fetchContracts, ContractRecord } from '@/lib/contractsAlterations';
import BridalIdentity from './BridalIdentity';

interface CommandPaletteModalProps {
  open: boolean;
  onClose: () => void;
  onNavigate: (view: ViewKey, params?: Record<string, string>) => void;
}

export default function CommandPaletteModal({ open, onClose, onNavigate }: CommandPaletteModalProps) {
  const [query, setQuery] = useState('');
  const [selectedIndex, setSelectedIndex] = useState(0);
  const { profile } = useAuth();
  const role = profile?.role ?? null;
  const { brides = [], gowns = [], leads = [], appointments = [], invoices = [] } = useVowosData();
  const [contracts, setContracts] = useState<ContractRecord[]>([]);

  useEffect(() => {
    if (open) {
      fetchContracts().then(setContracts).catch(() => {});
    }
  }, [open]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        if (open) onClose();
        else setQuery('');
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [open, onClose]);

  useEffect(() => {
    setSelectedIndex(0);
  }, [query]);

  // Compute matching items across navigation and domain entities
  const navResults = useMemo(() => {
    if (!query.trim()) {
      return (NAVIGATION_ITEMS || []).filter((item) => !item.external && canAccessView(role, item.id as ViewKey, profile?.id)).slice(0, 5);
    }
    const q = query.toLowerCase();
    return (NAVIGATION_ITEMS || []).filter((item) => {
      if (item.external) return false;
      if (!canAccessView(role, item.id as ViewKey, profile?.id)) return false;
      return (
        item.label.toLowerCase().includes(q) ||
        item.shortLabel?.toLowerCase().includes(q) ||
        item.searchKeywords.some((kw) => kw.includes(q))
      );
    });
  }, [query, role, profile?.id]);

  const brideResults = useMemo(() => {
    if (!query.trim() || !canAccessView(role, 'customers', profile?.id)) return [];
    const q = query.toLowerCase();
    return (brides || [])
      .filter((b) => b.name?.toLowerCase().includes(q) || b.email?.toLowerCase().includes(q) || b.phone?.includes(q))
      .slice(0, 4);
  }, [query, brides, role, profile?.id]);

  const gownResults = useMemo(() => {
    if (!query.trim() || !canAccessView(role, 'inventory', profile?.id)) return [];
    const q = query.toLowerCase();
    return (gowns || [])
      .filter((g) => g.name?.toLowerCase().includes(q) || g.designer?.toLowerCase().includes(q) || g.sku?.toLowerCase().includes(q))
      .slice(0, 4);
  }, [query, gowns, role, profile?.id]);

  const leadResults = useMemo(() => {
    if (!query.trim() || !canAccessView(role, 'leads', profile?.id)) return [];
    const q = query.toLowerCase();
    return (leads || [])
      .filter((l) => l.name?.toLowerCase().includes(q) || l.email?.toLowerCase().includes(q))
      .slice(0, 3);
  }, [query, leads, role, profile?.id]);

  const contractResults = useMemo(() => {
    if (!query.trim() || !canAccessView(role, 'contracts', profile?.id)) return [];
    const q = query.toLowerCase();
    return (contracts || [])
      .filter((c) => c.customer?.toLowerCase().includes(q) || c.id?.toLowerCase().includes(q))
      .slice(0, 3);
  }, [query, contracts, role, profile?.id]);

  const invoiceResults = useMemo(() => {
    if (!query.trim() || !canAccessView(role, 'invoices', profile?.id)) return [];
    const q = query.toLowerCase();
    return (invoices || [])
      .filter((inv) => inv.brideName?.toLowerCase().includes(q) || inv.invoiceNumber?.toLowerCase().includes(q))
      .slice(0, 3);
  }, [query, invoices, role, profile?.id]);

  // Combined selectable list for keyboard navigation
  const allResults = useMemo(() => {
    const list: { type: string; id: string; label: string; sub?: string; icon: any; action: () => void }[] = [];

    navResults.forEach((item) => {
      const Icon = item.icon;
      list.push({
        type: 'Navigation',
        id: `nav-${item.id}`,
        label: item.label,
        sub: `Go to ${item.label}`,
        icon: Icon,
        action: () => {
          onNavigate(item.id as ViewKey);
          onClose();
        },
      });
    });

    brideResults.forEach((b) => {
      list.push({
        type: 'Brides',
        id: `bride-${b.id}`,
        label: b.name,
        sub: `Wedding: ${b.weddingDate || 'TBD'} ┬╖ ${b.status}`,
        icon: Users,
        customerObj: b,
        action: () => {
          onNavigate('customers', { brideId: b.id });
          onClose();
        },
      });
    });

    gownResults.forEach((g) => {
      list.push({
        type: 'Inventory',
        id: `gown-${g.id}`,
        label: g.name,
        sub: `${g.designer} ┬╖ SKU ${g.sku}`,
        icon: Shirt,
        action: () => {
          onNavigate('inventory', { gownId: g.id });
          onClose();
        },
      });
    });

    leadResults.forEach((l) => {
      list.push({
        type: 'Leads',
        id: `lead-${l.id}`,
        label: l.name,
        sub: `Stage: ${l.stage} ┬╖ Source: ${l.source}`,
        icon: Sparkles,
        action: () => {
          onNavigate('leads', { leadId: l.id });
          onClose();
        },
      });
    });

    contractResults.forEach((c) => {
      list.push({
        type: 'Contracts',
        id: `contract-${c.id}`,
        label: `Contract for ${c.customer}`,
        sub: `Status: ${c.status} ┬╖ Total: $${c.amountCents ? (c.amountCents / 100).toFixed(2) : '0.00'}`,
        icon: FileSignature,
        action: () => {
          onNavigate('contracts', { contractId: c.id });
          onClose();
        },
      });
    });

    invoiceResults.forEach((inv) => {
      list.push({
        type: 'Invoices',
        id: `invoice-${inv.id}`,
        label: `${inv.invoiceNumber} - ${inv.brideName}`,
        sub: `Status: ${inv.status} ┬╖ Balance: $${(inv.balanceCents / 100).toFixed(2)}`,
        icon: Receipt,
        action: () => {
          onNavigate('invoices', { invoiceId: inv.id });
          onClose();
        },
      });
    });

    return list;
  }, [navResults, brideResults, gownResults, leadResults, contractResults, invoiceResults, onNavigate, onClose]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setSelectedIndex((prev) => (allResults.length > 0 ? (prev + 1) % allResults.length : 0));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setSelectedIndex((prev) => (allResults.length > 0 ? (prev - 1 + allResults.length) % allResults.length : 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (allResults[selectedIndex]) {
        allResults[selectedIndex].action();
      }
    } else if (e.key === 'Escape') {
      e.preventDefault();
      onClose();
    }
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center pt-16 sm:pt-24 px-4 bg-stone-900/60 backdrop-blur-sm">
      <div
        className="w-full max-w-2xl overflow-hidden rounded-2xl bg-white shadow-2xl ring-1 ring-stone-900/10 animate-in fade-in zoom-in-95 duration-150"
        onKeyDown={handleKeyDown}
      >
        {/* Search Header */}
        <div className="flex items-center border-b border-stone-200 px-4 py-3.5">
          <Search className="h-5 w-5 text-stone-400 mr-3 flex-shrink-0" />
          <input
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search brides, gowns, contracts, invoices, schedule, or commands..."
            className="flex-1 bg-transparent text-sm text-stone-900 placeholder-stone-400 focus:outline-none"
            autoFocus
          />
          <kbd className="hidden sm:inline-flex items-center gap-1 rounded border border-stone-200 bg-stone-50 px-1.5 py-0.5 text-[10px] font-medium text-stone-500 mr-2">
            ESC
          </kbd>
          <button
            onClick={onClose}
            className="rounded-lg p-1 text-stone-400 hover:bg-stone-100 hover:text-stone-600 transition-colors"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Results List */}
        <div className="max-h-96 overflow-y-auto p-2 space-y-1">
          {allResults.length === 0 ? (
            <div className="py-12 text-center">
              <p className="text-sm font-medium text-stone-600">No matching records or commands found</p>
              <p className="text-xs text-stone-400 mt-1">Try searching for a bride name, gown style, invoice #, or view key.</p>
            </div>
          ) : (
            allResults.map((item, idx) => {
              const isSelected = idx === selectedIndex;
              const Icon = item.icon;
              return (
                <button
                  key={item.id}
                  onClick={item.action}
                  onMouseEnter={() => setSelectedIndex(idx)}
                  className={`flex w-full items-center justify-between rounded-xl px-3 py-2.5 text-left text-sm transition-all ${
                    isSelected ? 'bg-brand-soft text-brand-secondary font-medium' : 'text-stone-700 hover:bg-stone-50'
                  }`}
                >
                  <div className="flex items-center gap-3 min-w-0">
                    {(item as any).customerObj ? (
                      <BridalIdentity customer={(item as any).customerObj} size="sm" />
                    ) : (
                      <div
                        className={`flex h-8 w-8 items-center justify-center rounded-lg ${
                          isSelected ? 'bg-brand-primary text-white' : 'bg-stone-100 text-stone-600'
                        }`}
                      >
                        <Icon className="h-4 w-4" />
                      </div>
                    )}
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2">
                        <span className="truncate font-semibold text-stone-900">{item.label}</span>
                        <span className="text-[10px] font-medium text-stone-400 uppercase tracking-wider bg-stone-100 px-1.5 py-0.5 rounded">
                          {item.type}
                        </span>
                      </div>
                      {item.sub && <p className="text-xs text-stone-500 truncate">{item.sub}</p>}
                    </div>
                  </div>
                  <ArrowRight className={`h-4 w-4 ml-2 transition-transform ${isSelected ? 'text-brand-primary translate-x-0.5' : 'text-stone-300'}`} />
                </button>
              );
            })
          )}
        </div>

        {/* Footer shortcuts */}
        <div className="flex items-center justify-between border-t border-stone-100 bg-stone-50/80 px-4 py-2 text-[11px] text-stone-500">
          <div className="flex items-center gap-3">
            <span>
              <kbd className="rounded border bg-white px-1 font-sans shadow-2xs">ΓåæΓåô</kbd> Navigate
            </span>
            <span>
              <kbd className="rounded border bg-white px-1 font-sans shadow-2xs">Γå╡</kbd> Select
            </span>
          </div>
          <span>Permission & Location Scoped</span>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from 'react';
import { MessageSquare, Mail, Search, Send, Loader2, CheckCircle2, AlertCircle, CalendarCheck, Link2, BellRing, Sparkles, Zap, RefreshCw, X, ArrowDownLeft, Sunrise, Phone, Instagram, Facebook, MessageCircle, Wand2 } from 'lucide-react';
import { Customer, formatCents, formatDate, locationById } from '@/data/vowosData';
import { useVowosData } from '@/contexts/VowosDataContext';
import { supabase } from '@/lib/supabase';
import { toast } from '@vowos/design-system';
import BridalIdentity from './BridalIdentity';
import { PageHeader, inputCls, Modal, BeautifulEmptyState } from './ui';
import {
  MessageChannel,
  MessageKind,
  MessageRecord,
  KIND_LABELS,
  fetchMessages,
  sendAndLogMessage,
  appointmentConfirmationTemplates,
  appointmentRescheduleTemplates,
  paymentLinkTemplates,
  overdueChaseTemplates,
  reminderTemplates,
  isEmail,
  isPhone,
  generateAiReply,
} from '@/lib/messaging';
import { fetchDigestSettings, saveDigestSettings } from '@/lib/fitProfile';
import BrideChecklist, { ChecklistDraft } from './BrideChecklist';


const todayIso = () => new Date().toISOString().slice(0, 10);

export default function CommunicationsView() {
  const { brides, allAppointments, allInvoices, setAppointmentStatus } = useVowosData();
  const [query, setQuery] = useState('');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [thread, setThread] = useState<MessageRecord[]>([]);
  const [threadLoading, setThreadLoading] = useState(false);
  const [channel, setChannel] = useState<MessageChannel>('sms');
  const [subject, setSubject] = useState('');
  const [body, setBody] = useState('');
  const [kind, setKind] = useState<MessageKind>('general');
  const [sending, setSending] = useState(false);
  const [confirmingId, setConfirmingId] = useState<string | null>(null);
  const [runningAuto, setRunningAuto] = useState(false);
  const [lastInboundCount, setLastInboundCount] = useState<Record<string, number>>({});
  const pollRef = useRef<number | null>(null);

  // Morning digest settings (persisted in app_settings, consumed by the 9am cron)
  const [digestEmail, setDigestEmail] = useState('');
  const [digestEnabled, setDigestEnabled] = useState(true);
  const [savingDigest, setSavingDigest] = useState(false);
  const [sendingDigest, setSendingDigest] = useState(false);

  useEffect(() => {
    fetchDigestSettings().then((s) => {
      setDigestEmail(s.email);
      setDigestEnabled(s.enabled);
    });
  }, []);


  const contacts = useMemo(
    () =>
      brides.filter(
        (b) =>
          b.name.toLowerCase().includes(query.toLowerCase()) ||
          b.email.toLowerCase().includes(query.toLowerCase()),
      ),
    [brides, query],
  );

  const selected: Customer | null = brides.find((b) => b.id === selectedId) ?? null;

  // Auto-select the first bride so the hub never opens empty
  useEffect(() => {
    if (!selectedId && brides.length > 0) setSelectedId(brides[0].id);
  }, [brides, selectedId]);

  // Pick the best default channel for the selected bride
  useEffect(() => {
    if (!selected) return;
    if (isPhone(selected.phone)) setChannel('sms');
    else if (isEmail(selected.email)) setChannel('email');
  }, [selectedId]); // eslint-disable-line react-hooks/exhaustive-deps

  const loadThread = async (name: string, showSpinner = true) => {
    if (showSpinner) setThreadLoading(true);
    const msgs = await fetchMessages(name);
    setThread(msgs);
    if (showSpinner) setThreadLoading(false);
    // Surface new inbound replies as a toast while the hub is open
    const inbound = msgs.filter((m) => m.direction === 'inbound').length;
    setLastInboundCount((prev) => {
      if (prev[name] !== undefined && inbound > prev[name]) {
        toast({ title: `New text from ${name}`, description: msgs.find((m) => m.direction === 'inbound')?.body?.slice(0, 120) });
      }
      return { ...prev, [name]: inbound };
    });
  };

  useEffect(() => {
    if (selected) loadThread(selected.name);
    else setThread([]);
  }, [selectedId]); // eslint-disable-line react-hooks/exhaustive-deps

  // ΓöÇΓöÇ Two-way texting: poll the thread every 12s so bride replies appear live ΓöÇΓöÇ
  useEffect(() => {
    if (!selected) return;
    pollRef.current = window.setInterval(() => loadThread(selected.name, false), 12000);
    return () => {
      if (pollRef.current) window.clearInterval(pollRef.current);
    };
  }, [selectedId]); // eslint-disable-line react-hooks/exhaustive-deps

  // Upcoming appointments awaiting confirmation (across all stores)
  const pendingConfirmations = useMemo(
    () =>
      allAppointments.filter(
        (a) => a.status === 'Pending' && a.date >= todayIso(),
      ),
    [allAppointments],
  );

  const nextApptFor = (name: string) =>
    allAppointments
      .filter((a) => a.customer === name && a.date >= todayIso() && a.status !== 'Cancelled' && a.status !== 'Completed')
      .sort((a, b) => a.date.localeCompare(b.date))[0] ?? null;

  const openInvoiceFor = (name: string) =>
    allInvoices
      .filter((i) => i.customer === name && i.amountCents > i.paidCents)
      .sort((a, b) => a.dueDate.localeCompare(b.dueDate))[0] ?? null;

  const applyTemplate = (t: 'confirm' | 'reschedule' | 'payment' | 'chase' | 'reminder') => {
    if (!selected) return;
    if (t === 'payment' || t === 'chase') {
      const inv = openInvoiceFor(selected.name);
      if (!inv) {
        toast({ title: 'No open balance', description: `${selected.name} has no unpaid invoices.` });
        return;
      }
      const tpl = t === 'chase' ? overdueChaseTemplates(inv) : paymentLinkTemplates(inv);
      setKind(t === 'chase' ? 'chase' : 'payment');
      setSubject(tpl.emailSubject);
      setBody(channel === 'sms' ? tpl.sms : tpl.emailText);
      return;
    }
    const appt = nextApptFor(selected.name);
    if (!appt) {
      toast({ title: 'No upcoming appointment', description: `Book ${selected.name} first, then send a ${t} message.` });
      return;
    }
    const tpl =
      t === 'confirm'
        ? appointmentConfirmationTemplates(appt)
        : t === 'reschedule'
          ? appointmentRescheduleTemplates(appt)
          : reminderTemplates(appt);
    setKind(t === 'confirm' ? 'confirmation' : t === 'reschedule' ? 'reschedule' : 'reminder');
    setSubject(tpl.emailSubject);
    setBody(channel === 'sms' ? tpl.sms : tpl.emailText);
  };

  /** Checklist hands us an AI/template draft ΓÇö load it into the composer. */
  const handleChecklistDraft = (draft: ChecklistDraft) => {
    setChannel(draft.channel);
    setKind(draft.kind);
    setSubject(draft.subject);
    setBody(draft.body);
  };

  const [generatingAi, setGeneratingAi] = useState(false);

  const handleMagicReply = async () => {
    if (!selected) return;
    setGeneratingAi(true);
    const { ok, text, error } = await generateAiReply(selected, thread, channel);
    setGeneratingAi(false);
    if (ok) {
      setBody(text);
      setKind('general');
      toast({ title: 'Magic Reply Generated', description: 'Review the drafted message before sending.' });
    } else {
      toast({ title: 'AI Generation Failed', description: error ?? 'Unknown error', variant: 'destructive' });
    }
  };

  const handleSend = async () => {
    if (!selected || !body.trim()) return;
    const to = channel === 'sms' ? selected.phone : selected.email;
    if (channel === 'sms' && !isPhone(to)) {
      toast({ title: 'No phone on file', description: `Add a phone number for ${selected.name} to text her.`, variant: 'destructive' });
      return;
    }
    if (channel === 'email' && !isEmail(to)) {
      toast({ title: 'No email on file', description: `Add an email address for ${selected.name} first.`, variant: 'destructive' });
      return;
    }
    setSending(true);
    const res = await sendAndLogMessage({
      channel,
      to,
      subject: channel === 'email' ? (subject || 'A note from your bridal boutique') : undefined,
      body: body.trim(),
      customer: selected.name,
      kind,
    });
    setSending(false);
    if (res.ok) {
      toast({ title: channel === 'sms' ? 'Text sent' : 'Email sent', description: `Delivered to ${to}.` });
    } else {
      toast({
        title: 'Send failed ΓÇö logged to conversation',
        description: res.error ?? 'Unknown error',
        variant: 'destructive',
      });
    }
    setBody('');
    setSubject('');
    setKind('general');
    loadThread(selected.name);
  };

  /** One-click: send confirmation via every available channel + mark Confirmed. */
  const handleConfirmAppointment = async (apptId: string) => {
    const appt = allAppointments.find((a) => a.id === apptId);
    if (!appt) return;
    const bride = brides.find((b) => b.name === appt.customer);
    setConfirmingId(apptId);
    const tpl = appointmentConfirmationTemplates(appt);
    const results: string[] = [];
    if (bride && isEmail(bride.email)) {
      const r = await sendAndLogMessage({
        channel: 'email',
        to: bride.email,
        subject: tpl.emailSubject,
        body: tpl.emailText,
        html: tpl.emailHtml,
        customer: appt.customer,
        kind: 'confirmation',
      });
      results.push(r.ok ? 'email sent' : 'email failed');
    }
    if (bride && isPhone(bride.phone)) {
      const r = await sendAndLogMessage({
        channel: 'sms',
        to: bride.phone,
        body: tpl.sms,
        customer: appt.customer,
        kind: 'confirmation',
      });
      results.push(r.ok ? 'text sent' : 'text failed');
    }
    await setAppointmentStatus(appt.id, 'Confirmed');
    setConfirmingId(null);
    toast({
      title: 'Appointment confirmed',
      description:
        results.length > 0
          ? `${appt.customer} ┬╖ ${formatDate(appt.date)} at ${appt.time} ΓÇö ${results.join(' ┬╖ ')}.`
          : `${appt.customer} confirmed. No email or phone on file, so no message was sent.`,
    });
    if (selected && selected.name === appt.customer) loadThread(appt.customer);
  };

  /** Manually trigger the automation sweep (reminders / chases / photo emails / digest). */
  const handleRunAutomations = async () => {
    setRunningAuto(true);
    try {
      const { data, error } = await supabase.functions.invoke('auto-comms', { body: {} });
      if (error || !data?.ok) {
        toast({ title: 'Automation run failed', description: error?.message ?? data?.error ?? 'Unknown error', variant: 'destructive' });
      } else {
        toast({
          title: 'Automations ran',
          description: `${data.reminders} reminder(s) ┬╖ ${data.chases} overdue chase(s) ┬╖ ${data.photos} photo email(s) ┬╖ digest: ${data.digest ?? 'n/a'}.`,
        });
        if (selected) loadThread(selected.name, false);
      }
    } catch (e: any) {
      toast({ title: 'Automation run failed', description: e?.message ?? 'Network error', variant: 'destructive' });
    }
    setRunningAuto(false);
  };

  /** Persist the morning digest recipient + on/off switch. */
  const handleSaveDigest = async () => {
    if (digestEmail.trim() && !isEmail(digestEmail)) {
      toast({ title: 'Enter a valid email address', variant: 'destructive' });
      return;
    }
    setSavingDigest(true);
    const err = await saveDigestSettings({ email: digestEmail, enabled: digestEnabled });
    setSavingDigest(false);
    if (err) toast({ title: 'Could not save digest settings', description: err, variant: 'destructive' });
    else
      toast({
        title: 'Digest settings saved',
        description: digestEnabled && digestEmail.trim()
          ? `The morning digest will go to ${digestEmail.trim()} every day at 9am.`
          : 'The daily digest is currently off.',
      });
  };

  /** Send today's digest immediately (also saves the recipient first). */
  const handleSendDigestNow = async () => {
    if (!isEmail(digestEmail)) {
      toast({ title: 'Enter a recipient email first', variant: 'destructive' });
      return;
    }
    setSendingDigest(true);
    await saveDigestSettings({ email: digestEmail, enabled: digestEnabled });
    try {
      const { data, error } = await supabase.functions.invoke('auto-comms', {
        body: { task: 'digest', force: true },
      });
      if (error || !data?.ok) {
        toast({ title: 'Digest send failed', description: error?.message ?? data?.error ?? 'Unknown error', variant: 'destructive' });
      } else if (String(data.digest ?? '').startsWith('sent')) {
        toast({ title: 'Digest sent', description: `Today's briefing is on its way to ${digestEmail.trim()}.` });
      } else {
        toast({ title: 'Digest not sent', description: String(data.digest ?? 'Unknown result'), variant: 'destructive' });
      }
    } catch (e: any) {
      toast({ title: 'Digest send failed', description: e?.message ?? 'Network error', variant: 'destructive' });
    }
    setSendingDigest(false);
  };


  const templateChips: { key: 'confirm' | 'reschedule' | 'payment' | 'chase' | 'reminder'; label: string; icon: typeof CalendarCheck }[] = [
    { key: 'confirm', label: 'Confirm appointment', icon: CalendarCheck },
    { key: 'reschedule', label: 'Reschedule notice', icon: BellRing },
    { key: 'payment', label: 'Payment link', icon: Link2 },
    { key: 'chase', label: 'Overdue chase', icon: AlertCircle },
    { key: 'reminder', label: 'Visit reminder', icon: Sparkles },
  ];

  return (
    <div>
      <PageHeader
        title="Communications"
        subtitle={`Two-way texting and email ┬╖ ${pendingConfirmations.length} appointment${pendingConfirmations.length === 1 ? '' : 's'} awaiting confirmation`}
      />

      {/* Auto-pilot strip */}
      <div className="mb-6 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-stone-200 bg-gradient-to-r from-stone-900 to-stone-800 px-5 py-4 text-white shadow-sm">
        <div className="flex items-start gap-3">
          <Zap className="mt-0.5 h-5 w-5 flex-shrink-0 text-amber-400" />
          <div>
            <p className="text-sm font-semibold">Auto-pilot is on ΓÇö runs every morning at 9am</p>
            <p className="text-xs text-stone-400">
              Visit reminders 24h before ┬╖ overdue balances chased every 4 days (max 4) ┬╖ wedding photo email 2 months after the big day ┬╖ morning digest to staff ┬╖ bride replies flow back in below
            </p>
          </div>
        </div>
        <button
          data-tour-id="btn-run-automations"
          onClick={handleRunAutomations}
          disabled={runningAuto}
          className="inline-flex items-center gap-2 rounded-lg bg-status-warning px-4 py-2 text-xs font-semibold text-stone-900 transition-colors hover:bg-amber-400 disabled:opacity-60"
        >
          {runningAuto ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Zap className="h-3.5 w-3.5" />}
          Run now
        </button>
      </div>


      {/* Daily digest settings */}
      <div className="mb-6 rounded-2xl border border-stone-200 bg-white p-4 shadow-sm">
        <div className="flex flex-wrap items-end gap-3">
          <div className="flex items-start gap-3">
            <div className="mt-0.5 rounded-xl bg-status-warning/10 p-2 text-status-warning">
              <Sunrise className="h-4 w-4" />
            </div>
            <div>
              <p className="text-sm font-semibold text-stone-800">Morning digest email</p>
              <p className="max-w-md text-xs text-stone-500">
                One email every morning at 9am: today's appointments, overdue balances, gowns awaiting pickup, unsigned contracts, and every bride text from the last 24 hours.
              </p>
            </div>
          </div>
          <div className="ml-auto flex flex-wrap items-center gap-2">
            <input
              type="email"
              value={digestEmail}
              onChange={(e) => setDigestEmail(e.target.value)}
              placeholder="owner@idobridalcouture.com"
              className={`${inputCls} w-64`}
            />
            <label data-tour-id="label-daily-digest" className="inline-flex cursor-pointer items-center gap-2 rounded-lg border border-stone-200 px-3 py-2 text-xs font-medium text-stone-600">
              <input
                type="checkbox"
                checked={digestEnabled}
                onChange={(e) => setDigestEnabled(e.target.checked)}
                className="h-4 w-4 rounded border-stone-300 text-brand-primary focus:ring-rose-300"
              />
              Send daily
            </label>
            <button
              data-tour-id="btn-save-digest"
              onClick={handleSaveDigest}
              disabled={savingDigest}
              className="inline-flex items-center gap-1.5 rounded-lg bg-stone-900 px-3.5 py-2 text-xs font-semibold text-white transition-colors hover:bg-stone-700 disabled:opacity-60"
            >
              {savingDigest ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <CheckCircle2 className="h-3.5 w-3.5" />}
              Save
            </button>
            <button
              onClick={handleSendDigestNow}
              disabled={sendingDigest}
              className="inline-flex items-center gap-1.5 rounded-lg border border-amber-300 bg-status-warning/10 px-3.5 py-2 text-xs font-semibold text-status-warning transition-colors hover:bg-amber-100 disabled:opacity-60"
            >
              {sendingDigest ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Send className="h-3.5 w-3.5" />}
              Send now
            </button>
          </div>
        </div>
      </div>


      {/* Pending confirmations strip */}
      {pendingConfirmations.length > 0 && (
        <div className="mb-6 rounded-2xl border border-status-warning/20 bg-status-warning/10/60 p-4">
          <p className="mb-3 flex items-center gap-2 text-xs font-semibold uppercase tracking-wider text-status-warning">
            <BellRing className="h-4 w-4" /> Awaiting confirmation ΓÇö one click sends the confirmation and updates the calendar
          </p>
          <div className="flex flex-wrap gap-2">
            {pendingConfirmations.map((a) => (
              <div key={a.id} className="flex items-center gap-3 rounded-xl border border-status-warning/20 bg-white px-3 py-2 shadow-sm">
                <div>
                  <p className="text-sm font-medium text-stone-800">{a.customer}</p>
                  <p className="text-[11px] text-stone-500">
                    {a.type} ┬╖ {formatDate(a.date)} at {a.time} ┬╖ {locationById(a.location).short}
                  </p>
                </div>
                <button
                  onClick={() => handleConfirmAppointment(a.id)}
                  disabled={confirmingId === a.id}
                  className="inline-flex items-center gap-1.5 rounded-lg bg-emerald-600 px-3 py-1.5 text-xs font-semibold text-white transition-colors hover:bg-emerald-700 disabled:opacity-60"
                >
                  {confirmingId === a.id ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <CheckCircle2 className="h-3.5 w-3.5" />}
                  Confirm &amp; notify
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
        {/* Contact list */}
        <div className="rounded-2xl border border-stone-200/80 bg-white shadow-sm lg:col-span-1">
          <div className="border-b border-stone-100 p-4">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-stone-400" />
              <input
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Search brides..."
                className={`${inputCls} pl-9`}
              />
            </div>
          </div>
          <div className="max-h-[520px] divide-y divide-stone-100 overflow-y-auto">
            {contacts.map((b) => (
              <button
                key={b.id}
                onClick={() => setSelectedId(b.id)}
                className={`flex w-full items-center gap-3 px-4 py-3 text-left transition-colors ${
                  selectedId === b.id ? 'bg-brand-soft/70' : 'hover:bg-stone-50'
                }`}
              >
                <BridalIdentity customer={b} size="sm" />
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-medium text-stone-800">{b.name}</p>
                  <p className="truncate text-[11px] text-stone-400">
                    {isPhone(b.phone) ? b.phone : 'no phone'} ┬╖ {isEmail(b.email) ? b.email : 'no email'}
                  </p>
                </div>
              </button>
            ))}
            {contacts.length === 0 && (
              <p className="px-4 py-10 text-center text-sm text-stone-400">No brides match your search.</p>
            )}
          </div>
        </div>

        {/* Conversation + composer + checklist */}
        <div className="space-y-6 lg:col-span-2">
          <div className="flex flex-col rounded-2xl border border-stone-200/80 bg-white shadow-sm">
            {selected ? (
              <>
                <div className="flex flex-wrap items-center justify-between gap-2 border-b border-stone-100 px-5 py-4">
                  <div>
                    <p className="font-serif text-lg text-stone-900">{selected.name}</p>
                    <p className="text-xs text-stone-500">
                      {locationById(selected.location).short} ┬╖ Wedding {formatDate(selected.weddingDate)}
                      {openInvoiceFor(selected.name) &&
                        ` ┬╖ Balance ${formatCents(openInvoiceFor(selected.name)!.amountCents - openInvoiceFor(selected.name)!.paidCents)}`}
                    </p>
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => loadThread(selected.name)}
                      title="Refresh conversation"
                      className="rounded-lg border border-stone-200 p-2 text-stone-500 transition-colors hover:border-rose-300 hover:text-brand-primary"
                    >
                      <RefreshCw className={`h-3.5 w-3.5 ${threadLoading ? 'animate-spin' : ''}`} />
                    </button>
                    <div className="flex rounded-lg border border-stone-200 p-0.5 bg-stone-50/50">
                      {(['ig', 'fb', 'chat', 'sms', 'email'] as MessageChannel[]).map((c) => (
                        <button
                          key={c}
                          onClick={() => setChannel(c)}
                          className={`inline-flex items-center gap-1.5 rounded-md px-3 py-1.5 text-xs font-semibold transition-all ${
                            channel === c ? 'bg-white text-stone-900 shadow-sm ring-1 ring-black/5' : 'text-stone-500 hover:text-stone-800'
                          }`}
                        >
                          {c === 'ig' && <Instagram className="h-3.5 w-3.5 text-pink-500" />}
                          {c === 'fb' && <Facebook className="h-3.5 w-3.5 text-status-info" />}
                          {c === 'chat' && <MessageCircle className="h-3.5 w-3.5 text-indigo-500" />}
                          {c === 'sms' && <MessageSquare className="h-3.5 w-3.5" />}
                          {c === 'email' && <Mail className="h-3.5 w-3.5" />}
                          {c === 'ig' ? 'Instagram' : c === 'fb' ? 'Messenger' : c === 'chat' ? 'Live Chat' : c === 'sms' ? 'Text' : 'Email'}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>

                {/* Thread ΓÇö outbound right, inbound bride replies left */}
                <div className="max-h-[300px] flex-1 space-y-3 overflow-y-auto px-5 py-4 bg-stone-50/30">
                  {threadLoading && (
                    <div className="py-8 text-center">
                      <Loader2 className="mx-auto h-5 w-5 animate-spin text-brand-primary" />
                    </div>
                  )}
                  {!threadLoading && thread.length === 0 && (
                    <BeautifulEmptyState
                      icon={<MessageSquare className="h-8 w-8" />}
                      title="No Messages"
                      description="No messages yet - start the conversation below. Bride replies appear here automatically."
                      colorHint="rose"
                    />
                  )}
                  {!threadLoading &&
                    [...thread].reverse().map((m) =>
                      m.direction === 'inbound' ? (
                        <div key={m.id} className="flex justify-start">
                          <div className={`max-w-[85%] rounded-2xl rounded-bl-sm px-4 py-2.5 text-sm shadow-sm ring-1 ring-inset ${m.sentiment === 'anxious' || m.sentiment === 'frustrated' ? 'bg-red-50 text-red-900 ring-red-200' : 'bg-white text-stone-800 ring-stone-200'}`}>
                            {m.sentiment === 'anxious' && <span className="inline-flex items-center gap-1 text-[10px] font-bold text-red-600 mb-1 uppercase tracking-wider"><AlertCircle className="h-3 w-3" /> Anxious</span>}
                            {m.sentiment === 'frustrated' && <span className="inline-flex items-center gap-1 text-[10px] font-bold text-red-600 mb-1 uppercase tracking-wider"><AlertCircle className="h-3 w-3" /> Frustrated</span>}
                            <p className="whitespace-pre-wrap leading-relaxed">{m.body}</p>
                            <p className="mt-1.5 flex items-center gap-1 text-[10px] text-stone-400">
                              {m.channel === 'ig' ? <Instagram className="h-3 w-3 text-pink-500" /> : m.channel === 'fb' ? <Facebook className="h-3 w-3 text-status-info" /> : m.channel === 'chat' ? <MessageCircle className="h-3 w-3 text-indigo-500" /> : <ArrowDownLeft className="h-3 w-3 text-status-success" />}
                              Reply ┬╖ {m.toAddress} ┬╖{' '}
                              {new Date(m.createdAt).toLocaleString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })}
                            </p>
                          </div>
                        </div>
                      ) : (
                        <div key={m.id} className="flex justify-end">
                          <div
                            className={`max-w-[85%] rounded-2xl rounded-br-sm px-4 py-2.5 text-sm shadow-sm ${
                              m.status === 'sent' ? 'bg-stone-900 text-white' : 'bg-brand-soft text-brand-secondary ring-1 ring-inset ring-focus-ring'
                            }`}
                          >
                            {m.subject && <p className="mb-0.5 text-xs font-semibold opacity-80">{m.subject}</p>}
                            <p className="whitespace-pre-wrap leading-relaxed">{m.body}</p>
                            <p className={`mt-1.5 flex items-center gap-1 text-[10px] ${m.status === 'sent' ? 'text-stone-400' : 'text-brand-primary'}`}>
                              {m.status === 'sent' ? <CheckCircle2 className="h-3 w-3" /> : <AlertCircle className="h-3 w-3" />}
                              {m.channel === 'ig' ? 'Instagram' : m.channel === 'fb' ? 'Messenger' : m.channel === 'chat' ? 'Live Chat' : m.channel === 'sms' ? 'Text' : 'Email'}
                              {m.kind !== 'general' && ` ┬╖ ${KIND_LABELS[m.kind] ?? m.kind}`} ┬╖ {m.toAddress} ┬╖{' '}
                              {new Date(m.createdAt).toLocaleString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })}
                              {m.status === 'failed' && ' ┬╖ failed'}
                            </p>
                          </div>
                        </div>
                      ),
                    )}
                </div>

                {/* Composer */}
                <div className="border-t border-stone-100 p-4">
                  <div className="mb-3 flex flex-wrap items-center gap-2">
                    <button
                      data-tour-id="btn-magic-reply"
                      onClick={handleMagicReply}
                      disabled={generatingAi}
                      className="inline-flex items-center gap-1.5 rounded-full border border-indigo-200 bg-indigo-50 px-3 py-1.5 text-xs font-semibold text-indigo-700 transition-colors hover:bg-indigo-100 disabled:opacity-50"
                    >
                      {generatingAi ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Wand2 className="h-3.5 w-3.5" />}
                      Magic AI Reply
                    </button>
                    <div className="h-4 w-px bg-stone-200 mx-1"></div>
                    {templateChips.map(({ key, label, icon: Icon }) => (
                      <button
                        key={key}
                        data-tour-id={`template-chip-${key}`}
                        onClick={() => applyTemplate(key)}
                        className="inline-flex items-center gap-1.5 rounded-full border border-stone-200 bg-stone-50 px-3 py-1.5 text-xs font-medium text-stone-600 transition-colors hover:border-rose-300 hover:bg-brand-soft hover:text-brand-primary"
                      >
                        <Icon className="h-3.5 w-3.5" /> {label}
                      </button>
                    ))}
                    {kind !== 'general' && (
                      <span className="ml-auto inline-flex items-center gap-1.5 rounded-full bg-stone-900 px-3 py-1.5 text-xs font-semibold text-white">
                        {KIND_LABELS[kind]}
                        <button onClick={() => setKind('general')} className="text-stone-400 hover:text-white">
                          <X className="h-3 w-3" />
                        </button>
                      </span>
                    )}
                  </div>
                  {channel === 'email' && (
                    <input
                      value={subject}
                      onChange={(e) => setSubject(e.target.value)}
                      placeholder="Subject"
                      className={`${inputCls} mb-2`}
                    />
                  )}
                  <div className="flex items-end gap-2">
                    <textarea
                      value={body}
                      onChange={(e) => setBody(e.target.value)}
                      rows={3}
                      placeholder={
                        channel === 'sms'
                          ? `Text ${selected.name.split(' ')[0]} at ${isPhone(selected.phone) ? selected.phone : '(no phone on file)'}...`
                          : `Email ${selected.name.split(' ')[0]} at ${isEmail(selected.email) ? selected.email : '(no email on file)'}...`
                      }
                      className={`${inputCls} resize-none`}
                    />
                    <button
                      data-tour-id="btn-new-message"
                      onClick={handleSend}
                      disabled={sending || !body.trim()}
                      className="inline-flex h-10 items-center gap-2 rounded-lg bg-brand-primary px-4 text-sm font-medium text-white shadow-sm transition-colors hover:bg-brand-primary-hover disabled:opacity-50"
                    >
                      {sending ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
                      Send
                    </button>
                  </div>
                  <p className="mt-2 text-[11px] text-stone-400">
                    Two-way texting is live ΓÇö replies land in this thread within seconds. Point your Twilio number's inbound webhook at the sms-inbound function to activate.
                  </p>
                </div>
              </>
            ) : (
              <div className="flex flex-1 flex-col items-center justify-center px-6 py-20 text-center">
                <MessageSquare className="h-8 w-8 text-stone-300" />
                <p className="mt-3 text-sm text-stone-400">Select a bride to view her conversation.</p>
              </div>
            )}
          </div>

          {/* Post-visit checklist */}
          {selected && (
            <BrideChecklist
              bride={selected}
              thread={thread}
              appointments={allAppointments}
              invoices={allInvoices}
              onDraft={handleChecklistDraft}
            />
          )}
        </div>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState, type CSSProperties } from 'react';
import { AlertTriangle, CalendarCog, ChevronLeft, ChevronRight, Mail, Plus, Users2 } from 'lucide-react';
import { Appointment, teamMembers, locationById } from '@/data/vowosData';
import { useVowosData } from '@/contexts/VowosDataContext';
import { useAuth } from '@/contexts/AuthContext';
import { supabase } from '@/lib/supabase';
import {
  ScheduleData,
  dutyFor,
  apptOutsideShift,
  shiftShortLabel,
  minutesToLabel,
  fetchSchedules,
} from '@/lib/schedules';
import ScheduleModal from './ScheduleModal';
import EmailScheduleModal from './EmailScheduleModal';
import { BeautifulEmptyState } from './ui';

const TYPE_DOT: Record<string, string> = {
  'Bridal Consultation': 'bg-brand-primary',
  Fitting: 'bg-violet-400',
  Alterations: 'bg-amber-400',
  Pickup: 'bg-emerald-400',
  Accessories: 'bg-sky-400',
};

/** Diagonal-stripe shading for cells where the stylist is off. */
const OFF_STRIPES: CSSProperties = {
  backgroundImage:
    'repeating-linear-gradient(135deg, rgba(120,113,108,0.08) 0px, rgba(120,113,108,0.08) 6px, transparent 6px, transparent 12px)',
};

const isoDate = (d: Date) => {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
};

/** Sunday that starts the week containing `d`. */
function weekStartOf(d: Date): Date {
  const copy = new Date(d.getFullYear(), d.getMonth(), d.getDate());
  copy.setDate(copy.getDate() - copy.getDay());
  return copy;
}

interface StaffMember {
  name: string;
  role: string;
}

export default function CoverageCalendar({
  onBook,
  onEdit,
}: {
  /** Book a bride into a specific day (and optionally a specific stylist). */
  onBook: (defaults: { date: string; stylist?: string }) => void;
  /** Open an existing appointment for editing/rescheduling. */
  onEdit: (appt: Appointment) => void;
}) {
  const { appointments } = useVowosData();
  const { profile } = useAuth();
  const canManageSchedules = profile?.role === 'Owner' || profile?.role === 'Manager';
  const [weekStart, setWeekStart] = useState<Date>(() => weekStartOf(new Date()));
  const [staff, setStaff] = useState<StaffMember[]>([]);
  const [schedules, setSchedules] = useState<ScheduleData>({ shifts: [], timeOff: [] });
  const [scheduleOpen, setScheduleOpen] = useState(false);
  const [emailOpen, setEmailOpen] = useState(false);

  // Pull every employee account so the manager sees the whole team on one calendar,
  // even employees with zero appointments (coverage gaps are the whole point).
  useEffect(() => {
    (async () => {
      const { data } = await supabase.from('staff_profiles').select('name, role').order('created_at', { ascending: true });
      if (data) setStaff(data.map((r: any) => ({ name: r.name, role: r.role ?? 'Stylist' })));
    })();
  }, []);

  const reloadSchedules = useCallback(async () => {
    setSchedules(await fetchSchedules());
  }, []);

  useEffect(() => {
    reloadSchedules();
  }, [reloadSchedules]);

  const days = useMemo(
    () =>
      Array.from({ length: 7 }, (_, i) => {
        const d = new Date(weekStart);
        d.setDate(d.getDate() + i);
        return d;
      }),
    [weekStart],
  );
  const dayKeys = days.map(isoDate);
  const todayKey = isoDate(new Date());

  const weekAppts = useMemo(
    () => appointments.filter((a) => dayKeys.includes(a.date) && a.status !== 'Cancelled'),
    [appointments, dayKeys.join(',')], // eslint-disable-line react-hooks/exhaustive-deps
  );

  // Roster = every employee account + booking-form stylists + anyone already holding
  // an appointment this week (so nothing ever falls off the grid).
  const roster = useMemo(() => {
    const names: { name: string; role: string }[] = [];
    const seen = new Set<string>();
    const push = (name: string, role: string) => {
      const key = name.trim();
      if (!key || seen.has(key)) return;
      seen.add(key);
      names.push({ name: key, role });
    };
    staff.forEach((s) => push(s.name, s.role));
    teamMembers.forEach((m) => push(m, 'Stylist'));
    weekAppts.forEach((a) => push(a.stylist, 'Stylist'));
    return names;
  }, [staff, weekAppts]);

  /** Appointments for one stylist on one day, in booked order. */
  const cellAppts = (stylist: string, day: string) =>
    weekAppts.filter((a) => a.stylist === stylist && a.date === day);

  /** True when a stylist holds 2+ active appointments at the same time that day. */
  const hasDoubleBooking = (list: Appointment[]) => {
    const times = new Map<string, number>();
    list.forEach((a) => {
      if (a.status === 'Completed') return;
      times.set(a.time, (times.get(a.time) ?? 0) + 1);
    });
    return [...times.values()].some((n) => n > 1);
  };

  const shiftWeek = (delta: number) => {
    const d = new Date(weekStart);
    d.setDate(d.getDate() + delta * 7);
    setWeekStart(d);
  };

  const weekLabel = `${days[0].toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} ΓÇô ${days[6].toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}`;

  const totalWeek = weekAppts.length;
  const coveredStylists = new Set(weekAppts.map((a) => a.stylist)).size;

  /** How many team members are on duty (working a shift) on a given day. */
  const onDutyCount = (day: string) =>
    roster.filter((m) => dutyFor(schedules, m.name, day).status === 'on').length;

  /** Count of this week's appointments that fall outside the assigned stylist's shift. */
  const outsideShiftCount = useMemo(
    () =>
      weekAppts.filter(
        (a) => a.status !== 'Completed' && apptOutsideShift(dutyFor(schedules, a.stylist, a.date), a.time),
      ).length,
    [weekAppts, schedules],
  );

  return (
    <div className="overflow-hidden rounded-2xl border border-stone-200/80 bg-white shadow-sm">
      {/* Week navigation */}
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-stone-100 px-5 py-4">
        <div className="flex items-center gap-2">
          <button
            onClick={() => shiftWeek(-1)}
            className="rounded-lg border border-stone-200 p-1.5 text-stone-500 transition-colors hover:bg-stone-50"
            aria-label="Previous week"
          >
            <ChevronLeft className="h-4 w-4" />
          </button>
          <button
            onClick={() => setWeekStart(weekStartOf(new Date()))}
            className="rounded-lg border border-stone-200 px-3 py-1.5 text-xs font-medium text-stone-600 transition-colors hover:bg-stone-50"
          >
            Today
          </button>
          <button
            onClick={() => shiftWeek(1)}
            className="rounded-lg border border-stone-200 p-1.5 text-stone-500 transition-colors hover:bg-stone-50"
            aria-label="Next week"
          >
            <ChevronRight className="h-4 w-4" />
          </button>
          <h2 className="ml-2 font-serif text-lg text-stone-900">{weekLabel}</h2>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <p className="flex items-center gap-1.5 text-xs text-stone-500">
            <Users2 className="h-3.5 w-3.5 text-stone-400" />
            {totalWeek} appointment{totalWeek === 1 ? '' : 's'} ┬╖ {coveredStylists} of {roster.length} team members covering
          </p>
          {outsideShiftCount > 0 && (
            <p className="flex items-center gap-1 rounded-full bg-status-warning/10 px-2.5 py-1 text-[11px] font-semibold text-status-warning ring-1 ring-amber-200">
              <AlertTriangle className="h-3 w-3" /> {outsideShiftCount} outside shift
            </p>
          )}
          {canManageSchedules && (
            <>
              <button
                onClick={() => setScheduleOpen(true)}
                className="inline-flex items-center gap-1.5 rounded-lg border border-stone-200 px-3 py-1.5 text-xs font-medium text-stone-600 transition-colors hover:bg-stone-50"
                title="Set working days, hours, and time off per team member"
              >
                <CalendarCog className="h-3.5 w-3.5" /> Schedules
              </button>
              <button
                onClick={() => setEmailOpen(true)}
                className="inline-flex items-center gap-1.5 rounded-lg border border-stone-200 px-3 py-1.5 text-xs font-medium text-stone-600 transition-colors hover:bg-stone-50"
                title="Email each team member their shifts for this week"
              >
                <Mail className="h-3.5 w-3.5" /> Email Schedule
              </button>
            </>
          )}
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full min-w-[860px] table-fixed border-collapse text-sm">
          <thead>
            <tr className="border-b border-stone-200 bg-stone-50/70">
              <th className="w-40 px-4 py-3 text-left text-[10px] font-semibold uppercase tracking-wider text-stone-500">
                Team member
              </th>
              {days.map((d, i) => {
                const key = dayKeys[i];
                const isToday = key === todayKey;
                const dayCount = weekAppts.filter((a) => a.date === key).length;
                const duty = onDutyCount(key);
                return (
                  <th key={key} className={`px-2 py-2 text-center ${isToday ? 'bg-brand-soft/70' : ''}`}>
                    <button
                      onClick={() => onBook({ date: key })}
                      className="group mx-auto block w-full rounded-lg py-1 transition-colors hover:bg-brand-soft"
                      title={`Book a bride on ${d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}`}
                    >
                      <span className="block text-[10px] font-semibold uppercase tracking-wider text-stone-400">
                        {d.toLocaleDateString('en-US', { weekday: 'short' })}
                      </span>
                      <span
                        className={`mx-auto mt-0.5 flex h-7 w-7 items-center justify-center rounded-full text-sm font-medium ${
                          isToday ? 'bg-brand-primary text-white' : 'text-stone-800 group-hover:bg-brand-soft'
                        }`}
                      >
                        {d.getDate()}
                      </span>
                      <span className="block text-[10px] text-stone-400">
                        {dayCount > 0 ? `${dayCount} appt${dayCount === 1 ? '' : 's'}` : 'ΓÇö'}
                      </span>
                      <span
                        className={`mx-auto mt-0.5 inline-block rounded-full px-1.5 py-px text-[9px] font-semibold ${
                          duty === 0
                            ? 'bg-brand-soft text-brand-primary'
                            : 'bg-status-success/10 text-status-success ring-1 ring-emerald-100'
                        }`}
                        title={`${duty} team member${duty === 1 ? '' : 's'} scheduled to work this day`}
                      >
                        {duty} on duty
                      </span>
                    </button>
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody className="divide-y divide-stone-100">
            {roster.map((member) => {
              const memberWeekCount = weekAppts.filter((a) => a.stylist === member.name).length;
              return (
                <tr key={member.name} className="align-top">
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-2.5">
                      <div className="flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-stone-500 to-stone-700 text-[11px] font-semibold text-white">
                        {member.name.split(' ').map((n) => n[0]).join('').slice(0, 2).toUpperCase()}
                      </div>
                      <div className="min-w-0">
                        <p className="truncate text-xs font-semibold text-stone-800">{member.name}</p>
                        <p className="text-[10px] text-stone-400">
                          {member.role} ┬╖ {memberWeekCount} this week
                        </p>
                      </div>
                    </div>
                  </td>
                  {dayKeys.map((day) => {
                    const list = cellAppts(member.name, day);
                    const doubled = hasDoubleBooking(list);
                    const isToday = day === todayKey;
                    const duty = dutyFor(schedules, member.name, day);
                    const isOff = duty.status !== 'on';
                    const cellTitle =
                      duty.status === 'on'
                        ? `${member.name} works ${minutesToLabel(duty.startMinutes)} ΓÇô ${minutesToLabel(duty.endMinutes)}${duty.scheduled ? '' : ' (default hours ΓÇö no schedule set)'}`
                        : duty.status === 'time_off'
                          ? `${member.name} is off: ${duty.reason}`
                          : `${member.name} does not work this day`;
                    return (
                      <td
                        key={day}
                        className={`group/cell px-1.5 py-2 ${isOff ? 'bg-stone-50' : isToday ? 'bg-brand-soft/40' : ''}`}
                        style={isOff ? OFF_STRIPES : undefined}
                        title={cellTitle}
                      >
                        <div className="min-h-[52px] space-y-1">
                          {isOff && (
                            <p className="rounded-md bg-stone-200/70 px-1.5 py-0.5 text-center text-[9px] font-semibold uppercase tracking-wider text-stone-500">
                              {duty.status === 'time_off' ? duty.reason : 'Off'}
                            </p>
                          )}
                          {!isOff && duty.scheduled && (
                            <p className="text-center text-[9px] font-medium text-stone-300">
                              {shiftShortLabel(duty.startMinutes, duty.endMinutes)}
                            </p>
                          )}
                          {doubled && (
                            <p className="flex items-center gap-1 rounded-md bg-brand-soft px-1.5 py-0.5 text-[9px] font-semibold text-brand-primary-hover">
                              <AlertTriangle className="h-2.5 w-2.5" /> Double-booked
                            </p>
                          )}
                          {list.map((a) => {
                            const outside = a.status !== 'Completed' && apptOutsideShift(duty, a.time);
                            return (
                              <button
                                key={a.id}
                                onClick={() => onEdit(a)}
                                title={`${a.customer} ┬╖ ${a.type} ┬╖ ${a.time} ┬╖ ${locationById(a.location).short}${a.feePaid ? ' ┬╖ fee paid' : ' ┬╖ fee due'}${outside ? ` ┬╖ WARNING: outside ${member.name}'s shift ΓÇö reassign or reschedule` : ''}`}
                                className={`block w-full rounded-lg border px-1.5 py-1 text-left transition-colors ${
                                  a.status === 'Completed'
                                    ? 'border-stone-100 bg-stone-50 opacity-60'
                                    : outside
                                      ? 'border-amber-300 bg-status-warning/10 ring-1 ring-amber-300 hover:bg-amber-100'
                                      : a.status === 'Pending'
                                        ? 'border-status-warning/20 bg-status-warning/10 hover:bg-amber-100'
                                        : 'border-stone-200 bg-white hover:border-border-subtle hover:bg-brand-soft'
                                }`}
                              >
                                <span className="flex items-center gap-1">
                                  <span className={`h-1.5 w-1.5 flex-shrink-0 rounded-full ${TYPE_DOT[a.type] ?? 'bg-stone-300'}`} />
                                  <span className="truncate text-[10px] font-semibold text-stone-800">{a.time}</span>
                                  {outside && (
                                    <AlertTriangle className="h-2.5 w-2.5 flex-shrink-0 text-status-warning" aria-label="Booked outside this stylist's shift" />
                                  )}
                                  {!a.feePaid && a.status !== 'Completed' && (
                                    <span className="ml-auto h-1.5 w-1.5 flex-shrink-0 rounded-full bg-amber-400" title="Booking fee due" />
                                  )}
                                </span>
                                <span className="block truncate text-[10px] text-stone-600">{a.customer}</span>
                                {outside && (
                                  <span className="block truncate text-[9px] font-semibold text-status-warning">
                                    Outside shift
                                  </span>
                                )}
                              </button>
                            );
                          })}
                          <button
                            onClick={() => onBook({ date: day, stylist: member.name })}
                            className="flex w-full items-center justify-center gap-1 rounded-lg border border-dashed border-transparent py-1 text-[10px] font-medium text-transparent transition-colors group-hover/cell:border-stone-200 group-hover/cell:text-stone-400 hover:!border-rose-300 hover:bg-brand-soft hover:!text-brand-primary"
                            title={
                              isOff
                                ? `${member.name} is off this day ΓÇö booking here will be flagged`
                                : `Book a bride with ${member.name} on this day`
                            }
                          >
                            <Plus className="h-3 w-3" /> Book
                          </button>
                        </div>
                      </td>
                    );
                  })}
                </tr>
              );
            })}
            {roster.length === 0 && (
              <tr>
                <td colSpan={8} className="p-8">
                  <BeautifulEmptyState
                    icon={<Users2 className="h-8 w-8" />}
                    title="No Team Members"
                    description="No team members yet - staff accounts appear here automatically."
                    colorHint="indigo"
                  />
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Legend */}
      <div className="flex flex-wrap items-center gap-x-4 gap-y-1.5 border-t border-stone-100 px-5 py-3 text-[10px] text-stone-500">
        {Object.entries(TYPE_DOT).map(([type, dot]) => (
          <span key={type} className="inline-flex items-center gap-1">
            <span className={`h-2 w-2 rounded-full ${dot}`} /> {type}
          </span>
        ))}
        <span className="inline-flex items-center gap-1">
          <span className="h-2 w-2 rounded-full bg-amber-400" /> Fee due at check-in
        </span>
        <span className="inline-flex items-center gap-1">
          <span className="inline-block h-2.5 w-2.5 rounded-sm border border-stone-200" style={OFF_STRIPES} /> Off / vacation
        </span>
        <span className="inline-flex items-center gap-1">
          <AlertTriangle className="h-2.5 w-2.5 text-status-warning" /> Booked outside shift
        </span>
        <span className="ml-auto inline-flex items-center gap-1.5">
          Hover a cell to book that stylist ┬╖ click a day number to book that day
        </span>
      </div>

      {/* Owner/Manager: working days, hours & time off */}
      <ScheduleModal
        open={scheduleOpen}
        onClose={() => setScheduleOpen(false)}
        roster={roster}
        data={schedules}
        onChanged={reloadSchedules}
      />

      {/* Owner/Manager: email the visible week's shifts to the team */}
      <EmailScheduleModal
        open={emailOpen}
        onClose={() => setEmailOpen(false)}
        roster={roster}
        weekDays={dayKeys}
        weekLabel={weekLabel}
        schedules={schedules}
      />

    </div>
  );
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { Download, Loader2, LogOut, Trash2, AlertTriangle } from 'lucide-react';
import { teamMembers } from '@/data/vowosData';
import { supabase } from '@/lib/supabase';
import { toast } from '@vowos/design-system';
import { ScheduleData, fetchSchedules } from '@/lib/schedules';
import {
  TimeEntry,
  fetchTimeEntries,
  fetchOpenEntries,
  clockOut,
  deleteTimeEntry,
  entryHours,
  fmtHours,
  localIsoDate,
  scheduledHoursForRange,
  SUSPICIOUS_SHIFT_HOURS,
} from '@/lib/timeclock';
import { btnSecondary } from './ui';

function downloadCsv(filename: string, rows: (string | number)[][]) {
  const csv = rows.map((r) => r.map((c) => `"${String(c).replace(/"/g, '""')}"`).join(',')).join('\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

/** Sunday-start week containing today. */
function thisWeek(): [string, string] {
  const now = new Date();
  const start = new Date(now.getFullYear(), now.getMonth(), now.getDate() - now.getDay());
  const end = new Date(start);
  end.setDate(end.getDate() + 6);
  return [localIsoDate(start), localIsoDate(end)];
}

const PRESETS: { label: string; range: () => [string, string] }[] = [
  { label: 'This week', range: thisWeek },
  {
    label: 'Last week',
    range: () => {
      const [s] = thisWeek();
      const start = new Date(`${s}T00:00:00`);
      start.setDate(start.getDate() - 7);
      const end = new Date(start);
      end.setDate(end.getDate() + 6);
      return [localIsoDate(start), localIsoDate(end)];
    },
  },
  {
    label: 'This month',
    range: () => {
      const now = new Date();
      return [
        localIsoDate(new Date(now.getFullYear(), now.getMonth(), 1)),
        localIsoDate(new Date(now.getFullYear(), now.getMonth() + 1, 0)),
      ];
    },
  },
  {
    label: 'Last month',
    range: () => {
      const now = new Date();
      return [
        localIsoDate(new Date(now.getFullYear(), now.getMonth() - 1, 1)),
        localIsoDate(new Date(now.getFullYear(), now.getMonth(), 0)),
      ];
    },
  },
  {
    label: 'Last 30 days',
    range: () => {
      const now = new Date();
      const start = new Date(now);
      start.setDate(start.getDate() - 29);
      return [localIsoDate(start), localIsoDate(now)];
    },
  },
];

/**
 * Hours & Time Clock report: scheduled hours (from shift rules minus time off)
 * vs actual punched hours per team member, with punch-level detail and cleanup.
 */
export default function HoursReportTab() {
  const [[from, to], setRange] = useState<[string, string]>(thisWeek);
  const [loading, setLoading] = useState(true);
  const [schedules, setSchedules] = useState<ScheduleData>({ shifts: [], timeOff: [] });
  const [entries, setEntries] = useState<TimeEntry[]>([]);
  const [openEntries, setOpenEntries] = useState<TimeEntry[]>([]);
  const [staffNames, setStaffNames] = useState<string[]>([]);

  const reload = useCallback(async () => {
    setLoading(true);
    const [sched, ents, open, staffRes] = await Promise.all([
      fetchSchedules(),
      fetchTimeEntries(from, to),
      fetchOpenEntries(),
      supabase.from('staff_profiles').select('name').order('created_at', { ascending: true }),
    ]);
    setSchedules(sched);
    setEntries(ents);
    setOpenEntries(open);
    setStaffNames((staffRes.data ?? []).map((r: any) => r.name));
    setLoading(false);
  }, [from, to]);

  useEffect(() => {
    reload();
  }, [reload]);

  const now = new Date();

  // Roster = staff accounts + booking-form stylists + anyone with a punch in range
  const roster = useMemo(() => {
    const seen = new Set<string>();
    const out: string[] = [];
    const push = (n: string) => {
      const k = n.trim();
      if (k && !seen.has(k)) {
        seen.add(k);
        out.push(k);
      }
    };
    staffNames.forEach(push);
    teamMembers.forEach(push);
    entries.forEach((e) => push(e.staffName));
    return out;
  }, [staffNames, entries]);

  const rows = useMemo(
    () =>
      roster.map((name) => {
        const mine = entries.filter((e) => e.staffName === name);
        const worked = mine.reduce((s, e) => s + entryHours(e, now), 0);
        const scheduled = scheduledHoursForRange(schedules, name, from, to);
        const daysWorked = new Set(mine.map((e) => localIsoDate(new Date(e.clockIn)))).size;
        const onClock = openEntries.some((e) => e.staffName === name);
        return { name, scheduled, worked, variance: worked - scheduled, punches: mine.length, daysWorked, onClock };
      }),
    [roster, entries, schedules, openEntries, from, to], // eslint-disable-line react-hooks/exhaustive-deps
  );

  const totalScheduled = rows.reduce((s, r) => s + r.scheduled, 0);
  const totalWorked = rows.reduce((s, r) => s + r.worked, 0);
  const coverage = totalScheduled > 0 ? Math.round((totalWorked / totalScheduled) * 100) : 0;

  const handleForceOut = async (e: TimeEntry) => {
    const err = await clockOut(e.id);
    if (err) toast({ title: 'Could not clock out', description: err, variant: 'destructive' });
    else toast({ title: 'Clocked out', description: `${e.staffName}'s open punch was closed.` });
    reload();
  };

  const handleDelete = async (e: TimeEntry) => {
    const err = await deleteTimeEntry(e.id);
    if (err) toast({ title: 'Could not delete punch', description: err, variant: 'destructive' });
    else toast({ title: 'Punch deleted', description: `${e.staffName} ┬╖ ${new Date(e.clockIn).toLocaleString()}` });
    reload();
  };

  const exportCsv = () =>
    downloadCsv(`hours-${from}-to-${to}.csv`, [
      ['Team Member', 'Scheduled Hours', 'Worked Hours', 'Variance', 'Punches', 'Days Worked'],
      ...rows.map((r) => [
        r.name,
        r.scheduled.toFixed(2),
        r.worked.toFixed(2),
        r.variance.toFixed(2),
        r.punches,
        r.daysWorked,
      ]),
    ]);

  const fmtStamp = (iso: string) =>
    new Date(iso).toLocaleString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });

  return (
    <div className="space-y-6">
      {/* Range controls */}
      <div className="flex flex-wrap items-end gap-3 rounded-2xl border border-stone-200/80 bg-white p-4 shadow-sm">
        <div>
          <label className="mb-1 block text-[10px] font-semibold uppercase tracking-wider text-stone-500">From</label>
          <input
            type="date"
            value={from}
            max={to}
            onChange={(e) => e.target.value && setRange([e.target.value, to])}
            className="rounded-lg border border-stone-200 px-3 py-2 text-sm text-stone-800 focus:border-rose-300 focus:outline-none focus:ring-2 focus:ring-focus-ring"
          />
        </div>
        <div>
          <label className="mb-1 block text-[10px] font-semibold uppercase tracking-wider text-stone-500">To</label>
          <input
            type="date"
            value={to}
            min={from}
            onChange={(e) => e.target.value && setRange([from, e.target.value])}
            className="rounded-lg border border-stone-200 px-3 py-2 text-sm text-stone-800 focus:border-rose-300 focus:outline-none focus:ring-2 focus:ring-focus-ring"
          />
        </div>
        <div className="flex flex-wrap gap-1.5">
          {PRESETS.map((p) => (
            <button
              key={p.label}
              onClick={() => setRange(p.range())}
              className="rounded-full border border-stone-200 px-3 py-1.5 text-xs font-medium text-stone-600 transition-colors hover:border-border-subtle hover:bg-brand-soft hover:text-brand-primary"
            >
              {p.label}
            </button>
          ))}
        </div>
        <button onClick={exportCsv} className={`${btnSecondary} ml-auto`}>
          <Download className="h-4 w-4" /> Export CSV
        </button>
      </div>

      {/* KPIs */}
      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        {[
          { label: 'Scheduled hours', value: fmtHours(totalScheduled) },
          { label: 'Worked hours (punched)', value: fmtHours(totalWorked), tone: 'text-emerald-700' },
          {
            label: 'Worked vs scheduled',
            value: totalScheduled > 0 ? `${coverage}%` : 'ΓÇö',
            tone: coverage >= 90 ? 'text-emerald-700' : coverage >= 70 ? 'text-status-warning' : 'text-brand-primary',
          },
          { label: 'On the clock right now', value: String(openEntries.length), tone: openEntries.length > 0 ? 'text-emerald-700' : undefined },
        ].map((s) => (
          <div key={s.label} className="rounded-2xl border border-stone-200/80 bg-white p-5 shadow-sm">
            <p className="text-xs font-medium uppercase tracking-wider text-stone-500">{s.label}</p>
            <p className={`mt-1 font-serif text-2xl ${s.tone ?? 'text-stone-900'}`}>{s.value}</p>
          </div>
        ))}
      </div>

      {loading ? (
        <div className="flex flex-col items-center rounded-2xl border border-stone-200/80 bg-white py-14 shadow-sm">
          <Loader2 className="h-6 w-6 animate-spin text-brand-primary" />
          <p className="mt-3 text-sm text-stone-500">Crunching the hours...</p>
        </div>
      ) : (
        <>
          {/* Per-member summary */}
          <div className="overflow-hidden rounded-2xl border border-stone-200/80 bg-white shadow-sm">
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-stone-100 text-sm">
                <thead className="bg-stone-50/70">
                  <tr>
                    {['Team member', 'Scheduled', 'Worked', 'Variance', 'Punches', 'Days worked', 'Status'].map((h) => (
                      <th key={h} className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wider text-stone-500">
                        {h}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-stone-100">
                  {rows.map((r) => (
                    <tr key={r.name} className="transition-colors hover:bg-brand-soft/40">
                      <td className="px-5 py-3.5 font-medium text-stone-900">{r.name}</td>
                      <td className="px-5 py-3.5 text-stone-700">{r.scheduled > 0 ? fmtHours(r.scheduled) : 'ΓÇö'}</td>
                      <td className="px-5 py-3.5 font-semibold text-stone-900">{r.worked > 0 ? fmtHours(r.worked) : 'ΓÇö'}</td>
                      <td className="px-5 py-3.5">
                        {r.scheduled === 0 && r.worked === 0 ? (
                          <span className="text-stone-400">ΓÇö</span>
                        ) : (
                          <span
                            className={`font-semibold ${
                              r.variance >= 0 ? 'text-emerald-700' : r.variance > -2 ? 'text-status-warning' : 'text-brand-primary'
                            }`}
                          >
                            {r.variance >= 0 ? '+' : 'ΓêÆ'}
                            {fmtHours(Math.abs(r.variance))}
                          </span>
                        )}
                      </td>
                      <td className="px-5 py-3.5 text-stone-700">{r.punches}</td>
                      <td className="px-5 py-3.5 text-stone-700">{r.daysWorked}</td>
                      <td className="px-5 py-3.5">
                        {r.onClock ? (
                          <span className="inline-flex items-center gap-1.5 rounded-full bg-status-success/10 px-2.5 py-0.5 text-[11px] font-semibold text-emerald-700 ring-1 ring-inset ring-emerald-200">
                            <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-status-success" /> On the clock
                          </span>
                        ) : (
                          <span className="text-xs text-stone-400">Off</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
                <tfoot className="bg-stone-50/70">
                  <tr>
                    <td className="px-5 py-3 text-xs font-semibold uppercase tracking-wider text-stone-500">Total</td>
                    <td className="px-5 py-3 font-semibold text-stone-900">{fmtHours(totalScheduled)}</td>
                    <td className="px-5 py-3 font-semibold text-stone-900">{fmtHours(totalWorked)}</td>
                    <td className="px-5 py-3" colSpan={4} />
                  </tr>
                </tfoot>
              </table>
            </div>
          </div>

          {/* Punch detail */}
          <div className="overflow-hidden rounded-2xl border border-stone-200/80 bg-white shadow-sm">
            <div className="border-b border-stone-100 px-5 py-4">
              <h3 className="font-serif text-lg text-stone-900">Punch Detail</h3>
              <p className="text-xs text-stone-500">
                Every clock-in inside the range. Close forgotten punches or delete mistakes ΓÇö the summary updates instantly.
              </p>
            </div>
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-stone-100 text-sm">
                <thead className="bg-stone-50/70">
                  <tr>
                    {['Team member', 'Clock in', 'Clock out', 'Hours', ''].map((h, i) => (
                      <th key={i} className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wider text-stone-500">
                        {h}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-stone-100">
                  {entries.map((e) => {
                    const hrs = entryHours(e, now);
                    const suspicious = hrs > SUSPICIOUS_SHIFT_HOURS;
                    return (
                      <tr key={e.id} className="transition-colors hover:bg-brand-soft/40">
                        <td className="px-5 py-3 font-medium text-stone-900">{e.staffName}</td>
                        <td className="px-5 py-3 text-stone-700">{fmtStamp(e.clockIn)}</td>
                        <td className="px-5 py-3 text-stone-700">
                          {e.clockOut ? (
                            fmtStamp(e.clockOut)
                          ) : (
                            <span className="inline-flex items-center gap-1 rounded-full bg-status-success/10 px-2 py-0.5 text-[11px] font-semibold text-emerald-700 ring-1 ring-inset ring-emerald-200">
                              Still clocked in
                            </span>
                          )}
                        </td>
                        <td className="px-5 py-3">
                          <span className={`font-semibold ${suspicious ? 'text-status-warning' : 'text-stone-900'}`}>
                            {fmtHours(hrs)}
                          </span>
                          {suspicious && (
                            <span className="ml-1.5 inline-flex items-center gap-0.5 text-[10px] font-semibold text-status-warning">
                              <AlertTriangle className="h-3 w-3" /> check
                            </span>
                          )}
                        </td>
                        <td className="px-5 py-3">
                          <div className="flex justify-end gap-1.5">
                            {!e.clockOut && (
                              <button
                                onClick={() => handleForceOut(e)}
                                className="inline-flex items-center gap-1 rounded-lg border border-stone-200 px-2.5 py-1 text-[11px] font-medium text-stone-600 transition-colors hover:bg-stone-50"
                                title="Close this punch now"
                              >
                                <LogOut className="h-3 w-3" /> Clock out
                              </button>
                            )}
                            <button
                              onClick={() => handleDelete(e)}
                              className="rounded-lg p-1.5 text-stone-400 transition-colors hover:bg-brand-soft hover:text-brand-primary"
                              title="Delete this punch"
                              aria-label={`Delete punch for ${e.staffName}`}
                            >
                              <Trash2 className="h-3.5 w-3.5" />
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                  {entries.length === 0 && (
                    <tr>
                      <td colSpan={5} className="px-5 py-10 text-center text-stone-500">
                        No punches in this range yet ΓÇö the team clocks in from the Appointments page.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>

          <p className="text-xs text-stone-400">
            Scheduled hours come from each member's weekly shift pattern minus approved time off (set from the
            calendar's Schedules button). Members without a saved schedule count default salon hours on every day.
          </p>
        </>
      )}
    </div>
  );
}

import { useState } from 'react';
import { Lead, LeadStage, formatCents, formatDate, teamMembers } from '@/data/vowosData';
import { useVowosData } from '@/contexts/VowosDataContext';
import { Modal, StatusBadge } from './ui';
import { Sparkles, Calendar, DollarSign, UserCheck, Mail, Phone, MessageSquare, ArrowRight, CheckCircle2, CalendarPlus, UserPlus, Tag, Clock } from 'lucide-react';
import { toast } from '@vowos/design-system';

interface Lead360ModalProps {
  lead: Lead | null;
  onClose: () => void;
  onNavigateToBride?: (brideId: string) => void;
  onBookAppointment?: (leadName: string, leadEmail: string) => void;
}

const STAGES: LeadStage[] = ['New', 'Contacted', 'Appointment Set', 'Won'];

export default function Lead360Modal({
  lead,
  onClose,
  onNavigateToBride,
  onBookAppointment,
}: Lead360ModalProps) {
  const { advanceLead, updateLeadStage, addBride } = useVowosData();
  const [notes, setNotes] = useState(`Interested in bridal gowns & veil styling. Preferred budget: ${formatCents(lead?.budgetCents || 0)}.`);
  const [assignedStylist, setAssignedStylist] = useState(teamMembers[0]);
  const [phoneInput, setPhoneInput] = useState('(225) 555-0199');
  const [converting, setConverting] = useState(false);

  if (!lead) return null;

  const handleStageChange = async (newStage: LeadStage) => {
    await updateLeadStage(lead.id, newStage);
    toast({ title: 'Pipeline Stage Updated', description: `${lead.name} moved to ${newStage}` });
  };

  const handleConvertLeadToBride = async () => {
    setConverting(true);
    try {
      const newBride = await addBride({
        name: lead.name,
        email: lead.email,
        phone: phoneInput,
        weddingDate: lead.weddingDate,
        stylist: assignedStylist,
        status: 'Active',
      });
      await updateLeadStage(lead.id, 'Won');
      toast({ title: 'Lead Converted to Bride!', description: `${lead.name} enrolled in Bride 360 pipeline.` });
