import { useState } from 'react';
import { ArrowRight, Sparkles, Loader2, ChevronRight, UserPlus, Phone, Mail, Plus, Layers, Inbox, Clock, CalendarCheck, Globe, PieChart, BarChart3, Zap, Settings, AlertTriangle, Tag } from 'lucide-react';
import { LEAD_STAGES, LeadStage, Lead, formatCents, formatDate } from '@/data/vowosData';
import { useVowosData } from '@/contexts/VowosDataContext';
import { PageHeader, btnPrimary, btnSecondary, BeautifulEmptyState } from './ui';
import Lead360Modal from './Lead360Modal';
import BookAppointmentModal from './BookAppointmentModal';
import LeadGeneratorWizard from './lead-generator/LeadGeneratorWizard';
import LeadInboxView from './leads/LeadInboxView';
import LeadFollowUpView from './leads/LeadFollowUpView';
import LeadAttributionView from './leads/LeadAttributionView';
import LeadReportsView from './leads/LeadReportsView';
import { leadService, UnifiedLeadRecord } from '@/lib/services/leadIntelligenceService';

export type LeadsSubTab =
  | 'pipeline'
  | 'generator'
  | 'inbox'
  | 'assignments'
  | 'followup'
  | 'appointments'
  | 'sources'
  | 'attribution'
  | 'reports'
  | 'automations'
  | 'settings';

const STAGE_STYLES: Record<string, { dot: string; header: string }> = {
  New: { dot: 'bg-sky-400', header: 'text-sky-700' },
  'Contact Attempted': { dot: 'bg-amber-400', header: 'text-status-warning' },
  Contacted: { dot: 'bg-indigo-400', header: 'text-indigo-700' },
  'Appointment Requested': { dot: 'bg-purple-400', header: 'text-purple-700' },
  'Appointment Set': { dot: 'bg-violet-400', header: 'text-violet-700' },
  Confirmed: { dot: 'bg-teal-400', header: 'text-teal-700' },
  Completed: { dot: 'bg-blue-400', header: 'text-blue-700' },
  Won: { dot: 'bg-emerald-400', header: 'text-emerald-700' },
  Lost: { dot: 'bg-brand-primary', header: 'text-brand-primary-hover' },
  Nurture: { dot: 'bg-stone-400', header: 'text-stone-700' },
};

export default function LeadsView({ onNavigate }: { onNavigate?: (view: string, id?: string) => void }) {
  const { leads: list, loading, advanceLead } = useVowosData();
  const [unifiedLeads, setUnifiedLeads] = useState<UnifiedLeadRecord[]>(leadService.getLeads());
  const [activeTab, setActiveTab] = useState<LeadsSubTab>('pipeline');
  const [selectedLead, setSelectedLead] = useState<Lead | null>(null);
  const [bookLead, setBookLead] = useState<{ name: string; email: string } | null>(null);
  const [cardMode, setCardMode] = useState<'compact' | 'expanded'>('expanded');

  const pipelineValue = list.filter((l) => l.stage !== 'Won').reduce((s, l) => s + l.budgetCents, 0);

  const SUB_TABS: { id: LeadsSubTab; label: string; icon: any }[] = [
    { id: 'pipeline', label: 'Pipeline Board', icon: Layers },
    { id: 'generator', label: 'Lead Generator', icon: Plus },
    { id: 'inbox', label: 'Lead Inbox', icon: Inbox },
    { id: 'followup', label: 'Follow-Up & SLAs', icon: Clock },
    { id: 'attribution', label: 'Attribution Matrix', icon: PieChart },
    { id: 'reports', label: 'Lead Reports', icon: BarChart3 },
    { id: 'automations', label: 'Automations', icon: Zap },
    { id: 'settings', label: 'Routing Settings', icon: Settings },
  ];

  return (
    <div className="space-y-6 select-none">
      {/* Page Header */}
      <PageHeader
        title="Daily Sales Execution Center (Leads)"
        subtitle={`${list.length} active leads ┬╖ ${formatCents(pipelineValue)} open pipeline value ┬╖ DEMO ΓÇö SIMULATED LEADS AND MARKETING DATA`}
        action={
          <button data-tour-id="btn-add-lead" onClick={() => setActiveTab('generator')} className={btnPrimary}>
            <Plus className="h-4 w-4" /> Lead Generator Wizard
          </button>
        }
      />

      {/* Internal Sub-Tab Navigation Bar */}
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-stone-200/80 pb-3">
        <div className="flex flex-wrap items-center gap-1.5">
          {SUB_TABS.map((tab) => {
            const Icon = tab.icon;
            const active = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center gap-1.5 rounded-xl px-3 py-2 text-xs font-semibold transition-all ${
                  active
                    ? 'bg-brand-primary text-white shadow-xs'
                    : 'bg-white text-stone-600 border border-stone-200 hover:border-stone-300 hover:bg-stone-50'
                }`}
              >
                <Icon className="h-3.5 w-3.5" />
                <span>{tab.label}</span>
              </button>
            );
          })}
        </div>

        {activeTab === 'pipeline' && (
          <button
            onClick={() => setCardMode((m) => (m === 'expanded' ? 'compact' : 'expanded'))}
            className={btnSecondary + ' text-xs'}
          >
            Mode: {cardMode === 'expanded' ? 'Expanded Detail' : 'Compact Cards'}
          </button>
        )}
      </div>

      {/* ΓöÇΓöÇ TAB 1: PIPELINE BOARD ΓöÇΓöÇ */}
      {activeTab === 'pipeline' && (
        <>
          {loading ? (
            <div className="flex flex-col items-center rounded-2xl border border-stone-200/80 bg-white py-16 shadow-sm">
              <Loader2 className="h-6 w-6 animate-spin text-brand-primary" />
              <p className="mt-3 text-sm text-stone-500">Loading sales execution pipeline...</p>
            </div>
          ) : (
            <div data-tour-id="table-leads" className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
              {LEAD_STAGES.map((stage) => {
                const stageLeads = list
                  .filter((l) => l.stage === stage)
                  .sort((a, b) => (b.aiScore ?? 0) - (a.aiScore ?? 0));
                const style = STAGE_STYLES[stage] || { dot: 'bg-stone-400', header: 'text-stone-700' };
                return (
                  <div key={stage} className="rounded-2xl border border-stone-200/80 bg-stone-50/50 p-3">
                    <div className="mb-3 flex items-center gap-2 px-1">
                      <span className={`h-2.5 w-2.5 rounded-full ${style.dot}`} />
                      <h3 className={`text-sm font-semibold ${style.header}`}>{stage}</h3>
                      <span className="ml-auto rounded-full bg-white px-2 py-0.5 text-xs font-medium text-stone-500 ring-1 ring-stone-200">
                        {stageLeads.length}
                      </span>
                    </div>

                    <div className="space-y-3">
                      {stageLeads.map((l) => (
                        <div
                          key={l.id}
                          onClick={() => setSelectedLead(l)}
                          className="rounded-xl border border-stone-200/70 bg-white p-4 shadow-sm transition-all hover:shadow-md hover:border-brand-primary cursor-pointer group"
                        >
                          <div className="flex items-start justify-between gap-2">
                            <p className="font-bold text-stone-900 group-hover:text-brand-primary transition-colors flex items-center gap-1">
                              {l.name} <ChevronRight className="h-3.5 w-3.5 text-stone-400 group-hover:translate-x-0.5 transition-transform" />
                            </p>
                            <div className="flex items-center gap-1 bg-brand-soft px-2 py-0.5 rounded-full border border-border-subtle/50">
                              <Sparkles className="h-3 w-3 text-brand-primary" />
                              <span className="text-[10px] font-bold text-brand-primary-hover">AI {l.aiScore}</span>
                            </div>
                          </div>

                          <p className="mt-0.5 text-xs text-stone-400">{l.email}</p>

                          {cardMode === 'expanded' && (
                            <>
                              {l.aiInsight && (
                                <p className="mt-2 text-[11px] font-medium text-indigo-600 leading-tight bg-indigo-50/50 p-1.5 rounded-lg border border-indigo-100/50">
                                  {l.aiInsight}
                                </p>
                              )}

                              {/* Warnings & CPL */}
                              <div className="mt-2 flex flex-wrap items-center gap-1">
                                <span className="rounded bg-status-warning/10 px-1.5 py-0.5 text-[9px] font-semibold text-status-warning border border-status-warning/20">
                                  CPL: $24.50
                                </span>
                                <span className="rounded bg-brand-soft px-1.5 py-0.5 text-[9px] font-semibold text-brand-primary-hover border border-border-subtle">
                                  SLA: 4m
                                </span>
                              </div>
                            </>
                          )}

                          <div className="mt-3 flex items-center justify-between text-xs text-stone-500">
                            <span>Budget {formatCents(l.budgetCents)}</span>
                            <span>{formatDate(l.weddingDate)}</span>
                          </div>

                          <div className="mt-2 flex items-center justify-between">
                            <span className="rounded-full bg-stone-100 px-2.5 py-0.5 text-[11px] font-semibold text-stone-600">
                              {l.source}
                            </span>
                            {stage !== 'Won' && (
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  advanceLead(l.id);
                                }}
                                className="inline-flex items-center gap-1 rounded-lg px-2 py-1 text-xs font-semibold text-brand-primary transition-colors hover:bg-brand-soft"
                              >
                                Advance <ArrowRight className="h-3 w-3" />
                              </button>
                            )}
                          </div>
                        </div>
                      ))}

                      {stageLeads.length === 0 && (
                        <p className="rounded-xl border border-dashed border-stone-200 py-6 text-center text-xs text-stone-400">
                          No leads in this stage
                        </p>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </>
      )}

      {/* ΓöÇΓöÇ TAB 2: LEAD GENERATOR WIZARD ΓöÇΓöÇ */}
      {activeTab === 'generator' && (
        <LeadGeneratorWizard onComplete={() => setActiveTab('pipeline')} onCancel={() => setActiveTab('pipeline')} />
      )}

      {/* ΓöÇΓöÇ TAB 3: LEAD INBOX ΓöÇΓöÇ */}
      {activeTab === 'inbox' && (
        <LeadInboxView
          onSelectLead={(l) => {
            const found = list.find((item) => item.id === l.id);
            if (found) setSelectedLead(found);
          }}
        />
      )}

      {/* ΓöÇΓöÇ TAB 4: FOLLOW-UP & SLAS ΓöÇΓöÇ */}
      {activeTab === 'followup' && (
        <LeadFollowUpView
          onSelectLead={(l) => {
            const found = list.find((item) => item.id === l.id);
            if (found) setSelectedLead(found);
          }}
        />
      )}

      {/* ΓöÇΓöÇ TAB 5: ATTRIBUTION MATRIX ΓöÇΓöÇ */}
      {activeTab === 'attribution' && <LeadAttributionView />}

      {/* ΓöÇΓöÇ TAB 6: LEAD REPORTS ΓöÇΓöÇ */}
      {activeTab === 'reports' && <LeadReportsView />}

      {/* ΓöÇΓöÇ TAB 7, 8: AUTOMATIONS & SETTINGS PLACEHOLDERS ΓöÇΓöÇ */}
      {(activeTab === 'automations' || activeTab === 'settings' || activeTab === 'sources' || activeTab === 'assignments' || activeTab === 'appointments') && (
        <div className="mt-6">
          <BeautifulEmptyState
            icon={<Zap className="h-8 w-8" />}
            title={`${activeTab.toUpperCase()} View Active`}
            description="Configured and synchronizing directly with VowOS Shared Lead Intelligence Service."
            colorHint="rose"
          />
        </div>
      )}

      {/* Lead 360 Source Drilldown Modal */}
      {selectedLead && (
        <Lead360Modal
          lead={selectedLead}
          onClose={() => setSelectedLead(null)}
          onNavigateToBride={(brideId) => {
            sessionStorage.setItem('vowos_target_bride_id', brideId);
            if (onNavigate) onNavigate('customers');
          }}
          onBookAppointment={(name, email) => {
            setBookLead({ name, email });
          }}
        />
      )}

      {/* Book Appointment Modal for Lead */}
      {bookLead && (
        <BookAppointmentModal
          open={true}
          onClose={() => setBookLead(null)}
          defaultName={bookLead.name}
          defaultEmail={bookLead.email}
        />
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { MoreHorizontal, X, ExternalLink, Lock, Monitor, Smartphone } from 'lucide-react';
import { NAVIGATION_ITEMS, NAVIGATION_SECTIONS, NavigationItem, ViewKey } from '@/lib/navigation/navigationRegistry';
import { useAuth } from '@/contexts/AuthContext';
import { canAccessView } from '@/components/vowos/Sidebar';
import { useDeviceMode } from '@/contexts/DeviceModeContext';
import { InstallAppButton } from '@/components/pwa/InstallAppButton';
import { useDemo } from '@/lib/demo/demoContext';

interface MobileNavigationProps {
  view: ViewKey;
  onNavigate: (v: ViewKey) => void;
  onRequestSignIn: () => void;
}

export default function MobileNavigation({ view, onNavigate }: MobileNavigationProps) {
  const [moreOpen, setMoreOpen] = useState(false);
  const { profile } = useAuth();
  const { isDemoMode, activePersona, activeStore } = useDemo();
  const { isDesktopModeOverride, setDesktopModeOverride } = useDeviceMode();
  const role = isDemoMode ? activePersona.role : (profile?.role ?? null);

  let bottomBarKeys: ViewKey[] = [];
  if (role === 'Owner') {
    bottomBarKeys = ['overview', 'schedule', 'sales', 'reports'];
  } else if (role === 'Manager') {
    bottomBarKeys = ['dashboard', 'schedule', 'actions', 'sales'];
  } else {
    bottomBarKeys = ['dashboard', 'schedule', 'customers', 'marketing'];
  }

  const bottomBarItems = bottomBarKeys.map(k => NAVIGATION_ITEMS.find(i => i.id === k)).filter(Boolean) as NavigationItem[];

  useEffect(() => {
    const handleOpenDrawer = () => setMoreOpen(true);
    window.addEventListener('vowos:open-mobile-drawer', handleOpenDrawer);
    return () => window.removeEventListener('vowos:open-mobile-drawer', handleOpenDrawer);
  }, []);

  return (
    <>
      <nav className="fixed bottom-0 left-0 right-0 z-30 border-t border-stone-200 bg-white/95 backdrop-blur lg:hidden pb-[env(safe-area-inset-bottom)] shadow-lg">
        <div className="flex items-center justify-around h-14 px-1">
          {bottomBarItems.map((item) => {
            const active = view === item.id;
            const Icon = item.icon;
            return (
              <button
                key={item.id}
                data-tour-id={`mobile-tab-${item.id}`}
                onClick={() => {
                  onNavigate(item.id as ViewKey);
                  setMoreOpen(false);
                }}
                className={`flex flex-col items-center justify-center min-w-[56px] py-1 text-[10px] font-semibold transition-colors ${
                  active ? 'text-brand-primary font-bold' : 'text-stone-500 hover:text-stone-800'
                }`}
              >
                <Icon className={`h-5 w-5 ${active ? 'text-brand-primary scale-105' : 'text-stone-500'}`} />
                <span className="truncate max-w-[64px] mt-0.5">{item.shortLabel || item.label}</span>
              </button>
            );
          })}

          <button
            data-tour-id="mobile-more-btn"
            onClick={() => setMoreOpen(!moreOpen)}
            className={`flex flex-col items-center justify-center min-w-[56px] py-1 text-[10px] font-semibold transition-colors ${
              moreOpen || (!bottomBarItems.some((i) => i.id === view) && view !== 'dashboard')
                ? 'text-brand-primary font-bold'
                : 'text-stone-500 hover:text-stone-800'
            }`}
          >
            <MoreHorizontal className={`h-5 w-5 ${moreOpen ? 'text-brand-primary' : 'text-stone-500'}`} />
            <span>More</span>
          </button>
        </div>
      </nav>

      {moreOpen && (
        <div className="fixed inset-0 z-40 lg:hidden">
          <div className="absolute inset-0 bg-stone-900/60 backdrop-blur-xs" onClick={() => setMoreOpen(false)} />
          <div className="absolute inset-x-0 bottom-14 max-h-[85vh] overflow-y-auto rounded-t-3xl bg-[#1c1a1f] p-5 shadow-2xl animate-in slide-in-from-bottom duration-200">
            <div className="flex items-center justify-between border-b border-white/10 pb-4 mb-4">
              <div>
                <p className="font-serif text-lg text-white">VowOS Menu</p>
                <p className="text-[10px] uppercase tracking-wider text-stone-400">
                  {isDemoMode ? `${activeStore.name} ┬╖ Demo` : 'Your Organization'}
                </p>
              </div>
              <button
                onClick={() => setMoreOpen(false)}
                className="rounded-full p-2 text-stone-400 hover:bg-white/10 hover:text-white"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="mb-6 rounded-2xl bg-white/5 p-4 border border-white/10">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-white flex items-center gap-2">
                    {isDesktopModeOverride ? <Monitor className="h-4 w-4" /> : <Smartphone className="h-4 w-4" />}
                    {isDesktopModeOverride ? 'Desktop View Active' : 'Mobile Experience Active'}
                  </p>
                  <p className="text-xs text-stone-400 mt-1 max-w-[220px]">
                    {isDesktopModeOverride 
                      ? 'You are viewing the desktop layout on mobile.'
                      : 'You are using the optimized mobile command center.'}
                  </p>
                </div>
                <button
                  onClick={() => setDesktopModeOverride(!isDesktopModeOverride)}
                  className={`relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none ${
                    isDesktopModeOverride ? 'bg-status-warning' : 'bg-stone-600'
                  }`}
                >
                  <span
                    className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${
                      isDesktopModeOverride ? 'translate-x-5' : 'translate-x-0'
                    }`}
                  />
                </button>
              </div>
            </div>

            <div className="mb-6 px-1">
              <InstallAppButton fullWidth variant="secondary" />
            </div>

            <div className="space-y-6 pb-6">
              {NAVIGATION_SECTIONS.map((sec) => {
                const itemsInSec = NAVIGATION_ITEMS.filter(
                  (i) => i.section === sec.id && !(isDemoMode && i.id === 'platform-admin'),
                );
                if (itemsInSec.length === 0) return null;
                
                return (
                  <div key={sec.id} className="space-y-2">
                    <p className="text-[10px] font-bold uppercase tracking-wider text-stone-400 px-2">
                      {sec.label}
                    </p>
                    <div className="grid grid-cols-2 gap-2">
                      {itemsInSec.map((item) => {
                        const Icon = item.icon;
                        const active = view === item.id;
                        const locked = !canAccessView(role as any, item.id as ViewKey, profile?.id);

                        if (item.external) {
                          const href = isDemoMode && item.id === 'booking' ? '/demoapp/book' : item.path;
                          return (
                            <a
                              key={item.id}
                              href={href}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="flex items-center gap-2.5 rounded-xl border border-dashed border-brand-primary/30 p-2.5 text-xs font-medium text-rose-300 hover:bg-brand-primary/10"
                            >
                              <Icon className="h-4 w-4 text-brand-primary" />
                              <span className="truncate">{item.label}</span>
                              <ExternalLink className="ml-auto h-3 w-3 text-brand-primary/60" />
                            </a>
                          );
                        }

                        return (
                          <button
                            key={item.id}
                            data-tour-id={`mobile-nav-${item.id}`}
                            onClick={() => {
                              onNavigate(item.id as ViewKey);
                              setMoreOpen(false);
                            }}
                            className={`flex items-center gap-2.5 rounded-xl p-2.5 text-xs font-medium transition-all ${
                              active
                                ? 'bg-gradient-to-r from-rose-500/20 to-transparent text-rose-300 ring-1 ring-inset ring-focus-ring/30 font-semibold'
                                : 'text-stone-300 hover:bg-white/5 hover:text-white'
                            }`}
                          >
                            <Icon className={`h-4 w-4 ${active ? 'text-brand-primary' : 'text-stone-400'}`} />
                            <span className="truncate">{item.label}</span>
                            {locked && <Lock className="ml-auto h-3 w-3 text-stone-500" />}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}
    </>
  );
}

import { useEffect, useState, useMemo } from 'react';
import { AlertCircle, FileCheck, RefreshCcw, BellElectric, ArrowRight, Loader2, X, ChevronRight } from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import { useVowosData } from '@/contexts/VowosDataContext';
import { useApplicationRoute } from '@/lib/navigation/useApplicationRoute';
import { fetchActions, ActionCenterRecord, updateActionStatus } from '@/lib/services/actionCenterService';
import { useDemo } from '@/lib/demo/demoContext';

type FilterType = 'All' | 'Urgent' | 'Approvals' | 'Due Today' | 'Follow-ups' | 'Exceptions';

export default function NeedsAttention() {
  const { session, profile } = useAuth();
  const { activeLocation } = useVowosData();
  const { navigateToPath } = useApplicationRoute();
  const { isDemoMode } = useDemo();
  
  console.log('NeedsAttention rendering:', { session: !!session, isDemoMode });

  const [actions, setActions] = useState<ActionCenterRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);
  const [filter, setFilter] = useState<FilterType>('All');

  useEffect(() => {
    let mounted = true;

    async function load() {
      if (!session && !isDemoMode) return;
      
      // Use demo business ID in demo mode, otherwise extract from session or use a default
      const businessId = isDemoMode ? 'demo-business-id-001' : (session?.user?.user_metadata?.business_id || 'demo-business-id-001');
      
      try {
        setLoading(true);
        setError(null);
        const data = await fetchActions(businessId, activeLocation);
        if (mounted) setActions(data);
      } catch (err: any) {
        if (mounted) setError(err);
      } finally {
        if (mounted) setLoading(false);
      }
    }

    load();
    return () => { mounted = false; };
  }, [session, isDemoMode, activeLocation]);

  const handleActionClick = (action: ActionCenterRecord) => {
    navigateToPath(action.deep_link);
  };

  const handleDismiss = async (action: ActionCenterRecord, e: React.MouseEvent) => {
    e.stopPropagation();
    // Simulate dismiss logic for demo, usually this would prompt for a reason
    const success = await updateActionStatus(action.id, 'Dismissed', { reason: 'Dismissed from Today view', dismissed_by: profile?.id });
    if (success) {
      setActions(prev => prev.filter(a => a.id !== action.id));
    }
  };

  // Filter conditions
  const urgentActions = actions.filter(a => a.priority === 'Critical' || a.priority === 'High');
  const approvalActions = actions.filter(a => a.requires_approval || a.action_type.includes('approval'));
  const followUpActions = actions.filter(a => a.action_type.includes('follow') || a.action_type.includes('response'));
  const exceptionActions = actions.filter(a => !urgentActions.includes(a) && !approvalActions.includes(a) && !followUpActions.includes(a) && (a.action_type.includes('exception') || a.action_type.includes('discrepancy')));
  const dueTodayActions = actions.filter(a => {
    if (!a.due_at) return false;
    const due = new Date(a.due_at);
    const today = new Date();
    return due.toDateString() === today.toDateString();
  });

  const filteredActions = useMemo(() => {
    switch (filter) {
      case 'Urgent': return urgentActions;
      case 'Approvals': return approvalActions;
      case 'Follow-ups': return followUpActions;
      case 'Exceptions': return exceptionActions;
      case 'Due Today': return dueTodayActions;
      default: return actions;
    }
  }, [filter, actions, urgentActions, approvalActions, followUpActions, exceptionActions, dueTodayActions]);

  if (!session && !isDemoMode) return null;

  return (
    <div className="rounded-2xl border border-stone-200/80 bg-white shadow-sm flex flex-col h-full max-h-[500px]">
      <div className="p-4 sm:p-6 border-b border-stone-100 flex items-center justify-between">
        <div>
          <h2 className="font-serif text-lg text-stone-900 flex items-center gap-2">
            <BellElectric className="h-5 w-5 text-brand-primary" />
            Needs Attention
          </h2>
          <p className="text-xs text-stone-500 mt-1">Operational exceptions requiring your input</p>
        </div>
        <div className="hidden md:flex gap-2 text-xs">
          {(['All', 'Urgent', 'Due Today', 'Approvals'] as FilterType[]).map(f => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`px-3 py-1.5 rounded-lg transition-colors font-medium ${filter === f ? 'bg-stone-900 text-white' : 'bg-stone-100 text-stone-600 hover:bg-stone-200'}`}
            >
              {f}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-2 sm:p-4 bg-stone-50/50">
        {loading ? (
          <div className="flex flex-col items-center justify-center py-12">
            <Loader2 className="h-6 w-6 animate-spin text-stone-300 mb-2" />
            <p className="text-xs text-stone-500">Scanning operations...</p>
          </div>
        ) : error ? (
          <div className="flex flex-col items-center justify-center py-10 px-4 text-center">
            <AlertCircle className="h-10 w-10 text-brand-primary mb-3" />
            <h3 className="text-sm font-semibold text-stone-900">Unable to load attention items</h3>
            <p className="mt-1 text-xs text-stone-500">The action service could not complete the request. Please check your connection or system health.</p>
          </div>
        ) : filteredActions.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 px-4 text-center">
            <FileCheck className="h-10 w-10 text-emerald-400 mb-3" />
            <h3 className="text-sm font-semibold text-stone-900">You're caught up</h3>
            <p className="mt-1 text-xs text-stone-500">No urgent operational items require your attention right now.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-1 gap-2">
            {filteredActions.map(action => {
              const isUrgent = action.priority === 'Critical' || action.priority === 'High';
              return (
                <div
                  key={action.id}
                  onClick={() => handleActionClick(action)}
                  className={`group relative rounded-xl border p-3 sm:p-4 cursor-pointer transition-all hover:shadow-md ${isUrgent ? 'border-border-subtle bg-brand-soft/30 hover:border-rose-300' : 'border-stone-200 bg-white hover:border-stone-300'}`}
                >
                  <div className="flex justify-between items-start mb-1">
                    <div className="flex items-center gap-2">
                      <span className={`inline-flex items-center rounded-sm px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wider ${isUrgent ? 'bg-brand-soft text-brand-primary-hover' : 'bg-stone-100 text-stone-600'}`}>
                        {action.priority}
                      </span>
                      <span className="text-[10px] text-stone-400 font-medium uppercase tracking-wider">{action.source_module}</span>
                    </div>
                    <div className="flex items-center gap-1">
                      {action.due_at && (
                        <span className="text-[10px] text-stone-400 hidden sm:inline-block">
                          Due {new Date(action.due_at).toLocaleDateString()}
                        </span>
                      )}
                      <button 
                        onClick={(e) => handleDismiss(action, e)}
                        className="opacity-0 group-hover:opacity-100 transition-opacity p-1 text-stone-400 hover:text-stone-600 hover:bg-stone-100 rounded"
                        title="Dismiss"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </div>
                  </div>
                  <h4 className="font-semibold text-stone-900 text-sm leading-tight pr-6">{action.title}</h4>
                  {action.description && (
                    <p className="mt-1 text-xs text-stone-500 line-clamp-1">{action.description}</p>
                  )}
                  <div className="mt-3 flex">
                    <div className="inline-flex items-center justify-center gap-1.5 rounded-lg bg-brand-primary hover:bg-brand-primary-hover px-3 py-1.5 text-xs font-bold text-white shadow-sm transition-colors w-full sm:w-auto">
                      Fix Now <ChevronRight className="h-3.5 w-3.5" />
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
      
      {actions.length > 0 && !error && (
        <div className="p-3 border-t border-stone-100 bg-white rounded-b-2xl">
          <button 
            onClick={() => setFilter('All')}
            className="w-full text-center text-xs font-semibold text-stone-500 hover:text-stone-900 transition-colors py-1"
          >
            {filter !== 'All' ? 'View All Attention Items' : `${actions.length} Total Open Items`}
          </button>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { supabase } from '@/lib/supabase';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@vowos/design-system';
import { Badge } from '@vowos/design-system';
import { Loader2, Settings, ShieldAlert, Building } from 'lucide-react';
import { toast } from '@vowos/design-system';
import { CommercialPlan } from '@/config/commercialCatalog';

export function PlatformAdminView() {
  const [loading, setLoading] = useState(true);
  const [tenants, setTenants] = useState<any[]>([]);

  const fetchTenants = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('businesses')
        .select(`
          id,
          name,
          created_at,
          tenant_subscriptions (
            id,
            plan,
            status,
            addons,
            overrides,
            industry_pack
          )
        `)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setTenants(data || []);
    } catch (err) {
      console.error(err);
      toast({ title: 'Error fetching tenants', variant: 'destructive' });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTenants();
  }, []);

  const updateTenantPlan = async (subId: string, newPlan: CommercialPlan) => {
    try {
      const { error } = await supabase
        .from('tenant_subscriptions')
        .update({ plan: newPlan })
        .eq('id', subId);

      if (error) throw error;
      toast({ title: 'Plan updated successfully' });
      fetchTenants();
    } catch (err) {
      console.error(err);
      toast({ title: 'Error updating plan', variant: 'destructive' });
    }
  };

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-stone-300" />
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto space-y-6">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-2xl font-semibold text-stone-900 tracking-tight">Platform Admin</h1>
          <p className="text-stone-500 mt-1">Global view of all tenants and their subscriptions.</p>
        </div>
        <Badge variant="outline" className="bg-brand-soft text-brand-primary-hover border-border-subtle uppercase tracking-widest text-[10px]">
          <ShieldAlert className="h-3 w-3 mr-1" />
          Superuser Access
        </Badge>
      </div>

      <div className="grid gap-4">
        {tenants.map(tenant => {
          const sub = tenant.tenant_subscriptions?.[0] || {};
          return (
            <Card key={tenant.id}>
              <CardContent className="p-6 flex flex-col md:flex-row gap-6 md:items-center justify-between">
                <div className="flex items-center gap-4">
                  <div className="h-12 w-12 rounded-xl bg-stone-100 border border-stone-200 flex items-center justify-center">
                    <Building className="h-6 w-6 text-stone-500" />
                  </div>
                  <div>
                    <h3 className="font-semibold text-lg text-stone-900">{tenant.name}</h3>
                    <div className="flex items-center gap-3 mt-1">
                      <p className="text-xs text-stone-500 font-mono">{tenant.id}</p>
                      <Badge variant="outline" className="capitalize text-[10px]">{sub.status || 'unknown'}</Badge>
                      <Badge variant="secondary" className="text-[10px]">{sub.industry_pack || 'bridal'}</Badge>
                    </div>
                  </div>
                </div>
                
                <div className="flex items-center gap-4">
                  <div className="flex flex-col items-end">
                    <span className="text-xs text-stone-500 uppercase font-bold tracking-wider mb-1">Current Plan</span>
                    <select
                      className="border-stone-200 rounded-md text-sm font-medium focus:ring-focus-ring focus:border-brand-primary"
                      value={sub.plan || 'essentials'}
                      onChange={(e) => updateTenantPlan(sub.id, e.target.value as CommercialPlan)}
                    >
                      <option value="essentials">Essentials</option>
                      <option value="pro">Pro</option>
                      <option value="enterprise">Enterprise</option>
                    </select>
                  </div>
                  
                  <div className="flex flex-col items-end">
                    <span className="text-xs text-stone-500 uppercase font-bold tracking-wider mb-1">Add-ons</span>
                    <div className="flex gap-1">
                      {sub.addons?.length ? (
                        sub.addons.map((a: string) => <Badge key={a} variant="outline" className="text-[10px]">{a}</Badge>)
                      ) : (
                        <span className="text-xs text-stone-400">None</span>
                      )}
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { PackageSearch, Truck, CheckCircle2, Loader2, Globe, KeyRound, Eye, EyeOff, Copy, ExternalLink, Plus, Search, Building2, Calendar, AlertTriangle, User, Sparkles, BarChart3, ArrowUpRight, Clock, ShieldCheck, FileText, DollarSign, Trash2, Archive, RotateCcw, Pencil, UserCheck } from 'lucide-react';
import { formatCents, formatDate, LOCATIONS, locationById, PurchaseOrder, teamMembers } from '@/data/vowosData';
import { useVowosData } from '@/contexts/VowosDataContext';
import { PageHeader, StatusBadge, StatCard, Modal, inputCls, btnPrimary, btnSecondary, BeautifulEmptyState } from './ui';
import { getVendorPortals, saveVendorPortal, VendorPortal } from '@/lib/services/vendorPortalStore';
import { toast } from '@vowos/design-system';

import PODetailDrilldownModal from '@/features/inventory/components/PODetailDrilldownModal';
import { catalogService } from '@/lib/services/catalogService';
import { Vendor, Product, ProductVariant } from '@/types/catalog';

export default function PurchasesView() {
  const { purchaseOrders: list, brides, loading, markPoDelivered, updatePoStatus, updatePurchaseOrder, deletePurchaseOrder, addPurchaseOrder } = useVowosData();
  const [activeTab, setActiveTab] = useState<'orders' | 'vault' | 'customers' | 'analytics'>('orders');
  const [selectedDrilldownPo, setSelectedDrilldownPo] = useState<PurchaseOrder | null>(null);

  // Search & Filter controls
  const [searchTerm, setSearchTerm] = useState('');
  const [vendorFilter, setVendorFilter] = useState('all');
  const [statusFilter, setStatusFilter] = useState('all');
  const [staffFilter, setStaffFilter] = useState('all');

  // Vendor Credentials Vault State
  const [portals, setPortals] = useState<VendorPortal[]>([]);
  const [showPassMap, setShowPassMap] = useState<Record<string, boolean>>({});

  // Modal States
  const [showNewPoModal, setShowNewPoModal] = useState(false);
  const [showPortalModal, setShowPortalModal] = useState(false);
  const [editingPortal, setEditingPortal] = useState<VendorPortal | null>(null);
  const [deletePoId, setDeletePoId] = useState<string | null>(null);

  // Edit PO State
  const [editingPo, setEditingPo] = useState<PurchaseOrder | null>(null);
  const [editVendor, setEditVendor] = useState('Justin Alexander');
  const [editItems, setEditItems] = useState('');
  const [editAmountDollars, setEditAmountDollars] = useState('');
  const [editEta, setEditEta] = useState('');
  const [editLocation, setEditLocation] = useState<any>('ido-cov');
  const [editStaff, setEditStaff] = useState('Dana R.');
  const [editCustomer, setEditCustomer] = useState('');
  const [editNotes, setEditNotes] = useState('');

  const handleOpenEditPo = (po: PurchaseOrder) => {
    setEditingPo(po);
    setEditVendor(po.vendor);
    setEditItems(po.items);
    setEditAmountDollars((po.amountCents / 100).toFixed(2));
    setEditEta(po.expectedDelivery);
    setEditLocation(po.location);
    setEditStaff(po.assignedStaff || teamMembers[0]);
    setEditCustomer(po.assignedCustomer || '');
    setEditNotes(po.notes || '');
  };

  const handleSaveEditPo = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingPo) return;
    const amountCents = Math.round(parseFloat(editAmountDollars || '0') * 100);
    const success = await updatePurchaseOrder(editingPo.id, {
      vendor: editVendor,
      items: editItems,
      amountCents: amountCents > 0 ? amountCents : editingPo.amountCents,
      expectedDelivery: editEta,
      location: editLocation,
      assignedStaff: editStaff,
      assignedCustomer: editCustomer,
      notes: editNotes,
    });
    if (success) {
      setEditingPo(null);
      toast({
        title: 'Purchase Order Updated',
        description: `${editingPo.id} assigned to ${editStaff} and linked to ${editCustomer || 'Store Stock'}.`,
      });
    }
  };

  const handleStatusChange = async (poId: string, newStatus: PurchaseOrder['status']) => {
    const success = await updatePoStatus(poId, newStatus);
    if (success) {
      toast({
        title: 'Status Updated',
        description: `${poId} status changed to "${newStatus}".`,
      });
    }
  };

  const handleDeletePoConfirm = async () => {
    if (!deletePoId) return;
    const targetId = deletePoId;
    const success = await deletePurchaseOrder(targetId);
    setDeletePoId(null);
    if (success) {
      toast({
        title: 'Purchase Order Deleted',
        description: `${targetId} has been deleted.`,
      });
    }
  };

  // New PO Form & Auto Ingest
  const [newVendor, setNewVendor] = useState('Justin Alexander');
  const [newItems, setNewItems] = useState('');
  const [newAmountDollars, setNewAmountDollars] = useState('');
  const [newEta, setNewEta] = useState('');
  const [newCustomer, setNewCustomer] = useState('');
  const [rawIngestText, setRawIngestText] = useState('');
  const [submittingPo, setSubmittingPo] = useState(false);

  // Portal Form
  const [portalName, setPortalName] = useState('');
  const [portalBrand, setPortalBrand] = useState('');
  const [portalUrl, setPortalUrl] = useState('');
  const [portalUsername, setPortalUsername] = useState('');
  const [portalPassword, setPortalPassword] = useState('');
  const [portalDealerId, setPortalDealerId] = useState('');
  const [portalRepName, setPortalRepName] = useState('');
  const [portalRepPhone, setPortalRepPhone] = useState('');
  const [portalRepEmail, setPortalRepEmail] = useState('');
  const [portalLeadTimeDays, setPortalLeadTimeDays] = useState('40');

  const [catalogVendors, setCatalogVendors] = useState<Vendor[]>([]);
  const [catalogProducts, setCatalogProducts] = useState<Product[]>([]);
  const [catalogVariants, setCatalogVariants] = useState<ProductVariant[]>([]);

  useEffect(() => {
    getVendorPortals().then(setPortals);
    catalogService.getVendors('b0000000-0000-0000-0000-000000000001').then(setCatalogVendors).catch(console.error);
  }, []);

  useEffect(() => {
    if (newVendor && catalogVendors.some(v => v.id === newVendor)) {
      catalogService.getVendorProducts('b0000000-0000-0000-0000-000000000001', newVendor).then(setCatalogProducts).catch(console.error);
    } else {
      setCatalogProducts([]);
    }
  }, [newVendor, catalogVendors]);

  const togglePasswordVisibility = (id: string) => {
    setShowPassMap((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  const copyToClipboard = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    toast({ title: 'Copied to Clipboard', description: `${label} copied.` });
  };

  const handleOpenEditPortal = (p?: VendorPortal) => {
    if (p) {
      setEditingPortal(p);
      setPortalName(p.name);
      setPortalBrand(p.brand);
      setPortalUrl(p.portalUrl);
      setPortalUsername(p.username);
      setPortalPassword(p.password || '');
      setPortalDealerId(p.dealerId);
      setPortalRepName(p.repName);
      setPortalRepPhone(p.repPhone);
      setPortalRepEmail(p.repEmail);
      setPortalLeadTimeDays(String(p.avgLeadTimeDays));
    } else {
      setEditingPortal(null);
      setPortalName('');
      setPortalBrand('');
      setPortalUrl('');
      setPortalUsername('');
      setPortalPassword('');
      setPortalDealerId('');
      setPortalRepName('');
      setPortalRepPhone('');
      setPortalRepEmail('');
      setPortalLeadTimeDays('40');
    }
    setShowPortalModal(true);
  };

  const handleSavePortal = async (e: React.FormEvent) => {
    e.preventDefault();
    const newEntry: VendorPortal = {
      id: editingPortal ? editingPortal.id : `v-${Date.now()}`,
      name: portalName.trim(),
      brand: portalBrand.trim() || portalName.trim(),
      portalUrl: portalUrl.trim(),
      username: portalUsername.trim(),
      password: portalPassword.trim(),
      dealerId: portalDealerId.trim(),
      repName: portalRepName.trim(),
      repPhone: portalRepPhone.trim(),
      repEmail: portalRepEmail.trim(),
      avgLeadTimeDays: parseInt(portalLeadTimeDays) || 30,
    };
    const updated = await saveVendorPortal(newEntry);
    setPortals(updated);
    setShowPortalModal(false);
    toast({ title: 'Vendor Portal Vault Updated', description: `${newEntry.name} credentials saved.` });
  };

  // Auto Ingest Parser logic
  const handleAutoIngest = () => {
    if (!rawIngestText.trim()) return;
    const text = rawIngestText;
    
    // Look for items or gown names
    let matchedItem = 'Special Order Gown & Accessories';
    if (text.toLowerCase().includes('justin alexander')) setNewVendor('Justin Alexander');
    else if (text.toLowerCase().includes('pronovias')) setNewVendor('Pronovias');
    else if (text.toLowerCase().includes('essense')) setNewVendor('Essense of Australia');
    else if (text.toLowerCase().includes('morilee')) setNewVendor('Morilee');

    const lines = text.split('\n').filter((l) => l.trim().length > 0);
    if (lines.length > 0) {
      matchedItem = lines[0].slice(0, 80);
    }
    setNewItems(matchedItem);

    // Look for amounts e.g. $1,850 or 1850
    const priceMatch = text.match(/\$?([0-9,]+(?:\.[0-9]{2})?)/);
    if (priceMatch) {
      const parsedDollars = priceMatch[1].replace(',', '');
      setNewAmountDollars(parsedDollars);
    }

    // Default ETA + 45 days
    const futureDate = new Date();
    futureDate.setDate(futureDate.getDate() + 45);
    setNewEta(futureDate.toISOString().slice(0, 10));

    toast({ title: 'Vendor Confirmation Parsed', description: 'Populated PO details from confirmation payload.' });
  };

  const handleCreatePo = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmittingPo(true);
    const amountCents = Math.round(parseFloat(newAmountDollars || '0') * 100);
    const vendorName = catalogVendors.find(v => v.id === newVendor)?.name || newVendor;
    const success = await addPurchaseOrder({
      vendor: vendorName,
      items: newItems + (newCustomer ? ` (Bride: ${newCustomer})` : ''),
      amountCents: amountCents > 0 ? amountCents : 150000,
      expectedDelivery: newEta || new Date().toISOString().slice(0, 10),
    });
    setSubmittingPo(false);
    if (success) {
      setShowNewPoModal(false);
      setNewItems('');
      setNewAmountDollars('');
      setRawIngestText('');
      toast({ title: 'Purchase Order Created', description: `PO created and linked to ${vendorName}.` });
    }
  };

  // Metrics
  const openOrders = list.filter((p) => p.status !== 'Delivered');
  const inTransit = list.filter((p) => p.status === 'In Transit' || p.status === 'Ordered');
  const openValue = openOrders.reduce((s, p) => s + p.amountCents, 0);
  const delayedCount = list.filter((p) => p.status === 'Delayed').length;

  const filteredOrders = list.filter((po) => {
    const q = (searchTerm || '').toLowerCase();
    const matchesSearch =
      (po.id || '').toLowerCase().includes(q) ||
      (po.vendor || '').toLowerCase().includes(q) ||
      (po.items || '').toLowerCase().includes(q) ||
      (po.assignedStaff && po.assignedStaff.toLowerCase().includes(q)) ||
      (po.assignedCustomer && po.assignedCustomer.toLowerCase().includes(q));
    const matchesVendor = vendorFilter === 'all' || po.vendor === vendorFilter;
    const matchesStatus = statusFilter === 'all' || po.status === statusFilter;
    const matchesStaff = staffFilter === 'all' || po.assignedStaff === staffFilter;
    return matchesSearch && matchesVendor && matchesStatus && matchesStaff;
  });

  return (
    <div className="space-y-6">
      <PageHeader
        title="Purchasing & Designer Portals"
        subtitle="Manage vendor ordering portals, credentials vault, special order tracking, and lead-time analytics"
        action={
          <div className="flex items-center gap-2">
            <button
              data-tour-id="btn-vendor-vault"
              onClick={() => handleOpenEditPortal()}
              className={btnSecondary}
            >
              <KeyRound className="h-4 w-4 text-[#a98a4b]" /> Vendor Vault Credentials
            </button>
            <button
              data-tour-id="btn-new-po"
              onClick={() => setShowNewPoModal(true)}
              className={btnPrimary}
            >
              <Plus className="h-4 w-4" /> Create Purchase Order
            </button>
          </div>
        }
      />

      {/* KPI Stats Bar */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard label="Open Purchase Orders" value={String(openOrders.length)} sub={`${delayedCount} flagged delayed`} icon={<PackageSearch className="h-5 w-5" />} accent="violet" />
        <StatCard label="In Transit & Ordered" value={String(inTransit.length)} sub="Active factory runs" icon={<Truck className="h-5 w-5" />} accent="amber" />
        <StatCard label="Total Open PO Value" value={formatCents(openValue)} sub="Wholesale committed" icon={<DollarSign className="h-5 w-5" />} accent="emerald" />
        <StatCard label="Designer Portals Vault" value={String(portals.length)} sub="Saved dealer logins" icon={<Globe className="h-5 w-5" />} accent="rose" />
      </div>

      {/* Navigation Tabs */}
      <div data-tour-id="tabs-purchases" className="flex border-b border-stone-200">
        <button
          onClick={() => setActiveTab('orders')}
          className={`flex items-center gap-2 border-b-2 px-5 py-3 text-sm font-semibold transition-colors ${
            activeTab === 'orders'
              ? 'border-stone-900 text-stone-900'
              : 'border-transparent text-stone-500 hover:text-stone-700'
          }`}
        >
          <PackageSearch className="h-4 w-4" /> All Purchase Orders ({list.length})
        </button>
        <button
          onClick={() => setActiveTab('vault')}
          className={`flex items-center gap-2 border-b-2 px-5 py-3 text-sm font-semibold transition-colors ${
            activeTab === 'vault'
              ? 'border-stone-900 text-stone-900'
              : 'border-transparent text-stone-500 hover:text-stone-700'
          }`}
        >
          <Globe className="h-4 w-4 text-sky-600" /> Designer Portals &amp; Vault ({portals.length})
        </button>
        <button
          onClick={() => setActiveTab('customers')}
          className={`flex items-center gap-2 border-b-2 px-5 py-3 text-sm font-semibold transition-colors ${
            activeTab === 'customers'
              ? 'border-stone-900 text-stone-900'
              : 'border-transparent text-stone-500 hover:text-stone-700'
          }`}
        >
          <User className="h-4 w-4 text-brand-primary" /> Customer Special Orders
        </button>
        <button
          onClick={() => setActiveTab('analytics')}
          className={`flex items-center gap-2 border-b-2 px-5 py-3 text-sm font-semibold transition-colors ${
            activeTab === 'analytics'
              ? 'border-stone-900 text-stone-900'
              : 'border-transparent text-stone-500 hover:text-stone-700'
          }`}
        >
          <BarChart3 className="h-4 w-4 text-status-success" /> Lead Times &amp; Analytics
        </button>
      </div>

      {/* TAB 1: ALL PURCHASE ORDERS */}
      {activeTab === 'orders' && (
        <div className="space-y-4">
          {/* Search & Filters */}
          <div className="flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-stone-200/80 bg-white p-4 shadow-sm">
            <div className="flex flex-1 items-center gap-2 rounded-xl border border-stone-200 bg-stone-50/50 px-3 py-2 text-sm max-w-md">
              <Search className="h-4 w-4 text-stone-400" />
              <input
                type="text"
                placeholder="Search PO #, vendor, or gown style..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-transparent outline-none placeholder:text-stone-400 text-xs"
              />
            </div>

            <div className="flex items-center gap-3">
              <select
                value={vendorFilter}
                onChange={(e) => setVendorFilter(e.target.value)}
                className="rounded-xl border border-stone-200 bg-white px-3 py-2 text-xs font-semibold text-stone-700 outline-none"
              >
                <option value="all">All Vendors</option>
                <option value="Justin Alexander">Justin Alexander</option>
                <option value="Pronovias">Pronovias</option>
                <option value="Essense of Australia">Essense of Australia</option>
                <option value="Morilee">Morilee</option>
                <option value="Veil & Co.">Veil &amp; Co.</option>
              </select>

              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="rounded-xl border border-stone-200 bg-white px-3 py-2 text-xs font-semibold text-stone-700 outline-none"
              >
                <option value="all">All Statuses</option>
                <option value="Ordered">Ordered</option>
                <option value="In Transit">In Transit</option>
                <option value="Delivered">Delivered</option>
                <option value="Delayed">Delayed</option>
                <option value="Archived">Archived</option>
              </select>

              <select
                value={staffFilter}
                onChange={(e) => setStaffFilter(e.target.value)}
                className="rounded-xl border border-stone-200 bg-white px-3 py-2 text-xs font-semibold text-stone-700 outline-none"
              >
                <option value="all">All Staff / Stylists</option>
                {teamMembers.map((t) => (
                  <option key={t} value={t}>{t}</option>
                ))}
              </select>
            </div>
          </div>

          {loading ? (
            <div className="flex flex-col items-center rounded-2xl border border-stone-200/80 bg-white py-16 shadow-sm">
              <Loader2 className="h-6 w-6 animate-spin text-brand-primary" />
              <p className="mt-3 text-sm text-stone-500">Loading purchase orders...</p>
            </div>
          ) : (
            <div className="space-y-3">
              {filteredOrders.map((po) => {
                const vendorPortal = portals.find((p) => p.brand.toLowerCase() === po.vendor.toLowerCase());
                return (
                  <div key={po.id} className="flex flex-col gap-4 rounded-2xl border border-stone-200/80 bg-white p-5 shadow-sm transition-shadow hover:shadow-md sm:flex-row sm:items-center">
                    <div className="flex h-12 w-12 flex-shrink-0 items-center justify-center rounded-xl bg-stone-100 text-stone-600">
                      <PackageSearch className="h-6 w-6" />
                    </div>
                    <div className="min-w-0 flex-1 cursor-pointer group" onClick={() => setSelectedDrilldownPo(po)}>
                      <div className="flex flex-wrap items-center gap-2">
                        <p className="font-semibold text-stone-900 group-hover:text-brand-primary transition-colors flex items-center gap-1">
                          {po.id} <Eye className="h-3.5 w-3.5 text-brand-primary opacity-0 group-hover:opacity-100 transition-opacity" />
                        </p>
                        <StatusBadge status={po.status} />
                        {po.assignedStaff && (
                          <span className="inline-flex items-center gap-1 rounded-full bg-violet-50 border border-violet-200 px-2.5 py-0.5 text-[10px] font-bold text-violet-700">
                            <UserCheck className="h-3 w-3" /> Staff: {po.assignedStaff}
                          </span>
                        )}
                        {po.assignedCustomer && (
                          <span className="inline-flex items-center gap-1 rounded-full bg-brand-soft border border-border-subtle px-2.5 py-0.5 text-[10px] font-bold text-brand-primary-hover">
                            <User className="h-3 w-3" /> Bride: {po.assignedCustomer}
                          </span>
                        )}
                        {vendorPortal && (
                          <a
                            href={vendorPortal.portalUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-1 rounded-full bg-stone-100 px-2.5 py-0.5 text-[10px] font-bold text-stone-600 hover:bg-stone-200"
                          >
                            <Globe className="h-3 w-3 text-sky-600" /> {vendorPortal.name} <ExternalLink className="h-2.5 w-2.5" />
                          </a>
                        )}
                      </div>
                      <p className="mt-1 font-medium text-sm text-stone-800">{po.items}</p>
                      <p className="text-xs text-stone-500 mt-0.5">
                        <span className="font-semibold text-stone-700">{po.vendor}</span> ┬╖ Ordered {formatDate(po.ordered)} ┬╖ ETA {formatDate(po.expectedDelivery)} ┬╖ {locationById(po.location).short}
                      </p>
                    </div>

                    <div className="flex flex-wrap items-center gap-4">
                      <div className="text-right">
                        <p className="font-serif text-lg font-bold text-stone-900">{formatCents(po.amountCents)}</p>
                        <span className="text-[10px] text-stone-400 font-mono">Wholesale PO</span>
                      </div>

                      {/* Interactive Reversible Status Dropdown */}
                      <div className="flex items-center gap-2">
                        <div className="flex items-center gap-1.5 rounded-xl border border-stone-200 bg-stone-50 px-2.5 py-1.5 text-xs font-semibold">
                          <span className="text-[10px] text-stone-400 uppercase font-bold">Status:</span>
                          <select
                            value={po.status}
                            onChange={(e) => handleStatusChange(po.id, e.target.value as PurchaseOrder['status'])}
                            className="bg-transparent font-bold text-stone-800 outline-none cursor-pointer"
                          >
                            <option value="Ordered">Ordered</option>
                            <option value="In Transit">In Transit</option>
                            <option value="Delivered">Delivered (Received)</option>
                            <option value="Delayed">Delayed</option>
                            <option value="Archived">Archived</option>
                          </select>
                        </div>

                        {/* Edit PO & Reassign Button */}
                        <button
                          onClick={() => handleOpenEditPo(po)}
                          title="Edit PO & Reassign Staff/Customer"
                          className="rounded-xl border border-stone-200 p-2 text-stone-600 hover:bg-stone-100 hover:text-stone-900 transition-colors"
                        >
                          <Pencil className="h-4 w-4" />
                        </button>

                        {/* Archive Button */}
                        <button
                          onClick={() => handleStatusChange(po.id, po.status === 'Archived' ? 'Ordered' : 'Archived')}
                          title={po.status === 'Archived' ? 'Unarchive PO' : 'Archive PO'}
                          className={`rounded-xl border p-2 transition-colors ${
                            po.status === 'Archived'
                              ? 'border-amber-300 bg-status-warning/10 text-amber-800'
                              : 'border-stone-200 text-stone-400 hover:bg-stone-100 hover:text-stone-700'
                          }`}
                        >
                          <Archive className="h-4 w-4" />
                        </button>

                        {/* Delete Button */}
                        <button
                          onClick={() => setDeletePoId(po.id)}
                          title="Delete Purchase Order"
                          className="rounded-xl border border-stone-200 p-2 text-stone-400 hover:bg-brand-soft hover:text-brand-primary transition-colors"
                        >
                          <Trash2 className="h-4 w-4" />
                        </button>
                      </div>
                    </div>
                  </div>
                );
              })}
              {filteredOrders.length === 0 && (
                <div className="mt-4">
                  <BeautifulEmptyState
                    icon={<PackageSearch className="h-8 w-8" />}
                    title="No Purchases Found"
                    description="No matching purchase orders found."
                    colorHint="indigo"
                  />
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* TAB 2: DESIGNER PORTALS & VAULT */}
      {activeTab === 'vault' && (
        <div className="space-y-6">
          <div className="rounded-2xl border border-status-warning/20/80 bg-status-warning/10/60 p-4 flex items-center justify-between text-xs text-amber-900">
            <div className="flex items-center gap-2">
              <ShieldCheck className="h-5 w-5 text-status-warning flex-shrink-0" />
              <p>
                <span className="font-bold">Designer Credential Vault</span>: Secure store for Ramsey Sims &amp; purchasing agents. Quick launch retailer ordering portals with 1-click credential copying and auto-ingestion.
              </p>
            </div>
            <button onClick={() => handleOpenEditPortal()} className={btnPrimary}>
              <Plus className="h-3.5 w-3.5" /> Add Designer Portal
            </button>
          </div>

          <div className="grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-3">
            {portals.map((p) => {
              const showPass = showPassMap[p.id] || false;
              return (
                <div key={p.id} className="rounded-2xl border border-stone-200 bg-white p-5 shadow-sm space-y-4 hover:shadow-md transition-shadow">
                  <div className="flex items-start justify-between">
                    <div>
                      <span className="rounded-full bg-stone-100 px-2.5 py-0.5 text-[10px] font-bold uppercase tracking-wider text-stone-600">
                        {p.brand}
                      </span>
                      <h4 className="text-base font-semibold text-stone-900 mt-1">{p.name}</h4>
                    </div>
                    <a
                      href={p.portalUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="inline-flex items-center gap-1 rounded-xl bg-stone-900 px-3 py-1.5 text-xs font-semibold text-white hover:bg-stone-700 shadow-xs"
                    >
                      Launch Portal <ExternalLink className="h-3.5 w-3.5" />
                    </a>
                  </div>

                  {/* Credentials Section */}
                  <div className="rounded-xl border border-stone-100 bg-stone-50/80 p-3 space-y-2 text-xs font-mono">
                    <div className="flex items-center justify-between">
                      <span className="text-stone-400 font-sans font-medium text-[11px]">Portal Login Email:</span>
                      <div className="flex items-center gap-1.5">
                        <span className="font-semibold text-stone-800">{p.username}</span>
                        <button onClick={() => copyToClipboard(p.username, 'Username')} className="text-stone-400 hover:text-stone-700">
                          <Copy className="h-3.5 w-3.5" />
                        </button>
                      </div>
                    </div>

                    <div className="flex items-center justify-between border-t border-stone-200/60 pt-2">
                      <span className="text-stone-400 font-sans font-medium text-[11px]">Vault Password:</span>
                      <div className="flex items-center gap-1.5">
                        <span className="font-semibold text-stone-800">{showPass ? p.password : 'ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó'}</span>
                        <button onClick={() => togglePasswordVisibility(p.id)} className="text-stone-400 hover:text-stone-700">
                          {showPass ? <EyeOff className="h-3.5 w-3.5" /> : <Eye className="h-3.5 w-3.5" />}
                        </button>
                        {p.password && (
                          <button onClick={() => copyToClipboard(p.password!, 'Password')} className="text-stone-400 hover:text-stone-700">
                            <Copy className="h-3.5 w-3.5" />
                          </button>
                        )}
                      </div>
                    </div>

                    <div className="flex items-center justify-between border-t border-stone-200/60 pt-2">
                      <span className="text-stone-400 font-sans font-medium text-[11px]">Dealer / Acct ID:</span>
                      <span className="font-bold text-status-warning">{p.dealerId}</span>
                    </div>
                  </div>

                  {/* Representative Contact */}
                  <div className="text-xs text-stone-600 space-y-1">
                    <p className="font-semibold text-stone-800">Account Executive: {p.repName}</p>
                    <p className="text-stone-500">{p.repEmail} ┬╖ {p.repPhone}</p>
                    <p className="text-[11px] text-stone-400">Est. Lead Time: <span className="font-bold text-stone-700">{p.avgLeadTimeDays} days</span></p>
                  </div>

                  <div className="pt-2 border-t border-stone-100 flex justify-end">
                    <button onClick={() => handleOpenEditPortal(p)} className="text-xs font-semibold text-stone-600 hover:text-stone-900">
                      Edit Credentials
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* TAB 3: CUSTOMER SPECIAL ORDERS */}
      {activeTab === 'customers' && (
        <div className="space-y-4">
          <div className="rounded-2xl border border-stone-200 bg-white p-5 shadow-sm space-y-4">
            <h4 className="text-sm font-bold text-stone-900">Bride Special Order Matrix &amp; Wedding Date Runways</h4>
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs">
                <thead>
                  <tr className="border-b border-stone-200 text-stone-400 font-semibold uppercase text-[10px] tracking-wider">
                    <th className="pb-3">Bride / Customer</th>
                    <th className="pb-3">Wedding Date</th>
                    <th className="pb-3">PO Number &amp; Items</th>
                    <th className="pb-3">Vendor / Designer</th>
                    <th className="pb-3">Order Status</th>
                    <th className="pb-3">ETA Runway</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-stone-100">
                  {list.map((po) => {
                    const bride = brides.find((b) => po.items.toLowerCase().includes(b.name.toLowerCase()));
                    const weddingDate = bride?.weddingDate || '2026-10-15';
                    return (
                      <tr key={po.id} className="hover:bg-stone-50/60">
                        <td className="py-3.5 font-semibold text-stone-900">
                          {bride ? bride.name : 'Special Order Bride'}
                          <span className="block text-[10px] text-stone-400 font-normal">{bride?.email || 'idobridal@robertsenterprises.com'}</span>
                        </td>
                        <td className="py-3.5 text-stone-700 font-medium">
                          {formatDate(weddingDate)}
                        </td>
                        <td className="py-3.5">
                          <span className="font-bold text-stone-800">{po.id}</span>
                          <span className="block text-stone-500">{po.items}</span>
                        </td>
                        <td className="py-3.5 font-medium text-stone-700">
                          {po.vendor}
                        </td>
                        <td className="py-3.5">
                          <StatusBadge status={po.status} />
                        </td>
                        <td className="py-3.5 font-mono text-stone-800">
                          ETA {formatDate(po.expectedDelivery)}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* TAB 4: PURCHASING ANALYTICS */}
      {activeTab === 'analytics' && (
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
          <div className="rounded-2xl border border-stone-200 bg-white p-6 shadow-sm space-y-4">
            <h4 className="text-sm font-bold text-stone-900">Vendor Lead-Time &amp; Fulfillment Metrics</h4>
            <div className="space-y-4">
              {portals.map((p) => (
                <div key={p.id} className="space-y-1.5">
                  <div className="flex justify-between text-xs font-semibold text-stone-800">
                    <span>{p.brand}</span>
                    <span>{p.avgLeadTimeDays} Days Lead Time</span>
                  </div>
                  <div className="h-2 w-full overflow-hidden rounded-full bg-stone-100">
                    <div
                      className="h-full bg-[#a98a4b]"
                      style={{ width: `${Math.min(100, (p.avgLeadTimeDays / 60) * 100)}%` }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="rounded-2xl border border-stone-200 bg-white p-6 shadow-sm space-y-4">
            <h4 className="text-sm font-bold text-stone-900">Wholesale Committed vs. Retail Value</h4>
            <div className="space-y-3 text-xs">
              <div className="flex justify-between border-b border-stone-100 pb-2">
                <span className="text-stone-500">Total Open Wholesale POs:</span>
                <span className="font-mono font-bold text-stone-900">{formatCents(openValue)}</span>
              </div>
              <div className="flex justify-between border-b border-stone-100 pb-2">
                <span className="text-stone-500">Est. Retail Selling Price:</span>
                <span className="font-mono font-bold text-emerald-700">{formatCents(openValue * 2.5)}</span>
              </div>
              <div className="flex justify-between border-b border-stone-100 pb-2">
                <span className="text-stone-500">Average Retail Markup Multiple:</span>
                <span className="font-bold text-stone-800">2.5├ù (60% Gross Margin)</span>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* CREATE PO & INGEST MODAL */}
      <Modal open={showNewPoModal} onClose={() => setShowNewPoModal(false)} title="Create Purchase Order & Vendor Ingestion">
        <form onSubmit={handleCreatePo} className="space-y-4">
          {/* Quick Auto Ingest Box */}
          <div className="rounded-xl border border-sky-200 bg-sky-50/70 p-3.5 space-y-2">
            <div className="flex items-center justify-between text-xs font-bold text-sky-900">
              <span className="flex items-center gap-1.5"><Sparkles className="h-4 w-4 text-sky-600" /> Vendor Confirmation Ingestion</span>
              <button type="button" onClick={handleAutoIngest} className="text-sky-700 hover:text-sky-900 underline">Parse Text</button>
            </div>
            <textarea
              rows={2}
              placeholder="Paste raw vendor confirmation email or order payload here to auto-fill..."
              value={rawIngestText}
              onChange={(e) => setRawIngestText(e.target.value)}
              className="w-full rounded-lg border border-sky-200 bg-white p-2 text-xs outline-none"
            />
          </div>

          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <div className="space-y-1">
              <label className="text-xs font-semibold text-stone-700 block">Vendor / Designer (From Catalog)</label>
              <select value={newVendor} onChange={(e) => setNewVendor(e.target.value)} className={inputCls}>
                <option value="">-- Choose Vendor --</option>
                {catalogVendors.map(v => (
                  <option key={v.id} value={v.id}>{v.name}</option>
                ))}
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-xs font-semibold text-stone-700 block">Link Bride / Customer</label>
              <select value={newCustomer} onChange={(e) => setNewCustomer(e.target.value)} className={inputCls}>
                <option value="">Store Stock Restock (No Customer)</option>
                {brides.map((b) => (
                  <option key={b.id} value={b.name}>{b.name} (Wedding: {formatDate(b.weddingDate)})</option>
                ))}
              </select>
            </div>
          </div>

          {catalogProducts.length > 0 && (
            <div className="space-y-1">
              <label className="text-xs font-semibold text-stone-700 block">Select Product (Optional)</label>
              <select
                className={inputCls}
                onChange={(e) => {
                  const p = catalogProducts.find(prod => prod.id === e.target.value);
                  if (p) {
                    setNewItems(`${p.name} (Style: ${p.style_number})`);
                  }
                }}
              >
                <option value="">-- Choose Product --</option>
                {catalogProducts.map(p => (
                  <option key={p.id} value={p.id}>{p.name} ({p.style_number})</option>
                ))}
              </select>
            </div>
          )}

          <div className="space-y-1">
            <label className="text-xs font-semibold text-stone-700 block">Order Items &amp; Description</label>
            <input type="text" placeholder="e.g. Odette gown (sz 8) custom ivory" value={newItems} onChange={(e) => setNewItems(e.target.value)} className={inputCls} required />
          </div>

          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <div className="space-y-1">
              <label className="text-xs font-semibold text-stone-700 block">Wholesale Amount ($)</label>
              <input type="number" placeholder="1850" value={newAmountDollars} onChange={(e) => setNewAmountDollars(e.target.value)} className={inputCls} required />
            </div>

            <div className="space-y-1">
              <label className="text-xs font-semibold text-stone-700 block">Expected Arrival ETA</label>
              <input type="date" value={newEta} onChange={(e) => setNewEta(e.target.value)} className={inputCls} required />
            </div>
          </div>

          <div className="flex gap-2 justify-end pt-3 border-t border-stone-100">
            <button type="button" onClick={() => setShowNewPoModal(false)} className={btnSecondary}>Cancel</button>
            <button type="submit" className={btnPrimary} disabled={submittingPo}>
              {submittingPo ? 'Submitting...' : 'Create Purchase Order'}
            </button>
          </div>
        </form>
      </Modal>

      {/* PORTAL VAULT CREDENTIALS MODAL */}
      <Modal open={showPortalModal} onClose={() => setShowPortalModal(false)} title={editingPortal ? 'Edit Designer Portal Credentials' : 'Add Designer Portal Credentials'}>
        <form onSubmit={handleSavePortal} className="space-y-4">
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <div className="space-y-1">
