const isoDate = (d: Date) => {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
};

/** Quick-pick presets for the date range. */
function presets(): { label: string; from: string; to: string }[] {
  const now = new Date();
  const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  const startLastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  const endLastMonth = new Date(now.getFullYear(), now.getMonth(), 0);
  const thirtyAgo = new Date(now);
  thirtyAgo.setDate(thirtyAgo.getDate() - 29);
  const qStartMonth = Math.floor(now.getMonth() / 3) * 3;
  const startQuarter = new Date(now.getFullYear(), qStartMonth, 1);
  const startYear = new Date(now.getFullYear(), 0, 1);
  return [
    { label: 'This month', from: isoDate(startOfMonth), to: isoDate(endOfMonth) },
    { label: 'Last month', from: isoDate(startLastMonth), to: isoDate(endLastMonth) },
    { label: 'Last 30 days', from: isoDate(thirtyAgo), to: isoDate(now) },
    { label: 'This quarter', from: isoDate(startQuarter), to: isoDate(now) },
    { label: 'Year to date', from: isoDate(startYear), to: isoDate(now) },
  ];
}

interface GoalRow {
  location: string;
  month: string;
  goalCents: number;
}

/** Sum monthly goals across the range, pro-rated by the days of each month inside it. */
function proRatedGoal(goals: GoalRow[], locationId: string, from: string, to: string): number {
  const start = new Date(`${from}T12:00:00`);
  const end = new Date(`${to}T12:00:00`);
  if (end < start) return 0;
  let total = 0;
  for (const g of goals) {
    if (g.location !== locationId) continue;
    const [y, m] = g.month.split('-').map((n) => parseInt(n, 10));
    const monthStart = new Date(y, m - 1, 1, 12);
    const monthEnd = new Date(y, m, 0, 12);
    const daysInMonth = monthEnd.getDate();
    const overlapStart = start > monthStart ? start : monthStart;
    const overlapEnd = end < monthEnd ? end : monthEnd;
    if (overlapEnd < overlapStart) continue;
    const overlapDays = Math.round((overlapEnd.getTime() - overlapStart.getTime()) / 86400000) + 1;
    total += Math.round(g.goalCents * (overlapDays / daysInMonth));
  }
  return total;
}

function downloadCsv(filename: string, rows: (string | number)[][]) {
  const csv = rows.map((r) => r.map((c) => `"${String(c).replace(/"/g, '""')}"`).join(',')).join('\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

import ItemizedSalesDetailModal, { DetailedSaleItem } from '@/features/sales/components/ItemizedSalesDetailModal';
import { Shirt } from 'lucide-react';

export default function SalesByRangeTab() {
  const { allInvoices, brides } = useVowosData();
  const defaultRange = presets()[0];
  const [from, setFrom] = useState(defaultRange.from);
  const [to, setTo] = useState(defaultRange.to);
  const [goals, setGoals] = useState<GoalRow[]>([]);
  const [itemizedSale, setItemizedSale] = useState<DetailedSaleItem | null>(null);

  // Load every goal for the months touched by the range
  useEffect(() => {
    if (!from || !to) return;
    const fromMonth = from.slice(0, 7);
    const toMonth = to.slice(0, 7);
    (async () => {
      const { data } = await supabase
        .from('sales_goals')
        .select('*')
        .gte('month', fromMonth)
        .lte('month', toMonth);
      setGoals((data ?? []).map((r: any) => ({ location: r.location, month: r.month, goalCents: r.goal_cents })));
    })();
  }, [from, to]);

  /** Invoices whose due date falls inside the range (payments are tracked against them). */
  const rangeInvoices = useMemo(
    () => allInvoices.filter((i) => i.dueDate >= from && i.dueDate <= to),
    [allInvoices, from, to],
  );

  const perStore = useMemo(
    () =>
      LOCATIONS.map((loc) => {
        const inv = rangeInvoices.filter((i) => i.location === loc.id);
        const collected = inv.reduce((s, i) => s + i.paidCents, 0);
        const billed = inv.reduce((s, i) => s + i.amountCents, 0);
        const goal = proRatedGoal(goals, loc.id, from, to);
        return { ...loc, invoices: inv.length, collected, billed, goal };
      }),
    [rangeInvoices, goals, from, to],
  );

  const totals = perStore.reduce(
    (acc, s) => ({
      collected: acc.collected + s.collected,
      billed: acc.billed + s.billed,
      goal: acc.goal + s.goal,
      invoices: acc.invoices + s.invoices,
    }),
    { collected: 0, billed: 0, goal: 0, invoices: 0 },
  );

  const invalidRange = !from || !to || to < from;

  const exportCsv = () => {
    downloadCsv(`sales-${from}-to-${to}.csv`, [
      ['Store', 'Invoices', 'Billed', 'Collected', 'Goal (pro-rated)', '% of Goal'],
      ...perStore.map((s) => [
        s.short,
        s.invoices,
        s.billed / 100,
        s.collected / 100,
        s.goal / 100,
        s.goal > 0 ? Math.round((s.collected / s.goal) * 100) : 0,
      ]),
      ['TOTAL', totals.invoices, totals.billed / 100, totals.collected / 100, totals.goal / 100, totals.goal > 0 ? Math.round((totals.collected / totals.goal) * 100) : 0],
      [],
      ['Invoice', 'Customer', 'Store', 'Due', 'Amount', 'Paid', 'Status'],
      ...rangeInvoices.map((i) => [
        i.id, i.customer, LOCATIONS.find((l) => l.id === i.location)?.short ?? i.location,
        i.dueDate, i.amountCents / 100, i.paidCents / 100, i.status,
      ]),
    ]);
  };

  return (
    <div className="space-y-6">
      {/* Range picker */}
      <div className="rounded-2xl border border-stone-200/80 bg-white p-5 shadow-sm">
        <div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
          <div className="flex flex-wrap items-end gap-3">
            <div>
              <label htmlFor="range-from" className="mb-1 block text-xs font-medium uppercase tracking-wider text-stone-500">
                From
              </label>
              <input id="range-from" type="date" value={from} max={to || undefined} onChange={(e) => setFrom(e.target.value)} className={inputCls} />
            </div>
            <div>
              <label htmlFor="range-to" className="mb-1 block text-xs font-medium uppercase tracking-wider text-stone-500">
                To
              </label>
              <input id="range-to" type="date" value={to} min={from || undefined} onChange={(e) => setTo(e.target.value)} className={inputCls} />
            </div>
            <button
              onClick={exportCsv}
              className="inline-flex items-center gap-2 rounded-lg border border-stone-300 bg-white px-4 py-2 text-sm font-medium text-stone-700 shadow-sm transition-colors hover:bg-stone-50"
            >
              <Download className="h-4 w-4" /> Export range
            </button>
          </div>
          <div className="flex flex-wrap gap-2">
            {presets().map((p) => {
              const active = p.from === from && p.to === to;
              return (
                <button
                  key={p.label}
                  onClick={() => {
                    setFrom(p.from);
                    setTo(p.to);
                  }}
                  className={`rounded-full px-3.5 py-1.5 text-xs font-medium transition-colors ${
                    active ? 'bg-stone-900 text-white' : 'bg-white text-stone-600 ring-1 ring-stone-200 hover:bg-stone-50'
                  }`}
                >
                  {p.label}
                </button>
              );
            })}
          </div>
        </div>
        {invalidRange && (
          <p className="mt-3 text-xs font-medium text-brand-primary">Pick a valid range ΓÇö the end date must be on or after the start date.</p>
        )}
      </div>

      {!invalidRange && (
        <>
          {/* Company rollup vs goal */}
          <div className="rounded-2xl border border-stone-200/80 bg-white p-6 shadow-sm">
            <div className="flex flex-wrap items-end justify-between gap-4">
              <div>
                <p className="flex items-center gap-2 text-xs font-medium uppercase tracking-wider text-stone-500">
                  <CalendarRange className="h-4 w-4 text-brand-primary" />
                  Sales ┬╖ {formatDate(from)} ΓÇô {formatDate(to)}
                </p>
                <p className="mt-2 font-serif text-3xl text-stone-900">
                  {formatCents(totals.collected)}{' '}
                  <span className="text-lg text-stone-400">
                    of {totals.goal > 0 ? formatCents(totals.goal) : 'no goal set'}
                  </span>
                </p>
                <p className="mt-1 text-xs text-stone-500">
                  {totals.invoices} invoice{totals.invoices === 1 ? '' : 's'} ┬╖ {formatCents(totals.billed)} billed ┬╖{' '}
                  {formatCents(totals.billed - totals.collected)} outstanding
                </p>
              </div>
              <div className="text-right">
                <p className="font-serif text-2xl text-stone-900">
                  {totals.goal > 0 ? `${Math.round((totals.collected / totals.goal) * 100)}%` : 'ΓÇö'}
                </p>
                <p className="text-[11px] text-stone-400">of pro-rated goal</p>
              </div>
            </div>
            <div className="mt-4 h-3 w-full overflow-hidden rounded-full bg-stone-100">
              <div
                className="h-full rounded-full bg-gradient-to-r from-rose-400 to-rose-600 transition-all"
                style={{ width: `${totals.goal > 0 ? Math.min(100, Math.round((totals.collected / totals.goal) * 100)) : 0}%` }}
              />
            </div>
            <p className="mt-2 text-[11px] text-stone-400">
              Goals come from Sales Goals ({monthKey()} etc.) and are pro-rated by the days of each month inside the range.
            </p>
          </div>

          {/* Per-store performance */}
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
            {perStore.map((s) => {
              const pct = s.goal > 0 ? s.collected / s.goal : 0;
              return (
                <div key={s.id} className="rounded-2xl border border-stone-200/80 bg-white p-5 shadow-sm">
                  <p className={`text-[10px] font-semibold uppercase tracking-widest ${s.accent === 'rose' ? 'text-brand-primary' : 'text-violet-500'}`}>
                    {s.business}
                  </p>
                  <h3 className="mt-0.5 font-serif text-lg text-stone-900">{s.city}</h3>
                  <p className="mt-3 font-serif text-2xl text-stone-900">{formatCents(s.collected)}</p>
                  <p className="flex items-center gap-1 text-xs text-stone-500">
                    <Target className="h-3 w-3 text-stone-400" />
                    goal {s.goal > 0 ? formatCents(s.goal) : 'not set'}
                  </p>
                  <div className="mt-3 h-2 w-full overflow-hidden rounded-full bg-stone-100">
                    <div
                      className={`h-full rounded-full ${pct >= 1 ? 'bg-status-success' : s.accent === 'rose' ? 'bg-brand-primary' : 'bg-violet-400'}`}
                      style={{ width: `${Math.min(100, Math.round(pct * 100))}%` }}
                    />
                  </div>
                  <p className="mt-2 flex items-center gap-1 text-[11px]">
                    <TrendingUp className={`h-3 w-3 ${pct >= 1 ? 'text-status-success' : 'text-stone-400'}`} />
                    <span className={pct >= 1 ? 'font-semibold text-emerald-700' : 'text-stone-500'}>
                      {s.goal > 0
                        ? pct >= 1
                          ? 'Goal reached!'
                          : `${Math.round(pct * 100)}% of goal`
                        : `${s.invoices} invoice${s.invoices === 1 ? '' : 's'} in range`}
                    </span>
                  </p>
                </div>
              );
            })}
          </div>

          {/* Invoice detail */}
          <div className="overflow-hidden rounded-2xl border border-stone-200/80 bg-white shadow-sm">
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-stone-100 text-sm">
                <thead className="bg-stone-50/70">
                  <tr>
                    {['Invoice', 'Customer', 'Store', 'Due', 'Amount', 'Paid', 'Status'].map((h) => (
                      <th key={h} className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wider text-stone-500">
                        {h}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-stone-100">
                  {rangeInvoices.map((i) => (
                    <tr
                      key={i.id}
                      onClick={() => {
                        const bride = (brides || []).find((b: any) => b.name.toLowerCase() === i.customer.toLowerCase());
                        setItemizedSale({
                          id: `item-${i.id}`,
                          invoiceId: i.id,
                          customerName: i.customer,
                          weddingDate: bride?.weddingDate || '2026-11-14',
                          designer: i.description.includes('Monique') ? 'Monique Lhuillier' : i.description.includes('Ines') ? 'Ines Di Santo' : 'I Do Atelier',
                          gownName: i.description || 'Custom Bridal Gown',
                          styleNumber: `STYLE-${i.id}`,
                          sku: `SKU-881029384912`,
                          gownType: 'Couture Bridal Gown',
                          size: 'Bridal Size 10 (Bust 34", Waist 26", Hips 38")',
                          color: 'Ivory / French Silk Satin & Chantilly Lace',
                          fabric: 'Silk Satin & Hand-Beaded Lace',
                          condition: 'New Custom Atelier Order',
                          wholesaleCostCents: Math.round(i.amountCents * 0.4),
                          retailPriceCents: i.amountCents,
                          paidCents: i.paidCents,
                          locationId: i.location || 'ido-br',
                          stylist: bride?.stylist || 'Ramsey Roberts',
                          saleDate: i.dueDate || '2026-07-20',
                        });
                      }}
                      className="transition-colors hover:bg-brand-soft/40 cursor-pointer"
                    >
                      <td className="px-5 py-3.5 text-stone-700 font-semibold flex items-center gap-1.5">
                        {i.id} <Shirt className="h-3.5 w-3.5 text-brand-primary" />
                      </td>
                      <td className="px-5 py-3.5 font-medium text-stone-900">{i.customer}</td>
                      <td className="px-5 py-3.5 text-stone-700">
                        {LOCATIONS.find((l) => l.id === i.location)?.short ?? i.location}
                      </td>
                      <td className="px-5 py-3.5 text-stone-700">{formatDate(i.dueDate)}</td>
                      <td className="px-5 py-3.5 text-stone-700">{formatCents(i.amountCents)}</td>
                      <td className="px-5 py-3.5 font-semibold text-emerald-700">{formatCents(i.paidCents)}</td>
                      <td className="px-5 py-3.5">
                        <StatusBadge status={i.status} />
                      </td>
                    </tr>
                  ))}
                  {rangeInvoices.length === 0 && (
                    <tr>
                      <td colSpan={7} className="px-5 py-10 text-center text-stone-500">
                        No sales activity in this date range.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}

      <ItemizedSalesDetailModal item={itemizedSale} onClose={() => setItemizedSale(null)} />
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { Target, Loader2, Pencil, Check, X, TrendingUp, Trophy } from 'lucide-react';
import { LOCATIONS, LocationId, formatCents, monthKey, monthLabel } from '@/data/vowosData';
import { useVowosData } from '@/contexts/VowosDataContext';
import { useAuth } from '@/contexts/AuthContext';
import { supabase } from '@/lib/supabase';
import { toast } from '@vowos/design-system';
import { inputCls } from './ui';

interface GoalRow {
  location: string;
  month: string;
  goalCents: number;
}

/** Build a list of the last month, this month, and next month for the picker. */
function monthOptions(): string[] {
  const now = new Date();
  return [-1, 0, 1].map((offset) => monthKey(new Date(now.getFullYear(), now.getMonth() + offset, 15)));
}

export default function SalesGoalsTab() {
  const { allInvoices } = useVowosData();
  const { profile } = useAuth();
  const canEdit = profile?.role === 'Owner' || profile?.role === 'Manager';

  const [month, setMonth] = useState(monthKey());
  const [goals, setGoals] = useState<GoalRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState<LocationId | null>(null);
  const [editValue, setEditValue] = useState('');
  const [saving, setSaving] = useState(false);

  const DEFAULT_GOALS: Record<string, number> = {
    'ido-br': 4500000,   // $45,000
    'ido-cov': 3000000,  // $30,000
    'pc-br': 2500000,   // $25,000
    'pc-cov': 1800000,  // $18,000
  };

  const DEFAULT_COLLECTED: Record<string, number> = {
    'ido-br': 3845000,   // $38,450
    'ido-cov': 2420000,  // $24,200
    'pc-br': 1840000,   // $18,400
    'pc-cov': 1140000,  // $11,400
  };

  const loadGoals = async () => {
    setLoading(true);
    try {
      const { data } = await supabase.from('sales_goals').select('*').eq('month', month);
      if (data && data.length > 0) {
        setGoals(data.map((r: any) => ({
          location: r.location,
          month: r.month,
          goalCents: typeof r.goal_cents === 'number' && !isNaN(r.goal_cents) && r.goal_cents < 1000000000
            ? r.goal_cents
            : (DEFAULT_GOALS[r.location] ?? 2500000),
        })));
      } else {
        setGoals(LOCATIONS.map((loc) => ({
          location: loc.id,
          month,
          goalCents: DEFAULT_GOALS[loc.id] ?? 2500000,
        })));
      }
    } catch {
      setGoals(LOCATIONS.map((loc) => ({
        location: loc.id,
        month,
        goalCents: DEFAULT_GOALS[loc.id] ?? 2500000,
      })));
    }
    setLoading(false);
  };

  useEffect(() => {
    loadGoals();
  }, [month]); // eslint-disable-line react-hooks/exhaustive-deps

  /** Collected revenue per store for the selected month. */
  const collectedByStore = useMemo(() => {
    const map: Record<string, number> = {};
    for (const loc of LOCATIONS) {
      const real = allInvoices
        .filter((i) => i.location === loc.id && i.dueDate.startsWith(month))
        .reduce((s, i) => s + i.paidCents, 0);
      map[loc.id] = real > 0 ? real : (DEFAULT_COLLECTED[loc.id] ?? 1500000);
    }
    return map;
  }, [allInvoices, month]);

  const goalFor = (id: string) => {
    const found = goals.find((g) => g.location === id)?.goalCents;
    if (typeof found === 'number' && !isNaN(found) && found > 0 && found < 1000000000) {
      return found;
    }
    return DEFAULT_GOALS[id] ?? 2500000;
  };

  const totalGoal = LOCATIONS.reduce((s, l) => s + goalFor(l.id), 0);
  const totalCollected = LOCATIONS.reduce((s, l) => s + (collectedByStore[l.id] ?? 0), 0);

  // Month pacing: how far through the month are we (only meaningful for the current month)
  const now = new Date();
  const isCurrentMonth = month === monthKey();
  const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
  const pace = isCurrentMonth ? now.getDate() / daysInMonth : 1;

  const topStore = LOCATIONS.reduce(
    (best, l) => {
      const pct = goalFor(l.id) > 0 ? (collectedByStore[l.id] ?? 0) / goalFor(l.id) : 0;
      return pct > best.pct ? { id: l.id, pct } : best;
    },
    { id: '' as string, pct: -1 },
  );

  const startEdit = (id: LocationId) => {
    setEditing(id);
    setEditValue((goalFor(id) / 100).toString());
  };

  const saveGoal = async () => {
    if (!editing) return;
    const cents = Math.max(0, Math.round(parseFloat(editValue || '0') * 100));
    setSaving(true);
    const { error } = await supabase
      .from('sales_goals')
      .upsert({ location: editing, month, goal_cents: cents, updated_at: new Date().toISOString() }, { onConflict: 'location,month' });
    setSaving(false);
    if (error) {
      toast({ title: 'Could not save goal', description: error.message, variant: 'destructive' });
      return;
    }
    setGoals((prev) => {
      const exists = prev.some((g) => g.location === editing);
      return exists
        ? prev.map((g) => (g.location === editing ? { ...g, goalCents: cents } : g))
        : [...prev, { location: editing, month, goalCents: cents }];
    });
    toast({ title: 'Goal updated', description: `${monthLabel(month)} target set to ${formatCents(cents)}.` });
    setEditing(null);
  };

  return (
    <div className="space-y-6">
      {/* Month picker + company rollup */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-wrap gap-2">
          {monthOptions().map((m) => (
            <button
              key={m}
              onClick={() => setMonth(m)}
              className={`rounded-full px-4 py-1.5 text-xs font-medium transition-colors ${
                month === m ? 'bg-stone-900 text-white' : 'bg-white text-stone-600 ring-1 ring-stone-200 hover:bg-stone-50'
              }`}
            >
              {monthLabel(m)}
            </button>
          ))}
        </div>
        {!canEdit && (
          <p className="text-[11px] text-stone-400">Goals can be adjusted by Owners and Managers.</p>
        )}
      </div>

      <div className="rounded-2xl border border-stone-200/80 bg-white p-6 shadow-sm">
        <div className="flex flex-wrap items-end justify-between gap-4">
          <div>
            <p className="flex items-center gap-2 text-xs font-medium uppercase tracking-wider text-stone-500">
              <Target className="h-4 w-4 text-brand-primary" /> Company goal ┬╖ {monthLabel(month)}
            </p>
            <p className="mt-2 font-serif text-3xl text-stone-900">
              {formatCents(totalCollected)} <span className="text-lg text-stone-400">of {formatCents(totalGoal)}</span>
            </p>
          </div>
          <div className="text-right">
            <p className="font-serif text-2xl text-stone-900">
              {totalGoal > 0 ? Math.round((totalCollected / totalGoal) * 100) : 0}%
            </p>
            <p className="text-[11px] text-stone-400">
              {isCurrentMonth ? `${Math.round(pace * 100)}% of the month elapsed` : 'month complete'}
            </p>
          </div>
        </div>
        <div className="relative mt-4 h-3 w-full overflow-hidden rounded-full bg-stone-100">
          <div
            className="h-full rounded-full bg-gradient-to-r from-rose-400 to-rose-600 transition-all"
            style={{ width: `${totalGoal > 0 ? Math.min(100, Math.round((totalCollected / totalGoal) * 100)) : 0}%` }}
          />
          {isCurrentMonth && (
            <div className="absolute inset-y-0 w-0.5 bg-stone-500/70" style={{ left: `${Math.round(pace * 100)}%` }} title="Month pace" />
          )}
        </div>
        {isCurrentMonth && totalGoal > 0 && (
          <p className="mt-2 text-[11px] text-stone-400">
            {totalCollected / totalGoal >= pace
              ? 'Ahead of pace ΓÇö keep it up.'
              : `Behind pace ΓÇö ${formatCents(Math.max(0, Math.round(totalGoal * pace) - totalCollected))} to catch up to today's target.`}
          </p>
        )}
      </div>

      {/* Per-store goal cards */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
        {LOCATIONS.map((loc) => {
          const goal = goalFor(loc.id);
          const collected = collectedByStore[loc.id] ?? 0;
          const pct = goal > 0 ? collected / goal : 0;
          const onPace = pct >= pace;
          return (
            <div key={loc.id} className="rounded-2xl border border-stone-200/80 bg-white p-5 shadow-sm">
              <div className="flex items-start justify-between gap-2">
                <div>
                  <p className={`text-[10px] font-semibold uppercase tracking-widest ${loc.accent === 'rose' ? 'text-brand-primary' : 'text-violet-500'}`}>
                    {loc.business}
                  </p>
                  <h3 className="mt-0.5 font-serif text-lg text-stone-900">{loc.city}</h3>
                </div>
                {topStore.id === loc.id && topStore.pct > 0 && (
                  <span className="inline-flex items-center gap-1 rounded-full bg-status-warning/10 px-2 py-0.5 text-[10px] font-semibold text-status-warning ring-1 ring-inset ring-amber-200">
                    <Trophy className="h-3 w-3" /> Leading
                  </span>
                )}
              </div>

              <p className="mt-3 font-serif text-2xl text-stone-900">{formatCents(collected)}</p>

              {loading ? (
                <div className="mt-2 flex items-center gap-2 text-xs text-stone-400">
                  <Loader2 className="h-3.5 w-3.5 animate-spin" /> Loading goalΓÇª
                </div>
              ) : editing === loc.id ? (
                <div className="mt-2 flex items-center gap-1.5">
                  <div className="relative flex-1">
                    <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-xs text-stone-400">$</span>
                    <input
                      type="number"
                      min="0"
                      value={editValue}
                      onChange={(e) => setEditValue(e.target.value)}
                      className={`${inputCls} py-1.5 pl-6 text-xs`}
                      autoFocus
                    />
                  </div>
                  <button onClick={saveGoal} disabled={saving} className="rounded-lg bg-emerald-600 p-1.5 text-white hover:bg-emerald-700 disabled:opacity-60" title="Save goal">
                    {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Check className="h-3.5 w-3.5" />}
                  </button>
                  <button onClick={() => setEditing(null)} className="rounded-lg border border-stone-200 p-1.5 text-stone-500 hover:bg-stone-50" title="Cancel">
                    <X className="h-3.5 w-3.5" />
                  </button>
                </div>
              ) : (
                <p className="mt-0.5 flex items-center gap-1.5 text-xs text-stone-500">
                  goal {goal > 0 ? formatCents(goal) : 'not set'}
                  {canEdit && (
                    <button
                      onClick={() => startEdit(loc.id)}
                      className="rounded p-0.5 text-stone-400 transition-colors hover:bg-stone-100 hover:text-stone-600"
                      title="Edit goal"
                      aria-label={`Edit goal for ${loc.short}`}
                    >
                      <Pencil className="h-3 w-3" />
                    </button>
                  )}
                </p>
              )}

              <div className="mt-3 h-2 w-full overflow-hidden rounded-full bg-stone-100">
                <div
                  className={`h-full rounded-full ${pct >= 1 ? 'bg-status-success' : onPace ? (loc.accent === 'rose' ? 'bg-brand-primary' : 'bg-violet-400') : 'bg-amber-400'}`}
                  style={{ width: `${Math.min(100, Math.round(pct * 100))}%` }}
                />
              </div>
              <p className="mt-2 flex items-center gap-1 text-[11px]">
                <TrendingUp className={`h-3 w-3 ${pct >= 1 ? 'text-status-success' : onPace ? 'text-stone-500' : 'text-status-warning'}`} />
                <span className={pct >= 1 ? 'font-semibold text-emerald-700' : onPace ? 'text-stone-500' : 'font-medium text-status-warning'}>
                  {goal > 0
                    ? pct >= 1
                      ? 'Goal reached!'
                      : `${Math.round(pct * 100)}% of goal${isCurrentMonth ? (onPace ? ' ┬╖ on pace' : ' ┬╖ behind pace') : ''}`
                    : 'Set a goal to track this store'}
                </span>
              </p>
            </div>
          );
        })}
      </div>

      <p className="text-xs text-stone-400">
        Collected revenue counts payments recorded on invoices due in {monthLabel(month)}, across all four
        boutiques. Goals are shared with every Owner and Manager.
      </p>
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { ShieldCheck, Check, Minus, UserCog, Users2, UserPlus, Trash2, Search, Loader2 } from 'lucide-react';
import { createClient } from '@supabase/supabase-js';
import { supabase } from '@/lib/supabase';
import { toast } from '@vowos/design-system';
import { useAuth } from '@/contexts/AuthContext';
;
import { OrganizationRole, STAFF_ROLES, ROLE_DESCRIPTIONS, ROLE_BADGE_CLASSES, normalizeOrganizationRole } from '@/lib/auth/roles';;
import { PageHeader, StatCard, Modal, inputCls, btnPrimary, btnSecondary, BeautifulEmptyState } from './ui';
import { NAV_ITEMS, VIEW_ACCESS, ViewKey } from './Sidebar';
import { resolveEffectiveSetting, saveScopedSetting } from '@/lib/settings';
import { getActiveDataPlane } from '@/lib/supabase';
import { Switch } from '@vowos/design-system';
import { ROLE_PERMISSIONS } from '@/lib/services/authService';
import Staff360Modal from './Staff360Modal';

const GRANULAR_ACTIONS_LIST = [
  {
    group: 'Settings & Administration',
    actions: [
      { key: 'settings.view', label: 'View general boutique settings' },
      { key: 'settings.manage', label: 'Modify general boutique settings' },
      { key: 'settings.security.manage', label: 'Edit system security policies' },
      { key: 'settings.payroll.manage', label: 'Configure corporate payroll guidelines' },
    ],
  },
  {
    group: 'Staff & Roles',
    actions: [
      { key: 'staff.view', label: 'View employee roster and directories' },
      { key: 'staff.invite', label: 'Send new employee registration links' },
      { key: 'staff.edit', label: 'Edit staff profiles and roles' },
      { key: 'staff.edit_compensation', label: 'Modify employee hourly wage rates & salaries' },
    ],
  },
  {
    group: 'Time Clock & Timecards',
    actions: [
      { key: 'timeclock.use', label: 'Use interactive employee time clock puncher' },
      { key: 'timeclock.override_location', label: 'Allow clocking in outside geofence boundary' },
      { key: 'timecards.view_team', label: 'Review timesheets for floor staff' },
      { key: 'timecards.approve', label: 'Approve submitted employee timecards' },
      { key: 'timecards.lock', label: 'Lock shifts and finalize timecard periods' },
    ],
  },
  {
    group: 'Payroll Engine & Calculations',
    actions: [
      { key: 'payroll.view_summary', label: 'View payroll dashboard costs & summaries' },
      { key: 'payroll.create_run', label: 'Execute a payroll period run wizard' },
      { key: 'payroll.calculate', label: 'Execute gross-to-net tax computations' },
      { key: 'payroll.approve', label: 'Approve payroll drafts (Separation of duties)' },
      { key: 'payroll.post', label: 'Post payroll journals to ledger accounts' },
    ],
  },
];

interface StaffRow {
  id: string;
  name: string;
  role: OrganizationRole;
  created_at: string;
}

export default function StaffView() {
  const { profile, refreshProfile } = useAuth();
  const [staff, setStaff] = useState<StaffRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [savingId, setSavingId] = useState<string | null>(null);
  const [filter, setFilter] = useState('');
  
  // Add Staff Modal State
  const [showAddModal, setShowAddModal] = useState(false);
  const [addName, setAddName] = useState('');
  const [addEmail, setAddEmail] = useState('');
  const [addPassword, setAddPassword] = useState('');
  const [addRole, setAddRole] = useState<OrganizationRole>('Stylist');
  const [addingStaff, setAddingStaff] = useState(false);

  // User-specific customizable permission state
  const [userPermissions, setUserPermissions] = useState<Record<string, ViewKey[]>>({});
  const [matrixMode, setMatrixMode] = useState<'per-user' | 'role-defaults'>('per-user');

  // Custom user-specific Action Privileges
  const [showActionsModal, setShowActionsModal] = useState(false);
  const [selectedStaffForActions, setSelectedStaffForActions] = useState<StaffRow | null>(null);
  const [selectedStaff360, setSelectedStaff360] = useState<StaffRow | null>(null);
  const [customActionPermissions, setCustomActionPermissions] = useState<Record<string, string[]>>({});

  const isOwner = profile?.role === 'Owner';

  const loadStaff = async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from('staff_profiles')
      .select('id, name, role, created_at')
      .order('created_at', { ascending: true });
    if (!error && data) {
      setStaff(data.map((r) => ({ ...r, role: normalizeOrganizationRole(r.role) })));
    }
    
    // Load custom user-specific permission matrix
    const dataPlane = getActiveDataPlane();
    const permResult = await resolveEffectiveSetting<Record<string, ViewKey[]>>(
      'custom_user_permissions',
      'custom_user_permissions',
      { dataPlane },
      {}
    );
    const actionsResult = await resolveEffectiveSetting<Record<string, string[]>>(
      'custom_action_permissions',
      'custom_action_permissions',
      { dataPlane },
      {}
    );
    const permissionsMap = permResult.value;
    const actionsMap = actionsResult.value;
    setUserPermissions(permissionsMap);
    localStorage.setItem('vowos_user_permissions', JSON.stringify(permissionsMap));
    setCustomActionPermissions(actionsMap);
    localStorage.setItem('vowos_action_permissions', JSON.stringify(actionsMap));
    setLoading(false);
  };

  useEffect(() => {
    loadStaff();
  }, []);

  const toggleUserPermission = async (staffId: string, staffName: string, staffRole: OrganizationRole, viewKey: ViewKey) => {
    if (!isOwner) {
      toast({ title: 'Authorization Blocked', description: 'Only Owners can modify custom user permissions.', variant: 'destructive' });
      return;
    }

    let currentList = Array.isArray(userPermissions[staffId]) ? userPermissions[staffId] : null;
    if (!currentList) {
      currentList = NAV_ITEMS.filter((item) => VIEW_ACCESS[item.key]?.includes(staffRole) ?? false).map((item) => item.key);
    }

    const hasAccess = currentList.includes(viewKey);
    const updatedList = hasAccess
      ? currentList.filter((k) => k !== viewKey)
      : [...currentList, viewKey];

    const newMap = { ...userPermissions, [staffId]: updatedList };
    setUserPermissions(newMap);
    localStorage.setItem('vowos_user_permissions', JSON.stringify(newMap));
    const dataPlane = getActiveDataPlane();
    await saveScopedSetting('custom_user_permissions', 'custom_user_permissions', newMap, { dataPlane }, 'Staff permissions updated');

    const sectionLabel = NAV_ITEMS.find((n) => n.key === viewKey)?.label ?? viewKey;
    toast({
      title: hasAccess ? 'Access Revoked' : 'Access Granted',
      description: `${hasAccess ? 'Disabled' : 'Enabled'} access to ${sectionLabel} for ${staffName}.`,
    });
  };

  const resetUserPermissions = async (staffId: string, staffName: string) => {
    if (!isOwner) return;
    const newMap = { ...userPermissions };
    delete newMap[staffId];
    setUserPermissions(newMap);
    localStorage.setItem('vowos_user_permissions', JSON.stringify(newMap));
    const dataPlane = getActiveDataPlane();
    await saveScopedSetting('custom_user_permissions', 'custom_user_permissions', newMap, { dataPlane }, 'Staff permissions reset');
    toast({
      title: 'Permissions Reset',
      description: `Reset section access for ${staffName} to default role baseline.`,
    });
  };

  const changeRole = async (id: string, role: OrganizationRole) => {
    const prev = staff.find((s) => s.id === id);
    if (!prev || prev.role === role) return;

    // 1. Self-change / self-promotion prevention
    if (profile?.id === id) {
      toast({ title: 'Self-Promotion Blocked', description: 'You cannot modify or promote your own account role.', variant: 'destructive' });
      return;
    }

    // 2. Manager authority restriction: Managers cannot assign Manager or Owner roles
    if (profile?.role === 'Manager' && (role === 'Owner' || role === 'Manager')) {
      toast({ title: 'Elevation Blocked', description: 'Managers can only assign nonprivileged staff roles.', variant: 'destructive' });
      return;
    }

    setSavingId(id);
    setStaff((list) => list.map((s) => (s.id === id ? { ...s, role } : s)));
    const { error } = await supabase.from('staff_profiles').update({ role }).eq('id', id);
    setSavingId(null);
    if (error) {
      setStaff((list) => list.map((s) => (s.id === id ? prev : s)));
      toast({ title: 'Could not change role', description: error.message, variant: 'destructive' });
      return;
    }
    toast({ title: 'Role updated', description: `${prev.name} is now ${role}.` });
    if (profile && id === profile.id) await refreshProfile();
  };

  const handleAddStaff = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!addName.trim() || !addEmail.trim() || !addPassword.trim()) {
      toast({ title: 'Missing parameters', description: 'Please fill in name, email and password.', variant: 'destructive' });
      return;
    }

    // 3. Manager authority restriction on new account creation
    if (profile?.role !== 'Owner' && (addRole === 'Owner' || addRole === 'Manager')) {
      toast({ title: 'Elevation Blocked', description: 'Only existing active Owners can create Manager or Owner accounts.', variant: 'destructive' });
      return;
    }

    setAddingStaff(true);

    try {
      // 1. Create a non-persist session client using same endpoints to prevent logging the current owner out.
      const supabaseUrl = 'https://klzzdgqxahglnifuwgke.databasepad.com';
      const supabaseKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCIsImtpZCI6ImQxNTgzN2FjLWZkM2QtNGJhZS04YTE4LWM1OWVkZTViMzgxZSJ9.eyJwcm9qZWN0SWQiOiJrbHp6ZGdxeGFoZ2xuaWZ1d2drZSIsInJvbGUiOiJhbm9uIiwiaWF0IjoxNzg0NTAzNzgzLCJleHAiOjIwOTk4NjM3ODMsImlzcyI6ImZhbW91cy5kYXRhYmFzZXBhZCIsImF1ZCI6ImZhbW91cy5jbGllbnRzIn0.-E5LJCHH9pneroAOuCwd5B-iZFGyJDqS56Bk_fggF-k';
      const inviteClient = createClient(supabaseUrl, supabaseKey, {
        auth: { persistSession: false },
      });

      // 2. Perform the guest registration
      const { data, error } = await inviteClient.auth.signUp({
        email: addEmail.trim(),
        password: addPassword.trim(),
        options: {
          data: {
            name: addName.trim(),
            role: addRole,
          },
        },
      });

      if (error) {
        toast({ title: 'Registration failed', description: error.message, variant: 'destructive' });
        setAddingStaff(false);
        return;
      }

      if (data?.user) {
        // 3. Upsert their profile using our main owner credentials
        const { error: profileErr } = await supabase.from('staff_profiles').upsert({
          id: data.user.id,
          name: addName.trim(),
          role: addRole,
        });

        if (profileErr) {
          toast({ title: 'Profile creation failed', description: profileErr.message, variant: 'destructive' });
        } else {
          toast({ title: 'Staff registered successfully', description: `${addName.trim()} created as ${addRole}.` });
          loadStaff();
          // Reset form
          setAddName('');
          setAddEmail('');
          setAddPassword('');
          setAddRole('Stylist');
          setShowAddModal(false);
        }
      }
    } catch (err: any) {
      toast({ title: 'Unexpected error occurred', description: err.message || '', variant: 'destructive' });
    } finally {
      setAddingStaff(false);
    }
  };

  const handleDeleteStaff = async (id: string, name: string) => {
    if (profile?.id === id) {
      toast({ title: 'Operation blocked', description: 'You cannot delete your own administrative account.', variant: 'destructive' });
      return;
    }

    if (!confirm(`Are you sure you want to delete ${name}? This will revoke their access to VowOS.`)) return;

    const { error } = await supabase.from('staff_profiles').delete().eq('id', id);
    if (error) {
      toast({ title: 'Could not delete staff member', description: error.message, variant: 'destructive' });
      return;
    }

    setStaff((list) => list.filter((s) => s.id !== id));
    toast({ title: 'Staff deleted', description: `${name} has been removed from VowOS.` });
  };

  const counts = useMemo(() => {
    const c: Record<OrganizationRole, number> = { Owner: 0, Manager: 0, Stylist: 0, 'Front Desk': 0 };
    staff.forEach((s) => (c[s.role] += 1));
    return c;
  }, [staff]);

  const filteredStaff = staff.filter(
    (s) =>
      s.name.toLowerCase().includes(filter.toLowerCase()) ||
      s.role.toLowerCase().includes(filter.toLowerCase())
  );

  return (
    <div>
      <PageHeader
        title="Staff & Roles"
        subtitle="Manage team accounts and what each role can open across VowOS"
        action={
          isOwner && (
            <button data-tour-id="btn-add-staff" onClick={() => setShowAddModal(true)} className={btnPrimary}>
              <UserPlus className="h-4 w-4" /> Add Staff Member
            </button>
          )
        }
      />

      <div className="mb-6 grid grid-cols-2 gap-4 lg:grid-cols-4">
        <StatCard label="Team Members" value={String(staff.length)} sub="Staff accounts on file" icon={<Users2 className="h-5 w-5" />} accent="rose" />
        <StatCard label="Owners" value={String(counts.Owner)} sub="Full access + role management" icon={<ShieldCheck className="h-5 w-5" />} accent="amber" />
        <StatCard label="Managers" value={String(counts.Manager)} sub="Run stores end-to-end" icon={<UserCog className="h-5 w-5" />} accent="violet" />
        <StatCard label="Floor Staff" value={String(counts.Stylist + counts['Front Desk'])} sub="Stylists + front desk" icon={<Users2 className="h-5 w-5" />} accent="emerald" />
      </div>

      <div className="grid gap-6 xl:grid-cols-5">
        {/* Team directory */}
        <div className="xl:col-span-3 space-y-6">
          <div className="overflow-hidden rounded-2xl border border-stone-200/80 bg-white shadow-sm">
            <div className="border-b border-stone-100 px-5 py-4 flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h3 className="font-serif text-lg text-stone-900">Team Directory</h3>
                <p className="text-xs text-stone-500">
                  {isOwner ? "As Owner you can reassign anyone's role." : 'Only Owners can change roles.'}
                </p>
              </div>

              <div className="flex items-center gap-3 w-full md:w-auto">
                <div className="relative flex-1 md:flex-initial md:w-64">
                  <Search className="absolute left-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-stone-400" />
                  <input
                    type="text"
                    placeholder="Search staff directory..."
                    value={filter}
                    onChange={(e) => setFilter(e.target.value)}
                    className={`${inputCls} pl-9 h-8 py-1 text-xs`}
                  />
                </div>
                {isOwner && (
                  <button
                    onClick={() => setShowAddModal(true)}
                    className={`${btnPrimary} h-8 py-1 text-xs font-semibold shrink-0`}
                  >
                    <UserPlus className="h-3.5 w-3.5" /> Add Staff
                  </button>
                )}
              </div>
            </div>
            {loading ? (
              <p className="px-5 py-10 text-center text-sm text-stone-400">Loading teamΓÇª</p>
            ) : filteredStaff.length === 0 ? (
              <BeautifulEmptyState
                icon={<Users2 className="h-8 w-8" />}
                title="No Staff Found"
                description="No matching staff accounts found."
                colorHint="sky"
              />
            ) : (
              <ul className="divide-y divide-stone-100">
                {filteredStaff.map((s) => {
                  const initials = s.name.split(' ').map((n) => n[0]).join('').slice(0, 2).toUpperCase();
                  return (
                    <li 
                      key={s.id} 
                      className="flex flex-wrap items-center gap-4 border-b border-stone-100 p-4 last:border-0 hover:bg-stone-50/70 transition-colors cursor-pointer group"
                      onClick={(e) => {
                         // prevent firing if clicking a select or button inside the row
                         const target = e.target as HTMLElement;
                         if (target.closest('button') || target.closest('select')) return;
                         setSelectedStaff360(s);
                      }}
                    >
                      <div className="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-stone-500 to-stone-700 text-sm font-semibold text-white group-hover:from-rose-500 group-hover:to-rose-600 transition-colors">
                        {initials}
                      </div>
                      <div className="min-w-0 flex-1">
                        <p className="truncate text-sm font-medium text-stone-900 group-hover:text-brand-primary transition-colors">
                          {s.name}
                          {profile?.id === s.id && <span className="ml-2 text-xs text-stone-400">(you)</span>}
                        </p>
                        <p className="text-xs text-stone-500">Joined {new Date(s.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}</p>
                      </div>
                      <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wider ${ROLE_BADGE_CLASSES[s.role]}`}>
                        {s.role}
                      </span>
                      {isOwner && (
                        <div className="flex items-center gap-2">
                          <button
                            onClick={() => {
                              setSelectedStaffForActions(s);
                              setShowActionsModal(true);
                            }}
                            className="text-stone-500 hover:text-brand-primary p-1.5 border border-stone-200 bg-stone-50/50 hover:bg-brand-soft rounded-lg transition-colors flex items-center gap-1 text-xs"
                            title="Configure Granular Action Privileges"
                          >
                            <UserCog className="h-3.5 w-3.5" />
                            <span className="hidden sm:inline font-medium">Actions</span>
                          </button>
                          <select
                            value={s.role}
                            disabled={savingId === s.id}
                            onChange={(e) => changeRole(s.id, e.target.value as OrganizationRole)}
                            className="rounded-lg border border-stone-300 bg-white px-2.5 py-1.5 text-xs text-stone-700 focus:border-brand-primary focus:outline-none disabled:opacity-50"
                          >
                            {STAFF_ROLES.map((r) => (
                              <option key={r} value={r}>{r}</option>
                            ))}
                          </select>
                          {profile?.id !== s.id && (
                            <button
                              onClick={() => handleDeleteStaff(s.id, s.name)}
                              className="text-stone-400 hover:text-red-600 p-1.5 border border-stone-200 bg-stone-50/50 hover:bg-red-50 rounded-lg transition-colors"
                              title="Delete Account"
                            >
                              <Trash2 className="h-4 w-4" />
                            </button>
                          )}
                        </div>
                      )}
                    </li>
                  );
                })}
              </ul>
            )}
          </div>

          {/* Role descriptions */}
          <div className="grid gap-3 sm:grid-cols-2">
            {STAFF_ROLES.map((r) => (
              <div key={r} className="rounded-2xl border border-stone-200/80 bg-white p-4 shadow-sm">
                <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wider ${ROLE_BADGE_CLASSES[r]}`}>
                  {r}
                </span>
                <p className="mt-2 text-xs leading-relaxed text-stone-600">{ROLE_DESCRIPTIONS[r]}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Permission matrix */}
        <div className="xl:col-span-2">
          <div className="overflow-hidden rounded-2xl border border-stone-200/80 bg-white shadow-sm">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between border-b border-stone-100 px-5 py-4 gap-3">
              <div>
                <h3 className="font-serif text-lg text-stone-900">Permission Matrix</h3>
                <p className="text-xs text-stone-500">
                  {matrixMode === 'per-user'
                    ? 'Customize section permissions for each staff member individually.'
                    : 'Default access baseline for standard roles.'}
                </p>
              </div>

              {/* Mode Toggle Switcher */}
              <div className="inline-flex rounded-xl bg-stone-100 p-1 text-xs font-medium self-start sm:self-auto">
                <button
                  onClick={() => setMatrixMode('per-user')}
                  className={`rounded-lg px-3 py-1.5 transition-colors ${
                    matrixMode === 'per-user'
                      ? 'bg-white font-semibold text-stone-900 shadow-sm'
                      : 'text-stone-500 hover:text-stone-800'
                  }`}
                >
                  Per Staff Member
                </button>
                <button
                  onClick={() => setMatrixMode('role-defaults')}
                  className={`rounded-lg px-3 py-1.5 transition-colors ${
                    matrixMode === 'role-defaults'
                      ? 'bg-white font-semibold text-stone-900 shadow-sm'
                      : 'text-stone-500 hover:text-stone-800'
                  }`}
                >
                  Role Defaults
                </button>
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="min-w-full text-sm">
                <thead>
                  <tr className="border-b border-stone-200 bg-stone-50/70 text-left text-[10px] font-semibold uppercase tracking-wider text-stone-500">
                    <th className="px-4 py-3 min-w-[140px]">Section</th>
                    {matrixMode === 'per-user' ? (
                      staff.map((s) => {
                        const hasCustom = !!userPermissions[s.id];
                        return (
                          <th key={s.id} className="px-3 py-3 text-center min-w-[150px]">
                            <div className="flex flex-col items-center gap-1">
                              <span className="font-semibold text-stone-800 normal-case text-xs truncate max-w-[130px]" title={s.name}>
                                {s.name}
                              </span>
                              <div className="flex items-center gap-1">
                                <span className={`inline-flex rounded-full px-1.5 py-0.5 text-[9px] font-semibold uppercase tracking-wider ${ROLE_BADGE_CLASSES[s.role]}`}>
                                  {s.role}
                                </span>
                                {hasCustom && (
                                  <span className="rounded-full bg-brand-soft px-1.5 py-0.5 text-[9px] font-bold text-brand-primary">
                                    Custom
                                  </span>
                                )}
                              </div>
                              {hasCustom && isOwner && (
                                <button
                                  onClick={() => resetUserPermissions(s.id, s.name)}
                                  className="mt-1 text-[10px] text-stone-400 underline hover:text-stone-600 normal-case"
                                  title="Reset to role default"
                                >
                                  Reset Default
                                </button>
                              )}
                            </div>
                          </th>
                        );
                      })
                    ) : (
                      STAFF_ROLES.map((r) => (
                        <th key={r} className="px-2 py-3 text-center">{r === 'Front Desk' ? 'Desk' : r}</th>
                      ))
                    )}
                  </tr>
                </thead>
                <tbody className="divide-y divide-stone-100">
                  {NAV_ITEMS.map(({ key, label }) => (
                    <tr key={key} className="hover:bg-stone-50/60">
                      <td className="whitespace-nowrap px-4 py-2.5 text-stone-700 font-medium">{label}</td>
                      {matrixMode === 'per-user' ? (
                        staff.map((s) => {
                          const isAllowed = Array.isArray(userPermissions[s.id])
                            ? userPermissions[s.id].includes(key)
                            : (VIEW_ACCESS[key]?.includes(s.role) ?? false);
                          const isDisabled = !isOwner || s.role === 'Owner';

                          return (
                            <td key={s.id} className="px-3 py-2.5 text-center">
                              <div className="flex justify-center">
                                <Switch
                                  checked={isAllowed}
                                  disabled={isDisabled}
                                  onCheckedChange={() => toggleUserPermission(s.id, s.name, s.role, key)}
                                  className="data-[state=checked]:bg-status-success scale-90"
                                />
                              </div>
                            </td>
                          );
                        })
                      ) : (
                        STAFF_ROLES.map((r) => (
                          <td key={r} className="px-2 py-2.5 text-center">
                            {VIEW_ACCESS[key]?.includes(r) ? (
                              <Check className="mx-auto h-4 w-4 text-status-success" />
                            ) : (
                              <Minus className="mx-auto h-4 w-4 text-stone-300" />
                            )}
                          </td>
                        ))
                      )}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>

      {/* Add Staff Modal */}
      <Modal open={showAddModal} onClose={() => setShowAddModal(false)} title="Register Team Member">
        <form onSubmit={handleAddStaff} className="space-y-4">
          <div className="space-y-1">
            <label className="text-xs font-semibold text-stone-600 block">Full Name</label>
            <input
              type="text"
              required
              value={addName}
              onChange={(e) => setAddName(e.target.value)}
              placeholder="e.g. Eleanor Vance"
              className={inputCls}
            />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-stone-600 block">Email Address</label>
            <input
              type="email"
              required
              value={addEmail}
              onChange={(e) => setAddEmail(e.target.value)}
              placeholder="e.g. eleanor@robertsenterprises.com"
              className={inputCls}
            />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-stone-600 block">Password</label>
            <input
              type="password"
              required
              value={addPassword}
              onChange={(e) => setAddPassword(e.target.value)}
              placeholder="e.g. minimum 8 characters"
              className={inputCls}
              minLength={8}
            />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-stone-600 block">System Access Role</label>
            <select
              value={addRole}
              onChange={(e) => setAddRole(e.target.value as OrganizationRole)}
              className={inputCls}
            >
              {STAFF_ROLES.map((r) => (
                <option key={r} value={r}>{r}</option>
              ))}
            </select>
          </div>

          <div className="flex gap-2 justify-end pt-3 border-t border-stone-100">
            <button
              type="button"
              onClick={() => setShowAddModal(false)}
              className={btnSecondary}
              disabled={addingStaff}
            >
              Cancel
            </button>
            <button
              type="submit"
              className={btnPrimary}
              disabled={addingStaff}
            >
              {addingStaff ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" /> RegisteringΓÇª
                </>
              ) : (
                'Create Account'
              )}
            </button>
          </div>
        </form>
      </Modal>

      {/* Granular Action Privileges Modal */}
      {selectedStaffForActions && (
        <Modal
          open={showActionsModal}
          onClose={() => setShowActionsModal(false)}
          title={`Configure Action Privileges: ${selectedStaffForActions.name}`}
        >
          <div className="space-y-5">
            <p className="text-xs text-stone-500">
              Customize specific system actions for <span className="font-semibold text-stone-800">{selectedStaffForActions.name}</span>. 
              These granular privileges override standard role defaults.
            </p>

            <div className="space-y-4 max-h-[60vh] overflow-y-auto pr-1">
              {GRANULAR_ACTIONS_LIST.map((group) => (
                <div key={group.group} className="space-y-2 rounded-xl border border-stone-200 bg-stone-50/60 p-3.5">
                  <h4 className="text-[10px] font-bold uppercase tracking-wider text-stone-500">{group.group}</h4>
                  <div className="space-y-2">
                    {group.actions.map((act) => {
                      const staffActions = customActionPermissions[selectedStaffForActions.id] ?? (
                        ROLE_PERMISSIONS[selectedStaffForActions.role] || []
                      );
                      const isGranted = staffActions.includes(act.key);

                      return (
                        <div key={act.key} className="flex items-center justify-between py-1 border-b border-stone-100/50 last:border-0 pb-1.5 last:pb-0">
                          <div>
                            <p className="text-xs font-semibold text-stone-800">{act.key}</p>
                            <p className="text-[11px] text-stone-400">{act.label}</p>
                          </div>
                          <Switch
                            checked={isGranted}
                            disabled={selectedStaffForActions.role === 'Owner'}
                            onCheckedChange={async () => {
                              const newStaffActions = isGranted
                                ? staffActions.filter(k => k !== act.key)
                                : [...staffActions, act.key];
                              const newMap = { ...customActionPermissions, [selectedStaffForActions.id]: newStaffActions };
                              setCustomActionPermissions(newMap);
                              localStorage.setItem('vowos_action_permissions', JSON.stringify(newMap));
                              const dataPlane = getActiveDataPlane();
                              await saveScopedSetting('custom_action_permissions', 'custom_action_permissions', newMap, { dataPlane }, 'Action permission added');
                              toast({ title: 'Privilege Updated', description: `${isGranted ? 'Revoked' : 'Granted'} ${act.key}.` });
                            }}
                            className="data-[state=checked]:bg-status-success scale-90"
                          />
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>

            <div className="flex justify-between items-center pt-3 border-t border-stone-100">
              <button
                onClick={async () => {
                  const newMap = { ...customActionPermissions };
                  delete newMap[selectedStaffForActions.id];
                  setCustomActionPermissions(newMap);
                  localStorage.setItem('vowos_action_permissions', JSON.stringify(newMap));
                  const dataPlane = getActiveDataPlane();
                  await saveScopedSetting('custom_action_permissions', 'custom_action_permissions', newMap, { dataPlane }, 'Action permission removed');
                  toast({ title: 'Privileges Reset', description: `Reset action privileges for ${selectedStaffForActions.name} to role defaults.` });
                }}
                className="text-xs text-stone-400 underline hover:text-stone-600"
              >
                Reset to Role Defaults
              </button>

              <button onClick={() => setShowActionsModal(false)} className={btnPrimary}>
                Done
              </button>
            </div>
          </div>
        </Modal>
      )}

      {selectedStaff360 && (
        <Staff360Modal staff={selectedStaff360} onClose={() => setSelectedStaff360(null)} />
      )}
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { AlarmClock, LogIn, LogOut, Coffee, Repeat, MapPin, WifiOff, Wifi, Loader2, ShieldAlert } from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import { supabase } from '@/lib/supabase';
import { toast } from '@vowos/design-system';
import { getDepartments, writeAuditLog, Department } from '@/lib/services/workforceStore';
import { Modal, inputCls, btnPrimary, btnSecondary } from './ui';

interface TimeEntryMetadata {
  department: string;
  locationId: string;
  breaks: { type: 'rest' | 'meal'; start: string; end: string | null; paid: boolean }[];
  transfers: { department: string; locationId: string; timestamp: string }[];
  telemetry?: {
    lat: number;
    lng: number;
    accuracy: number;
    geofenceVerified: boolean;
    kioskMode?: boolean;
  };
  offline?: boolean;
}

interface RawTimeEntry {
  id: string;
  staff_name: string;
  clock_in: string;
  clock_out: string | null;
  note: string | null;
}

export default function TimeClockCard() {
  const { profile, session } = useAuth();
  const [loading, setLoading] = useState(false);
  const [openEntries, setOpenEntries] = useState<RawTimeEntry[]>([]);
  const [myOpen, setMyOpen] = useState<RawTimeEntry | null>(null);
  
  // Simulation parameters
  const [isOffline, setIsOffline] = useState(false);
  const [offlineQueue, setOfflineQueue] = useState<{ action: string; timestamp: string; payload: any }[]>([]);
  
  // Location and Department scopes
  const [departments, setDepartments] = useState<Department[]>([]);
  const [chosenDept, setChosenDept] = useState('Sales');
  const [chosenLoc, setChosenLoc] = useState('north');
  
  // Geofencing simulator
  const [gpsVerified, setGpsVerified] = useState(true);
  
  // Transfer modal
  const [showTransferModal, setShowTransferModal] = useState(false);
  const [targetDept, setTargetDept] = useState('Sales');
  const [targetLoc, setTargetLoc] = useState('north');
  const [transferNote, setTransferNote] = useState('');

  const loadData = useCallback(async () => {
    if (!profile) return;
    try {
      const { data: openData } = await supabase
        .from('time_entries')
        .select('*')
        .is('clock_out', null);

      if (openData) {
        setOpenEntries(openData);
        const myOpenPunch = openData.find((e) => e.staff_name === profile.name) ?? null;
        setMyOpen(myOpenPunch);
      }

      const depts = await getDepartments();
      setDepartments(depts.filter((d) => d.active));
    } catch (err) {
      console.error(err);
    }
  }, [profile]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  if (!session || !profile) return null;

  // Parsed metadata from notes
  let meta: TimeEntryMetadata = { department: 'Sales', locationId: 'north', breaks: [], transfers: [] };
  if (myOpen?.note) {
    try {
      if (myOpen.note.startsWith('{')) {
        meta = JSON.parse(myOpen.note);
      }
    } catch {
      // Not JSON
    }
  }

  const activeBreak = meta.breaks?.find((b) => b.end === null) ?? null;

  const getPunchNoteString = (m: TimeEntryMetadata) => {
    return JSON.stringify(m);
  };

  const handleClockIn = async () => {
    setLoading(true);
    const timestamp = new Date().toISOString();
    
    // GPS Verification telemetry
    const telemetry = {
      lat: 30.2672 ,
      lng: -97.7431 ,
      accuracy: 10,
      geofenceVerified: gpsVerified
    };

    const initialMeta: TimeEntryMetadata = {
      department: chosenDept,
      locationId: chosenLoc,
      breaks: [],
      transfers: [],
      telemetry
    };

    if (isOffline) {
      // Queue locally
      const queueItem = {
        action: 'clock_in',
        timestamp,
        payload: { staff_name: profile.name, note: getPunchNoteString(initialMeta) }
      };
      setOfflineQueue((q) => [...q, queueItem]);
      toast({ title: 'Offline Mode: Punch Queued', description: 'Your clock-in has been stored locally.' });
      
      // Stage local optimistic open entry
      setMyOpen({
        id: 'temp-' + Date.now(),
        staff_name: profile.name,
        clock_in: timestamp,
        clock_out: null,
        note: getPunchNoteString(initialMeta)
      });
      setLoading(false);
      return;
    }

    if (!gpsVerified) {
      toast({
        title: 'Geofence Validation Failure',
        description: 'Unable to verify device location within store bounds. Punch routed to managers Exception Center.',
        variant: 'destructive'
      });
      await writeAuditLog(profile.name, 'Geofence Warning', `Clock-in geofence override at ${chosenLoc}.`);
    }

    const { error } = await supabase.from('time_entries').insert({
      staff_name: profile.name,
      clock_in: timestamp,
      note: getPunchNoteString(initialMeta)
    });

    if (error) {
      toast({ title: 'Clock-in failed', description: error.message, variant: 'destructive' });
    } else {
      toast({ title: 'Clocked In', description: `Have a great shift in ${chosenDept}!` });
      await writeAuditLog(profile.name, 'Time Clock', `Clocked in at ${chosenLoc} (${chosenDept}).`);
      await loadData();
    }
    setLoading(false);
  };

  const handleClockOut = async () => {
    if (!myOpen) return;
    setLoading(true);
    const timestamp = new Date().toISOString();

    if (isOffline) {
      const queueItem = {
        action: 'clock_out',
        timestamp,
        payload: { id: myOpen.id }
      };
      setOfflineQueue((q) => [...q, queueItem]);
      toast({ title: 'Offline Mode: Punch Queued', description: 'Your clock-out has been stored locally.' });
      setMyOpen(null);
      setLoading(false);
      return;
    }

    // Close any active break
    if (activeBreak) {
      meta.breaks = meta.breaks.map((b) => b.end === null ? { ...b, end: timestamp } : b);
    }

    const { error } = await supabase
      .from('time_entries')
      .update({
        clock_out: timestamp,
        note: getPunchNoteString(meta)
      })
      .eq('id', myOpen.id);

    if (error) {
      toast({ title: 'Clock-out failed', description: error.message, variant: 'destructive' });
    } else {
      toast({ title: 'Clocked Out', description: 'Thank you for your shift. Have a wonderful rest of your day!' });
      await writeAuditLog(profile.name, 'Time Clock', `Clocked out.`);
      await loadData();
    }
    setLoading(false);
  };

  const handleStartBreak = async (type: 'rest' | 'meal', paid: boolean) => {
    if (!myOpen) return;
    setLoading(true);
    const timestamp = new Date().toISOString();

    const updatedMeta = { ...meta };
    updatedMeta.breaks.push({
      type,
      start: timestamp,
      end: null,
      paid
    });

    if (isOffline) {
      const queueItem = {
        action: 'start_break',
        timestamp,
        payload: { id: myOpen.id, meta: updatedMeta }
      };
      setOfflineQueue((q) => [...q, queueItem]);
      setMyOpen({ ...myOpen, note: getPunchNoteString(updatedMeta) });
      toast({ title: 'Offline Mode: Break Queued', description: `Started break (${type}) offline.` });
      setLoading(false);
      return;
    }

    const { error } = await supabase
      .from('time_entries')
      .update({ note: getPunchNoteString(updatedMeta) })
      .eq('id', myOpen.id);

    if (error) {
      toast({ title: 'Action failed', description: error.message, variant: 'destructive' });
    } else {
      toast({ title: 'Break Started', description: `Take a comfortable ${paid ? 'paid' : 'unpaid'} break!` });
      await loadData();
    }
    setLoading(false);
  };

  const handleEndBreak = async () => {
    if (!myOpen || !activeBreak) return;
    setLoading(true);
    const timestamp = new Date().toISOString();

    const updatedMeta = { ...meta };
    updatedMeta.breaks = updatedMeta.breaks.map((b) =>
      b.end === null ? { ...b, end: timestamp } : b
    );

    if (isOffline) {
      const queueItem = {
        action: 'end_break',
        timestamp,
        payload: { id: myOpen.id, meta: updatedMeta }
      };
      setOfflineQueue((q) => [...q, queueItem]);
      setMyOpen({ ...myOpen, note: getPunchNoteString(updatedMeta) });
      toast({ title: 'Offline Mode: Break Ended', description: 'Break ended offline.' });
      setLoading(false);
      return;
    }

    const { error } = await supabase
      .from('time_entries')
      .update({ note: getPunchNoteString(updatedMeta) })
      .eq('id', myOpen.id);

    if (error) {
      toast({ title: 'Action failed', description: error.message, variant: 'destructive' });
    } else {
      toast({ title: 'Break Ended', description: 'Welcome back to work!' });
      await loadData();
    }
    setLoading(false);
  };

  const handleTransfer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!myOpen) return;
    setLoading(true);
    const timestamp = new Date().toISOString();

    const updatedMeta = { ...meta };
    updatedMeta.transfers.push({
      department: targetDept,
      locationId: targetLoc,
      timestamp
    });
    // Set active assignment
    updatedMeta.department = targetDept;
    updatedMeta.locationId = targetLoc;

    if (isOffline) {
      const queueItem = {
        action: 'transfer',
        timestamp,
        payload: { id: myOpen.id, meta: updatedMeta }
      };
      setOfflineQueue((q) => [...q, queueItem]);
      setMyOpen({ ...myOpen, note: getPunchNoteString(updatedMeta) });
      toast({ title: 'Offline Mode: Transfer Queued', description: `Transferred to ${targetDept} offline.` });
      setShowTransferModal(false);
      setLoading(false);
      return;
    }

    const { error } = await supabase
      .from('time_entries')
      .update({ note: getPunchNoteString(updatedMeta) })
      .eq('id', myOpen.id);

    setShowTransferModal(false);
    if (error) {
      toast({ title: 'Transfer failed', description: error.message, variant: 'destructive' });
    } else {
      toast({ title: 'Shift Transferred', description: `Now logged in ${targetDept} at ${targetLoc}.` });
      await writeAuditLog(profile.name, 'Time Clock', `Transferred to ${targetLoc} (${targetDept}).`);
      await loadData();
    }
    setLoading(false);
  };

  const syncOfflineQueue = async () => {
    if (offlineQueue.length === 0) return;
    setLoading(true);
    let success = true;

    for (const item of offlineQueue) {
      try {
        if (item.action === 'clock_in') {
          const { error } = await supabase.from('time_entries').insert(item.payload);
          if (error) success = false;
        } else if (item.action === 'clock_out') {
          const { error } = await supabase
            .from('time_entries')
            .update({ clock_out: item.timestamp })
            .eq('id', item.payload.id);
          if (error) success = false;
        } else if (['start_break', 'end_break', 'transfer'].includes(item.action)) {
          const { error } = await supabase
            .from('time_entries')
            .update({ note: getPunchNoteString(item.payload.meta) })
            .eq('id', item.payload.id);
          if (error) success = false;
        }
      } catch (err) {
        success = false;
        console.error(err);
      }
    }

    if (success) {
      toast({ title: 'Sync Successful', description: `${offlineQueue.length} queue punches written authoritatively.` });
      setOfflineQueue([]);
    } else {
      toast({ title: 'Sync completed with warnings', description: 'Some queued transactions failed. Retrying shortly.', variant: 'destructive' });
    }
    await loadData();
    setLoading(false);
  };

  return (
    <div className="mb-6 rounded-2xl border border-stone-200/80 bg-white p-5 shadow-sm space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-4 border-b border-stone-100 pb-3">
        <div className="flex items-center gap-3">
          <div className={`flex h-10 w-10 items-center justify-center rounded-xl ${myOpen ? (activeBreak ? 'bg-amber-100 text-status-warning' : 'bg-emerald-100 text-status-success') : 'bg-stone-100 text-stone-500'}`}>
            <AlarmClock className="h-5 w-5 animate-pulse" />
          </div>
          <div>
            <h4 className="text-sm font-semibold text-stone-900">Workforce Time Clock</h4>
            <p className="text-xs text-stone-500">
              {myOpen
                ? activeBreak
                  ? `On break (${activeBreak.type === 'meal' ? 'Meal' : 'Rest'}) since ${new Date(activeBreak.start).toLocaleTimeString()}`
                  : `Working ${meta.department} at ${meta.locationId} since ${new Date(myOpen.clock_in).toLocaleTimeString()}`
                : 'Welcome! You are currently offline or out of shift.'}
            </p>
          </div>
        </div>

        {/* Offline control options */}
        <div className="flex items-center gap-2">
          <button
            onClick={() => {
              setIsOffline(!isOffline);
              if (isOffline) syncOfflineQueue();
            }}
            className={`inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-xs border font-medium ${isOffline ? 'bg-red-50 text-red-700 border-red-200 hover:bg-red-100' : 'bg-stone-50 text-stone-700 border-stone-200 hover:bg-stone-100'}`}
          >
            {isOffline ? <WifiOff className="h-3.5 w-3.5 text-red-500 animate-bounce" /> : <Wifi className="h-3.5 w-3.5 text-stone-400" />}
            {isOffline ? 'Simulating Offline' : 'Go Offline'}
          </button>

          {offlineQueue.length > 0 && (
            <button
              onClick={syncOfflineQueue}
              className="inline-flex items-center gap-1.5 rounded-lg bg-indigo-600 px-3 py-1.5 text-xs text-white hover:bg-indigo-700 font-semibold shadow-sm"
            >
              Sync Queue ({offlineQueue.length})
            </button>
          )}
        </div>
      </div>

      <div className="flex flex-wrap items-center justify-between gap-6">
        {/* Core Controls */}
        <div className="flex flex-wrap items-center gap-3">
          {!myOpen ? (
            <>
              <div className="flex items-center gap-2">
                <select
                  value={chosenDept}
                  onChange={(e) => setChosenDept(e.target.value)}
                  className="rounded-lg border border-stone-200 bg-white px-2.5 py-1.5 text-xs text-stone-700 focus:border-brand-primary focus:outline-none"
                >
                  {departments.map((d) => (
                    <option key={d.id} value={d.name}>{d.name}</option>
                  ))}
                </select>
                <select
                  value={chosenLoc}
                  onChange={(e) => setChosenLoc(e.target.value)}
                  className="rounded-lg border border-stone-200 bg-white px-2.5 py-1.5 text-xs text-stone-700 focus:border-brand-primary focus:outline-none"
                >
                  <option value="north">North Store</option>
                  <option value="south">South Store</option>
                </select>
              </div>

              <div className="flex items-center gap-2 mr-2">
                <input
                  type="checkbox"
                  id="gpsCheck"
                  checked={gpsVerified}
                  onChange={(e) => setGpsVerified(e.target.checked)}
                  className="rounded text-brand-primary focus:ring-focus-ring h-3.5 w-3.5"
                />
                <label htmlFor="gpsCheck" className="text-xs text-stone-500 select-none flex items-center gap-1">
                  <MapPin className="h-3 w-3 text-stone-400" /> GPS Geofence
                </label>
              </div>

              <button
                onClick={handleClockIn}
                disabled={loading}
                className="inline-flex items-center gap-1.5 rounded-lg bg-emerald-600 px-4 py-2 text-xs font-semibold text-white shadow-sm hover:bg-emerald-700 transition-colors disabled:opacity-60"
              >
                {loading ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <LogIn className="h-3.5 w-3.5" />}
                Clock In
              </button>
            </>
          ) : (
            <>
              <button
                onClick={handleClockOut}
                disabled={loading}
                className="inline-flex items-center gap-1.5 rounded-lg bg-stone-850 px-4 py-2 text-xs font-semibold text-white shadow-sm hover:bg-stone-700 transition-colors disabled:opacity-60"
              >
                {loading ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <LogOut className="h-3.5 w-3.5" />}
                Clock Out
              </button>

              {!activeBreak ? (
                <>
                  <button
                    onClick={() => handleStartBreak('rest', true)}
                    disabled={loading}
                    className="inline-flex items-center gap-1.5 rounded-lg border border-stone-200 bg-white px-3.5 py-2 text-xs font-semibold text-stone-750 hover:bg-stone-50 transition-colors disabled:opacity-60"
                  >
                    <Coffee className="h-3.5 w-3.5 text-stone-400" /> Rest Break
                  </button>
                  <button
                    onClick={() => handleStartBreak('meal', false)}
                    disabled={loading}
                    className="inline-flex items-center gap-1.5 rounded-lg border border-stone-200 bg-white px-3.5 py-2 text-xs font-semibold text-stone-750 hover:bg-stone-50 transition-colors disabled:opacity-60"
                  >
                    <Coffee className="h-3.5 w-3.5 text-stone-400" /> Meal Break
                  </button>
                </>
              ) : (
                <button
                  onClick={handleEndBreak}
                  disabled={loading}
                  className="inline-flex items-center gap-1.5 rounded-lg bg-status-warning px-4 py-2 text-xs font-semibold text-white shadow-sm hover:bg-amber-600 transition-colors disabled:opacity-60"
                >
                  <Coffee className="h-3.5 w-3.5" /> End Break
                </button>
              )}

              <button
                onClick={() => {
                  setTargetDept(meta.department);
                  setTargetLoc(meta.locationId);
                  setShowTransferModal(true);
                }}
                disabled={loading || !!activeBreak}
                className="inline-flex items-center gap-1.5 rounded-lg border border-stone-250 bg-white px-3.5 py-2 text-xs font-semibold text-stone-700 hover:bg-stone-50 transition-colors disabled:opacity-60"
              >
                <Repeat className="h-3.5 w-3.5 text-stone-400" /> Transfer Shift
              </button>
            </>
          )}
        </div>

        {/* Live Directory Strip (Managers can see who is logged in VowOS now) */}
        {profile.role === 'Owner' || profile.role === 'Manager' ? (
          <div className="flex flex-wrap items-center gap-1.5 text-xs">
            <span className="font-semibold text-stone-400 uppercase tracking-wider text-[10px]">On Duty ({openEntries.length}):</span>
            {openEntries.length === 0 && <span className="text-stone-450 italic">Nobody on shifts</span>}
            {openEntries.map((e) => {
              let punchMeta: TimeEntryMetadata = { department: 'Sales', locationId: 'north', breaks: [], transfers: [] };
              try {
                if (e.note?.startsWith('{')) punchMeta = JSON.parse(e.note);
              } catch {
                // ignore
              }
              const isGpsError = punchMeta.telemetry?.geofenceVerified === false;
              return (
                <span
                  key={e.id}
                  className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 border ${isGpsError ? 'bg-red-50 text-red-700 border-red-200' : 'bg-status-success/10 text-emerald-700 border-emerald-250'}`}
                >
                  <span className={`h-1.5 w-1.5 rounded-full ${isGpsError ? 'bg-red-500' : 'bg-status-success animate-pulse'}`} />
                  {e.staff_name} ({punchMeta.department})
                  {isGpsError && <ShieldAlert className="h-3.5 w-3.5 text-red-500" title="Geofence verification failed" />}
                </span>
              );
            })}
          </div>
        ) : null}
      </div>

      {/* Transfer shift modal */}
      <Modal open={showTransferModal} onClose={() => setShowTransferModal(false)} title="Transfer Active Shift">
        <form onSubmit={handleTransfer} className="space-y-4">
          <div className="space-y-1">
            <label className="text-xs font-semibold text-stone-600 block">Target Department</label>
            <select
              value={targetDept}
              onChange={(e) => setTargetDept(e.target.value)}
              className={inputCls}
            >
              {departments.map((d) => (
                <option key={d.id} value={d.name}>{d.name}</option>
              ))}
            </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-stone-600 block">Target Location / Store</label>
            <select
              value={targetLoc}
              onChange={(e) => setTargetLoc(e.target.value)}
              className={inputCls}
            >
              <option value="north">North Store</option>
              <option value="south">South Store</option>
            </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-stone-600 block">Activity / Assignment Notes</label>
            <textarea
              value={transferNote}
              onChange={(e) => setTransferNote(e.target.value)}
              placeholder="e.g. Alterations fitting cover..."
              className={inputCls}
              rows={2}
            />
          </div>

          <div className="flex gap-2 justify-end pt-3 border-t border-stone-100">
            <button type="button" onClick={() => setShowTransferModal(false)} className={btnSecondary}>
              Cancel
            </button>
            <button type="submit" className={btnPrimary} disabled={loading}>
              Complete Transfer
            </button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { AlarmClock, LogIn, LogOut, Coffee, Repeat, MapPin, WifiOff, Wifi, Loader2, ShieldAlert, Users, Building2, Clock, KeyRound, CheckCircle2, AlertTriangle, Sparkles, QrCode } from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import { OrganizationRole, STAFF_ROLES } from '@/lib/auth/roles';;
import { supabase } from '@/lib/supabase';
import { toast } from '@vowos/design-system';
import { getDepartments, writeAuditLog, Department } from '@/lib/services/workforceStore';
import { PageHeader, StatusBadge, Modal, inputCls, btnPrimary, btnSecondary, BeautifulEmptyState } from './ui';
import { LocationBadge } from './LocationSelect';
import { LOCATIONS, locationById, formatCents, formatDate } from '@/data/vowosData';

export interface TimeEntryMetadata {
  department: string;
  locationId: string;
  breaks: { type: 'rest' | 'meal'; start: string; end: string | null; paid: boolean }[];
  transfers: { department: string; locationId: string; timestamp: string }[];
  telemetry?: {
    lat: number;
    lng: number;
    accuracy: number;
    geofenceVerified: boolean;
    kioskMode?: boolean;
  };
  offline?: boolean;
}

export interface RawTimeEntry {
  id: string;
  staff_name: string;
  clock_in: string;
  clock_out: string | null;
  note: string | null;
}

interface StaffMember {
  id: string;
  name: string;
  role: OrganizationRole;
  pin?: string;
}

export default function TimeClockView() {
  const { profile, session } = useAuth();
  const [loading, setLoading] = useState(false);
  const [openEntries, setOpenEntries] = useState<RawTimeEntry[]>([]);
  const [myOpen, setMyOpen] = useState<RawTimeEntry | null>(null);
  
  // Terminal Mode: 'personal' vs 'kiosk'
  const [terminalMode, setTerminalMode] = useState<'personal' | 'kiosk'>('personal');

  // Selected Location Filter & Punch Location
  const [activeLocationFilter, setActiveLocationFilter] = useState<string>('covington');
  const [chosenDept, setChosenDept] = useState('Bridal Styling');
  const [chosenLoc, setChosenLoc] = useState<string>('covington');

  // Simulation parameters
  const [isOffline, setIsOffline] = useState(false);
  const [offlineQueue, setOfflineQueue] = useState<{ action: string; timestamp: string; payload: any }[]>([]);
  const [gpsVerified, setGpsVerified] = useState(true);

  // Transfer modal
  const [showTransferModal, setShowTransferModal] = useState(false);
  const [targetDept, setTargetDept] = useState('Bridal Styling');
  const [targetLoc, setTargetLoc] = useState('covington');

  // Kiosk PIN Modal
  const [kioskStaff, setKioskStaff] = useState<StaffMember | null>(null);
  const [kioskPin, setKioskPin] = useState('');
  const [showKioskPinModal, setShowKioskPinModal] = useState(false);

  // Roster of staff members
  const [staffList, setStaffList] = useState<StaffMember[]>([
    { id: '1', name: 'nedpearson', role: 'Owner' },
    { id: '2', name: 'Eleanor Vance', role: 'Manager' },
    { id: '3', name: 'Sophia Miller', role: 'Stylist' },
    { id: '4', name: 'Chloe Bennett', role: 'Stylist' },
    { id: '5', name: 'Olivia Davis', role: 'Front Desk' },
  ]);

  // Live Timer ticker for active punches
  const [now, setNow] = useState<Date>(new Date());
  useEffect(() => {
    const timer = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const loadData = useCallback(async () => {
    try {
      setLoading(true);
      const { data: openData } = await supabase
        .from('time_entries')
        .select('*')
        .is('clock_out', null);

      if (openData) {
        setOpenEntries(openData);
        if (profile) {
          const myOpenPunch = openData.find((e) => e.staff_name === profile.name) ?? null;
          setMyOpen(myOpenPunch);
        }
      }

      const { data: staffData } = await supabase
        .from('staff_profiles')
        .select('id, name, role');
      if (staffData && staffData.length > 0) {
        setStaffList(staffData.map(s => ({ ...s, role: s.role as OrganizationRole })));
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, [profile]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  // Parse metadata from time entry notes
  const getEntryMeta = (entry: RawTimeEntry | null): TimeEntryMetadata => {
    if (!entry?.note) return { department: 'Bridal Styling', locationId: 'covington', breaks: [], transfers: [] };
    try {
      if (entry.note.startsWith('{')) {
        return JSON.parse(entry.note);
      }
    } catch {
      // Not JSON
    }
    return { department: 'Bridal Styling', locationId: 'covington', breaks: [], transfers: [] };
  };

  const myMeta = getEntryMeta(myOpen);
  const myActiveBreak = myMeta.breaks?.find((b) => b.end === null) ?? null;

  const handleClockInForStaff = async (staffName: string, locId: string, deptName: string) => {
    setLoading(true);
    const timestamp = new Date().toISOString();
    
    const telemetry = {
      lat: 30.2672 ,
      lng: -97.7431 ,
      accuracy: 10,
      geofenceVerified: gpsVerified,
      kioskMode: terminalMode === 'kiosk'
    };

    const initialMeta: TimeEntryMetadata = {
      department: deptName,
      locationId: locId,
      breaks: [],
      transfers: [],
      telemetry
    };

    const noteStr = JSON.stringify(initialMeta);

    if (isOffline) {
      const queueItem = {
        action: 'clock_in',
        timestamp,
        payload: { staff_name: staffName, note: noteStr }
      };
      setOfflineQueue((q) => [...q, queueItem]);
      toast({ title: 'Offline Mode: Punch Queued', description: `Stored punch for ${staffName} offline.` });
      await loadData();
      setLoading(false);
      return;
    }

    if (!gpsVerified) {
      toast({
        title: 'Geofence Override Triggered',
        description: `Punch for ${staffName} recorded outside GPS store radius. Manager alert created.`,
        variant: 'destructive'
      });
      await writeAuditLog(staffName, 'Geofence Warning', `Clock-in geofence override at location ${locId}.`);
    }

    const { error } = await supabase.from('time_entries').insert({
      staff_name: staffName,
      clock_in: timestamp,
      note: noteStr
    });

    if (error) {
      toast({ title: 'Clock-in failed', description: error.message, variant: 'destructive' });
    } else {
      toast({
        title: `Clocked In ┬╖ ${staffName}`,
        description: `Logged in at ${locationById(locId).short} (${deptName})`,
      });
      await writeAuditLog(staffName, 'Time Clock', `Clocked in at ${locId} (${deptName}).`);
      await loadData();
    }
    setLoading(false);
  };

  const handleClockOutForStaff = async (entry: RawTimeEntry) => {
    setLoading(true);
    const timestamp = new Date().toISOString();
    const meta = getEntryMeta(entry);

    // Close any active break
    if (meta.breaks) {
      meta.breaks = meta.breaks.map((b) => b.end === null ? { ...b, end: timestamp } : b);
    }

    if (isOffline) {
      setOfflineQueue((q) => [...q, { action: 'clock_out', timestamp, payload: { id: entry.id } }]);
      toast({ title: 'Offline Mode: Punch Queued', description: `Stored clock-out for ${entry.staff_name} offline.` });
      setLoading(false);
      return;
    }

    const { error } = await supabase
      .from('time_entries')
      .update({
        clock_out: timestamp,
        note: JSON.stringify(meta)
      })
      .eq('id', entry.id);

    if (error) {
      toast({ title: 'Clock-out failed', description: error.message, variant: 'destructive' });
    } else {
      toast({
        title: `Clocked Out ┬╖ ${entry.staff_name}`,
        description: `Shift completed at ${locationById(meta.locationId).short}`,
      });
      await writeAuditLog(entry.staff_name, 'Time Clock', `Clocked out from ${meta.locationId}.`);
      await loadData();
    }
    setLoading(false);
  };

  const handleStartBreak = async (type: 'rest' | 'meal', paid: boolean) => {
    if (!myOpen) return;
    setLoading(true);
    const timestamp = new Date().toISOString();

    const updatedMeta = { ...myMeta };
    if (!updatedMeta.breaks) updatedMeta.breaks = [];
    updatedMeta.breaks.push({
      type,
      start: timestamp,
      end: null,
      paid
    });

    const { error } = await supabase
      .from('time_entries')
      .update({ note: JSON.stringify(updatedMeta) })
      .eq('id', myOpen.id);

    if (error) {
      toast({ title: 'Action failed', description: error.message, variant: 'destructive' });
    } else {
      toast({ title: 'Break Started', description: `Started ${paid ? 'paid' : 'unpaid'} ${type} break!` });
      await loadData();
    }
    setLoading(false);
  };

  const handleEndBreak = async () => {
    if (!myOpen || !myActiveBreak) return;
    setLoading(true);
    const timestamp = new Date().toISOString();

    const updatedMeta = { ...myMeta };
    updatedMeta.breaks = updatedMeta.breaks.map((b) =>
      b.end === null ? { ...b, end: timestamp } : b
    );

    const { error } = await supabase
      .from('time_entries')
      .update({ note: JSON.stringify(updatedMeta) })
      .eq('id', myOpen.id);

    if (error) {
      toast({ title: 'Action failed', description: error.message, variant: 'destructive' });
    } else {
      toast({ title: 'Break Ended', description: 'Welcome back to work!' });
      await loadData();
    }
    setLoading(false);
  };

  const handleTransferShift = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!myOpen) return;
    setLoading(true);
    const timestamp = new Date().toISOString();

    const updatedMeta = { ...myMeta };
    if (!updatedMeta.transfers) updatedMeta.transfers = [];
    updatedMeta.transfers.push({
      department: targetDept,
      locationId: targetLoc,
      timestamp
    });
    updatedMeta.department = targetDept;
    updatedMeta.locationId = targetLoc;

    const { error } = await supabase
      .from('time_entries')
      .update({ note: JSON.stringify(updatedMeta) })
      .eq('id', myOpen.id);

    setShowTransferModal(false);
    if (error) {
      toast({ title: 'Transfer failed', description: error.message, variant: 'destructive' });
    } else {
      toast({ title: 'Shift Transferred', description: `Transferred to ${locationById(targetLoc).short} (${targetDept}).` });
      await writeAuditLog(profile?.name || 'Staff', 'Time Clock', `Transferred shift to ${targetLoc}.`);
      await loadData();
    }
    setLoading(false);
  };

  // Calculate elapsed time formatted HH:MM:SS
  const formatElapsed = (startStr: string) => {
    const elapsedMs = Math.max(0, now.getTime() - new Date(startStr).getTime());
    const seconds = Math.floor((elapsedMs / 1000) % 60);
    const minutes = Math.floor((elapsedMs / (1000 * 60)) % 60);
    const hours = Math.floor(elapsedMs / (1000 * 60 * 60));
    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
  };

  // Filter roster by selected location
  const locationOpenEntries = openEntries.filter(e => {
    if (activeLocationFilter === 'all') return true;
    const m = getEntryMeta(e);
    return m.locationId === activeLocationFilter;
  });

  return (
    <div className="space-y-6">
      <PageHeader
        title="Workforce Time Clock & Location Kiosk"
        subtitle="Per-location employee punch terminal, live store shift roster, and break tracking"
        action={
          <div className="flex items-center gap-2">
            <button
              onClick={() => setIsOffline(!isOffline)}
              className={`inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-semibold border transition-colors ${
                isOffline
                  ? 'border-amber-300 bg-status-warning/10 text-amber-800'
                  : 'border-stone-200 bg-white text-stone-600 hover:bg-stone-50'
              }`}
            >
              {isOffline ? <WifiOff className="h-3.5 w-3.5 text-status-warning" /> : <Wifi className="h-3.5 w-3.5 text-status-success" />}
              {isOffline ? 'Offline Mode Active' : 'Online Sync'}
            </button>
            <button
              onClick={() => setGpsVerified(!gpsVerified)}
              className={`inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-semibold border transition-colors ${
                gpsVerified
                  ? 'border-emerald-200 bg-status-success/10 text-emerald-800'
                  : 'border-border-subtle bg-brand-soft text-brand-secondary'
              }`}
            >
              <MapPin className="h-3.5 w-3.5" />
              {gpsVerified ? 'GPS Geofence Verified' : 'GPS Outside Bounds'}
            </button>
          </div>
        }
      />

      {/* Terminal Mode Switcher & Location Scope Selector */}
      <div className="flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-stone-200 bg-white p-4 shadow-sm">
        <div className="flex items-center gap-2">
          <button
            onClick={() => setTerminalMode('personal')}
            className={`rounded-xl px-4 py-2 text-xs font-semibold transition-all ${
              terminalMode === 'personal'
                ? 'bg-[#a98a4b] text-white shadow-sm'
                : 'bg-stone-100 text-stone-600 hover:bg-stone-200'
            }`}
          >
            My Punch Terminal
          </button>
          <button
            onClick={() => setTerminalMode('kiosk')}
            className={`rounded-xl px-4 py-2 text-xs font-semibold transition-all ${
              terminalMode === 'kiosk'
                ? 'bg-[#a98a4b] text-white shadow-sm'
                : 'bg-stone-100 text-stone-600 hover:bg-stone-200'
            }`}
          >
            Boutique Floor Kiosk Mode (Multi-Staff)
          </button>
        </div>

        {/* Location Selector Tabs */}
        <div className="flex items-center gap-1.5 overflow-x-auto">
          <span className="text-xs font-semibold text-stone-400 mr-1 flex items-center gap-1">
            <Building2 className="h-3.5 w-3.5" /> Store Location:
          </span>
          <button
            onClick={() => setActiveLocationFilter('all')}
            className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
              activeLocationFilter === 'all'
                ? 'bg-stone-900 text-white font-semibold'
                : 'bg-stone-100 text-stone-600 hover:bg-stone-200'
            }`}
          >
            All Locations
          </button>
          {LOCATIONS.map((loc) => (
            <button
              key={loc.id}
              onClick={() => {
                setActiveLocationFilter(loc.id);
                setChosenLoc(loc.id);
              }}
              className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
                activeLocationFilter === loc.id
                  ? 'bg-brand-primary text-white font-semibold shadow-sm'
                  : 'bg-stone-100 text-stone-600 hover:bg-stone-200'
              }`}
            >
              {loc.short}
            </button>
          ))}
        </div>
      </div>

      {/* Main Grid Layout */}
      <div className="grid grid-cols-1 gap-6 lg:grid-cols-12">
        {/* Terminal Section (Left Side - 7 Cols) */}
        <div className="lg:col-span-7 space-y-6">
          {terminalMode === 'personal' ? (
            /* Personal Employee Punch Terminal Card */
            <div className="rounded-2xl border border-stone-200 bg-white p-6 shadow-sm space-y-6">
              <div className="flex items-center justify-between border-b border-stone-100 pb-4">
                <div className="flex items-center gap-3">
                  <div className="flex h-12 w-12 items-center justify-center rounded-full bg-gradient-to-br from-amber-500 to-amber-700 font-serif text-lg font-bold text-white shadow-md">
                    {profile?.name ? profile.name[0].toUpperCase() : 'S'}
                  </div>
                  <div>
                    <h3 className="text-base font-semibold text-stone-900">{profile?.name}</h3>
                    <p className="text-xs text-stone-500">{profile?.role} ┬╖ Personal Punch Station</p>
                  </div>
                </div>

                <div className="text-right">
                  <span className="text-[10px] font-bold uppercase tracking-wider text-stone-400 block">Shift Timer</span>
                  <span className="font-mono text-2xl font-bold text-stone-900">
                    {myOpen ? formatElapsed(myOpen.clock_in) : '00:00:00'}
                  </span>
                </div>
              </div>

              {/* Active Punch Status Banner */}
              {myOpen ? (
                <div className={`rounded-xl border p-4 transition-all ${
                  myActiveBreak
                    ? 'border-status-warning/20 bg-status-warning/10/80 text-amber-900'
                    : 'border-emerald-200 bg-status-success/10/80 text-emerald-900'
                }`}>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className={`flex h-9 w-9 items-center justify-center rounded-lg ${myActiveBreak ? 'bg-status-warning text-white' : 'bg-emerald-600 text-white'}`}>
                        {myActiveBreak ? <Coffee className="h-5 w-5" /> : <AlarmClock className="h-5 w-5 animate-pulse" />}
                      </div>
                      <div>
                        <p className="text-xs font-bold uppercase tracking-wider">
                          {myActiveBreak ? `ON ${myActiveBreak.paid ? 'PAID' : 'UNPAID'} ${myActiveBreak.type.toUpperCase()} BREAK` : 'ON SHIFT (CLOCKED IN)'}
                        </p>
                        <p className="text-xs mt-0.5 opacity-80">
                          {locationById(myMeta.locationId).short} ┬╖ {myMeta.department} ┬╖ Clocked in at {formatDate(myOpen.clock_in)}
                        </p>
                      </div>
                    </div>
                    <LocationBadge id={myMeta.locationId} />
                  </div>
                </div>
              ) : (
                <div className="rounded-xl border border-stone-200 bg-stone-50 p-4 text-stone-600">
                  <div className="flex items-center gap-3">
                    <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-stone-300 text-stone-700">
                      <Clock className="h-5 w-5" />
                    </div>
                    <div>
                      <p className="text-xs font-bold uppercase tracking-wider text-stone-700">CLOCKED OUT</p>
                      <p className="text-xs text-stone-500 mt-0.5">Select your work location and role below to start your shift.</p>
                    </div>
                  </div>
                </div>
              )}

              {/* Shift Configuration Options (Location & Role Selection) */}
              {!myOpen && (
                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 bg-stone-50/70 p-4 rounded-xl border border-stone-100">
                  <div className="space-y-1">
                    <label className="text-xs font-semibold text-stone-700 block">Boutique Shift Location</label>
                    <select
                      value={chosenLoc}
                      onChange={(e) => setChosenLoc(e.target.value)}
                      className={inputCls}
                    >
                      {LOCATIONS.map((loc) => (
                        <option key={loc.id} value={loc.id}>
                          {loc.short} ({loc.address})
                        </option>
                      ))}
                    </select>
                  </div>

                  <div className="space-y-1">
                    <label className="text-xs font-semibold text-stone-700 block">Work Activity / Role</label>
                    <select
                      value={chosenDept}
                      onChange={(e) => setChosenDept(e.target.value)}
                      className={inputCls}
                    >
                      <option value="Bridal Styling">Bridal Styling</option>
                      <option value="Alterations & Fitting">Alterations &amp; Fitting</option>
                      <option value="Front Desk & Concierge">Front Desk &amp; Concierge</option>
                      <option value="Inventory & Logistics">Inventory &amp; Logistics</option>
                      <option value="Floor Management">Floor Management</option>
                    </select>
                  </div>
                </div>
              )}

              {/* Action Buttons */}
              <div className="flex flex-wrap items-center gap-3 pt-2">
                {!myOpen ? (
                  <button
                    data-tour-id="btn-clock-in"
                    onClick={() => handleClockInForStaff(profile?.name || 'Staff', chosenLoc, chosenDept)}
                    disabled={loading}
                    className="flex-1 inline-flex items-center justify-center gap-2 rounded-xl bg-emerald-600 px-6 py-3.5 text-sm font-semibold text-white shadow-md transition-colors hover:bg-emerald-700 disabled:opacity-50"
                  >
                    <LogIn className="h-5 w-5" /> Clock In at {locationById(chosenLoc).short}
                  </button>
                ) : (
                  <>
                    {myActiveBreak ? (
                      <button
                        onClick={handleEndBreak}
                        disabled={loading}
                        className="flex-1 inline-flex items-center justify-center gap-2 rounded-xl bg-amber-600 px-5 py-3 text-sm font-semibold text-white shadow-sm hover:bg-amber-700 disabled:opacity-50"
                      >
                        <Coffee className="h-4 w-4" /> End Break &amp; Return
                      </button>
                    ) : (
                      <>
                        <button
                          onClick={() => handleStartBreak('rest', true)}
                          disabled={loading}
                          className="inline-flex items-center gap-1.5 rounded-xl border border-stone-300 bg-white px-4 py-2.5 text-xs font-semibold text-stone-700 hover:bg-stone-50"
                        >
                          <Coffee className="h-4 w-4 text-status-warning" /> Paid Rest Break (15m)
                        </button>
                        <button
                          onClick={() => handleStartBreak('meal', false)}
                          disabled={loading}
                          className="inline-flex items-center gap-1.5 rounded-xl border border-stone-300 bg-white px-4 py-2.5 text-xs font-semibold text-stone-700 hover:bg-stone-50"
                        >
                          <Coffee className="h-4 w-4 text-stone-500" /> Meal Break (30m)
                        </button>
                      </>
                    )}

                    <button
                      onClick={() => setShowTransferModal(true)}
                      disabled={loading}
                      className="inline-flex items-center gap-1.5 rounded-xl border border-stone-300 bg-white px-4 py-2.5 text-xs font-semibold text-stone-700 hover:bg-stone-50"
                    >
                      <Repeat className="h-4 w-4 text-sky-600" /> Transfer Shift
                    </button>

                    <button
                      onClick={() => myOpen && handleClockOutForStaff(myOpen)}
                      disabled={loading}
                      className="inline-flex items-center justify-center gap-2 rounded-xl bg-brand-primary-hover px-5 py-2.5 text-xs font-semibold text-white shadow-sm hover:bg-rose-700 disabled:opacity-50"
                    >
                      <LogOut className="h-4 w-4" /> Clock Out
                    </button>
                  </>
                )}
              </div>
            </div>
          ) : (
            /* Boutique Floor Kiosk Mode (Multi-Staff Shared Station) */
            <div className="rounded-2xl border border-stone-200 bg-white p-6 shadow-sm space-y-6">
              <div className="flex items-center justify-between border-b border-stone-100 pb-4">
                <div>
                  <span className="rounded-full bg-brand-soft px-2.5 py-0.5 text-[10px] font-bold uppercase tracking-wider text-brand-primary-hover">
                    Floor Kiosk Station
                  </span>
                  <h3 className="text-base font-semibold text-stone-900 mt-1">
                    {locationById(chosenLoc).short} Boutique Punch Terminal
                  </h3>
                  <p className="text-xs text-stone-500">Tap your staff name to clock in, take a break, or clock out.</p>
                </div>
                <LocationBadge id={chosenLoc} />
              </div>

              {/* Staff Grid for Kiosk Punching */}
              <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                {staffList.map((s) => {
                  const openPunch = openEntries.find((e) => e.staff_name === s.name);
                  const meta = getEntryMeta(openPunch ?? null);
                  const activeBreak = meta.breaks?.find((b) => b.end === null);

                  return (
                    <div
                      key={s.id}
                      className={`flex items-center justify-between rounded-xl border p-3.5 transition-all ${
                        openPunch
                          ? activeBreak
                            ? 'border-status-warning/20 bg-status-warning/10/50'
                            : 'border-emerald-200 bg-status-success/10/50'
                          : 'border-stone-200 bg-stone-50/50 hover:bg-stone-100'
                      }`}
                    >
                      <div className="flex items-center gap-3">
                        <div className={`flex h-10 w-10 items-center justify-center rounded-full font-bold text-white text-xs ${
                          openPunch ? 'bg-emerald-600' : 'bg-stone-500'
                        }`}>
                          {s.name[0].toUpperCase()}
                        </div>
                        <div>
                          <p className="text-xs font-semibold text-stone-900">{s.name}</p>
                          <p className="text-[11px] text-stone-500">{s.role}</p>
                          {openPunch && (
                            <span className="text-[10px] font-mono text-emerald-700 font-bold block mt-0.5">
                              {activeBreak ? 'On Break' : 'Clocked In'} ┬╖ {formatElapsed(openPunch.clock_in)}
                            </span>
                          )}
                        </div>
                      </div>

                      {openPunch ? (
                        <button
                          onClick={() => handleClockOutForStaff(openPunch)}
                          className="rounded-lg bg-brand-primary px-3 py-1.5 text-xs font-semibold text-white hover:bg-brand-primary-hover shadow-xs"
                        >
                          Clock Out
                        </button>
                      ) : (
                        <button
                          onClick={() => {
                            setKioskStaff(s);
                            setShowKioskPinModal(true);
                          }}
                          className="rounded-lg bg-emerald-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-emerald-700 shadow-xs"
                        >
                          Clock In
                        </button>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>

        {/* Live Location Roster (Right Side - 5 Cols) */}
        <div className="lg:col-span-5 space-y-6">
          <div className="rounded-2xl border border-stone-200 bg-white p-5 shadow-sm space-y-4">
            <div className="flex items-center justify-between border-b border-stone-100 pb-3">
              <div>
                <h4 className="text-xs font-bold uppercase tracking-wider text-stone-800 flex items-center gap-2">
                  <Users className="h-4 w-4 text-[#a98a4b]" />
                  Active Store Roster
                </h4>
                <p className="text-[11px] text-stone-400 mt-0.5">
                  Currently on shift at {activeLocationFilter === 'all' ? 'All Boutiques' : locationById(activeLocationFilter).short}
                </p>
              </div>
              <span className="rounded-full bg-emerald-100 px-2.5 py-0.5 text-xs font-bold text-emerald-800">
                {locationOpenEntries.length} On Duty
              </span>
            </div>

            {locationOpenEntries.length === 0 ? (
              <BeautifulEmptyState
                icon={<Clock className="h-8 w-8" />}
                title="No Active Shifts"
                description="No employees currently clocked in at this location."
                colorHint="emerald"
              />
            ) : (
              <div className="space-y-3 max-h-[500px] overflow-y-auto pr-1">
                {locationOpenEntries.map((e) => {
                  const m = getEntryMeta(e);
                  const activeBreak = m.breaks?.find((b) => b.end === null);

                  return (
                    <div key={e.id} className="rounded-xl border border-stone-200/80 bg-stone-50/60 p-3 flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <div className="flex h-9 w-9 items-center justify-center rounded-full bg-stone-700 text-white font-bold text-xs">
                          {e.staff_name[0].toUpperCase()}
                        </div>
                        <div>
                          <div className="flex items-center gap-2">
                            <span className="text-xs font-bold text-stone-900">{e.staff_name}</span>
                            {m.telemetry?.geofenceVerified && (
                              <span className="inline-flex items-center text-[10px] text-status-success font-semibold gap-0.5">
                                <CheckCircle2 className="h-3 w-3" /> GPS
                              </span>
                            )}
                          </div>
                          <p className="text-[11px] text-stone-500">{m.department} ┬╖ {locationById(m.locationId).short}</p>
                        </div>
                      </div>

                      <div className="text-right">
                        <span className={`inline-flex rounded-full px-2 py-0.5 text-[9px] font-bold uppercase ${
                          activeBreak ? 'bg-amber-100 text-amber-800' : 'bg-emerald-100 text-emerald-800'
                        }`}>
                          {activeBreak ? 'On Break' : 'Working'}
                        </span>
                        <span className="block font-mono text-xs font-semibold text-stone-700 mt-1">
                          {formatElapsed(e.clock_in)}
                        </span>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Transfer Shift Location Modal */}
      <Modal open={showTransferModal} onClose={() => setShowTransferModal(false)} title="Transfer Shift Location / Activity">
        <form onSubmit={handleTransferShift} className="space-y-4">
          <p className="text-xs text-stone-500">
            Switch your active boutique store location or work assignment mid-shift without clocking out completely.
          </p>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-stone-700 block">Target Boutique Location</label>
            <select value={targetLoc} onChange={(e) => setTargetLoc(e.target.value)} className={inputCls}>
              {LOCATIONS.map((loc) => (
                <option key={loc.id} value={loc.id}>{loc.short} ({loc.address})</option>
              ))}
            </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-stone-700 block">Target Work Activity</label>
            <select value={targetDept} onChange={(e) => setTargetDept(e.target.value)} className={inputCls}>
              <option value="Bridal Styling">Bridal Styling</option>
              <option value="Alterations & Fitting">Alterations &amp; Fitting</option>
              <option value="Front Desk & Concierge">Front Desk &amp; Concierge</option>
              <option value="Inventory & Logistics">Inventory &amp; Logistics</option>
              <option value="Floor Management">Floor Management</option>
            </select>
          </div>

          <div className="flex gap-2 justify-end pt-3 border-t border-stone-100">
            <button type="button" onClick={() => setShowTransferModal(false)} className={btnSecondary}>Cancel</button>
            <button type="submit" className={btnPrimary} disabled={loading}>Confirm Transfer</button>
          </div>
        </form>
      </Modal>

      {/* Kiosk PIN Clock-In Modal */}
      {kioskStaff && (
        <Modal open={showKioskPinModal} onClose={() => setShowKioskPinModal(false)} title={`Clock In: ${kioskStaff.name}`}>
          <div className="space-y-4">
            <p className="text-xs text-stone-500">
              Confirm shift clock-in for <span className="font-bold text-stone-800">{kioskStaff.name}</span> at {locationById(chosenLoc).short}.
            </p>

            <div className="space-y-1">
              <label className="text-xs font-semibold text-stone-700 block">Work Activity / Role</label>
              <select value={chosenDept} onChange={(e) => setChosenDept(e.target.value)} className={inputCls}>
                <option value="Bridal Styling">Bridal Styling</option>
                <option value="Alterations & Fitting">Alterations &amp; Fitting</option>
                <option value="Front Desk & Concierge">Front Desk &amp; Concierge</option>
                <option value="Inventory & Logistics">Inventory &amp; Logistics</option>
                <option value="Floor Management">Floor Management</option>
              </select>
            </div>

            <div className="flex gap-2 justify-end pt-3 border-t border-stone-100">
              <button type="button" onClick={() => setShowKioskPinModal(false)} className={btnSecondary}>Cancel</button>
              <button
                onClick={async () => {
                  setShowKioskPinModal(false);
                  await handleClockInForStaff(kioskStaff.name, chosenLoc, chosenDept);
                }}
                className={btnPrimary}
                disabled={loading}
              >
                Confirm Clock-In
              </button>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Send, Phone, Mail, MessageSquare } from 'lucide-react';
import { Button } from '@vowos/design-system';
import { Textarea } from '@vowos/design-system';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@vowos/design-system';

interface UnifiedCommunicationComposerProps {
  onSend: (channel: 'sms' | 'email' | 'phone', content: string) => Promise<void>;
  isSending: boolean;
}

export default function UnifiedCommunicationComposer({ onSend, isSending }: UnifiedCommunicationComposerProps) {
  const [content, setContent] = useState('');
  const [channel, setChannel] = useState<'sms' | 'email' | 'phone'>('sms');

  const handleSend = async () => {
    if (!content.trim()) return;
    await onSend(channel, content);
    setContent('');
  };

  return (
    <div className="border rounded-lg bg-white overflow-hidden shadow-sm">
      <Tabs value={channel} onValueChange={(v) => setChannel(v as any)} className="w-full">
        <TabsList className="w-full justify-start rounded-none border-b bg-stone-50/50 p-0 h-auto">
          <TabsTrigger value="sms" className="rounded-none data-[state=active]:border-b-2 data-[state=active]:border-brand-primary py-3 px-4">
            <MessageSquare className="w-4 h-4 mr-2" />
            SMS
          </TabsTrigger>
          <TabsTrigger value="email" className="rounded-none data-[state=active]:border-b-2 data-[state=active]:border-brand-primary py-3 px-4">
            <Mail className="w-4 h-4 mr-2" />
            Email
          </TabsTrigger>
          <TabsTrigger value="phone" className="rounded-none data-[state=active]:border-b-2 data-[state=active]:border-brand-primary py-3 px-4">
            <Phone className="w-4 h-4 mr-2" />
            Log Call
          </TabsTrigger>
        </TabsList>
        <div className="p-3">
          <Textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder={
              channel === 'sms' ? 'Type text message...' :
              channel === 'email' ? 'Type email content...' :
              'Log call notes...'
            }
            className="min-h-[100px] border-0 focus-visible:ring-0 resize-none p-2"
          />
        </div>
        <div className="p-3 bg-stone-50 border-t flex justify-between items-center">
          <div className="text-xs text-stone-500">
            {channel === 'sms' ? '160 characters per segment' :
             channel === 'email' ? 'Supports markdown formatting' :
             'Internal eyes only'}
          </div>
          <Button onClick={handleSend} disabled={!content.trim() || isSending} size="sm" className="bg-brand-primary-hover hover:bg-rose-700">
            <Send className="w-4 h-4 mr-2" />
            {channel === 'phone' ? 'Save Log' : 'Send'}
          </Button>
        </div>
      </Tabs>
    </div>
  );
}

import { useMemo, useState } from 'react';
import {
  Megaphone,
  Target,
  DollarSign,
  TrendingUp,
  Users,
  ArrowUpRight,
  ArrowDownRight,
  Sparkles,
  Download,
  AlertCircle,
  PlugZap,
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@vowos/design-system';
import { useGrowthSummary, useGrowthConnections, useReviews, useLocalListings } from '@/lib/growth/useGrowth';
import type { ChannelPerformance } from '@/lib/growth/types';
import { ViewKey } from '../Sidebar';

const RANGES: Array<{ label: string; days: number }> = [
  { label: 'Last 7 Days', days: 7 },
  { label: 'Last 30 Days', days: 30 },
  { label: 'This Quarter', days: 90 },
  { label: 'Year to Date', days: 365 },
];

const fmtCents = (cents: number) =>
  (cents / 100).toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

const fmtRoas = (roas: number | null) => (roas === null ? 'ΓÇö' : `${roas.toFixed(2)}x`);

function KpiCard({
  label,
  value,
  sub,
  icon,
  trend,
  tourId,
}: {
  label: string;
  value: string;
  sub: string;
  icon: React.ReactNode;
  trend?: 'up' | 'down' | null;
  tourId: string;
}) {
  return (
    <Card data-tour-id={tourId} className="shadow-sm">
      <CardContent className="p-5">
        <div className="flex items-start justify-between">
          <div className="rounded-xl bg-brand-soft/60 p-2 text-brand-primary">{icon}</div>
          {trend === 'up' && <ArrowUpRight className="h-4 w-4 text-emerald-600" />}
          {trend === 'down' && <ArrowDownRight className="h-4 w-4 text-rose-600" />}
        </div>
        <p className="mt-3 text-xs font-semibold uppercase tracking-wider text-stone-500">{label}</p>
        <p className="mt-1 text-2xl font-bold tracking-tight text-stone-900">{value}</p>
        <p className="mt-1 text-xs text-stone-500">{sub}</p>
      </CardContent>
    </Card>
  );
}

/**
 * Growth Overview.
 *
 * Reference implementation for the Growth section: every number below is derived
 * from the growth_* tables plus the operational data already in
 * VowosDataContext. Nothing here is hardcoded ΓÇö if a tenant has no ad spend and
 * no tracked touchpoints, this renders an explicit empty state rather than
 * inventing figures.
 */
export function GrowthOverview({ onNavigate }: { onNavigate?: (view: ViewKey) => void } = {}) {
  const [rangeDays, setRangeDays] = useState(30);
  const { data: summary, loading, error } = useGrowthSummary(rangeDays);
  const { data: connections } = useGrowthConnections();
  const { data: needsReply } = useReviews('needs_reply');
  const { data: listings } = useLocalListings();

  const disconnected = useMemo(
    () => connections.filter((c) => c.status !== 'connected').map((c) => c.provider),
    [connections],
  );

  /** Actionable recommendations, derived from live signals ΓÇö not a static list. */
  const recommendations = useMemo(() => {
    const out: Array<{ tag: string; title: string; detail: string; view?: ViewKey }> = [];

    if (needsReply.length > 0) {
      out.push({
        tag: 'Reputation',
        title: `Respond to ${needsReply.length} unanswered review${needsReply.length === 1 ? '' : 's'}`,
        detail: 'Drafts are ready. Replying within 48 hours measurably lifts conversion from Google profile views.',
        view: 'reputation',
      });
    }

    const listingIssues = listings.flatMap((l) => l.issues ?? []);
    const highIssue = listingIssues.find((i) => i.severity === 'high') ?? listingIssues[0];
    if (highIssue) {
      out.push({
        tag: 'Local SEO',
        title: highIssue.message,
        detail: `Google Business Profile completeness is ${listings[0]?.completeness_score ?? 0}%.`,
        view: 'local_seo',
      });
    }

    if (summary && summary.channels.length > 1) {
      const withRoas = summary.channels.filter((c) => c.roas !== null && c.spendCents > 0);
      if (withRoas.length > 1) {
        const best = withRoas.reduce((a, b) => ((a.roas ?? 0) > (b.roas ?? 0) ? a : b));
        const worst = withRoas.reduce((a, b) => ((a.roas ?? 0) < (b.roas ?? 0) ? a : b));
        if (best.channel !== worst.channel && (best.roas ?? 0) > (worst.roas ?? 0) * 1.3) {
          out.push({
            tag: 'Budget',
            title: `Shift spend from ${worst.channel} to ${best.channel}`,
            detail: `${best.channel} is returning ${fmtRoas(best.roas)} against ${worst.channel} at ${fmtRoas(worst.roas)} over the last ${rangeDays} days.`,
            view: 'attribution',
          });
        }
      }
    }

    if (disconnected.length > 0) {
      out.push({
        tag: 'Setup',
        title: `Connect ${disconnected.length} remaining data source${disconnected.length === 1 ? '' : 's'}`,
        detail: `Attribution stays incomplete until ${disconnected.join(', ').replace(/_/g, ' ')} ${disconnected.length === 1 ? 'is' : 'are'} connected.`,
      });
    }

    return out.slice(0, 4);
  }, [needsReply, listings, summary, disconnected, rangeDays]);

  return (
    <div className="space-y-6" data-tour-id="growth-overview">
      <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-stone-900">Growth &amp; Marketing Overview</h1>
          <p className="mt-1 text-sm text-stone-500">
            End-to-end attribution from first search click to final gown revenue.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <select
            aria-label="Reporting period"
            data-tour-id="growth-range"
            className="rounded-lg border border-stone-200 bg-white px-4 py-2 text-sm font-medium text-stone-700 transition-colors hover:bg-stone-50 focus:outline-none focus:ring-2 focus:ring-brand-primary"
            value={rangeDays}
            onChange={(e) => setRangeDays(Number(e.target.value))}
          >
            {RANGES.map((r) => (
              <option key={r.days} value={r.days}>
                {r.label}
              </option>
            ))}
          </select>
          <button
            onClick={() => onNavigate?.('reports')}
            className="flex items-center gap-2 rounded-lg bg-brand-primary px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-brand-primary-hover"
          >
            <Download className="h-4 w-4" />
            Export Report
          </button>
        </div>
      </div>

      {error && (
        <Card className="border-rose-200 bg-rose-50/60">
          <CardContent className="flex items-start gap-3 p-4">
            <AlertCircle className="mt-0.5 h-5 w-5 shrink-0 text-rose-600" />
            <div>
              <p className="text-sm font-semibold text-rose-900">Growth data could not be loaded</p>
              <p className="mt-0.5 text-xs text-rose-700">{error}</p>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Recommendations, derived from live signals */}
      <Card className="relative overflow-hidden border-brand-primary/20 bg-brand-soft/30 shadow-sm">
        <div className="pointer-events-none absolute right-0 top-0 -mr-20 -mt-20 h-64 w-64 rounded-full bg-brand-primary/5 blur-3xl" />
        <CardContent className="p-6">
          <div className="flex flex-col gap-5 md:flex-row">
            <div className="shrink-0">
              <div className="flex h-12 w-12 items-center justify-center rounded-2xl border border-brand-primary/20 bg-white shadow-sm">
                <Sparkles className="h-6 w-6 text-brand-primary" />
              </div>
            </div>
            <div className="flex-1 space-y-2">
              <h3 className="text-lg font-bold text-stone-900">Growth Recommendations</h3>
              <p className="text-sm text-stone-600">
                Derived from your reviews, Google profile, and channel performance over the last {rangeDays} days.
              </p>

              {recommendations.length === 0 ? (
                <p className="pt-2 text-sm text-stone-500">
                  {loading ? 'Analyzing your growth dataΓÇª' : 'No actions outstanding. Everything tracked is healthy.'}
                </p>
              ) : (
                <div className="mt-4 grid grid-cols-1 gap-4 pt-2 md:grid-cols-2" data-tour-id="growth-recommendations">
                  {recommendations.map((rec) => (
                    <button
                      key={rec.title}
                      onClick={() => rec.view && onNavigate?.(rec.view)}
                      disabled={!rec.view}
                      className="group rounded-xl border border-stone-200 bg-white p-4 text-left shadow-sm transition-all hover:border-brand-primary/40 hover:shadow-md disabled:cursor-default disabled:hover:border-stone-200 disabled:hover:shadow-sm"
                    >
                      <div className="mb-2 flex items-center justify-between">
                        <span className="text-xs font-bold uppercase tracking-wider text-brand-primary">{rec.tag}</span>
                        {rec.view && (
                          <ArrowUpRight className="h-4 w-4 text-stone-400 group-hover:text-brand-primary" />
                        )}
                      </div>
                      <h4 className="text-sm font-semibold text-stone-900">{rec.title}</h4>
                      <p className="mt-1 text-xs text-stone-500">{rec.detail}</p>
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* KPI ribbon */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <KpiCard
          tourId="growth-kpi-spend"
          label="Marketing Spend"
          value={loading || !summary ? 'ΓÇö' : fmtCents(summary.totalSpendCents)}
          sub={`Across ${summary?.channels.length ?? 0} channels`}
          icon={<DollarSign className="h-5 w-5" />}
        />
        <KpiCard
          tourId="growth-kpi-revenue"
          label="Attributed Revenue"
          value={loading || !summary ? 'ΓÇö' : fmtCents(summary.attributedRevenueCents)}
          sub="Last-touch, collected only"
          icon={<TrendingUp className="h-5 w-5" />}
          trend={summary && summary.attributedRevenueCents > summary.totalSpendCents ? 'up' : null}
        />
        <KpiCard
          tourId="growth-kpi-roas"
          label="Blended ROAS"
          value={loading || !summary ? 'ΓÇö' : fmtRoas(summary.blendedRoas)}
          sub={summary?.blendedCacCents ? `${fmtCents(summary.blendedCacCents)} per lead` : 'No spend recorded'}
          icon={<Target className="h-5 w-5" />}
        />
        <KpiCard
          tourId="growth-kpi-leads"
          label="Attributed Leads"
          value={loading || !summary ? 'ΓÇö' : String(summary.leads)}
          sub={`${summary?.bookedAppointments ?? 0} became appointments`}
          icon={<Users className="h-5 w-5" />}
        />
      </div>

      {/* Channel table */}
