import { useState } from 'react';
import { 
  Dialog, 
  DialogContent, 
  DialogHeader, 
  DialogTitle, 
  DialogDescription,
  DialogFooter
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { supabase } from '@/lib/supabase';
import { toast } from 'sonner';
import { Loader2, Store, Clock, Calculator, Users } from 'lucide-react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

interface OnboardingWizardModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  businessId: string | null;
  onComplete: () => void;
}

export function OnboardingWizardModal({ open, onOpenChange, businessId, onComplete }: OnboardingWizardModalProps) {
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);

  // Form State
  const [locationName, setLocationName] = useState('Main Location');
  const [taxRate, setTaxRate] = useState('8.5');
  const [currency, setCurrency] = useState('USD');
  const [openingTime, setOpeningTime] = useState('09:00');
  const [closingTime, setClosingTime] = useState('18:00');

  const handleNext = async () => {
    if (step < 4) {
      setStep(step + 1);
    } else {
      await handleComplete();
    }
  };

  const handleComplete = async () => {
    if (!businessId) return;
    setLoading(true);
    try {
      // 1. Create Location
      const { data: locData, error: locError } = await supabase
        .from('locations')
        .insert({
          business_id: businessId,
          name: locationName,
          short_name: locationName.substring(0, 3).toUpperCase(),
          timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
          status: 'ACTIVE'
        })
        .select()
        .single();

      if (locError) throw locError;

      // 2. Set Default Tax Rate Setting
      const { error: settingsError } = await supabase
        .from('settings')
        .upsert({
          business_id: businessId,
          location_id: locData.id,
          setting_namespace: 'finance',
          setting_key: 'default_tax_rate',
          setting_value: taxRate,
          data_plane: 'vowos'
        });

      if (settingsError) throw settingsError;

      // 3. Mark Onboarding as COMPLETED on the business
      const { error: busError } = await supabase
        .from('businesses')
        .update({ onboarding_status: 'COMPLETED' })
        .eq('id', businessId);
      
      if (busError) throw busError;

      toast.success('Workspace setup complete!');
      onComplete();
      onOpenChange(false);
    } catch (err: any) {
      console.error('Onboarding Error:', err);
      toast.error(err.message || 'Failed to save setup data');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle>Complete Your Workspace Setup</DialogTitle>
          <DialogDescription>
            Step {step} of 4: Let's get the essentials configured.
          </DialogDescription>
        </DialogHeader>

        <div className="py-6">
          {step === 1 && (
            <div className="space-y-4 animate-in slide-in-from-right-4">
              <div className="flex items-center gap-4 mb-6 text-brand-primary">
                <Store className="h-8 w-8" />
                <h3 className="text-lg font-semibold text-stone-900">Your First Location</h3>
              </div>
              <p className="text-sm text-stone-500 mb-4">Every business needs at least one physical or virtual location to manage inventory and appointments.</p>
              <div className="space-y-2">
                <Label>Location Name</Label>
                <Input 
                  value={locationName} 
                  onChange={(e) => setLocationName(e.target.value)}
                  placeholder="e.g. Downtown Boutique"
                />
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-4 animate-in slide-in-from-right-4">
              <div className="flex items-center gap-4 mb-6 text-brand-primary">
                <Clock className="h-8 w-8" />
                <h3 className="text-lg font-semibold text-stone-900">Operating Hours</h3>
              </div>
              <p className="text-sm text-stone-500 mb-4">Set the default opening hours for {locationName}. You can adjust these for specific days later.</p>
              
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>Opening Time</Label>
                  <Input 
                    type="time" 
                    value={openingTime} 
                    onChange={(e) => setOpeningTime(e.target.value)} 
                  />
                </div>
                <div className="space-y-2">
                  <Label>Closing Time</Label>
                  <Input 
                    type="time" 
                    value={closingTime} 
                    onChange={(e) => setClosingTime(e.target.value)} 
                  />
                </div>
              </div>
            </div>
          )}

          {step === 3 && (
            <div className="space-y-4 animate-in slide-in-from-right-4">
              <div className="flex items-center gap-4 mb-6 text-brand-primary">
                <Calculator className="h-8 w-8" />
                <h3 className="text-lg font-semibold text-stone-900">Financial Settings</h3>
              </div>
              <p className="text-sm text-stone-500 mb-4">Configure defaults for invoicing and point of sale.</p>
              
              <div className="space-y-2 mb-4">
                <Label>Default Currency</Label>
                <Select value={currency} onValueChange={setCurrency}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="USD">USD ($)</SelectItem>
                    <SelectItem value="CAD">CAD ($)</SelectItem>
                    <SelectItem value="GBP">GBP (┬ú)</SelectItem>
                    <SelectItem value="EUR">EUR (Γé¼)</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>Default Sales Tax Rate (%)</Label>
                <Input 
                  type="number" 
                  step="0.01"
                  value={taxRate} 
                  onChange={(e) => setTaxRate(e.target.value)} 
                />
              </div>
            </div>
          )}

          {step === 4 && (
            <div className="space-y-4 animate-in slide-in-from-right-4 text-center py-4">
              <div className="flex justify-center mb-4">
                <div className="h-16 w-16 bg-brand-primary/10 text-brand-primary rounded-full flex items-center justify-center">
                  <Users className="h-8 w-8" />
                </div>
              </div>
              <h3 className="text-xl font-bold text-stone-900">You're ready to go!</h3>
              <p className="text-sm text-stone-500">
                You can always add staff members, update your hours, or adjust tax settings in the main Settings area.
              </p>
            </div>
          )}
        </div>

        <DialogFooter className="flex justify-between w-full sm:justify-between">
          <Button 
            variant="outline" 
            onClick={() => setStep(step - 1)} 
            disabled={step === 1 || loading}
          >
            Back
          </Button>
          <Button onClick={handleNext} disabled={loading}>
            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            {step === 4 ? 'Finish Setup' : 'Continue'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { Button } from '@vowos/design-system';
import { Badge } from '@vowos/design-system';
import { Popover, PopoverContent, PopoverTrigger } from '@vowos/design-system';
import { Calendar } from '@vowos/design-system';
import { format, subDays, startOfWeek, endOfWeek, startOfMonth, endOfMonth, startOfQuarter, endOfQuarter, startOfYear, endOfYear, subMonths } from 'date-fns';
import { Department } from '@/lib/services/workforceStore';
import { 
  Calendar as CalendarIcon, 
  MapPin, 
  Building2, 
  Users, 
  Filter, 
  RefreshCw 
} from 'lucide-react';

export interface PayrollScope {
  startDate: string;
  endDate: string;
  businessId: string;
  locations: string[]; // ['all'] or array of IDs
  payGroup: string; // 'all' or specific
  department: string; // 'all' or specific
  employeeSearch: string;
}

interface PayrollScopeBarProps {
  onScopeChange: (scope: PayrollScope) => void;
  departments: Department[];
}

export function PayrollScopeBar({ onScopeChange, departments }: PayrollScopeBarProps) {
  const [searchParams, setSearchParams] = useSearchParams();

  const [dateRange, setDateRange] = useState<{ from: Date; to?: Date }>({
    from: searchParams.get('start') ? new Date(searchParams.get('start')!) : startOfMonth(new Date()),
    to: searchParams.get('end') ? new Date(searchParams.get('end')!) : endOfMonth(new Date())
  });

  const [businessId, setBusinessId] = useState(searchParams.get('business') || 'roberts-enterprises');
  const [locations, setLocations] = useState<string[]>(searchParams.get('locations')?.split(',') || ['all']);
  const [payGroup, setPayGroup] = useState(searchParams.get('group') || 'all');
  const [department, setDepartment] = useState(searchParams.get('dept') || 'all');
  const [employeeSearch, setEmployeeSearch] = useState(searchParams.get('q') || '');

  // Synchronize state to URL and notify parent
  useEffect(() => {
    const scope: PayrollScope = {
      startDate: dateRange.from ? format(dateRange.from, 'yyyy-MM-dd') : '',
      endDate: dateRange.to ? format(dateRange.to, 'yyyy-MM-dd') : dateRange.from ? format(dateRange.from, 'yyyy-MM-dd') : '',
      businessId,
      locations,
      payGroup,
      department,
      employeeSearch
    };

    const newParams = new URLSearchParams(searchParams);
    if (scope.startDate) newParams.set('start', scope.startDate);
    if (scope.endDate) newParams.set('end', scope.endDate);
    newParams.set('business', scope.businessId);
    newParams.set('locations', scope.locations.join(','));
    newParams.set('group', scope.payGroup);
    newParams.set('dept', scope.department);
    if (scope.employeeSearch) newParams.set('q', scope.employeeSearch);
    else newParams.delete('q');

    setSearchParams(newParams, { replace: true });
    onScopeChange(scope);
  }, [dateRange, businessId, locations, payGroup, department, employeeSearch]);

  const handlePresetDate = (preset: string) => {
    const today = new Date();
    let from = today;
    let to = today;

    switch (preset) {
      case 'this_week':
        from = startOfWeek(today);
        to = endOfWeek(today);
        break;
      case 'last_week':
        from = startOfWeek(subDays(today, 7));
        to = endOfWeek(subDays(today, 7));
        break;
      case 'mtd':
        from = startOfMonth(today);
        to = today;
        break;
      case 'prev_month':
        from = startOfMonth(subMonths(today, 1));
        to = endOfMonth(subMonths(today, 1));
        break;
      case 'qtd':
        from = startOfQuarter(today);
        to = today;
        break;
      case 'ytd':
        from = startOfYear(today);
        to = today;
        break;
      case 'current_period':
        // Simulate current period to match instructions: July 16 - 31
        from = new Date(today.getFullYear(), 6, 16);
        to = new Date(today.getFullYear(), 6, 31);
        break;
      case 'prev_period':
        from = new Date(today.getFullYear(), 6, 1);
        to = new Date(today.getFullYear(), 6, 15);
        break;
    }
    setDateRange({ from, to });
  };

  const clearFilters = () => {
    setLocations(['all']);
    setPayGroup('all');
    setDepartment('all');
    setEmployeeSearch('');
  };

  const formatDisplayDate = () => {
    if (!dateRange.from) return 'Select date range';
    if (dateRange.from && !dateRange.to) return format(dateRange.from, 'MMM d, yyyy');
    return `${format(dateRange.from, 'MMM d, yyyy')} ΓÇô ${format(dateRange.to, 'MMM d, yyyy')}`;
  };

  return (
    <div className="bg-white border-b sticky top-0 z-10 p-3 flex flex-wrap items-center gap-3 shadow-sm text-sm">
      
      {/* Date Range Picker */}
      <Popover>
        <PopoverTrigger asChild>
          <Button variant="outline" className="flex items-center gap-2 font-medium">
            <CalendarIcon className="w-4 h-4 text-status-info" />
            {formatDisplayDate()}
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-auto p-4 flex gap-4" align="start">
          <div className="flex flex-col gap-2 w-[160px] border-r pr-4">
            <h4 className="font-semibold text-xs text-text-muted uppercase tracking-wider mb-2">Presets</h4>
            <Button variant="ghost" size="sm" className="justify-start" onClick={() => handlePresetDate('current_period')}>Current Pay Period</Button>
            <Button variant="ghost" size="sm" className="justify-start" onClick={() => handlePresetDate('prev_period')}>Previous Pay Period</Button>
            <Button variant="ghost" size="sm" className="justify-start" onClick={() => handlePresetDate('this_week')}>This Week</Button>
            <Button variant="ghost" size="sm" className="justify-start" onClick={() => handlePresetDate('last_week')}>Last Week</Button>
            <Button variant="ghost" size="sm" className="justify-start" onClick={() => handlePresetDate('mtd')}>Month to Date</Button>
            <Button variant="ghost" size="sm" className="justify-start" onClick={() => handlePresetDate('prev_month')}>Previous Month</Button>
            <Button variant="ghost" size="sm" className="justify-start" onClick={() => handlePresetDate('qtd')}>Quarter to Date</Button>
            <Button variant="ghost" size="sm" className="justify-start" onClick={() => handlePresetDate('ytd')}>Year to Date</Button>
          </div>
          <Calendar
            mode="range"
            selected={dateRange}
            onSelect={(range) => range && setDateRange({ from: range.from!, to: range.to })}
            numberOfMonths={2}
          />
        </PopoverContent>
      </Popover>

      <div className="h-6 w-px bg-gray-200 mx-1"></div>

      {/* Business Selector */}
      <div className="flex items-center gap-2">
        <Building2 className="w-4 h-4 text-text-muted" />
        <select 
          className="bg-transparent font-medium border-none outline-none cursor-pointer"
          value={businessId}
          onChange={(e) => setBusinessId(e.target.value)}
        >
          <option value="roberts-enterprises">The Boutique</option>
        </select>
      </div>

      <div className="h-6 w-px bg-gray-200 mx-1"></div>

      {/* Location Selector */}
      <div className="flex items-center gap-2">
        <MapPin className="w-4 h-4 text-text-muted" />
        <select 
          className="bg-transparent border-none outline-none cursor-pointer text-text-primary"
          value={locations.includes('all') ? 'all' : locations[0]}
          onChange={(e) => {
            const val = e.target.value;
            setLocations(val === 'all' ? ['all'] : [val]);
          }}
        >
          <option value="all">All Locations</option>
          <option value="north">North Boutique</option>
          <option value="south">South Boutique</option>
          <option value="downtown">Downtown</option>
          <option value="covington">Covington</option>
        </select>
      </div>

      <div className="h-6 w-px bg-gray-200 mx-1"></div>

      {/* Pay Group Selector */}
      <div className="flex items-center gap-2">
        <Users className="w-4 h-4 text-text-muted" />
        <select 
          className="bg-transparent border-none outline-none cursor-pointer text-text-primary"
          value={payGroup}
          onChange={(e) => setPayGroup(e.target.value)}
        >
          <option value="all">All Pay Groups</option>
          <option value="hourly">Hourly</option>
          <option value="salary">Salary</option>
          <option value="hourly_plus_commission">Hourly + Commission</option>
          <option value="salary_plus_commission">Salary + Commission</option>
        </select>
      </div>

      <div className="h-6 w-px bg-gray-200 mx-1"></div>

      {/* Department Selector */}
      <div className="flex items-center gap-2">
        <Filter className="w-4 h-4 text-text-muted" />
        <select 
          className="bg-transparent border-none outline-none cursor-pointer text-text-primary"
          value={department}
          onChange={(e) => setDepartment(e.target.value)}
        >
          <option value="all">All Departments</option>
          {departments.map(d => (
            <option key={d.id} value={d.id}>{d.name}</option>
          ))}
        </select>
      </div>

      <div className="flex-grow"></div>

      {/* Sticky Selected Chips */}
      <div className="hidden lg:flex items-center gap-2">
        {!locations.includes('all') && (
          <Badge variant="secondary" className="cursor-pointer" onClick={() => setLocations(['all'])}>
            Loc: {locations.join(', ')} ├ù
          </Badge>
        )}
        {payGroup !== 'all' && (
          <Badge variant="secondary" className="cursor-pointer" onClick={() => setPayGroup('all')}>
            Grp: {payGroup} ├ù
          </Badge>
        )}
        {department !== 'all' && (
          <Badge variant="secondary" className="cursor-pointer" onClick={() => setDepartment('all')}>
            Dept: {department} ├ù
          </Badge>
        )}
        
        {(payGroup !== 'all' || !locations.includes('all') || department !== 'all' || employeeSearch !== '') && (
          <Button variant="ghost" size="sm" onClick={clearFilters} className="text-text-muted hover:text-red-600 h-6 px-2 text-xs">
            Clear Filters
          </Button>
        )}
      </div>

      <Button variant="outline" size="sm" onClick={() => {
        // Trigger a force re-fetch or re-calc if needed by parent
        onScopeChange({...{
          startDate: dateRange.from ? format(dateRange.from, 'yyyy-MM-dd') : '',
          endDate: dateRange.to ? format(dateRange.to, 'yyyy-MM-dd') : dateRange.from ? format(dateRange.from, 'yyyy-MM-dd') : '',
          businessId,
          locations,
          payGroup,
          department,
          employeeSearch
        }});
      }}>
        <RefreshCw className="w-4 h-4 mr-2" />
        Refresh
      </Button>

    </div>
  );
}

import { useState, useEffect } from 'react';
import { Coins, Calendar, AlertTriangle, UserCheck, CheckCircle, Plus, Trash2, ArrowRight, CreditCard, FileText, DollarSign, Briefcase, Eye } from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import { supabase } from '@/lib/supabase';
import { toast } from '@vowos/design-system';
import {
  getDepartments,
  getCompensationProfiles,
  saveCompensationProfiles,
  getLeaveRequests,
  saveLeaveRequests,
  getBonuses,
  getReimbursements,
  getDeductions,
  writeAuditLog,
  getTimeEntries,
  saveTimeEntries,
  getTimeEntrySegments,
  saveTimeEntrySegments,
  getTimeEntryCorrections,
  saveTimeEntryCorrections,
  getOfficialPayrollPeriods,
  saveOfficialPayrollPeriods,
  CompensationProfile,
  Department,
  LeaveRequest,
  Bonus,
  Reimbursement,
  Deduction,
  TimeEntry,
  TimeEntrySegment,
  TimeEntryCorrection,
  OfficialPayrollPeriod
} from '@/lib/services/workforceStore';
import { authorizeAction } from '@/lib/services/authService';
import { PayrollRunResult, compilePayrollPeriod } from '@/lib/services/payrollEngine';
import { Modal, StatCard, inputCls, btnPrimary, btnSecondary } from '../ui';
import { PayrollScopeBar, PayrollScope } from './PayrollScopeBar';
import { ExceptionCenter, ExceptionData } from './ExceptionCenter';
import { PayrollWizard } from './PayrollWizard';
import { Timecard360 } from './Timecard360';
import { format } from 'date-fns';

export default function PayrollView() {
  const { profile } = useAuth();
  const [activeTab, setActiveTab] = useState<'command' | 'timecards' | 'corrections' | 'exceptions' | 'compensation' | 'leave'>('command');
  
  // Data State
  const [profiles, setProfiles] = useState<CompensationProfile[]>([]);
  const [punches, setPunches] = useState<TimeEntry[]>([]);
  const [segments, setSegments] = useState<TimeEntrySegment[]>([]);
  const [corrections, setCorrections] = useState<TimeEntryCorrection[]>([]);
  const [bonuses, setBonuses] = useState<Bonus[]>([]);
  const [reimbursements, setReimbursements] = useState<Reimbursement[]>([]);
  const [deductions, setDeductions] = useState<Deduction[]>([]);
  const [leaveRequests, setLeaveRequests] = useState<LeaveRequest[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [officialPeriods, setOfficialPeriods] = useState<OfficialPayrollPeriod[]>([]);
  
  // Scope State
  const [scope, setScope] = useState<PayrollScope>({
    startDate: '',
    endDate: '',
    businessId: 'roberts-enterprises',
    locations: ['all'],
    payGroup: 'all',
    department: 'all',
    employeeSearch: ''
  });
  
  // Modals & Sub-views
  const [showWizard, setShowWizard] = useState(false);
  const [draftRun, setDraftRun] = useState<PayrollRunResult | null>(null);
  const [viewingTimecard, setViewingTimecard] = useState<TimeEntry | null>(null);

  const [showCompModal, setShowCompModal] = useState(false);
  const [compEmployee, setCompEmployee] = useState('');
  const [compType, setCompType] = useState<'hourly' | 'salary'>('hourly');
  const [compRate, setCompRate] = useState('22.50');
  const [compEffective, setCompEffective] = useState('2026-07-01');
  const [compReason, setCompReason] = useState('Promo adjust');

  const loadData = async () => {
    try {
      setProfiles(await getCompensationProfiles());
      setDepartments(await getDepartments());
      setLeaveRequests(await getLeaveRequests());
      setBonuses(await getBonuses());
      setReimbursements(await getReimbursements());
      setDeductions(await getDeductions());
      setPunches(await getTimeEntries());
      setSegments(await getTimeEntrySegments());
      setCorrections(await getTimeEntryCorrections());
      setOfficialPeriods(await getOfficialPayrollPeriods());
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  if (!profile) return null;

  const canManageComp = authorizeAction({ userId: profile.id, userRole: profile.role, permission: 'compensation.edit' }).allowed;
  const canProcessPayroll = authorizeAction({ userId: profile.id, userRole: profile.role, permission: 'payroll.create_run' }).allowed;

  // Filter data based on current scope
  const scopedPunches = punches.filter(p => {
    if (scope.startDate && p.clockIn.split('T')[0] < scope.startDate) return false;
    if (scope.endDate && p.clockIn.split('T')[0] > scope.endDate) return false;
    if (scope.businessId && p.businessId !== scope.businessId) return false;
    
    // Check location
    if (scope.locations.length > 0 && !scope.locations.includes('all')) {
      const pSegs = segments.filter(s => s.timeEntryId === p.id);
      if (pSegs.length > 0) {
        if (!pSegs.some(s => scope.locations.includes(s.locationId))) return false;
      } else {
        if (!scope.locations.includes(p.originalLocationId)) return false;
      }
    }
    
    // Check department via segment or comp profile
    // Simplification: if searching by department, we filter...
    
    return true;
  });

  // Calculate Exceptions dynamically
  const generateExceptions = (): ExceptionData[] => {
    const exs: ExceptionData[] = [];
    scopedPunches.forEach(p => {
      const start = new Date(p.clockIn).getTime();
      const end = p.clockOut ? new Date(p.clockOut).getTime() : new Date().getTime();
      const hrs = (end - start) / 3_600_000;
      
      if (!p.clockOut && hrs > 16) {
        exs.push({ id: `ex-${p.id}-miss`, type: 'missing_punch', title: 'Missing Clock Out', employeeName: p.employeeName, description: 'Shift exceeded 16 hours without clock-out.', timeEntryId: p.id });
      } else if (hrs > 12) {
        exs.push({ id: `ex-${p.id}-ot`, type: 'overtime_risk', title: 'Double Time Warning', employeeName: p.employeeName, description: `Logged ${hrs.toFixed(1)}h continuous work shift.`, timeEntryId: p.id });
      }
      
      if (!p.approved && p.clockOut) {
        exs.push({ id: `ex-${p.id}-unapp`, type: 'unapproved', title: 'Unapproved Timecard', employeeName: p.employeeName, description: 'Timecard pending managerial review.', timeEntryId: p.id });
      }
    });
    return exs;
  };
  const exceptions = generateExceptions();

  // Handle Wizard Start
  const handleStartWizard = async () => {
    if (!scope.startDate || !scope.endDate) {
      toast({ title: 'Invalid Scope', description: 'Please select a concrete date range to begin payroll run.', variant: 'destructive' });
      return;
    }
    
    const draftPeriod: OfficialPayrollPeriod = {
      id: crypto.randomUUID(),
      businessId: scope.businessId,
      name: `${scope.startDate} to ${scope.endDate}`,
      startDate: scope.startDate,
      endDate: scope.endDate,
      payDate: new Date().toISOString().split('T')[0],
      payFrequency: 'custom',
      status: 'draft',
      eligiblePayGroups: scope.payGroup !== 'all' ? [scope.payGroup] : undefined
    };

    const commissionsMap: Record<string, number> = {};
    
    try {
      const result = await compilePayrollPeriod(
        draftPeriod,
        profiles,
        punches,
        segments,
        deductions,
        reimbursements,
        bonuses,
        commissionsMap,
        departments
      );

      setDraftRun(result);
      setShowWizard(true);
    } catch (err: any) {
      toast({ title: 'Payroll Error', description: err.message, variant: 'destructive' });
    }
  };

  const handlePostPayroll = async () => {
    if (draftRun) {
      const newPeriod: OfficialPayrollPeriod = {
        id: draftRun.runId,
        businessId: scope.businessId,
        name: draftRun.periodName,
        startDate: scope.startDate,
        endDate: scope.endDate,
        payDate: new Date().toISOString().split('T')[0],
        payFrequency: 'custom',
        status: 'posted',
        totalGrossCents: draftRun.totalGross,
        totalNetCents: draftRun.totalNet,
        totalEmployerCostCents: draftRun.totalEmployerCost,
        employeeCount: draftRun.statements.length,
        createdBy: profile.id,
        postedAt: new Date().toISOString()
      };
      await saveOfficialPayrollPeriods([...officialPeriods, newPeriod]);
      
      // Update punches to approved
      const updatedPunches = punches.map(p => {
        if (scopedPunches.some(sp => sp.id === p.id)) {
          return { ...p, approved: true, status: 'completed' as const };
        }
        return p;
      });
      await saveTimeEntries(updatedPunches);
      
      setOfficialPeriods([...officialPeriods, newPeriod]);
      setPunches(updatedPunches);
    }
  };

  const handleUpdateComp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!canManageComp) return;
    const rateCents = Math.round(parseFloat(compRate) * 100);
    const newProfile: CompensationProfile = {
      employeeId: compEmployee.toLowerCase().replace(' ', '_'),
      employeeName: compEmployee,
      type: compType,
      payFrequency: 'semimonthly',
      hourlyRate: compType === 'hourly' ? rateCents : 0,
      salaryAmount: compType === 'salary' ? rateCents * 24 : 0, 
      commissionRate: 5,
      drawAmount: 0,
      effectiveDate: compEffective,
      reason: compReason
    };

    const updated = [newProfile, ...profiles.filter(p => p.employeeName !== compEmployee)];
    await saveCompensationProfiles(updated);
    toast({ title: 'Compensation updated', description: `Saved compensation profile for ${compEmployee}.` });
    await writeAuditLog(profile.name, 'Compensation Change', `Updated compensation profile for ${compEmployee}.`);
    loadData();
    setShowCompModal(false);
  };

  return (
    <div className="space-y-0 h-full flex flex-col bg-gray-50/30">
      
      {/* Global Filter Bar */}
      <PayrollScopeBar onScopeChange={setScope} departments={departments} />
      
      <div className="p-6 space-y-6 max-w-7xl mx-auto w-full">
        {/* Navigation Tabs */}
        <div data-tour-id="tabs-payroll" className="flex flex-wrap border-b border-stone-200 gap-1 mb-6">
          {[
            { key: 'command', label: 'Command Center', icon: Briefcase },
            { key: 'timecards', label: 'Timecards Log', icon: Calendar },
            { key: 'corrections', label: 'Corrections Queue', icon: UserCheck },
            { key: 'exceptions', label: 'Exception Center', icon: AlertTriangle },
            { key: 'compensation', label: 'Compensation & Rates', icon: DollarSign },
          ].map(t => (
            <button
              key={t.key}
              data-tour-id={`tab-payroll-${t.key}`}
              onClick={() => setActiveTab(t.key as any)}
              className={`flex items-center gap-1.5 px-4 py-2.5 text-xs font-semibold uppercase tracking-wider border-b-2 transition-colors ${activeTab === t.key ? 'border-blue-600 text-blue-700' : 'border-transparent text-stone-500 hover:text-stone-700'}`}
            >
              <t.icon className="h-4 w-4" />
              {t.label}
              {t.key === 'exceptions' && exceptions.length > 0 && (
                <span className="ml-1 bg-status-warning text-white rounded-full px-1.5 py-0.5 text-[10px]">{exceptions.length}</span>
              )}
            </button>
          ))}
        </div>

        {/* COMMAND CENTER TAB */}
        {activeTab === 'command' && (
          <div className="space-y-6">
            <div data-tour-id="payroll-summary-cards" className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <StatCard label="Scope Timecards" value={String(scopedPunches.length)} sub="In selected date range" icon={<Calendar className="h-5 w-5" />} accent="violet" />
              <StatCard label="Direct Deposit Auth" value={draftRun ? `$${(draftRun.totalNet/100).toLocaleString()}` : "Pending Run"} sub={draftRun ? "Calculated" : "Requires Payroll Run"} icon={<CreditCard className="h-5 w-5" />} accent="emerald" />
              <StatCard label="Open Exceptions" value={String(exceptions.length)} sub="Drill down to fix punches" icon={<AlertTriangle className="h-5 w-5 animate-bounce" />} accent="amber" />
              <StatCard label="Provider Status" value="Healthy" sub="Gusto API Connected" icon={<CheckCircle className="h-5 w-5" />} accent="rose" />
            </div>

            <div className="grid gap-6 lg:grid-cols-3">
              <div className="lg:col-span-2 rounded-2xl border border-stone-200 bg-white p-6 shadow-sm space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="font-serif text-xl text-stone-900">Payroll Execution</h3>
                </div>
                <p className="text-sm text-stone-500 leading-relaxed">
                  You are viewing the scope for <span className="font-semibold text-stone-700">{scope.startDate || 'Beginning of time'} to {scope.endDate || 'Now'}</span>.
                  Ensure all exceptions are cleared before executing a payroll run.
                </p>
                <div className="pt-2">
                  <button data-tour-id="btn-run-payroll" onClick={handleStartWizard} className={`${btnPrimary} py-3 px-6 text-sm font-semibold shadow-md`}>
                    Run Payroll for this Scope <ArrowRight className="h-4 w-4 ml-2" />
                  </button>
                </div>
              </div>

              <div className="rounded-2xl border border-stone-200 bg-white p-5 shadow-sm space-y-3">
                <h3 className="font-serif text-lg text-stone-900">Recent Postings</h3>
                {officialPeriods.length > 0 ? (
                  <ul className="space-y-3">
                    {officialPeriods.slice(-3).reverse().map(op => (
                      <li key={op.id} className="border-b pb-2 last:border-0">
                        <div className="flex justify-between items-start">
                          <span className="font-medium text-sm">{op.name}</span>
                          <span className="text-xs font-semibold text-status-success uppercase tracking-wider">{op.status}</span>
                        </div>
                        <div className="flex justify-between text-xs text-text-muted mt-1">
                          <span>${(op.totalGrossCents! / 100).toLocaleString()} Gross</span>
                          <span>{new Date(op.postedAt!).toLocaleDateString()}</span>
                        </div>
                      </li>
                    ))}
                  </ul>
                ) : (
                  <p className="text-xs text-text-muted">No official payroll runs have been posted yet.</p>
                )}
              </div>
            </div>
          </div>
        )}

        {/* TIMECARDS TAB */}
        {activeTab === 'timecards' && (
          <div className="rounded-2xl border border-stone-200 bg-white p-5 shadow-sm space-y-4">
            <h3 className="font-serif text-lg text-stone-900">Timecards Log</h3>
            <div className="overflow-x-auto border border-stone-100 rounded-lg">
              <table className="min-w-full text-xs text-left">
                <thead className="bg-stone-50 text-stone-500 uppercase">
                  <tr>
                    <th className="px-4 py-2">Date</th>
                    <th className="px-4 py-2">Employee</th>
                    <th className="px-4 py-2">Location</th>
                    <th className="px-4 py-2">Status</th>
                    <th className="px-4 py-2">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-stone-100">
                  {scopedPunches.map(p => (
                    <tr key={p.id} className="hover:bg-stone-50 cursor-pointer" onClick={() => setViewingTimecard(p)}>
                      <td className="px-4 py-3">{new Date(p.clockIn).toLocaleDateString()}</td>
                      <td className="px-4 py-3 font-medium">{p.employeeName}</td>
                      <td className="px-4 py-3">{p.originalLocationId}</td>
                      <td className="px-4 py-3">
                        <span className={`px-2 py-1 rounded text-xs font-semibold ${p.approved ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'}`}>
                          {p.approved ? 'Approved' : p.clockOut ? 'Pending Review' : 'Clocked In'}
                        </span>
                      </td>
                      <td className="px-4 py-3">
                        <button className="text-status-info flex items-center gap-1 hover:underline">
                          <Eye className="w-3 h-3" /> View 360
                        </button>
                      </td>
                    </tr>
                  ))}
                  {scopedPunches.length === 0 && (
                    <tr><td colSpan={5} className="px-4 py-8 text-center text-text-muted">No timecards in this scope.</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* EXCEPTIONS TAB */}
        {activeTab === 'exceptions' && (
          <div className="max-w-4xl">
            <ExceptionCenter 
              exceptions={exceptions} 
              onResolve={(ex) => {
                const p = punches.find(p => p.id === ex.timeEntryId);
                if (p) setViewingTimecard(p);
              }} 
            />
          </div>
        )}
        
        {/* CORRECTIONS QUEUE TAB */}
        {activeTab === 'corrections' && (
          <div className="rounded-2xl border border-stone-200 bg-white p-5 shadow-sm space-y-4">
            <h3 className="font-serif text-lg text-stone-900">Corrections Queue</h3>
            {corrections.filter(c => c.status === 'pending').length > 0 ? (
              <div className="space-y-2">
                {corrections.filter(c => c.status === 'pending').map(c => (
                  <div key={c.id} className="p-4 border rounded shadow-sm bg-yellow-50 flex justify-between items-center">
                    <div>
                      <div className="font-semibold text-sm">{c.type.replace('_', ' ').toUpperCase()}</div>
                      <div className="text-text-secondary text-sm mt-1">{c.reason}</div>
                    </div>
                    <button className={btnPrimary} onClick={() => {
                       const p = punches.find(p => p.id === c.timeEntryId);
                       if (p) setViewingTimecard(p);
                    }}>Review</button>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-8 text-stone-500 text-sm">
                Queue clean. No pending punch corrections.
              </div>
            )}
          </div>
        )}

        {/* COMPENSATION TAB */}
        {activeTab === 'compensation' && (
          <div className="rounded-2xl border border-stone-200 bg-white p-5 shadow-sm space-y-4">
            <div className="flex items-center justify-between border-b border-stone-100 pb-3">
              <h3 className="font-serif text-lg text-stone-900">Compensation Profiles</h3>
              {canManageComp && (
                <button onClick={() => setShowCompModal(true)} className={btnPrimary}>
                  <Plus className="h-4 w-4" /> Edit Profile Rate
                </button>
              )}
            </div>

            <div className="overflow-x-auto border border-stone-100 rounded-lg">
              <table className="min-w-full text-xs text-left">
                <thead className="bg-stone-50 text-stone-500 uppercase">
                  <tr>
                    <th className="px-4 py-2">Staff Name</th>
                    <th className="px-4 py-2">Hourly Rate</th>
                    <th className="px-4 py-2">Annualized Salary</th>
                    <th className="px-4 py-2">Frequency</th>
                    <th className="px-4 py-2">Effective Date</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-stone-100">
                  {profiles.map(p => (
                    <tr key={p.employeeId}>
                      <td className="px-4 py-2.5 font-medium">{p.employeeName}</td>
                      <td className="px-4 py-2.5">{p.hourlyRate > 0 ? `$${(p.hourlyRate / 100).toFixed(2)}/hr` : 'ΓÇö'}</td>
                      <td className="px-4 py-2.5">{p.salaryAmount > 0 ? `$${(p.salaryAmount / 100).toLocaleString()}/yr` : 'ΓÇö'}</td>
                      <td className="px-4 py-2.5">{p.payFrequency || 'ΓÇö'}</td>
                      <td className="px-4 py-2.5">{p.effectiveDate}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>

      {/* OVERLAYS */}
      {showWizard && (
        <PayrollWizard
          draftRun={draftRun}
          exceptions={exceptions}
          onClose={() => setShowWizard(false)}
          onPost={() => {
            handlePostPayroll();
            setShowWizard(false);
            setActiveTab('command');
          }}
          onResolveExceptions={() => {
            setShowWizard(false);
            setActiveTab('exceptions');
          }}
        />
      )}

      {viewingTimecard && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4">
          <Timecard360
            entry={viewingTimecard}
            segments={segments.filter(s => s.timeEntryId === viewingTimecard.id)}
            corrections={corrections.filter(c => c.timeEntryId === viewingTimecard.id)}
            onClose={() => setViewingTimecard(null)}
            onSubmitCorrection={async (partial) => {
              const req: TimeEntryCorrection = {
                id: crypto.randomUUID(),
                timeEntryId: viewingTimecard.id,
                requestedBy: profile.id,
                requestedAt: new Date().toISOString(),
                type: partial.type!,
                reason: partial.reason!,
                status: 'pending'
              };
              await saveTimeEntryCorrections([...corrections, req]);
              setCorrections([...corrections, req]);
              toast({ title: 'Correction Submitted' });
            }}
            onApproveCorrection={async (cid) => {
              const updated = corrections.map(c => c.id === cid ? { ...c, status: 'approved' as const, resolvedBy: profile.id, resolvedAt: new Date().toISOString() } : c);
              await saveTimeEntryCorrections(updated);
              
              // Approve the timecard automatically when a correction is approved
              const updatedPunches = punches.map(p => p.id === viewingTimecard.id ? { ...p, approved: true } : p);
              await saveTimeEntries(updatedPunches);
              
              setCorrections(updated);
              setPunches(updatedPunches);
              setViewingTimecard(updatedPunches.find(p => p.id === viewingTimecard.id) || null);
            }}
            onVoid={async (id) => {
              const updatedPunches = punches.map(p => p.id === id ? { ...p, status: 'voided' as const } : p);
              await saveTimeEntries(updatedPunches);
              setPunches(updatedPunches);
              setViewingTimecard(null);
              toast({ title: 'Timecard Voided' });
            }}
          />
        </div>
      )}

      {/* Compensation Edit Modal */}
      <Modal open={showCompModal} onClose={() => setShowCompModal(false)} title="Modify Employee Compensation">
        <form onSubmit={handleUpdateComp} className="space-y-4">
          <div className="space-y-1">
            <label className="text-xs font-semibold text-stone-600 block">Select Employee</label>
            <select value={compEmployee} onChange={e => setCompEmployee(e.target.value)} className={inputCls} required>
              <option value="">Choose team memberΓÇª</option>
              {profiles.map(p => <option key={p.employeeId} value={p.employeeName}>{p.employeeName}</option>)}
            </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-stone-600 block">Pay Tier Classification</label>
            <select value={compType} onChange={e => setCompType(e.target.value as any)} className={inputCls}>
              <option value="hourly">Hourly Rate</option>
              <option value="salary">Salary Rate</option>
            </select>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-stone-600 block">Amount (Hourly Rate or Annual Salary in USD)</label>
            <input type="number" step="0.01" required value={compRate} onChange={e => setCompRate(e.target.value)} className={inputCls} />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-stone-600 block">Effective Date</label>
            <input type="date" required value={compEffective} onChange={e => setCompEffective(e.target.value)} className={inputCls} />
          </div>

          <div className="flex gap-2 justify-end pt-3 border-t border-stone-100">
            <button type="button" onClick={() => setShowCompModal(false)} className={btnSecondary}>Cancel</button>
            <button type="submit" className={btnPrimary}>Save Compensation Profile</button>
          </div>
        </form>
      </Modal>

    </div>
  );
}

import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from '@vowos/design-system';
import { Button } from '@vowos/design-system';
import { Input } from '@vowos/design-system';
import { Label } from '@vowos/design-system';
import { Textarea } from '@vowos/design-system';
import { Badge } from '@vowos/design-system';
import { Clock, MapPin, AlertCircle, History } from 'lucide-react';
import { TimeEntry, TimeEntrySegment, TimeEntryCorrection } from '@/lib/services/workforceStore';
import { format } from 'date-fns';

interface Timecard360Props {
  entry: TimeEntry;
  segments: TimeEntrySegment[];
  corrections: TimeEntryCorrection[];
  onClose: () => void;
  onSubmitCorrection: (correction: Partial<TimeEntryCorrection>) => void;
  onApproveCorrection: (correctionId: string) => void;
  onVoid: (entryId: string) => void;
}

export function Timecard360({ entry, segments, corrections, onClose, onSubmitCorrection, onApproveCorrection, onVoid }: Timecard360Props) {
  const [showCorrectionForm, setShowCorrectionForm] = useState(false);
  const [correctionType, setCorrectionType] = useState<TimeEntryCorrection['type']>('wrong_time');
  const [correctionReason, setCorrectionReason] = useState('');

  return (
    <Card className="w-full max-w-2xl mx-auto shadow-xl border-t-4 border-t-blue-600">
      <CardHeader className="bg-gray-50 border-b flex flex-row items-start justify-between">
        <div>
          <CardTitle className="text-xl flex items-center gap-2">
            Timecard 360
            <Badge variant={entry.approved ? "default" : "secondary"}>{entry.approved ? 'Approved' : 'Unapproved'}</Badge>
            <Badge variant="outline">{entry.status.toUpperCase()}</Badge>
          </CardTitle>
          <div className="text-sm text-text-muted mt-1">Employee: <span className="font-semibold text-text-primary">{entry.employeeName}</span></div>
          <div className="text-sm text-text-muted">Date: {format(new Date(entry.clockIn), 'MMM d, yyyy')}</div>
        </div>
        <Button variant="ghost" size="icon" onClick={onClose}>├ù</Button>
      </CardHeader>
      
      <CardContent className="p-6 space-y-6">
        {/* Core Times */}
        <div className="grid grid-cols-2 gap-4">
          <div className="bg-status-success/10 border border-green-100 rounded-lg p-4 flex items-center gap-3">
            <Clock className="w-8 h-8 text-status-success" />
            <div>
              <div className="text-xs text-green-700 font-semibold uppercase tracking-wider">Clock In</div>
              <div className="text-lg font-mono">{format(new Date(entry.clockIn), 'HH:mm:ss')}</div>
            </div>
          </div>
          <div className="bg-status-info/10 border border-blue-100 rounded-lg p-4 flex items-center gap-3">
            <Clock className="w-8 h-8 text-status-info" />
            <div>
              <div className="text-xs text-blue-700 font-semibold uppercase tracking-wider">Clock Out</div>
              <div className="text-lg font-mono">{entry.clockOut ? format(new Date(entry.clockOut), 'HH:mm:ss') : 'Active'}</div>
            </div>
          </div>
        </div>

        {/* Location & Segments */}
        <div>
          <h3 className="font-semibold text-sm mb-3 flex items-center gap-2"><MapPin className="w-4 h-4"/> Location Allocation</h3>
          {segments.length > 0 ? (
            <div className="space-y-2">
              {segments.map(seg => (
                <div key={seg.id} className="flex justify-between items-center text-sm border p-2 rounded">
                  <span>Loc: {seg.locationId} <Badge variant="outline" className="ml-2 text-[10px]">{seg.departmentId}</Badge></span>
                  <span>{Math.round(seg.paidMinutes / 60 * 100) / 100} hrs</span>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-sm border p-2 rounded bg-gray-50">
              Primary Location: {entry.originalLocationId} (100% allocation)
            </div>
          )}
        </div>

        {/* Corrections History */}
        {corrections.length > 0 && (
          <div>
            <h3 className="font-semibold text-sm mb-3 flex items-center gap-2"><History className="w-4 h-4"/> Corrections & Approvals</h3>
            <div className="space-y-2">
              {corrections.map(c => (
                <div key={c.id} className="p-3 border rounded text-sm bg-yellow-50">
                  <div className="flex justify-between items-start mb-1">
                    <span className="font-medium">{c.type.replace('_', ' ')}</span>
                    <Badge variant={c.status === 'pending' ? 'secondary' : c.status === 'approved' ? 'default' : 'destructive'}>{c.status}</Badge>
                  </div>
                  <div className="text-text-secondary mb-2">{c.reason}</div>
                  {c.status === 'pending' && (
                    <Button size="sm" onClick={() => onApproveCorrection(c.id)}>Approve</Button>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Correction Form */}
        {showCorrectionForm ? (
          <div className="border p-4 rounded-lg bg-gray-50 space-y-4">
            <h4 className="font-semibold text-sm flex items-center gap-2"><AlertCircle className="w-4 h-4"/> Submit Correction Request</h4>
            
            <div>
              <Label>Correction Type</Label>
              <select className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm" value={correctionType} onChange={e => setCorrectionType(e.target.value as any)}>
                <option value="missed_in">Missed Clock In</option>
                <option value="missed_out">Missed Clock Out</option>
                <option value="wrong_time">Wrong Time</option>
                <option value="wrong_location">Wrong Location</option>
                <option value="other">Other</option>
              </select>
            </div>
            
            <div>
              <Label>Reason / Notes</Label>
              <Textarea 
                value={correctionReason}
                onChange={e => setCorrectionReason(e.target.value)}
                placeholder="Explain the discrepancy..."
              />
            </div>
            
            <div className="flex justify-end gap-2">
              <Button variant="ghost" onClick={() => setShowCorrectionForm(false)}>Cancel</Button>
              <Button onClick={() => {
                onSubmitCorrection({ type: correctionType, reason: correctionReason });
                setShowCorrectionForm(false);
              }}>Submit Request</Button>
            </div>
          </div>
        ) : (
          <div className="flex gap-2">
            <Button variant="outline" onClick={() => setShowCorrectionForm(true)}>Request Correction</Button>
            <Button variant="outline" className="text-red-600 hover:text-red-700 hover:bg-red-50" onClick={() => onVoid(entry.id)}>Void Record</Button>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import React, { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { supabase } from '@/lib/supabase';
import { toast } from 'sonner';

interface AddPlatformUserModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess: () => void;
}

export function AddPlatformUserModal({ open, onOpenChange, onSuccess }: AddPlatformUserModalProps) {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('PLATFORM_ADMIN');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !role) return;

    try {
      setIsSubmitting(true);

      const { data, error } = await supabase.rpc('invite_platform_user', {
        p_email: email,
        p_role: role
      });

      if (error) throw error;

      toast.success(data?.message || 'Platform user successfully assigned.');
      onSuccess();
      onOpenChange(false);
      setEmail('');
      setRole('PLATFORM_ADMIN');
    } catch (err: any) {
      console.error('Failed to assign platform user:', err);
      toast.error(err.message || 'Failed to assign platform user. Note: The user must already exist in auth.users.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[425px]">
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle>Add Platform User</DialogTitle>
            <DialogDescription>
              Assign elevated VowOS Platform permissions to an existing authenticated user.
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="email">User Email</Label>
              <Input
                id="email"
                type="email"
                placeholder="colleague@vowos.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="role">Platform Role</Label>
              <Select value={role} onValueChange={setRole}>
                <SelectTrigger>
                  <SelectValue placeholder="Select a role" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="PLATFORM_OWNER">Platform Owner</SelectItem>
                  <SelectItem value="PLATFORM_ADMIN">Platform Admin</SelectItem>
                  <SelectItem value="PLATFORM_SUPPORT">Platform Support</SelectItem>
                  <SelectItem value="PLATFORM_BILLING">Platform Billing</SelectItem>
                  <SelectItem value="PLATFORM_READ_ONLY">Platform Read-Only</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)} disabled={isSubmitting}>
              Cancel
            </Button>
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting ? 'Assigning...' : 'Assign Role'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useEffect, useState } from 'react';
import { Cpu, Sparkles, CheckCircle2, RefreshCw, Zap, ShieldCheck, DollarSign, Award, Layers, Loader2 } from 'lucide-react';
import { AIModelConfig, AITaskType, BenchmarkResult, INITIAL_AI_MODELS } from '@/features/ai/modelGateway';
import { toast } from '@vowos/design-system';
import { btnPrimary, btnSecondary } from '@/components/vowos/ui';
import { resolveEffectiveSetting, saveScopedSetting } from '@/lib/settings';
import { getActiveDataPlane } from '@/lib/supabase';

const TASK_LABELS: Record<AITaskType, { label: string; desc: string }> = {
  high_reasoning: { label: 'High Reasoning', desc: 'Campaign diagnosis, strategic growth recommendations, budget explanations' },
  fast_summarization: { label: 'Fast Summarization', desc: 'Lead categorization, source normalization, note summaries' },
  vision_creative: { label: 'Vision Creative', desc: 'Ad creative evaluation, product photo scoring' },
  embedding_similarity: { label: 'Embedding & Similarity', desc: 'Duplicate detection, knowledge retrieval' },
  classical_ml: { label: 'Classical ML', desc: 'Lead scoring, appointment probability, no-show risk' },
  optimization_engine: { label: 'Optimization Engine', desc: 'Constrained budget allocation & spend pacing' },
};

interface AIModelSettingsTabProps {
  onDirtyChange: (dirty: boolean) => void;
  registerSaveRef: (saveFn: () => Promise<boolean>) => void;
  resetTrigger: number;
}

export default function AIModelSettingsTab({
  onDirtyChange,
  registerSaveRef,
  resetTrigger,
}: AIModelSettingsTabProps) {
  const [loading, setLoading] = useState(true);
  const [models, setModels] = useState<AIModelConfig[]>(INITIAL_AI_MODELS);
  const [dbModels, setDbModels] = useState<AIModelConfig[]>(INITIAL_AI_MODELS);

  const loadSettings = async () => {
    setLoading(true);
    const dataPlane = getActiveDataPlane();
    const result = await resolveEffectiveSetting<AIModelConfig[]>(
      'ai_models_config',
      'ai_models_config',
      { dataPlane },
      INITIAL_AI_MODELS
    );
    setModels(result.value);
    setDbModels(result.value);
    setLoading(false);
  };

  useEffect(() => {
    loadSettings();
  }, [resetTrigger]);

  const isDirty = JSON.stringify(models) !== JSON.stringify(dbModels);

  useEffect(() => {
    onDirtyChange(isDirty);
  }, [isDirty]);

  const handleSave = async (reason?: string): Promise<boolean> => {
    try {
      const dataPlane = getActiveDataPlane();
      await saveScopedSetting('ai_models_config', 'ai_models_config', models, { dataPlane }, reason);
      
      toast({
        title: 'AI Models saved',
        description: 'AI model configurations have been updated successfully.',
      });
      setDbModels(models);
      return true;
    } catch (err: any) {
      toast({
        title: 'Could not save AI models',
        description: err.message,
        variant: 'destructive',
      });
      return false;
    }
  };

  useEffect(() => {
    registerSaveRef(handleSave);
  }, [models]);

  const handlePromote = (modelId: string, modelName: string) => {
    setModels(currentModels => {
      const challenger = currentModels.find(m => m.id === modelId);
      if (!challenger) return currentModels;
      
      return currentModels.map(m => {
        if (m.taskType === challenger.taskType) {
          if (m.id === modelId) {
            return { ...m, isChampion: true, isChallenger: false, status: 'active' };
          } else {
            return { ...m, isChampion: false, isChallenger: true, status: 'shadow' };
          }
        }
        return m;
      });
    });
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-10 text-sm text-stone-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading AI model configs...
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Top Banner */}
      <div className="rounded-2xl border border-stone-200 bg-white p-5 shadow-xs flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="rounded-xl bg-violet-100 p-2.5 text-violet-700">
            <Cpu className="h-6 w-6" />
          </div>
          <div>
            <h3 className="text-base font-bold text-stone-900">AI Model Gateway & Task Routing Management</h3>
            <p className="text-xs text-stone-500">
              Configure task routing, benchmark quality vs latency, and manage Champion/Challenger models safely.
            </p>
          </div>
        </div>

      </div>

      {/* Model Roster by Task Type */}
      <div className="space-y-4">
        {Object.entries(TASK_LABELS).map(([taskKey, { label, desc }]) => {
          const taskModels = models.filter((m) => m.taskType === taskKey);
          return (
            <div key={taskKey} className="rounded-2xl border border-stone-200 bg-white p-5 shadow-xs space-y-3">
              <div className="flex items-center justify-between">
                <div>
                  <h4 className="text-sm font-bold text-stone-900 flex items-center gap-2">
                    <Layers className="h-4 w-4 text-brand-primary" /> {label} Task Routing
                  </h4>
                  <p className="text-xs text-stone-500">{desc}</p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-3 pt-2">
                {taskModels.map((m) => (
                  <div
                    key={m.id}
                    className={`rounded-xl border p-4 transition-all ${
                      m.isChampion
                        ? 'border-emerald-300 bg-status-success/10/40 ring-1 ring-emerald-400/30'
                        : 'border-stone-200 bg-stone-50/50'
                    }`}
                  >
                    <div className="flex items-start justify-between">
                      <div>
                        <div className="flex items-center gap-2">
                          <p className="text-sm font-bold text-stone-900">{m.name}</p>
                          {m.isChampion && (
                            <span className="inline-flex items-center gap-1 rounded-full bg-emerald-100 px-2 py-0.5 text-[10px] font-bold text-emerald-800">
                              <Award className="h-3 w-3" /> Champion
                            </span>
                          )}
                          {m.isChallenger && (
                            <span className="inline-flex items-center gap-1 rounded-full bg-amber-100 px-2 py-0.5 text-[10px] font-bold text-amber-800">
                              Challenger (Shadow)
                            </span>
                          )}
                        </div>
                        <p className="text-xs text-stone-400 mt-0.5">Provider: {m.provider}</p>
                      </div>

                      {m.isChallenger && (
                        <button
                          onClick={() => handlePromote(m.id, m.name)}
                          className="rounded-lg bg-stone-900 px-2.5 py-1 text-xs font-semibold text-white hover:bg-stone-800 transition-colors"
                        >
                          Promote
                        </button>
                      )}
                    </div>

                    <div className="mt-3 grid grid-cols-3 gap-2 border-t border-stone-200/60 pt-3 text-center">
                      <div>
                        <p className="text-[10px] text-stone-400 font-medium">Quality Score</p>
                        <p className="text-xs font-bold text-stone-800">{m.qualityScore}/100</p>
                      </div>
                      <div>
                        <p className="text-[10px] text-stone-400 font-medium">Latency</p>
                        <p className="text-xs font-bold text-stone-800">{m.latencyMs} ms</p>
                      </div>
                      <div>
                        <p className="text-[10px] text-stone-400 font-medium">Cost / 1k Tokens</p>
                        <p className="text-xs font-bold text-stone-800">${m.costPer1kTokensCents.toFixed(3)}</p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>

    </div>
  );
}

import { useEffect, useState } from 'react';
import { Loader2, Plus, Trash2, Scissors } from 'lucide-react';
import { toast } from '@vowos/design-system';
import { inputCls, btnPrimary } from '@/components/vowos/ui';
import { resolveEffectiveSetting, saveScopedSetting } from '@/lib/settings';
import { getActiveDataPlane } from '@/lib/supabase';
import { SettingsCard } from '../components/SettingsCard';
import { SettingsField } from '../components/SettingsField';

interface AlterationService {
  name: string;
  priceCents: number;
  durationMinutes: number;
}

interface AlterationSettings {
  services: AlterationService[];
  maxFittings: number;
  fittingDurationMinutes: number;
  dueBufferDays: number;
  rushFeeCents: number;
  readyTemplate: string;
}

const DEFAULT_ALTERATION_SETTINGS: AlterationSettings = {
  services: [
    { name: 'Hemming', priceCents: 15000, durationMinutes: 60 },
    { name: 'Bustle', priceCents: 12000, durationMinutes: 45 },
    { name: 'Side seams intake', priceCents: 18000, durationMinutes: 90 },
    { name: 'Shoulder adjustments', priceCents: 9000, durationMinutes: 30 },
  ],
  maxFittings: 3,
  fittingDurationMinutes: 45,
  dueBufferDays: 14, // 2 weeks before event
  rushFeeCents: 7500, // $75
  readyTemplate: 'Hi {bride_name}, your gown alterations are complete and ready for pickup! Book a pickup appointment here: {pickup_link}',
};

interface AlterationsSettingsTabProps {
  onDirtyChange: (dirty: boolean) => void;
  registerSaveRef: (saveFn: () => Promise<boolean>) => void;
  resetTrigger: number;
}

export function AlterationsSettingsTab({
  onDirtyChange,
  registerSaveRef,
  resetTrigger,
}: AlterationsSettingsTabProps) {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [settings, setSettings] = useState<AlterationSettings>(DEFAULT_ALTERATION_SETTINGS);
  const [dbSettings, setDbSettings] = useState<AlterationSettings>(DEFAULT_ALTERATION_SETTINGS);
  const [newServiceName, setNewServiceName] = useState('');
  const [newServicePrice, setNewServicePrice] = useState('100.00');

  const loadSettings = async () => {
    setLoading(true);
    const dataPlane = getActiveDataPlane();
    const result = await resolveEffectiveSetting<AlterationSettings>(
      'alteration_settings',
      'alteration_settings',
      { dataPlane },
      DEFAULT_ALTERATION_SETTINGS
    );
    setSettings(result.value);
    setDbSettings(result.value);
    setLoading(false);
  };

  useEffect(() => {
    loadSettings();
  }, [resetTrigger]);

  const isDirty = JSON.stringify(settings) !== JSON.stringify(dbSettings);

  useEffect(() => {
    onDirtyChange(isDirty);
  }, [isDirty]);

  const handleSave = async (reason?: string): Promise<boolean> => {
    setSaving(true);
    try {
      const dataPlane = getActiveDataPlane();
      await saveScopedSetting('alteration_settings', 'alteration_settings', settings, { dataPlane }, reason);
      
      setSaving(false);
      toast({
        title: 'Alterations & Pickup settings saved',
        description: 'Fitting parameters and pricing have been updated successfully.',
      });
      setDbSettings(settings);
      return true;
    } catch (err: any) {
      setSaving(false);
      toast({
        title: 'Could not save alterations settings',
        description: err.message,
        variant: 'destructive',
      });
      return false;
    }
  };

  useEffect(() => {
    registerSaveRef(handleSave);
  }, [settings]);

  const addService = () => {
    if (!newServiceName.trim()) return;
    const exists = settings.services.some((s) => s.name.toLowerCase() === newServiceName.trim().toLowerCase());
    if (exists) {
      toast({ title: 'Service already exists', variant: 'destructive' });
      return;
    }
    const priceCents = Math.round(parseFloat(newServicePrice) * 100) || 0;
    setSettings({
      ...settings,
      services: [
        ...settings.services,
        { name: newServiceName.trim(), priceCents, durationMinutes: 45 },
      ],
    });
    setNewServiceName('');
    setNewServicePrice('100.00');
  };

  const removeService = (name: string) => {
    setSettings({
      ...settings,
      services: settings.services.filter((s) => s.name !== name),
    });
  };

  const updateService = (name: string, fields: Partial<AlterationService>) => {
    setSettings({
      ...settings,
      services: settings.services.map((s) =>
        s.name === name ? { ...s, ...fields } : s
      ),
    });
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-10 text-sm text-stone-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading alterations parametersΓÇª
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <SettingsCard
        title="Fittings & Lead Times"
        description="Configure due buffers, rush fee rates, and default fitting parameters."
        icon={<Scissors className="h-5 w-5" />}
      >
        <div className="grid gap-4 sm:grid-cols-2">
          <SettingsField
            label="Maximum fittings per order"
            description="The default number of fitting sessions recommended for gowns."
          >
            <input
              type="number"
              value={settings.maxFittings}
              onChange={(e) => setSettings({ ...settings, maxFittings: parseInt(e.target.value) || 1 })}
              className={inputCls}
              min="1"
            />
          </SettingsField>

          <SettingsField
            label="Default fitting duration (minutes)"
            description="Slot duration allocated in the schedule for fitting sessions."
          >
            <input
              type="number"
              value={settings.fittingDurationMinutes}
              onChange={(e) => setSettings({ ...settings, fittingDurationMinutes: parseInt(e.target.value) || 1 })}
              className={inputCls}
              min="5"
            />
          </SettingsField>

          <SettingsField
            label="Due buffer before event date (days)"
            description="Gown must be finished this many days prior to the bride's wedding."
          >
            <input
              type="number"
              value={settings.dueBufferDays}
              onChange={(e) => setSettings({ ...settings, dueBufferDays: parseInt(e.target.value) || 0 })}
              className={inputCls}
              min="0"
            />
          </SettingsField>

          <SettingsField
            label="Rush alterations fee ($)"
            description="Additional fee applied for orders requiring expedited fittings."
          >
            <input
              type="number"
              value={(settings.rushFeeCents / 100).toFixed(2)}
              onChange={(e) => setSettings({ ...settings, rushFeeCents: Math.round(parseFloat(e.target.value) * 100) || 0 })}
              className={inputCls}
