  const [settings, setSettings] = useState<SchedulingSettings>(DEFAULT_SCHEDULING_SETTINGS);
  const [dbSettings, setDbSettings] = useState<SchedulingSettings>(DEFAULT_SCHEDULING_SETTINGS);
