        description: 'Your scheduling rules have been updated successfully.',
      });
      setDbSettings(settings);
      return true;
    } catch (err: any) {
      toast({
        title: 'Could not save scheduling rules',
        description: err.message,
        variant: 'destructive',
      });
      return false;
    }
  };

  useEffect(() => {
    registerSaveRef(handleSave);
  }, [settings]);

  const addApptType = () => {
    if (!newTypeName.trim()) return;
    const exists = settings.apptTypeConfigs.some((t) => t.name.toLowerCase() === newTypeName.trim().toLowerCase());
    if (exists) {
      toast({ title: 'Appointment type already exists', variant: 'destructive' });
      return;
    }
    setSettings({
      ...settings,
      apptTypeConfigs: [
        ...settings.apptTypeConfigs,
        { name: newTypeName.trim(), durationMinutes: 60, prepBufferMinutes: 15, cleanupBufferMinutes: 15, active: true },
      ],
    });
    setNewTypeName('');
  };

  const removeApptType = (name: string) => {
    setSettings({
      ...settings,
      apptTypeConfigs: settings.apptTypeConfigs.filter((t) => t.name !== name),
    });
  };

  const updateApptType = (name: string, fields: Partial<ApptTypeConfig>) => {
    setSettings({
      ...settings,
      apptTypeConfigs: settings.apptTypeConfigs.map((t) =>
        t.name === name ? { ...t, ...fields } : t
      ),
    });
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-10 text-sm text-stone-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading scheduling guidelinesΓÇª
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <SettingsCard
        title="Stylist Allocations & Rules"
        description="Define concurrent scheduling limits and cooldown periods for stylizing staff."
        icon={<Clock className="h-5 w-5" />}
      >
        <div className="grid gap-4 sm:grid-cols-2">
          <SettingsField
            label="Max simultaneous stylists per location"
            description="Controls the maximum number of simultaneous appointments allowed."
          >
            <input
              type="number"
              value={settings.maxSimultaneousStylists}
              onChange={(e) => setSettings({ ...settings, maxSimultaneousStylists: parseInt(e.target.value) || 1 })}
              className={inputCls}
              min="1"
              max="20"
            />
          </SettingsField>

          <SettingsField
            label="Stylist cooldown buffer (minutes)"
            description="Minimum rest period for stylists between appointments."
          >
            <input
              type="number"
              value={settings.stylistCooldownMinutes}
              onChange={(e) => setSettings({ ...settings, stylistCooldownMinutes: parseInt(e.target.value) || 0 })}
              className={inputCls}
              min="0"
              max="120"
            />
          </SettingsField>

          <SettingsField
            label="Allow overlapping appointments"
            description="Permit stylists to handle double bookings or staggered slots."
            className="sm:col-span-2"
          >
            <div className="flex items-center justify-between h-9 px-1">
              <span className="text-xs text-stone-500 font-medium">Double-booking permitted</span>
              <Switch
                checked={settings.allowOverlappingAppts}
                onCheckedChange={(checked) => setSettings({ ...settings, allowOverlappingAppts: checked })}
                className="data-[state=checked]:bg-brand-primary"
              />
            </div>
          </SettingsField>
        </div>
      </SettingsCard>

      <SettingsCard
        title="Appointment Types & Buffers"
        description="Establish durations, preparation, and cleanup buffers for different services."
        icon={<Calendar className="h-5 w-5" />}
      >
        <div className="space-y-4">
          <div className="flex gap-2">
            <input
              type="text"
              placeholder="e.g. VIP Consultation"
              value={newTypeName}
              onChange={(e) => setNewTypeName(e.target.value)}
              className={inputCls}
            />
            <button
              onClick={addApptType}
              className="flex items-center gap-1.5 rounded-lg bg-stone-900 px-4 text-xs font-semibold text-white hover:bg-stone-800 transition-colors"
            >
              <Plus className="h-3.5 w-3.5" /> Add Type
            </button>
          </div>

          <div className="divide-y divide-stone-100 rounded-xl border border-stone-200/80 bg-white">
            {settings.apptTypeConfigs.map((type) => (
              <div key={type.name} className="flex flex-col sm:flex-row sm:items-center justify-between p-4 gap-4">
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-semibold text-stone-800">{type.name}</span>
                    {!type.active && (
                      <span className="rounded bg-stone-100 px-1.5 py-0.5 text-[10px] font-medium text-stone-500">
                        Inactive
                      </span>
                    )}
                  </div>
                </div>

                <div className="flex flex-wrap items-center gap-3">
                  <div className="flex items-center gap-1">
                    <span className="text-xs text-stone-400">Duration</span>
                    <input
                      type="number"
                      value={type.durationMinutes}
                      onChange={(e) => updateApptType(type.name, { durationMinutes: parseInt(e.target.value) || 0 })}
                      className={`${inputCls} w-20 text-center py-1 text-xs`}
                      min="5"
                    />
                    <span className="text-xs text-stone-400">m</span>
                  </div>

                  <div className="flex items-center gap-1">
                    <span className="text-xs text-stone-400">Prep</span>
                    <input
                      type="number"
                      value={type.prepBufferMinutes}
                      onChange={(e) => updateApptType(type.name, { prepBufferMinutes: parseInt(e.target.value) || 0 })}
                      className={`${inputCls} w-16 text-center py-1 text-xs`}
                      min="0"
                    />
                    <span className="text-xs text-stone-400">m</span>
                  </div>

                  <div className="flex items-center gap-1">
                    <span className="text-xs text-stone-400">Cleanup</span>
                    <input
                      type="number"
                      value={type.cleanupBufferMinutes}
                      onChange={(e) => updateApptType(type.name, { cleanupBufferMinutes: parseInt(e.target.value) || 0 })}
                      className={`${inputCls} w-16 text-center py-1 text-xs`}
                      min="0"
                    />
                    <span className="text-xs text-stone-400">m</span>
                  </div>

                  <div className="flex items-center gap-2 pl-2 border-l border-stone-200">
                    <Switch
                      checked={type.active}
                      onCheckedChange={(checked) => updateApptType(type.name, { active: checked })}
                      className="scale-90 data-[state=checked]:bg-brand-primary"
                    />
                    <button
                      onClick={() => removeApptType(type.name)}
                      className="text-stone-400 hover:text-red-500 p-1"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </SettingsCard>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Loader2, MousePointerClick, Plus, Trash2, ArrowUp, ArrowDown, DollarSign } from 'lucide-react';
import { toast } from '@vowos/design-system';
import { inputCls, btnPrimary } from '@/components/vowos/ui';
import { Switch } from '@vowos/design-system';
import {
  BookingSettings,
  BookingQuestion,
  BookingFeeSettings,
  DEFAULT_BOOKING_SETTINGS,
  DEFAULT_BOOKING_QUESTIONS,
  DEFAULT_BOOKING_FEE_SETTINGS,
  resolveEffectiveSetting,
  saveScopedSetting,
} from '@/lib/settings';
import { getActiveDataPlane } from '@/lib/supabase';
import { SettingsCard } from '../components/SettingsCard';
import { SettingsField } from '../components/SettingsField';

interface BookingSettingsTabProps {
  onDirtyChange: (dirty: boolean) => void;
  registerSaveRef: (saveFn: () => Promise<boolean>) => void;
  resetTrigger: number;
}

export function BookingSettingsTab({
  onDirtyChange,
  registerSaveRef,
  resetTrigger,
}: BookingSettingsTabProps) {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  // Settings states
  const [booking, setBooking] = useState<BookingSettings>(DEFAULT_BOOKING_SETTINGS);
  const [dbBooking, setDbBooking] = useState<BookingSettings>(DEFAULT_BOOKING_SETTINGS);

  const [questions, setQuestions] = useState<BookingQuestion[]>(DEFAULT_BOOKING_QUESTIONS);
  const [dbQuestions, setDbQuestions] = useState<BookingQuestion[]>(DEFAULT_BOOKING_QUESTIONS);

  const [feeSettings, setFeeSettings] = useState<BookingFeeSettings>(DEFAULT_BOOKING_FEE_SETTINGS);
  const [dbFeeSettings, setDbFeeSettings] = useState<BookingFeeSettings>(DEFAULT_BOOKING_FEE_SETTINGS);

  // Form state for adding questions
  const [newQText, setNewQText] = useState('');
  const [newQType, setNewQType] = useState<BookingQuestion['type']>('text');
  const [newQOpts, setNewQOpts] = useState('');
  const [newQRequired, setNewQRequired] = useState(false);

  const loadSettings = async () => {
    setLoading(true);
    const dataPlane = getActiveDataPlane();
    
    const bookingResult = await resolveEffectiveSetting<BookingSettings>('booking', 'booking_settings', { dataPlane }, DEFAULT_BOOKING_SETTINGS);
    setBooking(bookingResult.value);
    setDbBooking(bookingResult.value);

    const questionsResult = await resolveEffectiveSetting<BookingQuestion[]>('booking', 'booking_questions', { dataPlane }, DEFAULT_BOOKING_QUESTIONS);
    const sorted = [...questionsResult.value].sort((a, b) => a.displayOrder - b.displayOrder);
    setQuestions(sorted);
    setDbQuestions(JSON.parse(JSON.stringify(sorted)));

    const feeResult = await resolveEffectiveSetting<BookingFeeSettings>('booking', 'booking_fee_settings', { dataPlane }, DEFAULT_BOOKING_FEE_SETTINGS);
    setFeeSettings(feeResult.value);
    setDbFeeSettings(feeResult.value);

    setLoading(false);
  };

  useEffect(() => {
    loadSettings();
  }, [resetTrigger]);

  const isDirty =
    JSON.stringify(booking) !== JSON.stringify(dbBooking) ||
    JSON.stringify(questions) !== JSON.stringify(dbQuestions) ||
    JSON.stringify(feeSettings) !== JSON.stringify(dbFeeSettings);

  useEffect(() => {
    onDirtyChange(isDirty);
  }, [isDirty]);

  const handleSave = async (reason?: string): Promise<boolean> => {
    setSaving(true);
    const orderedQuestions = questions.map((q, idx) => ({ ...q, displayOrder: idx + 1 }));
    
    try {
      const dataPlane = getActiveDataPlane();
      await saveScopedSetting('booking', 'booking_settings', booking, { dataPlane }, reason);
      await saveScopedSetting('booking', 'booking_questions', orderedQuestions, { dataPlane }, reason);
      await saveScopedSetting('booking', 'booking_fee_settings', feeSettings, { dataPlane }, reason);
      
      setSaving(false);
      toast({
        title: 'Settings saved',
        description: 'Online booking rules, questions, and fee policies updated.',
      });
      setDbBooking(booking);
      setDbQuestions(JSON.parse(JSON.stringify(orderedQuestions)));
      setQuestions(orderedQuestions);
      setDbFeeSettings(feeSettings);
      return true;
    } catch (err: any) {
      setSaving(false);
      toast({
        title: 'Could not save booking settings',
        description: err.message,
        variant: 'destructive',
      });
      return false;
    }
  };

  useEffect(() => {
    registerSaveRef(handleSave);
  }, [booking, questions, feeSettings]);

  const addQuestion = () => {
    if (!newQText.trim()) {
      toast({ title: 'Question required', description: 'Enter the question text first.', variant: 'destructive' });
      return;
    }
    const newQ: BookingQuestion = {
      id: String(Date.now()),
      question: newQText,
      type: newQType,
      options: ['select', 'multiselect'].includes(newQType)
        ? newQOpts.split(',').map((o) => o.trim()).filter(Boolean)
        : undefined,
      required: newQRequired,
      employeeOnly: false,
      customerVisible: true,
      displayOrder: questions.length + 1,
      appointmentTypes: ['Bridal Consultation'],
    };

    setQuestions([...questions, newQ]);
    setNewQText('');
    setNewQOpts('');
    setNewQRequired(false);
  };

  const removeQuestion = (id: string) => {
    setQuestions(questions.filter((q) => q.id !== id));
  };

  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    const targetIdx = direction === 'up' ? index - 1 : index + 1;
    if (targetIdx < 0 || targetIdx >= questions.length) return;

    const list = [...questions];
    const temp = list[index];
    list[index] = list[targetIdx];
    list[targetIdx] = temp;
    setQuestions(list);
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-10 text-sm text-stone-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading booking configurationΓÇª
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Availability Controls */}
      <SettingsCard
        title="Online Booking Status"
        description="Determine general options for customer self-booking."
        icon={<MousePointerClick className="h-5 w-5" />}
        enabled={booking.enabled}
        onToggleEnabled={(enabled) => setBooking({ ...booking, enabled })}
      >
        <div className="grid gap-4 sm:grid-cols-2">
          <SettingsField label="Earliest notice (hours)" description="Prevents last-minute bookings. Default is 24 hours.">
            <input
              type="number"
              min="0"
              value={booking.earliestNoticeHours}
              onChange={(e) => setBooking({ ...booking, earliestNoticeHours: parseInt(e.target.value) || 0 })}
              className={inputCls}
            />
          </SettingsField>

          <SettingsField label="Maximum days in advance" description="Furthest date a customer can book. Default is 90.">
            <input
              type="number"
              min="1"
              value={booking.maxDaysAdvance}
              onChange={(e) => setBooking({ ...booking, maxDaysAdvance: parseInt(e.target.value) || 1 })}
              className={inputCls}
            />
          </SettingsField>

          <SettingsField label="Default duration (minutes)">
            <input
              type="number"
              min="15"
              step="15"
              value={booking.defaultDurationMinutes}
              onChange={(e) => setBooking({ ...booking, defaultDurationMinutes: parseInt(e.target.value) || 15 })}
              className={inputCls}
            />
          </SettingsField>

          <SettingsField label="Party size limit">
            <input
              type="number"
              min="1"
              value={booking.partySizeMax}
              onChange={(e) => setBooking({ ...booking, partySizeMax: parseInt(e.target.value) || 1 })}
              className={inputCls}
            />
          </SettingsField>

          <div className="sm:col-span-2 space-y-3 rounded-xl border border-stone-200 bg-stone-50 p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs font-semibold text-stone-800">Support same-day appointments</p>
                <p className="text-[11px] text-stone-400">Allows booking on the current calendar day.</p>
              </div>
              <Switch
                checked={booking.sameDayBooking}
                onCheckedChange={(checked) => setBooking({ ...booking, sameDayBooking: checked })}
                className="data-[state=checked]:bg-status-success"
              />
            </div>

            <div className="flex items-center justify-between border-t border-stone-200 pt-3">
              <div>
                <p className="text-xs font-semibold text-stone-800">Automatic Employee Assignment</p>
                <p className="text-[11px] text-stone-400">Distributes bookings evenly among stylists.</p>
              </div>
              <Switch
                checked={booking.autoAssignmentEnabled}
                onCheckedChange={(checked) => setBooking({ ...booking, autoAssignmentEnabled: checked })}
                className="data-[state=checked]:bg-status-success"
              />
            </div>
          </div>
        </div>
      </SettingsCard>

      {/* Booking Fee Card */}
      <SettingsCard
        title="Booking Fee Policies"
        description="Configure appointment reservation fee defaults, waivers, and refund deadlines."
        icon={<DollarSign className="h-5 w-5" />}
        enabled={feeSettings.enabled}
        onToggleEnabled={(enabled) => setFeeSettings({ ...feeSettings, enabled })}
      >
        <div className="grid gap-4 sm:grid-cols-2">
          <SettingsField label="Default booking fee ($)">
            <input
              type="number"
              min="0"
              value={feeSettings.amountCents / 100}
              onChange={(e) =>
                setFeeSettings({
                  ...feeSettings,
                  amountCents: Math.round(parseFloat(e.target.value) * 100) || 0,
                })
              }
              className={inputCls}
            />
          </SettingsField>

          <SettingsField label="Cancellation deadline (hours)" description="Hours prior to start to receive refunds/waivers.">
            <input
              type="number"
              min="0"
              value={feeSettings.cancelDeadlineHours}
              onChange={(e) =>
                setFeeSettings({
                  ...feeSettings,
                  cancelDeadlineHours: parseInt(e.target.value) || 0,
                })
              }
              className={inputCls}
            />
          </SettingsField>

          <div className="sm:col-span-2 space-y-3 rounded-xl border border-stone-200 bg-stone-50 p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs font-semibold text-stone-800">Refundable Booking Fee</p>
                <p className="text-[11px] text-stone-400">Determines if cancellations before deadline receive a full refund.</p>
              </div>
              <Switch
                checked={feeSettings.refundable}
                onCheckedChange={(checked) => setFeeSettings({ ...feeSettings, refundable: checked })}
                className="data-[state=checked]:bg-status-success"
              />
            </div>

            <div className="flex items-center justify-between border-t border-stone-200 pt-3">
              <div>
                <p className="text-xs font-semibold text-stone-800">Credit Toward Purchase</p>
                <p className="text-[11px] text-stone-400">Automatically marks the fee as store credit upon showroom checkout.</p>
              </div>
              <Switch
                checked={feeSettings.creditTowardPurchase}
                onCheckedChange={(checked) => setFeeSettings({ ...feeSettings, creditTowardPurchase: checked })}
                className="data-[state=checked]:bg-status-success"
              />
            </div>

            {/* Location Scoped Overrides */}
            <div className="border-t border-stone-200 pt-3 space-y-2">
              <p className="text-xs font-semibold text-stone-800">Location-Scoped Fee Overrides</p>
              <p className="text-[11px] text-stone-400">Override the organization default ($75.00) for specific store locations.</p>
              <div className="grid grid-cols-2 gap-3 pt-1">
                <div>
                  <label className="text-[10px] font-semibold uppercase text-stone-500">North Boutique ($)</label>
                  <input
                    type="number"
                    value={((feeSettings.locationOverrides?.['north'] ?? feeSettings.amountCents) / 100).toFixed(2)}
                    onChange={(e) => {
                      const val = Math.round(parseFloat(e.target.value) * 100) || feeSettings.amountCents;
                      setFeeSettings({
                        ...feeSettings,
                        locationOverrides: { ...feeSettings.locationOverrides, north: val }
                      });
                    }}
                    className={inputCls}
                  />
                </div>
                <div>
                  <label className="text-[10px] font-semibold uppercase text-stone-500">South Boutique ($)</label>
                  <input
                    type="number"
                    value={((feeSettings.locationOverrides?.['south'] ?? feeSettings.amountCents) / 100).toFixed(2)}
                    onChange={(e) => {
                      const val = Math.round(parseFloat(e.target.value) * 100) || feeSettings.amountCents;
                      setFeeSettings({
                        ...feeSettings,
                        locationOverrides: { ...feeSettings.locationOverrides, south: val }
                      });
                    }}
                    className={inputCls}
                  />
                </div>
              </div>
            </div>
          </div>
        </div>
      </SettingsCard>

      {/* Intake Question Builder */}
      <div className="grid gap-6 lg:grid-cols-3">
        <div className="lg:col-span-2 space-y-4">
          <div className="rounded-2xl border border-stone-200 bg-white p-6 shadow-sm">
            <div className="mb-4">
              <h4 className="font-serif text-base font-medium text-stone-900">Intake Questions</h4>
              <p className="text-xs text-stone-500">Configure questions asked to clients during the online checkout flow.</p>
            </div>

            <div className="space-y-2 max-h-[500px] overflow-y-auto pr-1">
              {questions.map((q, idx) => (
                <div
                  key={q.id}
                  className="flex items-center justify-between gap-3 rounded-xl border border-stone-100 bg-stone-50/50 p-3 hover:bg-stone-50 transition-colors"
                >
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-2">
                      <span className="text-[10px] font-bold text-stone-400 uppercase tracking-wider bg-stone-200/50 px-1.5 py-0.5 rounded">
                        {q.type}
                      </span>
                      {q.required && (
                        <span className="text-[9px] font-semibold text-brand-primary bg-brand-soft px-1 py-0.5 rounded border border-border-subtle">
                          Required
                        </span>
                      )}
                    </div>
                    <p className="mt-1.5 text-xs font-medium text-stone-800 truncate">{q.question}</p>
                    {q.options && q.options.length > 0 && (
                      <p className="text-[10px] text-stone-400 truncate">Options: {q.options.join(', ')}</p>
                    )}
                  </div>

                  <div className="flex items-center gap-1.5">
                    <button
                      onClick={() => moveQuestion(idx, 'up')}
                      disabled={idx === 0}
                      className="rounded p-1 text-stone-400 hover:bg-stone-100 hover:text-stone-700 disabled:opacity-30"
                    >
                      <ArrowUp className="h-3.5 w-3.5" />
                    </button>
                    <button
                      onClick={() => moveQuestion(idx, 'down')}
                      disabled={idx === questions.length - 1}
                      className="rounded p-1 text-stone-400 hover:bg-stone-100 hover:text-stone-700 disabled:opacity-30"
                    >
                      <ArrowDown className="h-3.5 w-3.5" />
                    </button>
                    <button
                      onClick={() => removeQuestion(q.id)}
                      className="rounded p-1 text-stone-400 hover:bg-brand-soft hover:text-brand-primary"
                    >
                      <Trash2 className="h-3.5 w-3.5" />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Add Question Panel */}
        <div>
          <div className="rounded-2xl border border-stone-200 bg-white p-6 shadow-sm space-y-4">
            <h4 className="font-serif text-base font-medium text-stone-900">Add Question</h4>
            
            <SettingsField label="Question text">
              <input
                type="text"
                value={newQText}
                onChange={(e) => setNewQText(e.target.value)}
                placeholder="e.g. Preferred wedding date?"
                className={inputCls}
              />
            </SettingsField>

            <SettingsField label="Question Type">
              <select
                value={newQType}
                onChange={(e) => setNewQType(e.target.value as BookingQuestion['type'])}
                className={inputCls}
              >
                <option value="text">Short Text</option>
                <option value="longtext">Long Text</option>
                <option value="select">Dropdown (Single Select)</option>
                <option value="multiselect">Checkbox list (Multi Select)</option>
                <option value="currency">Currency Range</option>
                <option value="date">Date picker</option>
                <option value="number">Numeric entry</option>
                <option value="yesno">Yes / No toggle</option>
                <option value="checkbox">Acknowledgement box</option>
              </select>
            </SettingsField>

            {['select', 'multiselect'].includes(newQType) && (
              <SettingsField label="Options (Comma separated)" description="e.g. Option 1, Option 2, Option 3">
                <input
                  type="text"
                  value={newQOpts}
                  onChange={(e) => setNewQOpts(e.target.value)}
                  className={inputCls}
                />
              </SettingsField>
            )}

            <div className="flex items-center justify-between border-t border-stone-100 pt-3">
              <span className="text-xs text-stone-600">Response Required</span>
              <Switch
                checked={newQRequired}
                onCheckedChange={setNewQRequired}
                className="data-[state=checked]:bg-status-success"
              />
            </div>

            <button onClick={addQuestion} className={`${btnPrimary} w-full justify-center`}>
              <Plus className="h-4 w-4" /> Add to Flow
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Percent, Loader2, Plus, Trash2 } from 'lucide-react';
import { toast } from '@vowos/design-system';
import { inputCls } from '@/components/vowos/ui';
import { SettingsCard } from '../components/SettingsCard';
import { SettingsField } from '../components/SettingsField';
import { Switch } from '@vowos/design-system';
import { resolveEffectiveSetting, saveScopedSetting, CommissionSettings } from '@/lib/settings';
import { getActiveDataPlane } from '@/lib/supabase';

const DEFAULT_COMMISSION_SETTINGS: CommissionSettings = {
  plans: [
    { id: '1', name: 'Standard Consultant Rate', description: 'Base 3% commission on all completed gown sales.', ratePct: 3, designerRates: {}, bonusThresholdCents: 5000000, bonusAmountCents: 50000, active: true },
    { id: '2', name: 'Designer Special Tier', description: 'Elevated 5% rate for premium designer collections.', ratePct: 5, designerRates: { 'Monique Lhuillier': 6, 'Berta': 6 }, bonusThresholdCents: 8000000, bonusAmountCents: 100000, active: true },
  ],
};

interface CommissionSettingsTabProps {
  onDirtyChange: (dirty: boolean) => void;
  registerSaveRef: (saveFn: () => Promise<boolean>) => void;
  resetTrigger: number;
}

export function CommissionSettingsTab({
  onDirtyChange,
  registerSaveRef,
  resetTrigger,
}: CommissionSettingsTabProps) {
  const [loading, setLoading] = useState(true);
  const [settings, setSettings] = useState<CommissionSettings>(DEFAULT_COMMISSION_SETTINGS);
  const [dbSettings, setDbSettings] = useState<CommissionSettings>(DEFAULT_COMMISSION_SETTINGS);
  const [newPlanName, setNewPlanName] = useState('');
  const [newPlanRate, setNewPlanRate] = useState('3.0');

  const loadSettings = async () => {
    setLoading(true);
    const dataPlane = getActiveDataPlane();
    const result = await resolveEffectiveSetting<CommissionSettings>(
      'staff',
      'commission_settings',
      { dataPlane },
      DEFAULT_COMMISSION_SETTINGS
    );
    setSettings(result.value);
    setDbSettings(result.value);
    setLoading(false);
  };

  useEffect(() => {
    loadSettings();
  }, [resetTrigger]);

  const isDirty = JSON.stringify(settings) !== JSON.stringify(dbSettings);

  useEffect(() => {
    onDirtyChange(isDirty);
  }, [isDirty]);

  const handleSave = async (reason?: string): Promise<boolean> => {
    try {
      const dataPlane = getActiveDataPlane();
      await saveScopedSetting('staff', 'commission_settings', settings, { dataPlane }, reason);
      
      toast({
        title: 'Commission settings saved',
        description: 'Commission rules have been updated successfully.',
      });
      setDbSettings(settings);
      return true;
    } catch (err: any) {
      toast({
        title: 'Could not save commission settings',
        description: err.message,
        variant: 'destructive',
      });
      return false;
    }
  };

  useEffect(() => {
    registerSaveRef(handleSave);
  }, [settings]);

  const addPlan = () => {
    if (!newPlanName.trim()) return;
    const exists = settings.plans.some((p) => p.name.toLowerCase() === newPlanName.trim().toLowerCase());
    if (exists) {
      toast({ title: 'Plan already exists', variant: 'destructive' });
      return;
    }
    const ratePct = parseFloat(newPlanRate) || 0;
    setSettings({
      ...settings,
      plans: [
        ...settings.plans,
        {
          id: Date.now().toString(),
          name: newPlanName.trim(),
          description: 'Custom consultant commission structure.',
          ratePct,
          designerRates: {},
          bonusThresholdCents: 5000000,
          bonusAmountCents: 50000,
          active: true,
        },
      ],
    });
    setNewPlanName('');
    setNewPlanRate('3.0');
  };

  const removePlan = (id: string) => {
    setSettings({
      ...settings,
      plans: settings.plans.filter((p) => p.id !== id),
    });
  };

  const updatePlan = (id: string, fields: Partial<CommissionSettings['plans'][number]>) => {
    setSettings({
      ...settings,
      plans: settings.plans.map((p) =>
        p.id === id ? { ...p, ...fields } as typeof p : p
      ),
    });
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-10 text-sm text-stone-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading commission plansΓÇª
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <SettingsCard
        title="Compensation & Commission Policies"
        description="Establish baseline percentages, tiered bonus overrides, and split rules."
        icon={<Percent className="h-5 w-5" />}
      >
        <div className="space-y-4">
          <div className="flex flex-col sm:flex-row gap-2">
            <input
              type="text"
              placeholder="e.g. Senior Consultant Rate"
              value={newPlanName}
              onChange={(e) => setNewPlanName(e.target.value)}
              className={`${inputCls} flex-1`}
            />
            <input
              type="number"
              placeholder="Rate (%)"
              value={newPlanRate}
              onChange={(e) => setNewPlanRate(e.target.value)}
              className={`${inputCls} w-28 text-right`}
              step="0.1"
            />
            <button
              onClick={addPlan}
              className="flex items-center justify-center gap-1.5 rounded-lg bg-stone-900 px-4 py-2 text-xs font-semibold text-white hover:bg-stone-800 transition-colors"
            >
              <Plus className="h-3.5 w-3.5" /> Create Plan
            </button>
          </div>

          <div className="space-y-3">
            {settings.plans.map((plan) => (
              <div key={plan.id} className="rounded-xl border border-stone-200 bg-white p-4 space-y-4">
                <div className="flex items-start justify-between">
                  <div>
                    <input
                      type="text"
                      value={plan.name}
                      onChange={(e) => updatePlan(plan.id, { name: e.target.value })}
                      className="text-sm font-semibold text-stone-800 border-b border-transparent hover:border-stone-300 focus:border-stone-900 bg-transparent px-1 -mx-1 outline-none"
                    />
                    <input
                      type="text"
                      value={plan.description}
                      onChange={(e) => updatePlan(plan.id, { description: e.target.value })}
                      className="text-xs text-stone-400 mt-1 block w-full border-b border-transparent hover:border-stone-200 focus:border-stone-900 bg-transparent px-1 -mx-1 outline-none"
                    />
                  </div>

                  <div className="flex items-center gap-2">
                    <Switch
                      checked={plan.active}
                      onCheckedChange={(checked) => updatePlan(plan.id, { active: checked })}
                      className="scale-90 data-[state=checked]:bg-brand-primary"
                    />
                    <button
                      onClick={() => removePlan(plan.id)}
                      className="text-stone-400 hover:text-red-500 p-1"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </div>
                </div>

                <div className="grid gap-4 sm:grid-cols-3 pt-3 border-t border-stone-100">
                  <SettingsField label="Commission Percentage Rate (%)">
                    <input
                      type="number"
                      value={plan.ratePct}
                      onChange={(e) => updatePlan(plan.id, { ratePct: parseFloat(e.target.value) || 0 })}
                      className={inputCls}
                      step="0.1"
                      min="0"
                    />
                  </SettingsField>

                  <SettingsField label="Bonus Goal Threshold ($)">
                    <input
                      type="number"
                      value={(plan.bonusThresholdCents / 100).toFixed(0)}
                      onChange={(e) => updatePlan(plan.id, { bonusThresholdCents: Math.round(parseFloat(e.target.value) * 100) || 0 })}
                      className={inputCls}
                      min="0"
                    />
                  </SettingsField>

                  <SettingsField label="Goal Bonus Payout ($)">
                    <input
                      type="number"
                      value={(plan.bonusAmountCents / 100).toFixed(0)}
                      onChange={(e) => updatePlan(plan.id, { bonusAmountCents: Math.round(parseFloat(e.target.value) * 100) || 0 })}
                      className={inputCls}
                      min="0"
                    />
                  </SettingsField>
                </div>
              </div>
            ))}
          </div>
        </div>
      </SettingsCard>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { MessageSquare, Loader2, RefreshCw, Send, CheckCircle2, Edit3, Eye } from 'lucide-react';
import { toast } from '@vowos/design-system';
import { inputCls } from '@/components/vowos/ui';
import { SettingsCard } from '../components/SettingsCard';
import { SettingsField } from '../components/SettingsField';
import { Switch } from '@vowos/design-system';
import { resolveEffectiveSetting, saveScopedSetting, DEFAULT_TWILIO_SETTINGS, TwilioSettings } from '@/lib/settings';
import { getActiveDataPlane, supabase } from '@/lib/supabase';

interface ChannelConfig {
  emailSender: string;
  senderDisplayName: string;
  replyTo: string;
  smsConsentText: string;
}

const DEFAULT_CHANNEL_CONFIG: ChannelConfig = {
  emailSender: 'notifications@robertsenterprises.com',
  senderDisplayName: 'The Boutique Bridal',
  replyTo: 'support@robertsenterprises.com',
  smsConsentText: 'Reply STOP to unsubscribe. Msg & data rates may apply.',
};

interface MessageTemplate {
  id: string;
  name: string;
  channel: 'SMS' | 'Email';
  subject?: string;
  body: string;
  active: boolean;
}

const DEFAULT_TEMPLATES: MessageTemplate[] = [
  { id: '1', name: 'Booking Created Confirmation', channel: 'Email', subject: 'Your Bridal Consultation at The Boutique', body: 'Hi {bride_name}, your appointment is confirmed for {appointment_date} at {location_name}. We look forward to helping you find your dream gown!', active: true },
  { id: '2', name: 'Booking Fee Invoice Request', channel: 'SMS', body: 'Hi {bride_name}, your VIP styling consultation requires a $75 booking fee reservation. Please finalize payment here: {payment_link}', active: true },
  { id: '3', name: '7-Day Appointment Reminder', channel: 'SMS', body: 'Hi {bride_name}, this is a reminder of your bridal styling consultation next week on {appointment_date} at {location_name}. Reply YES to confirm.', active: true },
  { id: '4', name: 'Alterations Completed pickup', channel: 'Email', subject: 'Your gown alterations are complete!', body: 'Dear {bride_name}, your gown alterations are finalized and passed quality inspection. Book a pickup appointment here: {pickup_link}', active: true },
];

interface CommunicationsSettingsTabProps {
  onDirtyChange: (dirty: boolean) => void;
  registerSaveRef: (saveFn: () => Promise<boolean>) => void;
  resetTrigger: number;
}

export function CommunicationsSettingsTab({
  onDirtyChange,
  registerSaveRef,
  resetTrigger,
}: CommunicationsSettingsTabProps) {
  const [loading, setLoading] = useState(true);
  const [twilio, setTwilio] = useState<TwilioSettings>(DEFAULT_TWILIO_SETTINGS);
  const [dbTwilio, setDbTwilio] = useState<TwilioSettings>(DEFAULT_TWILIO_SETTINGS);
  const [channel, setChannel] = useState<ChannelConfig>(DEFAULT_CHANNEL_CONFIG);
  const [dbChannel, setDbChannel] = useState<ChannelConfig>(DEFAULT_CHANNEL_CONFIG);
  const [templates, setTemplates] = useState<MessageTemplate[]>(DEFAULT_TEMPLATES);
  const [dbTemplates, setDbTemplates] = useState<MessageTemplate[]>(DEFAULT_TEMPLATES);

  const [testingConnection, setTestingConnection] = useState(false);
  const [activeTemplateId, setActiveTemplateId] = useState<string | null>('1');
  const [testSendPhoneEmail, setTestSendPhoneEmail] = useState('');
  const [sendingTest, setSendingTest] = useState(false);

  const loadSettings = async () => {
    setLoading(true);
    const dataPlane = getActiveDataPlane();
    
    const twilioResult = await resolveEffectiveSetting<TwilioSettings>(
      'twilio_settings',
      'twilio_settings',
      { dataPlane },
      DEFAULT_TWILIO_SETTINGS
    );
    const channelResult = await resolveEffectiveSetting<ChannelConfig>(
      'channel_settings',
      'channel_settings',
      { dataPlane },
      DEFAULT_CHANNEL_CONFIG
    );
    const templatesResult = await resolveEffectiveSetting<MessageTemplate[]>(
      'message_templates',
      'message_templates',
      { dataPlane },
      DEFAULT_TEMPLATES
    );
    
    setTwilio(twilioResult.value);
    setDbTwilio(twilioResult.value);
    setChannel(channelResult.value);
    setDbChannel(channelResult.value);
    setTemplates(templatesResult.value);
    setDbTemplates(templatesResult.value);
    setLoading(false);
  };

  useEffect(() => {
    loadSettings();
  }, [resetTrigger]);

  const isDirty =
    JSON.stringify(twilio) !== JSON.stringify(dbTwilio) ||
    JSON.stringify(channel) !== JSON.stringify(dbChannel) ||
    JSON.stringify(templates) !== JSON.stringify(dbTemplates);

  useEffect(() => {
    onDirtyChange(isDirty);
  }, [isDirty]);

  const handleSave = async (reason?: string): Promise<boolean> => {
    try {
      const dataPlane = getActiveDataPlane();
      
      await saveScopedSetting('twilio_settings', 'twilio_settings', twilio, { dataPlane }, reason);
      await saveScopedSetting('channel_settings', 'channel_settings', channel, { dataPlane }, reason);
      await saveScopedSetting('message_templates', 'message_templates', templates, { dataPlane }, reason);

      toast({
        title: 'Communications settings saved',
        description: 'Twilio integration, channel defaults, and message templates updated.',
      });
      
      setDbTwilio(twilio);
      setDbChannel(channel);
      setDbTemplates(templates);
      return true;
    } catch (err: any) {
      toast({
        title: 'Could not save communications settings',
        description: err.message,
        variant: 'destructive',
      });
      return false;
    }
  };

  useEffect(() => {
    registerSaveRef(handleSave);
  }, [twilio, channel, templates]);

  const testTwilioConnection = async () => {
    setTestingConnection(true);
    try {
      const { error } = await supabase.rpc('test_twilio_connection');
      if (error) throw error;
      toast({
        title: 'Twilio connection verified',
        description: 'Webhook callbacks are functioning successfully.',
      });
    } catch (err: any) {
      toast({
        title: 'Twilio connection failed',
        description: err.message,
        variant: 'destructive',
      });
    } finally {
      setTestingConnection(false);
    }
  };

  const handleTemplateChange = (id: string, fields: Partial<MessageTemplate>) => {
    setTemplates(
      templates.map((t) => (t.id === id ? { ...t, ...fields } as typeof t : t))
    );
  };

  const selectedTemplate = templates.find((t) => t.id === activeTemplateId);

  const getResolvedPreview = (body: string) => {
    return body
      .replace('{bride_name}', 'Sarah Jenkins')
      .replace('{appointment_date}', 'July 27, 2026 at 2:00 PM')
      .replace('{location_name}', 'Baton Rouge Salon')
      .replace('{payment_link}', 'https://pay.vowos.com/bk_784x')
      .replace('{pickup_link}', 'https://book.vowos.com/pickup_90f');
  };

  const sendTestTemplate = async () => {
    if (!testSendPhoneEmail.trim() || !selectedTemplate) {
      toast({ title: 'Enter recipient details first', variant: 'destructive' });
      return;
    }
    setSendingTest(true);
    try {
      const { error } = await supabase.rpc('send_test_template', { 
        recipient: testSendPhoneEmail, 
        template_id: selectedTemplate.id 
      });
      if (error) throw error;
      toast({
        title: 'Test dispatch triggered',
        description: `Test message for "${selectedTemplate.name}" successfully sent to ${testSendPhoneEmail}.`,
      });
      setTestSendPhoneEmail('');
    } catch (err: any) {
      toast({
        title: 'Test dispatch failed',
        description: err.message,
        variant: 'destructive',
      });
    } finally {
      setSendingTest(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-10 text-sm text-stone-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading communication channelsΓÇª
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid gap-6 lg:grid-cols-2">
        <SettingsCard
          title="Twilio Gateway Connection"
          description="Status of inbound callback validation on Twilio."
          icon={<MessageSquare className="h-5 w-5" />}
        >
          <div className="space-y-4">
            <SettingsField
              label="Messaging Service SID"
              description="Twilio SID for SMS gateway integrations."
            >
              <input
                type="text"
                value={twilio.messagingServiceSid}
                onChange={(e) => setTwilio({ ...twilio, messagingServiceSid: e.target.value })}
                className={inputCls}
                placeholder="e.g. MGXXXXXXXXXXXXXXXX"
              />
            </SettingsField>

            <div className="flex items-center justify-between p-4 bg-status-success/10 border border-emerald-100 rounded-xl">
              <div className="flex items-center gap-2">
                <CheckCircle2 className="h-4 w-4 text-status-success flex-shrink-0" />
                <span className="text-xs font-semibold text-emerald-700">Twilio Webhook Active</span>
              </div>
              <button
                onClick={testTwilioConnection}
                disabled={testingConnection}
                className="flex items-center gap-1 text-xs text-brand-primary hover:text-brand-primary-hover font-semibold"
              >
                <RefreshCw className={`h-3 w-3 ${testingConnection ? 'animate-spin' : ''}`} />
                Test Connection
              </button>
            </div>
          </div>
        </SettingsCard>

        <SettingsCard
          title="Email & SMS Channel Defaults"
          description="Configure outbound domains and consent unsubscribe footers."
          icon={<MessageSquare className="h-5 w-5" />}
        >
          <div className="grid gap-4 sm:grid-cols-2">
            <SettingsField label="Sender Email">
              <input
                type="email"
                value={channel.emailSender}
                onChange={(e) => setChannel({ ...channel, emailSender: e.target.value })}
                className={inputCls}
              />
            </SettingsField>

            <SettingsField label="Outbound Display Name">
              <input
                type="text"
                value={channel.senderDisplayName}
                onChange={(e) => setChannel({ ...channel, senderDisplayName: e.target.value })}
                className={inputCls}
              />
            </SettingsField>

            <SettingsField label="Reply-To Address" className="sm:col-span-2">
              <input
                type="email"
                value={channel.replyTo}
                onChange={(e) => setChannel({ ...channel, replyTo: e.target.value })}
                className={inputCls}
              />
            </SettingsField>
          </div>
        </SettingsCard>
      </div>

      <SettingsCard
        title="Outbound Notification Templates"
        description="Edit automated message content, evaluate parameters, and send test logs."
        icon={<MessageSquare className="h-5 w-5" />}
      >
        <div className="grid gap-6 md:grid-cols-3">
          {/* Left panel: templates list */}
          <div className="space-y-2 border-r border-stone-100 pr-4 md:col-span-1">
            <span className="text-[10px] font-bold text-stone-400 uppercase tracking-wider block mb-2">Message Templates</span>
            {templates.map((tpl) => (
              <button
                key={tpl.id}
                onClick={() => setActiveTemplateId(tpl.id)}
                className={`flex w-full flex-col p-3 rounded-xl border text-left transition-all ${
                  activeTemplateId === tpl.id
                    ? 'border-rose-300 bg-brand-soft/30'
                    : 'border-stone-200 hover:bg-stone-50/50'
                }`}
              >
                <div className="flex items-center justify-between w-full">
                  <span className="text-xs font-semibold text-stone-800 truncate pr-2">{tpl.name}</span>
                  <span className="text-[9px] font-bold bg-stone-100 px-1 rounded text-stone-500 uppercase flex-shrink-0">
                    {tpl.channel}
                  </span>
                </div>
                <p className="text-[10px] text-stone-400 truncate mt-1">{tpl.body}</p>
              </button>
            ))}
          </div>

          {/* Right panel: editor & preview */}
          {selectedTemplate ? (
            <div className="space-y-4 md:col-span-2">
              <div className="flex items-center justify-between border-b border-stone-100 pb-3">
                <h5 className="text-sm font-semibold text-stone-800">Edit Template: {selectedTemplate.name}</h5>
                <div className="flex items-center gap-2">
                  <span className="text-xs text-stone-500">Active</span>
                  <Switch
                    checked={selectedTemplate.active}
                    onCheckedChange={(checked) => handleTemplateChange(selectedTemplate.id, { active: checked })}
                    className="scale-90 data-[state=checked]:bg-brand-primary"
                  />
                </div>
              </div>

              {selectedTemplate.channel === 'Email' && (
                <SettingsField label="Email Subject Header">
                  <input
                    type="text"
                    value={selectedTemplate.subject || ''}
                    onChange={(e) => handleTemplateChange(selectedTemplate.id, { subject: e.target.value })}
                    className={inputCls}
                  />
                </SettingsField>
              )}

              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-1">
                  <span className="text-xs font-semibold text-stone-600 block">Message Body</span>
                  <textarea
                    value={selectedTemplate.body}
                    onChange={(e) => handleTemplateChange(selectedTemplate.id, { body: e.target.value })}
                    className={`${inputCls} min-h-[140px] py-2 text-xs`}
                  />
                  <div className="flex flex-wrap gap-1 mt-1">
                    {['{bride_name}', '{appointment_date}', '{location_name}', '{payment_link}', '{pickup_link}'].map((v) => (
                      <button
                        key={v}
                        onClick={() => handleTemplateChange(selectedTemplate.id, { body: selectedTemplate.body + ' ' + v })}
                        className="text-[9px] font-semibold bg-stone-100 hover:bg-stone-200 text-stone-600 px-1.5 py-0.5 rounded transition-colors"
                      >
                        {v}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="space-y-3 bg-stone-50/50 p-4 border border-stone-200/80 rounded-xl">
                  <div className="flex items-center gap-1.5 text-stone-600 border-b border-stone-200/80 pb-2">
                    <Eye className="h-4 w-4" />
                    <span className="text-xs font-semibold">Live Preview</span>
                  </div>
                  {selectedTemplate.channel === 'Email' && (
                    <div className="text-[10px] text-stone-500">
                      <span className="font-semibold block">Subject:</span>
                      <p className="mt-0.5 bg-white p-2 border border-stone-200 rounded">{selectedTemplate.subject || 'No Subject Specified'}</p>
                    </div>
                  )}
                  <div className="text-[10px] text-stone-500">
                    <span className="font-semibold block">Content Body:</span>
                    <p className="mt-0.5 bg-white p-2 border border-stone-200 rounded min-h-[70px] whitespace-pre-wrap leading-relaxed">
                      {getResolvedPreview(selectedTemplate.body)}
                    </p>
                  </div>
                </div>
              </div>

              <div className="flex gap-2 items-end pt-3 border-t border-stone-100">
                <div className="flex-1">
                  <input
                    type="text"
                    placeholder={selectedTemplate.channel === 'Email' ? 'test@email.com' : '+1 (555) 555-5555'}
                    value={testSendPhoneEmail}
                    onChange={(e) => setTestSendPhoneEmail(e.target.value)}
                    className={`${inputCls} h-9 text-xs`}
                  />
                </div>
                <button
                  onClick={sendTestTemplate}
                  disabled={sendingTest}
                  className="flex items-center gap-1.5 rounded-lg bg-stone-900 px-4 py-2 h-9 text-xs font-semibold text-white hover:bg-stone-800 transition-colors disabled:opacity-50"
                >
                  <Send className="h-3.5 w-3.5" /> Dispatch test
                </button>
              </div>
            </div>
          ) : (
            <div className="md:col-span-2 flex items-center justify-center border border-dashed border-stone-200 rounded-xl p-8 text-stone-400 italic">
              Select a template to view details and edit values.
            </div>
          )}
        </div>
      </SettingsCard>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Database, Loader2, Download, RefreshCw, CheckCircle2, Trash2, Upload, FileSpreadsheet } from 'lucide-react';
import { toast } from '@vowos/design-system';
import { inputCls } from '@/components/vowos/ui';
import { Button } from '@vowos/design-system';
import { SettingsCard } from '../components/SettingsCard';
import { SettingsField } from '../components/SettingsField';
import { Switch } from '@vowos/design-system';
import { resolveEffectiveSetting, saveScopedSetting } from '@/lib/settings';
import { getActiveDataPlane, supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';

interface DataConfig {
  maxImportSizeMb: number;
  duplicateHandling: 'overwrite' | 'skip' | 'error';
  auditRetentionYears: number;
  commRetentionYears: number;
  stagingRetentionDays: number;
  backupIntervalHours: number;
}

const DEFAULT_DATA_CONFIG: DataConfig = {
  maxImportSizeMb: 10,
  duplicateHandling: 'skip',
  auditRetentionYears: 7,
  commRetentionYears: 3,
  stagingRetentionDays: 30,
  backupIntervalHours: 24,
};

interface DataSettingsTabProps {
  onDirtyChange: (dirty: boolean) => void;
  registerSaveRef: (saveFn: () => Promise<boolean>) => void;
  resetTrigger: number;
}

export function DataSettingsTab({
  onDirtyChange,
  registerSaveRef,
  resetTrigger,
}: DataSettingsTabProps) {
  const [loading, setLoading] = useState(true);
  const [settings, setSettings] = useState<DataConfig>(DEFAULT_DATA_CONFIG);
  const [dbSettings, setDbSettings] = useState<DataConfig>(DEFAULT_DATA_CONFIG);

  const [cleaningStaging, setCleaningStaging] = useState(false);
  const [importing, setImporting] = useState(false);
  const { userContext } = useAuth();

  const handleExportData = async () => {
    toast({
      title: 'Preparing Data Export',
      description: 'Your export is being generated in the background. We will email you a secure link when it is ready.',
    });
  };

  const handleAccountDeletion = async () => {
    if (confirm('Are you sure you want to request account deletion? This action cannot be undone.')) {
      toast({
        title: 'Deletion Request Submitted',
        description: 'Your account is now pending deletion. The process will complete in 30 days.',
      });
    }
  };

  const loadSettings = async () => {
    setLoading(true);
    const dataPlane = getActiveDataPlane();
    const result = await resolveEffectiveSetting<DataConfig>(
      'data_import_settings',
      'data_import_settings',
      { dataPlane },
      DEFAULT_DATA_CONFIG
    );
    const fallback = { ...DEFAULT_DATA_CONFIG, ...result.value };
    setSettings(fallback);
    setDbSettings(fallback);
    setLoading(false);
  };

  useEffect(() => {
    loadSettings();
  }, [resetTrigger]);

  const isDirty = JSON.stringify(settings) !== JSON.stringify(dbSettings);

  useEffect(() => {
    onDirtyChange(isDirty);
  }, [isDirty]);

  const handleSave = async (reason?: string): Promise<boolean> => {
    try {
      const dataPlane = getActiveDataPlane();
      await saveScopedSetting('data_import_settings', 'data_import_settings', settings, { dataPlane }, reason);

      toast({
        title: 'Data & Import settings saved',
        description: 'Retention details have been updated successfully.',
      });
      setDbSettings(settings);
      return true;
    } catch (err: any) {
      toast({
        title: 'Could not save data settings',
        description: err.message,
        variant: 'destructive',
      });
      return false;
    }
  };

  useEffect(() => {
    registerSaveRef(handleSave);
  }, [settings]);



  const clearStagingData = async () => {
    setCleaningStaging(true);
    try {
      const { error } = await supabase.rpc('clear_staging_data');
      if (error) throw error;
      toast({
        title: 'Staging files purged',
        description: 'Released temporary spreadsheet upload blocks.',
      });
    } catch (err: any) {
      toast({
        title: 'Cache purge failed',
        description: err.message,
        variant: 'destructive',
      });
    } finally {
      setCleaningStaging(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > (settings.maxImportSizeMb * 1024 * 1024)) {
      toast({
        title: 'File too large',
        description: `Please upload a file smaller than ${settings.maxImportSizeMb} MB.`,
        variant: 'destructive',
      });
      return;
    }

    setImporting(true);
    try {
      toast({ title: 'Uploading import file...' });
      
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Not authenticated");

      const filePath = `${user.id}/imports/${Date.now()}_${file.name}`;

      const { error } = await supabase.storage.from('data-imports').upload(filePath, file);
      if (error) throw error;
      
      toast({ 
        title: 'Import completed',
        description: `Successfully uploaded ${file.name}. Background processing started.`,
      });
    } catch (err: any) {
      toast({
        title: 'Import failed',
        description: err.message,
        variant: 'destructive'
      });
    } finally {
      setImporting(false);
      // Reset input
      e.target.value = '';
    }
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-10 text-sm text-stone-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading data guidelinesΓÇª
      </div>
    );
  }

  const safeSettings = settings || DEFAULT_DATA_CONFIG;

  return (
    <div className="space-y-6">
      
      <SettingsCard
        title="Import Center"
        description="Bulk import your historical customer records, leads, or inventory lists via CSV/Excel."
        icon={<FileSpreadsheet className="h-5 w-5" />}
      >
        <div className="p-8 border-2 border-dashed border-stone-200 rounded-xl bg-stone-50/50 flex flex-col items-center justify-center text-center">
          <div className="h-12 w-12 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center mb-4">
            <Upload className="h-6 w-6" />
          </div>
          <h3 className="text-sm font-semibold text-stone-900 mb-1">Click to upload or drag and drop</h3>
          <p className="text-xs text-stone-500 mb-6 max-w-sm">
            Supported formats: CSV, XLSX. Maximum file size: {safeSettings.maxImportSizeMb} MB. 
            Ensure your columns map correctly to system entities.
          </p>
          
          <div className="relative">
            <Button disabled={importing} className="gap-2 bg-stone-900 hover:bg-stone-800 text-white">
              {importing ? <Loader2 className="h-4 w-4 animate-spin" /> : <Database className="h-4 w-4" />}
              {importing ? 'Processing Data...' : 'Select File'}
            </Button>
            <input 
              type="file" 
              accept=".csv,.xlsx" 
              onChange={handleFileUpload}
              disabled={importing}
              className="absolute inset-0 opacity-0 cursor-pointer disabled:cursor-not-allowed" 
            />
          </div>
        </div>
      </SettingsCard>
      
      <div className="grid gap-6 lg:grid-cols-2">
        <SettingsCard
          title="Import Validation & Deduplication"
          description="Configure rules for spreadsheet parsing and matching customer records."
          icon={<Database className="h-5 w-5" />}
        >
          <div className="space-y-4">
            <SettingsField
              label="Maximum import file size (MB)"
              description="Restricts large files to prevent browser out-of-memory errors."
            >
              <input
                type="number"
                value={safeSettings.maxImportSizeMb || 10}
                onChange={(e) => setSettings({ ...safeSettings, maxImportSizeMb: parseInt(e.target.value) || 5 })}
                className={inputCls}
                min="1"
                max="50"
              />
            </SettingsField>

            <SettingsField
              label="Duplicate record resolution"
              description="Action taken when an imported record matches an existing account."
            >
              <select
                value={safeSettings.duplicateHandling}
                onChange={(e) => setSettings({ ...safeSettings, duplicateHandling: e.target.value as any })}
                className={inputCls}
              >
                <option value="skip">Skip & Keep Existing</option>
                <option value="overwrite">Overwrite with Imported Details</option>
                <option value="error">Halt Import & Raise Conflict Error</option>
              </select>
            </SettingsField>

            <div className="pt-2 border-t border-stone-100 flex items-center justify-between">
              <div>
                <span className="text-xs font-semibold text-stone-700">Clear Temp Staging Cache</span>
                <span className="block text-[10px] text-stone-400">Purge parsed CSV grids from memory.</span>
              </div>
              <button
                onClick={clearStagingData}
                disabled={cleaningStaging}
                className="flex items-center gap-1.5 rounded-lg border border-red-200 bg-white hover:bg-red-50 text-red-600 px-3 py-1.5 text-xs font-semibold transition-colors disabled:opacity-50"
              >
                <Trash2 className="h-3.5 w-3.5" /> Purge Cache
              </button>
            </div>
          </div>
        </SettingsCard>

        <SettingsCard
          title="Data Retention Policies"
          description="Establish data purging schedules. Storage durations must comply with legal requirements."
          icon={<Database className="h-5 w-5" />}
        >
          <div className="space-y-4">
            <SettingsField
              label="Audit logs retention (years)"
              description="Audit events must remain archived for compliance."
            >
              <input
                type="number"
                value={safeSettings.auditRetentionYears || 7}
                onChange={(e) => setSettings({ ...safeSettings, auditRetentionYears: parseInt(e.target.value) || 7 })}
                className={inputCls}
                min="7"
                max="15"
              />
            </SettingsField>

            <SettingsField
              label="Communication logs retention (years)"
              description="Archival span for client email/SMS logs."
            >
              <input
                type="number"
                value={safeSettings.commRetentionYears || 3}
                onChange={(e) => setSettings({ ...safeSettings, commRetentionYears: parseInt(e.target.value) || 3 })}
                className={inputCls}
                min="1"
              />
            </SettingsField>

            <SettingsField
              label="Staging data retention (days)"
              description="Prune temporary import files after this period."
            >
              <input
                type="number"
                value={safeSettings.stagingRetentionDays || 30}
                onChange={(e) => setSettings({ ...safeSettings, stagingRetentionDays: parseInt(e.target.value) || 30 })}
                className={inputCls}
                min="5"
              />
            </SettingsField>
          </div>
        </SettingsCard>
      </div>

      <div className="grid gap-6 lg:grid-cols-2">
        <SettingsCard
          title="Self-Service Data Export"
          description="Download a complete archive of your tenant's data in JSON and CSV formats for compliance."
          icon={<Download className="h-5 w-5" />}
        >
          <div className="space-y-4">
            <p className="text-sm text-stone-500">
              The export contains your customer records, financial ledgers, settings, and communication history. Due to the size, exports are processed asynchronously.
            </p>
            <Button onClick={handleExportData} className="w-full gap-2">
              <Download className="h-4 w-4" /> Request Data Archive
            </Button>
          </div>
        </SettingsCard>

        <SettingsCard
          title="Danger Zone: Account Deletion"
          description="Request a complete wipe of your tenant data from the platform."
          icon={<Trash2 className="h-5 w-5 text-red-500" />}
        >
          <div className="space-y-4 rounded-xl border border-red-200 bg-red-50 p-4">
            <p className="text-sm text-red-800">
              Requesting deletion will suspend your account immediately and place it in a 30-day soft-delete period. After 30 days, all PII and configuration data will be hard purged.
            </p>
            <Button variant="destructive" onClick={handleAccountDeletion} className="w-full gap-2">
              <Trash2 className="h-4 w-4" /> Request Account Deletion
            </Button>
          </div>
        </SettingsCard>
      </div>

    </div>
  );
}

import { useEffect, useState } from 'react';
import { 
  FileText, 
  Loader2, 
  Plus, 
  MoreVertical,
  Pencil,
  Trash2,
  FileCheck,
  FileDown,
  History,
  Copy,
  Upload
} from 'lucide-react';
import { toast } from '@vowos/design-system';
import { Button } from '@vowos/design-system';
import { inputCls } from '@/components/vowos/ui';
import { PageHeader } from '../../ui';
import { supabase, getActiveDataPlane } from '@/lib/supabase';
import { SettingsCard } from '../components/SettingsCard';
import {
  DocumentSettings,
  DEFAULT_DOCUMENT_SETTINGS,
  resolveEffectiveSetting,
  saveScopedSetting,
} from '@/lib/settings';

interface DocumentTemplate {
  id: string;
  document_type: string;
  template_name: string;
  version: number;
  is_active: boolean;
  is_default: boolean;
  file_path: string | null;
  file_type: string | null;
  updated_at: string;
}

interface DocumentsSettingsTabProps {
  onDirtyChange: (dirty: boolean) => void;
  registerSaveRef: (saveFn: () => Promise<boolean>) => void;
  resetTrigger: number;
}

export function DocumentsSettingsTab({
  onDirtyChange,
  registerSaveRef,
  resetTrigger,
}: DocumentsSettingsTabProps) {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [templates, setTemplates] = useState<DocumentTemplate[]>([]);
  const [settings, setSettings] = useState<DocumentSettings>(DEFAULT_DOCUMENT_SETTINGS);
  const [dbSettings, setDbSettings] = useState<DocumentSettings>(DEFAULT_DOCUMENT_SETTINGS);

  const loadTemplates = async () => {
    try {
      setLoading(true);
      const dataPlane = getActiveDataPlane();
      
      const { data, error } = await supabase
        .from('document_templates')
        .select('*')
        .eq('data_plane', dataPlane)
        .order('document_type', { ascending: true })
        .order('version', { ascending: false });

      if (error) throw error;
      setTemplates(data || []);

      const result = await resolveEffectiveSetting<DocumentSettings>(
        'documents',
        'document_templates',
        { dataPlane },
        DEFAULT_DOCUMENT_SETTINGS
      );
      setSettings(result.value);
      setDbSettings(result.value);
    } catch (err: any) {
      console.error("Error loading templates:", err);
      toast({
        title: 'Could not load templates',
        description: err.message,
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadTemplates();
  }, [resetTrigger]);

  const isDirty = JSON.stringify(settings) !== JSON.stringify(dbSettings);

  useEffect(() => {
    onDirtyChange(isDirty);
  }, [isDirty]);

  const handleSave = async (reason?: string): Promise<boolean> => {
    setSaving(true);
    try {
      const dataPlane = getActiveDataPlane();
      await saveScopedSetting('documents', 'document_templates', settings, { dataPlane }, reason);
      
      toast({
        title: 'Document settings saved',
        description: 'Template typography and configuration updated.',
      });
      setDbSettings(settings);
      setSaving(false);
      return true;
    } catch (err: any) {
      setSaving(false);
      toast({
        title: 'Could not save document settings',
        description: err.message,
        variant: 'destructive',
      });
      return false;
    }
  };

  useEffect(() => {
    registerSaveRef(handleSave);
  }, [settings]);

  const handleUploadTemplate = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      toast({ title: 'Uploading template...' });
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Not authenticated");

      const fileExt = file.name.split('.').pop();
      const filePath = `${user.id}/${Date.now()}_${file.name}`;

      const { error: uploadError } = await supabase.storage
        .from('document-templates')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      // Insert metadata
      const { error: dbError } = await supabase.from('document_templates').insert({
        data_plane: getActiveDataPlane(),
        document_type: 'Custom',
        template_name: file.name,
        file_path: filePath,
        file_type: fileExt,
        is_active: true,
        version: 1,
      });

      if (dbError) throw dbError;

      toast({ title: 'Template uploaded successfully' });
      loadTemplates();
    } catch (err: any) {
      toast({
        title: 'Upload failed',
        description: err.message,
        variant: 'destructive'
      });
    }
  };

  const handleSetDefault = async (id: string, docType: string) => {
    try {
      // Unset default for same type
      await supabase.from('document_templates')
        .update({ is_default: false })
        .eq('document_type', docType)
        .eq('data_plane', getActiveDataPlane());
        
      // Set new default
      await supabase.from('document_templates')
        .update({ is_default: true })
        .eq('id', id);
        
      toast({ title: 'Default template updated' });
      loadTemplates();
    } catch (err: any) {
      toast({ title: 'Update failed', description: err.message, variant: 'destructive' });
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this template?')) return;
    try {
      await supabase.from('document_templates').delete().eq('id', id);
      toast({ title: 'Template deleted' });
      loadTemplates();
    } catch (err: any) {
      toast({ title: 'Delete failed', description: err.message, variant: 'destructive' });
    }
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-10 text-sm text-stone-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading Template CenterΓÇª
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-lg font-medium text-stone-900">Template Center</h2>
          <p className="text-sm text-stone-500">Manage templates for Quotes, Contracts, Invoices, and more.</p>
        </div>
        <div className="flex gap-3">
          <Button variant="outline" className="gap-2 relative overflow-hidden">
            <Upload className="h-4 w-4" />
            Upload PDF/DOCX
            <input 
              type="file" 
              accept=".pdf,.docx" 
              className="absolute inset-0 opacity-0 cursor-pointer"
              onChange={handleUploadTemplate}
            />
          </Button>
          <Button className="gap-2 bg-stone-900 text-white hover:bg-stone-800">
            <Plus className="h-4 w-4" />
            New Template
          </Button>
        </div>
      </div>

      <div className="bg-white rounded-xl border border-stone-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="bg-stone-50 text-stone-500 font-medium border-b border-stone-200">
              <tr>
                <th className="px-6 py-4">Document Type</th>
                <th className="px-6 py-4">Template Name</th>
                <th className="px-6 py-4">Version</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-stone-100">
              {templates.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-8 text-center text-stone-500">
                    No templates found. Upload one to get started.
                  </td>
                </tr>
              ) : (
                templates.map((tpl) => (
                  <tr key={tpl.id} className="hover:bg-stone-50/50 transition-colors">
                    <td className="px-6 py-4 font-medium text-stone-900">
                      {tpl.document_type}
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        <FileCheck className="h-4 w-4 text-stone-400" />
                        {tpl.template_name}
                        {tpl.is_default && (
                          <span className="bg-stone-100 text-stone-600 px-2 py-0.5 rounded text-xs font-medium">Default</span>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4 text-stone-500">
                      v{tpl.version}.0
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${tpl.is_active ? 'bg-emerald-100 text-emerald-700' : 'bg-stone-100 text-stone-600'}`}>
                        {tpl.is_active ? 'Active' : 'Archived'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-2">
                        {!tpl.is_default && tpl.is_active && (
                          <Button variant="ghost" size="sm" onClick={() => handleSetDefault(tpl.id, tpl.document_type)}>
                            Set Default
                          </Button>
                        )}
                        <Button variant="ghost" size="sm" className="h-8 w-8 p-0" title="Edit">
                          <Pencil className="h-4 w-4 text-stone-500" />
                        </Button>
                        <Button variant="ghost" size="sm" className="h-8 w-8 p-0" onClick={() => handleDelete(tpl.id)} title="Delete">
                          <Trash2 className="h-4 w-4 text-brand-primary" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
      
      {/* Configuration Defaults */}
      <SettingsCard
        title="Template Configuration & Typography"
        description="Establish universal styling parameters that cascade across all generated PDF documents unless overridden by the template."
        icon={<FileText className="h-5 w-5" />}
      >
        <div className="grid gap-4 sm:grid-cols-2">
          <div className="sm:col-span-2 text-sm text-stone-500 mb-2">
            These global settings will be applied automatically to any active templates without specific overrides.
          </div>
          <div>
            <label className="block text-sm font-medium text-stone-700 mb-1">Brand Logo URL</label>
            <input 
              type="text" 
              placeholder="https://..." 
              className={inputCls} 
              value={settings.brandLogoUrl}
              onChange={(e) => setSettings({ ...settings, brandLogoUrl: e.target.value })}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-stone-700 mb-1">Primary Font Family</label>
            <select 
              className={inputCls}
              value={settings.primaryFontFamily}
              onChange={(e) => setSettings({ ...settings, primaryFontFamily: e.target.value })}
            >
              <option value="Inter">Inter</option>
              <option value="Roboto">Roboto</option>
              <option value="Playfair Display">Playfair Display</option>
              <option value="EB Garamond">EB Garamond</option>
            </select>
          </div>
        </div>
      </SettingsCard>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Flag, Loader2, Plus, Trash2 } from 'lucide-react';
import { toast } from '@vowos/design-system';
import { inputCls } from '@/components/vowos/ui';
import { SettingsCard } from '../components/SettingsCard';
import { SettingsField } from '../components/SettingsField';
import { Switch } from '@vowos/design-system';
import { resolveEffectiveSetting, saveScopedSetting, DEFAULT_FEATURE_FLAGS, FeatureFlag } from '@/lib/settings';
import { getActiveDataPlane } from '@/lib/supabase';

interface FeatureFlagsSettingsTabProps {
  onDirtyChange: (dirty: boolean) => void;
  registerSaveRef: (saveFn: () => Promise<boolean>) => void;
  resetTrigger: number;
}

export function FeatureFlagsSettingsTab({
  onDirtyChange,
  registerSaveRef,
  resetTrigger,
}: FeatureFlagsSettingsTabProps) {
  const [loading, setLoading] = useState(true);
  const [flags, setFlags] = useState<FeatureFlag[]>(DEFAULT_FEATURE_FLAGS);
  const [dbFlags, setDbFlags] = useState<FeatureFlag[]>(DEFAULT_FEATURE_FLAGS);

  const loadSettings = async () => {
    setLoading(true);
    const dataPlane = getActiveDataPlane();
    const result = await resolveEffectiveSetting<FeatureFlag[]>(
      'feature_flags',
      'feature_flags',
      { dataPlane },
      DEFAULT_FEATURE_FLAGS
    );
    const fallback = Array.isArray(result.value) ? result.value : DEFAULT_FEATURE_FLAGS;
    setFlags(fallback);
    setDbFlags(fallback);
    setLoading(false);
  };

  useEffect(() => {
    loadSettings();
  }, [resetTrigger]);

  const isDirty = JSON.stringify(flags) !== JSON.stringify(dbFlags);

  useEffect(() => {
    onDirtyChange(isDirty);
  }, [isDirty]);

  const handleSave = async (reason?: string): Promise<boolean> => {
    try {
      const dataPlane = getActiveDataPlane();
      await saveScopedSetting('feature_flags', 'feature_flags', flags, { dataPlane }, reason);

      toast({
        title: 'Feature flags updated',
        description: 'Staged releases rules updated successfully.',
      });
      setDbFlags(flags);
      return true;
    } catch (err: any) {
      toast({
        title: 'Could not save feature flags',
        description: err.message,
        variant: 'destructive',
      });
      return false;
    }
  };

  useEffect(() => {
    registerSaveRef(handleSave);
  }, [flags]);

  const updateFlag = (id: string, fields: Partial<FeatureFlag>) => {
    setFlags(
      flags.map((f) => (f.id === id ? { ...f, ...fields } as typeof f : f))
    );
  };

  const addFlag = () => {
    const newFlag: FeatureFlag = {
      id: Date.now().toString(),
      name: 'NEW_UNRELEASED_FEATURE',
      description: 'Custom feature toggle for dev staging.',
      enabled: false,
      rolloutPct: 0,
    };
    setFlags([...flags, newFlag]);
  };

  const deleteFlag = (id: string) => {
    setFlags(flags.filter((f) => f.id !== id));
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-10 text-sm text-stone-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading staged rolloutsΓÇª
      </div>
    );
  }

  const safeFlags = Array.isArray(flags) ? flags : DEFAULT_FEATURE_FLAGS;

  return (
    <div className="space-y-6">
      <SettingsCard
        title="Feature Rollouts & Staging Flags"
        description="Enable or disable experimental features for selected stores and stylists."
        icon={<Flag className="h-5 w-5" />}
      >
        <div className="space-y-4">
          <div className="flex justify-between items-center pb-2 border-b border-stone-100">
            <span className="text-[10px] font-bold text-stone-400 uppercase tracking-wider">Active Feature Toggles</span>
            <button
              onClick={addFlag}
              className="text-[10px] font-bold text-brand-primary hover:text-brand-primary px-2 py-0.5 border border-border-subtle rounded hover:bg-brand-soft/50"
            >
              + Add Custom Flag
            </button>
          </div>

          <div className="divide-y divide-stone-100 rounded-xl border border-stone-200 bg-white overflow-hidden">
            {safeFlags.map((flag) => (
              <div key={flag.id} className="p-4 space-y-3">
                <div className="flex justify-between items-start">
                  <div>
                    <input
                      type="text"
                      value={flag.name}
                      onChange={(e) => updateFlag(flag.id, { name: e.target.value })}
                      className="text-xs font-bold text-stone-800 uppercase tracking-wider bg-transparent border-b border-transparent hover:border-stone-200 focus:border-stone-800 outline-none w-64"
                    />
                    <input
                      type="text"
                      value={flag.description}
                      onChange={(e) => updateFlag(flag.id, { description: e.target.value })}
                      className="text-[11px] text-stone-400 mt-1 block w-96 bg-transparent border-b border-transparent hover:border-stone-200 focus:border-stone-800 outline-none"
                    />
                  </div>

                  <div className="flex items-center gap-3">
                    <button
                      onClick={() => deleteFlag(flag.id)}
                      className="text-stone-400 hover:text-red-500 p-1"
                      title="Delete Flag"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                    <Switch
                      checked={flag.enabled}
                      onCheckedChange={(checked) => updateFlag(flag.id, { enabled: checked })}
                      className="data-[state=checked]:bg-brand-primary"
                    />
                  </div>
                </div>

                <div className="flex items-center gap-4 pt-2 border-t border-stone-50">
                  <div className="flex-1 flex items-center gap-2">
                    <span className="text-[10px] text-stone-500 font-medium">Staged Rollout:</span>
                    <input
                      type="range"
                      min="0"
                      max="100"
                      value={flag.rolloutPct}
                      onChange={(e) => updateFlag(flag.id, { rolloutPct: parseInt(e.target.value) || 0 })}
                      className="flex-1 accent-rose-500 h-1 bg-stone-200 rounded-lg cursor-pointer"
                    />
                  </div>
                  <span className="text-[10px] text-stone-600 font-bold bg-stone-50 border border-stone-200 px-1.5 py-0.5 rounded w-12 text-center">
                    {flag.rolloutPct}%
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </SettingsCard>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Plug, Loader2, Sparkles, AlertCircle, RefreshCw, CheckCircle2, XCircle, Settings } from 'lucide-react';
import { toast } from '@vowos/design-system';
import { inputCls } from '@/components/vowos/ui';
import { Button } from '@vowos/design-system';
import { SettingsCard } from '../components/SettingsCard';
import { SettingsField } from '../components/SettingsField';
import { Switch } from '@vowos/design-system';
import { resolveEffectiveSetting, saveScopedSetting, DEFAULT_AI_SETTINGS, AISettings } from '@/lib/settings';
import { getActiveDataPlane, supabase } from '@/lib/supabase';

interface IntegrationState {
  id: string;
  provider: string;
  status: 'connected' | 'disconnected' | 'error';
  last_sync_at: string | null;
  error_message: string | null;
}

interface StripeSettings {
  testMode: boolean;
  successUrl: string;
  cancelUrl: string;
  acceptedCard: boolean;
  acceptedAch: boolean;
  disputeEmails: string;
}

const DEFAULT_STRIPE_SETTINGS: StripeSettings = {
  testMode: true,
  successUrl: 'https://robertsenterprises.com/checkout/success',
  cancelUrl: 'https://robertsenterprises.com/checkout/cancel',
  acceptedCard: true,
  acceptedAch: true,
  disputeEmails: 'billing@robertsenterprises.com, accounts@robertsenterprises.com',
};

interface IntegrationsSettingsTabProps {
  onDirtyChange: (dirty: boolean) => void;
  registerSaveRef: (saveFn: () => Promise<boolean>) => void;
  resetTrigger: number;
}

export function IntegrationsSettingsTab({
  onDirtyChange,
  registerSaveRef,
  resetTrigger,
}: IntegrationsSettingsTabProps) {
  const [loading, setLoading] = useState(true);
  const [aiSettings, setAiSettings] = useState<AISettings>(DEFAULT_AI_SETTINGS);
  const [dbAiSettings, setDbAiSettings] = useState<AISettings>(DEFAULT_AI_SETTINGS);
  
  const [stripe, setStripe] = useState<StripeSettings>(DEFAULT_STRIPE_SETTINGS);
  const [dbStripe, setDbStripe] = useState<StripeSettings>(DEFAULT_STRIPE_SETTINGS);
  
  const [stripeIntegration, setStripeIntegration] = useState<IntegrationState | null>(null);

  const loadSettings = async () => {
    try {
      setLoading(true);
      const dataPlane = getActiveDataPlane();
      
      const [aiResult, stripeResult] = await Promise.all([
        resolveEffectiveSetting<AISettings>('integrations', 'ai_settings', { dataPlane }, DEFAULT_AI_SETTINGS),
        resolveEffectiveSetting<StripeSettings>('integrations', 'stripe_settings', { dataPlane }, DEFAULT_STRIPE_SETTINGS)
      ]);
      
      setAiSettings(aiResult?.value || DEFAULT_AI_SETTINGS);
      setDbAiSettings(aiResult?.value || DEFAULT_AI_SETTINGS);
      setStripe(stripeResult?.value || DEFAULT_STRIPE_SETTINGS);
      setDbStripe(stripeResult?.value || DEFAULT_STRIPE_SETTINGS);

      // Load integration status
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        const { data: membership } = await supabase.from('business_memberships').select('business_id').eq('user_id', user.id).maybeSingle();
        if (membership) {
          const { data: integration } = await supabase.from('integrations')
            .select('*')
            .eq('business_id', membership.business_id)
            .eq('provider', 'stripe')
            .maybeSingle();
            
          setStripeIntegration(integration);
        }
      }
    } catch (err) {
      console.error("Failed to load integrations", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadSettings();
  }, [resetTrigger]);

  const isDirty =
    JSON.stringify(aiSettings) !== JSON.stringify(dbAiSettings) ||
    JSON.stringify(stripe) !== JSON.stringify(dbStripe);

  useEffect(() => {
    onDirtyChange(isDirty);
  }, [isDirty]);

  const handleSave = async (reason?: string): Promise<boolean> => {
    try {
      const dataPlane = getActiveDataPlane();
      await saveScopedSetting('integrations', 'ai_settings', aiSettings, { dataPlane }, reason);
      await saveScopedSetting('integrations', 'stripe_settings', stripe, { dataPlane }, reason);
      
      toast({
        title: 'Integrations & AI settings saved',
        description: 'Integration parameters updated successfully.',
      });
      setDbAiSettings(aiSettings);
      setDbStripe(stripe);
      return true;
    } catch (err: any) {
      toast({
        title: 'Could not save integrations settings',
        description: err.message,
        variant: 'destructive',
      });
      return false;
    }
  };

  useEffect(() => {
    registerSaveRef(handleSave);
  }, [aiSettings, stripe]);

  const handleToggleStripe = async () => {
    if (stripeIntegration?.status === 'connected') {
      if (confirm('Disconnect Stripe? You will no longer be able to process payments.')) {
        await supabase.from('integrations').update({ status: 'disconnected', access_token: null }).eq('id', stripeIntegration.id);
        setStripeIntegration({ ...stripeIntegration, status: 'disconnected' });
        toast({ title: 'Stripe disconnected' });
      }
    } else {
      toast({ title: 'Connecting to Stripe...', description: 'Verifying integration state...' });
      try {
        const { data, error } = await supabase.rpc('connect_stripe_integration', { 
          integration_id: stripeIntegration?.id 
        });
        if (error) throw error;
        setStripeIntegration(data as IntegrationState);
        toast({ title: 'Stripe connected securely' });
      } catch (err: any) {
        toast({ title: 'Connection failed', description: err.message, variant: 'destructive' });
      }
    }
  };


  if (loading) {
    return (
      <div className="flex items-center gap-2 py-10 text-sm text-stone-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading external adaptersΓÇª
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <SettingsCard
        title="Stripe Payment Gateways"
        description="Verify webhook feedback loops, disconnect keys, or adjust transaction endpoints."
        icon={<Plug className="h-5 w-5" />}
      >
        <div className="space-y-4">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between p-4 bg-stone-50 border border-stone-200 rounded-xl gap-4">
            <div className="flex items-center gap-3">
              {stripeIntegration?.status === 'connected' ? (
                <CheckCircle2 className="h-5 w-5 text-status-success flex-shrink-0" />
              ) : (
                <XCircle className="h-5 w-5 text-stone-400 flex-shrink-0" />
              )}
              <div>
                <span className="text-sm font-semibold text-stone-800">
                  {stripeIntegration?.status === 'connected' ? 'Stripe Connected' : 'Stripe Disconnected'}
                </span>
                <span className="block text-xs text-stone-400 mt-0.5">
                  {stripeIntegration?.status === 'connected' ? `Last sync: ${new Date(stripeIntegration.last_sync_at || '').toLocaleString()}` : 'Connect Stripe to process payments'}
                </span>
              </div>
            </div>
            <Button 
              variant={stripeIntegration?.status === 'connected' ? 'outline' : 'default'}
              className={stripeIntegration?.status !== 'connected' ? 'bg-indigo-600 hover:bg-indigo-700 text-white' : ''}
              onClick={handleToggleStripe}
            >
              {stripeIntegration?.status === 'connected' ? 'Disconnect' : 'Connect Stripe'}
            </Button>
          </div>

          <div className="grid gap-4 sm:grid-cols-2">
            <SettingsField
              label="Stripe Environment mode"
              description="Toggle sandbox payment simulation vs production processing."
            >
              <div className="flex items-center justify-between h-9 px-1">
                <span className="text-xs text-stone-500 font-medium">Test Mode (Sandbox Mode)</span>
                <Switch
                  checked={stripe.testMode}
                  onCheckedChange={(checked) => setStripe({ ...stripe, testMode: checked })}
                  className="data-[state=checked]:bg-brand-primary"
                />
              </div>
            </SettingsField>

            <SettingsField
              label="Webhook Callback Health"
              description="Feedback loops status from Stripe back to VowOS database."
            >
              <div className="flex items-center justify-between h-9 px-1">
                {stripeIntegration?.status === 'connected' ? (
                  <span className="text-xs font-semibold text-status-success">ΓùÅ Active & Listening</span>
                ) : (
                  <span className="text-xs font-semibold text-stone-400">Γùï Inactive</span>
                )}
              </div>
            </SettingsField>

            <SettingsField label="Checkout Success URL">
              <input
                type="text"
                value={stripe.successUrl}
                onChange={(e) => setStripe({ ...stripe, successUrl: e.target.value })}
                className={inputCls}
              />
            </SettingsField>

            <SettingsField label="Checkout Cancel URL">
              <input
                type="text"
                value={stripe.cancelUrl}
                onChange={(e) => setStripe({ ...stripe, cancelUrl: e.target.value })}
                className={inputCls}
              />
            </SettingsField>

            <SettingsField
              label="Dispute Alert Notifications"
              description="Email addresses notified immediately on chargebacks."
              className="sm:col-span-2"
            >
              <input
                type="text"
                value={stripe.disputeEmails}
                onChange={(e) => setStripe({ ...stripe, disputeEmails: e.target.value })}
                className={inputCls}
              />
            </SettingsField>
          </div>
        </div>
      </SettingsCard>

      <SettingsCard
        title="Machine Learning & Copilot Settings"
        description="Establish data protection filters and usage cost limits for AI matches."
        icon={<Sparkles className="h-5 w-5" />}
      >
        <div className="grid gap-4 sm:grid-cols-2">
          <SettingsField
            label="Enable AI Platform Features"
            description="Power stylist assignment suggestions and analytics using machine learning."
            className="sm:col-span-2"
          >
            <div className="flex items-center justify-between h-9 px-1">
              <span className="text-xs text-stone-500 font-medium">Active</span>
              <Switch
                checked={aiSettings.enabled}
                onCheckedChange={(checked) => setAiSettings({ ...aiSettings, enabled: checked })}
                className="data-[state=checked]:bg-brand-primary"
              />
            </div>
          </SettingsField>

          <SettingsField label="AI Provider Endpoint">
            <select
              value={aiSettings.provider}
              onChange={(e) => setAiSettings({ ...aiSettings, provider: e.target.value })}
              className={inputCls}
            >
              <option value="openai">OpenAI</option>
              <option value="anthropic">Anthropic</option>
              <option value="gemini">Google Gemini</option>
            </select>
          </SettingsField>

          <SettingsField label="Global Fallback Model">
            <input
              type="text"
              value={aiSettings.model}
              onChange={(e) => setAiSettings({ ...aiSettings, model: e.target.value })}
              className={inputCls}
            />
          </SettingsField>

          <SettingsField
            label="Temperature Controls"
            description="Controls creativity vs deterministic responses (0.0 - 1.0)."
          >
            <input
              type="number"
              value={aiSettings.temperature}
              onChange={(e) => setAiSettings({ ...aiSettings, temperature: parseFloat(e.target.value) || 0 })}
              className={inputCls}
              min="0"
              max="1"
              step="0.1"
            />
          </SettingsField>

          <SettingsField
            label="Monthly AI Cost Limit ($)"
            description="Budget boundary before AI suggestions get auto-disabled."
          >
            <input
              type="number"
              value={(aiSettings.costLimitCents / 100).toFixed(0)}
              onChange={(e) => setAiSettings({ ...aiSettings, costLimitCents: Math.round(parseFloat(e.target.value) * 100) || 0 })}
              className={inputCls}
              min="0"
            />
          </SettingsField>

          <div className="sm:col-span-2 rounded-xl bg-status-warning/10/50 border border-status-warning/20/60 p-4 flex items-start gap-3 mt-2">
            <AlertCircle className="h-5 w-5 text-status-warning flex-shrink-0 mt-0.5" />
            <div>
              <h6 className="text-xs font-semibold text-amber-800">Security Safeguard</h6>
              <p className="text-[11px] text-status-warning/80 mt-1 leading-relaxed">
                AI settings will never allow machine learning endpoints to bypass deterministic business policies,
                financial constraints, invoice approvals, or user roles.
              </p>
            </div>
          </div>
        </div>
      </SettingsCard>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Shirt, Loader2 } from 'lucide-react';
import { toast } from '@vowos/design-system';
import { inputCls } from '@/components/vowos/ui';
import { SettingsCard } from '../components/SettingsCard';
import { SettingsField } from '../components/SettingsField';
import { Switch } from '@vowos/design-system';
import { resolveEffectiveSetting, saveScopedSetting, DEFAULT_INVENTORY_SETTINGS, InventorySettings } from '@/lib/settings';
import { getActiveDataPlane } from '@/lib/supabase';

interface InventorySettingsTabProps {
  onDirtyChange: (dirty: boolean) => void;
  registerSaveRef: (saveFn: () => Promise<boolean>) => void;
  resetTrigger: number;
}

export function InventorySettingsTab({
  onDirtyChange,
  registerSaveRef,
  resetTrigger,
}: InventorySettingsTabProps) {
  const [loading, setLoading] = useState(true);
  const [settings, setSettings] = useState<InventorySettings>(DEFAULT_INVENTORY_SETTINGS);
  const [dbSettings, setDbSettings] = useState<InventorySettings>(DEFAULT_INVENTORY_SETTINGS);

  const loadSettings = async () => {
    setLoading(true);
    const dataPlane = getActiveDataPlane();
    const result = await resolveEffectiveSetting<InventorySettings>(
      'inventory_settings',
      'inventory_settings',
      { dataPlane },
      DEFAULT_INVENTORY_SETTINGS
    );
    setSettings(result.value);
    setDbSettings(result.value);
    setLoading(false);
  };

  useEffect(() => {
    loadSettings();
  }, [resetTrigger]);

  const isDirty = JSON.stringify(settings) !== JSON.stringify(dbSettings);

  useEffect(() => {
    onDirtyChange(isDirty);
  }, [isDirty]);

  const handleSave = async (reason?: string): Promise<boolean> => {
    try {
      const dataPlane = getActiveDataPlane();
      await saveScopedSetting('inventory_settings', 'inventory_settings', settings, { dataPlane }, reason);
      
      toast({
        title: 'Inventory rules saved',
        description: 'Tracking parameters have been updated successfully.',
      });
      setDbSettings(settings);
      return true;
    } catch (err: any) {
      toast({
        title: 'Could not save inventory settings',
        description: err.message,
        variant: 'destructive',
      });
      return false;
    }
  };

  useEffect(() => {
    registerSaveRef(handleSave);
  }, [settings]);

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-10 text-sm text-stone-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading inventory policiesΓÇª
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <SettingsCard
        title="Stock Rules & Safety Measures"
        description="Configure stock tracking triggers, barcode symbology, and low-stock warning limits."
        icon={<Shirt className="h-5 w-5" />}
      >
        <div className="grid gap-4 sm:grid-cols-2">
          <SettingsField
            label="Inventory tracking enabled"
            description="Actively monitor gown and accessory stock levels."
          >
            <div className="flex items-center justify-between h-9 px-1">
              <span className="text-xs text-stone-500 font-medium">Track stock levels</span>
              <Switch
                checked={settings.trackingEnabled}
                onCheckedChange={(checked) => setSettings({ ...settings, trackingEnabled: checked })}
                className="data-[state=checked]:bg-brand-primary"
              />
            </div>
          </SettingsField>

          <SettingsField
            label="Prevent negative stock levels"
            description="Forbid salesperson from posting orders for out-of-stock items."
          >
            <div className="flex items-center justify-between h-9 px-1">
              <span className="text-xs text-stone-500 font-medium">Block negative quantities</span>
              <Switch
                checked={settings.preventNegative}
                onCheckedChange={(checked) => setSettings({ ...settings, preventNegative: checked })}
                className="data-[state=checked]:bg-brand-primary"
              />
            </div>
          </SettingsField>

          <SettingsField
            label="Low-stock threshold (units)"
            description="Flag items in dashboard when inventory falls below this count."
          >
            <input
              type="number"
              value={settings.lowStockThreshold}
              onChange={(e) => setSettings({ ...settings, lowStockThreshold: parseInt(e.target.value) || 0 })}
              className={inputCls}
              min="0"
            />
          </SettingsField>

          <SettingsField
            label="Default reorder point (units)"
            description="Generate purchase order candidates when stock reaches this level."
          >
            <input
              type="number"
              value={settings.reorderThreshold}
              onChange={(e) => setSettings({ ...settings, reorderThreshold: parseInt(e.target.value) || 0 })}
              className={inputCls}
              min="0"
            />
          </SettingsField>

          <SettingsField
            label="Barcode format"
            description="Symbology pattern used for internal tags (e.g. CODE128, EAN13)."
          >
            <select
              value={settings.barcodeFormat}
              onChange={(e) => setSettings({ ...settings, barcodeFormat: e.target.value })}
              className={inputCls}
            >
              <option value="CODE128">Code 128 (Standard)</option>
              <option value="EAN13">EAN-13 (Retail)</option>
              <option value="UPCA">UPC-A (US retail)</option>
              <option value="QR">QR Code (High Density)</option>
            </select>
          </SettingsField>

          <SettingsField
            label="SKU generation pattern"
            description="Formula used to auto-generate SKUs from designer/color/size attributes."
          >
            <input
              type="text"
              value={settings.skuGenerationPattern}
              onChange={(e) => setSettings({ ...settings, skuGenerationPattern: e.target.value })}
              className={inputCls}
            />
          </SettingsField>
        </div>
      </SettingsCard>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { MapPin, Loader2, Calendar, Plus, Trash2 } from 'lucide-react';
import { toast } from '@vowos/design-system';
import { inputCls, btnSecondary } from '@/components/vowos/ui';
import { Switch } from '@vowos/design-system';
import {
  LocationSettings,
  DEFAULT_LOCATION_SETTINGS,
  resolveEffectiveSetting,
  saveScopedSetting,
} from '@/lib/settings';
import { getActiveDataPlane } from '@/lib/supabase';
import { LocationId, LOCATIONS } from '@/data/vowosData';
import { SettingsCard } from '../components/SettingsCard';
import { SettingsField } from '../components/SettingsField';

interface LocationSettingsTabProps {
  onDirtyChange: (dirty: boolean) => void;
  registerSaveRef: (saveFn: () => Promise<boolean>) => void;
  resetTrigger: number;
}

const DAYS_OF_WEEK = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

export function LocationSettingsTab({
  onDirtyChange,
  registerSaveRef,
  resetTrigger,
}: LocationSettingsTabProps) {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [locations, setLocations] = useState<Record<LocationId, LocationSettings>>(DEFAULT_LOCATION_SETTINGS);
  const [dbLocations, setDbLocations] = useState<Record<LocationId, LocationSettings>>(DEFAULT_LOCATION_SETTINGS);
  const [selectedLocId, setSelectedLocId] = useState<LocationId>('ido-br');

  // Holiday forms
  const [newHolidayName, setNewHolidayName] = useState('');
  const [newHolidayDate, setNewHolidayDate] = useState('');

  const loadSettings = async () => {
    setLoading(true);
    const dataPlane = getActiveDataPlane();
    const result = await resolveEffectiveSetting<Record<LocationId, LocationSettings>>(
      'location',
      'locations',
      { dataPlane },
      DEFAULT_LOCATION_SETTINGS
    );
    // Ensure all location structures exist
    const merged = { ...DEFAULT_LOCATION_SETTINGS, ...result.value };
    setLocations(merged);
    setDbLocations(JSON.parse(JSON.stringify(merged)));
    setLoading(false);
  };

  useEffect(() => {
    loadSettings();
  }, [resetTrigger]);

  const isDirty = JSON.stringify(locations) !== JSON.stringify(dbLocations);

  useEffect(() => {
    onDirtyChange(isDirty);
  }, [isDirty]);

  const handleSave = async (): Promise<boolean> => {
    setSaving(true);
    try {
      const dataPlane = getActiveDataPlane();
      await saveScopedSetting('location', 'locations', locations, { dataPlane }, 'Updated location configuration');
    } catch (err: any) {
      setSaving(false);
      toast({
        title: 'Could not save location settings',
        description: err.message,
        variant: 'destructive',
      });
      return false;
    }

    setSaving(false);
    toast({
      title: 'Settings saved',
      description: 'Location configurations and hours updated.',
    });
    setDbLocations(JSON.parse(JSON.stringify(locations)));
    return true;
  };

  useEffect(() => {
    registerSaveRef(handleSave);
  }, [locations]);

  const updateLoc = (updater: (loc: LocationSettings) => LocationSettings) => {
    setLocations((prev) => ({
      ...prev,
      [selectedLocId]: updater(prev[selectedLocId]),
    }));
  };

  const addHoliday = () => {
    if (!newHolidayName || !newHolidayDate) {
      toast({ title: 'Invalid Holiday', description: 'Provide a name and select a date.', variant: 'destructive' });
      return;
    }
    updateLoc((loc) => ({
      ...loc,
      holidayRules: [
        ...loc.holidayRules,
        { name: newHolidayName, date: newHolidayDate, closed: true },
      ],
    }));
    setNewHolidayName('');
    setNewHolidayDate('');
  };

  const removeHoliday = (index: number) => {
    updateLoc((loc) => ({
      ...loc,
      holidayRules: loc.holidayRules.filter((_, i) => i !== index),
    }));
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-10 text-sm text-stone-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading boutique locationsΓÇª
      </div>
    );
  }

  const currentLoc = locations[selectedLocId];

  return (
    <div className="space-y-6">
      {/* Location selector tab header */}
      <div className="flex flex-wrap gap-2 border-b border-stone-200 pb-3">
        {LOCATIONS.map((loc) => {
          const active = selectedLocId === loc.id;
          return (
            <button
              key={loc.id}
              onClick={() => setSelectedLocId(loc.id)}
              className={`rounded-lg px-4 py-2 text-xs font-semibold uppercase tracking-wider transition-all ${
                active
                  ? 'bg-stone-900 text-white shadow-sm'
                  : 'bg-white border border-stone-200 text-stone-600 hover:bg-stone-50'
              }`}
            >
              {loc.short}
            </button>
          );
        })}
      </div>

      <div className="grid gap-6 lg:grid-cols-3">
        {/* Basic Details & Address */}
        <div className="lg:col-span-2 space-y-6">
          <SettingsCard
            title="Location Details"
            description="Contact information and physical store parameters."
            icon={<MapPin className="h-5 w-5" />}
          >
            <div className="grid gap-4 sm:grid-cols-2">
              <SettingsField label="Boutique Display name">
                <input
                  type="text"
                  value={currentLoc.name}
                  onChange={(e) => updateLoc((l) => ({ ...l, name: e.target.value }))}
                  className={inputCls}
                />
              </SettingsField>

              <SettingsField label="Store Phone number">
                <input
                  type="text"
                  value={currentLoc.phone}
                  onChange={(e) => updateLoc((l) => ({ ...l, phone: e.target.value }))}
                  className={inputCls}
                />
              </SettingsField>

              <div className="sm:col-span-2">
                <SettingsField label="Address">
                  <input
                    type="text"
                    value={currentLoc.address}
                    onChange={(e) => updateLoc((l) => ({ ...l, address: e.target.value }))}
                    className={inputCls}
                  />
                </SettingsField>
              </div>
            </div>
          </SettingsCard>

          {/* Business Hours */}
          <SettingsCard
            title="Standard Business Hours"
            description="Configure standard opening and closing times. Appointments can only be booked during open hours."
            icon={<Calendar className="h-5 w-5" />}
          >
            <div className="divide-y divide-stone-100">
              {DAYS_OF_WEEK.map((day) => {
                const dayConfig = currentLoc.hours[day] || { open: '10:00 AM', close: '05:00 PM', closed: true };
                return (
                  <div key={day} className="flex items-center justify-between py-3">
                    <span className="w-28 text-sm font-medium text-stone-700">{day}</span>
                    
                    <div className="flex flex-1 items-center justify-end gap-3">
                      {!dayConfig.closed ? (
                        <div className="flex items-center gap-2 animate-fade-in">
                          <input
                            type="text"
                            value={dayConfig.open}
                            onChange={(e) =>
                              updateLoc((l) => {
                                const newHours = { ...l.hours };
                                newHours[day] = { ...dayConfig, open: e.target.value };
                                return { ...l, hours: newHours };
                              })
                            }
                            className="w-24 text-center rounded-lg border border-stone-300 bg-white px-2 py-1.5 text-xs focus:outline-none"
                            placeholder="e.g. 10:00 AM"
                          />
                          <span className="text-stone-400">to</span>
                          <input
                            type="text"
                            value={dayConfig.close}
                            onChange={(e) =>
                              updateLoc((l) => {
                                const newHours = { ...l.hours };
                                newHours[day] = { ...dayConfig, close: e.target.value };
                                return { ...l, hours: newHours };
                              })
                            }
                            className="w-24 text-center rounded-lg border border-stone-300 bg-white px-2 py-1.5 text-xs focus:outline-none"
                            placeholder="e.g. 05:00 PM"
                          />
                        </div>
                      ) : (
                        <span className="text-xs text-stone-400 font-semibold uppercase italic mr-12">Closed</span>
                      )}

                      <div className="flex items-center gap-2">
                        <span className="text-xs text-stone-500">Active</span>
                        <Switch
                          checked={!dayConfig.closed}
                          onCheckedChange={(checked) =>
                            updateLoc((l) => {
                              const newHours = { ...l.hours };
                              newHours[day] = { ...dayConfig, closed: !checked };
                              return { ...l, hours: newHours };
                            })
                          }
                          className="data-[state=checked]:bg-status-success"
                        />
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </SettingsCard>
        </div>

        {/* Holidays & Overrides */}
        <div className="space-y-6">
          <SettingsCard
            title="Closed Dates & Holidays"
            description="Add holiday dates where the store is temporarily closed."
          >
            <div className="space-y-4">
              <div className="grid gap-2">
                <input
                  type="text"
                  placeholder="Holiday label (e.g. Thanksgiving)"
                  value={newHolidayName}
                  onChange={(e) => setNewHolidayName(e.target.value)}
                  className="rounded-lg border border-stone-300 bg-white px-3 py-2 text-xs focus:outline-none"
                />
                <div className="flex gap-2">
                  <input
                    type="date"
                    value={newHolidayDate}
                    onChange={(e) => setNewHolidayDate(e.target.value)}
                    className="flex-1 rounded-lg border border-stone-300 bg-white px-3 py-2 text-xs focus:outline-none"
                  />
                  <button
                    onClick={addHoliday}
                    className="flex h-9 items-center justify-center rounded-lg bg-stone-900 px-3 text-white transition-colors hover:bg-stone-800"
                  >
                    <Plus className="h-4 w-4" />
                  </button>
                </div>
              </div>

              {currentLoc.holidayRules.length === 0 ? (
                <p className="text-center text-xs text-stone-400 py-6">No holiday closures set.</p>
              ) : (
                <ul className="space-y-2 max-h-80 overflow-y-auto pr-1">
                  {currentLoc.holidayRules.map((rule, idx) => (
                    <li
                      key={idx}
                      className="flex items-center justify-between rounded-lg border border-stone-100 bg-stone-50 p-2.5"
                    >
                      <div>
                        <p className="text-xs font-semibold text-stone-800">{rule.name}</p>
                        <p className="text-[10px] text-stone-500">{rule.date}</p>
                      </div>
                      <button
                        onClick={() => removeHoliday(idx)}
                        className="rounded-lg p-1.5 text-stone-400 hover:bg-brand-soft hover:text-brand-primary transition-colors"
                      >
                        <Trash2 className="h-3.5 w-3.5" />
                      </button>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </SettingsCard>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Bell, Loader2 } from 'lucide-react';
import { toast } from '@vowos/design-system';
import { inputCls } from '@/components/vowos/ui';
import { SettingsCard } from '../components/SettingsCard';
import { SettingsField } from '../components/SettingsField';
import { Switch } from '@vowos/design-system';
import { resolveEffectiveSetting, saveScopedSetting } from '@/lib/settings';
import { getActiveDataPlane } from '@/lib/supabase';

interface NotificationPref {
  inApp: boolean;
  email: boolean;
  sms: boolean;
}

interface NotificationSettings {
  appointments: NotificationPref;
  sales: NotificationPref;
  inventory: NotificationPref;
  transfers: NotificationPref;
}

const DEFAULT_NOTIFICATION_SETTINGS: NotificationSettings = {
  appointments: { inApp: true, email: true, sms: true },
  sales: { inApp: true, email: true, sms: false },
  inventory: { inApp: true, email: false, sms: false },
  transfers: { inApp: true, email: true, sms: true },
};

interface NotificationsSettingsTabProps {
  onDirtyChange: (dirty: boolean) => void;
  registerSaveRef: (saveFn: () => Promise<boolean>) => void;
  resetTrigger: number;
}

export function NotificationsSettingsTab({
  onDirtyChange,
  registerSaveRef,
  resetTrigger,
}: NotificationsSettingsTabProps) {
  const [loading, setLoading] = useState(true);
  const [settings, setSettings] = useState<NotificationSettings>(DEFAULT_NOTIFICATION_SETTINGS);
  const [dbSettings, setDbSettings] = useState<NotificationSettings>(DEFAULT_NOTIFICATION_SETTINGS);

  const loadSettings = async () => {
    setLoading(true);
    const dataPlane = getActiveDataPlane();
    const result = await resolveEffectiveSetting<NotificationSettings>(
      'alerts',
      'notification_settings',
      { dataPlane },
      DEFAULT_NOTIFICATION_SETTINGS
    );
    const data = result.value;
    const fallback = {
      appointments: { ...DEFAULT_NOTIFICATION_SETTINGS.appointments, ...data?.appointments },
      sales: { ...DEFAULT_NOTIFICATION_SETTINGS.sales, ...data?.sales },
      inventory: { ...DEFAULT_NOTIFICATION_SETTINGS.inventory, ...data?.inventory },
      transfers: { ...DEFAULT_NOTIFICATION_SETTINGS.transfers, ...data?.transfers },
    };
    setSettings(fallback);
    setDbSettings(fallback);
    setLoading(false);
  };

  useEffect(() => {
    loadSettings();
  }, [resetTrigger]);

  const isDirty = JSON.stringify(settings) !== JSON.stringify(dbSettings);

  useEffect(() => {
    onDirtyChange(isDirty);
  }, [isDirty]);

  const handleSave = async (reason?: string): Promise<boolean> => {
    try {
      const dataPlane = getActiveDataPlane();
      await saveScopedSetting('alerts', 'notification_settings', settings, { dataPlane }, reason);

      toast({
        title: 'Notification preferences saved',
        description: 'Default preferences updated successfully.',
      });
      setDbSettings(settings);
      return true;
    } catch (err: any) {
      toast({
        title: 'Could not save notification preferences',
        description: err.message,
        variant: 'destructive',
      });
      return false;
    }
  };

  useEffect(() => {
    registerSaveRef(handleSave);
  }, [settings]);

  const updatePreference = (category: keyof NotificationSettings, channel: keyof NotificationPref, checked: boolean) => {
    setSettings({
      ...settings,
      [category]: {
        ...settings[category],
        [channel]: checked,
      },
    });
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-10 text-sm text-stone-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading notification defaultsΓÇª
      </div>
    );
  }

  const categories: { key: keyof NotificationSettings; label: string; desc: string }[] = [
    { key: 'appointments', label: 'Appointments & Bookings', desc: 'Booking creations, confirmations, reschedules, or client cancellations.' },
    { key: 'sales', label: 'Invoices & Payments', desc: 'Surcharges applied, Stripe connections, invoice posts, or refunds.' },
    { key: 'inventory', label: 'Inventory & Stock Alerts', desc: 'Low-stock warnings, reorder points reached, or SKU exceptions.' },
    { key: 'transfers', label: 'Boutique Transfers', desc: 'Transfer arrivals, shipping carriers selected, or missing packages.' },
  ];

  return (
    <div className="space-y-6">
      <SettingsCard
        title="Default System Notifications"
        description="Toggle preferences for staff roles, departments, or custom location targets."
        icon={<Bell className="h-5 w-5" />}
      >
        <div className="space-y-6">
          {categories.map(({ key, label, desc }) => (
            <div key={key} className="flex flex-col md:flex-row justify-between pb-6 border-b border-stone-100 last:pb-0 last:border-0 gap-4">
              <div className="max-w-md">
                <h5 className="text-sm font-semibold text-stone-800">{label}</h5>
                <p className="text-xs text-stone-400 mt-1">{desc}</p>
              </div>

              <div className="flex items-center gap-6">
                <div className="flex items-center gap-2">
                  <span className="text-xs text-stone-500 font-medium">In-app</span>
                  <Switch
                    checked={settings[key]?.inApp}
                    onCheckedChange={(checked) => updatePreference(key, 'inApp', checked)}
                    className="data-[state=checked]:bg-brand-primary"
                  />
                </div>

                <div className="flex items-center gap-2">
                  <span className="text-xs text-stone-500 font-medium">Email</span>
                  <Switch
                    checked={settings[key]?.email}
                    onCheckedChange={(checked) => updatePreference(key, 'email', checked)}
                    className="data-[state=checked]:bg-brand-primary"
                  />
                </div>

                <div className="flex items-center gap-2">
                  <span className="text-xs text-stone-500 font-medium">SMS</span>
                  <Switch
                    checked={settings[key]?.sms}
                    onCheckedChange={(checked) => updatePreference(key, 'sms', checked)}
                    className="data-[state=checked]:bg-brand-primary"
                  />
                </div>
              </div>
            </div>
          ))}
        </div>
      </SettingsCard>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Building, Loader2 } from 'lucide-react';
import { toast } from '@vowos/design-system';
import { inputCls } from '@/components/vowos/ui';
import {
  OrganizationSettings,
