      const { error } = await supabase.rpc('revoke_all_sessions');
      if (error) throw error;
      toast({
        title: 'Sessions terminated',
        description: 'All active staff authentication cookies have been invalidated except yours.',
      });
    } catch (err: any) {
      toast({
        title: 'Revoke sessions failed',
        description: err.message,
        variant: 'destructive',
      });
    } finally {
      setRevokingSessions(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-10 text-sm text-stone-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading credentials policyΓÇª
      </div>
    );
  }

  const safeSettings = settings || DEFAULT_SECURITY_EXTENDED;

  return (
    <div className="space-y-6">
      <div className="grid gap-6 lg:grid-cols-2">
        <SettingsCard
          title="Authentication & Session Policies"
          description="Establish baseline password complexities, lockout limits, and idle timeouts."
          icon={<ShieldAlert className="h-5 w-5" />}
        >
          <div className="space-y-4">
            <SettingsField
              label="Minimum password length"
              description="Shortest password allowed for staff registration."
            >
              <input
                type="number"
                value={safeSettings.minPasswordLength || 8}
                onChange={(e) => setSettings({ ...safeSettings, minPasswordLength: parseInt(e.target.value) || 8 })}
                className={inputCls}
                min="8"
                max="32"
              />
            </SettingsField>

            <SettingsField
              label="Require password complexity"
              description="Forces passwords to contain upper/lowercase, numbers, and symbols."
            >
              <div className="flex items-center justify-between h-9 px-1">
                <span className="text-xs text-stone-500 font-medium">Strong complexity required</span>
                <Switch
                  checked={safeSettings.requireComplexity}
                  onCheckedChange={(checked) => setSettings({ ...safeSettings, requireComplexity: checked })}
                  className="data-[state=checked]:bg-brand-primary"
                />
              </div>
            </SettingsField>

            <SettingsField
              label="Failed login lockout attempts"
              description="Number of attempts before the account gets temporarily locked."
            >
              <input
                type="number"
                value={safeSettings.lockoutAttempts || 5}
                onChange={(e) => setSettings({ ...safeSettings, lockoutAttempts: parseInt(e.target.value) || 5 })}
                className={inputCls}
                min="3"
                max="10"
              />
            </SettingsField>

            <SettingsField
              label="Lockout duration (minutes)"
              description="Time locked accounts must wait before re-trying."
            >
              <input
                type="number"
                value={safeSettings.lockoutDurationMinutes || 15}
                onChange={(e) => setSettings({ ...safeSettings, lockoutDurationMinutes: parseInt(e.target.value) || 15 })}
                className={inputCls}
                min="5"
              />
            </SettingsField>
          </div>
        </SettingsCard>

        <SettingsCard
          title="Multi-Factor & Lock Session Timing"
          description="Force owners and managers to enroll in TOTP verification and set timing thresholds."
          icon={<ShieldCheck className="h-5 w-5" />}
        >
          <div className="space-y-4">
            <SettingsField
              label="Enforce Multi-Factor Authentication (MFA)"
              description="Force owners and managers to enroll in TOTP verification."
            >
              <div className="flex items-center justify-between h-9 px-1">
                <span className="text-xs text-stone-500 font-medium">MFA mandatory for admin roles</span>
                <Switch
                  checked={safeSettings.mfaRequired}
                  onCheckedChange={(checked) => setSettings({ ...safeSettings, mfaRequired: checked })}
                  className="data-[state=checked]:bg-brand-primary"
                />
              </div>
            </SettingsField>

            <SettingsField
              label="MFA Grace Period (days)"
              description="Days allowed for staff enrollment before account lockout."
            >
              <input
                type="number"
                value={safeSettings.mfaGracePeriodDays || 3}
                onChange={(e) => setSettings({ ...safeSettings, mfaGracePeriodDays: parseInt(e.target.value) || 3 })}
                className={inputCls}
                min="1"
                max="30"
              />
            </SettingsField>

            <SettingsField
              label="Maximum session duration (hours)"
              description="How long a logged-in user can remain active before being forced to log in again."
            >
              <input
                type="number"
                value={((safeSettings.sessionDurationMinutes || 120) / 60).toFixed(0)}
                onChange={(e) => setSettings({ ...safeSettings, sessionDurationMinutes: (parseInt(e.target.value) || 2) * 60 })}
                className={inputCls}
                min="1"
                max="24"
              />
            </SettingsField>

            <SettingsField
              label="Idle timeout warning (minutes)"
              description="Lock browser screen after inactivity."
            >
              <input
                type="number"
                value={safeSettings.idleTimeoutMinutes || 30}
                onChange={(e) => setSettings({ ...safeSettings, idleTimeoutMinutes: parseInt(e.target.value) || 15 })}
                className={inputCls}
                min="5"
              />
            </SettingsField>
          </div>
        </SettingsCard>
      </div>

      <SettingsCard
        title="IP Access Whitelisting & Active Sessions"
        description="Limit database requests to designated corporate offices or trigger remote cookie expirations."
        icon={<ShieldCheck className="h-5 w-5" />}
      >
        <div className="grid gap-6 md:grid-cols-2">
          <div className="space-y-4">
            <SettingsField
              label="Enable IP restrictions"
              description="Enforce validation checks matching browser requests against allowed static IPs."
            >
              <div className="flex items-center justify-between h-9 px-1">
                <span className="text-xs text-stone-500 font-medium">IP whitelist rules active</span>
                <Switch
                  checked={safeSettings.ipRestrictionEnabled}
                  onCheckedChange={(checked) => setSettings({ ...safeSettings, ipRestrictionEnabled: checked })}
                  className="data-[state=checked]:bg-brand-primary"
                />
              </div>
            </SettingsField>

            <SettingsField
              label="Whitelisted Corporate IPs"
              description="Comma-separated IP addresses allowed to connect to administrative modules."
            >
              <textarea
                value={safeSettings.allowedIps || ''}
                onChange={(e) => setSettings({ ...safeSettings, allowedIps: e.target.value })}
                className={`${inputCls} min-h-[72px] py-2 text-xs`}
                placeholder="e.g. 192.168.1.1, 74.125.19.147"
              />
            </SettingsField>
          </div>

          <div className="p-4 border border-stone-200 bg-stone-50/50 rounded-xl flex flex-col justify-between">
            <div>
              <span className="text-xs font-bold text-stone-800 block uppercase tracking-wider">Device Session Lifecycle</span>
              <p className="text-[11px] text-stone-400 mt-1 leading-relaxed">
                In case of lost hardware or corporate audit cycles, you can force logouts for every active session. This will require all personnel to re-authenticate.
              </p>
            </div>
            <button
              onClick={handleRevokeSessions}
              disabled={revokingSessions}
              className="mt-4 flex items-center justify-center gap-1.5 rounded-lg border border-red-200 bg-white px-4 py-2 text-xs font-semibold text-red-600 hover:bg-red-50 transition-colors disabled:opacity-50"
            >
              <ServerCrash className="h-4 w-4" /> Revoke all active sessions
            </button>
          </div>
        </div>
      </SettingsCard>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Activity, RefreshCw } from 'lucide-react';
import { toast } from '@vowos/design-system';
import { SettingsCard } from '../components/SettingsCard';
import { supabase } from '@/lib/supabase';
import { resolveEffectiveSetting } from '@/lib/settings';

interface SystemHealthSettingsTabProps {
  onDirtyChange: (dirty: boolean) => void;
  registerSaveRef: (saveFn: () => Promise<boolean>) => void;
  resetTrigger: number;
}

export function SystemHealthSettingsTab({
  onDirtyChange,
  registerSaveRef,
  resetTrigger,
}: SystemHealthSettingsTabProps) {
  const [checking, setChecking] = useState(false);
  const [dbStatus, setDbStatus] = useState<'Pending' | 'Healthy' | 'Error'>('Pending');
  const [stripeStatus, setStripeStatus] = useState<'Pending' | 'Healthy' | 'Error' | 'Disconnected'>('Pending');
  const [aiStatus, setAiStatus] = useState<'Pending' | 'Healthy' | 'Error' | 'Disconnected'>('Pending');

  useEffect(() => {
    // This tab doesn't have unsaved changes
    onDirtyChange(false);
    registerSaveRef(async () => true);
  }, []);

  const runDiagnostics = async () => {
    setChecking(true);
    setDbStatus('Pending');
    setStripeStatus('Pending');
    setAiStatus('Pending');
    
    try {
      // 1. Check DB Health
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Not authenticated");
      setDbStatus('Healthy');

      // 2. Check Integrations
      const { data: membership } = await supabase.from('business_memberships').select('business_id').eq('user_id', user.id).maybeSingle();
      if (membership) {
        const { data: integration } = await supabase.from('integrations')
          .select('status')
          .eq('business_id', membership.business_id)
          .eq('provider', 'stripe')
          .maybeSingle();
          
        setStripeStatus(integration?.status === 'connected' ? 'Healthy' : 'Disconnected');
      }

      // 3. Check AI Config
      const aiResult = await resolveEffectiveSetting<any>('integrations', 'ai_settings', { dataPlane: 'production' }, { enabled: false });
      setAiStatus(aiResult?.value?.enabled ? 'Healthy' : 'Disconnected');

      toast({
        title: 'Diagnostics check complete',
        description: 'All system services have been polled.',
      });
    } catch (e: any) {
      setDbStatus('Error');
      toast({
        title: 'Diagnostics check failed',
        description: e.message || 'Could not connect to database.',
        variant: 'destructive',
      });
    } finally {
      setChecking(false);
    }
  };

  const services = [
    { name: 'Supabase Database', desc: 'Queries, auth tokens, row level security policies.', status: dbStatus },
    { name: 'Stripe Adapter', desc: 'Secure connection check and webhook delivery loops.', status: stripeStatus },
    { name: 'AI Copilot Provider', desc: 'AI routing gateway and model verification.', status: aiStatus },
  ];

  return (
    <div className="space-y-6">
      <SettingsCard
        title="Owner System Administrations"
        description="Verify backend databases and integration endpoints health. Download diagnostics files."
        icon={<Activity className="h-5 w-5" />}
      >
        <div className="space-y-4">
          <div className="flex justify-between items-center pb-4 border-b border-stone-100">
            <div>
              <span className="text-xs text-stone-400 font-bold uppercase tracking-wider">Commit SHA:</span>
              <span className="text-xs text-stone-600 font-semibold ml-2">d7fce0f (main)</span>
            </div>
            <button
              onClick={runDiagnostics}
              disabled={checking}
              className="flex items-center gap-1.5 rounded-lg border border-stone-200 bg-white px-3 py-1.5 text-xs font-semibold text-stone-700 hover:bg-stone-50 transition-colors disabled:opacity-50"
            >
              <RefreshCw className={`h-3.5 w-3.5 ${checking ? 'animate-spin' : ''}`} />
              Run Health Check
            </button>
          </div>

          <div className="divide-y divide-stone-100 rounded-xl border border-stone-200 overflow-hidden bg-white">
            {services.map((svc) => (
              <div key={svc.name} className="flex justify-between items-center p-4">
                <div>
                  <h6 className="text-xs font-bold text-stone-800 uppercase tracking-wider">{svc.name}</h6>
                  <p className="text-[11px] text-stone-400 mt-0.5">{svc.desc}</p>
                </div>
                <span className={`rounded-full px-2.5 py-0.5 text-xs font-semibold ${
                  svc.status === 'Healthy' ? 'bg-status-success/10 text-status-success' :
                  svc.status === 'Error' ? 'bg-red-50 text-red-600' :
                  'bg-stone-100 text-stone-500'
                }`}>
                  {svc.status}
                </span>
              </div>
            ))}
          </div>
        </div>
      </SettingsCard>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { ArrowLeftRight, Loader2, CheckCircle2, ShieldCheck, AlertTriangle } from 'lucide-react';
import { toast } from '@vowos/design-system';
import { inputCls } from '@/components/vowos/ui';
import { SettingsCard } from '../components/SettingsCard';
import { SettingsField } from '../components/SettingsField';
import { Switch } from '@vowos/design-system';
import { resolveEffectiveSetting, saveScopedSetting, DEFAULT_TRANSFER_SETTINGS, TransferSettings } from '@/lib/settings';
import { getActiveDataPlane } from '@/lib/supabase';

interface TransferPermissions {
  locationId: string;
  name: string;
  canSend: boolean;
  canReceive: boolean;
}

const DEFAULT_TRANSFER_PERMS: TransferPermissions[] = [
  { locationId: 'ido-br', name: 'I Do Bridal Couture (Baton Rouge)', canSend: true, canReceive: true },
  { locationId: 'ido-cov', name: 'I Do Bridal Couture (Covington)', canSend: true, canReceive: true },
  { locationId: 'pc-br', name: 'Proper & Company (Baton Rouge)', canSend: true, canReceive: false },
  { locationId: 'pc-cov', name: 'Proper & Company (Covington)', canSend: false, canReceive: true },
];

interface TransfersSettingsTabProps {
  onDirtyChange: (dirty: boolean) => void;
  registerSaveRef: (saveFn: () => Promise<boolean>) => void;
  resetTrigger: number;
}

export function TransfersSettingsTab({
  onDirtyChange,
  registerSaveRef,
  resetTrigger,
}: TransfersSettingsTabProps) {
  const [loading, setLoading] = useState(true);
  const [settings, setSettings] = useState<TransferSettings>(DEFAULT_TRANSFER_SETTINGS);
  const [dbSettings, setDbSettings] = useState<TransferSettings>(DEFAULT_TRANSFER_SETTINGS);
  const [permissions, setPermissions] = useState<TransferPermissions[]>(DEFAULT_TRANSFER_PERMS);
  const [dbPermissions, setDbPermissions] = useState<TransferPermissions[]>(DEFAULT_TRANSFER_PERMS);

  const loadSettings = async () => {
    setLoading(true);
    const dataPlane = getActiveDataPlane();
    const settingsResult = await resolveEffectiveSetting<TransferSettings>(
      'transfer_settings',
      'transfer_settings',
      { dataPlane },
      DEFAULT_TRANSFER_SETTINGS
    );
    const permsResult = await resolveEffectiveSetting<TransferPermissions[]>(
      'transfer_permissions',
      'transfer_permissions',
      { dataPlane },
      DEFAULT_TRANSFER_PERMS
    );
    setSettings(settingsResult.value);
    setDbSettings(settingsResult.value);
    setPermissions(permsResult.value);
    setDbPermissions(permsResult.value);
    setLoading(false);
  };

  useEffect(() => {
    loadSettings();
  }, [resetTrigger]);

  const isDirty =
    JSON.stringify(settings) !== JSON.stringify(dbSettings) ||
    JSON.stringify(permissions) !== JSON.stringify(dbPermissions);

  useEffect(() => {
    onDirtyChange(isDirty);
  }, [isDirty]);

  const handleSave = async (reason?: string): Promise<boolean> => {
    try {
      const dataPlane = getActiveDataPlane();
      await saveScopedSetting('transfer_settings', 'transfer_settings', settings, { dataPlane }, reason);
      await saveScopedSetting('transfer_permissions', 'transfer_permissions', permissions, { dataPlane }, reason);
      
      toast({
        title: 'Transfer settings saved',
        description: 'Inter-location transfer policies updated successfully.',
      });
      setDbSettings(settings);
      setDbPermissions(permissions);
      return true;
    } catch (err: any) {
      toast({
        title: 'Could not save transfer settings',
        description: err.message,
        variant: 'destructive',
      });
      return false;
    }
  };

  useEffect(() => {
    registerSaveRef(handleSave);
  }, [settings, permissions]);

  const handlePermChange = (locationId: string, type: 'canSend' | 'canReceive', value: boolean) => {
    setPermissions(
      permissions.map((p) => (p.locationId === locationId ? { ...p, [type]: value } : p))
    );
  };

  if (loading) {
    return (
      <div className="flex items-center gap-2 py-10 text-sm text-stone-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading transfer protocolsΓÇª
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid gap-6 lg:grid-cols-2">
        <SettingsCard
          title="Transfer Routing Controls"
          description="Establish authorization rules, safety margins, and receipt check protocols."
          icon={<ArrowLeftRight className="h-5 w-5" />}
        >
          <div className="space-y-4">
            <SettingsField
              label="Enable store transfers"
              description="Allow boutique logistics team to request inter-location sample transfers."
            >
              <div className="flex items-center justify-between h-9 px-1">
                <span className="text-xs text-stone-500 font-medium">Transfers active</span>
                <Switch
                  checked={settings.enabled}
                  onCheckedChange={(checked) => setSettings({ ...settings, enabled: checked })}
                  className="data-[state=checked]:bg-brand-primary"
                />
              </div>
            </SettingsField>

            <SettingsField
              label="Manager approval required"
              description="Transfers require explicit manager authorization before packing."
            >
              <div className="flex items-center justify-between h-9 px-1">
                <span className="text-xs text-stone-500 font-medium">Enforce approval gates</span>
                <Switch
                  checked={settings.approvalRequired}
                  onCheckedChange={(checked) => setSettings({ ...settings, approvalRequired: checked })}
                  className="data-[state=checked]:bg-brand-primary"
                />
              </div>
            </SettingsField>

            <SettingsField
              label="Manager approval threshold ($)"
              description="Transactions with value exceeding this rate require owner override."
            >
              <input
                type="number"
                value={(settings.approvalThresholdCents / 100).toFixed(2)}
                onChange={(e) => setSettings({ ...settings, approvalThresholdCents: Math.round(parseFloat(e.target.value) * 100) || 0 })}
                className={inputCls}
                min="0"
                step="0.01"
              />
            </SettingsField>

            <SettingsField
              label="Minimum source safety stock (units)"
              description="Block shipping items if source stock drops below this count."
            >
              <input
                type="number"
                value={settings.minSourceStock}
                onChange={(e) => setSettings({ ...settings, minSourceStock: parseInt(e.target.value) || 0 })}
                className={inputCls}
                min="0"
              />
            </SettingsField>
          </div>
        </SettingsCard>

        <SettingsCard
          title="Fulfillment Logistics & Limits"
          description="Establish expected transit time boundaries and strict intake check rules."
          icon={<ArrowLeftRight className="h-5 w-5" />}
        >
          <div className="space-y-4">
            <SettingsField
              label="Default expected transit duration (days)"
              description="Flags transfer requests as overdue after this window."
            >
              <input
                type="number"
                value={settings.transitDaysDefault}
                onChange={(e) => setSettings({ ...settings, transitDaysDefault: parseInt(e.target.value) || 1 })}
                className={inputCls}
                min="1"
              />
            </SettingsField>

            <SettingsField
              label="Enforce package tracking numbers"
              description="Require package tracking information before flagging item as shipped."
            >
              <div className="flex items-center justify-between h-9 px-1">
                <span className="text-xs text-stone-500 font-medium">Tracking number mandatory</span>
                <Switch
                  checked={settings.trackingRequired}
                  onCheckedChange={(checked) => setSettings({ ...settings, trackingRequired: checked })}
                  className="data-[state=checked]:bg-brand-primary"
                />
              </div>
            </SettingsField>

            <SettingsField
              label="Enforce barcode scan on intake"
              description="Require clerk to verify barcode tag scan to mark item as received."
            >
              <div className="flex items-center justify-between h-9 px-1">
                <span className="text-xs text-stone-500 font-medium">Strict scanning checks active</span>
                <Switch
                  checked={settings.scanRequired}
                  onCheckedChange={(checked) => setSettings({ ...settings, scanRequired: checked })}
                  className="data-[state=checked]:bg-brand-primary"
                />
              </div>
            </SettingsField>
          </div>
        </SettingsCard>
      </div>

      <SettingsCard
        title="Location Dispatch Permissions"
        description="Filter which store locations are permitted to ship out or receive transfer shipments."
        icon={<ArrowLeftRight className="h-5 w-5" />}
      >
        <div className="rounded-xl border border-stone-200 bg-white overflow-hidden">
          <table className="w-full text-left border-collapse text-xs">
            <thead>
              <tr className="bg-stone-50 border-b border-stone-200 text-stone-500 font-bold uppercase tracking-wider">
                <th className="p-3">Location Boutique</th>
                <th className="p-3 text-center">Allow Outbound Shipping (Send)</th>
                <th className="p-3 text-center">Allow Inbound Intake (Receive)</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-stone-100">
              {permissions.map((p) => (
                <tr key={p.locationId} className="hover:bg-stone-50/50">
                  <td className="p-3 font-semibold text-stone-800">{p.name}</td>
                  <td className="p-3 text-center">
                    <Switch
                      checked={p.canSend}
                      onCheckedChange={(checked) => handlePermChange(p.locationId, 'canSend', checked)}
                      className="scale-90 data-[state=checked]:bg-brand-primary inline-block"
                    />
                  </td>
                  <td className="p-3 text-center">
                    <Switch
                      checked={p.canReceive}
                      onCheckedChange={(checked) => handlePermChange(p.locationId, 'canReceive', checked)}
                      className="scale-90 data-[state=checked]:bg-brand-primary inline-block"
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </SettingsCard>
    </div>
  );
}

