    { csvHeader: '', mappedField: 'retail_cents' },
  ]);

  const [importing, setImporting] = useState(false);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    catalogService.getVendors('b0000000-0000-0000-0000-000000000001').then(setVendors).catch(console.error);
  }, []);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;
    const uploadedFile = e.target.files[0];
    setFile(uploadedFile);
    setParsing(true);
    try {
      const data = await importEngine.parseCSV(uploadedFile);
      setRawData(data);
      if (data.length > 0) {
        setHeaders(Object.keys(data[0]));
      }
    } catch (err) {
      console.error(err);
      toast.error("Failed to parse CSV");
    } finally {
      setParsing(false);
    }
  };

  const handleMappingChange = (field: string, header: string) => {
    setMappings(prev => prev.map(m => m.mappedField === field ? { ...m, csvHeader: header } : m));
  };

  const handleImport = async () => {
    if (!selectedVendor || !file) return;
    
    // Check if style_number is mapped
    const styleMapping = mappings.find(m => m.mappedField === 'style_number');
    if (!styleMapping || !styleMapping.csvHeader) {
      toast.error("Style Number mapping is required.");
      return;
    }

    setImporting(true);
    try {
      const job = await importEngine.startImportJob('b0000000-0000-0000-0000-000000000001', selectedVendor, file.name);
      await importEngine.commitImport('b0000000-0000-0000-0000-000000000001', selectedVendor, job.id, rawData, mappings);
      setSuccess(true);
    } catch (err) {
      console.error(err);
      toast.error("Import failed. See console.");
    } finally {
      setImporting(false);
    }
  };

  if (success) {
    return (
      <div className="max-w-2xl mx-auto mt-12 text-center p-12 bg-white rounded-xl border border-border-default shadow-sm">
        <div className="w-16 h-16 bg-green-100 text-status-success rounded-full flex items-center justify-center mx-auto mb-6">
          <CheckCircle className="w-8 h-8" />
        </div>
        <h2 className="text-2xl font-serif font-light text-text-primary mb-2">Import Successful</h2>
        <p className="text-text-muted mb-8">
          The catalog data has been successfully mapped and imported into your vendor database.
        </p>
        <button
          onClick={() => { setSuccess(false); setFile(null); setRawData([]); }}
          className="px-6 py-2 bg-surface-dark text-white text-sm rounded hover:bg-surface-dark transition-colors"
        >
          Import Another File
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto p-6 space-y-6">
      <div>
        <h1 className="text-3xl font-serif font-light text-text-primary mb-1">Catalog Import Center</h1>
        <p className="text-text-muted">Upload vendor catalogs via CSV or Excel to automatically create products and variants.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="col-span-1 p-6 space-y-6 rounded-2xl border border-stone-200 bg-white shadow-sm">
          <div>
            <label className="block text-sm font-medium text-text-primary mb-2">Select Vendor</label>
            <select
              value={selectedVendor}
              onChange={(e) => setSelectedVendor(e.target.value)}
              className="w-full border-border-strong rounded-md shadow-sm focus:border-brand-primary focus:ring-focus-ring sm:text-sm"
            >
              <option value="">-- Choose Vendor --</option>
              {vendors.map(v => (
                <option key={v.id} value={v.id}>{v.name}</option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-text-primary mb-2">Upload File</label>
            <div className="mt-1 flex justify-center px-6 pt-5 pb-6 border-2 border-border-strong border-dashed rounded-md relative hover:border-brand-primary transition-colors">
              <div className="space-y-1 text-center">
                <Upload className="mx-auto h-12 w-12 text-text-muted" />
                <div className="flex text-sm text-text-secondary">
                  <label className="relative cursor-pointer bg-white rounded-md font-medium text-brand-primary hover:text-brand-primary">
                    <span>Upload a file</span>
                    <input type="file" accept=".csv" className="sr-only" onChange={handleFileUpload} />
                  </label>
                  <p className="pl-1">or drag and drop</p>
                </div>
                <p className="text-xs text-text-muted">CSV up to 10MB</p>
              </div>
            </div>
          </div>
          
          {file && (
            <div className="bg-surface-canvas p-4 rounded-lg flex items-center gap-3">
              <FileText className="w-5 h-5 text-text-muted" />
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-text-primary truncate">{file.name}</p>
                <p className="text-xs text-text-muted">{rawData.length} rows found</p>
              </div>
            </div>
          )}
        </div>

        <div className="col-span-2 p-6 rounded-2xl border border-stone-200 bg-white shadow-sm">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-lg font-medium text-text-primary">Field Mapping</h2>
            <div className="flex items-center gap-2 text-sm text-text-muted">
              <Settings className="w-4 h-4" />
              <span>Map columns to VowOS properties</span>
            </div>
          </div>

          {rawData.length === 0 ? (
            <div className="text-center py-12 text-text-muted">
              <AlertTriangle className="w-8 h-8 text-slate-300 mx-auto mb-3" />
              <p>Upload a file to begin mapping fields.</p>
            </div>
          ) : (
            <div className="space-y-6">
              <div className="grid grid-cols-12 gap-4 pb-2 border-b border-gray-100 text-xs font-medium text-text-muted uppercase tracking-wider">
                <div className="col-span-5">VowOS Property</div>
                <div className="col-span-2 text-center"></div>
                <div className="col-span-5">CSV Column</div>
              </div>

              {mappings.map((mapping) => (
                <div key={mapping.mappedField} className="grid grid-cols-12 gap-4 items-center">
                  <div className="col-span-5">
                    <span className="text-sm font-medium text-text-primary capitalize">
                      {mapping.mappedField.replace('_', ' ')}
                    </span>
                    {mapping.mappedField === 'style_number' && <span className="text-red-500 ml-1">*</span>}
                  </div>
                  <div className="col-span-2 flex justify-center text-slate-300">
                    <ArrowRight className="w-4 h-4" />
                  </div>
                  <div className="col-span-5">
                    <select
                      value={mapping.csvHeader}
                      onChange={(e) => handleMappingChange(mapping.mappedField, e.target.value)}
                      className="w-full border-border-strong rounded-md shadow-sm focus:border-brand-primary focus:ring-focus-ring sm:text-sm"
                    >
                      <option value="">-- Ignore --</option>
                      {headers.map(h => (
                        <option key={h} value={h}>{h}</option>
                      ))}
                    </select>
                  </div>
                </div>
              ))}

              <div className="pt-6 border-t border-gray-100 flex justify-end">
                <button
                  onClick={handleImport}
                  disabled={importing || !selectedVendor}
                  className="px-6 py-2 bg-surface-dark text-white text-sm rounded hover:bg-surface-dark transition-colors disabled:opacity-50 flex items-center gap-2"
                >
                  {importing ? 'Importing...' : 'Run Import'}
                  {!importing && <ArrowRight className="w-4 h-4" />}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Printer, CheckCircle2, RefreshCw, Barcode, Sliders, ShieldCheck } from 'lucide-react';
import { Modal } from '@/components/vowos/ui';

interface ThermalBarcodePrinterProps {
  isOpen: boolean;
  onClose: () => void;
  product?: {
    name: string;
    brand: string;
    styleNumber: string;
    size: string;
    color: string;
    priceCents: number;
    barcode: string;
  };
}

export default function ThermalBarcodePrinter({ isOpen, onClose, product }: ThermalBarcodePrinterProps) {
  const [printerType, setPrinterType] = useState<'zebra' | 'dymo' | 'brother' | 'web_serial'>('web_serial');
  const [copies, setCopies] = useState(1);
  const [labelSize, setLabelSize] = useState<'2x1' | '2.25x1.25' | 'swing_tag'>('2x1');
  const [printing, setPrinting] = useState(false);
  const [success, setSuccess] = useState(false);

  const defaultItem = product || {
    name: 'Ines Di Santo Couture Silk Gown',
    brand: 'I Do Bridal Couture',
    styleNumber: 'IDS-2026-FALL',
    size: '10',
    color: 'Ivory / Lace',
    priceCents: 450000, // $4,500.00
    barcode: '881029384912',
  };

  const handlePrint = async () => {
    setPrinting(true);
    setSuccess(false);

    // Simulate Web Serial / ESC-POS / ZPL thermal printing
    setTimeout(() => {
      setPrinting(false);
      setSuccess(true);
      setTimeout(() => setSuccess(false), 4000);
    }, 1000);
  };

  if (!isOpen) return null;

  return (
    <Modal open={isOpen} onClose={onClose} title="Direct Thermal Barcode Swing-Tag Printer" maxWidth="max-w-2xl">
      <div className="space-y-6">
        
        {/* Label Preview Card */}
        <div className="rounded-2xl border-2 border-stone-900 bg-white p-5 shadow-md flex flex-col items-center justify-center text-center space-y-2 relative overflow-hidden">
          <span className="text-[9px] font-bold uppercase tracking-widest text-stone-400 border border-stone-200 px-2 py-0.5 rounded">
            {defaultItem.brand} ┬╖ {labelSize.toUpperCase()} Thermal Tag
          </span>

          <h3 className="font-bold text-sm text-stone-900 leading-tight">{defaultItem.name}</h3>
          
          <div className="flex items-center gap-3 text-xs font-semibold text-stone-700">
            <span>Style: {defaultItem.styleNumber}</span>
            <span>┬╖</span>
            <span>Size: {defaultItem.size}</span>
            <span>┬╖</span>
            <span>{defaultItem.color}</span>
          </div>

          <div className="py-2 flex flex-col items-center">
            <Barcode className="h-12 w-48 text-stone-900" />
            <span className="font-mono text-xs font-bold text-stone-800 tracking-widest">{defaultItem.barcode}</span>
          </div>

          <p className="font-serif text-lg font-bold text-stone-900">${(defaultItem.priceCents / 100).toLocaleString()}.00</p>
        </div>

        {/* Configuration Controls */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div>
            <label className="text-xs font-bold text-stone-700 block mb-1">Thermal Printer Type</label>
            <select
              value={printerType}
              onChange={(e: any) => setPrinterType(e.target.value)}
              className="w-full rounded-xl border border-stone-200 bg-white px-3 py-2 text-xs font-semibold text-stone-900"
            >
              <option value="web_serial">Web Serial (Auto-Detect USB)</option>
              <option value="zebra">Zebra ZPL Thermal Printer</option>
              <option value="dymo">Dymo LabelWriter 450/550</option>
              <option value="brother">Brother QL Series</option>
            </select>
          </div>

          <div>
            <label className="text-xs font-bold text-stone-700 block mb-1">Tag Size</label>
            <select
              value={labelSize}
              onChange={(e: any) => setLabelSize(e.target.value)}
              className="w-full rounded-xl border border-stone-200 bg-white px-3 py-2 text-xs font-semibold text-stone-900"
            >
              <option value="2x1">2" x 1" Standard Barcode Tag</option>
              <option value="2.25x1.25">2.25" x 1.25" Bridal Tag</option>
              <option value="swing_tag">Bridal Boutique Swing Tag</option>
            </select>
          </div>

          <div>
            <label className="text-xs font-bold text-stone-700 block mb-1">Copies</label>
            <input
              type="number"
              min="1"
              max="100"
              value={copies}
              onChange={(e) => setCopies(parseInt(e.target.value || '1', 10))}
              className="w-full rounded-xl border border-stone-200 bg-white px-3 py-2 text-xs font-semibold text-stone-900"
            />
          </div>
        </div>

        {/* Action Button */}
        <button
          onClick={handlePrint}
          disabled={printing}
          className="w-full rounded-xl bg-stone-900 px-4 py-3 text-xs font-bold text-white shadow-lg hover:bg-stone-800 transition-colors flex items-center justify-center gap-2"
        >
          {printing ? (
            <>
              <RefreshCw className="h-4 w-4 animate-spin" /> Sending Thermal ESC-POS Command...
            </>
          ) : (
            <>
              <Printer className="h-4 w-4" /> Print {copies} Thermal Barcode Tag{copies > 1 ? 's' : ''}
            </>
          )}
        </button>

        {success && (
          <div className="rounded-xl bg-status-success/10 border border-emerald-200 p-3 text-xs font-bold text-emerald-800 text-center flex items-center justify-center gap-2">
            <CheckCircle2 className="h-4 w-4 text-status-success" />
            <span>Thermal barcode swing-tags sent to USB printer successfully!</span>
          </div>
        )}

      </div>
    </Modal>
  );
}

