    predictedSalesCents: Math.round((65 + Math.round(spendDelta / 8000)) * 0.36 * 195000),
    predictedGrossProfitCents: Math.round((65 + Math.round(spendDelta / 8000)) * 0.36 * 195000 * 0.60 - (500000 + spendDelta)),
