import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription, CardFooter } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { ArrowLeft, ArrowRight, UploadCloud, CheckCircle2, AlertTriangle, FileSpreadsheet, Loader2 } from 'lucide-react';
import { parseRawText, validateCustomerRow } from '@/lib/migration/importParsers';
import { toast } from 'sonner';

interface WizardProps {
  entityType: string;
  onCancel: () => void;
  onComplete: () => void;
}

type Step = 'UPLOAD' | 'MAP' | 'VALIDATE' | 'DRY_RUN' | 'COMMIT';

export default function ImportWorkflowWizard({ entityType, onCancel, onComplete }: WizardProps) {
  const [step, setStep] = useState<Step>('UPLOAD');
  const [isProcessing, setIsProcessing] = useState(false);
  const [rawRows, setRawRows] = useState<any[]>([]);

  const handleSimulateUpload = () => {
    setIsProcessing(true);
    setTimeout(() => {
      // Mock parsing a 50-row CSV
      const mockCsv = "firstName,lastName,email\n" + Array.from({length: 50}, (_, i) => `Jane${i},Doe${i},jane${i}@example.com`).join("\n");
      setRawRows(parseRawText(mockCsv));
      setIsProcessing(false);
      setStep('MAP');
    }, 1000);
  };

  const handleSimulateValidation = () => {
    setIsProcessing(true);
    setTimeout(() => {
      setIsProcessing(false);
      setStep('VALIDATE');
    }, 800);
  };

  const handleSimulateDryRun = () => {
    setIsProcessing(true);
    setTimeout(() => {
      setIsProcessing(false);
      setStep('DRY_RUN');
    }, 1200);
  };

  const handleSimulateCommit = () => {
    setIsProcessing(true);
    setTimeout(() => {
      setIsProcessing(false);
      toast.success(`Successfully imported ${rawRows.length} ${entityType}`);
      onComplete();
    }, 1500);
  };

  return (
    <div className="space-y-6 max-w-3xl animate-in slide-in-from-right-4 duration-300">
      <div className="flex items-center gap-4">
        <Button variant="ghost" onClick={onCancel} className="text-stone-500">
          <ArrowLeft className="w-4 h-4 mr-2" /> Back
        </Button>
        <div>
          <h2 className="text-xl font-serif text-stone-800 capitalize">Import {entityType}</h2>
          <p className="text-sm text-stone-500">Step {['UPLOAD', 'MAP', 'VALIDATE', 'DRY_RUN', 'COMMIT'].indexOf(step) + 1} of 5</p>
        </div>
      </div>

      <Card className="shadow-xs border-stone-200/60">
        <CardHeader>
          <CardTitle>
            {step === 'UPLOAD' && 'Upload Data File'}
            {step === 'MAP' && 'Map Fields'}
            {step === 'VALIDATE' && 'Validation Results'}
            {step === 'DRY_RUN' && 'Dry Run Confirmation'}
          </CardTitle>
          <CardDescription>
            {step === 'UPLOAD' && 'Select a CSV or XLSX file containing your historical data.'}
            {step === 'MAP' && `We found ${rawRows.length} rows. Map your columns to VowOS properties.`}
            {step === 'VALIDATE' && 'Review errors and warnings before proceeding.'}
            {step === 'DRY_RUN' && 'The data is staged and ready to be inserted into the live database.'}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {step === 'UPLOAD' && (
            <div className="border-2 border-dashed border-stone-200 rounded-lg p-12 text-center hover:bg-stone-50 transition-colors cursor-pointer" onClick={handleSimulateUpload}>
              {isProcessing ? (
                <div className="flex flex-col items-center">
                  <Loader2 className="w-8 h-8 text-brand-primary animate-spin mb-4" />
                  <p className="text-sm font-medium text-stone-600">Parsing file...</p>
                </div>
              ) : (
                <div className="flex flex-col items-center">
                  <FileSpreadsheet className="w-10 h-10 text-stone-300 mb-4" />
                  <p className="text-sm font-medium text-stone-800 mb-1">Click to browse or drag file here</p>
                  <p className="text-xs text-stone-500">Supports .csv, .xlsx up to 5MB</p>
                </div>
              )}
            </div>
          )}

          {step === 'MAP' && (
             <div className="space-y-4">
                <div className="grid grid-cols-3 gap-4 border-b border-stone-100 pb-2 text-sm font-medium text-stone-500">
                  <div>Source Column (CSV)</div>
                  <div>Sample Data</div>
                  <div>VowOS Field</div>
                </div>
                {['firstName', 'lastName', 'email'].map((col, idx) => (
                  <div key={idx} className="grid grid-cols-3 gap-4 items-center">
                    <div className="text-sm font-mono bg-stone-100 px-2 py-1 rounded w-fit">{col}</div>
                    <div className="text-sm text-stone-500 truncate">{rawRows[0][col]}</div>
                    <div>
                      <select className="flex h-9 w-full items-center justify-between rounded-md border border-input bg-transparent px-3 py-2 text-sm shadow-sm ring-offset-background placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-ring disabled:cursor-not-allowed disabled:opacity-50">
                        <option value={col}>{col}</option>
                      </select>
                    </div>
                  </div>
                ))}
             </div>
          )}

          {step === 'VALIDATE' && (
            <div className="space-y-6">
              <div className="flex gap-4">
                <div className="flex-1 bg-emerald-50 border border-emerald-200 p-4 rounded-lg flex flex-col items-center justify-center text-emerald-800">
                  <CheckCircle2 className="w-6 h-6 mb-2" />
                  <span className="text-2xl font-bold">{rawRows.length}</span>
                  <span className="text-xs font-medium uppercase tracking-wider">Valid Rows</span>
                </div>
                <div className="flex-1 bg-amber-50 border border-amber-200 p-4 rounded-lg flex flex-col items-center justify-center text-amber-800">
                  <AlertTriangle className="w-6 h-6 mb-2" />
                  <span className="text-2xl font-bold">0</span>
                  <span className="text-xs font-medium uppercase tracking-wider">Warnings</span>
                </div>
              </div>
              <p className="text-sm text-stone-600 text-center">All rows passed strict validation rules. No duplicates found in the live database.</p>
            </div>
          )}

          {step === 'DRY_RUN' && (
            <div className="bg-stone-50 border border-stone-200 rounded-lg p-6 text-center">
              <UploadCloud className="w-12 h-12 text-brand-primary mx-auto mb-4" />
              <h3 className="text-lg font-serif text-stone-800 mb-2">Ready for Import</h3>
              <p className="text-sm text-stone-500 max-w-md mx-auto">
                You are about to insert <strong>{rawRows.length}</strong> {entityType} into your live database. 
                This action is logged and can be rolled back by VowOS Support if a critical error occurs.
              </p>
            </div>
          )}
        </CardContent>
        <CardFooter className="flex justify-end gap-3 border-t border-stone-100 bg-stone-50/50 pt-4">
          {step !== 'UPLOAD' && (
            <Button variant="outline" onClick={onCancel}>Cancel</Button>
          )}
          {step === 'MAP' && (
            <Button onClick={handleSimulateValidation} disabled={isProcessing} className="bg-stone-900 text-white">
              {isProcessing ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : null}
              Run Validation
            </Button>
          )}
          {step === 'VALIDATE' && (
            <Button onClick={handleSimulateDryRun} disabled={isProcessing} className="bg-stone-900 text-white">
              {isProcessing ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : null}
              Proceed to Dry Run
            </Button>
          )}
          {step === 'DRY_RUN' && (
            <Button onClick={handleSimulateCommit} disabled={isProcessing} className="bg-brand-primary text-white hover:bg-brand-primary/90">
              {isProcessing ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : null}
              Commit Import
            </Button>
          )}
        </CardFooter>
      </Card>
    </div>
  );
}

import { useState } from 'react';
import { CommerceSyncIssue } from '../types/properCommerceTypes';
import { retrySyncIssue } from '../api/properCommerceApi';
import { AlertTriangle, RefreshCw, CheckCircle2, Clock, Trash2 } from 'lucide-react';
import { toast } from '@vowos/design-system';

interface CommerceSyncDiagnosticsViewProps {
  issues: CommerceSyncIssue[];
  onRefresh: () => void;
}

export default function CommerceSyncDiagnosticsView({ issues, onRefresh }: CommerceSyncDiagnosticsViewProps) {
  const [retrying, setRetrying] = useState<string | null>(null);

  const handleRetry = async (id: string) => {
    setRetrying(id);
    try {
      await retrySyncIssue(id);
      toast({ title: 'Sync Retried', description: 'The issue has been resolved and sync is retrying.' });
      onRefresh();
    } catch (e: any) {
      toast({ title: 'Retry Failed', description: e.message || 'Failed to retry sync.', variant: 'destructive' });
    } finally {
      setRetrying(null);
    }
  };

  const handleDismiss = async (id: string) => {
    if (confirm('Are you sure you want to dismiss this sync issue? This may leave the entity out of sync.')) {
      setRetrying(id);
      await retrySyncIssue(id); // Using the same API stub to delete it from in-memory array
      toast({ title: 'Issue Dismissed', description: 'The sync issue was removed from the queue.' });
      onRefresh();
      setRetrying(null);
    }
  };

  if (issues.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-center select-none">
        <div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-emerald-100 text-status-success mb-4 shadow-sm">
          <CheckCircle2 className="h-8 w-8" />
        </div>
        <h3 className="text-lg font-bold text-stone-900">All Systems Synced</h3>
        <p className="text-sm text-stone-500 max-w-md mt-2">
          Your catalogs, inventory, and orders are fully reconciled across all connected channels. There are no pending sync issues.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-6 select-none max-w-5xl mx-auto">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-bold text-stone-900">Sync Diagnostics</h2>
          <p className="text-xs text-stone-500">Review and resolve synchronization errors across your channels.</p>
        </div>
        <button
          onClick={onRefresh}
          className="inline-flex items-center gap-2 rounded-xl border border-stone-200 bg-white px-4 py-2 text-xs font-bold text-stone-700 shadow-sm hover:bg-stone-50"
        >
          <RefreshCw className="h-3.5 w-3.5" /> Refresh Queue
        </button>
      </div>

      <div className="space-y-4">
        {issues.map((issue) => (
          <div key={issue.id} className="rounded-2xl border border-rose-200 bg-rose-50/50 p-5 shadow-sm">
            <div className="flex flex-col md:flex-row md:items-start md:justify-between gap-4">
              <div className="flex items-start gap-4">
                <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-rose-100 text-rose-600">
                  <AlertTriangle className="h-5 w-5" />
                </div>
                <div className="space-y-1">
                  <div className="flex items-center gap-2">
                    <span className="rounded bg-rose-200 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider text-rose-800">
                      {issue.entityType}
                    </span>
                    <h3 className="font-bold text-stone-900 text-sm">{issue.entityName}</h3>
                  </div>
                  <p className="text-xs text-rose-800 font-medium">
                    {issue.errorMessage}
                  </p>
                  <div className="flex items-center gap-4 text-[11px] text-stone-500 pt-2">
                    <span className="flex items-center gap-1"><Clock className="h-3.5 w-3.5" /> Occurred: {new Date(issue.occurredAt).toLocaleString()}</span>
                    <span>Attempts: <strong>{issue.attempts}</strong></span>
                    <span className="font-mono bg-stone-100 px-1.5 py-0.5 rounded text-[10px]">ID: {issue.entityId}</span>
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-2 shrink-0 pt-2 md:pt-0">
                <button
                  onClick={() => handleDismiss(issue.id)}
                  disabled={retrying === issue.id}
                  className="inline-flex items-center gap-1.5 rounded-xl border border-stone-200 bg-white px-3 py-2 text-xs font-bold text-stone-600 hover:bg-stone-50 hover:text-rose-600 transition-colors"
                >
                  <Trash2 className="h-3.5 w-3.5" /> Dismiss
                </button>
                <button
                  onClick={() => handleRetry(issue.id)}
                  disabled={retrying === issue.id}
                  className="inline-flex items-center gap-1.5 rounded-xl bg-stone-900 px-4 py-2 text-xs font-bold text-white shadow-md hover:bg-stone-800 transition-colors disabled:opacity-50"
                >
                  {retrying === issue.id ? <RefreshCw className="h-3.5 w-3.5 animate-spin" /> : <RefreshCw className="h-3.5 w-3.5" />}
                  Retry Sync
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { CommerceConnection } from '../types/properCommerceTypes';
import { connectGoDaddy, disconnectGoDaddy } from '../api/properCommerceApi';
import { Modal } from '@/components/vowos/ui';
import { ShoppingBag, ShieldCheck, CheckCircle2, RefreshCw, Lock, Link2, Globe } from 'lucide-react';
import { toast } from '@vowos/design-system';

interface GoDaddyConnectModalProps {
  open: boolean;
  onClose: () => void;
  connection: CommerceConnection | undefined;
  onUpdate: () => void;
}

export default function GoDaddyConnectModal({ open, onClose, connection, onUpdate }: GoDaddyConnectModalProps) {
  const [shopDomain, setShopDomain] = useState(connection?.shopDomain || 'properandcompany.godaddysites.com');
  const [loading, setLoading] = useState(false);

  const handleConnect = async () => {
    if (!shopDomain.trim()) {
      toast({ title: 'Enter shop domain', description: 'Please enter your GoDaddy store domain.', variant: 'destructive' });
      return;
    }

    setLoading(true);
    try {
      // Direct the user to the real backend OAuth initiation endpoint
      window.location.href = `http://localhost:8080/api/auth/connect/godaddy?brand=Proper%20%26%20Company&shop=${encodeURIComponent(shopDomain)}`;
    } catch (e: any) {
      toast({ title: 'Connection failed', description: e.message || 'Could not authorize with GoDaddy.', variant: 'destructive' });
      setLoading(false);
    }
  };

  const handleDisconnect = async () => {
    if (confirm('Disconnect Proper & Co from GoDaddy Websites + Marketing? Online product sync will pause.')) {
      setLoading(true);
      await disconnectGoDaddy();
      toast({ title: 'GoDaddy Disconnected', description: 'Proper & Co store connection revoked.' });
      onUpdate();
      setLoading(false);
      onClose();
