import { useState } from 'react';
import { InventoryCountSession } from '../types/properCommerceTypes';
import { createCountSession, submitCountSession, approveCountSession } from '../api/properCommerceApi';
import { Modal } from '@/components/vowos/ui';
import { ClipboardList, Plus, Barcode, EyeOff, CheckCircle2, AlertTriangle, Check, X, Search, Scan } from 'lucide-react';
import { toast } from '@vowos/design-system';

interface InventoryCountManagerProps {
  sessions: InventoryCountSession[];
  onUpdate: () => void;
}

export default function InventoryCountManager({ sessions, onUpdate }: InventoryCountManagerProps) {
  const [newModalOpen, setNewModalOpen] = useState(false);
  const [selectedLoc, setSelectedLoc] = useState<'pc-br' | 'pc-cov'>('pc-br');
  const [scope, setScope] = useState<'Full Store' | 'Category' | 'Vendor'>('Full Store');
  const [blindCount, setBlindCount] = useState(true);
  const [creating, setCreating] = useState(false);

  // Active Count Modal State
  const [activeSession, setActiveSession] = useState<InventoryCountSession | null>(null);
  const [scanSku, setScanSku] = useState('');

  const handleCreateSession = async () => {
    setCreating(true);
    try {
      const session = await createCountSession(selectedLoc, scope, blindCount, 'Manager');
      toast({ title: 'Inventory Count Created', description: `Started new ${scope} count for ${session.locationName}` });
      setNewModalOpen(false);
      onUpdate();
      setActiveSession(session);
    } catch (e: any) {
      toast({ title: 'Creation failed', description: e.message || 'Could not start count session.', variant: 'destructive' });
    } finally {
      setCreating(false);
    }
  };

  const handleScanItem = (skuInput: string) => {
    if (!activeSession || !skuInput.trim()) return;
    const targetSku = skuInput.trim().toUpperCase();
    const line = activeSession.lines.find((l) => l.sku.toUpperCase() === targetSku || l.sku.toUpperCase().includes(targetSku));

    if (line) {
      line.countedQty += 1;
      line.varianceQty = line.countedQty - line.expectedQty;
      activeSession.scannedCount += 1;
      setActiveSession({ ...activeSession });
      toast({ title: 'Item Scanned', description: `+1 ${line.productTitle} (${line.sku})` });
      setScanSku('');
    } else {
      toast({ title: 'SKU not found', description: `No item matching SKU ${skuInput} in count session.`, variant: 'destructive' });
    }
  };

  const handleSubmitSession = async () => {
    if (!activeSession) return;
    await submitCountSession(activeSession.id);
    toast({ title: 'Count Submitted for Review', description: 'Session submitted to manager for variance approval.' });
    setActiveSession(null);
    onUpdate();
  };

  const handleApproveSession = async (session: InventoryCountSession) => {
    if (confirm(`Approve physical count variances for ${session.id}? This will post inventory adjustments.`)) {
      await approveCountSession(session.id, 'Ramsey Sims');
      toast({ title: 'Count Approved', description: 'Inventory movements posted and Shopify stock synced.' });
      onUpdate();
    }
  };

  return (
    <div className="space-y-5 select-none">
      {/* Action Bar */}
      <div className="flex items-center justify-between bg-white p-4 rounded-2xl border border-stone-200 shadow-sm">
        <div>
          <h3 className="font-bold text-stone-900 text-sm">Physical Inventory Count Sessions</h3>
          <p className="text-xs text-stone-500">
            Conduct location stock audits for Proper Baton Rouge or Proper Covington.
          </p>
        </div>
        <button
          onClick={() => setNewModalOpen(true)}
          className="inline-flex items-center gap-2 rounded-xl bg-brand-primary px-4 py-2 text-xs font-bold text-white shadow-md hover:bg-brand-primary-hover transition-colors"
        >
          <Plus className="h-4 w-4" /> Start New Physical Count
        </button>
      </div>

      {/* Count Sessions Grid */}
      <div className="space-y-4">
        {sessions.map((s) => (
          <div key={s.id} className="rounded-2xl border border-stone-200 bg-white p-5 shadow-sm space-y-3">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <div>
                <div className="flex items-center gap-2">
                  <span className="font-bold text-stone-900 text-base">{s.id}</span>
                  <span className="rounded-full bg-stone-100 px-2.5 py-0.5 text-xs font-semibold text-stone-700">
                    {s.locationName}
                  </span>
                  {s.blindCount && (
                    <span className="inline-flex items-center gap-1 rounded-full bg-violet-100 px-2.5 py-0.5 text-xs font-bold text-violet-800">
                      <EyeOff className="h-3 w-3" /> Blind Count
                    </span>
                  )}
                </div>
                <p className="text-xs text-stone-500 mt-0.5">
                  Scope: <strong>{s.scope}</strong> ┬╖ Started by <strong>{s.startedBy}</strong> on {new Date(s.startedAt).toLocaleTimeString()}
                </p>
              </div>

              <div className="flex items-center gap-2">
                {s.status === 'in_progress' && (
                  <button
                    onClick={() => setActiveSession(s)}
                    className="inline-flex items-center gap-1.5 rounded-xl bg-brand-primary px-4 py-2 text-xs font-bold text-white shadow-xs hover:bg-brand-primary-hover"
                  >
                    <Scan className="h-4 w-4" /> Resume Scan
                  </button>
                )}
                {s.status === 'awaiting_approval' && (
                  <button
                    onClick={() => handleApproveSession(s)}
                    className="inline-flex items-center gap-1.5 rounded-xl bg-emerald-600 px-4 py-2 text-xs font-bold text-white shadow-xs hover:bg-emerald-700"
                  >
                    <CheckCircle2 className="h-4 w-4" /> Approve &amp; Post Variances
                  </button>
                )}
                {s.status === 'approved' && (
                  <span className="inline-flex items-center gap-1 rounded-full bg-emerald-100 px-3 py-1 text-xs font-bold text-emerald-800">
                    <Check className="h-3.5 w-3.5" /> Approved &amp; Posted
                  </span>
                )}
              </div>
            </div>

            {/* Progress & Variance Summary */}
            <div className="grid grid-cols-3 gap-4 bg-stone-50 p-3 rounded-xl border border-stone-200 text-xs">
              <div>
                <p className="text-stone-500">Expected Stock</p>
                <p className="font-bold text-stone-900 text-sm">{s.totalExpected} units</p>
              </div>
              <div>
                <p className="text-stone-500">Scanned Stock</p>
                <p className="font-bold text-stone-900 text-sm">{s.scannedCount} units</p>
              </div>
              <div>
                <p className="text-stone-500">Variance</p>
                <p className={`font-bold text-sm ${s.totalVarianceUnits === 0 ? 'text-status-success' : 'text-brand-primary'}`}>
                  {s.totalVarianceUnits} units
                </p>
              </div>
            </div>
          </div>
        ))}
        {sessions.length === 0 && (
          <div className="rounded-2xl border border-dashed border-stone-300 p-12 text-center text-stone-400">
            No physical inventory count sessions active. Click "Start New Physical Count" to begin.
          </div>
        )}
      </div>

      {/* Start New Count Modal */}
      <Modal open={newModalOpen} onClose={() => setNewModalOpen(false)} title="Start Physical Inventory Count">
        <div className="space-y-4 select-none">
          <div>
            <label className="block text-xs font-semibold text-stone-700 mb-1">Target Location</label>
            <select
              value={selectedLoc}
              onChange={(e) => setSelectedLoc(e.target.value as any)}
              className="w-full rounded-xl border border-stone-300 bg-white p-2.5 text-xs font-semibold text-stone-800"
            >
              <option value="pc-br">Proper &amp; Co ΓÇö Baton Rouge</option>
              <option value="pc-cov">Proper &amp; Co ΓÇö Covington</option>
            </select>
          </div>

          <div>
            <label className="block text-xs font-semibold text-stone-700 mb-1">Count Scope</label>
            <select
              value={scope}
              onChange={(e) => setScope(e.target.value as any)}
              className="w-full rounded-xl border border-stone-300 bg-white p-2.5 text-xs font-semibold text-stone-800"
            >
              <option value="Full Store">Full Store Physical Count</option>
              <option value="Category">Category Cycle Count</option>
              <option value="Vendor">Vendor Spot Count</option>
            </select>
          </div>

          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="blindCountCheck"
              checked={blindCount}
              onChange={(e) => setBlindCount(e.target.checked)}
              className="rounded text-brand-primary accent-rose-500"
            />
            <label htmlFor="blindCountCheck" className="text-xs font-semibold text-stone-800 cursor-pointer">
              Enable Blind Count Mode (Staff cannot see expected stock numbers while scanning)
            </label>
          </div>

          <div className="flex justify-end gap-2 border-t border-stone-100 pt-4">
            <button
              onClick={() => setNewModalOpen(false)}
              className="rounded-xl border border-stone-300 bg-white px-4 py-2 text-xs font-bold text-stone-700 hover:bg-stone-50"
            >
              Cancel
            </button>
            <button
              onClick={handleCreateSession}
              disabled={creating}
              className="inline-flex items-center gap-1.5 rounded-xl bg-brand-primary px-5 py-2 text-xs font-bold text-white shadow-md hover:bg-brand-primary-hover"
            >
              Start Session
            </button>
          </div>
        </div>
      </Modal>

      {/* Active Count Scanner Modal */}
      {activeSession && (
        <Modal open={true} onClose={() => setActiveSession(null)} title={`Active Count ΓÇö ${activeSession.id}`}>
          <div className="space-y-5 select-none">
            {/* Barcode Scanner Input */}
            <div className="flex items-center gap-2 bg-stone-50 p-3 rounded-2xl border border-stone-200">
              <Barcode className="h-5 w-5 text-stone-500" />
              <input
                type="text"
                value={scanSku}
                onChange={(e) => setScanSku(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') handleScanItem(scanSku);
                }}
                placeholder="Scan barcode or enter SKU..."
                className="flex-1 bg-transparent text-sm font-bold text-stone-900 placeholder-stone-400 focus:outline-none"
                autoFocus
              />
              <button
                onClick={() => handleScanItem(scanSku)}
                className="rounded-xl bg-brand-primary px-4 py-2 text-xs font-bold text-white hover:bg-brand-primary-hover"
              >
                Scan Item
              </button>
            </div>

            {/* Scanned Lines Table */}
            <div className="max-h-60 overflow-y-auto rounded-xl border border-stone-200 bg-white">
              <table className="w-full text-left text-xs text-stone-600">
                <thead className="bg-stone-50 text-[10px] font-bold uppercase text-stone-500 border-b">
                  <tr>
                    <th className="p-2">Item / SKU</th>
                    {!activeSession.blindCount && <th className="p-2">Expected</th>}
                    <th className="p-2">Scanned</th>
                    <th className="p-2">Variance</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {activeSession.lines.map((l, i) => (
                    <tr key={i}>
                      <td className="p-2 font-semibold text-stone-900">{l.productTitle} ({l.sku})</td>
                      {!activeSession.blindCount && <td className="p-2 font-bold text-stone-700">{l.expectedQty}</td>}
                      <td className="p-2 font-bold text-brand-primary">{l.countedQty}</td>
                      <td className="p-2 font-bold">{l.varianceQty}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <div className="flex justify-end gap-2 border-t border-stone-100 pt-4">
              <button
                onClick={() => setActiveSession(null)}
                className="rounded-xl border border-stone-300 bg-white px-4 py-2 text-xs font-bold text-stone-700 hover:bg-stone-50"
              >
                Save Progress
              </button>
              <button
                onClick={handleSubmitSession}
                className="rounded-xl bg-emerald-600 px-5 py-2 text-xs font-bold text-white hover:bg-emerald-700"
              >
                Submit Count for Review
              </button>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

import { useState, useMemo } from 'react';
import { CatalogProduct, InventoryLevel, InventoryMovement } from '../types/properCommerceTypes';
import Product360Modal from './Product360Modal';
import { formatDate } from '@/data/vowosData';
import { Search, MapPin, ArrowRightLeft, History, PackageCheck, AlertCircle, RefreshCw } from 'lucide-react';

interface InventoryLevelsViewProps {
  levels: InventoryLevel[];
  movements: InventoryMovement[];
  products?: CatalogProduct[];
  onUpdate?: () => void;
}

export default function InventoryLevelsView({ levels, movements, products = [], onUpdate = () => {} }: InventoryLevelsViewProps) {
  const [activeTab, setActiveTab] = useState<'levels' | 'movements'>('levels');
  const [selectedLocation, setSelectedLocation] = useState<'all' | 'pc-br' | 'pc-cov'>('all');
  const [query, setQuery] = useState('');
  const [drilldownProd, setDrilldownProd] = useState<CatalogProduct | null>(null);

  const filteredLevels = useMemo(() => {
    return levels.filter((lvl) => {
      const matchesLoc = selectedLocation === 'all' || lvl.locationId === selectedLocation;
      const matchesQuery =
        lvl.sku.toLowerCase().includes(query.toLowerCase()) ||
        lvl.productTitle.toLowerCase().includes(query.toLowerCase());
      return matchesLoc && matchesQuery;
    });
  }, [levels, selectedLocation, query]);

  const filteredMovements = useMemo(() => {
    return movements.filter((m) => {
      const matchesLoc = selectedLocation === 'all' || m.locationId === selectedLocation;
      const matchesQuery =
        m.sku.toLowerCase().includes(query.toLowerCase()) ||
        m.productTitle.toLowerCase().includes(query.toLowerCase()) ||
        m.reason.toLowerCase().includes(query.toLowerCase());
      return matchesLoc && matchesQuery;
    });
  }, [movements, selectedLocation, query]);

  return (
    <div className="space-y-5 select-none">
      {/* Header Tabs & Filters */}
      <div className="flex flex-wrap items-center justify-between gap-3 bg-white p-4 rounded-2xl border border-stone-200 shadow-sm">
        <div className="flex items-center gap-2">
          <button
            onClick={() => setActiveTab('levels')}
            className={`px-4 py-2 text-xs font-bold rounded-xl transition-colors ${
              activeTab === 'levels' ? 'bg-brand-primary text-white shadow-xs' : 'bg-stone-100 text-stone-600 hover:bg-stone-200'
            }`}
          >
            Location Inventory Levels
          </button>
          <button
            onClick={() => setActiveTab('movements')}
            className={`px-4 py-2 text-xs font-bold rounded-xl transition-colors ${
              activeTab === 'movements' ? 'bg-brand-primary text-white shadow-xs' : 'bg-stone-100 text-stone-600 hover:bg-stone-200'
            }`}
          >
            Inventory Movement Ledger
          </button>
        </div>

        <div className="flex items-center gap-3">
          <select
            value={selectedLocation}
            onChange={(e) => setSelectedLocation(e.target.value as any)}
            className="rounded-xl border border-stone-300 bg-white px-3 py-2 text-xs font-bold text-stone-700 focus:outline-none"
          >
            <option value="all">Location: All Proper Stores</option>
            <option value="pc-br">Proper &amp; Co ΓÇö Baton Rouge</option>
            <option value="pc-cov">Proper &amp; Co ΓÇö Covington</option>
          </select>

          <div className="relative">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-stone-400" />
            <input
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search SKU or title..."
              className="rounded-xl border border-stone-300 bg-white pl-9 pr-3 py-2 text-xs font-medium text-stone-900 focus:outline-none"
            />
          </div>
        </div>
      </div>

      {/* Tab 1: Inventory Levels */}
      {activeTab === 'levels' && (
        <div className="overflow-hidden rounded-2xl border border-stone-200 bg-white shadow-sm">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs text-stone-600">
              <thead className="bg-stone-50 text-[11px] font-bold uppercase tracking-wider text-stone-500 border-b border-stone-200">
                <tr>
                  <th className="px-4 py-3">Product / SKU</th>
                  <th className="px-4 py-3">Location</th>
                  <th className="px-4 py-3">On Hand</th>
                  <th className="px-4 py-3">Committed / Reserved</th>
                  <th className="px-4 py-3">Available for Online</th>
                  <th className="px-4 py-3">Reorder Threshold</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-stone-100">
                {filteredLevels.map((lvl, idx) => (
                  <tr key={idx} className="transition-colors hover:bg-brand-soft/30">
                    <td className="px-4 py-3.5">
                      <p
                        onClick={() => {
                          const targetProd = products.find((p) => p.variants.some((v) => v.sku === lvl.sku));
                          if (targetProd) setDrilldownProd(targetProd);
                        }}
                        className="font-bold text-stone-900 cursor-pointer hover:text-brand-primary hover:underline transition-colors"
                      >
                        {lvl.productTitle}
                      </p>
                      <p className="text-[11px] font-mono text-stone-400">SKU: {lvl.sku}</p>
                    </td>
                    <td className="px-4 py-3.5 font-semibold text-stone-800">
                      <span className="inline-flex items-center gap-1">
                        <MapPin className="h-3.5 w-3.5 text-brand-primary" /> {lvl.locationName}
                      </span>
                    </td>
                    <td className="px-4 py-3.5 font-bold text-stone-900">{lvl.onHand} units</td>
                    <td className="px-4 py-3.5 text-stone-500">{lvl.committed + lvl.reserved} units</td>
                    <td className="px-4 py-3.5">
                      <span className="rounded-full bg-emerald-100 px-2.5 py-0.5 font-bold text-emerald-800">
                        {lvl.available} available
                      </span>
                    </td>
                    <td className="px-4 py-3.5 text-stone-500">
                      Reorder at Γëñ {lvl.reorderPoint} units
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Tab 2: Inventory Movement Ledger */}
      {activeTab === 'movements' && (
        <div className="overflow-hidden rounded-2xl border border-stone-200 bg-white shadow-sm">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs text-stone-600">
              <thead className="bg-stone-50 text-[11px] font-bold uppercase tracking-wider text-stone-500 border-b border-stone-200">
                <tr>
                  <th className="px-4 py-3">Timestamp</th>
                  <th className="px-4 py-3">Product / SKU</th>
                  <th className="px-4 py-3">Location</th>
                  <th className="px-4 py-3">Quantity Delta</th>
                  <th className="px-4 py-3">Movement Type</th>
                  <th className="px-4 py-3">Reason / Staff</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-stone-100">
                {filteredMovements.map((mov) => (
                  <tr key={mov.id} className="transition-colors hover:bg-stone-50">
                    <td className="px-4 py-3.5 font-mono text-[11px] text-stone-500">{formatDate(mov.occurredAt)}</td>
                    <td className="px-4 py-3.5">
                      <p className="font-bold text-stone-900">{mov.productTitle}</p>
                      <p className="text-[11px] font-mono text-stone-400">{mov.sku}</p>
                    </td>
                    <td className="px-4 py-3.5 font-semibold text-stone-800">
                      {mov.locationId === 'pc-br' ? 'Proper Baton Rouge' : 'Proper Covington'}
                    </td>
                    <td className="px-4 py-3.5 font-bold">
                      <span className={mov.quantityDelta >= 0 ? 'text-status-success' : 'text-brand-primary'}>
                        {mov.quantityDelta >= 0 ? `+${mov.quantityDelta}` : mov.quantityDelta} units
                      </span>
                    </td>
                    <td className="px-4 py-3.5">
                      <span className="rounded bg-stone-100 px-2 py-0.5 font-semibold text-stone-700 uppercase text-[10px]">
                        {mov.movementType.replace('_', ' ')}
                      </span>
                    </td>
                    <td className="px-4 py-3.5">
                      <p className="text-stone-800">{mov.reason}</p>
                      <p className="text-[11px] text-stone-400">By: {mov.performedBy}</p>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Product 360 Drilldown Modal */}
      {drilldownProd && (
        <Product360Modal
          product={drilldownProd}
          movements={movements}
          onClose={() => setDrilldownProd(null)}
          onUpdate={onUpdate}
        />
      )}
    </div>
  );
}

import { useState, useMemo } from 'react';
import { CatalogProduct, InventoryMovement, PurchaseMode } from '../types/properCommerceTypes';
import { updateCatalogProduct, recordStockAdjustment } from '../api/properCommerceApi';
import { formatCents, marginPct, formatDate } from '@/data/vowosData';
import { Modal } from '@/components/vowos/ui';
import { Package, Globe, Lock, Tag, MapPin, History, Code, Edit3, CheckCircle2, ExternalLink, Plus, Minus, RefreshCw, Layers, DollarSign, ShieldCheck } from 'lucide-react';
import { toast } from '@vowos/design-system';

interface Product360ModalProps {
  product: CatalogProduct | null;
  movements: InventoryMovement[];
  onClose: () => void;
  onUpdate: () => void;
}

export default function Product360Modal({ product, movements, onClose, onUpdate }: Product360ModalProps) {
  const [activeTab, setActiveTab] = useState<'source' | 'stock' | 'ledger' | 'json'>('source');
  const [editingPrice, setEditingPrice] = useState(false);
  const [retailInput, setRetailInput] = useState(
    (product?.variants?.[0]?.retailPriceCents / 100 || 0).toString()
  );
  const [costInput, setCostInput] = useState(
    (product?.variants?.[0]?.costCents / 100 || 0).toString()
  );

  // Manual Stock Adjustment state
  const [selectedVariantId, setSelectedVariantId] = useState(product?.variants?.[0]?.id || '');
  const [adjustLocation, setAdjustLocation] = useState<'pc-br' | 'pc-cov'>('pc-br');
  const [adjustQty, setAdjustQty] = useState(1);
  const [adjustReason, setAdjustReason] = useState('Manual cycle adjustment');

  // Filter movements for this product's variants
  const itemMovements = useMemo(() => {
    if (!product) return [];
    const variantSkus = product.variants.map((v) => v.sku);
    return movements.filter((m) => variantSkus.includes(m.sku));
  }, [movements, product]);

  if (!product) return null;

  const primaryVariant = product.variants[0];
  const currentCost = primaryVariant?.costCents || 0;
  const currentRetail = primaryVariant?.retailPriceCents || 0;
  const currentMargin = marginPct(currentCost, currentRetail);

  const handleSavePrices = async () => {
    const newRetailCents = Math.round(parseFloat(retailInput) * 100);
    const newCostCents = Math.round(parseFloat(costInput) * 100);

    if (isNaN(newRetailCents) || isNaN(newCostCents)) {
      toast({ title: 'Invalid price', description: 'Please enter valid dollar amounts.', variant: 'destructive' });
      return;
    }

    const updatedVariants = product.variants.map((v) => ({
      ...v,
      retailPriceCents: newRetailCents,
      costCents: newCostCents,
    }));

    await updateCatalogProduct(product.id, { variants: updatedVariants });
    toast({ title: 'Prices Updated', description: 'Updated cost & retail price across all variants.' });
    setEditingPrice(false);
    onUpdate();
  };

  const handleApplyAdjustment = async () => {
    if (!selectedVariantId) return;
    await recordStockAdjustment(
      product.id,
      selectedVariantId,
      adjustLocation,
      adjustQty,
      adjustReason,
      'Ramsey Sims'
    );
    toast({ title: 'Stock Adjusted', description: `Recorded ${adjustQty > 0 ? '+' : ''}${adjustQty} stock delta.` });
    onUpdate();
  };

  const togglePublish = async () => {
    const nextStatus = product.publishStatus === 'published' ? 'draft' : 'published';
    await updateCatalogProduct(product.id, {
      publishStatus: nextStatus,
      syncStatus: nextStatus === 'published' ? 'synced' : 'unpublished',
      lastSyncedAt: new Date().toISOString(),
    });
    toast({
      title: nextStatus === 'published' ? 'Published to Shopify' : 'Unpublished to Draft',
      description: `${product.title} status is now ${nextStatus}.`,
    });
    onUpdate();
  };

  return (
    <Modal open={true} onClose={onClose} title={`Product 360 Drilldown ΓÇö ${product.title}`}>
      <div className="space-y-5 select-none max-w-3xl">
        {/* Header Hero Card */}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 rounded-2xl bg-stone-900 p-4 text-white shadow-md">
          <div className="flex items-center gap-3">
            <div className="h-14 w-14 overflow-hidden rounded-xl bg-stone-800 border border-stone-700 flex-shrink-0">
              {product.primaryImageUrl ? (
                <img src={product.primaryImageUrl} alt={product.title} className="h-full w-full object-cover" />
              ) : (
                <div className="flex h-full w-full items-center justify-center text-stone-500">
                  <Package className="h-6 w-6" />
                </div>
              )}
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="font-bold text-white text-base">{product.title}</h3>
                <span
                  className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-bold ${
                    product.publishStatus === 'published'
                      ? 'bg-status-success/20 text-emerald-300 ring-1 ring-emerald-500/40'
                      : 'bg-status-warning/20 text-amber-300 ring-1 ring-status-warning/40'
                  }`}
                >
                  {product.publishStatus === 'published' ? <Globe className="h-3 w-3" /> : <Lock className="h-3 w-3" />}
                  {product.publishStatus === 'published' ? 'Published on Shopify' : 'Internal Draft'}
                </span>
              </div>
              <p className="text-xs text-stone-300">
                Style: <strong>{product.styleNumber}</strong> ┬╖ Vendor: <strong>{product.vendorName}</strong> ┬╖ Category: <strong>{product.category}</strong>
              </p>
              {product.shopifyProductId && (
                <p className="text-[11px] font-mono text-stone-400 mt-0.5">Shopify GID: {product.shopifyProductId}</p>
              )}
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={togglePublish}
              className={`rounded-xl px-3 py-1.5 text-xs font-bold transition-colors ${
                product.publishStatus === 'published'
                  ? 'bg-stone-800 text-stone-300 hover:bg-stone-700'
                  : 'bg-brand-primary text-white hover:bg-brand-primary-hover'
              }`}
            >
              {product.publishStatus === 'published' ? 'Unpublish to Draft' : 'Publish to Shopify'}
            </button>
          </div>
        </div>

        {/* Modal Navigation Sub-Tabs */}
        <div className="flex border-b border-stone-200 gap-2">
          <button
            onClick={() => setActiveTab('source')}
            className={`flex items-center gap-1.5 border-b-2 px-3 py-2 text-xs font-bold transition-colors ${
              activeTab === 'source' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-stone-500 hover:text-stone-800'
            }`}
          >
            <Tag className="h-3.5 w-3.5" /> Source Metadata &amp; Margin
          </button>
          <button
            onClick={() => setActiveTab('stock')}
            className={`flex items-center gap-1.5 border-b-2 px-3 py-2 text-xs font-bold transition-colors ${
              activeTab === 'stock' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-stone-500 hover:text-stone-800'
            }`}
          >
            <MapPin className="h-3.5 w-3.5" /> Multi-Location Stock
          </button>
          <button
            onClick={() => setActiveTab('ledger')}
            className={`flex items-center gap-1.5 border-b-2 px-3 py-2 text-xs font-bold transition-colors ${
              activeTab === 'ledger' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-stone-500 hover:text-stone-800'
            }`}
          >
            <History className="h-3.5 w-3.5" /> Item Audit Ledger ({itemMovements.length})
          </button>
          <button
            onClick={() => setActiveTab('json')}
            className={`flex items-center gap-1.5 border-b-2 px-3 py-2 text-xs font-bold transition-colors ${
              activeTab === 'json' ? 'border-brand-primary text-brand-primary' : 'border-transparent text-stone-500 hover:text-stone-800'
            }`}
          >
            <Code className="h-3.5 w-3.5" /> Raw Source Schema
          </button>
        </div>

        {/* TAB 1: Source Metadata */}
        {activeTab === 'source' && (
          <div className="space-y-4 text-xs">
            <div className="grid grid-cols-2 gap-4 rounded-xl border border-stone-200 bg-stone-50 p-4">
              <div>
                <p className="text-stone-400">Retail Selling Price</p>
                {editingPrice ? (
                  <input
                    type="number"
                    value={retailInput}
                    onChange={(e) => setRetailInput(e.target.value)}
                    className="w-24 rounded border border-stone-300 px-2 py-1 font-bold text-stone-900"
                  />
                ) : (
                  <p className="text-lg font-bold text-stone-900">{formatCents(currentRetail)}</p>
                )}
              </div>
              <div>
                <p className="text-stone-400">Wholesale Cost Basis</p>
                {editingPrice ? (
                  <input
                    type="number"
                    value={costInput}
                    onChange={(e) => setCostInput(e.target.value)}
                    className="w-24 rounded border border-stone-300 px-2 py-1 font-bold text-stone-900"
                  />
                ) : (
                  <p className="text-lg font-bold text-stone-900">{formatCents(currentCost)}</p>
                )}
              </div>
              <div>
                <p className="text-stone-400">Gross Profit Margin</p>
                <p className="text-lg font-bold text-status-success">{currentMargin}% Margin</p>
              </div>
              <div>
                <p className="text-stone-400">Purchase Mode</p>
                <p className="font-bold text-stone-900 capitalize">{product.purchaseMode.replace('_', ' ')}</p>
              </div>
            </div>

            <div className="flex justify-end gap-2">
              {editingPrice ? (
                <>
                  <button
                    onClick={() => setEditingPrice(false)}
                    className="rounded-xl border border-stone-300 bg-white px-3 py-1.5 text-xs font-bold text-stone-700 hover:bg-stone-50"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={handleSavePrices}
                    className="rounded-xl bg-emerald-600 px-4 py-1.5 text-xs font-bold text-white hover:bg-emerald-700"
                  >
                    Save Prices
                  </button>
                </>
              ) : (
                <button
                  onClick={() => setEditingPrice(true)}
                  className="inline-flex items-center gap-1 rounded-xl border border-stone-300 bg-white px-3 py-1.5 text-xs font-bold text-stone-700 hover:bg-stone-50"
                >
                  <Edit3 className="h-3.5 w-3.5 text-brand-primary" /> Edit Cost &amp; Retail Price
                </button>
              )}
            </div>

            <div className="space-y-2 border-t border-stone-100 pt-3">
              <p className="font-bold text-stone-900">Tags &amp; Collections</p>
              <div className="flex flex-wrap gap-1.5">
                {product.tags.map((t) => (
                  <span key={t} className="rounded-full bg-brand-soft border border-border-subtle px-2.5 py-0.5 text-[11px] font-semibold text-brand-primary-hover">
                    {t}
                  </span>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* TAB 2: Multi-Location Stock & Manual Adjustment */}
        {activeTab === 'stock' && (
          <div className="space-y-4 text-xs">
            <div className="rounded-xl border border-stone-200 bg-white overflow-hidden">
              <table className="w-full text-left text-xs text-stone-600">
                <thead className="bg-stone-50 text-[10px] font-bold uppercase text-stone-500 border-b">
                  <tr>
                    <th className="p-2.5">Variant / Size / Color</th>
                    <th className="p-2.5">SKU &amp; Barcode</th>
                    <th className="p-2.5">Baton Rouge Stock</th>
                    <th className="p-2.5">Covington Stock</th>
                    <th className="p-2.5">Total Available</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {product.variants.map((v) => (
                    <tr key={v.id}>
                      <td className="p-2.5 font-bold text-stone-900">
                        {v.color} / {v.size}
                      </td>
                      <td className="p-2.5 font-mono text-[11px] text-stone-500">
                        {v.sku} <br />
                        <span className="text-[10px] text-stone-400">UPC: {v.barcode}</span>
                      </td>
                      <td className="p-2.5 font-bold text-stone-800">{v.inventoryBatonRouge} units</td>
                      <td className="p-2.5 font-bold text-stone-800">{v.inventoryCovington} units</td>
                      <td className="p-2.5">
                        <span className="rounded-full bg-emerald-100 px-2 py-0.5 font-bold text-emerald-800">
                          {v.inventoryBatonRouge + v.inventoryCovington} total
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Quick Adjustment Tool */}
            <div className="rounded-2xl border border-stone-200 bg-stone-50 p-4 space-y-3">
              <p className="font-bold text-stone-900">Record Stock Adjustment</p>
              <div className="grid grid-cols-4 gap-2">
                <select
                  value={selectedVariantId}
                  onChange={(e) => setSelectedVariantId(e.target.value)}
                  className="rounded-xl border border-stone-300 bg-white p-2 text-xs font-semibold text-stone-800"
                >
                  {product.variants.map((v) => (
                    <option key={v.id} value={v.id}>
                      {v.color} / {v.size} ({v.sku})
                    </option>
                  ))}
                </select>

                <select
                  value={adjustLocation}
                  onChange={(e) => setAdjustLocation(e.target.value as any)}
                  className="rounded-xl border border-stone-300 bg-white p-2 text-xs font-semibold text-stone-800"
                >
                  <option value="pc-br">Proper Baton Rouge</option>
                  <option value="pc-cov">Proper Covington</option>
                </select>

                <input
                  type="number"
                  value={adjustQty}
                  onChange={(e) => setAdjustQty(parseInt(e.target.value, 10) || 0)}
                  placeholder="Delta e.g. +1 or -1"
                  className="rounded-xl border border-stone-300 bg-white p-2 text-xs font-bold text-stone-900"
                />

                <button
                  onClick={handleApplyAdjustment}
                  className="rounded-xl bg-brand-primary py-2 text-xs font-bold text-white hover:bg-brand-primary-hover"
                >
                  Post Adjustment
                </button>
              </div>

              <div>
                <label className="block text-[11px] font-semibold text-stone-500 mb-1">Adjustment Reason / Note</label>
                <input
                  type="text"
                  value={adjustReason}
                  onChange={(e) => setAdjustReason(e.target.value)}
                  className="w-full rounded-xl border border-stone-300 bg-white px-3 py-1.5 text-xs text-stone-900"
                />
              </div>
            </div>
          </div>
        )}

        {/* TAB 3: Audit Ledger */}
        {activeTab === 'ledger' && (
          <div className="space-y-3 text-xs max-h-80 overflow-y-auto">
            {itemMovements.map((m) => (
              <div key={m.id} className="flex items-center justify-between rounded-xl border border-stone-200 bg-white p-3 shadow-2xs">
                <div>
                  <p className="font-bold text-stone-900">{m.reason}</p>
                  <p className="text-[11px] font-mono text-stone-400">
                    {m.sku} ┬╖ Location: {m.locationId === 'pc-br' ? 'Baton Rouge' : 'Covington'} ┬╖ Staff: {m.performedBy}
                  </p>
                </div>
                <div className="text-right">
                  <span className={`font-bold ${m.quantityDelta >= 0 ? 'text-status-success' : 'text-brand-primary'}`}>
                    {m.quantityDelta >= 0 ? `+${m.quantityDelta}` : m.quantityDelta} units
                  </span>
                  <p className="text-[10px] text-stone-400">{formatDate(m.occurredAt)}</p>
                </div>
              </div>
            ))}
            {itemMovements.length === 0 && (
              <p className="py-8 text-center text-stone-400">No stock movements recorded for this item yet.</p>
            )}
          </div>
        )}

        {/* TAB 4: Raw JSON Source Schema */}
        {activeTab === 'json' && (
          <div className="rounded-xl border border-stone-800 bg-stone-950 p-4 text-[11px] font-mono text-emerald-400 max-h-80 overflow-y-auto">
            <pre>{JSON.stringify(product, null, 2)}</pre>
          </div>
        )}

        {/* Modal Actions */}
        <div className="flex justify-end border-t border-stone-100 pt-4">
          <button
            onClick={onClose}
            className="rounded-xl border border-stone-300 bg-white px-5 py-2 text-xs font-bold text-stone-700 hover:bg-stone-50"
          >
            Close Drilldown
          </button>
        </div>
      </div>
    </Modal>
  );
}

import { useState } from 'react';
import { CommerceConnection } from '../types/properCommerceTypes';
import { connectShopify, disconnectShopify } from '../api/properCommerceApi';
import { Modal } from '@/components/vowos/ui';
import { ShoppingBag, ShieldCheck, CheckCircle2, AlertTriangle, ExternalLink, RefreshCw, Lock, Link2 } from 'lucide-react';
import { toast } from '@/components/ui/use-toast';

interface ShopifyConnectModalProps {
  open: boolean;
  onClose: () => void;
  connection: CommerceConnection;
  onUpdate: () => void;
}

export default function ShopifyConnectModal({ open, onClose, connection, onUpdate }: ShopifyConnectModalProps) {
  const [shopDomain, setShopDomain] = useState(connection.shopDomain || 'properandcompany.myshopify.com');
  const [loading, setLoading] = useState(false);

  const handleConnect = async () => {
    if (!shopDomain.trim()) {
      toast({ title: 'Enter shop domain', description: 'Please enter your Proper & Co Shopify store domain.', variant: 'destructive' });
      return;
    }

    setLoading(true);
    try {
      const apiUrl = import.meta.env.VITE_API_URL || '';
      window.location.href = `${apiUrl}/api/auth/connect/shopify?brand=Proper%20%26%20Company&shop=${encodeURIComponent(shopDomain)}`;
    } catch (e: any) {
      toast({ title: 'Connection failed', description: e.message || 'Could not authorize with Shopify.', variant: 'destructive' });
      setLoading(false);
    }
  };

  const handleDisconnect = async () => {
    if (confirm('Disconnect Proper & Co from Shopify? Online product sync will pause.')) {
      setLoading(true);
      await disconnectShopify();
      toast({ title: 'Shopify Disconnected', description: 'Proper & Co store connection revoked.' });
      onUpdate();
      setLoading(false);
      onClose();
    }
  };

  return (
    <Modal open={open} onClose={onClose} title="Connect Proper & Co to Shopify">
      <div className="space-y-5 select-none">
        {/* Security Shield Callout */}
        <div className="rounded-2xl border border-rose-200 bg-rose-50/50 p-4 text-xs text-stone-700 space-y-2">
          <div className="flex items-center gap-2 font-semibold text-rose-900">
            <Lock className="h-4 w-4 text-rose-600" />
            <span>Secure Direct OAuth Authorization</span>
          </div>
          <p className="text-stone-600 leading-relaxed">
            VowOS connects to Proper & CoΓÇÖs Shopify store via official merchant OAuth. 
            <strong className="text-stone-900 font-semibold"> VowOS never asks for, receives, or stores your Shopify login password.</strong>
          </p>
        </div>

        {/* Status Card */}
        <div className="rounded-2xl border border-stone-200 bg-stone-50 p-4 space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-100 text-emerald-600">
                <ShoppingBag className="h-5 w-5" />
              </div>
              <div>
                <p className="text-sm font-bold text-stone-900">{connection.shopName}</p>
                <p className="text-xs text-stone-500">{connection.shopDomain}</p>
              </div>
            </div>
            <span
              className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-semibold ${
                connection.status === 'connected'
                  ? 'bg-emerald-100 text-emerald-700 ring-1 ring-emerald-300'
                  : 'bg-amber-100 text-amber-800 ring-1 ring-amber-300'
              }`}
            >
              <CheckCircle2 className="h-3.5 w-3.5" />
              {connection.status === 'connected' ? 'Connected ┬╖ Healthy' : 'Disconnected'}
            </span>
          </div>

          {connection.status === 'connected' && (
            <div className="border-t border-stone-200/60 pt-3 text-[11px] text-stone-500 flex flex-wrap gap-x-4 gap-y-1">
              <span>Granted Scopes: <strong>Products, Inventory, Orders, Webhooks</strong></span>
              <span>Last Verified: <strong>{new Date(connection.lastVerifiedAt || '').toLocaleDateString()}</strong></span>
            </div>
          )}
        </div>

        {/* Input Field */}
        <div>
          <label className="block text-xs font-semibold text-stone-700 mb-1.5">
            Proper & Co Shopify Store Permanent Domain
          </label>
          <div className="relative">
            <input
              type="text"
              value={shopDomain}
              onChange={(e) => setShopDomain(e.target.value)}
              placeholder="properandcompany.myshopify.com"
              className="w-full rounded-xl border border-stone-300 bg-white px-3.5 py-2 text-sm text-stone-900 placeholder-stone-400 focus:border-rose-500 focus:outline-none focus:ring-2 focus:ring-rose-500/20"
            />
          </div>
          <p className="text-[11px] text-stone-400 mt-1">Example: properandcompany.myshopify.com</p>
        </div>

        {/* Granted Scopes Checklist */}
        <div className="space-y-2">
          <p className="text-xs font-semibold text-stone-700">Authorized System Permissions:</p>
          <ul className="grid grid-cols-2 gap-2 text-xs text-stone-600">
            <li className="flex items-center gap-1.5">
              <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500" /> Read & Write Product Catalog
            </li>
            <li className="flex items-center gap-1.5">
              <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500" /> Multi-Location Stock Sync
            </li>
            <li className="flex items-center gap-1.5">
              <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500" /> Mirror Online Orders
            </li>
            <li className="flex items-center gap-1.5">
              <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500" /> Operational Fulfillment & Returns
            </li>
          </ul>
        </div>

        {/* Actions */}
        <div className="flex items-center justify-between border-t border-stone-200 pt-4">
          {connection.status === 'connected' ? (
            <button
              onClick={handleDisconnect}
              disabled={loading}
              className="text-xs font-semibold text-rose-600 hover:text-rose-700 transition-colors"
            >
              Disconnect Store
            </button>
          ) : (
            <div />
          )}

          <div className="flex items-center gap-2">
            <button
              onClick={onClose}
              className="rounded-xl border border-stone-200 bg-white px-4 py-2 text-xs font-semibold text-stone-600 hover:bg-stone-50 transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={handleConnect}
              disabled={loading}
              className="inline-flex items-center gap-1.5 rounded-xl bg-rose-500 px-5 py-2 text-xs font-semibold text-white shadow-md hover:bg-rose-600 transition-colors disabled:opacity-50"
            >
              {loading ? <RefreshCw className="h-4 w-4 animate-spin" /> : <Link2 className="h-4 w-4" />}
              {connection.status === 'connected' ? 'Re-verify Connection' : 'Connect Shopify'}
            </button>
          </div>
        </div>
      </div>
    </Modal>
  );
}

import { useState } from 'react';
import { CommerceConnection } from '../types/properCommerceTypes';
import { connectSquare, disconnectSquare } from '../api/properCommerceApi';
import { Modal } from '@/components/vowos/ui';
import { ShoppingBag, ShieldCheck, CheckCircle2, RefreshCw, Lock, Link2, Square } from 'lucide-react';
import { toast } from '@vowos/design-system';

interface SquareConnectModalProps {
  open: boolean;
  onClose: () => void;
  connection: CommerceConnection | undefined;
  onUpdate: () => void;
}

export default function SquareConnectModal({ open, onClose, connection, onUpdate }: SquareConnectModalProps) {
  const [shopDomain, setShopDomain] = useState(connection?.shopDomain || 'properandcompany.square.site');
  const [loading, setLoading] = useState(false);

  const handleConnect = async () => {
    if (!shopDomain.trim()) {
      toast({ title: 'Enter shop domain', description: 'Please enter your Square store domain or location ID.', variant: 'destructive' });
      return;
    }

    setLoading(true);
    try {
      // Direct the user to the real backend OAuth initiation endpoint for Square
      window.location.href = `http://localhost:8080/api/auth/connect/square?brand=Proper%20%26%20Company&shop=${encodeURIComponent(shopDomain)}`;
    } catch (e: any) {
      toast({ title: 'Connection failed', description: e.message || 'Could not authorize with Square.', variant: 'destructive' });
      setLoading(false);
    }
  };

  const handleDisconnect = async () => {
    if (confirm('Disconnect Proper & Co from Square POS? In-store POS inventory sync will pause.')) {
      setLoading(true);
      await disconnectSquare();
      toast({ title: 'Square Disconnected', description: 'Proper & Co Square connection revoked.' });
      onUpdate();
      setLoading(false);
      onClose();
    }
  };

  return (
    <Modal open={open} onClose={onClose} title="Connect Proper & Co to Square">
      <div className="space-y-5 select-none">
        {/* Security Shield Callout */}
        <div className="rounded-2xl border border-border-subtle bg-brand-soft/50 p-4 text-xs text-stone-700 space-y-2">
          <div className="flex items-center gap-2 font-semibold text-brand-secondary">
            <Lock className="h-4 w-4 text-brand-primary" />
            <span>Secure Direct OAuth Authorization</span>
          </div>
          <p className="text-stone-600 leading-relaxed">
            VowOS connects to your Square POS via official Square OAuth. 
            <strong className="text-stone-900 font-semibold"> VowOS never asks for, receives, or stores your Square login password.</strong>
          </p>
        </div>

        {/* Status Card */}
        {connection && (
          <div className="rounded-2xl border border-stone-200 bg-stone-50 p-4 space-y-3">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-gray-200 text-gray-800">
                  <Square className="h-5 w-5" />
                </div>
                <div>
                  <p className="text-sm font-bold text-stone-900">{connection.shopName}</p>
                  <p className="text-xs text-stone-500">{connection.shopDomain}</p>
                </div>
              </div>
              <span
                className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-semibold ${
                  connection.status === 'connected'
                    ? 'bg-emerald-100 text-emerald-700 ring-1 ring-emerald-300'
                    : 'bg-amber-100 text-amber-800 ring-1 ring-amber-300'
                }`}
              >
                <CheckCircle2 className="h-3.5 w-3.5" />
                {connection.status === 'connected' ? 'Connected ┬╖ Healthy' : 'Disconnected'}
              </span>
            </div>

            {connection.status === 'connected' && (
              <div className="border-t border-stone-200/60 pt-3 text-[11px] text-stone-500 flex flex-wrap gap-x-4 gap-y-1">
                <span>Granted Scopes: <strong>{connection.grantedScopes.join(', ')}</strong></span>
                <span>Last Verified: <strong>{new Date(connection.lastVerifiedAt || '').toLocaleDateString()}</strong></span>
              </div>
            )}
          </div>
        )}

        {/* Input Field */}
        <div>
          <label className="block text-xs font-semibold text-stone-700 mb-1.5">
            Square Domain or Location ID
          </label>
          <div className="relative">
            <input
              type="text"
              value={shopDomain}
              onChange={(e) => setShopDomain(e.target.value)}
              placeholder="properandcompany.square.site"
              className="w-full rounded-xl border border-stone-300 bg-white px-3.5 py-2 text-sm text-stone-900 placeholder-stone-400 focus:border-brand-primary focus:outline-none focus:ring-2 focus:ring-focus-ring/20"
            />
          </div>
          <p className="text-[11px] text-stone-400 mt-1">Example: properandcompany.square.site</p>
        </div>

        {/* Granted Scopes Checklist */}
        <div className="space-y-2">
          <p className="text-xs font-semibold text-stone-700">Authorized System Permissions:</p>
          <ul className="grid grid-cols-2 gap-2 text-xs text-stone-600">
            <li className="flex items-center gap-1.5">
              <CheckCircle2 className="h-3.5 w-3.5 text-status-success" /> Read & Write Items Catalog
            </li>
            <li className="flex items-center gap-1.5">
              <CheckCircle2 className="h-3.5 w-3.5 text-status-success" /> Sync POS Inventory
            </li>
            <li className="flex items-center gap-1.5">
              <CheckCircle2 className="h-3.5 w-3.5 text-status-success" /> Mirror In-store Orders
            </li>
          </ul>
        </div>

        {/* Actions */}
        <div className="flex items-center justify-between border-t border-stone-200 pt-4">
          {connection?.status === 'connected' ? (
            <button
              onClick={handleDisconnect}
              disabled={loading}
              className="text-xs font-semibold text-brand-primary hover:text-brand-primary-hover transition-colors"
            >
              Disconnect Square
            </button>
          ) : (
            <div />
          )}

          <div className="flex items-center gap-2">
            <button
              onClick={onClose}
              className="rounded-xl border border-stone-200 bg-white px-4 py-2 text-xs font-semibold text-stone-600 hover:bg-stone-50 transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={handleConnect}
              disabled={loading}
              className="inline-flex items-center gap-1.5 rounded-xl bg-brand-primary px-5 py-2 text-xs font-semibold text-white shadow-md hover:bg-brand-primary-hover transition-colors disabled:opacity-50"
            >
              {loading ? <RefreshCw className="h-4 w-4 animate-spin" /> : <Link2 className="h-4 w-4" />}
              {connection?.status === 'connected' ? 'Re-verify Connection' : 'Connect Square'}
            </button>
          </div>
        </div>
      </div>
    </Modal>
  );
}

import { useState, useRef } from 'react';
import { generateVendorTemplateCSV, addCatalogProduct } from '../api/properCommerceApi';
import { CatalogProduct, PurchaseMode } from '../types/properCommerceTypes';
import { formatCents } from '@/data/vowosData';
import { Download, Upload, FileSpreadsheet, CheckCircle2, AlertTriangle, ArrowRight, RefreshCw, Eye, Check, ShieldAlert, Layers, Sparkles } from 'lucide-react';
import { toast } from '@vowos/design-system';

interface VendorImportWizardProps {
  onImportComplete: () => void;
}

export default function VendorImportWizard({ onImportComplete }: VendorImportWizardProps) {
  const [step, setStep] = useState<1 | 2 | 3 | 4>(1);
  const [vendorName, setVendorName] = useState('Vow & Velvet');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [filename, setFilename] = useState<string | null>(null);

  // Parsed rows & Column Mappings
  const [parsedRows, setParsedRows] = useState<any[]>([]);
  const [importing, setImporting] = useState(false);

  const handleDownloadTemplate = () => {
    const csvContent = generateVendorTemplateCSV();
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'Proper_Vendor_Catalog_Template.csv';
    a.click();
    toast({ title: 'Template Downloaded', description: 'Saved Proper_Vendor_Catalog_Template.csv to your downloads.' });
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFilename(file.name);
    const reader = new FileReader();
    reader.onload = (event) => {
      const content = event.target?.result as string;
      if (content) {
        // Parse CSV lines
        const lines = content.split('\n').map((l) => l.trim()).filter(Boolean);
        if (lines.length > 1) {
          const headers = lines[0].split(',').map((h) => h.trim().replace(/^"|"$/g, ''));
          const rows = lines.slice(1).map((line) => {
            const values = line.split(',').map((v) => v.trim().replace(/^"|"$/g, ''));
            const rowObj: Record<string, any> = {};
            headers.forEach((h, idx) => {
              rowObj[h] = values[idx] || '';
            });
            return rowObj;
          });
          setParsedRows(rows);
          setStep(2);
        }
      }
    };
    reader.readAsText(file);
  };

  const handleExecuteImport = async (publishImmediate: boolean) => {
    setImporting(true);
    try {
      let importedCount = 0;
      for (const row of parsedRows) {
        const title = row['product_title'] || row['title'] || 'Vendor Item';
        const styleNumber = row['style_number'] || row['style'] || 'STYLE-101';
        const cost = Math.round(parseFloat(row['cost'] || '150') * 100);
        const retail = Math.round(parseFloat(row['retail_price'] || '400') * 100);
        const brQty = parseInt(row['baton_rouge_quantity'] || '2', 10);
        const covQty = parseInt(row['covington_quantity'] || '1', 10);

        const newProd: Omit<CatalogProduct, 'id' | 'createdAt' | 'updatedAt'> = {
          brand: 'Proper & Company',
          vendorId: `v-${Date.now().toString().slice(-3)}`,
          vendorName: row['vendor_name'] || vendorName,
          itemNumber: row['item_number'] || styleNumber,
          styleNumber,
          title,
          description: row['full_description'] || row['short_description'] || 'Vendor catalog import.',
          designer: row['designer'] || vendorName,
          category: row['category'] || 'Little White Dresses',
          purchaseMode: (row['purchase_mode'] as PurchaseMode) || 'buy_online',
          onlineEligible: true,
          publishStatus: publishImmediate ? 'published' : 'draft',
          tags: (row['tags'] || 'Imported').split(';'),
          primaryImageUrl: row['image_url_1'] || 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=600&q=80',
          mediaUrls: [row['image_url_1'] || 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=600&q=80'],
          syncStatus: publishImmediate ? 'synced' : 'draft',
          variants: [
            {
              id: `var-${Date.now().toString().slice(-4)}`,
              productId: '',
              sku: row['sku'] || `${styleNumber}-S`,
              barcode: row['barcode'] || '849102930999',
              color: row['color'] || 'Ivory',
              size: row['size'] || 'Small',
              costCents: cost,
              retailPriceCents: retail,
              inventoryBatonRouge: brQty,
              inventoryCovington: covQty,
              active: true,
            },
          ],
        };

        await addCatalogProduct(newProd);
        importedCount++;
      }

      toast({
        title: 'Catalog Import Completed',
        description: `Successfully imported ${importedCount} product(s) into Proper & Co catalog.`,
      });
      onImportComplete();
    } catch (e: any) {
      toast({ title: 'Import failed', description: e.message || 'Could not process catalog file.', variant: 'destructive' });
    } finally {
      setImporting(false);
    }
  };

  return (
    <div className="space-y-6 select-none max-w-4xl mx-auto">
      {/* Wizard Progress Steps */}
      <div className="flex items-center justify-between border-b border-stone-200 pb-4 text-xs font-semibold">
        <div className={`flex items-center gap-2 ${step >= 1 ? 'text-brand-primary font-bold' : 'text-stone-400'}`}>
          <span className="flex h-6 w-6 items-center justify-center rounded-full bg-brand-soft text-brand-primary text-xs">1</span>
          Select Vendor &amp; File
        </div>
        <div className={`flex items-center gap-2 ${step >= 2 ? 'text-brand-primary font-bold' : 'text-stone-400'}`}>
          <span className="flex h-6 w-6 items-center justify-center rounded-full bg-brand-soft text-brand-primary text-xs">2</span>
          Column Mapping
        </div>
        <div className={`flex items-center gap-2 ${step >= 3 ? 'text-brand-primary font-bold' : 'text-stone-400'}`}>
          <span className="flex h-6 w-6 items-center justify-center rounded-full bg-brand-soft text-brand-primary text-xs">3</span>
          Price &amp; Margin Check
        </div>
        <div className={`flex items-center gap-2 ${step >= 4 ? 'text-brand-primary font-bold' : 'text-stone-400'}`}>
          <span className="flex h-6 w-6 items-center justify-center rounded-full bg-brand-soft text-brand-primary text-xs">4</span>
          Import &amp; Publish
        </div>
      </div>

      {/* STEP 1: Template Download & File Select */}
      {step === 1 && (
        <div className="space-y-6 bg-white p-6 rounded-2xl border border-stone-200 shadow-sm">
          <div className="flex items-center justify-between border-b border-stone-100 pb-4">
            <div>
              <h3 className="font-bold text-stone-900 text-base">Vendor Catalog Import</h3>
              <p className="text-xs text-stone-500 mt-0.5">
                Upload wholesale catalogs in CSV or XLSX format to populate products, prices, and stock for Proper &amp; Co.
              </p>
            </div>
            <button
              onClick={handleDownloadTemplate}
              className="inline-flex items-center gap-2 rounded-xl border border-stone-300 bg-stone-50 px-3.5 py-2 text-xs font-bold text-stone-700 hover:bg-stone-100 transition-colors shadow-2xs"
            >
              <Download className="h-4 w-4 text-brand-primary" /> Download Template CSV
            </button>
          </div>

          <div
            onClick={() => fileInputRef.current?.click()}
            className="flex flex-col items-center justify-center rounded-2xl border-2 border-dashed border-stone-300 bg-stone-50/50 p-10 text-center cursor-pointer hover:border-brand-primary hover:bg-brand-soft/30 transition-all"
          >
            <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-brand-soft text-brand-primary mb-3 shadow-xs">
              <FileSpreadsheet className="h-6 w-6" />
            </div>
            <p className="text-sm font-bold text-stone-800">Click to choose catalog file or drag &amp; drop</p>
            <p className="text-xs text-stone-400 mt-1">Supports CSV, XLSX up to 10MB</p>
            <input
              ref={fileInputRef}
              type="file"
              accept=".csv,.xlsx"
              onChange={handleFileSelect}
              className="hidden"
            />
          </div>
        </div>
      )}

      {/* STEP 2: Column Mapping */}
      {step === 2 && (
        <div className="space-y-6 bg-white p-6 rounded-2xl border border-stone-200 shadow-sm">
          <div className="flex items-center justify-between border-b border-stone-100 pb-4">
            <div>
              <h3 className="font-bold text-stone-900 text-base">Confirm Column Mappings</h3>
              <p className="text-xs text-stone-500">Auto-detected {Object.keys(parsedRows[0] || {}).length} columns from {filename}</p>
            </div>
            <span className="rounded-full bg-emerald-100 px-3 py-1 text-xs font-bold text-emerald-700">100% High Confidence</span>
          </div>

          <div className="grid grid-cols-2 gap-4 text-xs">
            {Object.keys(parsedRows[0] || {}).map((col) => (
              <div key={col} className="flex items-center justify-between rounded-xl border border-stone-200 p-3 bg-stone-50">
                <span className="font-semibold text-stone-800">{col}</span>
                <span className="inline-flex items-center gap-1 font-bold text-status-success">
                  <Check className="h-3.5 w-3.5" /> Mapped
                </span>
              </div>
            ))}
          </div>

          <div className="flex justify-end gap-2 border-t border-stone-100 pt-4">
            <button
              onClick={() => setStep(1)}
              className="rounded-xl border border-stone-300 bg-white px-4 py-2 text-xs font-bold text-stone-700 hover:bg-stone-50"
            >
              Back
            </button>
            <button
              onClick={() => setStep(3)}
              className="inline-flex items-center gap-1.5 rounded-xl bg-brand-primary px-5 py-2 text-xs font-bold text-white shadow-md hover:bg-brand-primary-hover"
            >
              Continue to Price &amp; Margin Check <ArrowRight className="h-4 w-4" />
            </button>
          </div>
        </div>
      )}

      {/* STEP 3: Price & Margin Validation */}
      {step === 3 && (
        <div className="space-y-6 bg-white p-6 rounded-2xl border border-stone-200 shadow-sm">
          <div className="flex items-center justify-between border-b border-stone-100 pb-4">
            <div>
              <h3 className="font-bold text-stone-900 text-base">Price &amp; Margin Validation</h3>
              <p className="text-xs text-stone-500">Checking wholesale costs, retail pricing, and profit margins.</p>
            </div>
            <span className="rounded-full bg-emerald-100 px-3 py-1 text-xs font-bold text-emerald-700">0 Margin Warnings</span>
          </div>

          <div className="space-y-3">
            {parsedRows.map((r, idx) => {
              const cost = parseFloat(r['cost'] || '150');
              const retail = parseFloat(r['retail_price'] || '400');
              const margin = Math.round(((retail - cost) / retail) * 100);

              return (
                <div key={idx} className="flex items-center justify-between rounded-xl border border-stone-200 p-3 text-xs bg-stone-50">
                  <div>
                    <p className="font-bold text-stone-900">{r['product_title'] || 'Item ' + (idx + 1)}</p>
                    <p className="text-[11px] text-stone-400">Style: {r['style_number']} ┬╖ Category: {r['category']}</p>
                  </div>
                  <div className="flex items-center gap-6 text-right">
                    <div>
                      <p className="font-bold text-stone-900">${retail.toFixed(2)}</p>
                      <p className="text-[11px] text-stone-400">Cost: ${cost.toFixed(2)}</p>
                    </div>
                    <span className="rounded-full bg-emerald-100 px-2.5 py-1 text-xs font-bold text-emerald-800">
                      {margin}% Gross Margin
                    </span>
                  </div>
                </div>
              );
            })}
          </div>

          <div className="flex justify-end gap-2 border-t border-stone-100 pt-4">
            <button
              onClick={() => setStep(2)}
              className="rounded-xl border border-stone-300 bg-white px-4 py-2 text-xs font-bold text-stone-700 hover:bg-stone-50"
            >
              Back
            </button>
            <button
              onClick={() => setStep(4)}
              className="inline-flex items-center gap-1.5 rounded-xl bg-brand-primary px-5 py-2 text-xs font-bold text-white shadow-md hover:bg-brand-primary-hover"
            >
              Continue to Preview &amp; Import <ArrowRight className="h-4 w-4" />
            </button>
          </div>
        </div>
      )}

      {/* STEP 4: Import & Publish Actions */}
      {step === 4 && (
        <div className="space-y-6 bg-white p-6 rounded-2xl border border-stone-200 shadow-sm">
          <div className="flex items-center justify-between border-b border-stone-100 pb-4">
            <div>
              <h3 className="font-bold text-stone-900 text-base">Ready to Import Catalog</h3>
              <p className="text-xs text-stone-500">
                {parsedRows.length} product(s) validated and ready for Proper &amp; Co catalog.
              </p>
            </div>
            <span className="rounded-full bg-brand-soft px-3 py-1 text-xs font-bold text-brand-primary-hover">Validated</span>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="rounded-2xl border border-stone-200 bg-stone-50 p-5 space-y-3">
              <h4 className="font-bold text-stone-900 text-sm">Option A: Import as Drafts</h4>
              <p className="text-xs text-stone-500">
                Save products in VowOS as draft catalog records. Review pricing and pictures before publishing to Shopify storefront.
              </p>
              <button
                onClick={() => handleExecuteImport(false)}
                disabled={importing}
                className="w-full rounded-xl border border-stone-300 bg-white py-2.5 text-xs font-bold text-stone-800 shadow-2xs hover:bg-stone-100 transition-colors"
              >
                {importing ? 'Importing...' : 'Import as Draft Products'}
              </button>
            </div>

            <div className="rounded-2xl border border-border-subtle bg-brand-soft/50 p-5 space-y-3">
              <h4 className="font-bold text-brand-secondary text-sm">Option B: Draft &amp; Publish Immediately</h4>
              <p className="text-xs text-stone-600">
                Import into VowOS and immediately synchronize and publish approved products to the Proper &amp; Co Shopify store.
              </p>
              <button
                onClick={() => handleExecuteImport(true)}
                disabled={importing}
                className="w-full rounded-xl bg-brand-primary py-2.5 text-xs font-bold text-white shadow-md hover:bg-brand-primary-hover transition-colors"
              >
                {importing ? 'Publishing...' : 'Import & Publish to Shopify'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import {
  fetchCommerceConnections,
  fetchCatalogProducts,
  fetchCommerceOrders,
  fetchInventoryLevels,
  fetchInventoryMovements,
  fetchCountSessions,
  fetchSyncIssues
} from '../api/properCommerceApi';
import {
  CatalogProduct,
  CommerceConnection,
  CommerceOrder,
  CommerceSyncIssue,
  InventoryCountSession,
  InventoryLevel,
  InventoryMovement
} from '../types/properCommerceTypes';

import OnlineStoreOverview from '../components/OnlineStoreOverview';
import CatalogManager from '../components/CatalogManager';
import VendorImportWizard from '../components/VendorImportWizard';
import InventoryLevelsView from '../components/InventoryLevelsView';
import InventoryCountManager from '../components/InventoryCountManager';
import ShopifyOrdersView from '../components/ShopifyOrdersView';
import CommerceReportsView from '../components/CommerceReportsView';
import CommerceSettingsView from '../components/CommerceSettingsView';
import CommerceSyncDiagnosticsView from '../components/CommerceSyncDiagnosticsView';
import ShopifyConnectModal from '../components/ShopifyConnectModal';
import GoDaddyConnectModal from '../components/GoDaddyConnectModal';
import SquareConnectModal from '../components/SquareConnectModal';

import { PageHeader } from '@/components/vowos/ui';
import { ShoppingBag, Package, Layers, MapPin, ClipboardList, FileText, BarChart3, Settings, AlertCircle, Link2 } from 'lucide-react';

export type ProperCommerceTab =
  | 'overview'
  | 'catalog'
  | 'imports'
  | 'inventory'
  | 'counts'
  | 'orders'
  | 'reports'
  | 'sync-issues'
  | 'settings';

export default function OnlineStorePage() {
  const [tab, setTab] = useState<ProperCommerceTab>('overview');
  const [shopifyModalOpen, setShopifyModalOpen] = useState(false);
  const [godaddyModalOpen, setGoDaddyModalOpen] = useState(false);
  const [squareModalOpen, setSquareModalOpen] = useState(false);

  // Data States
  const [connections, setConnections] = useState<CommerceConnection[] | null>(null);
  const [products, setProducts] = useState<CatalogProduct[]>([]);
  const [orders, setOrders] = useState<CommerceOrder[]>([]);
  const [levels, setLevels] = useState<InventoryLevel[]>([]);
  const [movements, setMovements] = useState<InventoryMovement[]>([]);
  const [sessions, setSessions] = useState<InventoryCountSession[]>([]);
  const [syncIssues, setSyncIssues] = useState<CommerceSyncIssue[]>([]);
  const [loading, setLoading] = useState(true);

  const loadData = async () => {
    setLoading(true);
    try {
      const [conns, prods, ords, lvls, movs, sess, issues] = await Promise.all([
        fetchCommerceConnections(),
        fetchCatalogProducts(),
        fetchCommerceOrders(),
        fetchInventoryLevels(),
        fetchInventoryMovements(),
        fetchCountSessions(),
        fetchSyncIssues(),
      ]);
      setConnections(conns);
      setProducts(prods);
      setOrders(ords);
      setLevels(lvls);
      setMovements(movs);
      setSessions(sess);
      setSyncIssues(issues);
    } catch (e) {
      console.error('Failed to load Proper Commerce data:', e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  if (!connections) return null;

  const tabs: { key: ProperCommerceTab; label: string; icon: any }[] = [
    { key: 'overview', label: 'Overview', icon: ShoppingBag },
    { key: 'catalog', label: 'Catalog', icon: Package },
    { key: 'imports', label: 'Vendor Imports', icon: Layers },
    { key: 'inventory', label: 'Inventory', icon: MapPin },
    { key: 'counts', label: 'Physical Counts', icon: ClipboardList },
    { key: 'orders', label: 'Orders & Fulfillment', icon: FileText },
    { key: 'reports', label: 'Reports', icon: BarChart3 },
    { key: 'sync-issues', label: 'Sync Diagnostics', icon: AlertCircle },
    { key: 'settings', label: 'Settings', icon: Settings },
  ];

  return (
    <div className="space-y-6">
      <PageHeader
        title="Online Store ΓÇö Proper & Co."
        subtitle="Shopify ecommerce product master, vendor catalog imports, location inventory, and order fulfillment."
        action={
          <button
            onClick={() => setTab('settings')}
            className="inline-flex items-center gap-2 rounded-xl bg-stone-900 px-4 py-2 text-xs font-bold text-white shadow-md hover:bg-stone-800 transition-colors"
          >
            <Link2 className="h-4 w-4 text-brand-primary" /> Manage Integrations
          </button>
        }
      />

      {/* Internal Navigation Sub-Tabs */}
      <div className="flex border-b border-stone-200 overflow-x-auto gap-2">
        {tabs.map((t) => (
          <button
            key={t.key}
            onClick={() => setTab(t.key)}
            className={`flex items-center gap-2 whitespace-nowrap border-b-2 px-1 py-4 text-sm font-bold ${
              tab === t.key
                ? 'border-brand-primary text-brand-primary'
                : 'border-transparent text-stone-500 hover:border-stone-300 hover:text-stone-700'
            }`}
          >
            <t.icon className={`h-4 w-4 ${t.key === 'sync-issues' && syncIssues.length > 0 && tab !== 'sync-issues' ? 'text-rose-500' : ''}`} />
            {t.label}
            {t.key === 'sync-issues' && syncIssues.length > 0 && (
              <span className="ml-1 rounded-full bg-rose-100 px-2 py-0.5 text-[10px] text-rose-700">
                {syncIssues.length}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* Sub-Tab Contents */}
      {tab === 'overview' && (
        <OnlineStoreOverview
          connections={connections}
          products={products}
          orders={orders}
          syncIssues={syncIssues}
          onOpenConnectModal={() => setShopifyModalOpen(true)}
          onNavigateTab={(t) => setTab(t as ProperCommerceTab)}
        />
      )}

      {tab === 'catalog' && <CatalogManager products={products} movements={movements} onUpdate={loadData} />}

      {tab === 'imports' && (
        <VendorImportWizard
          onImportComplete={() => {
            loadData();
            setTab('catalog');
          }}
        />
      )}

      {tab === 'inventory' && <InventoryLevelsView levels={levels} movements={movements} products={products} onUpdate={loadData} />}

      {tab === 'counts' && <InventoryCountManager sessions={sessions} onUpdate={loadData} />}

      {tab === 'orders' && <ShopifyOrdersView orders={orders} onUpdate={loadData} />}

      {tab === 'reports' && <CommerceReportsView products={products} orders={orders} />}

      {tab === 'sync-issues' && <CommerceSyncDiagnosticsView issues={syncIssues} onRefresh={loadData} />}

      {tab === 'settings' && (
        <CommerceSettingsView 
          connections={connections} 
          onOpenShopifyModal={() => setShopifyModalOpen(true)} 
          onOpenGoDaddyModal={() => setGoDaddyModalOpen(true)} 
          onOpenSquareModal={() => setSquareModalOpen(true)}
        />
      )}

      {/* Connect Modals */}
      <ShopifyConnectModal
        open={shopifyModalOpen}
        onClose={() => setShopifyModalOpen(false)}
        connection={connections.find(c => c.provider === 'shopify')}
        onUpdate={loadData}
      />
      
      <GoDaddyConnectModal
        open={godaddyModalOpen}
        onClose={() => setGoDaddyModalOpen(false)}
        connection={connections.find(c => c.provider === 'godaddy')}
        onUpdate={loadData}
      />

      <SquareConnectModal
        open={squareModalOpen}
        onClose={() => setSquareModalOpen(false)}
        connection={connections.find(c => c.provider === 'square')}
        onUpdate={loadData}
      />
    </div>
  );
}

