        pauseTour,
        resumeTour,
        stopTour,
        stopScenario,
        nextStep,
        prevStep,
        toggleMute,
        setSpeed,
        resetDemoSession,
      }}
    >
      {children}
    </DemoContext.Provider>
  );
};

