/** Is this Stripe card brand an American Express card? */
export function isAmexBrand(brand: string | null | undefined): boolean {
  const b = (brand ?? '').toLowerCase();
  return b === 'amex' || b === 'american express';
}

/** Surcharge percent that applies to a detected card brand. */
export function surchargePctFor(brand: string | null | undefined, s: SurchargeSettings): number {
  if (!s.enabled) return 0;
  return isAmexBrand(brand) ? s.amexPct : s.creditPct;
}

/** Surcharge in cents for a base amount + detected brand. */
export function surchargeCentsFor(baseCents: number, brand: string | null | undefined, s: SurchargeSettings): number {
  return Math.round((baseCents * surchargePctFor(brand, s)) / 100);
}

/** Friendly display name for a Stripe card brand id. */
export function cardBrandLabel(brand: string | null | undefined): string {
  const map: Record<string, string> = {
    visa: 'Visa',
    mastercard: 'Mastercard',
    amex: 'American Express',
    discover: 'Discover',
    diners: 'Diners Club',
    jcb: 'JCB',
    unionpay: 'UnionPay',
  };
  return map[(brand ?? '').toLowerCase()] ?? 'card';
}

import { supabase } from '@/lib/supabase';

// ΓöÇΓöÇΓöÇ Staff shift scheduling: weekly working hours + time-off/vacation ranges ΓöÇΓöÇΓöÇ
// Both live in the `staff_schedules` table, discriminated by `kind`.

export const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'] as const;
export const WEEKDAY_SHORT = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'] as const;

/** Default salon shift when a team member hasn't been scheduled yet: 9:00 AM ΓÇô 5:30 PM. */
export const DEFAULT_START_MINUTES = 9 * 60;
export const DEFAULT_END_MINUTES = 17 * 60 + 30;

export const TIME_OFF_REASONS = ['Day off', 'Vacation', 'Sick', 'Personal', 'Training'] as const;

/** One weekday rule for one team member (kind='shift'). */
export interface ShiftRule {
  id: string;
  staffName: string;
  weekday: number; // 0=Sunday ΓÇª 6=Saturday
  isWorking: boolean;
  startMinutes: number;
  endMinutes: number;
}

/** One day-off / vacation range for one team member (kind='time_off'). */
export interface TimeOffEntry {
  id: string;
  staffName: string;
  offStart: string; // ISO date (inclusive)
  offEnd: string; // ISO date (inclusive)
  reason: string;
}

export interface ScheduleData {
  shifts: ShiftRule[];
  timeOff: TimeOffEntry[];
}

/** Parse "1:30 PM" style times into minutes since midnight (0 when unparseable). */
export function timeToMinutes(t: string): number {
  const m = /^(\d{1,2}):(\d{2})\s*(AM|PM)$/i.exec(t.trim());
  if (!m) return 0;
  let h = parseInt(m[1], 10) % 12;
  if (m[3].toUpperCase() === 'PM') h += 12;
  return h * 60 + parseInt(m[2], 10);
}

/** Format minutes-since-midnight back into "1:30 PM" style labels. */
export function minutesToLabel(mins: number): string {
  const h24 = Math.floor(mins / 60);
  const mm = String(mins % 60).padStart(2, '0');
  const ampm = h24 >= 12 ? 'PM' : 'AM';
  const h12 = h24 % 12 === 0 ? 12 : h24 % 12;
  return `${h12}:${mm} ${ampm}`;
}

/** Compact "9ΓÇô5:30" style shift label for tight calendar cells. */
export function shiftShortLabel(startMinutes: number, endMinutes: number): string {
  const short = (mins: number) => {
    const h24 = Math.floor(mins / 60);
    const h12 = h24 % 12 === 0 ? 12 : h24 % 12;
    const mm = mins % 60;
    return mm === 0 ? `${h12}` : `${h12}:${String(mm).padStart(2, '0')}`;
  };
  return `${short(startMinutes)}ΓÇô${short(endMinutes)}`;
}

/** Selectable shift boundary times: 7:00 AM ΓÇô 9:00 PM in 30-minute steps. */
export const SHIFT_TIME_OPTIONS: { minutes: number; label: string }[] = (() => {
  const opts: { minutes: number; label: string }[] = [];
  for (let m = 7 * 60; m <= 21 * 60; m += 30) opts.push({ minutes: m, label: minutesToLabel(m) });
  return opts;
})();

// ΓöÇΓöÇΓöÇ Data access ΓöÇΓöÇΓöÇ

export async function fetchSchedules(): Promise<ScheduleData> {
  const { data, error } = await supabase.from('staff_schedules').select('*');
  if (error || !data) return { shifts: [], timeOff: [] };
  const shifts: ShiftRule[] = [];
  const timeOff: TimeOffEntry[] = [];
  data.forEach((r: any) => {
    if (r.kind === 'shift' && r.weekday !== null) {
      shifts.push({
        id: r.id,
        staffName: r.staff_name,
        weekday: r.weekday,
        isWorking: r.is_working ?? true,
        startMinutes: r.start_minutes ?? DEFAULT_START_MINUTES,
        endMinutes: r.end_minutes ?? DEFAULT_END_MINUTES,
      });
    } else if (r.kind === 'time_off' && r.off_start) {
      timeOff.push({
        id: r.id,
        staffName: r.staff_name,
        offStart: String(r.off_start).slice(0, 10),
        offEnd: String(r.off_end ?? r.off_start).slice(0, 10),
        reason: r.reason || 'Day off',
      });
    }
  });
  timeOff.sort((a, b) => a.offStart.localeCompare(b.offStart));
  return { shifts, timeOff };
}

/** Replace one team member's full weekly shift pattern (7 rows) in one shot. */
export async function saveWeekShifts(
  staffName: string,
  week: { weekday: number; isWorking: boolean; startMinutes: number; endMinutes: number }[],
): Promise<string | null> {
  const { error: delErr } = await supabase
    .from('staff_schedules')
    .delete()
    .eq('staff_name', staffName)
    .eq('kind', 'shift');
  if (delErr) return delErr.message;
  const { error } = await supabase.from('staff_schedules').insert(
    week.map((w) => ({
      staff_name: staffName,
      kind: 'shift',
      weekday: w.weekday,
      is_working: w.isWorking,
      start_minutes: w.startMinutes,
      end_minutes: w.endMinutes,
    })),
  );
  return error ? error.message : null;
}

export async function addTimeOff(
  staffName: string,
  offStart: string,
  offEnd: string,
  reason: string,
): Promise<string | null> {
  const { error } = await supabase.from('staff_schedules').insert({
    staff_name: staffName,
    kind: 'time_off',
    off_start: offStart,
    off_end: offEnd < offStart ? offStart : offEnd,
    reason,
  });
  return error ? error.message : null;
}

export async function removeTimeOff(id: string): Promise<string | null> {
  const { error } = await supabase.from('staff_schedules').delete().eq('id', id);
  return error ? error.message : null;
}

// ΓöÇΓöÇΓöÇ Calendar helpers ΓöÇΓöÇΓöÇ

export type DayDuty =
  | { status: 'on'; startMinutes: number; endMinutes: number; scheduled: boolean }
  | { status: 'off' }
  | { status: 'time_off'; reason: string };

/** Weekday index (0=Sun) for an ISO date, immune to timezone drift. */
export function weekdayOfIso(isoDate: string): number {
  const [y, m, d] = isoDate.split('-').map((n) => parseInt(n, 10));
  return new Date(y, m - 1, d).getDay();
}

/**
 * Resolve one team member's duty for one calendar day.
 * Time off beats the weekly pattern; members with no rules yet count as
 * on duty for default salon hours (so an empty schedule doesn't shade everyone).
 */
export function dutyFor(data: ScheduleData, staffName: string, isoDate: string): DayDuty {
  const off = data.timeOff.find(
    (t) => t.staffName === staffName && isoDate >= t.offStart && isoDate <= t.offEnd,
  );
  if (off) return { status: 'time_off', reason: off.reason };
  const weekday = weekdayOfIso(isoDate);
  const rule = data.shifts.find((s) => s.staffName === staffName && s.weekday === weekday);
  if (!rule) {
    return {
      status: 'on',
      startMinutes: DEFAULT_START_MINUTES,
      endMinutes: DEFAULT_END_MINUTES,
      scheduled: false,
    };
  }
  if (!rule.isWorking) return { status: 'off' };
  return { status: 'on', startMinutes: rule.startMinutes, endMinutes: rule.endMinutes, scheduled: true };
}

/** True when an appointment time falls outside the member's shift for that day. */
export function apptOutsideShift(duty: DayDuty, apptTime: string): boolean {
  if (duty.status !== 'on') return true;
  if (!duty.scheduled) return false; // no explicit schedule yet ΓÇö don't nag
  const mins = timeToMinutes(apptTime);
  return mins < duty.startMinutes || mins >= duty.endMinutes;
}

export interface EligibilityResult {
  employeeId: string;
  eligible: boolean;
  reasonCode: 'ELIGIBLE' | 'INACTIVE' | 'WRONG_LOCATION' | 'NOT_SCHEDULED' | 'BREAK_CONFLICT' | 'TIME_OFF_CONFLICT' | 'APPOINTMENT_CONFLICT' | 'HOLD_CONFLICT' | 'MISSING_SKILL' | 'ROOM_UNAVAILABLE';
  explanation: string;
}

export interface TimeRange {
  start: Date;
  end: Date;
}

const doRangesOverlap = (r1: TimeRange, r2: TimeRange) => {
  return r1.start < r2.end && r1.end > r2.start;
};

export class EmployeeEligibilityEngine {
  static checkEligibility(
    employee: any,
    request: any,
    requestTime: TimeRange,
    schedules: any[],
    appointments: any[],
    holds: any[],
    timeOffs: any[],
    service: any,
    rooms: any[]
  ): EligibilityResult {
    // 1. Inactive
    if (employee.status === 'inactive') {
      return { employeeId: employee.id, eligible: false, reasonCode: 'INACTIVE', explanation: 'Employee is inactive.' };
    }

    // 2. Wrong business/location
    const employeeBusinessId = employee.business_id || employee.membership?.business_id || employee.membership_business_id;
    if (employeeBusinessId && employeeBusinessId !== request.business_id) {
      return { employeeId: employee.id, eligible: false, reasonCode: 'WRONG_LOCATION', explanation: 'Employee is not assigned to this business.' };
    }
    
    if (request.preferred_location_id) {
      const locationSchedules = employeeSchedules.filter(s => s.location_id === request.preferred_location_id);
      const worksAtLocation = locationSchedules.length > 0 || (employee.locations && employee.locations.includes(request.preferred_location_id));
      if (employeeSchedules.length > 0 && !worksAtLocation) {
        return { employeeId: employee.id, eligible: false, reasonCode: 'WRONG_LOCATION', explanation: 'Employee is not scheduled at the requested location.' };
      }
    }

    // 3. Not scheduled
    const employeeSchedules = schedules.filter(s => s.employee_id === employee.id);
    const isScheduled = employeeSchedules.some(s => {
      const sStart = new Date(s.start_time || s.start_at);
      const sEnd = new Date(s.end_time || s.end_at);
      return sStart <= requestTime.start && sEnd >= requestTime.end;
    });
    if (employeeSchedules.length > 0 && !isScheduled) { // If they have schedules, they must be scheduled
       return { employeeId: employee.id, eligible: false, reasonCode: 'NOT_SCHEDULED', explanation: 'Employee is not scheduled for the requested time.' };
    }

    // 4. Break conflict
    const hasBreakConflict = employeeSchedules.some(s => {
      if (!s.breaks) return false;
      return s.breaks.some((b: any) => {
        const bStart = new Date(b.start_time);
        const bEnd = new Date(b.end_time);
        return doRangesOverlap(requestTime, { start: bStart, end: bEnd });
      });
    });
    if (hasBreakConflict) {
      return { employeeId: employee.id, eligible: false, reasonCode: 'BREAK_CONFLICT', explanation: 'Conflict with scheduled break.' };
    }

    // 5. Time-off conflict
    const hasTimeOff = timeOffs.some(t => {
      if (t.employee_id !== employee.id || t.status !== 'approved') return false;
      const tStart = new Date(t.start_time || t.start_date);
      const tEnd = new Date(t.end_time || t.end_date);
      return doRangesOverlap(requestTime, { start: tStart, end: tEnd });
    });
    if (hasTimeOff) {
      return { employeeId: employee.id, eligible: false, reasonCode: 'TIME_OFF_CONFLICT', explanation: 'Employee has approved time off.' };
    }

    // 6. Appointment conflict
    const hasAppt = appointments.some(a => {
      if (a.employee_id !== employee.id) return false;
      if (a.status === 'cancelled' || a.status === 'no_show') return false;
      const aStart = new Date(a.start_time || a.start_at);
      const aEnd = new Date(a.end_time || a.end_at);
      return doRangesOverlap(requestTime, { start: aStart, end: aEnd });
    });
    if (hasAppt) {
      return { employeeId: employee.id, eligible: false, reasonCode: 'APPOINTMENT_CONFLICT', explanation: 'Employee already has an appointment.' };
    }

    // 7. Tentative-hold conflict
    const hasHold = holds.some(h => {
      if (h.employee_id !== employee.id) return false;
      if (new Date(h.expires_at) < new Date()) return false;
      const hStart = new Date(h.start_time || h.start_at);
      const hEnd = new Date(h.end_time || h.end_at);
      return doRangesOverlap(requestTime, { start: hStart, end: hEnd });
    });
    if (hasHold) {
      return { employeeId: employee.id, eligible: false, reasonCode: 'HOLD_CONFLICT', explanation: 'Employee has a tentative hold.' };
    }

    // 8. Missing service skill/role
    if (service && employee.skills) {
      const hasSkill = Array.isArray(employee.skills) && (employee.skills.includes(service.id) || employee.skills.includes(service.name));
      if (!hasSkill && service.required_role && employee.role !== service.required_role) {
         return { employeeId: employee.id, eligible: false, reasonCode: 'MISSING_SKILL', explanation: 'Employee lacks the required skill or role.' };
      }
    }

    // 9. Room/resource unavailable (handled outside or check if room overlaps)
    // If request requires a room, and all valid rooms are booked, this could be handled here or in room engine.
    // Assuming we pass in available rooms, if empty:
    if (service?.requires_room && rooms.length === 0) {
      return { employeeId: employee.id, eligible: false, reasonCode: 'ROOM_UNAVAILABLE', explanation: 'No rooms available.' };
    }

    return { employeeId: employee.id, eligible: true, reasonCode: 'ELIGIBLE', explanation: 'Employee is eligible.' };
  }
}

import { supabase } from '@/lib/supabase';
import { Database } from '@/types/supabase';
import { toast } from '@vowos/design-system';

export type ActionStatus = 'Open' | 'In Progress' | 'Waiting' | 'Pending Approval' | 'Approved' | 'Rejected' | 'Snoozed' | 'Completed' | 'Dismissed' | 'Superseded' | 'Failed';
export type ActionPriority = 'Critical' | 'High' | 'Medium' | 'Low';

export interface ActionCenterRecord {
  id: string;
  data_plane: string;
  business_id: string;
  location_id: string | null;
  action_type: string;
  source_module: string;
  source_record_type: string;
  source_record_id: string;
  title: string;
  description: string | null;
  status: ActionStatus;
  priority: ActionPriority;
  severity: string | null;
  assigned_user_id: string | null;
  assigned_role: string | null;
  due_at: string | null;
  created_at: string;
  updated_at: string;
  completed_at: string | null;
  dismissed_at: string | null;
  snoozed_until: string | null;
  financial_impact_cents: number | null;
  operational_impact: string | null;
  customer_impact: string | null;
  ai_generated: boolean;
  ai_confidence: number | null;
  requires_approval: boolean;
  approval_type: string | null;
  deep_link: string;
  metadata_json: Record<string, any>;
  version: number;
}

export async function fetchActions(businessId: string, locationId?: string | 'all', filters?: any): Promise<ActionCenterRecord[]> {
  try {
    let query = supabase
      .from('action_center_records')
      .select('*')
      .eq('business_id', businessId)
      .neq('status', 'Completed')
      .neq('status', 'Dismissed')
      .neq('status', 'Superseded')
      .neq('status', 'Failed')
      .order('priority', { ascending: true }) // Assuming string sorting or custom sorting later
      .order('due_at', { ascending: true, nullsFirst: false });

    if (locationId && locationId !== 'all') {
      query = query.eq('location_id', locationId);
    }

    if (filters?.assignedToMe && filters.userId) {
      query = query.eq('assigned_user_id', filters.userId);
    }

    if (filters?.status) {
      query = query.eq('status', filters.status);
    }

    const { data, error } = await query;
    if (error) throw error;
    
    // Manual sorting to ensure priority order: Critical -> High -> Medium -> Low
    const priorityOrder = { 'Critical': 0, 'High': 1, 'Medium': 2, 'Low': 3 };
    return (data || []).sort((a, b) => {
      const pA = priorityOrder[a.priority as keyof typeof priorityOrder] ?? 99;
      const pB = priorityOrder[b.priority as keyof typeof priorityOrder] ?? 99;
      if (pA !== pB) return pA - pB;
      if (a.due_at && b.due_at) return new Date(a.due_at).getTime() - new Date(b.due_at).getTime();
      return 0;
    }) as ActionCenterRecord[];
  } catch (error) {
    console.error('Error fetching actions:', error);
    toast({
      title: 'Attention Engine Error',
      description: 'Failed to load action items. The operational summary could not be retrieved.',
      variant: 'destructive'
    });
    throw error;
  }
}

export async function updateActionStatus(actionId: string, status: ActionStatus, metadata?: any) {
  try {
    const updateData: any = { status, updated_at: new Date().toISOString() };
    if (status === 'Completed') updateData.completed_at = new Date().toISOString();
    if (status === 'Dismissed') updateData.dismissed_at = new Date().toISOString();
    if (metadata) {
      updateData.metadata_json = metadata;
    }

    const { error } = await supabase
      .from('action_center_records')
      .update(updateData)
      .eq('id', actionId);
      
    if (error) throw error;
    return true;
  } catch (error) {
    console.error('Error updating action:', error);
    toast({
      title: 'Failed to update action',
      variant: 'destructive'
    });
    return false;
  }
}

export async function assignAction(actionId: string, userId: string | null) {
  try {
    const { error } = await supabase
      .from('action_center_records')
      .update({ assigned_user_id: userId, updated_at: new Date().toISOString() })
      .eq('id', actionId);
      
    if (error) throw error;
    return true;
  } catch (error) {
    console.error('Error assigning action:', error);
    toast({
      title: 'Failed to assign action',
      variant: 'destructive'
    });
    return false;
  }
}

import { supabase } from '../supabase';
import { useQuery } from '@tanstack/react-query';

export interface CapacityMetrics {
  scheduledEmployees: number;
  eligibleEmployees: number;
  bookableHours: number;
  confirmedHours: number;
  heldHours: number;
  openRequests: number;
  staffingGap: number;
}

export const calculateCapacityMetrics = (
  schedules: any[],
  appointments: any[],
  holds: any[],
  requests: any[],
  staff: any[]
): CapacityMetrics => {
  // 1. Scheduled employees today
  const scheduledStaffIds = new Set(schedules.map(s => s.employee_id));
  const scheduledEmployees = scheduledStaffIds.size;

  // 2. Eligible employees (active and available)
  const eligibleEmployees = staff.filter(s => s.status === 'active').length;

  // 3. Bookable hours (sum of scheduled hours)
  let bookableHours = 0;
  schedules.forEach(s => {
    const start = new Date(s.start_time || s.start_at);
    const end = new Date(s.end_time || s.end_at);
    if (!isNaN(start.getTime()) && !isNaN(end.getTime())) {
      bookableHours += (end.getTime() - start.getTime()) / (1000 * 60 * 60);
    }
  });

  // 4. Confirmed hours
  let confirmedHours = 0;
  appointments.forEach(a => {
    if (a.status !== 'cancelled' && a.status !== 'no_show') {
      const start = new Date(a.start_time || a.start_at);
      const end = new Date(a.end_time || a.end_at);
      if (!isNaN(start.getTime()) && !isNaN(end.getTime())) {
        confirmedHours += (end.getTime() - start.getTime()) / (1000 * 60 * 60);
      }
    }
  });

  // 5. Held hours
  let heldHours = 0;
  holds.forEach(h => {
    if (new Date(h.expires_at) >= new Date()) {
      const start = new Date(h.start_time || h.start_at);
      const end = new Date(h.end_time || h.end_at);
      if (!isNaN(start.getTime()) && !isNaN(end.getTime())) {
        heldHours += (end.getTime() - start.getTime()) / (1000 * 60 * 60);
      }
    }
  });

  // 6. Open requests
  const openRequests = requests.filter(r => r.status === 'pending' || r.status === 'open').length;

  // 7. Staffing gap
  // Gap = (Confirmed + Held + estimated open request hours) - Bookable
  // For simplicity, estimate 1 hour per open request
  const demandHours = confirmedHours + heldHours + openRequests;
  const staffingGap = Math.max(0, demandHours - bookableHours);

  return {
    scheduledEmployees,
    eligibleEmployees,
    bookableHours,
    confirmedHours,
    heldHours,
    openRequests,
    staffingGap
  };
};

export const fetchCapacityMetrics = async (businessId: string, date: string): Promise<CapacityMetrics> => {
  // Fetch for a specific date (simplified for real implementation)
  const startOfDay = new Date(date);
  startOfDay.setHours(0, 0, 0, 0);
  const endOfDay = new Date(date);
  endOfDay.setHours(23, 59, 59, 999);

  const [
    { data: schedules },
    { data: appointments },
    { data: holds },
    { data: requests },
    { data: staff }
  ] = await Promise.all([
    supabase.from('employee_schedules').select('*').eq('business_id', businessId).gte('start_time', startOfDay.toISOString()).lte('start_time', endOfDay.toISOString()),
    supabase.from('appointments').select('*').eq('business_id', businessId).gte('start_time', startOfDay.toISOString()).lte('start_time', endOfDay.toISOString()),
    supabase.from('appointment_holds').select('*').eq('business_id', businessId).gte('start_time', startOfDay.toISOString()).lte('start_time', endOfDay.toISOString()),
    supabase.from('appointment_requests').select('*').eq('business_id', businessId).in('status', ['pending', 'open']),
    supabase.from('staff_profiles').select('*').eq('business_id', businessId)
  ]);

  return calculateCapacityMetrics(schedules || [], appointments || [], holds || [], requests || [], staff || []);
};

export const useCapacityMetrics = (businessId: string | undefined, date: string) => {
  return useQuery({
    queryKey: ['capacity_metrics', businessId, date],
    queryFn: () => fetchCapacityMetrics(businessId!, date),
    enabled: !!businessId && !!date
  });
};

import Papa from 'papaparse';
import { supabase } from '../supabase';
import { ImportJob, ImportStagingRecord } from '../../types/catalog';

export interface FieldMapping {
  csvHeader: string;
  mappedField: string; // 'style_number', 'color', 'size', 'cost_cents', 'retail_cents'
}

export const importEngine = {
  async parseCSV(file: File): Promise<any[]> {
    return new Promise((resolve, reject) => {
      Papa.parse(file, {
        header: true,
        skipEmptyLines: true,
        complete: (results) => {
          resolve(results.data);
        },
        error: (error: any) => {
          reject(error);
        }
      });
    });
  },

  async startImportJob(businessId: string, vendorId: string, fileName: string): Promise<ImportJob> {
    const { data, error } = await supabase
      .from('import_jobs')
      .insert({
        business_id: businessId,
        vendor_id: vendorId,
        file_name: fileName,
        status: 'Mapping'
      })
      .select()
      .single();
    
    if (error) throw error;
    return data as ImportJob;
  },

  async commitImport(businessId: string, vendorId: string, jobId: string, rawData: any[], mapping: FieldMapping[]): Promise<void> {
    // Basic mapping implementation
    const records = rawData.map(row => {
      const mapped: any = {};
      mapping.forEach(m => {
        if (m.mappedField && m.mappedField !== 'ignore') {
          mapped[m.mappedField] = row[m.csvHeader];
        }
      });
      return mapped;
    });

    // In a real scenario, we'd insert into import_staging_records here,
    // then process them. For simplicity, we process them directly into products/variants.

    // Group by style number
    const productsMap = new Map<string, any[]>();
    records.forEach(r => {
      const style = r.style_number;
      if (!style) return;
      if (!productsMap.has(style)) {
        productsMap.set(style, []);
      }
      productsMap.get(style)!.push(r);
    });

    for (const [style, variants] of productsMap.entries()) {
      // Create or update product
      const { data: productData, error: productError } = await supabase
        .from('products')
        .select('id')
        .eq('business_id', businessId)
        .eq('vendor_id', vendorId)
        .eq('style_number', style)
        .single();
      
      let productId = productData?.id;

      if (!productId) {
        const { data: newProd, error: insertProdError } = await supabase
          .from('products')
          .insert({
            business_id: businessId,
            vendor_id: vendorId,
            style_number: style,
            name: variants[0].name || `Style ${style}`,
          })
          .select()
          .single();
        if (insertProdError) throw insertProdError;
        productId = newProd.id;
      }

      // Create variants
      for (const v of variants) {
        const { data: existingVariant } = await supabase
          .from('product_variants')
          .select('id')
          .eq('product_id', productId)
          .eq('color', v.color || '')
          .eq('size', v.size || '')
          .single();

        if (!existingVariant) {
          const cost = parseFloat(v.cost_cents?.toString() || '0') || 0;
          const retail = parseFloat(v.retail_cents?.toString() || '0') || 0;

          await supabase.from('product_variants').insert({
            business_id: businessId,
            product_id: productId,
            color: v.color || '',
            size: v.size || '',
            cost_cents: cost,
            store_retail_cents: retail
          });
        }
      }
    }

    await supabase
      .from('import_jobs')
      .update({ status: 'Completed', completed_at: new Date().toISOString() })
      .eq('id', jobId);
  }
};

import { supabase } from '../supabase';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { assertEntitlement } from './entitlementService';

export interface ActiveBusinessContext {
  businessId: string | undefined;
  business: any | undefined;
  locationId: string | undefined;
  locationScope: string;
  authorizedLocations: any[];
  role: string | undefined;
  permissions: string[];
  dataPlane: 'production' | 'demo';
  loading: boolean;
  error: any;
}

export const useActiveBusinessContext = (locationFilter?: string): ActiveBusinessContext => {
  const { data: authUser } = useQuery({
    queryKey: ['authUserSession'],
    queryFn: async () => {
      const { data: { session } } = await supabase.auth.getSession();
      return session?.user || null;
    }
  });

  const userId = authUser?.id;

  const contextQuery = useQuery({
    queryKey: ['activeBusinessContext', userId],
    queryFn: async () => {
      try {
        if (!userId) return null;
        
        const { data: memberships, error: memError } = await supabase
          .from('business_memberships')
          .select('*, business:businesses(*)')
          .eq('user_id', userId);
          
        if (memError) {
          console.error("[activeBusinessContext] membership query error:", memError);
          throw memError;
        }
        
        console.log("[activeBusinessContext] memberships found:", JSON.stringify(memberships));
          
        if (!memberships || memberships.length === 0) return null;
        
        const primaryMembership = memberships[0];
        const business = primaryMembership.business;
        if (!business) {
          console.error("[activeBusinessContext] primaryMembership.business is null/undefined:", JSON.stringify(primaryMembership));
          throw new Error("[activeBusinessContext] primaryMembership.business is null/undefined");
        }
        const businessId = business.id;
        const role = primaryMembership.role;

        const { data: allLocations, error: locError } = await supabase
          .from('locations')
          .select('*')
          .eq('business_id', businessId);
          
        if (locError) {
          console.error("[activeBusinessContext] locations query error:", locError);
          throw locError;
        }
        
        let authorizedLocations = allLocations || [];
        if (role !== 'Owner' && role !== 'Manager') {
          const { data: permissions } = await supabase
            .from('location_permissions')
            .select('location_id')
            .eq('membership_id', primaryMembership.id);
          const allowedIds = new Set(permissions?.map((p: any) => p.location_id) || []);
          authorizedLocations = (allLocations || []).filter((loc: any) => allowedIds.has(loc.id));
        }

        const dataPlane = authUser?.email === 'demo123@gmail.com' ? 'demo' : 'production';

        return {
          businessId,
          business,
          authorizedLocations,
          role,
          permissions: [] as string[],
          dataPlane
        };
      } catch (err: any) {
        console.error("[activeBusinessContext] Caught error:", err.message || err);
        throw err;
      }
    },
    enabled: !!userId
  });

  const context = contextQuery.data;
  
  let locationScope = locationFilter || 'all';
  let locationId: string | undefined = undefined;

  if (context) {
    if (locationScope === 'all') {
      locationId = context.authorizedLocations[0]?.id;
    } else {
      const isAuth = context.authorizedLocations.some((loc: any) => loc.id === locationScope);
      if (isAuth) {
        locationId = locationScope;
      } else {
        locationId = context.authorizedLocations[0]?.id;
        locationScope = locationId || 'all';
      }
    }
  }

  return {
    businessId: context?.businessId,
    business: context?.business,
    locationId,
    locationScope,
    authorizedLocations: context?.authorizedLocations || [],
    role: context?.role,
    permissions: context?.permissions || [],
    dataPlane: context?.dataPlane || 'production',
    loading: contextQuery.isLoading,
    error: contextQuery.error
  };
};

