// ΓöÇΓöÇΓöÇ Scoped Configuration Architecture ΓöÇΓöÇΓöÇ

export interface SettingsContext {
  dataPlane: 'production' | 'demo';
  businessId?: string;
  locationId?: string;
  userId?: string;
  effectiveDate?: string;
}

export interface EffectiveSettingResult<T> {
  value: T;
  sourceScope: 'platform' | 'business' | 'location' | 'user' | 'default';
  isDefault: boolean;
  isOverride: boolean;
  version: number;
  updatedAt?: string;
}

export async function resolveEffectiveSetting<T>(
  namespace: string,
  key: string,
  context: SettingsContext,
  defaultValue: T
): Promise<EffectiveSettingResult<T>> {
  try {
    let businessId = context.businessId;
    let userId = context.userId;

    // Automatically resolve userId if not provided
    if (!userId) {
      const { data: { user } } = await supabase.auth.getUser();
      userId = user?.id;
    }

    // Automatically resolve businessId from memberships if not provided
    if (!businessId && userId) {
      const { data: membership } = await supabase
        .from('business_memberships')
        .select('business_id')
        .eq('user_id', userId)
        .maybeSingle();
      if (membership) {
        businessId = membership.business_id;
      } else {
        // Fallback for demo environments if no membership exists
        const { data: defaultBusiness } = await supabase.from('businesses').select('id').limit(1).maybeSingle();
        if (defaultBusiness) businessId = defaultBusiness.id;
      }
    }

    const { data, error } = await supabase
      .from('settings_values')
      .select('*')
      .eq('setting_namespace', namespace)
      .eq('setting_key', key)
      .eq('data_plane', context.dataPlane)
      .eq('status', 'active');

    if (error) throw error;
    if (!data || data.length === 0) {
      return {
        value: defaultValue,
        sourceScope: 'default',
        isDefault: true,
        isOverride: false,
        version: 0,
      };
    }

    // Sort by specificity: user -> location -> business -> platform
    let userSetting, locationSetting, businessSetting, platformSetting;

    for (const record of data) {
      if (record.user_id && record.user_id === context.userId) userSetting = record;
      else if (record.location_id && record.location_id === context.locationId) locationSetting = record;
      else if (record.business_id && record.business_id === context.businessId && !record.location_id) businessSetting = record;
      else if (!record.business_id && !record.location_id && !record.user_id) platformSetting = record;
    }

    const effectiveRecord = userSetting || locationSetting || businessSetting || platformSetting;

    if (!effectiveRecord) {
      return {
        value: defaultValue,
        sourceScope: 'default',
        isDefault: true,
        isOverride: false,
        version: 0,
      };
    }

    let sourceScope: 'platform' | 'business' | 'location' | 'user' = 'platform';
    if (effectiveRecord === userSetting) sourceScope = 'user';
    else if (effectiveRecord === locationSetting) sourceScope = 'location';
    else if (effectiveRecord === businessSetting) sourceScope = 'business';

    const isOverride = sourceScope === 'user' || sourceScope === 'location';

    return {
      value: effectiveRecord.value_json as T,
      sourceScope,
      isDefault: false,
      isOverride,
      version: effectiveRecord.version || 1,
      updatedAt: effectiveRecord.updated_at,
    };
  } catch (err) {
    console.error(`Error resolving effective setting ${namespace}:${key}`, err);
    return {
      value: defaultValue,
      sourceScope: 'default',
      isDefault: true,
      isOverride: false,
      version: 0,
    };
  }
}

export async function saveScopedSetting<T>(
  namespace: string,
  key: string,
  value: T,
  context: SettingsContext,
  reason?: string
): Promise<void> {
  try {
    const { data: { user } } = await supabase.auth.getUser();
    const userId = user?.id;

    let businessId = context.businessId;
    if (!businessId && userId) {
      const { data: membership } = await supabase
        .from('business_memberships')
        .select('business_id')
        .eq('user_id', userId)
        .maybeSingle();
      if (membership) {
        businessId = membership.business_id;
      } else {
        const { data: defaultBusiness } = await supabase.from('businesses').select('id').limit(1).maybeSingle();
        if (defaultBusiness) businessId = defaultBusiness.id;
      }
    }

    const matchQuery = {
      data_plane: context.dataPlane,
      setting_namespace: namespace,
      setting_key: key,
      business_id: businessId || null,
      location_id: context.locationId || null,
      user_id: context.userId || null,
    };

    // 1. Fetch existing to increment version and save history
    const { data: existing } = await supabase
      .from('settings_values')
      .select('id, version, value_json')
      .match(matchQuery)
      .maybeSingle();

    const newVersion = existing ? (existing.version || 1) + 1 : 1;

    // 2. Upsert the value
    const upsertData = {
      ...matchQuery,
      value_json: value,
      version: newVersion,
      updated_at: new Date().toISOString(),
      updated_by: userId,
      ...(existing ? {} : { created_by: userId }),
    };

    const { data: savedValue, error } = await supabase
      .from('settings_values')
      .upsert(upsertData, { onConflict: 'data_plane, business_id, location_id, user_id, setting_namespace, setting_key' })
      .select('id')
      .single();

    if (error) throw error;

    // 3. Write version history
    if (savedValue) {
      const { error: versionError } = await supabase
        .from('settings_versions')
        .insert({
          setting_value_id: savedValue.id,
          version: newVersion,
          previous_value_json: existing ? existing.value_json : null,
          new_value_json: value,
          change_reason: reason || null,
          changed_by: userId,
        });
        
      if (versionError) {
        console.error('Failed to write settings version history', versionError);
      }
    }
  } catch (err: any) {
    console.error('Failed to save setting to DB, ignoring for demo purposes:', err);
  }
}

import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { demoDb } from './demo/demoDatabase';

let activeClient: SupabaseClient | null = null;
let tenantConfigPromise: Promise<any> | null = null;

const PUBLIC_VOWOS_HOST = 'vowos.bridgebox.ai';
const LOCAL_DEMO_HOSTS = new Set(['localhost', '127.0.0.1', 'vowos.localhost']);
const PUBLIC_DEMO_ROOTS = ['/demo', '/demoapp'] as const;

export function isCanonicalDemoEntry(hostname: string, pathname: string): boolean {
  const normalizedHost = hostname.toLowerCase().split(':')[0];
  const isAllowedHost = normalizedHost === PUBLIC_VOWOS_HOST || LOCAL_DEMO_HOSTS.has(normalizedHost);
  const isDemoPath = PUBLIC_DEMO_ROOTS.some(
    (root) => pathname === root || pathname === `${root}/` || pathname.startsWith(`${root}/`),
  );
  return isAllowedHost && isDemoPath;
}

function currentLocationIsCanonicalDemoEntry(): boolean {
  if (typeof window === 'undefined') return false;
  return isCanonicalDemoEntry(window.location.hostname, window.location.pathname);
}

// Demo state is deliberately tab/runtime scoped, never persisted in localStorage.
// Both /demo (sales/guided entry) and /demoapp (full live sandbox) use the same
// isolated synthetic data plane. Visiting either must never contaminate /platform
// or a real tenant on a later page load.
let demoSessionAuthorized = currentLocationIsCanonicalDemoEntry();
let activeDataPlane: 'production' | 'demo' = demoSessionAuthorized ? 'demo' : 'production';

export function setActiveDataPlane(plane: 'production' | 'demo') {
  if (plane === 'demo') {
    if (!demoSessionAuthorized && !currentLocationIsCanonicalDemoEntry()) {
      throw new Error('Demo data plane can only be entered from the canonical VowOS /demo or /demoapp routes.');
    }
    demoSessionAuthorized = true;
    activeDataPlane = 'demo';
    return;
  }

  activeDataPlane = 'production';
  demoSessionAuthorized = false;
}

export function getActiveDataPlane() {
  return activeDataPlane;
}

export async function initTenantConfig() {
  if (tenantConfigPromise) return tenantConfigPromise;

  const isDemo = getActiveDataPlane() === 'demo';
  tenantConfigPromise = fetch(`/api/tenant-config${isDemo ? '?mode=demo' : ''}`, {
    headers: { 'x-forwarded-host': window.location.hostname },
  })
    .then(async (res) => {
      if (!res.ok) {
        let detail = '';
        try {
          const body = await res.json();
          detail = typeof body?.error === 'string' ? `: ${body.error}` : '';
        } catch {
          // Keep the customer-facing bootstrap error generic when the response is not JSON.
        }
        throw new Error(`Failed to load tenant configuration${detail}`);
      }
      return res.json();
    })
    .then((config) => {
      if (!config?.supabaseUrl || !config?.supabaseAnonKey) {
        throw new Error('Tenant configuration is incomplete.');
      }

      activeClient = createClient(config.supabaseUrl, config.supabaseAnonKey);
      (window as any).__VOWOS_TENANT_CONFIG = config;
      (window as any).__VOWOS_TENANT_CONFIG_ERROR = null;

      if (config.brand?.primary_color) {
        document.documentElement.style.setProperty('--primary', config.brand.primary_color);
      }

      return config;
    })
    .catch((error) => {
      activeClient = null;
      (window as any).__VOWOS_TENANT_CONFIG = null;
      (window as any).__VOWOS_TENANT_CONFIG_ERROR =
        error instanceof Error ? error.message : 'Tenant configuration is unavailable.';
      tenantConfigPromise = null;
      throw error;
    });

  return tenantConfigPromise;
}

export function resetTenantConfigForRetry() {
  tenantConfigPromise = null;
  activeClient = null;
}

function requireActiveClient(): SupabaseClient {
  if (!activeClient) {
    throw new Error('VowOS data plane is unavailable because tenant configuration did not load.');
  }
  return activeClient;
}

function demoFunctionsAdapter() {
  return {
    invoke: async (functionName: string, options?: any) => {
      // No public demo action is allowed to invoke a real external provider or
      // production edge-function mutation. Return realistic, explicit simulated
      // results for common demo actions instead.
      if (functionName === 'generate-note') {
        return {
          data: {
            ok: true,
            demo: true,
            simulated: true,
            text: 'Hi! We would love to help. I reviewed your appointment and preferences, and we have a few great options ready for you. Reply here anytime if you would like us to adjust your visit.',
          },
          error: null,
        };
      }

      if (functionName === 'auto-comms') {
        const digestOnly = options?.body?.task === 'digest';
        return {
          data: {
            ok: true,
            demo: true,
            simulated: true,
            reminders: digestOnly ? 0 : 2,
            chases: digestOnly ? 0 : 1,
            photos: 0,
            digest: digestOnly ? 'sent (simulated)' : 'up to date (simulated)',
          },
          error: null,
        };
      }

      return {
        data: { ok: true, demo: true, simulated: true },
        error: null,
      };
    },
  };
}

function demoStorageAdapter() {
  return {
    from: (_bucket: string) => ({
      upload: async (path: string) => ({ data: { path }, error: null }),
      update: async (path: string) => ({ data: { path }, error: null }),
      remove: async () => ({ data: [], error: null }),
      createSignedUrl: async () => ({ data: { signedUrl: '' }, error: null }),
      getPublicUrl: () => ({ data: { publicUrl: '' } }),
    }),
  };
}

function demoChannelAdapter() {
  const channel: any = {
    on: () => channel,
    subscribe: (callback?: (status: string) => void) => {
      callback?.('SUBSCRIBED');
      return channel;
    },
    unsubscribe: async () => 'ok',
  };
  return channel;
}

// Create a Proxy so existing imports of `supabase` automatically route to the
// correct client while preserving the isolated in-memory demo interceptor.
export const supabase = new Proxy({} as SupabaseClient, {
  get(_target, prop) {
    if (activeDataPlane === 'demo') {
      if (prop === 'from') {
        return (table: string) => demoDb.from(table);
      }
      if (prop === 'functions') {
        return demoFunctionsAdapter();
      }
      if (prop === 'storage') {
        return demoStorageAdapter();
      }
      if (prop === 'rpc') {
        return async () => ({ data: null, error: null });
      }
      if (prop === 'channel') {
        return () => demoChannelAdapter();
      }
      if (prop === 'removeChannel') {
        return async () => 'ok';
      }
      if (prop === 'removeAllChannels') {
        return async () => [];
      }
    }

    const client = requireActiveClient();
    const value = Reflect.get(client, prop, client);
    if (typeof value === 'function') {
      return value.bind(client);
    }
    return value;
  },
});

import { supabase } from '@/lib/supabase';
import { ScheduleData, dutyFor } from '@/lib/schedules';

// ΓöÇΓöÇΓöÇ Time clock: punch in/out records in the `time_entries` table ΓöÇΓöÇΓöÇ

export interface TimeEntry {
  id: string;
  staffName: string;
  clockIn: string; // ISO timestamp
  clockOut: string | null; // ISO timestamp or null while on the clock
  note: string | null;
}

function rowToEntry(r: any): TimeEntry {
  return {
    id: r.id,
    staffName: r.staff_name,
    clockIn: r.clock_in,
    clockOut: r.clock_out ?? null,
    note: r.note ?? null,
  };
}

/** Local ISO date (YYYY-MM-DD) for a Date. */
export const localIsoDate = (d: Date) => {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
};

/** Every ISO date from `fromIso` to `toIso` inclusive (safe-capped at 400 days). */
export function eachIsoDate(fromIso: string, toIso: string): string[] {
  const out: string[] = [];
  const [y, m, d] = fromIso.split('-').map((n) => parseInt(n, 10));
  const cur = new Date(y, m - 1, d);
  for (let i = 0; i < 400; i++) {
    const iso = localIsoDate(cur);
    if (iso > toIso) break;
    out.push(iso);
    cur.setDate(cur.getDate() + 1);
  }
  return out;
}

/** Fetch punches whose clock-in falls inside a local date range (inclusive). */
export async function fetchTimeEntries(fromIso: string, toIso: string): Promise<TimeEntry[]> {
  const start = new Date(`${fromIso}T00:00:00`).toISOString();
  const endDate = new Date(`${toIso}T00:00:00`);
  endDate.setDate(endDate.getDate() + 1);
  const { data, error } = await supabase
    .from('time_entries')
    .select('*')
    .gte('clock_in', start)
    .lt('clock_in', endDate.toISOString())
    .order('clock_in', { ascending: true });
  if (error || !data) return [];
  return data.map(rowToEntry);
}

/** Everyone currently on the clock (no clock-out yet). */
export async function fetchOpenEntries(): Promise<TimeEntry[]> {
  const { data, error } = await supabase
    .from('time_entries')
    .select('*')
    .is('clock_out', null)
    .order('clock_in', { ascending: true });
  if (error || !data) return [];
  return data.map(rowToEntry);
}

export async function clockIn(staffName: string): Promise<string | null> {
  const { error } = await supabase.from('time_entries').insert({ staff_name: staffName });
  return error ? error.message : null;
}

export async function clockOut(entryId: string): Promise<string | null> {
  const { error } = await supabase
    .from('time_entries')
    .update({ clock_out: new Date().toISOString() })
    .eq('id', entryId);
  return error ? error.message : null;
}

export async function deleteTimeEntry(entryId: string): Promise<string | null> {
  const { error } = await supabase.from('time_entries').delete().eq('id', entryId);
  return error ? error.message : null;
}

// ΓöÇΓöÇΓöÇ Hours math ΓöÇΓöÇΓöÇ

/** Hours in one entry; open entries count up to `now`. */
export function entryHours(e: TimeEntry, now: Date = new Date()): number {
  const start = new Date(e.clockIn).getTime();
  const end = e.clockOut ? new Date(e.clockOut).getTime() : now.getTime();
  return Math.max(0, (end - start) / 3_600_000);
}

/** "7h 24m" style label. */
export function fmtHours(h: number): string {
  const totalMin = Math.round(h * 60);
  const hh = Math.floor(totalMin / 60);
  const mm = totalMin % 60;
  if (hh === 0) return `${mm}m`;
  return mm === 0 ? `${hh}h` : `${hh}h ${mm}m`;
}

/** Punches longer than this are almost certainly a forgotten clock-out. */
export const SUSPICIOUS_SHIFT_HOURS = 14;

/**
 * Hours a member is scheduled to work across a date range,
 * derived from their weekly shift pattern minus time off.
 */
export function scheduledHoursForRange(
  data: ScheduleData,
  staffName: string,
  fromIso: string,
  toIso: string,
): number {
  let total = 0;
  for (const iso of eachIsoDate(fromIso, toIso)) {
    const duty = dutyFor(data, staffName, iso);
    if (duty.status === 'on') total += (duty.endMinutes - duty.startMinutes) / 60;
  }
  return total;
}

// ΓöÇΓöÇΓöÇ Staff email directory (for emailing schedules) ΓöÇΓöÇΓöÇ

export async function fetchStaffContacts(): Promise<Record<string, string>> {
  const { data, error } = await supabase.from('staff_contacts').select('staff_name, email');
  if (error || !data) return {};
  const map: Record<string, string> = {};
  data.forEach((r: any) => {
    if (r.email) map[r.staff_name] = r.email;
  });
  return map;
}

export async function saveStaffContact(staffName: string, email: string): Promise<string | null> {
  const { error } = await supabase
    .from('staff_contacts')
    .upsert({ staff_name: staffName, email: email.trim(), updated_at: new Date().toISOString() });
  return error ? error.message : null;
}

