import { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { supabase } from '@/lib/supabase';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from 'sonner';
import { Loader2, AlertCircle } from 'lucide-react';
import { Alert, AlertDescription } from '@/components/ui/alert';

export default function Login() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<string | null>(searchParams.get('message'));
  const [workspaces, setWorkspaces] = useState<any[]>([]);
  const [showWorkspaceSelector, setShowWorkspaceSelector] = useState(false);

  useEffect(() => {
    // Check if already logged in
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        handleRouting(session.user.id);
      }
    });
  }, []);

  const handleRouting = async (userId: string) => {
    setLoading(true);
    try {
      // 1. Check Platform Super Admin
      const { data: adminData } = await supabase.rpc('is_super_admin');
      if (adminData === true) {
        const { data: { session } } = await supabase.auth.getSession();
        
        const isLocal = window.location.hostname.includes('localhost');
        const port = window.location.port ? `:${window.location.port}` : '';
        const base = isLocal ? 'localhost' : 'vowos.bridgebox.ai';
        const scheme = isLocal ? 'http' : 'https';
        const domain = `${scheme}://${base}${port}`;
        
        if (session) {
          window.location.href = `${domain}/central-auth#access_token=${session.access_token}&refresh_token=${session.refresh_token}&redirect=/platform`;
        } else {
          window.location.href = `${domain}/platform`;
        }
        return;
      }

      // 2. Check Workspaces (Organizations)
      const { data: memberships, error } = await supabase
        .from('business_memberships')
        .select(`
          business_id,
          businesses (
            id,
            name,
            slug,
            logo_url,
            status
          )
        `)
        .eq('user_id', userId)
        .eq('status', 'ACTIVE');

      if (error) throw error;

      if (!memberships || memberships.length === 0) {
        toast.error("You don't have access to any workspaces yet.");
        setLoading(false);
        return;
      }

      const redirectToTenant = async (slug: string) => {
        const { data: { session } } = await supabase.auth.getSession();
        
        const isLocal = window.location.hostname.includes('localhost');
        const port = window.location.port ? `:${window.location.port}` : '';
        const scheme = isLocal ? 'http' : 'https';
        const base = isLocal ? 'localhost' : 'bridgebox.ai';
        const domain = `${scheme}://${slug}.${base}${port}`;
        
        if (session) {
          window.location.href = `${domain}/central-auth#access_token=${session.access_token}&refresh_token=${session.refresh_token}`;
        } else {
          window.location.href = domain;
        }
      };

      if (memberships.length === 1) {
        // Log into the single workspace by redirecting to its subdomain
        const slug = (memberships[0].businesses as any).slug;
        await redirectToTenant(slug);
      } else {
        // Show Workspace Selector
        setWorkspaces(memberships.map((m: any) => m.businesses));
        setShowWorkspaceSelector(true);
        setLoading(false);
      }
    } catch (err: any) {
      console.error(err);
      toast.error('Failed to resolve routing. Please contact support.');
      setLoading(false);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage(null);

    const { data, error } = await supabase.auth.signInWithPassword({
      email,
      password,
    });

    if (error) {
      toast.error(error.message);
      setLoading(false);
    } else {
      await handleRouting(data.user.id);
    }
  };

  if (showWorkspaceSelector) {
    return (
      <div className="min-h-screen bg-stone-50 flex flex-col items-center justify-center p-4">
        <h1 className="text-2xl font-bold mb-6">Select a Workspace</h1>
        <div className="grid gap-4 w-full max-w-md">
          {workspaces.map((workspace) => (
            <Card 
              key={workspace.id}
              className="cursor-pointer hover:border-primary transition-colors"
              onClick={() => {
                const isLocal = window.location.hostname.includes('localhost');
                const port = window.location.port ? `:${window.location.port}` : '';
                const scheme = isLocal ? 'http' : 'https';
                const base = isLocal ? 'localhost' : 'bridgebox.ai';
                const domain = `${scheme}://${workspace.slug}.${base}${port}`;
                
                supabase.auth.getSession().then(({ data: { session } }) => {
                  if (session) {
                    window.location.href = `${domain}/central-auth#access_token=${session.access_token}&refresh_token=${session.refresh_token}`;
                  } else {
                    window.location.href = domain;
                  }
                });
              }}
            >
              <CardContent className="p-6 flex items-center justify-between">
                <div>
                  <h3 className="font-semibold text-lg">{workspace.name}</h3>
                  <p className="text-sm text-stone-500">{workspace.slug}</p>
                </div>
                <Button variant="outline">Enter</Button>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-stone-50 flex items-center justify-center p-4">
      <Card className="w-full max-w-md shadow-lg">
        <CardHeader className="text-center">
          <CardTitle className="text-2xl">Sign into VowOS</CardTitle>
          <CardDescription>Welcome back to the platform.</CardDescription>
        </CardHeader>
        <form onSubmit={handleLogin}>
          <CardContent className="space-y-4">
            {message === 'check-email' && (
              <Alert>
                <AlertCircle className="h-4 w-4" />
                <AlertDescription>
                  Please check your email to verify your account before logging in.
                </AlertDescription>
              </Alert>
            )}
            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <Input 
                id="email" 
                type="email" 
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="name@company.com" 
                required 
              />
            </div>
            <div className="space-y-2">
              <div className="flex justify-between">
                <Label htmlFor="password">Password</Label>
              </div>
              <Input 
                id="password" 
                type="password" 
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required 
              />
            </div>
          </CardContent>
          <CardFooter>
            <Button type="submit" className="w-full" disabled={loading}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Sign In
            </Button>
          </CardFooter>
        </form>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '@/contexts/AuthContext';
import { supabase } from '@/lib/supabase';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { Switch } from '@/components/ui/switch';
import { ArrowRight, ArrowLeft, Check, Loader2, Rocket, Building2, Package, Layers, Palette } from 'lucide-react';
import { PLANS, CommercialPlan } from '@/config/commercialCatalog';
import { getAllFeatures } from '@/lib/registry/features';

export default function Onboarding() {
  const { user, tenant, refreshProfile } = useAuth();
  const navigate = useNavigate();
  const [step, setStep] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Form State
  const [workspace, setWorkspace] = useState({
    businessName: '',
    industry: '',
    slug: '',
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
    country: 'US',
    state: '',
    parentId: '',
    websites: ['']
  });

  const [plan, setPlan] = useState<CommercialPlan>(
    (user?.user_metadata?.plan_intent as CommercialPlan) || 'essentials'
  );
  const [modules, setModules] = useState<Record<string, boolean>>({});
  
  const [branding, setBranding] = useState({
    primaryColor: '#0f172a',
    secondaryColor: '#f1f5f9'
  });

  useEffect(() => {
    // If tenant exists but isn't active/onboarding, or if they finished onboarding, redirect
    if (tenant && tenant.status === 'ACTIVE') {
      navigate('/');
    }
  }, [tenant, navigate]);

  const handleCreateWorkspace = async () => {
    setIsSubmitting(true);
    try {
      let businessId = tenant?.id;

      if (!businessId) {
        // 1. Provision organization (RPC handles creating businesses, memberships, default sub)
        const { data: newBusinessId, error: provisionError } = await supabase.rpc('provision_new_organization', {
          p_organization_type: 'BUSINESS',
          p_legal_name: workspace.businessName,
          p_display_name: workspace.businessName,
          p_slug: workspace.slug || workspace.businessName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)+/g, ''),
          p_industry: workspace.industry,
          p_country: workspace.country,
          p_state: workspace.state,
          p_timezone: workspace.timezone,
          p_plan_id: plan // The backend now strictly validates this (starter, pro, elite, comped)
        });
  
        if (provisionError) {
          if (provisionError.message.includes('slug_exists')) {
            throw new Error('That workspace URL is already taken. Please choose another one.');
          }
          throw provisionError;
        }
        businessId = newBusinessId;
      }

      // We removed the direct update of organization_subscriptions here, 
      // because the provision_new_organization RPC securely handles setting the subscription plan.

      // 3. Save branding and complete onboarding
      const { error: brandError } = await supabase
        .from('businesses')
        .update({ 
          primary_color: branding.primaryColor,
          secondary_color: branding.secondaryColor,
          onboarding_status: 'COMPLETE',
          status: 'ACTIVE',
          onboarding_progress: {
            currentStep: 4,
            completedSteps: [1, 2, 3, 4],
            startedAt: new Date().toISOString(),
            updatedAt: new Date().toISOString()
          }
        })
        .eq('id', businessId);
      if (brandError) throw brandError;

      // Force refresh auth context to load the new tenant
      await refreshProfile();
      toast.success('Workspace created successfully!');
      setStep(5); // Move to the welcome / handoff screen instead of immediate redirect
    } catch (e: any) {
      toast.error(e.message || 'Failed to create workspace');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleNext = () => setStep(s => s + 1);
  const handlePrev = () => setStep(s => s - 1);

  if (!user) {
    return <div className="min-h-screen flex items-center justify-center"><Loader2 className="animate-spin h-8 w-8 text-primary" /></div>;
  }

  return (
    <div className="min-h-screen bg-stone-50 flex items-center justify-center p-4 py-12">
      <div className="max-w-3xl w-full">
        {/* Progress Tracker */}
        <div className="mb-8 flex justify-between items-center px-4 relative">
          <div className="absolute left-0 top-1/2 -translate-y-1/2 w-full h-1 bg-stone-200 -z-10 rounded-full overflow-hidden">
            <div className="h-full bg-primary transition-all duration-300 ease-in-out" style={{ width: `${(Math.min(step - 1, 3) / 3) * 100}%` }} />
          </div>
          
          {[
            { id: 1, label: 'Workspace', icon: Building2 },
            { id: 2, label: 'Plan', icon: Package },
            { id: 3, label: 'Modules', icon: Layers },
            { id: 4, label: 'Branding', icon: Palette }
          ].map((s) => (
            <div key={s.id} className="flex flex-col items-center gap-2 bg-stone-50 px-2">
              <div className={`w-10 h-10 rounded-full flex items-center justify-center ${step >= s.id ? 'bg-primary text-primary-foreground' : 'bg-stone-200 text-stone-400'}`}>
                <s.icon className="w-5 h-5" />
              </div>
              <span className={`text-xs font-medium ${step >= s.id ? 'text-primary' : 'text-stone-400'}`}>{s.label}</span>
            </div>
          ))}
        </div>

        <Card className="shadow-lg border-0 ring-1 ring-black/5">
          {step === 1 && (
            <>
              <CardHeader>
                <CardTitle>Workspace Details</CardTitle>
                <CardDescription>Tell us a bit about your organization.</CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-2">
                  <Label>Business Name</Label>
                  <Input 
                    placeholder="Acme Corp" 
                    value={workspace.businessName} 
                    onChange={e => setWorkspace({...workspace, businessName: e.target.value})} 
                  />
                </div>
                <div className="space-y-2">
                  <Label>Workspace URL</Label>
                  <div className="flex items-center">
                    <Input 
                      placeholder="acme-corp" 
                      value={workspace.slug} 
                      onChange={e => setWorkspace({...workspace, slug: e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, '')})} 
                      className="rounded-r-none"
                    />
                    <div className="bg-stone-100 border border-l-0 border-input px-3 py-2 rounded-r-md text-sm text-stone-500 whitespace-nowrap">
                      .vowos.bridgebox.ai
                    </div>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label>Industry</Label>
                    <Select value={workspace.industry} onValueChange={v => setWorkspace({...workspace, industry: v})}>
                      <SelectTrigger><SelectValue placeholder="Select industry..." /></SelectTrigger>
                      <SelectContent>
                        <SelectItem value="retail">Retail</SelectItem>
                        <SelectItem value="bridal">Bridal & Formalwear</SelectItem>
                        <SelectItem value="services">Professional Services</SelectItem>
                        <SelectItem value="other">Other</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <Label>State / Province</Label>
                    <Input placeholder="NY" value={workspace.state} onChange={e => setWorkspace({...workspace, state: e.target.value})} />
                  </div>
                </div>
                <div className="space-y-4 pt-4 border-t border-stone-100 mt-4">
                  <div className="flex justify-between items-center">
                    <Label>Websites</Label>
                    <Button 
                      variant="outline" 
                      size="sm"
                      onClick={() => setWorkspace({...workspace, websites: [...workspace.websites, '']})}
                    >
                      + Add Website
                    </Button>
                  </div>
                  {workspace.websites.map((url, i) => (
                    <div key={i} className="flex gap-2">
                      <Input 
                        placeholder="https://example.com" 
                        value={url} 
                        onChange={e => {
                          const newWebsites = [...workspace.websites];
                          newWebsites[i] = e.target.value;
                          setWorkspace({...workspace, websites: newWebsites});
                        }} 
                      />
                      {workspace.websites.length > 1 && (
                        <Button 
                          variant="ghost" 
                          size="icon"
                          onClick={() => {
                            const newWebsites = workspace.websites.filter((_, index) => index !== i);
                            setWorkspace({...workspace, websites: newWebsites});
                          }}
                        >
                          Γ£ò
                        </Button>
                      )}
                    </div>
                  ))}
                </div>
                <div className="space-y-2 pt-4 border-t border-stone-100">
                  <Label>Parent Organization ID (Optional)</Label>
                  <Input 
                    placeholder="UUID of parent company if this is a child location" 
                    value={workspace.parentId} 
                    onChange={e => setWorkspace({...workspace, parentId: e.target.value})} 
                  />
                  <p className="text-xs text-stone-500">Leave blank if this is a top-level organization.</p>
                </div>
              </CardContent>
              <CardFooter className="flex justify-end">
                <Button onClick={handleNext} disabled={!workspace.businessName}>Continue <ArrowRight className="w-4 h-4 ml-2" /></Button>
              </CardFooter>
            </>
          )}

          {step === 2 && (
            <>
              <CardHeader>
                <CardTitle>Choose a Plan</CardTitle>
                <CardDescription>Select the package that fits your needs.</CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid md:grid-cols-2 gap-4">
                  {(Object.entries(PLANS) as [CommercialPlan, typeof PLANS[CommercialPlan]][]).map(([planId, planDef]) => (
                    <Card 
                      key={planId}
                      className={`cursor-pointer transition-all ${plan === planId ? 'ring-2 ring-primary border-primary bg-primary/5' : 'hover:border-primary/50'}`}
                      onClick={() => setPlan(planId)}
                    >
                      <CardHeader>
                        <CardTitle>{planDef.label}</CardTitle>
                        <div className="text-2xl font-bold">
                          ${planDef.monthly}
                          <span className="text-sm font-normal text-stone-500">/mo</span>
                        </div>
                        <CardDescription>{planDef.description}</CardDescription>
                      </CardHeader>
                    </Card>
                  ))}
                </div>
              </CardContent>
              <CardFooter className="flex justify-between">
                <Button variant="ghost" onClick={handlePrev}><ArrowLeft className="w-4 h-4 mr-2" /> Back</Button>
                <Button onClick={handleNext}>Continue <ArrowRight className="w-4 h-4 ml-2" /></Button>
              </CardFooter>
            </>
          )}

          {step === 3 && (
            <>
              <CardHeader>
                <CardTitle>Configure Modules</CardTitle>
                <CardDescription>Turn on only the features you need to keep your workspace clean.</CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-4">
                  {getAllFeatures().filter(f => f.configurable).map((feat) => (
                    <div key={feat.slug} className="flex items-center justify-between p-4 bg-stone-50 rounded-lg border border-stone-100">
                      <div>
                        <div className="font-medium capitalize">{feat.name}</div>
                        <div className="text-sm text-stone-500">{feat.description}</div>
                      </div>
                      <Switch 
                        checked={modules[feat.slug] ?? feat.defaultEnabled} 
                        onCheckedChange={(c) => setModules({...modules, [feat.slug]: c})}
                      />
                    </div>
                  ))}
                </div>
              </CardContent>
              <CardFooter className="flex justify-between">
                <Button variant="ghost" onClick={handlePrev}><ArrowLeft className="w-4 h-4 mr-2" /> Back</Button>
                <Button onClick={handleNext}>Continue <ArrowRight className="w-4 h-4 ml-2" /></Button>
              </CardFooter>
            </>
          )}

          {step === 4 && (
            <>
              <CardHeader>
                <CardTitle>Branding</CardTitle>
                <CardDescription>Set up your company colors.</CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                <div className="space-y-2">
                  <Label>Primary Color</Label>
                  <div className="flex gap-4">
                    <Input 
                      type="color" 
                      value={branding.primaryColor} 
                      onChange={e => setBranding({...branding, primaryColor: e.target.value})} 
                      className="w-16 p-1 h-10"
                    />
                    <Input 
                      value={branding.primaryColor} 
                      onChange={e => setBranding({...branding, primaryColor: e.target.value})} 
                      className="flex-1"
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <Label>Secondary Color</Label>
                  <div className="flex gap-4">
                    <Input 
                      type="color" 
                      value={branding.secondaryColor} 
                      onChange={e => setBranding({...branding, secondaryColor: e.target.value})} 
                      className="w-16 p-1 h-10"
                    />
                    <Input 
                      value={branding.secondaryColor} 
                      onChange={e => setBranding({...branding, secondaryColor: e.target.value})} 
                      className="flex-1"
                    />
                  </div>
                </div>
                
                <div className="p-6 rounded-lg bg-stone-50 border border-stone-200 mt-6">
                  <h4 className="text-sm font-medium mb-4 text-stone-500">Preview</h4>
                  <Button style={{ backgroundColor: branding.primaryColor, color: '#fff' }} className="mr-4">
                    Primary Action
                  </Button>
                  <Button variant="outline" style={{ borderColor: branding.secondaryColor, color: branding.primaryColor }}>
                    Secondary Action
                  </Button>
                </div>
              </CardContent>
              <CardFooter className="flex justify-between">
                <Button variant="ghost" onClick={handlePrev} disabled={isSubmitting}><ArrowLeft className="w-4 h-4 mr-2" /> Back</Button>
                <Button onClick={handleCreateWorkspace} disabled={isSubmitting}>
                  {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Rocket className="w-4 h-4 mr-2" />}
                  Launch Workspace
                </Button>
              </CardFooter>
            </>
          )}

          {step === 5 && (
            <div className="p-8 text-center space-y-8 animate-in fade-in zoom-in duration-500">
              <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-6">
                <Check className="w-10 h-10" />
              </div>
              <div>
                <h2 className="text-3xl font-bold text-stone-900 mb-3">Workspace Ready</h2>
                <p className="text-stone-500 max-w-md mx-auto">
                  Your VowOS workspace has been successfully provisioned. We recommend taking the interactive tour to get familiar with the system.
                </p>
              </div>

              <div className="grid sm:grid-cols-2 gap-4 mt-8">
                <Button 
                  variant="outline" 
                  className="h-auto py-6 flex flex-col gap-2 border-stone-200 hover:bg-stone-50"
                  onClick={() => {
                    const isLocal = window.location.hostname.includes('localhost');
                    const port = window.location.port ? `:${window.location.port}` : '';
                    const scheme = isLocal ? 'http' : 'https';
                    const base = isLocal ? 'localhost' : 'bridgebox.ai';
                    const domain = `${scheme}://${workspace.slug}.${base}${port}`;
                    
                    supabase.auth.getSession().then(({ data: { session } }) => {
                      if (session) {
                        window.location.href = `${domain}/central-auth#access_token=${session.access_token}&refresh_token=${session.refresh_token}`;
                      } else {
                        window.location.href = domain;
                      }
                    });
                  }}
                >
                  <Building2 className="w-6 h-6 text-stone-400" />
                  <div className="font-semibold text-stone-900">Go to Workspace</div>
                  <div className="text-xs text-stone-500 font-normal">Start setting up your real data</div>
                </Button>

                <Button 
                  className="h-auto py-6 flex flex-col gap-2 bg-brand-primary hover:bg-brand-secondary text-white border-none shadow-lg shadow-brand-primary/20"
                  onClick={() => navigate('/demo')}
                >
                  <Rocket className="w-6 h-6 text-white" />
                  <div className="font-semibold">Launch Guided Tour</div>
                  <div className="text-xs text-white/80 font-normal">Explore a synthetic sandbox with AI narration</div>
                </Button>
              </div>
            </div>
          )}
        </Card>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { supabase } from '@/lib/supabase';
import { useNavigate, Routes, Route, Link, useLocation } from 'react-router-dom';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import { Building2, Users, CreditCard, Activity, Search, LayoutDashboard, Shield, AlertTriangle, CloudRain, Briefcase, Zap, ShieldAlert, BookOpen, GitCommitHorizontal, DollarSign } from 'lucide-react';
import { toast } from 'sonner';
import TenantControlCenter from './PlatformAdmin/TenantControlCenter';
import UserDirectory from './PlatformAdmin/UserDirectory';
import SystemHealthView from './PlatformAdmin/SystemHealthView';
import FailedJobsView from './PlatformAdmin/FailedJobsView';
import IncidentsView from './PlatformAdmin/IncidentsView';
import IntegrationsHealthView from './PlatformAdmin/IntegrationsHealthView';
import PlatformAuditView from './PlatformAdmin/PlatformAuditView';
import ReleaseDashboardView from './PlatformAdmin/ReleaseDashboardView';
import PlatformSalesView from './PlatformAdmin/PlatformSalesView';
import DemoAnalyticsView from './platform/DemoAnalyticsView';
import CustomerSuccessWorkspace from './PlatformAdmin/CustomerSuccessWorkspace';
import SupportQueue from './PlatformAdmin/SupportQueue';
import { HeartHandshake, HeadphonesIcon } from 'lucide-react';

import { useAuth } from '@/contexts/AuthContext';
import { calculatePlatformMRR, SubRecord } from '@/lib/finance/reconciliationEngine';

export default function PlatformAdmin() {
  const { userContext } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    if (userContext && userContext.platform_role !== 'PLATFORM_OWNER') {
      toast.error('Unauthorized access');
      navigate('/login');
    }
  }, [userContext, navigate]);

  if (!userContext || userContext.platform_role !== 'PLATFORM_OWNER') return null;

  const navCategories = [
    {
      title: 'OVERVIEW',
      items: [
        { name: 'Command Center', path: '/platform', icon: <LayoutDashboard className="w-4 h-4" /> },
      ]
    },
    {
      title: 'REVENUE',
      items: [
        { name: 'Corporate Sales', path: '/platform/sales', icon: <DollarSign className="w-4 h-4" /> },
        { name: 'Demo Funnel', path: '/platform/demo-analytics', icon: <Users className="w-4 h-4" /> },
      ]
    },
    {
      title: 'CUSTOMERS',
      items: [
        { name: 'User Directory', path: '/platform/users', icon: <Users className="w-4 h-4" /> },
        { name: 'Customer Success', path: '/platform/success', icon: <HeartHandshake className="w-4 h-4" /> },
        { name: 'Support Queue', path: '/platform/support', icon: <HeadphonesIcon className="w-4 h-4" /> },
      ]
    },
    {
      title: 'PLATFORM',
      items: [
        { name: 'System Health', path: '/platform/health', icon: <Activity className="w-4 h-4" /> },
        { name: 'Incidents', path: '/platform/incidents', icon: <AlertTriangle className="w-4 h-4" /> },
        { name: 'Failed Jobs', path: '/platform/jobs', icon: <Briefcase className="w-4 h-4" /> },
        { name: 'Integrations', path: '/platform/integrations', icon: <Zap className="w-4 h-4" /> },
      ]
    },
    {
      title: 'ENGINEERING / GOVERNANCE',
      items: [
        { name: 'Release Dashboard', path: '/platform/releases', icon: <GitCommitHorizontal className="w-4 h-4" /> },
        { name: 'Audit Log', path: '/platform/audit', icon: <BookOpen className="w-4 h-4" /> },
      ]
    }
  ];

  return (
    <div className="flex h-screen bg-stone-50 overflow-hidden font-sans">
      <div className="w-64 bg-stone-900 text-stone-300 flex flex-col">
        <div className="p-6 border-b border-stone-800">
          <h1 className="text-xl font-serif text-white tracking-tight flex items-center gap-2">
            <Shield className="w-5 h-5 text-brand-primary" /> VowOS Platform
          </h1>
          <p className="text-[10px] uppercase tracking-widest text-stone-500 mt-2">Operations Center</p>
        </div>
        <nav className="flex-1 overflow-y-auto py-4">
          <div className="space-y-6 px-3">
            {navCategories.map(category => (
              <div key={category.title}>
                <h3 className="px-3 text-[10px] font-bold tracking-wider text-stone-500 uppercase mb-2">{category.title}</h3>
                <ul className="space-y-1">
                  {category.items.map(item => {
                    // Exact match for root, prefix match for others to keep state active
                    const isActive = item.path === '/platform' ? location.pathname === '/platform' : location.pathname.startsWith(item.path);
                    return (
                      <li key={item.path}>
                        <Link 
                          to={item.path}
                          className={`flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors ${isActive ? 'bg-stone-800 text-white font-medium' : 'hover:bg-stone-800/50 hover:text-stone-100'}`}
                        >
                          {item.icon}
                          {item.name}
                        </Link>
                      </li>
                    );
                  })}
                </ul>
              </div>
            ))}
          </div>
        </nav>
        <div className="p-4 border-t border-stone-800">
          <Button variant="ghost" className="w-full justify-start text-stone-400 hover:text-white hover:bg-stone-800" onClick={() => navigate('/app')}>
            Exit Operations
          </Button>
        </div>
      </div>
      <div className="flex-1 overflow-y-auto">
        <header className="bg-white border-b border-stone-200 h-16 flex items-center px-8 sticky top-0 z-10 shadow-sm">
          <h2 className="text-sm font-semibold text-stone-800">
            {navCategories.flatMap(c => c.items).find(i => i.path === location.pathname)?.name || 'Platform Admin'}
          </h2>
        </header>
        <main className="p-8 max-w-7xl mx-auto">
          <Routes>
            <Route path="/" element={<PlatformAdminHome />} />
            <Route path="/sales" element={<PlatformSalesView />} />
            <Route path="/demo-analytics" element={<DemoAnalyticsView />} />
            <Route path="/success" element={<CustomerSuccessWorkspace />} />
            <Route path="/support" element={<SupportQueue />} />
