import React, { useState, useEffect } from 'react';
import { supabase } from '@/lib/supabase';
import { toast } from 'sonner';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Search, Loader2, Plus, ShieldAlert } from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import { PlatformRole } from '@/lib/auth/roles';
import { AddPlatformUserModal } from '@/components/vowos/platform/AddPlatformUserModal';

export default function UserDirectory() {
  const [platformUsers, setPlatformUsers] = useState<any[]>([]);
  const [tenantUsers, setTenantUsers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [isInviteModalOpen, setIsInviteModalOpen] = useState(false);
  const { userContext } = useAuth();

  useEffect(() => {
    fetchDirectories();
  }, []);

  const fetchDirectories = async () => {
    try {
      setLoading(true);
      const [platformRes, tenantRes] = await Promise.all([
        supabase.rpc('get_platform_directory'),
        supabase.rpc('get_tenant_user_directory')
      ]);

      if (platformRes.error) throw platformRes.error;
      if (tenantRes.error) throw tenantRes.error;

      setPlatformUsers(platformRes.data || []);
      setTenantUsers(tenantRes.data || []);
    } catch (err: any) {
      console.error('Directory fetch error:', err);

      // Handle the Postgres 'Unauthorized' exception gracefully
      if (err.message?.includes('Unauthorized') || err.code === '42501') {
        toast.error('Access Denied: You do not have Platform Admin privileges.');
      } else {
        toast.error('Failed to load user directories');
      }
    } finally {
      setLoading(false);
    }
  };

  const filteredPlatformUsers = platformUsers.filter(u => 
    u.email?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const filteredTenantUsers = tenantUsers.filter(u => 
    u.email?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    u.business_name?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  if (loading) {
    return <div className="p-8 flex items-center justify-center"><Loader2 className="animate-spin h-8 w-8 text-primary" /></div>;
  }

  return (
    <div className="space-y-6">
      <AddPlatformUserModal 
        open={isInviteModalOpen} 
        onOpenChange={setIsInviteModalOpen}
        onSuccess={fetchDirectories}
      />
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold tracking-tight">User Directory</h2>
          <p className="text-muted-foreground">Manage platform staff and audit tenant users.</p>
        </div>
        <div className="flex items-center gap-4">
          <div className="relative">
            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-stone-500" />
            <Input 
              placeholder="Search by email..." 
              className="pl-9 w-[250px]"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          {userContext?.platform_role === PlatformRole.PLATFORM_OWNER && (
            <Button onClick={() => setIsInviteModalOpen(true)}>
              <Plus className="mr-2 h-4 w-4" /> Add Platform User
            </Button>
          )}
        </div>
      </div>

      <Tabs defaultValue="platform" className="space-y-4">
        <TabsList>
          <TabsTrigger value="platform">Platform Staff</TabsTrigger>
          <TabsTrigger value="tenant">Tenant Users</TabsTrigger>
        </TabsList>

        <TabsContent value="platform">
          <Card>
            <CardHeader>
              <CardTitle>VowOS Platform Staff</CardTitle>
              <CardDescription>Personnel with administrative access to the SaaS infrastructure.</CardDescription>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>User / Email</TableHead>
                    <TableHead>Platform Role</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Joined</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredPlatformUsers.map((user, idx) => (
                    <TableRow key={idx}>
                      <TableCell>
                        <div className="font-medium">{user.email}</div>
                      </TableCell>
                      <TableCell>
                        <Badge variant={user.platform_role === 'PLATFORM_OWNER' ? 'destructive' : 'default'}>
                          {user.platform_role}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <Badge variant={user.active ? 'outline' : 'secondary'}>
                          {user.active ? 'Active' : 'Suspended'}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-stone-500">
                        {new Date(user.created_at).toLocaleDateString()}
                      </TableCell>
                    </TableRow>
                  ))}
                  {filteredPlatformUsers.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={4} className="text-center py-8 text-stone-500">
                        No platform staff found.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="tenant">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                Tenant Users <ShieldAlert className="h-4 w-4 text-orange-500" />
              </CardTitle>
              <CardDescription>Global directory of all customers. Modifications should be done via Organization Support Mode.</CardDescription>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Email</TableHead>
                    <TableHead>Organization</TableHead>
                    <TableHead>Org Role</TableHead>
                    <TableHead>Joined</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredTenantUsers.map((user, idx) => (
                    <TableRow key={idx}>
                      <TableCell>
                        <div className="font-medium">{user.email}</div>
                        <div className="text-xs text-stone-500">ID: {user.id.substring(0, 8)}...</div>
                      </TableCell>
                      <TableCell>{user.business_name || 'N/A'}</TableCell>
                      <TableCell>
                        <Badge variant="outline">{user.role}</Badge>
                      </TableCell>
                      <TableCell className="text-stone-500">
                        {new Date(user.created_at).toLocaleDateString()}
                      </TableCell>
                    </TableRow>
                  ))}
                  {filteredTenantUsers.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={4} className="text-center py-8 text-stone-500">
                        No tenant users found.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Store, User, ArrowRight, Building2, CheckCircle2, Loader2 } from 'lucide-react';
import { supabase } from '@/lib/supabase';
import { toast } from 'sonner';
import { z } from 'zod';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';

import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

const signupSchema = z.object({
  firstName: z.string().min(2, 'First name is required'),
  lastName: z.string().min(2, 'Last name is required'),
  email: z.string().email('Valid email is required'),
  password: z.string().min(8, 'Password must be at least 8 characters'),
});

export default function Signup() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const planIntent = searchParams.get('plan');
  const billingIntent = searchParams.get('billing');

  const [step, setStep] = useState<1 | 2>(1);
  const [accountType, setAccountType] = useState<'BUSINESS' | 'INDIVIDUAL' | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const form = useForm<z.infer<typeof signupSchema>>({
    resolver: zodResolver(signupSchema),
  });

  const handleCreateAccount = async (data: any) => {
    setIsSubmitting(true);
    try {
      let loginError;
      
      const { data: authData, error: authError } = await supabase.auth.signUp({
        email: data.email,
        password: data.password,
        options: {
          data: {
            first_name: data.firstName,
            last_name: data.lastName,
            account_type: accountType, // Store intent for Onboarding flow
            plan_intent: planIntent,
            billing_intent: billingIntent
          },
        },
      });

      if (authError) {
        // If the user already exists, we will try to log them in directly instead of failing the flow
        if (authError.message.includes('already registered')) {
          const { error: signInErr } = await supabase.auth.signInWithPassword({
            email: data.email,
            password: data.password,
          });
          loginError = signInErr;
          if (!signInErr) {
            toast.success('Welcome back!');
          }
        } else {
          throw authError;
        }
      } else {
        toast.success('Account created successfully!');
        const { error: signInErr } = await supabase.auth.signInWithPassword({
          email: data.email,
          password: data.password,
        });
        loginError = signInErr;
      }

      if (!loginError) {
        navigate('/app');
      } else {
        navigate('/login?message=check-email');
      }
    } catch (error: any) {
      toast.error(error.message || 'Failed to create account. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-stone-50 flex items-center justify-center p-4">
      <div className="max-w-2xl w-full">
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold tracking-tight mb-2">Welcome to VowOS</h1>
          <p className="text-stone-500">The operating system for modern business.</p>
        </div>

        {step === 1 && (
          <div className="grid md:grid-cols-2 gap-6">
            <Card 
              className={`cursor-pointer transition-all hover:border-primary/50 hover:shadow-md ${accountType === 'BUSINESS' ? 'border-primary ring-2 ring-primary/20' : ''}`}
              onClick={() => setAccountType('BUSINESS')}
            >
              <CardHeader>
                <Building2 className="h-8 w-8 mb-4 text-primary" />
                <CardTitle>Business</CardTitle>
                <CardDescription>For companies, stores, teams and organizations.</CardDescription>
              </CardHeader>
            </Card>

            <Card 
              className={`cursor-pointer transition-all hover:border-primary/50 hover:shadow-md ${accountType === 'INDIVIDUAL' ? 'border-primary ring-2 ring-primary/20' : ''}`}
              onClick={() => setAccountType('INDIVIDUAL')}
            >
              <CardHeader>
                <User className="h-8 w-8 mb-4 text-primary" />
                <CardTitle>Individual</CardTitle>
                <CardDescription>For independent professionals and owner/operators.</CardDescription>
              </CardHeader>
            </Card>

            <div className="md:col-span-2 flex justify-end mt-4">
              <Button 
                size="lg" 
                disabled={!accountType} 
                onClick={() => setStep(2)}
              >
                Continue <ArrowRight className="ml-2 h-4 w-4" />
              </Button>
            </div>
          </div>
        )}

        {step === 2 && (
          <Card>
            <CardHeader>
              <CardTitle>Create your Account</CardTitle>
              <CardDescription>Let's get started with {accountType === 'BUSINESS' ? 'your organization' : 'your personal workspace'}.</CardDescription>
            </CardHeader>
            <form onSubmit={form.handleSubmit(handleCreateAccount)}>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="firstName">First Name</Label>
                    <Input id="firstName" {...form.register('firstName')} />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="lastName">Last Name</Label>
                    <Input id="lastName" {...form.register('lastName')} />
                  </div>
                </div>
                
                <div className="space-y-2">
                  <Label htmlFor="email">Email</Label>
                  <Input id="email" type="email" {...form.register('email')} />
                </div>
                
                <div className="space-y-2">
                  <Label htmlFor="password">Password</Label>
                  <Input id="password" type="password" {...form.register('password')} />
                </div>
              </CardContent>
              <CardFooter className="flex justify-between">
                <Button variant="ghost" type="button" onClick={() => setStep(1)}>Back</Button>
                <Button type="submit" disabled={isSubmitting}>
                  {isSubmitting ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
                  Create Account
                </Button>
              </CardFooter>
            </form>
          </Card>
        )}
      </div>
    </div>
  );
}

import React from 'react';
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from '@vowos/design-system';
import { Card, CardHeader, CardTitle, CardContent } from '@vowos/design-system';
import { Badge } from '@vowos/design-system';
import { Button } from '@vowos/design-system';
import { Brain, Star, Clock, AlertTriangle, Loader2 } from 'lucide-react';
import { useAIRecommendations } from '@/lib/services/schedulingService';

interface AIAssignmentDrawerProps {
  request: any;
  isOpen: boolean;
  onClose: () => void;
  onAssign: (recommendation: any) => void;
}

export function AIAssignmentDrawer({ request, isOpen, onClose, onAssign }: AIAssignmentDrawerProps) {
  const { data: recommendations, isLoading } = useAIRecommendations(request?.id);

  return (
    <Sheet open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <SheetContent side="right" className="w-[400px] sm:w-[540px] flex flex-col h-full bg-muted/20 p-0">
        <div className="p-6 bg-background border-b">
          <SheetHeader>
            <SheetTitle className="flex items-center gap-2">
              <Brain className="h-5 w-5 text-indigo-500" />
              AI Assignment Engine
            </SheetTitle>
            <SheetDescription>
              Assigning {request?.customer?.first_name || 'Customer'} for {request?.service?.name || 'Service'}
            </SheetDescription>
          </SheetHeader>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          <div className="text-sm font-medium text-muted-foreground uppercase tracking-wide">
            Top Recommendations
          </div>
          
          {isLoading ? (
            <div className="p-12 flex flex-col items-center justify-center text-center text-muted-foreground space-y-4">
              <Loader2 className="h-8 w-8 animate-spin text-indigo-500" />
              <p className="animate-pulse">Analyzing schedules and constraints...</p>
            </div>
          ) : recommendations && recommendations.length > 0 ? (
            recommendations.map((rec: any, index: number) => (
              <Card key={rec.id} className={`border-2 ${index === 0 ? 'border-indigo-500 shadow-md ring-1 ring-indigo-500/20' : 'border-transparent'}`}>
                <CardHeader className="pb-2">
                  <div className="flex justify-between items-start">
                    <div>
                      <CardTitle className="text-base">{rec.employee?.first_name} {rec.employee?.last_name}</CardTitle>
                      <div className="text-xs text-muted-foreground mt-1 flex items-center gap-2">
                        <Clock className="h-3 w-3" /> 
                        {new Date(rec.recommended_start).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})} - {new Date(rec.recommended_end).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                      </div>
                    </div>
                    <Badge variant={rec.score >= 90 ? "default" : "secondary"} className={rec.score >= 90 ? "bg-indigo-500" : ""}>
                      {rec.score}% Match
                    </Badge>
                  </div>
                </CardHeader>
                <CardContent>
                  <div className="space-y-2 mb-4">
                    {rec.match_reasons?.map((reason: string, i: number) => (
                      <div key={i} className="flex items-start gap-2 text-sm text-green-700 dark:text-green-400">
                        <Star className="h-3 w-3 mt-1 shrink-0" />
                        <span>{reason}</span>
                      </div>
                    ))}
                    {rec.conflict_warnings?.map((warning: string, i: number) => (
                      <div key={i} className="flex items-start gap-2 text-sm text-status-warning dark:text-status-warning">
                        <AlertTriangle className="h-3 w-3 mt-1 shrink-0" />
                        <span>{warning}</span>
                      </div>
                    ))}
                  </div>
                  <Button 
                    className="w-full" 
                    variant={index === 0 ? "default" : "outline"}
                    onClick={() => onAssign(rec)}
                  >
                    Assign to {rec.employee?.first_name}
                  </Button>
                </CardContent>
              </Card>
            ))
          ) : (
            <div className="p-12 flex flex-col items-center justify-center text-center border rounded-lg bg-background text-muted-foreground space-y-3">
              <Brain className="h-12 w-12 text-muted-foreground/30" />
              <p>No AI recommendations available for this request. Ensure employee schedules are published and the request has valid service requirements.</p>
            </div>
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
}

import React, { useState } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '@vowos/design-system';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@vowos/design-system';
import { Button } from '@vowos/design-system';
import { Badge } from '@vowos/design-system';
import { ScrollArea } from '@vowos/design-system';
import { Input } from '@vowos/design-system';
import { Avatar, AvatarFallback } from '@vowos/design-system';
import { Textarea } from '@vowos/design-system';
import { User, Phone, Mail, Clock, DollarSign, FileText, CheckCircle, MessageSquare, Play, AlertCircle, Sparkles } from 'lucide-react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@vowos/design-system';
import { 
  useAppointment360, 
  useStaffProfiles, 
  useAIRecommendations, 
  useCheckInAppointment,
  useStartAppointment,
  useAssignStaff,
  useAddAppointmentNote,
  useAddAppointmentTask,
  useAddCommunication
} from '@/lib/services/schedulingService';
import { useVowosData } from '@/contexts/VowosDataContext';
import { OutcomeModal } from './OutcomeModal';

export function Appointment360Panel({ appointmentId, request, onClose }: { appointmentId: string, request: any, onClose: () => void }) {
  const [activeTab, setActiveTab] = useState('summary');
  const [outcomeModalOpen, setOutcomeModalOpen] = useState(false);
  
  const { businessId } = useVowosData();
  const { data: apt360, isLoading } = useAppointment360(appointmentId);
  const { data: staff = [] } = useStaffProfiles();
  const { data: aiRecs = [] } = useAIRecommendations(request?.id || appointmentId);
  
  const assignMutation = useAssignStaff();
  const checkInMutation = useCheckInAppointment();
  const startMutation = useStartAppointment();
  const addNoteMutation = useAddAppointmentNote();
  const addTaskMutation = useAddAppointmentTask();
  const addCommMutation = useAddCommunication();

  const [newNote, setNewNote] = useState('');
  const [showNoteInput, setShowNoteInput] = useState(false);
  
  const [newTask, setNewTask] = useState('');
  const [showTaskInput, setShowTaskInput] = useState(false);

  const [newComm, setNewComm] = useState('');

  const handleAssignStaff = (employeeId: string) => {
    if (!appointmentId) return;
    assignMutation.mutate({ appointmentId, employeeId });
  };

  const handleCheckIn = () => {
    if (!appointmentId) return;
    checkInMutation.mutate({ appointmentId });
  };
  
  const handleStart = () => {
    if (!appointmentId) return;
    startMutation.mutate({ appointmentId });
  };

  const handleAddNote = () => {
    if (!appointmentId || !newNote.trim()) return;
    addNoteMutation.mutate({ appointmentId, content: newNote, businessId }, {
      onSuccess: () => {
        setNewNote('');
        setShowNoteInput(false);
      }
    });
  };

  const handleAddTask = () => {
    if (!appointmentId || !newTask.trim()) return;
    addTaskMutation.mutate({ appointmentId, title: newTask, businessId }, {
      onSuccess: () => {
        setNewTask('');
        setShowTaskInput(false);
      }
    });
  };

  const handleSendComm = () => {
    if (!appointmentId || !newComm.trim()) return;
    addCommMutation.mutate({ appointmentId, content: newComm, businessId }, {
      onSuccess: () => {
        setNewComm('');
      }
    });
  };

  if (!request && !appointmentId) {
    return (
      <div className="flex items-center justify-center h-full text-muted-foreground p-8 text-center bg-background">
        Select an appointment from the calendar or queue to view the 360┬░ details.
      </div>
    );
  }

  const customerName = request?.customerName || (apt360?.appointment?.customer ? apt360.appointment.customer.first_name + ' ' + apt360.appointment.customer.last_name : null);
  const initials = customerName ? customerName.split(' ').map((n: string) => n[0]).join('').substring(0, 2).toUpperCase() : '?';
  const status = (request?.status || apt360?.appointment?.confirmation_status || 'PENDING').toUpperCase();

  const renderMissing = (label: string) => (
    <div className="flex items-center gap-1.5 text-muted-foreground/60 text-xs italic">
      <AlertCircle className="h-3 w-3" /> Missing {label}
    </div>
  );

  return (
    <div className="h-full flex flex-col border-l bg-background">
      {/* Header */}
      <div className="relative overflow-hidden border-b bg-gradient-to-br from-indigo-50 via-white to-purple-50 dark:from-indigo-950/20 dark:via-background dark:to-purple-950/20">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 to-purple-500"></div>
        <div className="p-5 pt-6 flex justify-between items-start z-10">
          <div className="flex gap-4 items-center">
            <Avatar className="h-14 w-14 border-2 border-white shadow-md ring-1 ring-black/5">
              <AvatarFallback className="bg-gradient-to-br from-indigo-500 to-purple-500 text-white text-lg font-semibold">{initials}</AvatarFallback>
            </Avatar>
            <div>
              <div className="flex items-center gap-2 mb-1">
                <h2 className="text-xl font-bold text-foreground">{customerName || renderMissing('Customer Identity')}</h2>
                <Badge className={
                  status === 'CONFIRMED' ? 'bg-status-success/10 text-status-success border-emerald-200' : 
                  status === 'ARRIVED' || status === 'IN-PROGRESS' ? 'bg-indigo-500/10 text-indigo-600 border-indigo-200' :
                  status === 'COMPLETED' ? 'bg-gray-500/10 text-text-secondary border-border-default' :
                  'bg-status-warning/10 text-status-warning border-status-warning/20'
                } variant="outline">
                  {status}
                </Badge>
              </div>
              <p className="text-sm text-muted-foreground flex items-center gap-3">
                <span className="flex items-center gap-1"><Phone className="h-3 w-3" /> {apt360?.appointment?.customer?.phone || request?.customerPhone || renderMissing('Phone')}</span>
                <span className="flex items-center gap-1"><Mail className="h-3 w-3" /> {apt360?.appointment?.customer?.email || request?.customerEmail || renderMissing('Email')}</span>
              </p>
            </div>
          </div>
          <Button variant="ghost" size="icon" onClick={onClose} className="rounded-full hover:bg-black/5">
            &times;
          </Button>
        </div>
      </div>

      {/* Check-in / Execution Action Bar */}
      {appointmentId && (
        <div className="bg-background px-5 py-3 border-b flex gap-2 overflow-x-auto shadow-sm z-20">
          <Button size="sm" variant="outline" className="flex-1 flex gap-2 font-medium" onClick={handleCheckIn}><Clock className="h-4 w-4 text-indigo-500"/> Check In</Button>
          <Button size="sm" variant="default" className="flex-1 flex gap-2 font-medium bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-700 hover:to-purple-700" onClick={handleStart}><Play className="h-4 w-4"/> Start Appt</Button>
          <Button size="sm" variant="secondary" className="flex-1 flex gap-2 font-medium bg-status-success/10 text-emerald-700 hover:bg-emerald-100 dark:bg-emerald-950/50 dark:text-emerald-400" onClick={() => setOutcomeModalOpen(true)}><CheckCircle className="h-4 w-4"/> Complete</Button>
        </div>
      )}

      <Tabs value={activeTab} onValueChange={setActiveTab} className="flex-1 flex flex-col min-h-0">
        <div className="border-b overflow-x-auto custom-scrollbar">
          <TabsList className="inline-flex w-max min-w-full justify-start h-12 p-1 bg-transparent">
            <TabsTrigger value="summary" className="data-[state=active]:bg-muted">Summary</TabsTrigger>
            <TabsTrigger value="assignment" className="data-[state=active]:bg-muted">Assignment</TabsTrigger>
            <TabsTrigger value="comms" className="data-[state=active]:bg-muted">Comms</TabsTrigger>
            <TabsTrigger value="files" className="data-[state=active]:bg-muted">Files</TabsTrigger>
            <TabsTrigger value="tasks" className="data-[state=active]:bg-muted">Tasks</TabsTrigger>
            <TabsTrigger value="finance" className="data-[state=active]:bg-muted">Finance</TabsTrigger>
            <TabsTrigger value="outcome" className="data-[state=active]:bg-muted">Outcome</TabsTrigger>
            <TabsTrigger value="history" className="data-[state=active]:bg-muted">History</TabsTrigger>
          </TabsList>
        </div>

        <ScrollArea className="flex-1 p-5">
          <TabsContent value="summary" className="mt-0 space-y-6">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Appointment Number</p>
                <p className="text-sm font-medium">{apt360?.appointment?.id?.substring(0,8) || renderMissing('Appointment Number')}</p>
              </div>
              <div className="space-y-1">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Service</p>
                <p className="text-sm font-medium">{apt360?.appointment?.service?.name || request?.serviceName || renderMissing('Service')}</p>
              </div>
              <div className="space-y-1">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Date & Time</p>
                <p className="text-sm font-medium">
                  {apt360?.appointment?.start_at ? 
                    `${new Date(apt360.appointment.start_at).toLocaleDateString()} ${new Date(apt360.appointment.start_at).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}` 
                    : renderMissing('Date & Time')}
                </p>
              </div>
              <div className="space-y-1">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Duration</p>
                <p className="text-sm font-medium">{apt360?.appointment?.duration_minutes ? `${apt360.appointment.duration_minutes} mins` : renderMissing('Duration')}</p>
              </div>
              <div className="space-y-1">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Location / Room</p>
                <p className="text-sm font-medium">{apt360?.appointment?.room?.name || renderMissing('Room')}</p>
              </div>
              <div className="space-y-1">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Budget</p>
                <p className="text-sm font-medium">{apt360?.appointment?.budget ? `$${apt360.appointment.budget}` : renderMissing('Budget')}</p>
              </div>
              <div className="space-y-1">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Guests</p>
                <p className="text-sm font-medium">{apt360?.appointment?.guests_count || renderMissing('Guest Count')}</p>
              </div>
            </div>
          </TabsContent>

          <TabsContent value="assignment" className="mt-0 space-y-6">
             <div className="space-y-4">
               <h3 className="font-semibold text-xs uppercase text-indigo-600 dark:text-indigo-400 tracking-wider">Current Assignment</h3>
               <div className="flex flex-col gap-2">
                 <Select 
                    value={apt360?.appointment?.employee_id || ''} 
                    onValueChange={handleAssignStaff}
                  >
                    <SelectTrigger className="w-full">
                      <SelectValue placeholder="Select Staff Member..." />
                    </SelectTrigger>
                    <SelectContent>
                      {staff.map((s: any) => (
                        <SelectItem key={s.id} value={s.id}>
                          {s.first_name} {s.last_name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  {!apt360?.appointment?.employee_id && renderMissing('Assigned Staff')}
               </div>
             </div>

             <div className="space-y-4">
              <h3 className="font-semibold text-xs uppercase text-indigo-600 dark:text-indigo-400 tracking-wider flex items-center gap-1.5"><Sparkles className="h-3 w-3"/> AI Assignment Recommendations</h3>
              {aiRecs.length > 0 ? (
                <div className="space-y-3">
                  {aiRecs.map((rec: any, idx: number) => (
                    <Card key={rec.id} className={`overflow-hidden border transition-all ${idx === 0 ? 'border-indigo-300 shadow-md ring-1 ring-indigo-500/20 bg-indigo-50/30' : 'opacity-80 hover:opacity-100'}`}>
                      <CardContent className="p-4">
                        <div className="flex justify-between items-start mb-2">
                          <div className="flex items-center gap-3">
                            <Avatar className="h-8 w-8 border bg-white">
                              <AvatarFallback className="bg-indigo-100 text-indigo-700 text-xs">
                                {rec.employee?.first_name?.[0]}{rec.employee?.last_name?.[0]}
                              </AvatarFallback>
                            </Avatar>
                            <div>
                              <p className="font-semibold text-sm">{rec.employee?.first_name} {rec.employee?.last_name}</p>
                              <p className="text-xs text-muted-foreground">{rec.employee?.role || 'Staff'}</p>
                            </div>
                          </div>
                          <Badge variant={idx === 0 ? "default" : "secondary"} className={idx === 0 ? "bg-indigo-600" : ""}>
                            {rec.score}% Match
                          </Badge>
                        </div>
                        
                        <div className="text-xs text-muted-foreground mt-3 bg-muted/30 p-2 rounded-md">
                          {rec.reasoning || "AI determined this is an optimal match."}
                        </div>
                        
                        {appointmentId && apt360?.appointment?.employee_id !== rec.employee_id && (
                          <Button 
                            size="sm" 
                            variant="outline" 
                            className="w-full mt-3 h-8 text-xs bg-white hover:bg-indigo-50 hover:text-indigo-700 transition-colors"
                            onClick={() => handleAssignStaff(rec.employee_id)}
                            disabled={assignMutation.isPending}
                          >
                            Assign to {rec.employee?.first_name}
                          </Button>
                        )}
                      </CardContent>
                    </Card>
                  ))}
                </div>
              ) : (
                <div className="text-center p-6 border rounded-md border-dashed bg-muted/5">
                  <div className="h-10 w-10 rounded-full bg-indigo-100 text-indigo-500 flex items-center justify-center mx-auto mb-3">
                    <Sparkles className="h-5 w-5" />
                  </div>
                  <p className="text-sm font-medium">No AI recommendations available</p>
                  <p className="text-xs text-muted-foreground mt-1">This appointment has not been processed by the AI matching engine yet.</p>
                </div>
              )}
            </div>
          </TabsContent>

          <TabsContent value="comms" className="mt-0 space-y-4 h-full flex flex-col">
            <div className="flex gap-2 mb-2">
              <Button size="sm" variant="outline" className="flex-1"><MessageSquare className="h-4 w-4 mr-2"/> SMS</Button>
              <Button size="sm" variant="outline" className="flex-1"><Mail className="h-4 w-4 mr-2"/> Email</Button>
              <Button size="sm" variant="outline" className="flex-1"><Phone className="h-4 w-4 mr-2"/> Log Call</Button>
            </div>
            
            <div className="flex-1 border rounded-md p-4 bg-muted/10 space-y-4 mb-4 min-h-[200px] overflow-y-auto">
              {apt360?.communications?.length ? (
                apt360.communications.map((msg: any) => (
                  <div key={msg.id} className={`flex ${msg.direction === 'outbound' ? 'justify-end' : ''}`}>
                    <div className={`${msg.direction === 'outbound' ? 'bg-primary text-primary-foreground rounded-tr-none' : 'bg-primary/10 text-foreground rounded-tl-none'} p-3 rounded-lg max-w-[85%] text-sm`}>
                      {msg.content}
                    </div>
                  </div>
                ))
              ) : (
                <div className="flex items-center justify-center h-full text-muted-foreground text-sm italic">
                  No communications yet
                </div>
              )}
            </div>

            <div className="flex gap-2">
              <Input 
                placeholder="Type a message..." 
                className="flex-1" 
                value={newComm}
                onChange={(e) => setNewComm(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') handleSendComm(); }}
              />
              <Button size="icon" onClick={handleSendComm} disabled={addCommMutation.isPending || !newComm.trim()}>
                <Play className="h-4 w-4"/>
              </Button>
            </div>
          </TabsContent>

          <TabsContent value="files" className="mt-0 space-y-4">
             <div className="flex justify-between items-center mb-4">
              <h3 className="font-semibold text-sm text-muted-foreground">Attached Files & Photos</h3>
              <Button size="sm" variant="outline">Upload</Button>
            </div>
            <div className="grid grid-cols-2 gap-3">
              {apt360?.files?.length ? (
                apt360.files.map((f: any) => (
                  <Card key={f.id} className="overflow-hidden">
                    <div className="h-24 bg-muted flex items-center justify-center">
                      <FileText className="h-8 w-8 text-muted-foreground/50"/>
                    </div>
                    <CardContent className="p-2 text-xs truncate font-medium">{f.name}</CardContent>
                  </Card>
                ))
              ) : (
                <p className="text-xs text-muted-foreground col-span-2">{renderMissing('Files')}</p>
              )}
            </div>
          </TabsContent>

          <TabsContent value="tasks" className="mt-0 space-y-4">
            {/* Internal Notes & Tasks logic here */}
            <div className="space-y-3">
              <h3 className="font-semibold text-sm uppercase text-muted-foreground tracking-wider flex justify-between">
                Internal Notes
                <Button variant="link" size="sm" className="h-auto p-0" onClick={() => setShowNoteInput(!showNoteInput)}>
                  {showNoteInput ? 'Cancel' : 'Add Note'}
                </Button>
              </h3>
              
              {showNoteInput && (
                <div className="space-y-2 mb-4">
                  <Textarea 
                    placeholder="Enter internal note..." 
                    value={newNote} 
                    onChange={(e) => setNewNote(e.target.value)}
                    className="text-sm"
                  />
                  <Button size="sm" onClick={handleAddNote} disabled={addNoteMutation.isPending || !newNote.trim()}>
                    {addNoteMutation.isPending ? 'Saving...' : 'Save Note'}
                  </Button>
                </div>
              )}

              {apt360?.notes?.length ? (
                apt360.notes.map((note: any) => (
                  <Card key={note.id} className="bg-yellow-50/50 dark:bg-yellow-900/10 border-yellow-200 dark:border-yellow-900 shadow-none mb-2">
                    <CardContent className="p-3 text-sm">
                      <p className="font-medium text-xs text-yellow-800 dark:text-yellow-500 mb-1">Note ΓÇó {new Date(note.created_at).toLocaleString()}</p>
                      {note.content}
                    </CardContent>
                  </Card>
                ))
              ) : (
                <Card className="bg-yellow-50/50 dark:bg-yellow-900/10 border-yellow-200 dark:border-yellow-900 shadow-none">
                  <CardContent className="p-3 text-sm flex items-center justify-center min-h-[60px]">
                    <p className="text-muted-foreground italic">No internal notes.</p>
                  </CardContent>
                </Card>
              )}
            </div>

            <div className="space-y-3 mt-6">
              <h3 className="font-semibold text-sm uppercase text-muted-foreground tracking-wider flex justify-between">
                Next Actions
                <Button variant="link" size="sm" className="h-auto p-0" onClick={() => setShowTaskInput(!showTaskInput)}>
                  {showTaskInput ? 'Cancel' : 'Add Task'}
                </Button>
              </h3>
              
              {showTaskInput && (
                <div className="space-y-2 mb-4">
                  <Input 
                    placeholder="Task title..." 
                    value={newTask} 
                    onChange={(e) => setNewTask(e.target.value)}
                    className="text-sm"
                  />
                  <Button size="sm" onClick={handleAddTask} disabled={addTaskMutation.isPending || !newTask.trim()}>
                    {addTaskMutation.isPending ? 'Saving...' : 'Save Task'}
                  </Button>
                </div>
              )}

              {apt360?.tasks?.length ? (
                apt360.tasks.map((task: any) => (
                  <div key={task.id} className="border rounded-md p-3 text-sm flex items-start gap-3">
                    <input type="checkbox" className="mt-1" />
                    <div>
                      <p className="font-medium">{task.title}</p>
                      <p className="text-muted-foreground text-xs">{task.due_date ? `Due ${task.due_date}` : 'No due date'} ΓÇó Assigned to {task.assigned_to || 'Unassigned'}</p>
                    </div>
                  </div>
                ))
              ) : (
                <div className="border rounded-md p-3 text-sm text-muted-foreground italic text-center bg-muted/10 min-h-[60px] flex items-center justify-center">
                  No tasks or next actions
                </div>
              )}
            </div>
          </TabsContent>

          <TabsContent value="finance" className="mt-0 space-y-6">
            {(!apt360?.payments?.length && !apt360?.invoices?.length) ? (
              <div className="flex items-center justify-center h-32 border rounded-md bg-muted/10 text-muted-foreground text-sm italic">
                {renderMissing('Financial Records')}
              </div>
            ) : (
              <>
                {apt360?.payments?.map((payment: any) => (
                  <Card key={payment.id}>
                    <CardHeader className="p-4 pb-2">
                      <CardTitle className="text-lg flex justify-between">
                        {payment.title || 'Payment'}
                        <Badge variant="default" className="bg-status-success">{payment.status || 'PAID'}</Badge>
                      </CardTitle>
                    </CardHeader>
                    <CardContent className="p-4 pt-0 text-sm">
                      <div className="flex justify-between mb-1">
                        <span className="text-muted-foreground">Amount</span>
                        <span className="font-medium">${payment.amount?.toFixed(2)}</span>
                      </div>
                      <div className="flex justify-between mb-1">
                        <span className="text-muted-foreground">Method</span>
                        <span className="font-medium flex items-center gap-1"><DollarSign className="h-3 w-3"/> {payment.method || 'Credit Card'} {payment.last4 ? `(...${payment.last4})` : ''}</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-muted-foreground">Paid On</span>
                        <span className="font-medium">{payment.paid_at ? new Date(payment.paid_at).toLocaleDateString() : 'N/A'}</span>
                      </div>
                    </CardContent>
                  </Card>
                ))}

                {apt360?.invoices?.map((invoice: any) => (
                  <Card key={invoice.id}>
                    <CardHeader className="p-4 pb-2">
                      <CardTitle className="text-lg flex justify-between">
                        {invoice.title || 'Invoice'}
                        <Badge variant="outline" className="text-status-warning border-amber-500">{invoice.status || 'PENDING'}</Badge>
                      </CardTitle>
                    </CardHeader>
                    <CardContent className="p-4 pt-0 text-sm">
                      <div className="flex justify-between mb-1">
                        <span className="text-muted-foreground">Balance</span>
                        <span className="font-medium">${invoice.balance?.toFixed(2)}</span>
                      </div>
                      <Button size="sm" className="w-full mt-3">Request Payment via SMS</Button>
                    </CardContent>
                  </Card>
                ))}
              </>
            )}
          </TabsContent>

          <TabsContent value="outcome" className="mt-0 space-y-4">
             <div className="space-y-4">
               <h3 className="font-semibold text-xs uppercase text-muted-foreground tracking-wider">Appointment Outcome</h3>
               {apt360?.appointment?.outcome ? (
                 <div className="border rounded-md p-4 bg-muted/5">
                   <p className="font-medium">{apt360.appointment.outcome}</p>
                   {apt360.appointment.outcome_notes && <p className="text-sm text-muted-foreground mt-2">{apt360.appointment.outcome_notes}</p>}
                 </div>
               ) : (
                 <div className="border rounded-md p-4 bg-muted/5 text-center flex flex-col items-center justify-center min-h-[100px]">
                   <p className="text-sm text-muted-foreground italic mb-3">No outcome recorded yet.</p>
                   <Button size="sm" onClick={() => setOutcomeModalOpen(true)}>Record Outcome</Button>
                 </div>
               )}
             </div>
          </TabsContent>

          <TabsContent value="history" className="mt-0 space-y-4">
             <div className="relative border-l border-muted ml-3 space-y-6 pb-4">
                {/* Timeline UI */}
                <div className="relative pl-6">
                  <div className="absolute left-[-5px] top-1 h-2.5 w-2.5 rounded-full bg-indigo-500 ring-4 ring-background"></div>
                  <p className="text-sm font-medium">Appointment Created</p>
                  <p className="text-xs text-muted-foreground">{apt360?.appointment?.created_at ? new Date(apt360.appointment.created_at).toLocaleString() : 'Unknown Date'}</p>
                </div>
             </div>
          </TabsContent>
        </ScrollArea>
      </Tabs>
      
      {apt360?.appointment && (
        <OutcomeModal 
          appointment={apt360.appointment}
          isOpen={outcomeModalOpen}
          onClose={() => setOutcomeModalOpen(false)}
        />
      )}
    </div>
  );
}

import React, { useRef } from 'react';
import FullCalendar from '@fullcalendar/react';
import timeGridPlugin from '@fullcalendar/timegrid';
import dayGridPlugin from '@fullcalendar/daygrid';
import interactionPlugin from '@fullcalendar/interaction';
import { Card, CardHeader, CardTitle, CardContent } from '@vowos/design-system';
import { getActiveDataPlane } from '@/lib/supabase';
import { toast } from 'sonner';

const INITIAL_SEED_APPOINTMENTS: any[] = getActiveDataPlane() === 'demo' ? [] : [];

export default function ConfirmedAppointments() {
  const calendarRef = useRef<FullCalendar>(null);

  const handleViewChange = (view: 'timeGridDay' | 'timeGridWeek' | 'dayGridMonth') => {
    if (calendarRef.current) {
      calendarRef.current.getApi().changeView(view);
    }
  };

  return (
    <div className="p-6 h-[calc(100vh-64px)] flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold tracking-tight">Confirmed Appointments</h1>
        <div className="flex gap-2 bg-muted p-1 rounded-md">
          <button onClick={() => handleViewChange('timeGridDay')} className="px-3 py-1.5 rounded-md text-sm font-medium hover:bg-white hover:shadow-sm transition-all focus:bg-white focus:shadow-sm">Day</button>
          <button onClick={() => handleViewChange('timeGridWeek')} className="px-3 py-1.5 rounded-md text-sm font-medium hover:bg-white hover:shadow-sm transition-all focus:bg-white focus:shadow-sm">Week</button>
          <button onClick={() => handleViewChange('dayGridMonth')} className="px-3 py-1.5 rounded-md text-sm font-medium hover:bg-white hover:shadow-sm transition-all focus:bg-white focus:shadow-sm">Month</button>
        </div>
      </div>
      
      <Card className="flex-grow flex flex-col min-h-0">
        <CardHeader className="py-4">
          <CardTitle>Master Schedule</CardTitle>
          <p className="text-sm text-muted-foreground">
            View all confirmed appointments.
          </p>
        </CardHeader>
        <CardContent className="flex-grow p-4 relative">
          <div className="absolute inset-4">
            <FullCalendar
              ref={calendarRef}
              plugins={[timeGridPlugin, dayGridPlugin, interactionPlugin]}
              initialView="timeGridWeek"
              headerToolbar={{
                left: 'prev,next today',
                center: 'title',
                right: '' // Custom view buttons are outside
              }}
              allDaySlot={false}
              slotMinTime="08:00:00"
              slotMaxTime="20:00:00"
              events={INITIAL_SEED_APPOINTMENTS}
              height="100%"
              eventClick={(info) => {
                toast(`Appointment Details: ${info.event.title}`, {
                  description: `Time: ${info.event.start?.toLocaleTimeString()} - ${info.event.end?.toLocaleTimeString()}`
                });
              }}
            />
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from '@vowos/design-system';
import { Button } from '@vowos/design-system';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@vowos/design-system';
import { Input } from '@vowos/design-system';
import { Label } from '@vowos/design-system';
import { useStaffProfiles, useAppointments, useEmployeeSchedules } from '@/lib/services/schedulingService';
import { useVowosData } from '@/contexts/VowosDataContext';
import { supabase } from '@/lib/supabase';
import { useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import { AlertCircle, CalendarClock, UserX } from 'lucide-react';
import { Alert, AlertDescription, AlertTitle } from '@vowos/design-system';

export function EmployeeCalloutModal({ open, onOpenChange }: { open: boolean, onOpenChange: (open: boolean) => void }) {
  const { businessId, activeLocation } = useVowosData();
  const { data: staff = [] } = useStaffProfiles();
  const { data: appointments = [] } = useAppointments(businessId, activeLocation);
  const { data: schedules = [] } = useEmployeeSchedules(businessId, activeLocation);
  const queryClient = useQueryClient();

  const [employeeId, setEmployeeId] = useState<string>('');
  const [dateStr, setDateStr] = useState<string>(new Date().toISOString().split('T')[0]);
  const [reason, setReason] = useState<string>('');
  const [isProcessing, setIsProcessing] = useState(false);

  const selectedEmployee = staff.find((s: any) => s.id === employeeId);

  // Find impacted shift and appointments
  const impactedShift = schedules.find((s: any) => 
    s.employee_id === employeeId && 
    s.shift_date === dateStr &&
    s.status === 'published'
  );

  const impactedAppointments = appointments.filter((a: any) => {
    if (a.employee_id !== employeeId || a.status === 'Canceled') return false;
    const apptDate = a.start_at ? new Date(a.start_at).toISOString().split('T')[0] : '';
    return apptDate === dateStr;
  });

  const handleExecuteCallout = async () => {
    if (!employeeId || !dateStr) return;
    setIsProcessing(true);

    try {
      // 1. Cancel the shift
      if (impactedShift) {
        await supabase.from('employee_schedules')
          .update({ status: 'canceled' })
          .eq('id', impactedShift.id);
      }

      // 2. Reassign appointments via AI (Simulated for now due to lack of batch RPC)
      // We will just cancel them and create new requests for them so the AI can assign them.
      for (const appt of impactedAppointments) {
        await supabase.from('appointments').update({ status: 'Canceled', confirmation_status: 'Canceled' }).eq('id', appt.id);
        
        // Push back into the request queue
        if (appt.request_id) {
            await supabase.from('appointment_requests').update({ status: 'new' }).eq('id', appt.request_id);
        }
      }

      queryClient.invalidateQueries({ queryKey: ['appointments'] });
      queryClient.invalidateQueries({ queryKey: ['employee_schedules'] });
      queryClient.invalidateQueries({ queryKey: ['appointment_requests'] });
      
      toast.success('Callout processed. Appointments moved to AI Planner queue.');
      onOpenChange(false);
    } catch (err: any) {
      toast.error(err.message || 'Failed to process callout');
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <UserX className="h-5 w-5 text-red-500" />
            Process Employee Callout
          </DialogTitle>
          <DialogDescription>
            Record an unexpected absence. The AI Planner will immediately attempt to reassign impacted appointments.
          </DialogDescription>
        </DialogHeader>

        <div className="grid gap-4 py-4">
          <div className="grid grid-cols-4 items-center gap-4">
            <Label className="text-right font-medium">Employee</Label>
            <div className="col-span-3">
              <Select value={employeeId} onValueChange={setEmployeeId}>
                <SelectTrigger>
                  <SelectValue placeholder="Select staff member" />
                </SelectTrigger>
                <SelectContent>
                  {staff.map((s: any) => (
                    <SelectItem key={s.id} value={s.id}>{s.first_name} {s.last_name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-4 items-center gap-4">
            <Label className="text-right font-medium">Date</Label>
            <Input 
              type="date" 
              className="col-span-3" 
              value={dateStr}
              onChange={(e) => setDateStr(e.target.value)}
            />
          </div>

          <div className="grid grid-cols-4 items-center gap-4">
            <Label className="text-right font-medium">Reason</Label>
            <Input 
              placeholder="e.g., Sick, Personal Emergency"
              className="col-span-3"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
            />
          </div>

          {employeeId && dateStr && (
            <Alert variant="destructive" className="mt-4 bg-red-50 border-red-200">
              <AlertCircle className="h-4 w-4" />
              <AlertTitle>Impact Analysis</AlertTitle>
              <AlertDescription className="mt-2 text-sm space-y-1">
                {impactedShift ? (
                  <p>ΓÇó <strong>1 Shift</strong> will be canceled ({impactedShift.start_time} - {impactedShift.end_time})</p>
                ) : (
                  <p>ΓÇó No published shift found for this date.</p>
                )}
                <p>ΓÇó <strong>{impactedAppointments.length} Appointments</strong> will be sent to the AI Planner for immediate reassignment.</p>
              </AlertDescription>
            </Alert>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button>
          <Button 
            variant="destructive" 
            onClick={handleExecuteCallout}
            disabled={!employeeId || isProcessing}
          >
            {isProcessing ? 'Processing...' : 'Execute Callout & Reassign'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@vowos/design-system';
import { Button } from '@vowos/design-system';
import { Label } from '@vowos/design-system';
import { Input } from '@vowos/design-system';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@vowos/design-system';
import { useStaffProfiles, useBusiness } from '@/lib/services/schedulingService';
import { 
  useCreateEmployeeSchedule, 
  useUpdateEmployeeSchedule, 
  useDeleteEmployeeSchedule 
} from '@/lib/services/schedulingService';
import { toast } from 'sonner';
import { Textarea } from '@vowos/design-system';

export interface EmployeeShiftModalProps {
  isOpen: boolean;
  onClose: () => void;
  locationId?: string;
  initialData?: { 
    id?: string;
    employee_id?: string; 
    start?: string; 
    end?: string; 
    shift_type?: string;
    department?: string;
    unpaid_break_minutes?: number;
    paid_break_minutes?: number;
    notes?: string;
  } | null;
}

export function EmployeeShiftModal({ isOpen, onClose, locationId, initialData }: EmployeeShiftModalProps) {
  const { data: staff = [] } = useStaffProfiles();
  const { data: business } = useBusiness();
  
  const createMutation = useCreateEmployeeSchedule();
  const updateMutation = useUpdateEmployeeSchedule();
  const deleteMutation = useDeleteEmployeeSchedule();

  const [employeeId, setEmployeeId] = useState('');
  const [date, setDate] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [shiftType, setShiftType] = useState('Regular');
  const [department, setDepartment] = useState('Sales');
  const [unpaidBreak, setUnpaidBreak] = useState('0');
  const [paidBreak, setPaidBreak] = useState('0');
  const [notes, setNotes] = useState('');

  useEffect(() => {
    if (initialData && isOpen) {
      setEmployeeId(initialData.employee_id || '');
      if (initialData.start) {
        const start = new Date(initialData.start);
        setDate(start.toISOString().split('T')[0]);
        setStartTime(start.toTimeString().substring(0, 5));
      } else {
        setDate(new Date().toISOString().split('T')[0]);
        setStartTime('09:00');
      }
      if (initialData.end) {
        const end = new Date(initialData.end);
        setEndTime(end.toTimeString().substring(0, 5));
      } else {
        setEndTime('17:00');
      }
      setShiftType(initialData.shift_type || 'Regular');
      setDepartment(initialData.department || 'Sales');
      setUnpaidBreak((initialData.unpaid_break_minutes || 0).toString());
      setPaidBreak((initialData.paid_break_minutes || 0).toString());
      setNotes(initialData.notes || '');
    } else if (isOpen) {
      setEmployeeId('');
      setDate(new Date().toISOString().split('T')[0]);
      setStartTime('09:00');
      setEndTime('17:00');
      setShiftType('Regular');
      setDepartment('Sales');
      setUnpaidBreak('0');
      setPaidBreak('0');
      setNotes('');
    }
  }, [initialData, isOpen]);

  const handleSave = async () => {
    if (!employeeId || !date || !startTime || !endTime) {
      toast.error('Please fill out Employee, Date, Start Time, and End Time');
      return;
    }

    if (!business?.id || !locationId) {
      toast.error('Missing business or location context');
      return;
    }

    const startObj = new Date(`${date}T${startTime}:00`);
    const endObj = new Date(`${date}T${endTime}:00`);

    const shiftData = {
      businessId: business.id,
      locationId,
      employeeId,
      shiftDate: date,
      startAt: startObj.toISOString(),
      endAt: endObj.toISOString(),
      status: 'published',
      shiftType,
      department,
      unpaidBreakMinutes: parseInt(unpaidBreak) || 0,
      paidBreakMinutes: parseInt(paidBreak) || 0,
      notes
    };

    try {
      if (initialData?.id) {
        await updateMutation.mutateAsync({ id: initialData.id, ...shiftData });
        toast.success('Shift updated successfully');
      } else {
        await createMutation.mutateAsync(shiftData);
        toast.success('Shift added successfully');
      }
      onClose();
    } catch (err: any) {
      console.error(err);
      toast.error(err.message || 'Failed to save shift');
    }
  };

  const handleDelete = async () => {
    if (!initialData?.id) return;
    try {
      await deleteMutation.mutateAsync(initialData.id);
      toast.success('Shift deleted');
      onClose();
    } catch (err: any) {
      console.error(err);
      toast.error(err.message || 'Failed to delete shift');
    }
  };

  const isSubmitting = createMutation.isPending || updateMutation.isPending || deleteMutation.isPending;

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>{initialData?.id ? 'Edit Shift' : 'Add Shift'}</DialogTitle>
        </DialogHeader>
        <div className="grid gap-4 py-4">
          <div className="grid grid-cols-4 items-center gap-4">
            <Label className="text-right">Employee</Label>
            <Select value={employeeId} onValueChange={setEmployeeId}>
              <SelectTrigger className="col-span-3">
                <SelectValue placeholder="Select an employee" />
              </SelectTrigger>
              <SelectContent>
                {staff.map((s: any) => (
                  <SelectItem key={s.id} value={s.id}>{s.first_name} {s.last_name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="grid grid-cols-4 items-center gap-4">
            <Label className="text-right">Shift Type</Label>
            <Select value={shiftType} onValueChange={setShiftType}>
              <SelectTrigger className="col-span-3">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="Regular">Regular</SelectItem>
                <SelectItem value="Opening">Opening</SelectItem>
                <SelectItem value="Closing">Closing</SelectItem>
                <SelectItem value="Training">Training</SelectItem>
                <SelectItem value="On-Call">On-Call</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="grid grid-cols-4 items-center gap-4">
            <Label className="text-right">Department</Label>
            <Select value={department} onValueChange={setDepartment}>
              <SelectTrigger className="col-span-3">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="Sales">Sales (Bridal)</SelectItem>
                <SelectItem value="Alterations">Alterations</SelectItem>
                <SelectItem value="Front Desk">Front Desk</SelectItem>
                <SelectItem value="Management">Management</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="grid grid-cols-4 items-center gap-4">
            <Label className="text-right">Date</Label>
            <Input type="date" className="col-span-3" value={date} onChange={e => setDate(e.target.value)} />
          </div>
          <div className="grid grid-cols-4 items-center gap-4">
            <Label className="text-right">Start Time</Label>
            <Input type="time" className="col-span-3" value={startTime} onChange={e => setStartTime(e.target.value)} />
          </div>
          <div className="grid grid-cols-4 items-center gap-4">
            <Label className="text-right">End Time</Label>
            <Input type="time" className="col-span-3" value={endTime} onChange={e => setEndTime(e.target.value)} />
          </div>

          <div className="grid grid-cols-4 items-center gap-4">
            <Label className="text-right text-xs">Unpaid Break (min)</Label>
            <Input type="number" className="col-span-1" value={unpaidBreak} onChange={e => setUnpaidBreak(e.target.value)} min="0" />
            
            <Label className="text-right text-xs">Paid Break (min)</Label>
            <Input type="number" className="col-span-1" value={paidBreak} onChange={e => setPaidBreak(e.target.value)} min="0" />
          </div>

          <div className="grid grid-cols-4 items-start gap-4">
            <Label className="text-right mt-2">Notes</Label>
            <Textarea 
              className="col-span-3 resize-none" 
              rows={2} 
              placeholder="Internal notes for this shift..."
              value={notes} 
              onChange={e => setNotes(e.target.value)} 
            />
          </div>

        </div>
        <DialogFooter className="flex justify-between w-full sm:justify-between">
          <div>
            {initialData?.id && (
              <Button variant="destructive" onClick={handleDelete} disabled={isSubmitting}>Delete</Button>
            )}
          </div>
          <div className="flex gap-2">
            <Button variant="outline" onClick={onClose} disabled={isSubmitting}>Cancel</Button>
            <Button onClick={handleSave} disabled={isSubmitting}>Save Shift</Button>
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@vowos/design-system';
import { Button } from '@vowos/design-system';
import { Label } from '@vowos/design-system';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@vowos/design-system';
import { useBusiness, useCustomers, useServices, useStaffProfiles, useAssignAppointmentRequest } from '@/lib/services/schedulingService';
import { useVowosData } from '@/contexts/VowosDataContext';
import { supabase } from '@/lib/supabase';
import { useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';

export interface NewAppointmentModalProps {
  isOpen: boolean;
  onClose: () => void;
  initialData?: { start_at?: string; employee_id?: string } | null;
}

export function NewAppointmentModal({ isOpen, onClose, initialData }: NewAppointmentModalProps) {
  const queryClient = useQueryClient();
  const { activeLocation } = useVowosData();
  const { data: business } = useBusiness();
  const businessId = business?.id;
  
  const { data: customers = [] } = useCustomers(businessId);
  const { data: services = [] } = useServices(businessId);
  const { data: staff = [] } = useStaffProfiles();
  const assignAppointment = useAssignAppointmentRequest();
  
  const [customerId, setCustomerId] = useState('');
  const [serviceId, setServiceId] = useState('');
  const [employeeId, setEmployeeId] = useState(initialData?.employee_id || '');
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Reset state when opened
  useEffect(() => {
    if (isOpen) {
      setCustomerId('');
      setServiceId('');
    }
  }, [isOpen]);

  const handleSave = async () => {
    if (!customerId || !serviceId || !employeeId) {
      toast.error('Please select customer, service, and employee.');
      return;
    }
    if (!businessId || !activeLocation) {
      toast.error('Missing business or location context.');
      return;
    }
    if (!initialData?.start_at) {
      toast.error('Missing start time.');
      return;
    }

    setIsSubmitting(true);
    try {
      const preferredDate = initialData?.start_at 
        ? new Date(initialData.start_at).toISOString().split('T')[0] 
        : new Date().toISOString().split('T')[0];

      // 1. Create Request
      const requestPayload = {
        business_id: businessId,
        customer_id: customerId,
        service_id: serviceId,
        preferred_location_id: activeLocation,
        preferred_date_1: preferredDate,
        status: 'pending',
        channel: 'in-person'
      };

      const { data: reqData, error: reqError } = await supabase.from('appointment_requests').insert(requestPayload).select().single();
      if (reqError) throw reqError;
      
      // 2. Assign directly using RPC (this enforces shift/conflict validation)
      const service = services.find((s: any) => s.id === serviceId);
      const durationMs = (service?.duration_minutes || 60) * 60 * 1000;
      const startAt = new Date(initialData.start_at);
      const endAt = new Date(startAt.getTime() + durationMs);

      await assignAppointment.mutateAsync({
        requestId: reqData.id,
        employeeId: employeeId,
        roomId: '00000000-0000-0000-0000-000000000000', // Default room for MVP
        startAt: startAt.toISOString(),
        endAt: endAt.toISOString()
      });
      
      toast.success('Appointment booked successfully!');
      onClose();
    } catch (err: any) {
      console.error(err);
      toast.error(err.message || 'Failed to book appointment. Ensure employee is scheduled and has no conflicts.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>New Appointment Booking</DialogTitle>
        </DialogHeader>
        <div className="grid gap-6 py-4">
          {initialData?.start_at && (
            <div className="bg-muted/50 p-3 rounded-md text-sm text-muted-foreground flex justify-between items-center">
              <span>Selected Date:</span>
              <span className="font-medium text-foreground">
                {new Date(initialData.start_at).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' })}
              </span>
            </div>
          )}
          
          <div className="space-y-2">
            <Label>Customer</Label>
            <Select value={customerId} onValueChange={setCustomerId}>
              <SelectTrigger>
                <SelectValue placeholder="Search or select customer..." />
              </SelectTrigger>
              <SelectContent>
                {customers.map((c: any) => (
                  <SelectItem key={c.id} value={c.id}>{c.first_name} {c.last_name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          
          <div className="space-y-2">
            <Label>Service</Label>
            <Select value={serviceId} onValueChange={setServiceId}>
              <SelectTrigger>
                <SelectValue placeholder="Select a service..." />
              </SelectTrigger>
              <SelectContent>
                {services.map((s: any) => (
                  <SelectItem key={s.id} value={s.id}>{s.name} ({s.duration_minutes} min)</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label>Employee</Label>
            <Select value={employeeId} onValueChange={setEmployeeId}>
              <SelectTrigger>
                <SelectValue placeholder="Select staff member..." />
              </SelectTrigger>
              <SelectContent>
                {staff.map((s: any) => (
                  <SelectItem key={s.id} value={s.id}>{s.first_name} {s.last_name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={isSubmitting}>Cancel</Button>
          <Button onClick={handleSave} disabled={isSubmitting}>Submit Request</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@vowos/design-system';
import { Button } from '@vowos/design-system';
import { Label } from '@vowos/design-system';
import { Input } from '@vowos/design-system';
import { Textarea } from '@vowos/design-system';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@vowos/design-system';
import { Checkbox } from '@vowos/design-system';
import { 
  useBusiness, 
  useCustomers, 
  useServices, 
  useStaffProfiles, 
  useActiveBusinessContext,
  useCreateRequest 
} from '@/lib/services/schedulingService';
import { useVowosData } from '@/contexts/VowosDataContext';
import { toast } from 'sonner';
import { AlertCircle, ChevronLeft, ChevronRight, Check, Plus, Trash, FileText, UserPlus, Search } from 'lucide-react';

export interface NewRequestModalProps {
  isOpen: boolean;
  onClose: () => void;
  initialData?: { start_at?: string; employee_id?: string } | null;
}

type Step = 'CUSTOMER' | 'REQUEST' | 'FILES' | 'REVIEW' | 'SAVE';

export function NewRequestModal({ isOpen, onClose, initialData }: NewRequestModalProps) {
  const activeContext = useActiveBusinessContext();
  const businessId = activeContext.businessId;
  const activeLocation = activeContext.locationId;
  
  const { data: customers = [] } = useCustomers(businessId);
  const { data: services = [] } = useServices(businessId);
  const { data: staff = [] } = useStaffProfiles(businessId);
  
  const createRequestMutation = useCreateRequest();

  const [step, setStep] = useState<Step>('CUSTOMER');

  // Step 1: Customer States
  const [customerMode, setCustomerMode] = useState<'SEARCH' | 'CREATE'>('SEARCH');
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  
  // Create customer fields
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');
  const [prefComm, setPrefComm] = useState<'sms' | 'email' | 'phone'>('sms');
  const [smsConsent, setSmsConsent] = useState(false);
  const [emailConsent, setEmailConsent] = useState(false);
  const [accessibilityNeeds, setAccessibilityNeeds] = useState('');
  const [language, setLanguage] = useState('en');
  const [custNotes, setCustNotes] = useState('');

  // Duplicate warning
  const [duplicateCustomer, setDuplicateCustomer] = useState<any | null>(null);

  // Step 2: Request Details States
  const [serviceId, setServiceId] = useState('');
  const [prefEmployeeId, setPrefEmployeeId] = useState('');
  const [prefDate1, setPrefDate1] = useState('');
  const [prefWindow1, setPrefWindow1] = useState('morning');
  const [prefDate2, setPrefDate2] = useState('');
  const [prefWindow2, setPrefWindow2] = useState('');
  const [flexibleDate, setFlexibleDate] = useState(false);
  const [flexibleLocation, setFlexibleLocation] = useState(false);
  const [numberGuests, setNumberGuests] = useState(1);
  const [eventDate, setEventDate] = useState('');
  const [budget, setBudget] = useState('');
  const [designerInterest, setDesignerInterest] = useState('');
  const [source, setSource] = useState('Phone');
  const [campaign, setCampaign] = useState('');
  const [reqNotes, setReqNotes] = useState('');

  // Step 3: Files States
  const [fileUrls, setFileUrls] = useState<string[]>([]);
  const [newFileUrl, setNewFileUrl] = useState('');

  // Reset states when opened
  useEffect(() => {
    if (isOpen) {
      setStep('CUSTOMER');
      setCustomerMode('SEARCH');
      setSelectedCustomerId('');
      setFirstName('');
      setLastName('');
      setPhone('');
      setEmail('');
      setPrefComm('sms');
      setSmsConsent(false);
      setEmailConsent(false);
      setAccessibilityNeeds('');
      setLanguage('en');
      setCustNotes('');
      setDuplicateCustomer(null);

      setServiceId('');
      setPrefEmployeeId(initialData?.employee_id || '');
      setPrefDate1(initialData?.start_at ? new Date(initialData.start_at).toISOString().split('T')[0] : '');
      setPrefWindow1('morning');
      setPrefDate2('');
      setPrefWindow2('');
      setFlexibleDate(false);
      setFlexibleLocation(false);
      setNumberGuests(1);
      setEventDate('');
      setBudget('');
      setDesignerInterest('');
      setSource('Phone');
      setCampaign('');
      setReqNotes('');
      setFileUrls([]);
      setNewFileUrl('');
    }
  }, [isOpen, initialData]);

  // Real-time duplicate check
  useEffect(() => {
    if (customerMode === 'CREATE' && (email || phone)) {
      const match = customers.find((c: any) => {
        const emailMatch = email && c.email?.toLowerCase() === email.toLowerCase();
        const phoneMatch = phone && c.phone?.replace(/\D/g, '') === phone.replace(/\D/g, '');
        return emailMatch || phoneMatch;
      });
      setDuplicateCustomer(match || null);
    } else {
      setDuplicateCustomer(null);
    }
  }, [email, phone, customerMode, customers]);

  const handleLinkDuplicate = () => {
    if (duplicateCustomer) {
      setSelectedCustomerId(duplicateCustomer.id);
      setCustomerMode('SEARCH');
      toast.info(`Linked request to existing customer: ${duplicateCustomer.name}`);
    }
  };

  const handleAddFileUrl = () => {
    if (newFileUrl.trim()) {
      setFileUrls([...fileUrls, newFileUrl.trim()]);
      setNewFileUrl('');
    }
  };

  const handleRemoveFileUrl = (idx: number) => {
    setFileUrls(fileUrls.filter((_, i) => i !== idx));
  };

  const validateStep = (): boolean => {
    if (step === 'CUSTOMER') {
      if (customerMode === 'SEARCH' && !selectedCustomerId) {
        toast.error('Please select an existing customer or create a new one.');
        return false;
      }
      if (customerMode === 'CREATE') {
        if (!firstName || !lastName) {
          toast.error('First name and Last name are required.');
          return false;
        }
        if (!email && !phone) {
          toast.error('At least one contact method (email or phone) is required.');
          return false;
        }
      }
    } else if (step === 'REQUEST') {
      if (!serviceId) {
        toast.error('Please select a service.');
        return false;
      }
      if (!prefDate1) {
        toast.error('Preferred date is required.');
        return false;
      }
    }
    return true;
  };

  const handleNext = () => {
    if (!validateStep()) return;
    if (step === 'CUSTOMER') setStep('REQUEST');
    else if (step === 'REQUEST') setStep('FILES');
    else if (step === 'FILES') setStep('REVIEW');
  };

  const handleBack = () => {
    if (step === 'REQUEST') setStep('CUSTOMER');
    else if (step === 'FILES') setStep('REQUEST');
    else if (step === 'REVIEW') setStep('FILES');
  };

  const handleSave = async () => {
    if (!businessId || !activeLocation) {
      toast.error('Missing business or location context.');
      return;
    }

    try {
      const selectedService = services.find((s: any) => s.id === serviceId);
      
      const payload = {
        businessId,
        locationId: activeLocation,
        customer: customerMode === 'SEARCH' ? { id: selectedCustomerId } : {
          name: `${firstName} ${lastName}`,
          email: email || undefined,
          phone: phone || undefined,
          sms_consent: smsConsent,
          email_consent: emailConsent,
          accessibility_needs: accessibilityNeeds || undefined,
          language
        },
        request: {
          service_id: serviceId,
          preferred_employee_id: prefEmployeeId || undefined,
          preferred_date_1: prefDate1,
          preferred_window_1: prefWindow1,
          preferred_date_2: prefDate2 || undefined,
          preferred_window_2: prefWindow2 || undefined,
          flexible_date: flexibleDate,
          flexible_location: flexibleLocation,
          notes: reqNotes || undefined,
          intake_source: source,
          number_of_guests: Number(numberGuests),
          event_date: eventDate || undefined,
          budget_cents: budget ? Math.round(parseFloat(budget) * 100) : undefined,
          designer_interest: designerInterest || undefined,
          campaign_attribution: campaign || undefined
        }
      };

      await createRequestMutation.mutateAsync(payload);
      toast.success('Guided Request Intake completed successfully!');
      onClose();
    } catch (err: any) {
      console.error(err);
      toast.error(err.message || 'Failed to complete guided request intake');
    }
  };

  // Resolve Customer Info for Review Screen
  const reviewCustomerName = customerMode === 'SEARCH'
    ? customers.find((c: any) => c.id === selectedCustomerId)?.name || 'Unknown'
    : `${firstName} ${lastName}`;

  const reviewCustomerEmail = customerMode === 'SEARCH'
    ? customers.find((c: any) => c.id === selectedCustomerId)?.email || 'None'
    : email || 'None';

  const reviewCustomerPhone = customerMode === 'SEARCH'
    ? customers.find((c: any) => c.id === selectedCustomerId)?.phone || 'None'
    : phone || 'None';

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-[650px] max-h-[85vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex justify-between items-center pr-6">
            <span>Guided Request Intake</span>
            <span className="text-xs font-normal text-muted-foreground bg-stone-100 px-2.5 py-1 rounded-full">
              Step {step === 'CUSTOMER' ? '1' : step === 'REQUEST' ? '2' : step === 'FILES' ? '3' : '4'} of 4
            </span>
          </DialogTitle>
        </DialogHeader>

        {/* STEP 1: CUSTOMER */}
        {step === 'CUSTOMER' && (
          <div className="space-y-6 py-4">
            <div className="flex gap-4 p-1 bg-stone-100 rounded-lg">
              <Button 
                type="button"
                variant={customerMode === 'SEARCH' ? 'default' : 'ghost'} 
                className="flex-1 rounded-md"
                onClick={() => setCustomerMode('SEARCH')}
              >
                <Search className="mr-2 h-4 w-4" />
                Search Existing
              </Button>
              <Button 
                type="button"
                variant={customerMode === 'CREATE' ? 'default' : 'ghost'} 
                className="flex-1 rounded-md"
                onClick={() => setCustomerMode('CREATE')}
              >
                <UserPlus className="mr-2 h-4 w-4" />
                Create New
              </Button>
            </div>

            {customerMode === 'SEARCH' ? (
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label>Select Existing Customer</Label>
                  <Select value={selectedCustomerId} onValueChange={setSelectedCustomerId}>
                    <SelectTrigger>
                      <SelectValue placeholder="Choose a customer..." />
                    </SelectTrigger>
                    <SelectContent>
                      {customers.map((c: any) => (
                        <SelectItem key={c.id} value={c.id}>
                          {c.name} {c.email ? `(${c.email})` : ''} {c.phone ? `- ${c.phone}` : ''}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>
            ) : (
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label>First Name *</Label>
                    <Input value={firstName} onChange={(e) => setFirstName(e.target.value)} placeholder="Jane" />
                  </div>
                  <div className="space-y-2">
                    <Label>Last Name *</Label>
                    <Input value={lastName} onChange={(e) => setLastName(e.target.value)} placeholder="Doe" />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label>Phone Number</Label>
                    <Input value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="(555) 000-0000" />
                  </div>
                  <div className="space-y-2">
                    <Label>Email Address</Label>
                    <Input value={email} onChange={(e) => setEmail(e.target.value)} placeholder="jane@example.com" />
                  </div>
                </div>

                {duplicateCustomer && (
                  <div className="bg-status-warning/10 border border-status-warning/20 rounded-lg p-3.5 flex items-start gap-3">
                    <AlertCircle className="h-5 w-5 text-status-warning shrink-0 mt-0.5" />
                    <div className="flex-1">
                      <h5 className="text-sm font-semibold text-amber-900">Duplicate Customer Detected</h5>
                      <p className="text-xs text-status-warning mt-1">
                        We found an existing profile matching this info: <strong>{duplicateCustomer.name}</strong> ({duplicateCustomer.phone || duplicateCustomer.email}).
                      </p>
                      <Button 
                        type="button" 
                        variant="link" 
                        className="p-0 h-auto text-xs font-semibold text-amber-900 hover:text-amber-800 underline mt-2"
                        onClick={handleLinkDuplicate}
                      >
                        Link to this existing customer profile instead
                      </Button>
                    </div>
                  </div>
                )}

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label>Preferred Communication</Label>
                    <Select value={prefComm} onValueChange={(v: any) => setPrefComm(v)}>
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="sms">SMS Text Message</SelectItem>
                        <SelectItem value="email">Email</SelectItem>
                        <SelectItem value="phone">Phone Call</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <Label>Preferred Language</Label>
                    <Select value={language} onValueChange={setLanguage}>
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="en">English</SelectItem>
                        <SelectItem value="es">Spanish</SelectItem>
                        <SelectItem value="fr">French</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                <div className="flex flex-col gap-2 pt-2">
                  <div className="flex items-center space-x-2">
                    <Checkbox id="smsConsent" checked={smsConsent} onCheckedChange={(v) => setSmsConsent(!!v)} />
                    <Label htmlFor="smsConsent" className="text-xs font-normal">Customer consents to receiving SMS updates</Label>
                  </div>
                  <div className="flex items-center space-x-2">
                    <Checkbox id="emailConsent" checked={emailConsent} onCheckedChange={(v) => setEmailConsent(!!v)} />
                    <Label htmlFor="emailConsent" className="text-xs font-normal">Customer consents to receiving Email promotional materials & updates</Label>
                  </div>
                </div>

                <div className="space-y-2">
                  <Label>Accessibility Needs</Label>
                  <Input value={accessibilityNeeds} onChange={(e) => setAccessibilityNeeds(e.target.value)} placeholder="e.g. Wheelchair access, Sign language support" />
                </div>

                <div className="space-y-2">
                  <Label>Customer Internal Notes</Label>
                  <Textarea value={custNotes} onChange={(e) => setCustNotes(e.target.value)} placeholder="VIP, referred by..." rows={2} />
                </div>
              </div>
            )}
          </div>
        )}

        {/* STEP 2: REQUEST DETAILS */}
        {step === 'REQUEST' && (
          <div className="space-y-4 py-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Service *</Label>
                <Select value={serviceId} onValueChange={setServiceId}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select service..." />
                  </SelectTrigger>
                  <SelectContent>
                    {services.map((s: any) => (
                      <SelectItem key={s.id} value={s.id}>{s.name} ({s.duration_minutes} min)</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>Preferred Staff / Consultant</Label>
                <Select value={prefEmployeeId} onValueChange={setPrefEmployeeId}>
                  <SelectTrigger>
                    <SelectValue placeholder="Any Consultant" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="any">Any Consultant</SelectItem>
                    {staff.map((st: any) => (
                      <SelectItem key={st.id} value={st.id}>{st.name} ({st.role})</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Primary Date Preference *</Label>
                <Input type="date" value={prefDate1} onChange={(e) => setPrefDate1(e.target.value)} />
              </div>
              <div className="space-y-2">
                <Label>Primary Time Window</Label>
                <Select value={prefWindow1} onValueChange={setPrefWindow1}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="morning">Morning (9am - 12pm)</SelectItem>
                    <SelectItem value="afternoon">Afternoon (12pm - 4pm)</SelectItem>
                    <SelectItem value="evening">Evening (4pm - 8pm)</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Alternate Date Preference</Label>
                <Input type="date" value={prefDate2} onChange={(e) => setPrefDate2(e.target.value)} />
              </div>
              <div className="space-y-2">
                <Label>Alternate Time Window</Label>
                <Select value={prefWindow2} onValueChange={setPrefWindow2}>
                  <SelectTrigger>
                    <SelectValue placeholder="Choose alternate..." />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="morning">Morning (9am - 12pm)</SelectItem>
                    <SelectItem value="afternoon">Afternoon (12pm - 4pm)</SelectItem>
                    <SelectItem value="evening">Evening (4pm - 8pm)</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="flex gap-6 pt-1">
              <div className="flex items-center space-x-2">
                <Checkbox id="flexDate" checked={flexibleDate} onCheckedChange={(v) => setFlexibleDate(!!v)} />
                <Label htmlFor="flexDate">Flexible Dates</Label>
              </div>
              <div className="flex items-center space-x-2">
                <Checkbox id="flexLoc" checked={flexibleLocation} onCheckedChange={(v) => setFlexibleLocation(!!v)} />
                <Label htmlFor="flexLoc">Flexible Locations</Label>
              </div>
            </div>

            <div className="grid grid-cols-3 gap-4">
              <div className="space-y-2">
                <Label>Number of Guests</Label>
                <Input type="number" min={1} value={numberGuests} onChange={(e) => setNumberGuests(parseInt(e.target.value) || 1)} />
              </div>
              <div className="space-y-2">
                <Label>Event/Wedding Date</Label>
                <Input type="date" value={eventDate} onChange={(e) => setEventDate(e.target.value)} />
              </div>
              <div className="space-y-2">
                <Label>Estimated Budget ($)</Label>
                <Input type="number" placeholder="Budget limit" value={budget} onChange={(e) => setBudget(e.target.value)} />
              </div>
            </div>

            <div className="grid grid-cols-3 gap-4">
              <div className="space-y-2 col-span-2">
                <Label>Product/Designer Interest</Label>
                <Input placeholder="e.g. Monique Lhuillier, A-line gowns" value={designerInterest} onChange={(e) => setDesignerInterest(e.target.value)} />
              </div>
              <div className="space-y-2">
                <Label>Intake Source</Label>
                <Select value={source} onValueChange={setSource}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="Phone">Phone Call</SelectItem>
                    <SelectItem value="In-person">In-person</SelectItem>
                    <SelectItem value="Web">Web Intake Form</SelectItem>
                    <SelectItem value="Social">Social Media</SelectItem>
                    <SelectItem value="Referral">Word of Mouth</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="space-y-2">
              <Label>Campaign Attribution</Label>
              <Input placeholder="e.g. Summer Bridal Fair 2026" value={campaign} onChange={(e) => setCampaign(e.target.value)} />
            </div>

            <div className="space-y-2">
              <Label>Request Notes</Label>
              <Textarea value={reqNotes} onChange={(e) => setReqNotes(e.target.value)} placeholder="Include special preferences or alternate locations..." rows={3} />
            </div>
          </div>
        )}

        {/* STEP 3: FILES & INSPIRATION */}
        {step === 'FILES' && (
          <div className="space-y-6 py-4">
            <div className="bg-stone-50 border border-stone-200 rounded-xl p-4 space-y-4">
              <Label className="text-sm font-semibold">Supporting Documents & Inspiration URLs</Label>
              <p className="text-xs text-muted-foreground">Add links to bridal boards, Pinterest ideas, or custom sizing worksheets.</p>
              
              <div className="flex gap-2">
                <Input 
                  placeholder="https://pinterest.com/... or document URL" 
                  value={newFileUrl} 
                  onChange={(e) => setNewFileUrl(e.target.value)}
                />
                <Button type="button" onClick={handleAddFileUrl} className="shrink-0 bg-stone-900 text-white">
                  <Plus className="h-4 w-4 mr-1" /> Add Link
                </Button>
              </div>
            </div>

            <div className="space-y-2">
              <Label className="text-xs uppercase tracking-wider text-muted-foreground">Linked Files ({fileUrls.length})</Label>
              {fileUrls.length === 0 ? (
                <div className="text-center py-8 border border-dashed rounded-xl text-muted-foreground text-sm">
                  No links added yet. Paste a Pinterest board or inspiration URL above.
                </div>
              ) : (
                <div className="space-y-2">
                  {fileUrls.map((url, idx) => (
                    <div key={idx} className="flex justify-between items-center bg-stone-50 p-2.5 rounded-lg border">
                      <div className="flex items-center gap-2 truncate pr-4">
                        <FileText className="h-4 w-4 text-stone-500 shrink-0" />
                        <span className="text-sm truncate text-stone-700">{url}</span>
                      </div>
                      <Button 
                        type="button" 
                        size="icon" 
                        variant="ghost" 
                        className="h-7 w-7 text-brand-primary hover:text-brand-primary-hover shrink-0"
                        onClick={() => handleRemoveFileUrl(idx)}
                      >
                        <Trash className="h-4 w-4" />
                      </Button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

        {/* STEP 4: REVIEW & SAVE */}
        {step === 'REVIEW' && (
          <div className="space-y-6 py-4">
            <div className="space-y-4">
              <div className="bg-stone-50 rounded-xl p-4 border space-y-3">
                <h4 className="font-serif font-semibold text-lg text-stone-900 border-b pb-2 flex justify-between items-center">
                  <span>Customer Summary</span>
                  <span className="text-xs font-normal text-muted-foreground">
                    {customerMode === 'SEARCH' ? 'Linked Profile' : 'New Profile'}
                  </span>
                </h4>
                <div className="grid grid-cols-2 gap-2 text-sm text-stone-700">
                  <div><strong>Name:</strong> {reviewCustomerName}</div>
                  <div><strong>Preferred Contact:</strong> {prefComm.toUpperCase()}</div>
                  <div><strong>Phone:</strong> {reviewCustomerPhone}</div>
                  <div><strong>Email:</strong> {reviewCustomerEmail}</div>
                  {customerMode === 'CREATE' && (
                    <div className="col-span-2 pt-2 border-t mt-1 text-xs text-stone-500">
                      SMS Updates: {smsConsent ? 'Consented' : 'No Consent'} | Promos: {emailConsent ? 'Consented' : 'No Consent'}
                    </div>
                  )}
                </div>
              </div>

              <div className="bg-stone-50 rounded-xl p-4 border space-y-3">
                <h4 className="font-serif font-semibold text-lg text-stone-900 border-b pb-2">Request details</h4>
                <div className="grid grid-cols-2 gap-2 text-sm text-stone-700">
                  <div><strong>Service:</strong> {services.find(s => s.id === serviceId)?.name || 'Unknown'}</div>
                  <div><strong>Intake Source:</strong> {source}</div>
                  <div><strong>Preferred Date:</strong> {prefDate1} ({prefWindow1})</div>
                  <div><strong>Alt Date:</strong> {prefDate2 || 'None'} {prefDate2 ? `(${prefWindow2})` : ''}</div>
                  <div><strong>Preferred Staff:</strong> {staff.find(st => st.id === prefEmployeeId)?.name || 'Any Consultant'}</div>
                  <div><strong>Guests:</strong> {numberGuests}</div>
                  {eventDate && <div><strong>Event Date:</strong> {eventDate}</div>}
                  {budget && <div><strong>Budget:</strong> ${budget}</div>}
                </div>
              </div>

              {fileUrls.length > 0 && (
                <div className="bg-stone-50 rounded-xl p-4 border space-y-2">
                  <h4 className="font-serif font-semibold text-sm text-stone-900">Inspiration Links</h4>
                  <div className="text-xs text-stone-600 truncate space-y-1">
                    {fileUrls.map((url, i) => <div key={i} className="truncate">ΓÇó {url}</div>)}
                  </div>
                </div>
              )}
            </div>
          </div>
        )}

        <DialogFooter className="gap-2 sm:gap-0 mt-4 border-t pt-4">
          {step !== 'CUSTOMER' && (
            <Button type="button" variant="outline" onClick={handleBack}>
              <ChevronLeft className="h-4 w-4 mr-1" /> Back
            </Button>
          )}
          
          <Button 
            type="button" 
            variant="outline" 
            onClick={onClose} 
            disabled={createRequestMutation.isPending}
          >
            Cancel
          </Button>

          {step !== 'REVIEW' ? (
            <Button type="button" onClick={handleNext} className="bg-stone-900 text-white hover:bg-stone-800">
              Next <ChevronRight className="h-4 w-4 ml-1" />
            </Button>
          ) : (
            <Button 
              type="button" 
              onClick={handleSave} 
              disabled={createRequestMutation.isPending} 
              className="bg-brand-primary hover:bg-brand-primary-hover text-white font-medium shadow-sm transition-colors"
            >
              {createRequestMutation.isPending ? 'Submitting...' : 'Complete Intake & Save'}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from '@vowos/design-system';
import { Button } from '@vowos/design-system';
import { Input } from '@vowos/design-system';
import { Label } from '@vowos/design-system';
import { RadioGroup, RadioGroupItem } from '@vowos/design-system';
import { Textarea } from '@vowos/design-system';
import { DollarSign, Smile, Frown, Meh } from 'lucide-react';
import { supabase } from '@/lib/supabase';
import { useQueryClient } from '@tanstack/react-query';

import { useCompleteAppointment } from '@/lib/services/schedulingService';

interface OutcomeModalProps {
  appointment: any;
  isOpen: boolean;
  onClose: () => void;
}

export function OutcomeModal({ appointment, isOpen, onClose }: OutcomeModalProps) {
  const [revenue, setRevenue] = useState('');
  const [sentiment, setSentiment] = useState('positive');
  const [notes, setNotes] = useState('');
  
  const queryClient = useQueryClient();
  const completeMutation = useCompleteAppointment();

  const handleComplete = async () => {
    if (!appointment) return;
    
    try {
      const outcomeText = `Revenue: $${revenue || '0.00'}. Sentiment: ${sentiment}`;
      await completeMutation.mutateAsync({
        appointmentId: appointment.id,
        outcome: outcomeText,
        notes: notes
      });
      
      onClose();
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>Complete Appointment</DialogTitle>
          <DialogDescription>
            Record the outcome for {appointment?.customer?.first_name}'s visit.
          </DialogDescription>
        </DialogHeader>
        
        <div className="grid gap-4 py-4">
          <div className="grid grid-cols-4 items-center gap-4">
            <Label htmlFor="revenue" className="text-right">Revenue collected</Label>
            <div className="col-span-3 relative">
              <DollarSign className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
              <Input
                id="revenue"
                type="number"
                placeholder="0.00"
                className="pl-8"
                value={revenue}
                onChange={(e) => setRevenue(e.target.value)}
              />
            </div>
          </div>
          
          <div className="grid grid-cols-4 items-start gap-4">
            <Label className="text-right mt-2">Sentiment</Label>
            <RadioGroup defaultValue="positive" className="col-span-3 flex gap-4" value={sentiment} onValueChange={setSentiment}>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="positive" id="r1" />
                <Label htmlFor="r1" className="flex items-center gap-1 cursor-pointer"><Smile className="h-4 w-4 text-status-success"/> Great</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="neutral" id="r2" />
                <Label htmlFor="r2" className="flex items-center gap-1 cursor-pointer"><Meh className="h-4 w-4 text-status-warning"/> Neutral</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="negative" id="r3" />
                <Label htmlFor="r3" className="flex items-center gap-1 cursor-pointer"><Frown className="h-4 w-4 text-red-500"/> Poor</Label>
              </div>
            </RadioGroup>
          </div>
          
          <div className="grid grid-cols-4 items-start gap-4">
            <Label htmlFor="notes" className="text-right mt-2">Wrap-up Notes</Label>
            <Textarea
              id="notes"
              placeholder="Any specific follow ups needed?"
              className="col-span-3 min-h-[100px]"
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
            />
          </div>
        </div>
        
        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={completeMutation.isPending}>Cancel</Button>
          <Button onClick={handleComplete} disabled={completeMutation.isPending}>
            {completeMutation.isPending ? 'Saving...' : 'Complete Appointment'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '@vowos/design-system';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@vowos/design-system';
import { Button } from '@vowos/design-system';
import { Badge } from '@vowos/design-system';
import { ScrollArea } from '@vowos/design-system';
import { Avatar, AvatarFallback } from '@vowos/design-system';
import { 
  Phone, 
  Mail, 
  Clock, 
  Calendar, 
  User, 
  FileText, 
  CheckCircle, 
  MessageSquare, 
  Play, 
  AlertCircle, 
  Sparkles,
  Lock,
  UserCheck
} from 'lucide-react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@vowos/design-system';
import { 
  useAIRecommendations,
  useStaffProfiles,
  useCreateHold,
  useConfirmHold,
  useTransitionRequestStatus,
  useAssignAppointmentRequest
} from '@/lib/services/schedulingService';
import { useVowosData } from '@/contexts/VowosDataContext';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/lib/supabase';
import { toast } from 'sonner';

export function Request360Panel({ requestId, request, onClose }: { requestId?: string, request: any, onClose: () => void }) {
  const [activeTab, setActiveTab] = useState('summary');
  const queryClient = useQueryClient();
  const reqId = requestId || request?.id;
  
  const { businessId } = useVowosData();
  const { data: staff = [] } = useStaffProfiles();
  const { data: aiRecs = [] } = useAIRecommendations(reqId);
  
  const createHoldMutation = useCreateHold();
  const confirmHoldMutation = useConfirmHold();
  const transitionStatusMutation = useTransitionRequestStatus();
  const assignRequestMutation = useAssignAppointmentRequest();

  // Fetch active holds for this request
  const { data: activeHolds = [], refetch: refetchHolds } = useQuery({
    queryKey: ['activeHolds', reqId],
    queryFn: async () => {
      if (!reqId) return [];
      const { data, error } = await supabase
        .from('appointment_holds')
        .select('*, employee:staff_profiles(*)')
        .eq('request_id', reqId)
        .gt('expires_at', new Date().toISOString());
      
      if (error) throw error;
      return data || [];
    },
    enabled: !!reqId
  });

  if (!request && !reqId) {
    return (
      <div className="flex items-center justify-center h-full text-muted-foreground p-8 text-center bg-background">
        Select a request from the queue to view the 360┬░ details.
      </div>
    );
  }

  const customerName = request?.customerName || (request?.customer ? `${request.customer.first_name || ''} ${request.customer.last_name || ''}`.trim() : null);
  const initials = customerName ? customerName.split(' ').map((n: string) => n[0]).join('').substring(0, 2).toUpperCase() : '?';
  const status = (request?.status || 'PENDING').toUpperCase();

  const handleCreateHold = async (rec: any) => {
    if (!reqId || !businessId) return;
    try {
      await createHoldMutation.mutateAsync({
        requestId: reqId,
        employeeId: rec.employee_id,
        businessId,
        locationId: rec.location_id,
        roomId: rec.room_id || null,
        startAt: rec.proposed_start_at,
        endAt: rec.proposed_end_at
      });
      toast.success('Tentative hold created successfully for 15 minutes.');
      refetchHolds();
      queryClient.invalidateQueries({ queryKey: ['appointment_requests'] });
    } catch (err: any) {
      toast.error('Failed to create hold: ' + err.message);
    }
  };

  const handleConfirmHold = async (holdId: string) => {
    try {
      await confirmHoldMutation.mutateAsync({ holdId });
      toast.success('Hold confirmed successfully! Appointment is scheduled.');
      refetchHolds();
      queryClient.invalidateQueries({ queryKey: ['appointment_requests'] });
      queryClient.invalidateQueries({ queryKey: ['appointments'] });
    } catch (err: any) {
      toast.error('Failed to confirm hold: ' + err.message);
    }
  };

  const handleDirectConfirm = async (rec: any) => {
    if (!reqId) return;
    try {
      await assignRequestMutation.mutateAsync({
        requestId: reqId,
        employeeId: rec.employee_id,
        roomId: rec.room_id || '00000000-0000-0000-0000-000000000000',
        startAt: rec.proposed_start_at,
        endAt: rec.proposed_end_at
      });
      toast.success('Appointment assigned and confirmed successfully!');
      queryClient.invalidateQueries({ queryKey: ['appointment_requests'] });
      queryClient.invalidateQueries({ queryKey: ['appointments'] });
    } catch (err: any) {
      toast.error('Failed to confirm appointment: ' + err.message);
    }
  };

  const handleStatusChange = async (newStatus: string) => {
    if (!reqId) return;
    try {
      await transitionStatusMutation.mutateAsync({
        requestId: reqId,
        newStatus
      });
      toast.success(`Request status transitioned to ${newStatus}`);
      queryClient.invalidateQueries({ queryKey: ['appointment_requests'] });
    } catch (err: any) {
      toast.error('Failed to transition status: ' + err.message);
    }
  };

  const renderMissing = (label: string) => (
    <div className="flex items-center gap-1.5 text-muted-foreground/60 text-xs italic">
      <AlertCircle className="h-3 w-3" /> Missing {label}
    </div>
  );

  return (
    <div className="h-full flex flex-col border-l bg-background">
      {/* Header */}
      <div className="relative overflow-hidden border-b bg-gradient-to-br from-blue-50 via-white to-cyan-50 dark:from-blue-950/20 dark:via-background dark:to-cyan-950/20">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-cyan-500"></div>
        <div className="p-5 pt-6 flex justify-between items-start z-10">
          <div className="flex gap-4 items-center">
            <Avatar className="h-14 w-14 border-2 border-white shadow-md ring-1 ring-black/5 bg-background">
              <AvatarFallback className="bg-gradient-to-br from-blue-500 to-cyan-500 text-white text-lg font-semibold">{initials}</AvatarFallback>
            </Avatar>
            <div>
              <div className="flex items-center gap-2 mb-1">
                <h2 className="text-xl font-bold text-foreground">{customerName || renderMissing('Customer Identity')}</h2>
                <Badge className={
                  status === 'PENDING' || status === 'NEW' ? 'bg-status-warning/10 text-status-warning border-status-warning/20' :
                  status === 'CONFIRMED' ? 'bg-status-success/10 text-status-success border-emerald-200' :
                  'bg-gray-500/10 text-text-secondary border-border-default'
                } variant="outline">
                  {status}
                </Badge>
              </div>
              <p className="text-sm text-muted-foreground flex items-center gap-3">
                <span className="flex items-center gap-1"><Phone className="h-3 w-3" /> {request?.customerPhone || request?.customer?.phone || renderMissing('Phone')}</span>
                <span className="flex items-center gap-1"><Mail className="h-3 w-3" /> {request?.customerEmail || request?.customer?.email || renderMissing('Email')}</span>
              </p>
            </div>
          </div>
          <Button variant="ghost" size="icon" onClick={onClose} className="rounded-full hover:bg-black/5">
            &times;
          </Button>
        </div>
      </div>

      {/* Active Holds Banner */}
      {activeHolds.length > 0 && (
        <div className="bg-status-warning/10 border-b border-status-warning/20 px-5 py-3 flex items-center justify-between text-xs text-amber-900 shrink-0">
          <div className="flex items-center gap-2">
            <Clock className="h-4 w-4 text-status-warning shrink-0" />
            <span>
              Hold active for <strong>{activeHolds[0].employee?.name}</strong>. Expires {new Date(activeHolds[0].expires_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}.
            </span>
          </div>
          <Button 
            size="xs" 
            onClick={() => handleConfirmHold(activeHolds[0].id)} 
            disabled={confirmHoldMutation.isPending}
            className="bg-amber-600 hover:bg-amber-700 text-white font-medium shadow-xs"
          >
            {confirmHoldMutation.isPending ? 'Confirming...' : 'Confirm Hold'}
          </Button>
        </div>
      )}

      {/* Action Bar */}
      <div className="bg-background px-5 py-2.5 border-b flex items-center justify-between gap-3 shadow-xs shrink-0">
        <span className="text-xs font-semibold text-stone-500">Manual Stage:</span>
        <Select value={request?.status || 'new'} onValueChange={handleStatusChange}>
          <SelectTrigger className="w-40 h-8 text-xs font-medium border-stone-200">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="new">New Inquiry</SelectItem>
            <SelectItem value="review">Staffing Review</SelectItem>
            <SelectItem value="waitlist">Waitlist</SelectItem>
            <SelectItem value="canceled">Canceled</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab} className="flex-1 flex flex-col min-h-0">
        <div className="border-b overflow-x-auto custom-scrollbar">
          <TabsList className="inline-flex w-max min-w-full justify-start h-12 p-1 bg-transparent">
            <TabsTrigger value="summary" className="data-[state=active]:bg-muted">Summary</TabsTrigger>
            <TabsTrigger value="customer" className="data-[state=active]:bg-muted">Customer</TabsTrigger>
            <TabsTrigger value="preferences" className="data-[state=active]:bg-muted">Preferences</TabsTrigger>
            <TabsTrigger value="staffing" className="data-[state=active]:bg-muted">Staffing</TabsTrigger>
            <TabsTrigger value="ai" className="data-[state=active]:bg-muted flex gap-1.5"><Sparkles className="h-3 w-3 text-status-warning"/> AI Match</TabsTrigger>
            <TabsTrigger value="comms" className="data-[state=active]:bg-muted">Comms</TabsTrigger>
            <TabsTrigger value="files" className="data-[state=active]:bg-muted">Files</TabsTrigger>
            <TabsTrigger value="tasks" className="data-[state=active]:bg-muted">Tasks</TabsTrigger>
            <TabsTrigger value="history" className="data-[state=active]:bg-muted">History</TabsTrigger>
          </TabsList>
        </div>

        <ScrollArea className="flex-1 p-5">
          <TabsContent value="summary" className="mt-0 space-y-6">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Request Number</p>
                <p className="text-sm font-medium">{request?.requestNumber || request?.id?.substring(0,8) || renderMissing('Request Number')}</p>
              </div>
              <div className="space-y-1">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Submitted Date</p>
                <p className="text-sm font-medium">{request?.created_at ? new Date(request.created_at).toLocaleString() : renderMissing('Submitted Date')}</p>
              </div>
              <div className="space-y-1">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Service</p>
                <p className="text-sm font-medium">{request?.serviceName || request?.service?.name || renderMissing('Service')}</p>
              </div>
              <div className="space-y-1">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Event Date</p>
                <p className="text-sm font-medium">{request?.eventDate || request?.event_date ? new Date(request.eventDate || request.event_date).toLocaleDateString() : renderMissing('Event Date')}</p>
              </div>
              <div className="space-y-1">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Budget</p>
                <p className="text-sm font-medium">{request?.budget || request?.budget_cents ? `$${(request.budget || request.budget_cents / 100).toFixed(2)}` : renderMissing('Budget')}</p>
              </div>
              <div className="space-y-1">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Attendees</p>
                <p className="text-sm font-medium">{request?.attendees || request?.number_of_guests || renderMissing('Attendees Count')}</p>
              </div>
            </div>
          </TabsContent>

          <TabsContent value="customer" className="mt-0 space-y-6">
             <div className="grid grid-cols-2 gap-4">
               <div className="space-y-1">
                 <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Assigned Consultant</p>
                 <p className="text-sm font-medium">{request?.customer?.assigned_consultant?.name || renderMissing('Assigned Consultant')}</p>
               </div>
               <div className="space-y-1">
                 <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Preferred Contact</p>
                 <p className="text-sm font-medium">{request?.customer?.preferred_contact_method || renderMissing('Preference')}</p>
               </div>
             </div>
             <div>
                 <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider mb-2">Customer Notes</p>
                 {request?.customer?.notes ? (
                   <p className="text-sm">{request.customer.notes}</p>
                 ) : renderMissing('Customer Notes')}
             </div>
          </TabsContent>
          
          <TabsContent value="preferences" className="mt-0 space-y-6">
             <div className="space-y-4">
                 <h3 className="text-sm font-semibold text-foreground border-b pb-2">Scheduling Preferences</h3>
                 <div className="grid grid-cols-2 gap-4">
                   <div className="space-y-1">
                     <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Preferred Date</p>
                     <p className="text-sm font-medium">{request?.preferred_date_1 || renderMissing('Preferred Date')}</p>
                   </div>
                   <div className="space-y-1">
                     <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Preferred Time Window</p>
                     <p className="text-sm font-medium">{request?.preferred_window_1 || renderMissing('Preferred Window')}</p>
                   </div>
                   <div className="space-y-1">
                     <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Alt Date</p>
                     <p className="text-sm font-medium">{request?.preferred_date_2 || 'None'}</p>
                   </div>
                   <div className="space-y-1">
                     <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Alt Window</p>
                     <p className="text-sm font-medium">{request?.preferred_window_2 || 'None'}</p>
                   </div>
                 </div>
             </div>
          </TabsContent>

          <TabsContent value="staffing" className="mt-0 space-y-6">
            <div className="space-y-1">
              <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Eligible Employees</p>
              <div className="flex flex-wrap gap-2 mt-2">
                {staff.length ? staff.map((e: any) => (
                  <Badge variant="secondary" key={e.id}>{e.name} ({e.role})</Badge>
                )) : renderMissing('Eligible Employees')}
              </div>
            </div>
          </TabsContent>

          <TabsContent value="ai" className="mt-0 space-y-6">
            <h3 className="font-semibold text-xs uppercase text-status-info dark:text-blue-400 tracking-wider">AI Assignment Recommendations</h3>
            {aiRecs.length > 0 ? (
              <div className="space-y-3">
                {aiRecs.map((rec: any, idx: number) => (
                  <Card key={rec.id} className={`overflow-hidden border transition-all ${idx === 0 ? 'border-blue-300 shadow-md ring-1 ring-blue-500/20 bg-status-info/10/30' : 'opacity-80 hover:opacity-100'}`}>
                    <CardContent className="p-4">
                      <div className="flex justify-between items-start mb-2">
                        <div className="flex items-center gap-3">
                          <Avatar className="h-8 w-8 border bg-white">
                            <AvatarFallback className="bg-blue-100 text-blue-700 text-xs">
                              {rec.employee?.first_name?.[0] || 'S'}{rec.employee?.last_name?.[0] || 'P'}
                            </AvatarFallback>
                          </Avatar>
                          <div>
                            <p className="font-semibold text-sm">{rec.employee?.first_name || 'Staff'} {rec.employee?.last_name || ''}</p>
                            <p className="text-xs text-muted-foreground">{rec.employee?.role || 'Consultant'}</p>
                          </div>
                        </div>
                        <Badge variant={idx === 0 ? "default" : "secondary"} className={idx === 0 ? "bg-blue-600" : ""}>
                          {rec.score}% Match
                        </Badge>
                      </div>
                      
                      <p className="text-xs font-semibold text-stone-700 mt-2">
                        Proposed: {rec.proposed_start_at ? new Date(rec.proposed_start_at).toLocaleString() : 'TBD'}
                      </p>
                      
                      {rec.disqualification_reasons_json && rec.disqualification_reasons_json.length > 0 && (
                        <div className="text-xs text-brand-primary mt-2 bg-brand-soft p-2 rounded-md">
                          Disqualifications: {rec.disqualification_reasons_json.join(', ')}
                        </div>
                      )}

                      <div className="text-xs text-muted-foreground mt-3 bg-muted/30 p-2 rounded-md">
                        {rec.score_breakdown_json ? JSON.stringify(rec.score_breakdown_json) : "Optimal matching score based on proximity and consultant schedule."}
                      </div>

                      <div className="flex items-center gap-2 mt-4">
                        <Button 
                          size="xs" 
                          variant="outline" 
                          onClick={() => handleCreateHold(rec)}
                          disabled={createHoldMutation.isPending}
                        >
                          Create Hold
                        </Button>
                        <Button 
                          size="xs" 
                          onClick={() => handleDirectConfirm(rec)}
                          disabled={assignRequestMutation.isPending}
                          className="bg-blue-600 hover:bg-blue-700 text-white"
                        >
                          Direct Confirm
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            ) : (
              <div className="text-center p-6 border rounded-md border-dashed bg-muted/5">
                <div className="h-10 w-10 rounded-full bg-blue-100 text-status-info flex items-center justify-center mx-auto mb-3">
                  <Sparkles className="h-5 w-5" />
                </div>
                <p className="text-sm font-medium">No AI recommendations available</p>
                <p className="text-xs text-muted-foreground mt-1">This request has not been processed by the AI matching engine yet.</p>
              </div>
            )}
          </TabsContent>

          <TabsContent value="comms" className="mt-0 space-y-4 h-full flex flex-col min-h-[400px]">
             <div className="flex-1 border rounded-md p-4 bg-muted/10 flex items-center justify-center text-muted-foreground text-sm italic">
                {renderMissing('Communications Data')}
             </div>
          </TabsContent>

          <TabsContent value="files" className="mt-0 space-y-4">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-semibold text-sm text-muted-foreground">Attached Files & Photos</h3>
              <Button size="sm" variant="outline">Upload</Button>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <p className="text-xs text-muted-foreground col-span-2">{renderMissing('Files')}</p>
            </div>
          </TabsContent>

          <TabsContent value="tasks" className="mt-0 space-y-4">
             <div className="flex justify-between items-center mb-4">
              <h3 className="font-semibold text-sm text-muted-foreground">Tasks</h3>
              <Button size="sm" variant="outline">Add Task</Button>
            </div>
            <p className="text-xs text-muted-foreground">{renderMissing('Tasks')}</p>
          </TabsContent>

          <TabsContent value="history" className="mt-0 space-y-4">
             <div className="relative border-l border-muted ml-3 space-y-6 pb-4">
                <div className="relative pl-6">
                  <div className="absolute left-[-5px] top-1 h-2.5 w-2.5 rounded-full bg-status-info ring-4 ring-background"></div>
                  <p className="text-sm font-medium">Request Created</p>
                  <p className="text-xs text-muted-foreground">{request?.created_at ? new Date(request.created_at).toLocaleString() : 'Unknown Date'}</p>
                </div>
             </div>
          </TabsContent>
        </ScrollArea>
      </Tabs>
    </div>
  );
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import FullCalendar from '@fullcalendar/react';
import timeGridPlugin from '@fullcalendar/timegrid';
import dayGridPlugin from '@fullcalendar/daygrid';
import interactionPlugin, { Draggable } from '@fullcalendar/interaction';
import { Card, CardHeader, CardTitle, CardContent } from '@vowos/design-system';
import { Badge } from '@vowos/design-system';
import { Button } from '@vowos/design-system';
import { Avatar, AvatarFallback, AvatarImage } from '@vowos/design-system';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@vowos/design-system';
import { 
  CalendarDays, 
  Inbox, 
  Users, 
  Sparkles, 
  BarChart3, 
  Plus, 
  Check, 
  X, 
  AlertTriangle, 
  Clock, 
  MapPin, 
  UserCheck, 
  Zap, 
  RefreshCw, 
  SlidersHorizontal,
  ChevronRight,
  UserPlus
} from 'lucide-react';
import { Appointment360Panel } from './Appointment360Panel';
import { Request360Panel } from './Request360Panel';
import { AIAssignmentDrawer } from './AIAssignmentDrawer';
import { NewAppointmentModal } from './NewAppointmentModal';
import { NewRequestModal } from './NewRequestModal';
import { EmployeeShiftModal } from './EmployeeShiftModal';
import { DraggableAppointmentCard } from './components/DraggableAppointmentCard';
import { NotificationPermissionToggle } from '@/components/vowos/NotificationPermissionToggle';
import { useVowosData } from '@/contexts/VowosDataContext';
import { 
  useBusiness, 
  useAppointmentRequests, 
  useAppointments, 
  useEmployeeSchedules,
  useStaffProfiles,
  useAssignAppointmentRequest,
  useRescheduleAppointment,
  usePublishSchedules,
  useFetchTimeOffRequests
} from '@/lib/services/schedulingService';
import { WorkforceMatrix } from './components/WorkforceMatrix';
import { useCapacityMetrics } from '@/lib/services/capacityService';
import { supabase } from '@/lib/supabase';
import { useQueryClient } from '@tanstack/react-query';
import { useSearchParams } from 'react-router-dom';
import { toast } from 'sonner';

export type SchedulingMode = 'calendar' | 'requests' | 'workforce' | 'ai' | 'capacity';

export function UnifiedSchedulingWorkspace() {
  const [searchParams, setSearchParams] = useSearchParams();
  const rawMode = searchParams.get('mode') as SchedulingMode | null;
  const activeMode: SchedulingMode = ['calendar', 'requests', 'workforce', 'ai', 'capacity'].includes(rawMode || '')
    ? (rawMode as SchedulingMode)
    : 'calendar';

  const appointmentIdFromUrl = searchParams.get('appointmentId') || searchParams.get('appointment') || searchParams.get('request');

  const [selectedRequest, setSelectedRequest] = useState<Record<string, any> | null>(null);
  const [assigningRequest, setAssigningRequest] = useState<Record<string, any> | null>(null);
  
  const { mutate: assignRequest } = useAssignAppointmentRequest();
  const rescheduleMutation = useRescheduleAppointment();

  const [newAppointmentData, setNewAppointmentData] = useState<{ start_at: string; employee_id: string } | null>(null);
  const [isNewAppointmentModalOpen, setIsNewAppointmentModalOpen] = useState(false);
  const [isNewRequestModalOpen, setIsNewRequestModalOpen] = useState(false);
  const [shiftModalData, setShiftModalData] = useState<{ isOpen: boolean; data: any }>({ isOpen: false, data: null });

  // Layer Toggles for Calendar Mode
  const [layerFilters, setLayerFilters] = useState({
    appointments: true,
    requests: true,
    shifts: true,
    holds: true,
    rooms: true,
  });

  // Selected Employee filter for Workforce mode
  const [selectedWorkforceStaff, setSelectedWorkforceStaff] = useState<string>('all');

  const queryClient = useQueryClient();
  const queueRef = useRef<HTMLDivElement>(null);

  const { activeLocation } = useVowosData();
  const { data: business } = useBusiness();
  const businessId = business?.id;

  const { data: requests = [] } = useAppointmentRequests(businessId, activeLocation);
  const { data: appointments = [] } = useAppointments(businessId, activeLocation);
  const { data: schedules = [] } = useEmployeeSchedules(businessId, activeLocation);
  const { data: staff = [] } = useStaffProfiles();
  const { data: timeOffRequests = [] } = useFetchTimeOffRequests(businessId);

  const todayStr = new Date().toISOString().split('T')[0];
  const { data: capacityMetrics } = useCapacityMetrics(businessId, todayStr);

  // Mode Switcher handler
  const setMode = (mode: SchedulingMode) => {
    const nextParams = new URLSearchParams(searchParams);
    nextParams.set('mode', mode);
    setSearchParams(nextParams);
  };

  // Sync URL query params to selected record
  useEffect(() => {
    if (appointmentIdFromUrl) {
      const apt = appointments.find((a: any) => a.id === appointmentIdFromUrl);
      if (apt) {
        setSelectedRequest({
          type: 'appointment',
          id: apt.id,
          customerName: apt.customer ? `${apt.customer.first_name || ''} ${apt.customer.last_name || ''}`.trim() : null,
          serviceName: apt.service?.name || null,
          status: apt.confirmation_status || 'confirmed',
          time: `${new Date(apt.start_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} - ${new Date(apt.end_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`,
          employeeName: apt.employee ? `${apt.employee.first_name || ''} ${apt.employee.last_name || ''}`.trim() : null,
          roomName: apt.room?.name || null,
          raw: apt
        });
        return;
      }

      const req = requests.find((r: any) => r.id === appointmentIdFromUrl);
      if (req) {
        setSelectedRequest({
          type: 'request',
          id: req.id,
          customerName: req.customer ? `${req.customer.first_name || ''} ${req.customer.last_name || ''}`.trim() : null,
          serviceName: req.service?.name || null,
          status: req.status || 'new',
          time: req.preferred_date_1 || null,
          employeeName: null,
          roomName: null,
          raw: req
        });
        return;
      }
    }
  }, [appointmentIdFromUrl, appointments, requests]);

  // Real-time synchronization
  useEffect(() => {
    const channel = supabase
      .channel('unified-scheduling-sync')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'appointments' },
        () => {
          queryClient.invalidateQueries({ queryKey: ['appointments'] });
        }
      )
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'appointment_holds' },
        () => {
          queryClient.invalidateQueries({ queryKey: ['activeHolds'] });
        }
      )
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'appointment_requests' },
        () => {
          queryClient.invalidateQueries({ queryKey: ['appointment_requests'] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [queryClient]);

  const updateSelectedRequestUrl = (req: Record<string, any> | null) => {
    setSelectedRequest(req);
    const nextParams = new URLSearchParams(searchParams);
    if (req?.id) {
      nextParams.set('appointmentId', req.id);
    } else {
      nextParams.delete('appointmentId');
      nextParams.delete('appointment');
      nextParams.delete('request');
    }
    setSearchParams(nextParams);
  };

  // Map events for FullCalendar
  const calendarEvents = useMemo(() => {
    const events: Record<string, any>[] = [];

    // Add employee shift background blocks if layer enabled
    if (layerFilters.shifts) {
      schedules.forEach((shift: any) => {
        events.push({
          id: `shift_${shift.id}`,
          title: shift.employee?.first_name ? `${shift.employee.first_name} (Shift)` : 'Staff Shift',
          start: shift.start_at || shift.start_time,
          end: shift.end_at || shift.end_time,
          display: 'background',
          backgroundColor: '#f1f5f9',
        });
      });
    }

    // Add confirmed appointments if layer enabled
    if (layerFilters.appointments) {
      appointments.forEach((apt: any) => {
        const isSelected = selectedRequest?.id === apt.id;
        events.push({
          id: apt.id,
          title: `${apt.customer?.first_name || 'Bride'} - ${apt.service?.name || 'Appointment'} (${apt.employee?.first_name || 'Unassigned'})`,
          start: apt.start_at,
          end: apt.end_at,
          backgroundColor: isSelected ? '#be123c' : '#e11d48',
          borderColor: isSelected ? '#881337' : '#be123c',
          textColor: '#ffffff',
          extendedProps: {
            type: 'appointment',
            customerName: apt.customer ? `${apt.customer.first_name || ''} ${apt.customer.last_name || ''}`.trim() : 'Guest',
            serviceName: apt.service?.name || 'Consultation',
            status: apt.confirmation_status || 'confirmed',
            time: `${new Date(apt.start_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} - ${new Date(apt.end_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`,
            employeeName: apt.employee ? `${apt.employee.first_name || ''} ${apt.employee.last_name || ''}`.trim() : 'Unassigned',
            roomName: apt.room?.name || 'Fitting Room'
          }
        });
      });
    }

    return events;
  }, [appointments, schedules, layerFilters, selectedRequest]);

  // Setup draggable for queue
  useEffect(() => {
    if (queueRef.current && activeMode === 'calendar') {
      const draggable = new Draggable(queueRef.current, {
        itemSelector: '.draggable-request-card',
        eventData: function (eventEl) {
          const id = eventEl.getAttribute('data-id');
          const title = eventEl.getAttribute('data-title');
          return { id, title, duration: '01:30' };
        }
      });

      return () => {
        draggable.destroy();
      };
    }
  }, [queueRef, activeMode]);

  const handleEventReceive = async (info: any) => {
    const requestId = info.event.id;
    const dropTime = info.event.start;
    const dropEndTime = new Date(dropTime.getTime() + 90 * 60 * 1000); // 1.5 hrs default

    const req = requests.find((r: any) => r.id === requestId);
    if (!req) return;

    assignRequest({
      requestId: req.id,
      employeeId: info.event.getResources?.[0]?.id || '00000000-0000-0000-0000-000000000000',
      roomId: req.preferred_room_id || '00000000-0000-0000-0000-000000000000',
      startAt: dropTime.toISOString(),
      endAt: dropEndTime.toISOString()
    }, {
      onSuccess: () => {
        toast.success('Appointment created from request!');
        queryClient.invalidateQueries({ queryKey: ['appointments'] });
        queryClient.invalidateQueries({ queryKey: ['appointment_requests'] });
      },
      onError: (err: any) => {
        toast.error('Failed to schedule request: ' + err.message);
        info.revert();
      }
    });
  };

  const handleEventDrop = async (info: any) => {
    const newStart = info.event.start;
    const newEnd = info.event.end || new Date(newStart.getTime() + 90 * 60 * 1000);
    const employeeId = info.event.getResources?.[0]?.id || info.event.extendedProps?.raw?.employee_id || '00000000-0000-0000-0000-000000000000';

    rescheduleMutation.mutate({
      appointmentId: info.event.id,
      newStartAt: newStart.toISOString(),
      newEndAt: newEnd.toISOString(),
      newEmployeeId: employeeId
    }, {
      onSuccess: () => {
        toast.success('Appointment rescheduled successfully');
        queryClient.invalidateQueries({ queryKey: ['appointments'] });
      },
      onError: (err: any) => {
        info.revert();
        toast.error('Failed to reschedule appointment: ' + err.message);
      }
    });
  };

  const handleDateSelect = (selectInfo: any) => {
    setNewAppointmentData({
      start_at: selectInfo.startStr,
      employee_id: selectInfo.resource?.id || ''
    });
    setIsNewAppointmentModalOpen(true);
  };

  const handleEventClick = (clickInfo: any) => {
    if (clickInfo.event.extendedProps.type === 'appointment') {
      updateSelectedRequestUrl({
        id: clickInfo.event.id,
        ...clickInfo.event.extendedProps
      });
    }
  };

  const { mutate: publishSchedules } = usePublishSchedules();

  const publishWorkforceSchedule = () => {
    if (businessId) {
      publishSchedules({ businessId, locationId: activeLocation }, {
        onSuccess: () => {
          toast.success('All current shifts published to team members!');
        },
        onError: () => {
          toast.error('Failed to publish schedules.');
        }
      });
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-5rem)] bg-[#faf8f5]">
      {/* Top Segmented Workspace Mode Switcher */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between px-4 py-3 bg-white border-b border-stone-200 gap-3 shrink-0">
        <div className="flex items-center gap-1 bg-stone-100 p-1 rounded-xl overflow-x-auto scrollbar-none">
          <button
            onClick={() => setMode('calendar')}
            className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all whitespace-nowrap ${
              activeMode === 'calendar'
                ? 'bg-white text-stone-900 shadow-sm font-bold'
                : 'text-stone-600 hover:text-stone-900'
            }`}
          >
            <CalendarDays className="h-3.5 w-3.5 text-brand-primary" />
            Calendar
          </button>
          <button
            onClick={() => setMode('requests')}
            className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all whitespace-nowrap ${
              activeMode === 'requests'
                ? 'bg-white text-stone-900 shadow-sm font-bold'
                : 'text-stone-600 hover:text-stone-900'
            }`}
          >
            <Inbox className="h-3.5 w-3.5 text-status-info" />
            Booking Requests
            {requests.filter((r: any) => r.status === 'new').length > 0 && (
              <span className="ml-1 px-1.5 py-0.2 rounded-full bg-brand-primary text-white text-[10px] font-bold">
                {requests.filter((r: any) => r.status === 'new').length}
              </span>
            )}
          </button>
          <button
            onClick={() => setMode('workforce')}
            className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all whitespace-nowrap ${
              activeMode === 'workforce'
                ? 'bg-white text-stone-900 shadow-sm font-bold'
                : 'text-stone-600 hover:text-stone-900'
            }`}
          >
            <Users className="h-3.5 w-3.5 text-vowos-violet" />
            Workforce
          </button>
          <button
            onClick={() => setMode('ai')}
            className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all whitespace-nowrap ${
              activeMode === 'ai'
                ? 'bg-white text-stone-900 shadow-sm font-bold'
                : 'text-stone-600 hover:text-stone-900'
            }`}
          >
            <Sparkles className="h-3.5 w-3.5 text-status-warning" />
            AI Planner
          </button>
          <button
            onClick={() => setMode('capacity')}
            className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all whitespace-nowrap ${
              activeMode === 'capacity'
                ? 'bg-white text-stone-900 shadow-sm font-bold'
                : 'text-stone-600 hover:text-stone-900'
            }`}
          >
            <BarChart3 className="h-3.5 w-3.5 text-status-success" />
            Capacity
          </button>
        </div>

        {/* Quick Action Controls */}
        <div className="flex items-center gap-2">
          <NotificationPermissionToggle />
          {activeMode === 'workforce' && (
            <Button
              onClick={publishWorkforceSchedule}
              variant="outline"
              size="sm"
              className="text-xs font-medium border-stone-200"
            >
              <Check className="h-3.5 w-3.5 mr-1.5 text-status-success" />
              Publish Shifts
            </Button>
          )}

          <Button
            onClick={() => setIsNewRequestModalOpen(true)}
            variant="outline"
            size="sm"
            className="text-xs font-medium border-stone-200"
          >
            <Plus className="h-3.5 w-3.5 mr-1" />
            New Request
          </Button>

          <Button
            onClick={() => setIsNewAppointmentModalOpen(true)}
            size="sm"
            className="bg-stone-900 hover:bg-stone-800 text-white text-xs font-semibold shadow-xs"
          >
            <Plus className="h-3.5 w-3.5 mr-1" />
            New Appointment
          </Button>
        </div>
      </div>

      {/* Main Workspace Body */}
      <div className="flex-1 flex overflow-hidden relative">
        {/* Left Panel: Mode-Specific Actions & Filter Queue */}
        <div className="w-80 border-r border-stone-200 bg-white flex flex-col shrink-0">
          {activeMode === 'calendar' && (
            <div className="p-4 flex flex-col h-full overflow-y-auto">
              <h3 className="font-semibold text-sm text-stone-900 mb-3 flex items-center justify-between">
                <span>Unassigned Requests</span>
                <Badge variant="secondary" className="text-xs">{requests.length}</Badge>
              </h3>
              <p className="text-xs text-stone-500 mb-4">
                Drag a booking request onto the calendar to assign time and consultant.
              </p>

              <div ref={queueRef} className="space-y-3 flex-1 overflow-y-auto pr-1">
                {requests.length === 0 ? (
                  <div className="text-center py-8 text-stone-400 text-xs border border-dashed border-stone-200 rounded-xl">
                    No pending booking requests
                  </div>
                ) : (
                  requests.map((req: any) => (
                    <DraggableAppointmentCard
                      key={req.id}
                      request={req}
                      onSelect={(r) => updateSelectedRequestUrl({ type: 'request', id: r.id, raw: r })}
                      onAssign={(r) => setAssigningRequest(r)}
                    />
                  ))
                )}
              </div>

              {/* Layer Toggles */}
              <div className="mt-4 pt-4 border-t border-stone-200">
                <p className="text-xs font-bold uppercase tracking-wider text-stone-400 mb-2">Calendar Layers</p>
                <div className="space-y-1.5 text-xs text-stone-600">
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input 
                      type="checkbox" 
                      checked={layerFilters.appointments} 
                      onChange={e => setLayerFilters({...layerFilters, appointments: e.target.checked})}
                      className="rounded border-stone-300 text-brand-primary focus:ring-focus-ring" 
                    />
                    <span>Confirmed Appointments</span>
                  </label>
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input 
                      type="checkbox" 
                      checked={layerFilters.shifts} 
                      onChange={e => setLayerFilters({...layerFilters, shifts: e.target.checked})}
                      className="rounded border-stone-300 text-brand-primary focus:ring-focus-ring" 
                    />
                    <span>Employee Staff Shifts</span>
                  </label>
                </div>
              </div>
            </div>
          )}

          {activeMode === 'requests' && (
            <div className="p-4 flex flex-col h-full overflow-y-auto">
              <h3 className="font-semibold text-sm text-stone-900 mb-3">Request Status Pipeline</h3>
              <div className="space-y-2">
                {[
                  { label: 'New Inquiries', count: requests.filter((r: any) => r.status === 'new').length, color: 'bg-status-info' },
                  { label: 'Staffing Review', count: requests.filter((r: any) => r.status === 'review' || r.status === 'staffing_review').length, color: 'bg-vowos-violet' },
                  { label: 'AI Ready', count: requests.filter((r: any) => r.status === 'ai_ready' || r.status === 'recommended').length, color: 'bg-status-warning' },
                  { label: 'Confirmation Pending', count: requests.filter((r: any) => r.status === 'tentative_hold' || r.status === 'confirmation_pending').length, color: 'bg-brand-primary' },
                  { label: 'Waitlist', count: requests.filter((r: any) => r.status === 'waitlist').length, color: 'bg-stone-400' },
                ].map(group => (
                  <div key={group.label} className="flex items-center justify-between p-2.5 rounded-lg border border-stone-100 hover:bg-stone-50 cursor-pointer">
                    <div className="flex items-center gap-2">
                      <div className={`h-2.5 w-2.5 rounded-full ${group.color}`} />
                      <span className="text-xs font-medium text-stone-700">{group.label}</span>
                    </div>
                    <Badge variant="secondary" className="text-xs">{group.count}</Badge>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeMode === 'workforce' && (
            <div className="p-4 flex flex-col h-full overflow-y-auto">
              <h3 className="font-semibold text-sm text-stone-900 mb-3">Team & Shifts</h3>
              <p className="text-xs text-stone-500 mb-4">Select a consultant to focus schedule or edit template shifts.</p>
              
              <div className="mb-4">
                <label className="text-xs font-semibold text-stone-700 block mb-1">Filter Staff</label>
                <Select value={selectedWorkforceStaff} onValueChange={setSelectedWorkforceStaff}>
                  <SelectTrigger className="w-full text-xs">
                    <SelectValue placeholder="All Consultants" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Consultants</SelectItem>
                    {staff.map((s: any) => (
                      <SelectItem key={s.id} value={s.id}>{s.first_name} {s.last_name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

                <Button 
                  onClick={() => setShiftModalData({ isOpen: true, data: { employee_id: selectedWorkforceStaff !== 'all' ? selectedWorkforceStaff : '' } })} 
                  variant="outline" 
                  className="text-xs mb-2 w-full"
                >
                  <Plus className="h-3.5 w-3.5 mr-1" /> Add Custom Shift
                </Button>
            </div>
          )}

          {activeMode === 'ai' && (
            <div className="p-4 flex flex-col h-full overflow-y-auto">
              <h3 className="font-semibold text-sm text-stone-900 mb-2 flex items-center gap-1.5">
                <Sparkles className="h-4 w-4 text-status-warning" /> Operational Insights
              </h3>
              <p className="text-xs text-stone-500 mb-4">AI detected 3 optimization opportunities for today's schedule.</p>
              
              <div className="space-y-3">
                <div className="p-3 rounded-xl border border-status-warning/20 bg-status-warning/10/50 text-xs">
                  <p className="font-semibold text-stone-900 mb-1">Fill Saturday Staffing Gap</p>
                  <p className="text-stone-600 mb-2">High demand for Bridal Consultations. Recommend adding 1 Senior Stylist shift.</p>
                  <Button size="xs" variant="default" className="bg-stone-900 text-white">Review</Button>
                </div>
              </div>
            </div>
          )}

          {activeMode === 'capacity' && (
            <div className="p-4 flex flex-col h-full overflow-y-auto">
              <h3 className="font-semibold text-sm text-stone-900 mb-2">Daily Capacity</h3>
              <p className="text-xs text-stone-500 mb-4">View peak utilization for today.</p>
              <div className="space-y-3 text-xs">
                <div className="flex justify-between items-center">
                  <span className="text-stone-600">Eligible Employees:</span>
                  <span className="font-bold text-stone-900">{capacityMetrics?.eligibleEmployees || 0}</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-stone-600">Scheduled Employees:</span>
                  <span className="font-bold text-stone-900">{capacityMetrics?.scheduledEmployees || 0}</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-stone-600">Staffing Gap (Hrs):</span>
                  <span className="font-bold text-stone-900">{capacityMetrics?.staffingGap?.toFixed(1) || '0.0'}</span>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Center Panel: Primary View Display */}
        <div className="flex-1 p-2 md:p-4 bg-[#faf8f5] overflow-y-auto overflow-x-hidden w-full">
          {activeMode === 'calendar' && (
            <Card className="h-full flex flex-col shadow-xs border-stone-200 overflow-hidden">
              <CardContent className="p-1 md:p-3 flex-1 min-h-[500px] overflow-hidden">
                <FullCalendar
                  plugins={[dayGridPlugin, timeGridPlugin, interactionPlugin]}
                  initialView="timeGridWeek"
                  headerToolbar={{
                    left: 'prev,next today',
                    center: 'title',
                    right: 'dayGridMonth,timeGridWeek,timeGridDay'
                  }}
                  events={calendarEvents}
                  editable={true}
                  selectable={true}
                  droppable={true}
                  eventReceive={handleEventReceive}
                  eventDrop={handleEventDrop}
                  select={handleDateSelect}
                  eventClick={handleEventClick}
                  height="100%"
                  slotMinTime="08:00:00"
                  slotMaxTime="20:00:00"
                />
              </CardContent>
            </Card>
          )}

          {activeMode === 'requests' && (
            <div className="space-y-4">
              <h2 className="text-lg font-bold text-stone-900">Booking Requests Queue</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {requests.map((req: any) => (
                  <Card key={req.id} className="border-stone-200 hover:border-stone-300 transition-all">
                    <CardHeader className="p-4 pb-2">
                      <div className="flex justify-between items-start">
                        <CardTitle className="text-sm font-bold text-stone-900">
                          {req.customer?.first_name} {req.customer?.last_name}
                        </CardTitle>
                        <Badge className="bg-brand-soft text-brand-primary-hover">{req.status || 'New'}</Badge>
                      </div>
                    </CardHeader>
                    <CardContent className="p-4 pt-0 text-xs text-stone-600 space-y-2">
                      <p><span className="font-semibold text-stone-800">Service:</span> {req.service?.name || <span className="text-red-500 font-medium">Missing Information</span>}</p>
                      <p><span className="font-semibold text-stone-800">Requested:</span> {req.preferred_date_1 || 'Flexible'}</p>
                      <div className="pt-2 flex gap-2">
                        <Button 
                          onClick={() => setAssigningRequest(req)} 
                          size="xs" 
                          className="bg-brand-primary hover:bg-brand-primary-hover text-white"
                        >
                          AI Recommend & Assign
                        </Button>
                        <Button 
                          onClick={() => updateSelectedRequestUrl({ type: 'request', id: req.id, raw: req })} 
                          variant="outline" 
                          size="xs"
                        >
                          View 360
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </div>
          )}

          {activeMode === 'workforce' && (
            <Card className="h-full flex flex-col shadow-xs border-stone-200 p-2 md:p-4 overflow-hidden">
              <div className="flex justify-between items-center mb-4">
                <div className="flex gap-4">
                  <div>
                    <h3 className="font-bold text-base text-stone-900">Workforce & Employee Schedule</h3>
                    <p className="text-xs text-stone-500">Manage shifts, breaks, and consultant coverage</p>
                  </div>
                  <div className="flex items-center gap-3 ml-8 border-l border-stone-200 pl-6">
                    <div className="flex flex-col">
                      <span className="text-[10px] uppercase font-bold text-stone-500">Staffing Gap</span>
                      <span className="text-sm font-semibold text-brand-primary flex items-center gap-1">
                        <AlertTriangle className="w-3 h-3" /> Saturday (+1 Stylist)
                      </span>
                    </div>
                    <div className="flex flex-col ml-4">
                      <span className="text-[10px] uppercase font-bold text-stone-500">Peak Capacity</span>
                      <span className="text-sm font-semibold text-status-warning">
                        85% on Thu
                      </span>
                    </div>
                  </div>
                </div>
              </div>
              <div className="flex-1 overflow-auto bg-white rounded-md shadow-inner border border-stone-100 p-2">
                <WorkforceMatrix 
                  staff={staff.filter((s: any) => selectedWorkforceStaff === 'all' || s.id === selectedWorkforceStaff)}
                  schedules={schedules}
                  timeOffRequests={timeOffRequests}
                  currentDate={new Date()}
                  onShiftClick={(shift) => setShiftModalData({ isOpen: true, data: shift })}
                  onEmptySlotClick={(employeeId, date) => {
                    const localDateStr = new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().split('T')[0];
                    setShiftModalData({ 
                      isOpen: true, 
                      data: { 
                        employee_id: employeeId, 
                        start: `${localDateStr}T09:00:00`,
                        end: `${localDateStr}T17:00:00`
                      } 
                    });
                  }}
                />
              </div>
            </Card>
          )}

          {activeMode === 'ai' && (
            <div className="space-y-4">
              <h2 className="text-lg font-bold text-stone-900 flex items-center gap-2">
                <Sparkles className="h-5 w-5 text-status-warning" /> AI Scheduling Optimization & Recommendations
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {requests.filter((r: any) => r.status === 'new' || r.status === 'ai_ready').length === 0 ? (
                  <div className="col-span-full p-8 text-center text-stone-500 border border-dashed border-stone-200 rounded-xl">
                    No pending booking requests requiring AI assignment.
                  </div>
                ) : (
                  requests
                    .filter((r: any) => r.status === 'new' || r.status === 'ai_ready')
                    .map((req: any) => (
                      <AIRequestCard key={req.id} request={req} onAssign={setAssigningRequest} />
                    ))
                )}
              </div>
            </div>
          )}

          {activeMode === 'capacity' && capacityMetrics && (
            <div className="space-y-4">
              <h2 className="text-lg font-bold text-stone-900">Capacity Metrics</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <Card className="p-4 border-stone-200 shadow-sm flex flex-col items-center justify-center">
                  <span className="text-sm text-stone-500">Bookable Hours</span>
                  <span className="text-2xl font-bold text-stone-900">{capacityMetrics.bookableHours.toFixed(1)}</span>
                </Card>
                <Card className="p-4 border-stone-200 shadow-sm flex flex-col items-center justify-center">
                  <span className="text-sm text-stone-500">Confirmed Hours</span>
                  <span className="text-2xl font-bold text-stone-900">{capacityMetrics.confirmedHours.toFixed(1)}</span>
                </Card>
                <Card className="p-4 border-stone-200 shadow-sm flex flex-col items-center justify-center">
                  <span className="text-sm text-stone-500">Held Hours</span>
                  <span className="text-2xl font-bold text-stone-900">{capacityMetrics.heldHours.toFixed(1)}</span>
                </Card>
                <Card className="p-4 border-stone-200 shadow-sm flex flex-col items-center justify-center">
                  <span className="text-sm text-stone-500">Staffing Gap</span>
                  <span className="text-2xl font-bold text-brand-primary">{capacityMetrics.staffingGap.toFixed(1)}</span>
                </Card>
              </div>
            </div>
          )}
        </div>

        {/* Right Panel: 360 Detail View */}
        {selectedRequest && (
          <div className="absolute inset-y-0 right-0 z-50 w-full md:w-96 md:border-l border-stone-200 bg-white p-0 md:p-0 overflow-y-auto shadow-2xl animate-in slide-in-from-right duration-200 flex flex-col h-full">
            {selectedRequest.type === 'appointment' ? (
              <Appointment360Panel appointmentId={selectedRequest.id} request={selectedRequest.raw} onClose={() => updateSelectedRequestUrl(null)} />
            ) : (
              <Request360Panel requestId={selectedRequest.id} request={selectedRequest.raw} onClose={() => updateSelectedRequestUrl(null)} />
            )}
          </div>
        )}
      </div>

      {/* Drawers and Modals */}
      {assigningRequest && (
        <AIAssignmentDrawer
          isOpen={!!assigningRequest}
          onClose={() => setAssigningRequest(null)}
          request={assigningRequest}
          onAssign={(rec) => {
            const startAtStr = assigningRequest.preferred_date_1 || new Date().toISOString().split('T')[0];
            const startDate = new Date(startAtStr);
            const validStartDate = isNaN(startDate.getTime()) ? new Date() : startDate;
            assignRequest({
              requestId: assigningRequest.id,
              employeeId: rec.employee_id,
              roomId: assigningRequest.preferred_room_id || '00000000-0000-0000-0000-000000000000',
              startAt: validStartDate.toISOString(),
              endAt: new Date(validStartDate.getTime() + 60 * 60 * 1000).toISOString()
            });
            setAssigningRequest(null);
          }}
        />
      )}

      {isNewAppointmentModalOpen && (
        <NewAppointmentModal
          isOpen={isNewAppointmentModalOpen}
          onClose={() => {
            setIsNewAppointmentModalOpen(false);
            setNewAppointmentData(null);
          }}
          initialData={newAppointmentData}
        />
      )}

      {isNewRequestModalOpen && (
        <NewRequestModal
          isOpen={isNewRequestModalOpen}
          onClose={() => setIsNewRequestModalOpen(false)}
        />
      )}

      {shiftModalData.isOpen && (
        <EmployeeShiftModal
          isOpen={shiftModalData.isOpen}
          onClose={() => setShiftModalData({ isOpen: false, data: null })}
          initialData={shiftModalData.data}
        />
      )}
    </div>
  );
}

function AIRequestCard({ request, onAssign }: { request: any; onAssign: (req: any) => void }) {
  return (
    <Card className="border-stone-200 hover:border-amber-300 transition-all bg-white shadow-xs">
      <CardHeader className="p-4 pb-2">
        <div className="flex justify-between items-start">
          <CardTitle className="text-sm font-bold text-stone-900">
            {request.customer?.name || `${request.customer?.first_name || ''} ${request.customer?.last_name || ''}`.trim() || 'Guest'}
          </CardTitle>
          <Badge className="bg-amber-100 text-amber-800 border-status-warning/20">
            {request.status || 'New'}
          </Badge>
        </div>
      </CardHeader>
      <CardContent className="p-4 pt-0 text-xs text-stone-600 space-y-2">
        <p><span className="font-semibold text-stone-800">Service:</span> {request.service?.name || 'Bridal Fitting'}</p>
        <p><span className="font-semibold text-stone-800">Preferred Date:</span> {request.preferred_date_1 || 'Flexible'}</p>
        <p><span className="font-semibold text-stone-800">Guests:</span> {request.number_of_guests || 1}</p>
        <div className="pt-3 flex gap-2">
          <Button 
            onClick={() => onAssign(request)} 
            size="xs" 
            className="bg-status-warning hover:bg-amber-600 text-white font-medium flex-1"
          >
            <Sparkles className="h-3 w-3 mr-1" /> AI Optimize
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

import React from 'react';
import { Badge } from '@vowos/design-system';
import { Button } from '@vowos/design-system';
import { Clock } from 'lucide-react';

interface DraggableAppointmentCardProps {
  request: any;
  onSelect: (req: any) => void;
  onAssign: (req: any) => void;
}

export function DraggableAppointmentCard({ request, onSelect, onAssign }: DraggableAppointmentCardProps) {
  return (
    <div
      data-id={request.id}
      data-title={`${request.customer?.first_name || 'Guest'} - ${request.service?.name || 'Fitting'}`}
      className="draggable-request-card p-3 rounded-xl border border-stone-200 bg-stone-50/50 hover:bg-stone-100/80 cursor-grab active:cursor-grabbing transition-all hover:border-rose-300 shadow-sm"
      onClick={() => onSelect(request)}
    >
      <div className="flex justify-between items-start mb-1">
        <span className="font-semibold text-xs text-stone-900">
          {request.customer?.first_name} {request.customer?.last_name}
        </span>
        <Badge variant="outline" className="text-[10px] bg-brand-soft text-brand-primary-hover border-border-subtle">
          Pending
        </Badge>
      </div>
